local P = LoreForeverPacks.Begin("LoreForever_Lang_ukUA")
P.entries["quest:1738"] = {n="Серцедерево",s="«Серцедерево» — завдання для чорнокнижників Альянсу, що веде їх глибоко в Ашенваль по гілку прадавнього дерева з трагічною історією. Самітник Такар Провидець посилає їх від імені Ґакіна Зв'язувача Темряви: цю романтичну реліквію чорнокнижники шукають як могутню принаду, щоб виманити й підкорити сукуба у Стормвінді.",h="«Серцедерево» — завдання для чорнокнижників Альянсу, що веде їх глибоко в Ашенваль по гілку прадавнього...",kw={"серцедерево","сукуб","анатера","латеріон","руїни ордил'аран","чорнокнижник"},ang={["class:Warlock"]="Здобути шматок Серцедерева — важлива віха для молодих чорнокнижників: це дає змогу викликати й поневолити сукуба, щоб маніпулювати розумом ворогів на полі бою.",["faction:Alliance"]="Подорож до Калімдору знайомить молодих заклиначів Альянсу зі спірною дикою місцевістю, ворожими заставами Орди й прадавніми руїнами нічних ельфів.",["race:Human"]="Приховані чорнокнижники Стормвінда часто покладаються на далеких розвідників на кшталт Такара Провидця, щоб розшукати реліквії давнього Калімдору, яких людські маги ніколи не описували."},sec={{t="Пам'ятник трагічному коханню",b="За словами Такара Провидця, Серцедерево виросло на тому місці, де десять тисяч років тому, під час Війни Прадавніх, разом полягли двоє закоханих нічних ельфів — Анатера й Латеріон. Живлене їхніми останніми подихами й вічною відданістю, дерево виросло чистим символом безсмертного кохання. Для смертних це священний трагічний пам'ятник, але для знавців темних мистецтв зосереджена сила почуттів — могутнє магічне паливо."},{t="Принада для сукуба",b="Сукуби живляться смертними пристрастями, жаданням і душевними муками. Такар розуміє: звичайні спокуси — ніщо порівняно з артефактом, що тисячоліттями вбирав чисту, безсмертну відданість. Шматок Серцедерева дає Ґакінові Зв'язувачу Темряви саме той каталізатор, який потрібен, щоб виманити одного з цих хитрих демонів крізь Нижній Світ до кола виклику в Кварталі магів Стормвінда."},{t="Руїни Ордил'Аран",b="Дерево стоїть серед Руїн Ордил'Аран на північному заході Ашенвалю. Проте, щоб здобути гілку, доведеться кинути виклик не лише диким звірам і ворожим землям, а й сектантам Темного Пасма, які захопили ельфійські руїни. Здобуту деревину треба переправити через моря назад до «Зарізаного Ягняти» у Стормвінді, щоб розпочати обряд підкорення."}},faq={{q="Навіщо чорнокнижникам Серцедерево, щоб закликати сукуба?",a="Сукубів вабить пристрасть, жага й сильні почуттєві зв'язки. Серцедерево проросло там, де десять тисяч років тому разом загинули двоє відданих одне одному закоханих нічних ельфів. Їхня незгасна пристрасть просякла деревину, і та стала ідеальною духовною принадою, щоб витягти сукуба крізь Нижній Світ.",al={"навіщо серцедерево","приманка для сукуба","навіщо дерево для сукуба"}},{q="Де росте Серцедерево?",a="Воно росте в Руїнах Орділ'Арана, у північно-західних лісах Ашенвалю, неподалік на південь від Темного Узбережжя. Ця місцевість потрапила до рук зловісних культистів.",al={"місце серцедерева","де серцедерево","де знайти серцедерево"}},{q="Ким були Анатера й Латеріон?",a="Це двоє нічних ельфів, що билися пліч-о-пліч під час Війни Прадавніх. Коли вони разом полягли на полі бою, саме там, де вони востаннє зітхнули, виросло Серцедерево — пам'ятник їхньому незламному коханню.",al={"анатера і латеріон","хто були закохані","закохані ашенвалю"}},{q="Хто такий Такар Провидець?",a="Такар — обдарований провидець-людина, союзник чорнокнижників Стормвінда. Він живе відлюдником у південних Пустках біля Табору Тауражо й своїм містичним зором пронизує тумани часу, відшукуючи забуті реліквії для Ґакіна Зв'язувача Темряви.",al={"хто такий такар","такар провидець","відлюдник пусток"}},{q="Як чорнокнижникові Альянсу безпечно дістатися з Пусток до Ашенвалю?",a="Мандрівникам з Альянсу, що йдуть з Пусток, варто оминати добре охоронювану заставу Орди на Валу Мор'шан. Чорнокнижники часто прослизають крізь неохоронюваний пролом у частоколі трохи на схід від головної брами, ідуть верхнім шляхом через Гори Кам'яного Кігтя або перепливають прикордонну річку.",al={"як дістатися ашенвалю","обійти моршан","уникнути валу орди"}},{q="Що відбувається, коли Ґакін отримує Серцедерево?",a="Ґакін готує з деревини ритуал у катакомбах під «Зарізаним Ягням» у Стормвінді. Він креслить коло закликання, щоб витягти сукуба з Викривленого Нижнього Світу, і доручає чорнокнижникові перемогти й підкорити демона.",al={"що далі після серцедерева","що ґакін робить із серцедеревом"}}},fp="10,301,25.441.0,20.398.0,23.359.1,53.288.0,36.177.0,32.249.0,22.254.0,73.271.0,49.228.0"}
P.entries["quest:1739"] = {n="Зв'язування",s="«Зв'язування» — завершальний обряд посвяти для чорнокнижників Альянсу, що прагнуть підкорити сукуба в Стормвінді. Із зачарованим осердям, здобутим із Серцедерева, адепт входить до кола прикликання під «Зарізаним Ягням», щоб витягти демона й здолати його в бою. Коли демона переможено, його волю сковують, прирікаючи його служити прикликачу.",h="«Зв'язування» — завершальний обряд посвяти для чорнокнижників Альянсу, що прагнуть підкорити сукуба в...",kw={"зв'язування","сукуб","чорнокнижник","осердя серцедерева","ґакін","зарізане ягня","склеп"},ang={["class:Warlock"]="Цей обряд — ключова віха для чорнокнижників із людей і гномів: вони переходять від безмозких бісів і блукачів порожнечі до влади над розумними, розважливими демонами.",["faction:Alliance"]="Саме існування цього ритуалу глибоко під Стормвіндом показує, як Альянс тихо терпить магію тіні в потаємних закутках, попри доктрини Церкви."},sec={{t="Спуск до Склепу",b="Під мостинами «Зарізаного Ягняти» в стормвіндському Кварталі магів лежить просторий склеп, присвячений забороненим мистецтвам. Подалі від пильних очей міської варти й Собору Світла таємна громада міських чорнокнижників проводить тут свої найнебезпечніші ритуали. Кола прикликання, викарбувані в камені, спрямовують первісні сили Нижнього Світу й дають честолюбним посвяченим змогу прорвати завісу між світами."},{t="Приборкання спокусниці",b="Прикликати сукубу — це значно більше, ніж бурмотіти заклинання. Чорнокнижник має принести фокус — у цьому разі підготовлене Осердя Серцедерева — і здійснити біля кола обряд прориву. Сукуби вміють розбещувати, спокушати й підкорювати навіть найстійкіший розум. Щоб утвердити цілковиту владу, прикликач мусить зітнути тварюку в двобої, відіславши її тілесну оболонку назад у Викривлений Нижній Світ й водночас закріпивши справжню прив'язь."},{t="Таємниці Ґакіна",b="Убивши прикликане створіння, переможний посвячений повертає виснажене осердя Ґакіну Зв'язувачу Темряви. Довівши і силу духу, і бойову вправність, підмайстер отримує основні знання, потрібні, щоб кликати сукуба через порожнечу, коли завгодно. Цей ритуал знаменує змужніння чорнокнижника Альянсу — відтепер він адепт, здатний давати раду мінливим, розумним демонам."}},faq={{q="Де відбувається закликання?",a="Ритуал відбувається в глибоких катакомбах під «Зарізаним Ягням» — непримітною корчмою в Кварталі магів Стормвінда. Чорнокнижники спускаються гвинтовими сходами повз пивний льох у підземне святилище з чародійськими колами закликання.",al={"де закликати","місце закликання сукуба","місце склепу"}},{q="Навіщо потрібне Осердя Серцедерева?",a="Осердя Серцедерева — це якір і каталізатор. Узяте з Серцедерева, що виросло в Ашенвалі там, де під час Війни Прадавніх полягли двоє закоханих нічних ельфів, воно дає саме той духовний резонанс, який потрібен, щоб розірвати невеликий розлам і заманити сукуба крізь Викривлений Нижній Світ.",al={"навіщо осердя серцедерева","що робить серцедерево"}},{q="Чому чорнокнижник мусить убити сукуба?",a="Демони Нижнього Світу коряться лише сильнішій волі й силі. Сукуб — майстер психологічних маніпуляцій і підкорення розуму; дати йому втілитися й не здолати одразу — значить накликати біду. Вбивши істоту в бою, чорнокнижник утверджує свою владу й силоміць закарбовує її на духові, перш ніж той знову збереться в Нижньому Світі.",al={"чому я б'юся з сукубом","чому вбити демона, щоб підкорити"}},{q="Хто такий Ґакін Зв'язувач Темряви?",a="Ґакін Зв'язувач Темряви — старший чорнокнижник, що живе під «Зарізаним Ягням» і наглядає за навчанням практиків Альянсу в Стормвінді. Він таємно добуває демонологічні артефакти й оцінює, чи вистачить учням волі, щоб підкорити демонічних істот.",al={"хто такий ґакін","ґакін зв'язувач темряви лор"}},{q="Що за Сурену згадує Ґакін?",a="Сурена Каледон — колишня учениця Ґакіна, яка втекла до Дефіас і чиє намисто ви раніше повернули. Ґакін іронічно міркує, чи не була вона перевдягненим сукубом, якого підіслали заморочити йому голову, — а тоді вирішує, що забагато їй честі.",al={"згадка про сурену","хто була сурена"}},{q="Чи можна сукубам ходити вулицями Стормвінда?",a="Відкрита демонологія суворо заборонена Церквою Святого Світла й владою королівства. Хоча ігрові механіки дозволяють підкореним демонам іти за чорнокнижниками містом, за лором ця практика ховається в тінях, підвалах і відлюдних святилищах на кшталт крипт «Зарізаного Ягняти».",al={"чи вартові бачать мого сукуба","чи законне закликання демонів у стормвінді"}}},fp="11,370,22.421.0,26.440.0,15.398.1,36.258.0,43.307.0,39.356.0,28.297.0,34.235.0,50.298.0"}
P.entries["quest:174"] = {n="Подивись на зорі",s="«Подивись на зорі» — початок задуму Вікторі Призм'Антраса зазирнути за моторошне склепіння крон Сутінколісся. Вікторі вірить, що темне прокляття лісу має наукове пояснення, а не лише чародійські забобони, і просить вас зібрати деталі для телескопа, який сконструював його приятель-гном.",h="«Подивись на зорі» — початок задуму Вікторі Призм'Антраса зазирнути за моторошне склепіння крон Сутінколісся.",kw={"подивись на зорі","вікторі призм'антрас","телескоп","коґ","даркшир","інженерія"},ang={["faction:Alliance"]="Поки патрулі Нічної Варти відбиваються від жахіть на дорогах довкола Даркшира, задум Вікторі уособлює маленьку, вперту надію міста збагнути, що отруїло їхній дім.",["profession:Engineering"]="Уся справа тримається на гномській конструкції та вправній роботі з металом, тож майстри можуть безпосередньо допомогти Вікторі в його астрономічних пошуках.",["race:Gnome"]="Вікторі покладається на винахідливість свого гномського товариша Коґа — ще одне свідчення того, що гномське ремесло несе лад і розум навіть у найтемніші закутки королівства."},sec={{t="Шукаючи в небесах",b="Серед мороку й страху, що огорнули Даркшир, Вікторі Призм'Антрас дивиться на лихо Сутінколісся вельми незвично. Замість того щоб приписувати скверну краю самій лише чорній магії, прокльонам чи неспокійним мерцям, Вікторі підозрює, що важливіші істини чекають високо над кронами. З кресленнями свого гномського товариша Коґа він береться будувати оптичний прилад, здатний зазирнути в небеса."},{t="Справа інженерії",b="Щоб почати збирати прилад для споглядання зірок, Вікторі потрібна міцна основа. За специфікаціями Коґа він просить мандрівників роздобути виточену бронзову трубу. Цей перший крок тримається на винахідливості смертних механіків, а не на чарах — і підкреслює вперте переконання Вікторі, що практичне ремесло й спостереження можуть пролити світло там, де містика безсила."}},faq={{q="Хто такий Вікторі Призм'Антрас?",a="Вікторі Призм'Антрас — учений мешканець Даркшира. На відміну від багатьох місцевих, яких скував страх чи поглинули забобони, він шукає раціонального пояснення скверні, що охоплює Сутінколісся, вивчаючи зорі.",al={"вікторі","хто дає подивись на зорі","вікторі призм'антрас"}},{q="Навіщо Вікторі будує телескоп?",a="Вікторі вірить, що дивне перетворення Сутінколісся має відчутне пояснення поза магією. Він сподівається, що, вдивляючись у небо крізь телескоп, побачить те, що проґавили місцеві легенди й чарівники.",al={"навіщо дивитися на зорі","навіщо бронзова трубка","завдання телескопа даркшир"}},{q="Хто такий Коґ?",a="Коґ — гном-інженер і друг Вікторі. Він накреслив механічні креслення, потрібні, щоб збудувати пристрій для спостереження за зорями.",al={"гном коґ","хто спроєктував телескоп"}},{q="Де взяти бронзову трубку?",a="Бронзову трубку зазвичай виготовляють інженери з певним досвідом. Мандрівники, які самі не інженери, часто дістають її обміном, на аукціоні або в мандрівних торговців інженерним крамом, у яких випадково знайдеться запас.",al={"як дістати бронзову трубку","місце бронзової трубки","де знайти бронзову трубку"}},{q="Чи це частина довшого ланцюжка завдань?",a="Так. Це перший крок у кількаетапній справі: зібрати й налаштувати зореглядний пристрій Вікторі в Даркширі.",al={"ланцюжок подивись на зорі","скільки завдань подивись на зорі"}},{q="Чому Вікторі шукає в Сутінколіссі природних пояснень?",a="Хоча ліс аж кишить нежиттю й темними чарами, Вікторі вірить, що перетворенням досі можуть керувати фундаментальні космічні чи природні закони, — тож він шукає відповідей у вивченні небесних світил.",al={"чому наукове пояснення в сутінколіссі","магія чи наука в сутінколіссі"}}},fp="17,288,19.432.0,23.382.0,28.217.0,43.230.0,11.130.0,36.237.0,35.128.0,60.201.0"}
P.entries["quest:1740"] = {n="Сфера Соран'рука",s="«Сфера Соран'рука» — обряд посвяти для чорнокнижників, який доручає самітник Доан Кархан на півдні Пусток. Молоді знавці темних мистецтв розшукують розбиті демонічні реліквії по всьому Азероту, щоб знову скласти посудину, яка ув'язнює суть зганьбленого демона.",h="«Сфера Соран'рука» — обряд посвяти для чорнокнижників, який доручає самітник Доан Кархан на півдні Пусток.",kw={"сфера соран'рука","доан кархан","молот присмерку","фортеця шадовфенг","чорнокнижник","палаючий легіон"},ang={["class:Warlock"]="Відновлення Соран'рука — велика віха для чорнокнижників: воно вчить, як Легіон карає своїх і як ув'язнені демонічні сутності можна перетворити на робочі знаряддя.",["faction:Horde"]="Доан Кархан живе на суворих просторах Пусток, тож південні рівнини — обов'язкова зупинка для мандрівних заклиначів, що шукають глибших темних знань."},sec={{t="Посудини для зганьблених",b="В ієрархії Палаючого Легіону за невдачу карають довіку. Коли менші демони втрачають прихильність своїх демонічних володарів, їхні духи зв'язують і ув'язнюють у кришталевих сферах. Ці артефакти потім роздають смертним заклиначам і чорнокнижникам Легіону як провідники чистої, підкореної сили. Навіть коли сферу розбито на уламки, ув'язнена в ній демонічна суть зберігає могутню магічну силу."},{t="Розкидана по континентах",b="Сфера Соран'рука не лишилася цілою. Розбита на частини, вона розійшлася по темних закутках обох великих континентів. Одну половину розтрощили ще дрібніше, і її уламки тримають сектанти Молота Присмерку у вогких глибинах Чорноглибинних Печер в Ашенвалі. Більша, ціла половина потрапила за море, до Срібнолісся, і нею заволодів один із чаклунів у примарних руїнах Фортеці Шадовфенг. Доан Кархан, що все життя вивчає сфери Легіону й уже склав Сферу Зарґейна, використовує здобуті уламки, щоб відновити Соран'рук як дієве знаряддя."}},faq={{q="Що таке Сфера Соран'рука?",a="Соран'рук — демон Палаючого Легіону, що впав у неласку. За демонічним звичаєм його дух ув'язнили в магічній сфері й віддали смертним практикам. Згодом сферу розбили, але навіть її уламки зберігають силу ув'язненого демона.",al={"лор соран'рука","що таке соран'рук","хто був соран'рук"}},{q="Хто такий Доан Кархан?",a="Доан Кархан — відлюдний чорнокнижник з південних Пусток, який присвятив життя вивченню й відновленню сфер Палаючого Легіону. Багато років він збирав власний артефакт, Сферу Зарґайна, а тепер допомагає молодим чорнокнижникам скласти докупи Сферу Соран'рука.",al={"хто такий доан кархан","історія доана кархана"}},{q="Чому сфера розкидана по двох різних підземеллях?",a="Первісну сферу розкололо на дві головні частини. Одна розлетілася на дрібніші уламки, якими користуються культисти Молота Присмерку в Чорноглибинних Печерах, а великий залишок привласнив чарівник у похмурих мурах Фортеці Шадовфенг.",al={"чому уламки в двох підземеллях","де уламки соран'рука"}},{q="Хто може взятися за це завдання?",a="Це завдання — лише для чорнокнижників, які прагнуть удосконалити своє ремесло й опанувати артефакти, викувані з ув'язнених демонічних духів.",al={"хто може виконати завдання","чи сфера соран'рука лише для чорнокнижників"}},{q="Що Доан Кархан робить зі знайденими уламками?",a="Доан Кархан вивчає уламки, щоб просунути свої дослідження реліквій Легіону, а тоді складає їх у цілком відновлене магічне знаряддя тієї форми, яку обере чорнокнижник.",al={"що буде після збору уламків","відновлення соран'рука"}},{q="Що таке Сфера Зарґайна?",a="Сфера Зарґайна — демонічна сфера-в'язниця, яку Доан Кархан багато років розшукував і відновлював для себе; у ній ув'язнено іншого зганьбленого демона Легіону.",al={"сфера зарґайна","зарґайн лор"}}},fp="20,247,24.444.0,27.600.0,29.264.0,19.280.0,52.248.0,28.137.0,54.184.0,27.170.0"}
P.entries["quest:175"] = {n="Подивись на зорі",s="За кресленнями майстра Коґа Вікторі Призм'Антрас шукає дзеркальну поверхню, щоб зібрати свій телескоп у Даркширі. Він посилає мандрівників на південь Сутінколісся розшукати Мері — місцеву жінку, яку пам'ятають тим, що вона завжди носила при собі дзеркальце.",h="За кресленнями майстра Коґа Вікторі Призм'Антрас шукає дзеркальну поверхню, щоб зібрати свій телескоп у...",kw={"подивись на зорі","вікторі призм'антрас","сліпа мері","дзеркальце","цвинтар тихих садів","телескоп"},ang={["faction:Alliance"]="Допомога Вікторі з телескопом — рідкісний проблиск допитливості й поступу в місті, яке інакше поглинули жах і тлін.",["profession:Engineering"]="Збирання телескопа вимагає точних оптичних специфікацій: гномські креслення допомагають відбити й збільшити ледь помітне світло зірок."},sec={{t="Дзеркальна поверхня",b="Роздобувши бронзову трубу для телескопа, Вікторі Призм'Антрас береться за наступну вимогу з креслень Коґа: надійне дзеркало, що спрямовуватиме й відбиватиме світло в приладі. Замість того щоб у злиденному Даркширі виготовляти тонке посріблене скло з нуля, Вікторі згадує Мері — місцеву мешканку, відому на всю округу тим, що вона завжди мала при собі дзеркальце."},{t="Пошуки на півдні",b="Колишня оселя Мері лежить глибоко на півдні Сутінколісся, трохи на північ від проклятого Цвинтаря Тихих Садів. Шукаючи її, шукачі пригод виходять за безпечні межі патрулів Нічної Варти й потрапляють у зотлілі гаї, що кишать ненажерливими вовками, дикими павуками й блукаючою нежиттю."},{t="Трагічна мешканка",b="Діставшись скромної хатини Мері на півдні, мандрівники бачать гірку правду падіння Сутінколісся. Жінка, яку пам'ятав Вікторі, вже не жива мешканка, а Сліпа Мері — блукаючий дух, що тримається біля старої оселі й сусіднього цвинтаря, прив'язаний до спогадів і речей колишнього життя."}},faq={{q="Що будує Вікторі Призм'Антрас?",a="Вікторі будує астрономічний телескоп у своїй хатині на пагорбі в Даркширі за кресленнями майстра-винахідника на ім'я Коґ.",al={"телескоп вікторі","проєкт подивись на зорі","що робить вікторі"}},{q="Навіщо Вікторі дзеркальце?",a="За оптичними кресленнями Коґа потрібне дзеркало, щоб відбивати й фокусувати світло в корпусі телескопа. Вікторі пам'ятає, що Мері завжди носила із собою дзеркальце, і сподівається дістати його для свого пристрою.",al={"навіщо дзеркальце","відбивна поверхня телескопа"}},{q="Де знайти Мері?",a="Мері живе в зруйнованому домі на південному сході Сутінколісся, трохи на північ від Цвинтаря Тихих Садів.",al={"де мері","місце мері в сутінколіссі","знайти сліпу мері"}},{q="Хто така Мері?",a="Мері жила на півдні Сутінколісся ще до того, як край поглинула проклята темрява, і в Даркширі її добре знали, бо вона завжди мала при собі дзеркальце. Що з нею сталося, вам доведеться дізнатися самим у її старому домі біля Цвинтаря Тихих Садів.",al={"хто така сліпа мері","передісторія сліпої мері"}},{q="Чи ще має Мері своє дзеркальце?",a="Коли до неї підійти, Мері визнає, що колись мала дзеркальце, але тепер його в неї немає — вона може лише підказати, куди воно поділося.",al={"чи є в мері дзеркальце","дзеркальце сліпої мері"}},{q="Які небезпеки чатують довкола хатини Мері?",a="Південно-східні ліси й сусідній Цвинтар Тихих Садів кишать ворожою нежиттю, дикими сутінковими кажанами, отруйними павуками-тенетниками й скаженими вовками, що полюють на мандрівників, які забрели на південь від Даркшира.",al={"небезпеки біля мері","загрози цвинтаря тихих садів"}}},fp="17,265,20.388.0,19.282.0,17.298.1,38.138.0,38.189.0,24.109.0,12.246.1,39.144.1,37.199.0"}
P.entries["quest:1758"] = {n="Фоліант Кабали",s="«Фоліант Кабали» посилає молодого чорнокнижника Альянсу з круч над Раджетом назад до Бібліотеки Айронфорджа. Щоб викликати й підкорити ненажерливого мисливця Скверни, заклинач мусить відшукати легендарний посібник, написаний першими чорнокнижниками, яким колись вдалося приборкати цього звіра.",h="«Фоліант Кабали» посилає молодого чорнокнижника Альянсу з круч над Раджетом назад до Бібліотеки Айронфорджа.",kw={"фоліант кабали","кром стаутарм","зала дослідників","айронфордж","мисливець скверни","страгад фарсан"},ang={["class:Warlock"]="Здобути Фоліант Кабали — вирішальний обряд посвяти для знавця темних мистецтв, що прагне влади над мисливцями Скверни: це крок від менших слуг до справжньої антимагічної демонології.",["faction:Alliance"]="Знавцям темних мистецтв з Альянсу доводиться повертатися з рубежів Калімдору до Зали Дослідників в Айронфорджі, щоб звернутися до дворфійської вченості по заборонені темні тексти.",["race:Dwarf"]="Кром Стаутарм доводить, що не кожен дворф, який сидить у Залі Дослідників, відкопує артефакти Титанів, — дехто потай збирає знання Палаючої Тіні."},sec={{t="Звір, що живиться магією",b="Щоб підкорити біса, блукача Порожнечі чи сукуба, потрібен обряд, але мисливець Скверни — небезпека зовсім іншого штибу. Мисливці Скверни не просто служать Палаючому Легіонові: вони самі полюють на магічну енергію й пожирають її. Звичайне коло виклику перед таким звіром розсиплеться, а сам він висмокче магію заклинача ще до того, як зв'язування встигне вчепитися. Страгад Фарсан, що наглядає за Раджетом зі своєї твердині в Пустках, надто мудрий, щоб дозволити недосвідченому братися за таке зв'язування без підготовки."},{t="Перше зв'язування",b="Щоб безпечно викликати й зв'язати мисливця Скверни, учневі потрібні магічні формули, зібрані у Фоліанті Кабали. Цей рукопис написала найперша смертна кабала чорнокнижників, яка без сторонньої допомоги зуміла зламати мисливця Скверни; він докладно описує особливу геомантію, матеріали й руни зв'язування, потрібні, щоб устояти перед голодом істоти. На біду Страгада і його кола, їхній примірник цієї шедевральної праці давно загубився."},{t="Збирач із Дун Мороґа",b="Не маючи змоги дати текст сам, Страгад посилає чорнокнижників Альянсу за Велике море, до Зали Дослідників в Айронфорджі. Там тиняється Кром Стаутарм — мандрівний дворф-чорнокнижник, що на схилі літ перебирає давні рукописи й бібліотечні записи. Якщо у Східних Королівствах і лишився бодай якийсь слід загубленого гримуара, він похований у ретельних каталогах Крома."}},faq={{q="Навіщо шукати Фоліант Кабали?",a="У Фоліанті Кабали — точні настанови, які записали перші смертні чорнокнижники, що самотужки закликали й підкорили мисливця Скверни. Звичайних ритуалів закликання замало, щоб упіймати демона, який активно живиться магічною енергією.",al={"що таке фоліант кабали","навіщо шукати книгу","мета фоліанта кабали"}},{q="Хто такий Кром Стаутарм?",a="Кром Стаутарм — мандрівний дворф-чорнокнижник, що оселився в бібліотеці Зали Дослідників в Айронфорджі. Він днями сидить серед запилених фоліантів і впорядковує давні історичні записи.",al={"де кром","хто такий кром стаутарм","кром айронфордж"}},{q="Що Страгад Фарсан робить у Пустках?",a="Страгад Фарсан — досвідчений чорнокнижник-людина, що тримає тихий нейтральний притулок на кручах над Раджетом. Подалі від пильних очей Кірін-Тору й влади Стормвінда він навчає могутньої демонології практиків і Альянсу, і Орди.",al={"місце страгада","чому ретчет","хто такий страгад"}},{q="Що буде після розмови з Кромом Стаутармом?",a="Кром Стаутарм пригадує згадки про фоліант у старих каталожних реєстрах. Він доручить вам розшукати його загублені частини й рідкісні реагенти, потрібні, щоб відновити гримуар.",al={"наступне завдання","після крома","наступний крок фоліанта кабали"}},{q="Чи можуть чорнокнижники Орди виконати це завдання?",a="Ця подорож до Айронфорджа — лише для чорнокнижників Альянсу. Чорнокнижники Орди отримують від Страгада схоже завдання, яке натомість посилає їх до обізнаних людей на землях Орди.",al={"версія для орди","чи лише для альянсу"}},{q="Якого демона відкриває цей ланцюжок завдань?",a="Увесь ланцюжок завдань про Фоліант Кабали завершується ритуальним боєм із закликаним мисливцем Скверни, після якого чорнокнижник знає, як закликати й підкорити такого демона назавжди.",al={"який демон","завдання мисливця скверни","якого улюбленця я отримаю"}}},fp="17,266,27.470.0,17.439.0,25.399.0,44.244.0,21.197.0,37.269.0,44.198.1,33.203.0,38.180.0"}
P.entries["quest:176"] = {n="РОЗШУКУЄТЬСЯ: «Гоґґер»",s="«РОЗШУКУЄТЬСЯ: „Гоґґер“» — оголошення Альянсу про винагороду, вивішене біля Ґолдшира, за голову велетенського лютого ватажка гнолів. Гоґґер никає південно-західними хащами Лісу Елвінн і жорстоко зривав усі спроби місцевої влади його здолати.",h="«РОЗШУКУЄТЬСЯ: „Гоґґер“» — оголошення Альянсу про винагороду, вивішене біля Ґолдшира, за голову велетенського...",kw={"гоґґер","гноли","розшукується","винагорода","ґолдшир","ліс елвінн","узлісся"},ang={["faction:Alliance"]="Перемога над Гоґґером вважається обрядом посвяти для молодих героїв Альянсу, що гартують характер, обороняючи серце земель Стормвінда.",["race:Human"]="Для людей Елвінну смерть Гоґґера означає безпеку садиб і торгових шляхів, які місяцями тероризували засідки гнолів."},sec={{t="Загроза в лісі",b="Поки Ліс Елвінн потерпає від розбою й навали кобольдів, племена гнолів на півдні стали зухвалішими й згуртованішими під грубим проводом Гоґґера. Гоґґер, що височіє над звичайними гнолами Річколапів, отаборився біля Узлісся, нападає на подорожніх і бере гору над патрулями місцевого ополчення, яких посилають його вгамувати."},{t="Відчай Ґолдшира",b="Армія Стормвінда розтягнута до межі й не може виділити регулярних сил, щоб пильнувати околиці столиці, тож Маршал Дуґан пішов на незвичний крок — призначив відкриту винагороду за звіра. Щоб здолати Гоґґера, треба заглибитися у вкрай ворожі землі гнолів, а його лютість зробила його найсмертоноснішою загрозою для шукачів пригод-початківців в Елвінні."}},faq={{q="Хто такий Гоґґер?",a="Гоґґер — незвично великий і лютий ватажок гнолів, що тероризує південний захід Лісу Елвінн. Він керує місцевими зграями довкола Узлісся й жорстоко відбив усі попередні спроби вартових Стормвінда схопити чи вбити його.",al={"хто такий гоґґер","гоґґер лор","що таке гоґґер"}},{q="Де знайти Гоґґера?",a="Гоґґер блукає між таборами гнолів на південному заході Лісу Елвінн, біля південних околиць, відомих як Узлісся, трохи на північ від річки, що відділяє ліс від Вестфолу й Сутінколісся.",al={"місце гоґґера","де гоґґер","знайти гоґґера"}},{q="Чому за голову Гоґґера призначено винагороду?",a="Армія Стормвінда призначила винагороду за Гоґґера, бо він здолав місцеві патрулі й смертельно небезпечний для мандрівників. Регулярних військ по всьому королівству бракує, тож Маршал Дуґан звернувся до незалежних шукачів пригод і мисливців за головами, щоб позбутися загрози.",al={"чому вбити гоґґера","плакат розшукується гоґґер","хто призначив винагороду за гоґґера"}},{q="Кому нести доказ загибелі Гоґґера?",a="Доказ загибелі звіра — його Велетенський Кіготь Ґнола — треба принести просто Маршалові Дуґану, який командує місцевим гарнізоном у Ґолдширі.",al={"здати гоґґера","кому здати гоґґера","кому потрібен кіготь гоґґера"}},{q="Чому Гоґґер небезпечніший за інших гнолів?",a="На відміну від звичайних гнолів, що никають Елвінном, Гоґґер має велетенську статуру й неабияку жорстокість. Він б'є значно сильніше й витримує набагато більше, тож часто розправляється з бійцями-одинаками, які його недооцінюють.",al={"чи гоґґер сильний","чому гоґґер елітний"}},{q="Чому вартові Стормвінда не можуть самі впоратися з Гоґґером?",a="Військові сили королівства геть виснажені: вони прикуті до оборони головних кордонів і до клопотів зі зникненням короля Варіана Рінна. Невеликому загонові Маршала Дуґана в Ґолдширі бракує людей, щоб безпечно вполювати таку живучу потвору.",al={"чому дуґан не вб'є гоґґера","де армія стормвінда"}}},fp="16,253,21.347.0,23.369.0,14.234.0,26.184.0,32.274.0,41.151.0,52.226.0,56.251.0"}
P.entries["quest:177"] = {n="Подивись на зорі",s="Це завдання посилає шукачів пригод повернути викинуте дзеркальце Сліпої Мері для астронома Вікторі Призм'Антраса. Тендітне дзеркальце потрапило до лап Божевільного Гуля, що блукає спустошеним Цвинтарем Тихих Садів на півдні Сутінколісся.",h="Це завдання посилає шукачів пригод повернути викинуте дзеркальце Сліпої Мері для астронома Вікторі...",kw={"подивись на зорі","сліпа мері","божевільний гуль","цвинтар тихих садів","вікторі призм'антрас","дзеркальце"},ang={["class:Priest"]="Жерці, що ступають оскверненою землею Цвинтаря Тихих Садів, бачать жахливе приниження мерців Сутінколісся: загиблих селян обернено на божевільних трупоїдів.",["faction:Alliance"]="Повертаючи загублені реліквії містян із рук ненажерливої нежиті, ви бачите гірку долю людей Сутінколісся, покинутих на небезпечних околицях Королівства Стормвінд.",["profession:Engineering"]="Інженери оцінять імпровізовану оптику Вікторі, що обертає звичайні поліровані ручні дзеркальця на відбивачі для астрономічного приладу."},sec={{t="Реліквія кращих днів",b="Ще до того як темрява, що підкрадалася, поглинула Велике Селище й обернула її на заплакану примару, Сліпа Мері дорожила вишуканим дзеркальцем. Після жахливої події, що забрала в неї зір і розум, вона кинула пам'ятку в землю за родинною стодолою. Саме таке дзеркальце потрібне Вікторі Призм'Антрасу для його величного телескопа в Даркширі, але його поцупили в темряву задовго до того, як астроном замріяв вивчати небеса."},{t="Цвинтарний нишпорка",b="Дзеркальце підібрав Божевільний Гуль, що нишпорив за зруйнованими хуторами. Гнаний на південь неспокійним голодом, жалюгідний мрець заніс дзеркальце на Цвинтар Тихих Садів і тепер блукає покинутою каплицею серед зарослих надгробків. Щоб повернути тендітне скло, доведеться пробитися крізь трупоїдних жахіть, що заполонили південні ліси, і вирвати втрачений скарб Мері з гнилих пазурів."}},faq={{q="Навіщо Вікторі дзеркальце Мері?",a="Вікторі Призм'Антрас збирає потужний телескоп у своїй хатині на пагорбі в Даркширі. Йому потрібні якісні лінзи й дзеркала, щоб уловлювати тьмяне світло зір, а цінна родинна реліквія Мері якраз відповідає оптичним вимогам його винаходу.",al={"дзеркальце вікторі","навіщо дзеркальце","для чого дзеркало"}},{q="Хто такий Божевільний Гуль, що вкрав дзеркало?",a="Божевільний Гуль — мерзенна нежить-збирач, яка тягала дрібнички з покинутих хуторів біля дому Мері. Він утік на південь і сховався в зруйнованій каплиці на Цвинтарі Тихих Садів.",al={"де божевільний гуль","хто має дзеркальце","гуль у каплиці"}},{q="Чому Сліпа Мері викинула своє дзеркальце?",a="Мері дорожила дзеркальцем аж до «того випадку», що відібрав у неї зір, затьмарив розум і прикував її як неспокійну тінь. Після того лиха вона вже не могла ні дивитися в нього, ні тримати його в руках і в розпачі викинула за свою стодолу.",al={"чому мері викинула","дзеркальце сліпої мері","випадок із дзеркальцем мері"}},{q="Де розташований Цвинтар Тихих Садів?",a="Цвинтар Тихих Садів лежить на південному сході Сутінколісся, на південь від головного шляху. Колись це був спокійний цвинтар Ґранд-Гемлету, а тепер там кишать агресивні гулі, скелети й звірі-падальники.",al={"місце цвинтаря тихих садів","де цвинтар"}},{q="Хто такий Коґ?",a="Коґ — гном-винахідник, що живе в Даркширі. Вікторі покладається на інженерний хист Коґа, щоб оцінити й допомогти зібрати тонкі механізми своєї машини для спостереження за зорями.",al={"хто такий коґ","коґ вікторі"}},{q="Що відбувається, коли повернути дзеркало Вікторі?",a="Отримавши дзеркало, Вікторі в захваті від того, як просувається робота. Він переходить до останнього етапу складання телескопа й просить ще одну, вирішальну деталь, щоб завершити систему лінз.",al={"наступне завдання подивись на зорі","що буде далі"}}},fp="17,249,22.467.0,23.420.0,43.261.0,46.205.0,48.237.0,39.221.0,11.184.0,51.228.1"}
P.entries["quest:178"] = {n="Пошуки для Теокрітуса",s="Пошуки для Теокрітуса починаються, коли шукач пригод у Редріджі знаходить у місцевих гнолів магічну дрібничку й чує в ній далекий голос. Це говорить Теокрітус, верховний маг Вежі Азори, якому вдалося перехопити магічну мережу гнолів; він терміново просить принести йому підвісок для вивчення.",h="Пошуки для Теокрітуса починаються, коли шукач пригод у Редріджі знаходить у місцевих гнолів магічну дрібничку...",kw={"пошуки для теокрітуса","теокрітус","вежа азори","амулет тіньової шкури","морґант","гноли Тіньової Шкури"},ang={["class:Mage"]="Праця Теокрітуса — винахідливе поєднання захисної й віщувальної магії: він зламує мережу іншого чаклуна, щоб посилати контрзакляття на величезні відстані.",["faction:Alliance"]="Співпраця між Вежею Азори в Елвінні й обложеними захисниками Лейкширу показує, як місцеві маги заступають там, де королівське військо Стормвінда лишило гарнізони без людей."},sec={{t="Голос у камені",b="Б'ючись із дикими гнолами Тіньової Шкури в Горах Редріджу, мандрівники іноді натрапляють на зачаровану дрібничку — Амулет Тіньової Шкури. Замість гортанного гарчання чи прокльонів, доторк до нього пробуджує спокійний безтілесний голос Теокрітуса, мага-людини, що живе у Вежі Азори за кордоном, у Лісі Елвінн. Це послання — плід довгих і копітких досліджень, спрямованих на те, щоб проникнути в темне чаклунство, яке керує зграями гнолів."},{t="Злам мережі Морґанта",b="Гноли Тіньової Шкури діють не лише з дикого інстинкту: вони підкоряються Морґантові, темному чаклунові-ренегату, що сховався в горах. Морґант виготовляє й роздає ці зачаровані підвіски, щоб передавати накази просто своїм звіроподібним поплічникам. Теокрітус кілька місяців розплутував частоту передавальних закль Морґанта. Коли шукач пригод приносить збляклий підвісок до Вежі Азори, чарівник переконується, що його віщування дісталося талісмана, — а отже, можна створити зворотне закляття й зовсім знешкодити гнолів."}},faq={{q="Хто такий Теокрітус?",a="Теокрітус — верховний маг Альянсу, що живе у Вежі Азори на сході Лісу Елвінн. Він пильно стежить за заворушеннями в краю й присвячує чимало магічних студій протидії темній магії, що просочується з Редріджу.",al={"лор теокрітуса","хто говорить через підвіску","маг вежі азори"}},{q="Чому гноли з клану Тіньової Шкури носили магічні підвіски?",a="Підвіски — магічні провідники, виготовлені чарівником-ренегатом Морґантом. Через них він передає подумки накази й здалеку керує пересуванням клану Тіньової Шкури.",al={"чому гноли мають підвіски","призначення підвіски тіньової шкури","магічна річ гнолів"}},{q="Чому голос, який надіслав Теокрітус, прийшов із запізненням?",a="Теокрітус наклав послання за кілька тижнів до того, як шукач пригод знайшов камінь, і спершу думав, що чари розвіялися марно. Прорватися крізь темні захисти Морґанта й налагодити зв'язок на таку відстань — ось що спричинило помітну магічну затримку.",al={"запізніле повідомлення","чому теокрітус забарився","затримка вицвілої підвіски"}},{q="Чого Теокрітус сподівається досягти за допомогою здобутої підвіски?",a="Розгадавши особливу магічну частоту, що пов'язує підвіску з Морґантом, Теокрітус сподівається обернути потік магії. Його найсміливіша мета — послати через цю мережу бойове закляття, яке миттю знерухомить кожного гнола, що носить таку підвіску.",al={"план теокрітуса","що зробить теокрітус","навіщо вивчати підвіску"}},{q="Куди веде цей ланцюжок завдань далі?",a="Доставка підвіски веде просто до завдання «Пильне око», де шукачі пригод вирушають стежити за твердинею Морґанта — Вежею Ілґалара, — і зрештою кладуть край впливові чарівника-ренегата на Редрідж.",al={"наступне завдання після теокрітуса","ланцюжок морганта","що буде далі"}}},fp="21,342,20.490.0,29.538.1,18.244.0,57.178.0,50.252.0,64.257.0,38.215.1"}
P.entries["quest:1782"] = {n="Обладунок Фурена",s="«Обладунок Фурена» — вершина завдання молодого воїна, який допомагає майстрові-ковалю Фуренові Лонґбірду в Стормвінді. Зібравши павучі ікла, роги химер і флакон флогістону, шукач пригод допомагає Лонґбірдові викувати міцну загартовану вогнем кольчугу. На подяку Лонґбірд вручає воїнові готову кольчугу й обіцяє поділитися своїми новими металургійними прийомами з усім Альянсом.",h="«Обладунок Фурена» — вершина завдання молодого воїна, який допомагає майстрові-ковалю Фуренові Лонґбірду в...",kw={"обладунок фурена","фурен лонґбірд","загартована вогнем кольчуга","воїн","ковальство","стормвінд"},ang={["class:Warrior"]="Для воїнів Альянсу, що тільки мужніють, здобути особливо загартовану броню Фурена — обряд посвяти й незамінний захист у перших походах на передовій.",["faction:Alliance"]="Добре спорядження вкрай важливе, щоб війська Альянсу вистояли проти невпинних загроз — Дефіас, гнолів і ворожих сил стихій.",["profession:Blacksmithing"]="Вдалий експеримент Фурена підкреслює традицію співпраці ковалів Альянсу, які діляться особливими металургійними відкриттями, щоб підносити рівень ремесла в Стормвінді й Айронфорджі."},sec={{t="Прорив майстра",b="Фурен Лонґбірд, шанований дворф-бронник, що працює в Стормвінді, присвятив своє ремесло тому, щоб розсунути межі захисної металургії Альянсу. Доручивши відважному шукачеві пригод розшукати рідкісні ікла, роги й флогістон, Лонґбірд прагнув випробувати новітні прийоми гартування кольчуги проти пекучого жару й нищівних ударів. Робота вдалася на славу й утвердила Лонґбірда як одного з провідних бронників Альянсу."},{t="Ремесло, яким діляться",b="Вручаючи щойно викувану загартовану вогнем кольчугу шукачеві пригод, який зібрав матеріали, Фурен щиро дякує за співпрацю. Його експерименти дали більше, ніж одну міцну кольчугу: вони поглибили його розуміння захисного ковальства. У дусі спільноти майстрів Айронфорджа й Стормвінда Лонґбірд вирішує розіслати свої записи й відкриття іншим ковалям Альянсу, щоб його прорив зміцнив бійців передової по всьому Альянсу."}},faq={{q="Хто такий Фурен Лонґбірд?",a="Фурен Лонґбірд — дворфійський майстер-бронник, що працює в Стормвінді. Він багато співпрацює з бойовими орденами Альянсу, особливо з воїнами, яким потрібен особливий, добротний обладунок.",al={"хто такий фурен","фурен лонґбірд","коваль стормвінда фурен"}},{q="Який обладунок створив Фурен?",a="Після численних дослідів з рідкісними іклами, рогами й флогістоном Фурен викував Загартований Вогнем Обладунок — кольчужний нагрудник. Він задумав його так, щоб той витримував люті атаки й нестерпний жар на полі бою.",al={"який обладунок робить фурен","загартована вогнем кольчуга","нагорода фурена"}},{q="Кому Фурен Лонґбірд надсилає свої ковальські відкриття?",a="Фурен обіцяє розіслати свої технічні висновки й записи іншим ковалям по всьому Альянсу, щоб нові, щойно випробувані способи гартування прислужилися зброярням і кузням усього королівства.",al={"кому надсилають записи фурена","хто отримує проєкти фурена","ковалі альянсу"}},{q="Чому воїна попросили зібрати реагенти для Фурена?",a="Фуренові потрібні були рідкісні й нестійкі складники, щоб випробувати ще не перевірені ковальські прийоми. Сам він не міг покинути кузню й полювати на павуків Багнокраю та химер у Горах Кам'яного Кігтя, тож покладався на завзятого воїна.",al={"чому збирати реагенти для фурена","матеріали завдання кольчуги"}},{q="Де кують і вручають цей обладунок?",a="Обмін відбувається просто біля кузні Фурена Лонґбірда в Стормвінді, де той завершує останнє кування й охолодження кольчуги.",al={"де фурен лонґбірд","місце здавання","місце фурена"}},{q="Чи прислужиться ця робота іншим бійцям Альянсу?",a="Так. Фурен зауважує, що здобутими під час роботи з цими матеріалами знаннями поділиться з іншими бронниками Альянсу, і сподівається, що це спонукає інших ковалів виготовляти добірне спорядження для вояків Альянсу.",al={"користь для альянсу","прорив фурена"}}},fp="13,426,23.485.0,17.494.0,23.201.0,36.214.0,57.204.0,55.237.0,41.155.0,47.223.0"}
P.entries["quest:179"] = {n="Дворфійські постачальники",s="Дворфійські постачальники — вступне завдання на виживання в Долині Холодного Хребта, яке пропонує Стен Стаутарм. За винищення місцевих вовків і збирання їхнього жилавого м'яса на зимові харчі новобранців винагороджують міцними рукавицями, що бережуть від обмороження в лютому холоді Дун Мороґу.",h="Дворфійські постачальники — вступне завдання на виживання в Долині Холодного Хребта, яке пропонує Стен...",kw={"дворфійські постачальники","стен стаутарм","вовки","рукавиці","долина холодного хребта","анвілмар","виживання"},ang={["race:Dwarf"]="Для молодих дворфів Бронзбірдів, що виходять у Долину Холодного Хребта, це завдання — ранній урок прикордонної самодостатності: заробіть своє утримання, забезпечте табір і шануйте гірський холод.",["race:Gnome"]="Знайшовши притулок у дворфійських родичів у Дун Мороґу, гноми швидко переконуються, що для виживання в Анвілмарі практичний гірський одяг потрібен не менше за гострий розум."},sec={{t="Чесна угода в Холодному Хребті",b="Високогірний перевал Долини Холодного Хребта люто холодний, і непідготовлені мандрівники швидко переконуються, що звичайне спорядження стихії не рівня. Стоячи біля Анвілмара, Стен Стаутарм пропонує новобранцям просту прикордонну угоду: вирушити в засніжені замети, вполювати вовків, що там никають, і принести шматки жилавого м'яса, щоб поповнити припаси застави. Натомість він дає справжні теплі рукавиці, щоб молоді шукачі пригод зберегли всі десять пальців."},{t="Жити з того, що дає долина",b="Хоч вовки — постійна небезпека для дворфійських розвідників і гномів-новачків, що навчаються в долині, вони також життєво важливий ресурс. Їхнє м'ясо годує гарнізон, що стоїть в Анвілмарі, а винищення їхнього поголів'я робить стежки між місцевими таборами дещо безпечнішими. Угода Стаутарма має подвійну мету: перевірити вміння новобранця давати раду місцевій звірині й заразом запасти харчі на люті ночі попереду."}},faq={{q="Хто такий Стен Стаутарм?",a="Стен Стаутарм — дворф, що стоїть біля Анвілмара в Долині Холодного Хребта. Він приглядає за новоприбулими новобранцями й дбає, щоб вони мали належне спорядження й пережили морози Дун Мороґу, — дає практичні речі в обмін на здобич з полювання.",al={"стен стаутарм","хто дає дворфійських постачальників","постачальник анвілмара"}},{q="Навіщо Стенові вовче м'ясо?",a="Застава в Анвілмарі поповнює запаси завдяки місцевому полюванню. Вовче м'ясо — ситна й надійна їжа для вояків і наставників, що живуть у відлюдній засніженій долині.",al={"навіщо вовче м'ясо","жорстке вовче м'ясо","для чого м'ясо"}},{q="Де шукати вовків для цього завдання?",a="Вовки блукають засніженими галявинами по всій Долині Холодного Хребта, особливо одразу за головним подвір'ям Анвілмара й уздовж стежок до віддалених таборів.",al={"де вовки","місця вовків холодного хребта","де взяти м'ясо"}},{q="Яку нагороду дає Стен?",a="Стен винагороджує новобранців надійною парою теплих рукавиць, які рятують від обмороження й захищають руки бійця від пронизливих вітрів Дун Мороґу.",al={"нагорода дворфійських постачальників","які рукавиці дадуть","нагорода за завдання"}},{q="Чи вважають дворфи вовче м'ясо доброю їжею?",a="Жорстке вовче м'ясо грубе й жилаве, але в суворому гірському кліматі Дун Мороґу дворфи цінують ситну їжу більше за вишукані страви. Тушковане чи засмажене над вогнищем, воно цілком годиться для гарнізону.",al={"чи смачне вовче м'ясо","дворфи вовче м'ясо","їсти вовка"}},{q="Чи можуть це завдання виконати й гноми?",a="Так. Гноми, що навчаються пліч-о-пліч із союзниками-дворфами в Долині Холодного Хребта, терплять ті самі пронизливі вітри й так само нагально потребують теплого одягу.",al={"гноми дворфійські постачальники","чи гноми можуть отримати рукавиці","гноми і холод"}}},fp="18,283,25.471.0,21.438.0,21.262.0,29.195.0,43.175.0,30.166.0,48.221.0,29.145.0"}
P.entries["quest:1791"] = {n="Спостерігач Вітрів",s="«Спостерігач Вітрів» — настанова, що скеровує досвідчених воїнів на пошуки відлюдного троля-шамана далеко на півночі. Довівши свій гарт у випробуванні Бійкою й опанувавши стійку берсерка, воїни вирушають шукати зброю, гідну їхньої зростаючої люті.",h="«Спостерігач Вітрів» — настанова, що скеровує досвідчених воїнів на пошуки відлюдного троля-шамана далеко на...",kw={"спостерігач вітрів","бат'ра","стійка берсерка","кланнок маклауд","гори альтерак","воїн"},ang={["class:Warrior"]="Цей обряд посвяти поєднує опанування стійки берсерка на Острові Бійки з пошуками легендарної зброї, викуваної силою стихій.",["race:Troll"]="Пошуки Бат'ри показують, що навіть серед зруйнованих руїн Лордерону тролі-шамани й зброярі володіють містичними знаннями, які шанують воїни будь-якого роду."},sec={{t="Зброя для берсерка",b="Пройшовши жорстоке випробування на витривалість у Бійці на Острові Бійки, воїни опановують у Кланнока Маклауда люту науку стійки берсерка. Та сира бойова наука вимагає зброї не меншої слави. Розуміючи це, Кланнок відсилає багатообіцяльних бійців геть від узбережжя Пусток — через континенти, на пошуки самотнього майстра, здатного викувати надзвичайну зброю."},{t="Самітник на березі річки",b="Завдання веде мандрівників углиб спірних долин північного Лордерону — до оповитого туманом прикордоння між Горами Альтерак і сплюндрованими Західними Чумними Землями. Біля річки, що тече на північ повз Таррен Мілл, серед кам'яних руїн самотньо живе троль-самітник Бат'ра Спостерігач Вітрів. Бат'ра — не звичайний самітник: він і обдарований зброяр, і могутній шаман стихій, що чекає на воїнів, досить рішучих, аби викувати щось справді величне."}},faq={{q="Хто посилає шукати Спостерігача Вітрів?",a="Кланнок Маклауд, майстер бойових випробувань з Острова Бійки біля східного узбережжя Пусток, відправляє вас у цю подорож, коли ви здолаєте Бійку й опануєте стійку берсерка.",al={"хто дає завдання","хто дає спостерігача вітрів","завдання кланнока маклауда"}},{q="Хто такий Бат'ра Спостерігач Вітрів?",a="Бат'ра — загадковий троль-відлюдник, майстер-зброяр і могутній шаман, що живе на самоті в дикій глушині між Горами Альтерак і Західними Чумними Землями.",al={"хто такий бат'ра","бат'ра спостерігач вітрів лор","особа бат'ри"}},{q="Де саме перебуває Бат'ра?",a="Бат'ра отаборився на східному березі річки, що тече на північ повз Таррен Мілл, біля давніх руїн на межі Альтераку й Західних Чумних Земель.",al={"де бат'ра","місце бат'ри","знайти бат'ру"}},{q="Чому Кланнок посилає воїнів до Бат'ри?",a="Кланнок розуміє, що воїнові, який опанував люту стійку берсерка, потрібна виняткова зброя, щоб спрямувати цю лють, а Бат'ра має рідкісні знання стихій і ковальства, щоб таку викувати.",al={"чому йти до бат'ри","мета цього завдання","навіщо спостерігач вітрів"}},{q="Що далі після розмови з Бат'рою?",a="Розмова з Бат'рою одразу веде до завдання вистояти проти буремного елементаля Циклоніана й зібрати рідкісні матеріали для потужної бойової зброї.",al={"що після спостерігача вітрів","наступне завдання циклоніана","продовження спостерігача вітрів"}},{q="Чи безпечна ця подорож для мандрівника з Пусток?",a="Вона доволі небезпечна. Шлях веде через передгір'я Гілсбреда до спірних північних земель повз схованки Синдикату, лютих гірських хижаків і смертоносну чуму Західних Чумних Земель.",al={"чи небезпечно","небезпека річки таррен мілл"}}},fp="15,283,24.410.0,27.517.0,38.202.0,32.171.0,34.175.0,43.210.0,40.163.1,60.223.0"}
P.entries["quest:1793"] = {n="Фоліант Звитяги",s="Фоліант Звитяги — одне з перших справжніх випробувань для паладинів Альянсу, що набираються сили. Наставники-паладини Стормвінда й Айронфорджа вимагають від посвячених довести, що їхня мужність і відданість захисту невинних не поступаються бойовій вправності.",h="Фоліант Звитяги — одне з перших справжніх випробувань для паладинів Альянсу, що набираються сили.",kw={"фоліант звитяги","паладин","святе світло","собор світла","зала таїнств","відвага"},ang={["class:Paladin"]="Цей обряд знаменує ваш перехід від простого послушника до надійного захисника Святого Світла: він вимагає ставити самовіддане служіння вище за власну безпеку.",["faction:Alliance"]="Випробування з Фоліанту готують поборників, що боронитимуть поселення Альянсу від нових загроз — від місцевих розбійників до жахливих загарбників.",["race:Dwarf"]="Паладини Айронфорджа на чолі з наставниками на кшталт Тізи Баттлфордж бачать у Фоліанті Звитяги доказ того, що дворфійську витривалість зміцнює свята мета.",["race:Human"]="Це випробування проводять під пильним оком Дуторіана Ралла в Соборі Світла; воно відбиває незмінну відданість Стормвінда засадам, на яких постала Срібна Длань."},sec={{t="Мірило паладина",b="Щоб нести Святе Світло в бій, мало важкої броні й бойової дисципліни. Коли юні паладини сягають нових висот у навчанні, наставники в Соборі Світла й Залі Таїнств вимагають доказів їхньої внутрішньої стійкості. Уроки Фоліанту Звитяги перевіряють, чи готовий посвячений стати проти найстрашнішого зла — від драконів до демонів, — не завагавшись і не покинувши тих, хто не може захистити себе сам."},{t="Чесноти ордену",b="Відвага перед смертельною загрозою для святого воїна така ж необхідна, як зброя і щит. Проходячи випробування з Фоліанту Звитяги, паладини засвоюють: сила без непохитної обітниці захищати безпорадних — порожня. Справжня небезпека гартує їх, тож коли на Альянс упаде темрява, його захисники встоять, а не зламаються."}},faq={{q="Навіщо потрібен Фоліант Звитяги?",a="Фоліант Звитяги — обряд посвяти для молодих паладинів Альянсу. Його задумали наставники Святого Світла, щоб переконатися: перш ніж посвячений просунеться в ордені, він має справжню мужність і безкорисливе прагнення захищати беззахисних.",al={"що таке фоліант звитяги","навіщо фоліант звитяги","чому робити фоліант звитяги"}},{q="Хто посилає паладинів на це випробування?",a="Зазвичай посвячених кличуть на це випробування старші паладини в столицях Альянсу, як-от Дуторіан Ралл у Соборі Світла в Стормвінді чи Тіза Баттлфордж у Залі Таїнств в Айронфорджі.",al={"хто дає фоліант звитяги","дає фоліант звитяги","хто починає фоліант звитяги"}},{q="Куди веде це випробування?",a="Перший поклик відкриває низку окремих завдань, що перевіряють рішучість паладина й ведуть його в поле назустріч справжній небезпеці, щоб захистити королівство й невинних.",al={"що після фоліанта звитяги","продовження фоліанта звитяги","ланцюжок фоліанта звитяги"}},{q="Чому для паладинів так важить хоробрість?",a="Святе Світло відгукується на віру й волю. Перед нездоланним жахом, як-от демони чи дракони, страх може зламати дух воїна; мужність же дає паладинові змогу й у найскрутніші часи лишатися непохитним щитом для інших.",al={"чому звитяга","чому хоробрість важлива паладинам"}},{q="Чи проходять паладини-дворфи й паладини-люди однакове випробування?",a="Паладини-дворфи навчаються в Айронфорджі, а люди — в Соборі Світла в Стормвінді, проте обидві традиції шанують ті самі головні чесноти: мужність, обов'язок і захист беззахисних під покровом Світла.",al={"чи різне для дворфів","фоліант звитяги айронфордж","фоліант звитяги стормвінд"}},{q="Яких головних уроків навчає випробування?",a="Випробування зосереджене на трьох основних обов'язках: незламна хоробрість попри будь-які шанси, діяльний захист слабких від лиха й віра, що не хитається перед жахом.",al={"уроки фоліанта звитяги","чого вчить фоліант"}}},fp="17,264,24.434.0,20.366.0,41.255.0,35.201.0,27.195.0,50.234.0,52.205.0,44.197.0"}
P.entries["quest:1795"] = {n="Зв'язування",s="«Зв'язування» — завершальний обряд для чорнокнижників, які прагнуть командувати мисливцем Скверни. Під наглядом загадкового заклинача Страгада Фарсана на кручах над Раджетом обряд за допомогою відновленого Фоліанта Кабали вириває лютого демонічного хижака з Нижнього Світу й змушує його скоритися в двобої.",h="«Зв'язування» — завершальний обряд для чорнокнижників, які прагнуть командувати мисливцем Скверни.",kw={"зв'язування","мисливець скверни","страгад фарсан","фоліант кабали","раджет","чорнокнижник"},ang={["class:Warlock"]="Підкорення мисливця Скверни — важлива віха для кожного чорнокнижника: він отримує особливого антимагічного хижака, здатного пожирати чари й знешкоджувати ворожих заклиначів.",["faction:Alliance"]="Чорнокнижників Альянсу посилають із безпечного Стормвінда за море, до суворого нейтрального притулку Раджета, щоб під пильним оком Страгада завершити небезпечний обряд виклику.",["faction:Horde"]="Знавці темних мистецтв з Орди вирушають у серце Пусток, щоб довести свою владу над Нижнім Світом, і стають перед Страгадом на нейтральній землі, щоб підкорити гончака."},sec={{t="Коло кабали",b="На кручах над гоблінським портом Раджет Страгад Фарсан проводить одні з найнебезпечніших демонологічних випробувань у Калімдорі. Коли чорнокнижник збере розрізнені уламки й реагенти, потрібні, щоб скласти прадавній Фоліант Кабали, Страгад готує місце для зв'язування. Він накреслює внутрішній знак стримування, а його вірні учні через зачаровані жезли замикають зовнішнє коло, щоб жахіття, які з'являться, лишилися відрізаними від поселення внизу."},{t="Підкорення мисливця",b="Читаючи заклинання з Фоліанта Кабали, новачок прокладає міст у Викривлений Нижній Світ. Мисливці Скверни — ненажерливі демонічні гончаки, що від природи прагнуть магічної сили й бенкетують магічною енергією. Викликаного звіра не вмовиш солодкими словами й не зачаруєш лагідно: його треба силою здолати й зламати в бою, і лише тоді він визнає чорнокнижника своїм законним господарем. Вистоявши в сутичці, заклинач доводить, що готовий спрямовувати цього гончака проти ворожих магів."}},faq={{q="Яка мета цього ритуалу?",a="Ритуал дає змогу чорнокнижникові закликати мисливця Скверни й підкорити його своїй волі. Читаючи з відновленого Фоліанта Кабали в колі закликання Страгада Фарсана, чорнокнижник витягає демонічного хижака з Нижнього Світу й перемагає його в бою, здобуваючи його вічну службу.",al={"навіщо це завдання","мета завдання мисливця скверни","мета зв'язування"}},{q="Хто такий Страгад Фарсан?",a="Страгад Фарсан — досвідчений чорнокнижник-людина, що працює у вежі над Раджетом у Пустках. Через його глибокі знання темних мистецтв закликання наставники і з Альянсу, і з Орди потай посилають до нього своїх найперспективніших учнів опановувати складні обряди підкорення.",al={"хто такий страгад","страгад фарсан лор","хто дає завдання страгад"}},{q="Чому чорнокнижник мусить убити демона, а не просто поневолити його?",a="Мисливець Скверни — агресивний хижак, що пожирає магію, і визнає лише цілковиту владу. Ритуал вимагає здолати демона в рукопашному й магічному бою, щоб зламати його лють і закарбувати свою владу на його духові, — тоді він коритиметься й надалі, щойно його закличуть.",al={"чому вбити мисливця скверни","чи можна поневолити мисливця скверни","бій з мисливцем скверни"}},{q="Чи можуть чорнокнижники і з Орди, і з Альянсу провести тут цей ритуал?",a="Так. Попередні завдання з відновлення Фоліанта Кабали різняться залежно від фракції, але зрештою і чорнокнижників Альянсу, і чорнокнижників Орди скеровують до Страгада Фарсана над Раджетом для останнього закликання.",al={"чи лише для орди","чи лише для альянсу","хто отримує це завдання"}},{q="Що буде, якщо мисливець Скверни переможе закликача?",a="Якщо закликач полягне, демона буде вигнано назад у Нижній Світ, а ритуал зазнає невдачі. Проте Страгад дозволяє чорнокнижникам, які пережили поразку, отримати новий примірник Фоліанта Кабали й повторити закликання, коли вони як слід підготуються.",al={"що якщо я помру","провал зв'язування","чи можна повторити ритуал"}},{q="Чим мисливці Скверни відрізняються від інших демонів?",a="Мисливці Скверни — демонічні пси, що полюють, відчуваючи магічні випромінювання. Замість покладатися лише на грубу силу чи закляття тіні, вони вміють винюхувати чаклунство, пожирати чинні чари й зривати закляття ворожих чарівників, тож вони — безцінні супутники проти суперників-магів.",al={"що робить мисливець скверни","мисливець скверни лор","чому мисливці скверни"}}},fp="11,301,18.506.0,22.507.0,35.285.0,22.302.0,66.283.0,62.227.0,51.257.0,54.293.0"}
P.entries["quest:1796"] = {n="Складники Зачарованої Золотої Кривавої Роби",s="Менара Войдрендер доручає молодим чорнокнижникам у Пустках роздобути Робу Аркани — основу для могутнього магічного вбрання. Це перший крок до створення Зачарованої Золотої Кривавої Роби: так готують надійну посудину, здатну витримати темні чари.",h="Менара Войдрендер доручає молодим чорнокнижникам у Пустках роздобути Робу Аркани — основу для могутнього...",kw={"зачарована золота кривава роба","роба аркани","менара войдрендер","чорнокнижник","кравецтво","пустки"},ang={["class:Warlock"]="Виготовлення Зачарованої Золотої Кривавої Роби — важливий обряд посвяти для чорнокнижників: воно вчить, що могутні артефакти творять на міцній, ретельно підготовленій основі.",["profession:Tailoring"]="Це завдання вимагає рідкісного вміння вправного кравця, що опанував викрійку Роби Аркани і працює з павучим шовком та сувій за сувоєм тонкого шовку.",["race:Orc"]="Для оркських чорнокнижників, що працюють у тіні демонічного минулого свого народу, збирання матеріалів для витонченої роби — тихіше опанування енергії Скверни, подалі від цікавих очей.",["race:Undead"]="Знавці темних мистецтв з Відступників часто мандрують аж до вибілених сонцем Пусток, щоб перейняти прийоми Менари й зміцнити свої крихкі смертні оболонки проти власного мінливого мистецтва."},sec={{t="Посудина магії",b="Перш ніж прив'язати темну магію до тканини, саме вбрання має бути гідним такої сили. Менара Войдрендер велить чорнокнижникам, що прагнуть більшої могутності, роздобути Робу Аркани. Як пояснює Менара, міць будь-якої магічної реліквії залежить від майстерності, рідкісності й праці, вкладених у її основу. Звичайне лахміття розлізлося б під тиском глибоких чарів, тож без тонко зшитого, сприйнятливого вбрання не обійтися."},{t="Ремесло й честолюбство",b="Менара особливо захоплюється тими, хто здатен зшити вбрання власноруч, але безжальне честолюбство цінує вище за гордість. Чи чорнокнижник сам шиє шовк, чи замовляє роботу в здібного майстра, чи торгується на ринку, — наслідок однаковий: готова роба, яку можна перетворити на особливе знаряддя влади над Скверною."}},faq={{q="Чому Менарі Войдрендер потрібна саме Роба Аркани?",a="Чари найвищого рівня потребують одягу, витканого з винятковою майстерністю й з рідкісних матеріалів. Менара бере Робу Аркани як чисту, сприйнятливу основу, здатну втримати нестійкі магічні сили, які невдовзі в неї вплетуть.",al={"чому роба аркани","чому саме ця роба","навіщо роба"}},{q="Де знайти Менару Войдрендер?",a="Менара Войдрендер живе в гоблінському порту Раджет у Пустках, де навчає чорнокнижників, які прагнуть удосконалити своє ремесло й виготовити особливе спорядження.",al={"місце менари войдрендер","де менара","де менара войдрендер"}},{q="Чи треба самому шити Робу Аркани?",a="Ні. Менара шанує відданість тих, хто шиє одяг власноруч, але прийме й робу, здобуту обміном чи куплену в інших майстрів. Для чорнокнижника годиться будь-який практичний спосіб роздобути цю основу.",al={"чи треба шити самому","чи можна купити робу","чи потрібне кравецтво"}},{q="Звідки береться викрійка Роби Аркани?",a="Викрійка — рідкісна здобич, що випадає здебільшого з культистів і темних чарівників, як-от закликачів Порожнечі з Темного Пасма біля Вежі Альталакса на Темному Узбережжі чи зачарувальників Дефіас у Сутінколіссі.",al={"викрійка роби аркани","як отримати викрійку","місце рецепта кравця"}},{q="Що стається з Робою Аркани, коли її віддати?",a="Менара забирає робу як сировину для подальшого ритуалу наснаження. Якщо на момент завершення завдання роба на вас, вона знімає її одразу, і ви лишаєтеся без нагрудного вбрання, доки не завершите наступні кроки.",al={"чи втрачу я робу","роба зникає","що з робою"}},{q="Що таке Зачарована Золота Кривава Роба?",a="Це особливе вбрання для чорнокнижників середнього рівня. Скріплене темними складниками й захисними чарами, воно зміцнює стійкість чарівника й запаси темної енергії.",al={"що таке кривава роба","кривава роба лор","зачарована золота кривава роба"}}},fp="43,292,18.443.0,18.366.0,61.234.0,35.159.0,47.225.0,53.191.0,58.255.0,37.182.0"}
P.entries["quest:1798"] = {n="У пошуках Страгада",s="«У пошуках Страгада» — завдання для чорнокнижників Альянсу, що посилає знавців темних мистецтв зі Стормвінда за Велике море, у Пустки. Там, неподалік від гоблінського порту Раджет, вони шукають знань Страгада Фарсана, щоб навчитися викликати мисливців Скверни. Це завдання знаменує перехід чорнокнижника на вищі, небезпечніші щаблі підкорення демонів.",h="«У пошуках Страгада» — завдання для чорнокнижників Альянсу, що посилає знавців темних мистецтв зі Стормвінда...",kw={"у пошуках страгада","страгад фарсан","ґакін зв'язувач темряви","мисливець скверни","чорнокнижник","раджет"},ang={["class:Warlock"]="Це завдання — важлива віха в зростанні чорнокнижника: від простих демонів і сукубів до хитрого мисливця Скверни, що пожирає магію.",["faction:Alliance"]="Для заклиначів Альянсу ця подорож — довгий шлях за Велике море, просто в суворе серце Калімдору, де панує Орда."},sec={{t="Поклик за море",b="У підземному притулку під «Зарізаним Ягням» у Стормвінді Ґакін Зв'язувач Темряви наглядає за розвитком молодих чорнокнижників. Та щоб опанувати хижого мисливця Скверни, потрібні матеріали, реліквії й обряди, яких скромний підвал у Кварталі магів дати не може. Бачачи, що учень набрав сили, Ґакін відсилає його геть із безпечного королівства до Калімдору — у подорож, що поєднує таємні кола людської демонології на різних континентах."},{t="Самітник із Раджета",b="Мета — посушливі пагорби над гоблінською гаванню Раджет. Там живе Страгад Фарсан, людський чорнокнижник і рівня Ґакіна в їхній таємній кабалі. Нейтральна земля дає Страгадові відносну свободу від пильних очей магістратів Альянсу, церковних інквізиторів і вартових Орди. Його присутність у Пустках — опора для честолюбних заклиначів, готових вирвати владу над демонами, що висмоктують ману."}},faq={{q="Хто посилає шукати Страгада?",a="Ґакін Зв'язувач Темряви, наставник чорнокнижників, що ховається в крипті під «Зарізаним Ягням» у Кварталі магів Стормвінда, відправляє вас у цю подорож, коли ви готові навчитися закликати мисливця Скверни.",al={"хто дає пошуки страгада","хто дає завдання","ґакін"}},{q="Де знайти Страгада Фарсана?",a="Страгад Фарсан живе в Пустках, на висотах над гоблінським портовим містечком Раджет.",al={"місце страгада","де страгад","знайти страгада"}},{q="Чому чорнокнижникові Альянсу треба їхати аж у Пустки?",a="У Стормвінді Ґакінові бракує особливих реагентів і знань, щоб провести обряди закликання мисливця Скверни. Страгад Фарсан має потрібні знання й матеріали, а оселився він на нейтральній землі Раджета, подалі від чужих очей.",al={"чому йти в пустки","чому калімдор","чому ретчет"}},{q="До якого вміння веде це завдання?",a="Це завдання — перший крок у ланцюжку, що веде до Фоліанта Кабали й ритуалу підкорення, потрібного, щоб закликати супутника — мисливця Скверни.",al={"для якого улюбленця","що я отримаю","завдання мисливця скверни"}},{q="Чи ворожий Страгад Фарсан до Орди?",a="Ні. Страгад живе на нейтральній гоблінській землі й навчає чорнокнижників і Альянсу, і Орди, які прагнуть таємниць закликання мисливців Скверни, та підтримує зв'язки з різними кабалами.",al={"чи страгад лише для альянсу","страгад орда"}},{q="Що буде після розмови зі Страгадом?",a="Привітавшись із вами, Страгад доручає зібрати потрібні складники для ритуалу підкорення — так починається кількаетапний ланцюжок завдань про Фоліант Кабали.",al={"наступне завдання","що після пошуків страгада","фоліант кабали"}}},fp="15,369,24.480.0,21.455.0,30.202.0,32.115.0,71.262.0,47.147.0,39.195.0,40.170.0"}
P.entries["quest:18"] = {n="Братство злодіїв",s="«Братство злодіїв» — одне з перших завдань, яке дає Помічник Віллем біля Абатства Нортшира. Він посилає молодих новобранців Альянсу за східну річку, щоб відтіснити зграю розбійників, відому як Братство Дефіас. Зібрані червоні бандани з мішковини — відмітний знак злодіїв — стають для влади Стормвінда першим речовим доказом організованої присутності цієї групи в долині.",h="«Братство злодіїв» — одне з перших завдань, яке дає Помічник Віллем біля Абатства Нортшира.",kw={"братство дефіас","бандани","помічник віллем","нортшир","розбійники","новобранці"},ang={["class:Rogue"]="Зустріч із Дефіас дає розбійникам-новачкам уявлення про те, як організовані злочинні мережі діють у тіні людських земель.",["faction:Alliance"]="Влада Стормвінда покладається на щойно прибулих новобранців Альянсу, щоб підтримувати мир у Нортширі, поки регулярне військо королівства розтягнуте до краю.",["race:Human"]="Для людей, що починають вишкіл у Нортширі, сутичка з Дефіас — перше суворе нагадування про те, що безпека Королівства Стормвінд руйнується зсередини."},sec={{t="Бандити в долині",b="Долину Нортширу довго вважали безпечним прихистком у Лісі Елвінн: її охороняла варта Стормвінда, а саму долину присвятили вишколу новобранців і кліриків Святого Світла. Останнім часом, однак, порядок на околицях похитнувся. Волоцюги й злодії перейшли східну річку, никають біля лісу й ставлять невеликі табори просто під носом в абатства. Помічник Віллем, що відповідає за лад у долині, розуміє: місцева варта не має людей, щоб пильнувати кожен закуток без допомоги добровольців."},{t="Багряний знак",b="Від звичайних розбійників цих злочинців відрізняють злагодженість і однакове вбрання. Вони звуть себе Братством Дефіас і засвідчують свою належність до нього червоними банданами з мішковини, якими закривають обличчя. Наказавши новобранцям полювати на розбійників і забирати їхні маски, Помічник Віллем прагне стримати їхній зухвалий наступ і водночас зважити, як глибоко Дефіас проникли в серце королівства."}},faq={{q="Хто такі Братство Дефіас?",a="Братство Дефіас — організоване угруповання розбійників і злочинців, що нині діє по всьому Лісу Елвінн і Вестфолу. Влада Нортширу спершу вважає їх просто зухвалими злодіями, але вони носять однакові червоні маски з мішковини й діють під злагодженим проводом.",al={"хто такі дефіас","що таке братство дефіас","дефіас лор"}},{q="Чому Помічник Віллем просить допомоги в новобранців, а не в Армії Стормвінда?",a="Армія Стормвінда й міська варта розпорошені по всьому королівству. Заворушення в сусідніх краях наростають, а в Стормвінді керівництву й так непросто, тож місцеві помічники шерифа мусять покладатися на завзятих добровольців і новобранців, щоб вигнати бандитів, які підбираються дедалі ближче.",al={"чому віллему потрібна допомога","де вартові стормвінда","чому немає армії"}},{q="Звідки беруться ці злодії?",a="У Нортширі злодії зібралися за річкою, на схід від абатства, і никають околицями місцевих хуторів і таборів біля виноградника.",al={"де бандити","місце дефіас нортшир"}},{q="Чому злодії носять червоні пов'язки з мішковини?",a="Червона пов'язка з мішковини — спільний знак Братства Дефіас: вона приховує обличчя й водночас показує належність до інших злочинців, що діють по всіх людських землях.",al={"чому червоні пов'язки","значення червоних масок","червона мішковина"}},{q="Що буде після цього завдання?",a="Помічник Віллем і місцеві швидко розуміють, що загроза від бандитів сягає глибше в Нортшир, тож новобранці допомагають Міллі Осворт з її знищеним урожаєм і вистежують ватажка на ім'я Ґаррик Педфут.",al={"що далі","після братства злодіїв"}},{q="Чи знає Помічник Віллем, хто очолює Дефіас?",a="Поки що Віллем не уявляє справжніх масштабів організації. Він знає лише, що вони звуть себе Братством Дефіас, і підозрює, що їхня поява біля абатства не віщує Стормвіндові нічого доброго.",al={"чи віллем знає венкліфа","хто очолює дефіас нортшир"}}},fp="22,393,21.543.0,17.440.0,31.267.0,82.264.0,36.162.0,44.197.0,41.217.0,45.203.0"}
P.entries["quest:180"] = {n="Розшукується: лейтенант Фанґор",s="Розшукується: лейтенант Фанґор — місцеве оголошення про нагороду, яке Магістрат Соломон вивісив у Лейкширі. Воно закликає шукачів пригод вистежити Лейтенанта Фанґора, лютого ватажка гнолів Тіньової Шкури, що заполонюють Гори Редріджу. Його смерть — прямий удар по чаклунові-ренегату Морґанту, якому служать гноли.",h="Розшукується: лейтенант Фанґор — місцеве оголошення про нагороду, яке Магістрат Соломон вивісив у Лейкширі.",kw={"розшукується: лейтенант фанґор","лейтенант фанґор","гноли Тіньової Шкури","морґант","магістрат соломон","лейкшир"},ang={["faction:Alliance"]="Лейкшир — важливий бастіон Альянсу в Редріджі; знищивши Фанґора, ви не дасте поселенню опинитися в цілковитій ізоляції.",["race:Human"]="Люди-захисники в Редріджі на власній шкурі відчувають байдужість Стормвінда, тож особиста боротьба з ватажками гнолів стає для них питанням виживання рідного краю."},sec={{t="Містечко в облозі",b="Лейкшир у відчайдушному становищі. Військо Стормвінда розпорошене, король Варіан Рінн загадково зник, і Верховний Лорд Болвар Фордрагон лишив прикордонні поселення на кшталт Редріджу самим дбати про себе. Клан гнолів Тіньової Шкури дедалі зухвалішає: грабує торгові шляхи, палить хутори й підступає під самі околиці містечка. Магістрат Соломон покладається на оголошення про нагороди, щоб залучити клинки найманців туди, куди не йдуть королівські солдати."},{t="Лейтенант Морґанта",b="Лейтенант Фанґор — не просто звір-мародер: він виконує волю Морґанта, темного чарівника-ренегата, що зачаївся в пагорбах Редріджу. Під командуванням Фанґора гноли Тіньової Шкури завдають злагоджених ударів, а не б'ються як розрізнені падальники, і погрожують зовсім відрізати Лейкшир від Лісу Елвінн. Відрубана лапа Фанґора стане для Магістрата Соломона доказом того, що грубий авангард Морґанта розбито."}},faq={{q="Хто такий Лейтенант Фанґор?",a="Лейтенант Фанґор — могутній ватажок гнолів з клану Тіньової Шкури, що живе в Редріджі. Він керує загонами гнолів-нападників і втілює волю Морґанта — темного чаклуна, що загрожує Лейкширу.",al={"лейтенант фанґор","хто такий фанґор","фанґор лор"}},{q="Хто оголосив винагороду за Лейтенанта Фанґора?",a="Винагороду оголосив Магістрат Соломон, очільник Лейкшира, який намагається вберегти околиці Редріджу від ворожих гнолів і темних чаклунів.",al={"хто призначив винагороду","хто хоче смерті фанґора","магістрат соломон фанґор"}},{q="Чому Стормвінд не посилає солдатів, щоб упоратися з гнолами?",a="Стормвінд паралізований раптовим зникненням короля Варіана Рінна й внутрішніми чварами. Верховний Лорд Болвар Фордрагон і Дім Вельмож відмовилися посилати загони регулярного війська до окраїнних містечок на кшталт Лейкшира, тож Магістрат Соломон мусить наймати шукачів пригод.",al={"чому немає вартових стормвінда","де солдати стормвінда","чому армія не допомагає"}},{q="Який доказ потрібен, щоб отримати винагороду?",a="Магістрат Соломон вимагає відрубану лапу Лейтенанта Фанґора як речовий доказ того, що воєводу Тіньової Шкури убито.",al={"доказ фанґора","лапа фанґора","який предмет здати"}},{q="Хто такий Морґант і чому Фанґор йому служить?",a="Морґант — чаклун-ренегат з людей, що практикує темну магію у вежі в Горах Редріджу. Він підкорив своїй волі гнолів Тіньової Шкури, а Лейтенант Фанґор став його виконавцем, що тероризує довколишні села.",al={"хто такий морґант","чому гноли слідують морганту","фанґор морґант"}},{q="Хто такі гноли Тіньової Шкури?",a="Клан Тіньової Шкури — люте плем'я гнолів, що населяє скелі й ліси Гір Редріджу. Відомі агресивністю й жорстокими засідками, вони роками не дають спокою поселенцям Лейкшира.",al={"клан тіньової шкури","гноли редріджа","тіньова шкура лор"}}},fp="26,333,18.465.0,21.441.0,26.209.0,45.174.0,57.282.0,43.127.0,48.222.0,31.219.0"}
P.entries["quest:1801"] = {n="Фоліант Кабали",s="Це завдання посилає чорнокнижників Орди з табору Страгада Фарсана в Пустках до Андерсіті на пошуки давніх демонологічних знань. Щоб викликати й підкорити мисливця Скверни, новачок мусить відшукати загублений Фоліант Кабали, почавши з картографа на ім'я Джора Аннісон. Це важливий крок до опанування вищих демонічних викликів.",h="Це завдання посилає чорнокнижників Орди з табору Страгада Фарсана в Пустках до Андерсіті на пошуки давніх...",kw={"фоліант кабали","джора аннісон","страгад фарсан","андерсіті","мисливець скверни","чорнокнижник"},ang={["class:Warlock"]="Цей обряд посвяти обов'язковий для чорнокнижників Орди, які хочуть приборкати мисливця Скверни: доведеться мандрувати між Калімдором і Східними Королівствами, щоб зібрати забуті обрядові складники.",["faction:Horde"]="Це завдання показує співпрацю темних заклиначів Калімдору з окультними вченими-Відступниками, що живуть під руїнами Лордерону."},sec={{t="Полювання на давні знання",b="Виклик мисливця Скверни — не дрібний фокус магії Скверни: ці хижі звірі пожирають магічну енергію й опираються звичайним колам виклику. Страгад Фарсан пояснює, що для цього новачкові потрібна допомога особливих кіл і давній гримуар, відомий як Фоліант Кабали. Написаний першим орденом чорнокнижників, який без сторонньої допомоги підкорив мисливця Скверни, він містить точні обряди й печаті, потрібні, щоб поневолити такого небезпечного демона."},{t="Картограф з Андерсіті",b="Оскільки примірники Фоліанта Кабали давно загубилися для чорнокнижників Калімдору, Страгад відсилає учня за море, до Джори Аннісона в Андерсіті. Хоч той формально служить королівським картографом і складає мапи Лордерону, Аннісон має надзвичайно глибокі знання про давні й маловідомі тексти. Як зізнається сам Аннісон, просте ремесло мапника він зневажає й набагато більше прагне рідкісних історій, окультних оповідей і трактатів про темну магію."}},faq={{q="Що таке Фоліант Кабали?",a="Фоліант Кабали — рідкісний окультний гримуар, написаний першими чорнокнижниками, які самотужки закликали й підкорили мисливця Скверни. У ньому — точні настанови, захисні знаки й обряди, потрібні, щоб безпечно привести в Азерот одного з цих звірів, що пожирають магію.",al={"лор фоліанта кабали","що це за книга","фоліант кабали"}},{q="Чому Страгад Фарсан посилає до Андерсіті?",a="У Страгада та його учнів у Пустках немає примірника Фоліанта Кабали. Він знає, що Джора Аннісон, картограф з Андерсіті, знавець рідкісних і давніх книжок, і може підказати, де шукати втрачені сторінки чи томи.",al={"чому до андерсіті","страгад фарсан андерсіті","чому до джори"}},{q="Хто такий Джора Аннісон?",a="Джора Аннісон — учений з Відступників, що працює в Андерсіті. Офіційно він картограф і креслить мапи, але його справжня пристрасть — маловідомі тексти, некромантські трактати й давня література.",al={"хто така джора","джора аннісон лор"}},{q="Чому для закликання мисливця Скверни потрібна особлива книга?",a="Мисливці Скверни за природою живляться чародійською й магічною енергією, тож закликати їх крізь звичайні демонічні кола важко й небезпечно. Фоліант Кабали описує особливі запобіжники, потрібні, щоб підкорити такого звіра, перш ніж той пожере закликача.",al={"навіщо книга для мисливця скверни","чому мисливця скверни важко закликати"}}},fp="17,352,28.467.0,29.487.0,30.273.0,50.237.0,21.209.0,51.254.0"}
P.entries["quest:1802"] = {n="Фоліант Кабали",s="Це завдання доручає чорнокнижникові Альянсу розшукати розірвані половини єдиного у своєму роді гримуара — Фоліанту Кабали. Без утрачених сторінок із далеких земель не розгадати темних обрядів, потрібних, щоб скорити мисливця Скверни.",h="Це завдання доручає чорнокнижникові Альянсу розшукати розірвані половини єдиного у своєму роді гримуара —...",kw={"фоліант кабали","чорнокнижник","мисливець скверни","гримуар","гілсбред","тисяча голок","кентаври"},ang={["class:Warlock"]="Здобуття розірваних половин гримуара — обряд посвяти: він відкриває вам ритуали виклику, без яких не витягти мисливця Скверни з Нижнього Світу й не поневолити його.",["faction:Alliance"]="Чорнокнижники Альянсу покладаються на айронфорджських спільників на кшталт Крома Стаутарма, щоб вистежувати рідкісні демонічні реліквії на різних континентах і не накликати відкритої підозри церкви чи корони."},sec={{t="Розділений гримуар",b="Фоліант Кабали переписали лише в одному примірнику, і бурхлива історія не дала йому вціліти. Розірваний і сплюндрований, він розлетівся уривками в зовсім різні куточки світу. Одна частина — пошматований рукопис, видертий просто з палітурки, — якось перетнула море й опинилася в суворих каньйонах Калімдору, у руках кентаврійських кланів. Другу частину мали перевезти морем із берегів Лордерону до Каз Модану, але корабель затонув, так і не дійшовши до порту."},{t="Через море й каньйони",b="Щоб знову скласти гримуар, доведеться пройти крізь дві підступні небезпеки. Сторінки, загублені в морі, винесло на узбережжя Гілсбреду на захід від Саутшора: уламки й розмоклі реліквії там прибрали до рук прибережні мурлоки біля Шахти Лазурової Жили. А по посушливу половину доведеться пробратися до Твердині Розщепленого Копита в Тисячі Голок і спуститися глибоко в печери кентаврів, щоб дістати рукопис зі старовинної скрині. Лише коли обидві половини знову разом, Кром Стаутарм зможе оглянути втрачений текст, перш ніж той повернеться до Страгада Фарсана."}},faq={{q="Що таке Фоліант Кабали?",a="Це рідкісний, єдиний у своєму роді демонічний гримуар з таємними знаннями, потрібними чорнокнижникам. У ньому — складні заклинання й ритуали підкорення, без яких не закликати мисливця Скверни з Викривленого Нижнього Світу й не скорити його.",al={"лор фоліанта кабали","що це за книга","фоліант кабали"}},{q="Хто такий Кром Стаутарм і навіщо йому фоліант?",a="Кром Стаутарм — дворф з Айронфорджа, що поринув у вивчення рідкісних і забутих текстів. За те, що він підкаже чорнокнижникам Альянсу, куди потрапили вирвані частини фоліанта, він просить лише змоги особисто вивчити його вміст, коли їх повернуть.",al={"хто такий кром стаутарм","навіщо крому книга","кром стаутарм айронфордж"}},{q="Куди потрапили дві частини книги?",a="Запліснявілий Фоліант винесло на берег Гілсбреда на захід від Саутшора, біля Шахти Лазурової Жили, і його підібрали прибережні мурлоки. Подертий Манускрипт опинився на Калімдорі, у Твердині Розщепленого Копита, — схований у пошарпаній скрині глибоко в печері кентаврів у Тисячі Голок.",al={"де частини фоліанта","місця книги","місце подертого рукопису"}},{q="Чому фоліант узагалі розірвали?",a="Фоліант Кабали переписали лише раз. Колись у його темному минулому книгу навмисно зіпсували: великий шмат вирвали з оправи й вивезли на Калімдор, а решта загинула в морі під час фатальної подорожі до Гавані Менетіл.",al={"чому фоліант розірвали","хто зіпсував фоліант"}},{q="Хто такий Страгад Фарсан і до чого він тут?",a="Страгад Фарсан — досвідчений чорнокнижник, що живе біля Раджета в Пустках. Він посилає молодих закликачів по фоліант, щоб під його наглядом вони опанували обряди закликання й підкорення мисливця Скверни.",al={"хто такий страгад","страгад фарсан","зв'язок страгада"}},{q="Чому Запліснявілий Фоліант укритий морським брудом?",a="Книга була на борту корабля, що плив з узбережжя Лордерону до Гавані Менетіл і так туди й не дістався. Уламки корабля прибило до берега Гілсбреда, де вологі, запліснявілі сторінки зібрали прибережні мурлоки біля Шахти Лазурової Жили.",al={"чому запліснявілий фоліант мокрий","фоліант хілсбрада мурлоки"}}},fp="17,262,18.560.0,21.545.0,30.227.0,51.262.0,44.274.0,47.281.0,66.214.0,43.247.0"}
P.entries["quest:1803"] = {n="Фоліант Кабали",s="Це завдання доручає чорнокнижникам Орди возз'єднати розірвані половини давнього Фоліанта Кабали для Джори Аннісона в Андерсіті. Колись гримуар зберігали в королівстві Лордерон, але його розірвали, розкидали світом, а згодом і зовсім загубили. Щоб відшукати його вогкі й пошматовані рештки, доведеться ризикнути у ворожих водах Східних Королівств і в самому серці земель кентаврів у Калімдорі.",h="Це завдання доручає чорнокнижникам Орди возз'єднати розірвані половини давнього Фоліанта Кабали для Джори...",kw={"фоліант кабали","джора аннісон","запліснявілий фоліант","подертий манускрипт","твердиня розщепленого копита","тисяча голок","чорнокнижник"},ang={["class:Warlock"]="Повернути Фоліант Кабали — обряд посвяти для досвідченіших чорнокнижників: так ви збираєте втрачені таємні знання Лордерона, щоб розширити свій арсенал викликів.",["faction:Horde"]="Пошуки манускрипту ведуть вас каньйонами Тисячі Голок, де загони Орди із Застави Вільного Вітру безупинно воюють із місцевими кентаврами.",["race:Undead"]="Фоліант зберігався в Лордероні ще до падіння королівства, тож повернути його — означає повернути окультну спадщину з колишнього людського життя Відступників."},sec={{t="Розділений спадок",b="Колись Фоліант Кабали зберігався в бібліотеці старого королівства Лордерон. Ще до падіння королівства хтось навмисно зіпсував зловісний гримуар: вирвав мало не половину сторінок і розірвав книгу надвоє. Решту основного тексту мали відправити на південь, до дворфійських зал Айронфорджа, але доля розпорядилася інакше: корабель розбився об скелясте узбережжя на захід від Саутшора, і сторінки лишилися гнити на мілині під пильним оком мурлоків, що нишпорять у пошуках поживи."},{t="Розкиданий континентами",b="Зіпсована половина фоліанта забрела ще далі. Викрадена з Лордерона, вона дісталася аж до південного Калімдору й опинилася в грубих руках кентаврів Ґалак глибоко у Твердині Розщепленого Копита в Тисячі Голок. Щоб відновити повний текст, чорнокнижник мусить обшукати вогке узбережжя Гілсбреда в пошуках Запліснявілого Фоліанта й пробратися крізь пил і дикість кентаврських каньйонів по Подертий Манускрипт. Коли обидві частини складуть перед Джорою Аннісоном, легендарний темний текст знову стане єдиною книгою, яку можна прочитати."}},faq={{q="Що таке Фоліант Кабали?",a="Це чародійський і демонічний гримуар, який колись зберігався в столиці Лордерону. У ньому — складні ритуали чорнокнижників; книгу зіпсували й розділили на дві частини, які загубилися на двох різних континентах.",al={"лор фоліанта кабали","що це за книга","фоліант кабали"}},{q="Чому одна частина книги опинилася біля Саутшора?",a="Після того як книгу зіпсували, вцілілу частину в оправі мали передати вченим Айронфорджа. Проте корабель, що її віз, розбився біля берега на захід від Саутшора, і гримуар лишився серед місцевих мурлоків.",al={"чому саутшор","походження запліснявілого фоліанта","узбережжя на захід від саутшора"}},{q="Як сторінки потрапили до кентаврів у Тисячі Голок?",a="Приблизно половину сторінок вирвали з первісного фоліанта ще в Лордероні й потай вивезли. Через торгівлю, грабунок чи випадкові руки цей подертий манускрипт зрештою опинився глибоко в Твердині Розщепленого Копита, де кентаври Ґалак тримали його в скрині.",al={"чому кентаври мають сторінки","сторінки тисячі голок","спліттхуфи тримають книгу"}},{q="Хто такий Джора Аннісон?",a="Джора Аннісон — чорнокнижник з Відступників, що працює в Магічному Кварталі Андерсіті. Він допомагає молодим чорнокнижникам Орди відшукувати забуті, заборонені знання, щоб ті глибше опанували владу над демонічними силами.",al={"джора аннісон лор","хто така джора"}},{q="Хто взагалі зіпсував фоліант?",a="Хто це зробив, достеменно невідомо. Джора Аннісон і сам бідкається через цей вандалізм і дивується, хто міг скоїти таку мерзоту з текстом такої глибокої окультної сили.",al={"хто роздер книгу","хто вкрав сторінки","вандал фоліанта"}},{q="Що Джора робить із книгою, коли ви принесете обидві частини?",a="Отримавши і Запліснявілий Фоліант, і Подертий Манускрипт, Джора Аннісон з'єднує їх в один том і прочитує сторінки, готуючи вас до наступних кроків ваших демонічних обрядів.",al={"що буде після здавання","відновлений фоліант"}}},fp="17,405,16.528.0,27.563.1,30.206.0,44.241.0,62.248.0,21.210.0,43.189.0,64.204.0"}
P.entries["quest:1804"] = {n="Фоліант Кабали",s="Це завдання — остання підготовка для чорнокнижників Альянсу, що прагнуть командувати мисливцем Скверни. Склавши докупи розірваний Фоліант Кабали, чорнокнижник мусить зібрати жезли каналізування в орків Драконячої Пащі в Багнокраї й повернутися до Страгада Фарсана на кручах над Раджетом.",h="Це завдання — остання підготовка для чорнокнижників Альянсу, що прагнуть командувати мисливцем Скверни.",kw={"фоліант кабали","кром стаутарм","жезл каналізування","драконяча паща","багнокрай","мисливець скверни"},ang={["class:Warlock"]="Підкорення мисливця Скверни — визначальний обряд посвяти, що підносить чорнокнижника від простих угод із бісами й блукачами Порожнечі до влади над хижими демонами, створеними пожирати магію.",["faction:Alliance"]="Це завдання посилає заклиначів Альянсу мандрувати між Айронфорджем, туманними болотами Багнокраю й нейтральним гоблінським портом Раджет у Калімдорі.",["race:Dwarf"]="Навіть темні мистецтва покладаються на ретельне вміння зберігати старовину, яким славиться Зала Дослідників Айронфорджа, де Кром Стаутарм складає докупи зруйновані реліквії."},sec={{t="Неохоча передача",b="У Залі Дослідників Айронфорджа Кром Стаутарм ретельно зшив докупи обвуглені, зотлілі рештки Фоліанта Кабали. Не бажаючи розлучатися з такою рідкісною пам'яткою темної вченості, дворф-учений вимагає обіцянки майбутньої копії, перш ніж передати свіжий лист від Страгада Фарсана. Фоліант містить обряди, потрібні, щоб пробити шлях у Нижній Світ, але самого лише пергаменту для обряду замало."},{t="Викрадені реліквії Драконячої Пащі",b="Перш ніж учні Страгада зможуть допомогти зв'язати такого ненажерливого демона, як мисливець Скверни, їм потрібні фокусні знаряддя, щоб утримати викликані енергії. Кром скеровує чорнокнижника до Багнокраю, де заклиначі клану Драконячої Пащі носять жезли каналізування. Вирвані з рук ворожих орків, ці фокуси дадуть колу Страгада провідник, щоб утримати розлам під контролем."},{t="Назад у Пустки",b="Доставка і відновленого гримуара, і жезлів заклиначів до вежі Страгада високо над Раджетом завершує виснажливе збирання. Знаряддя здобуто, текст перекладено, і Страгад готується розпочати небезпечний обряд зв'язування — перевірити, чи має заклинач досить сили волі, щоб приборкати гончака Палаючого Легіону."}},faq={{q="Навіщо Страгадові жезли спрямування?",a="Закликати й підкорити мисливця Скверни надто бурхлива справа для чорнокнижника-одинака без опори. Учні Страгада мусять підтримувати й фокусувати коло закликання під час ритуалу, а ці жезли спрямовують і врівноважують потрібну енергію, щоб портал не завалився й не вийшов з-під контролю.",al={"навіщо жезли спрямування","призначення жезлів спрямування","для чого жезли"}},{q="Де знайти жезли спрямування?",a="Жезли мають при собі орки-чаклуни з клану Драконячої Пащі, що живуть у Багнокраї, — особливо довкола боліт і руїн, які вони захопили.",al={"де взяти жезли спрямування","хто дропає жезли спрямування","місце жезлів спрямування"}},{q="Чому Кром Стаутарм долучився до ритуалу чорнокнижників?",a="Кром Стаутарм — майстер-дослідник з Айронфорджа, що має особливі навички, щоб перекладати, зберігати й фізично відновлювати давні пошкоджені рукописи. Захоплення рідкісними старожитностями спонукало його відновити зіпсовані сторінки Фоліанта Кабали.",al={"чому кром","чому дворф з айронфорджа допомагає чорнокнижнику","кром стаутарм чорнокнижник"}},{q="Що буде, коли віддати фоліант і жезли Страгадові?",a="Страгад одразу пускає зібране в діло й починає ритуал підкорення на вершині своєї вежі, де вам доведеться власноруч зійтися із закликаним мисливцем Скверни й скорити його.",al={"що буде далі","наступне завдання після фоліанта кабали","що робить страгад"}},{q="Хто такий Страгад Фарсан?",a="Страгад Фарсан — могутній чорнокнижник, що працює у відлюдній вежі на кручах над портовим містечком Раджет у Пустках. Досвідчені практики з усього Калімдору й Східних Королівств визнають його майстерність у демонології.",al={"страгад фарсан лор","хто такий страгад","чоловік над ретчетом"}},{q="Чи користується Фоліантом Кабали й Орда?",a="Чорнокнижники Орди проходять власну версію обрядів Фоліанта Кабали, але їхні сліди ведуть до інших людей на Калімдорі та в Андерсіті, а не до Крома Стаутарма в Айронфорджі.",al={"орда фоліант кабали","чи орки виконують це завдання"}}},fp="17,278,19.436.0,30.375.0,19.338.1,41.284.0,39.144.0,51.268.0,55.165.1,22.242.0,51.209.0"}
P.entries["quest:1805"] = {n="Фоліант Кабали",s="Це завдання — останній підготовчий етап на шляху чорнокнижника Орди до виклику мисливця Скверни й влади над ним. Допомігши Джорі Аннісону відновити давній Фоліант Кабали, знавець темних мистецтв мусить вирушити на ворожу землю, щоб здобути три жезли каналізування, а тоді принести складники Страгадові Фарсану в Раджет.",h="Це завдання — останній підготовчий етап на шляху чорнокнижника Орди до виклику мисливця Скверни й влади над...",kw={"фоліант кабали","відновлений фоліант","жезл каналізування","драконяча паща","джора аннісон","страгад фарсан"},ang={["class:Warlock"]="Це випробування перевіряє вашу рішучість здобути небезпечні обрядові складники на ворожих землях і доводить, що вам вистачить знань і відваги, щоб підкорити хижого мисливця Скверни.",["faction:Horde"]="Ренегати Драконячої Пащі в Багнокраї лишаються запеклими ворогами Орди Тралла, тож силою відібрати в них жезли каналізування — подвійна перемога для Орди.",["race:Orc"]="Розправа з орками-ренегатами Драконячої Пащі в Багнокраї — суворе нагадування про темний, нерозкаяний шлях, який Орда так прагнула залишити позаду.",["race:Undead"]="Наукова праця Джори Аннісона в Андерсіті відбиває традицію чорнокнижників-Відступників розбирати заборонені магічні тексти заради практичної магічної переваги."},sec={{t="Таємниці Відновленого фоліанта",b="В Андерсіті вчений-Відступник Джора Аннісон вивчає уламки знайденого Фоліанта Кабали, складаючи докупи його моторошні уривки. Задоволений рідкісною інтелектуальною здобиччю, Джора передає нагальне розпорядження від Страгада Фарсана. Щоб зв'язати демонічного хижака на кшталт мисливця Скверни, самих знань замало: чорнокнижник мусить мати точні знаряддя сили, здатні зосередити буйну демонічну енергію в колі зв'язування."},{t="Вилазка в Багнокрай",b="Страгадові потрібні три жезли каналізування — особливі провідники, які носять орки-ренегати з клану Драконячої Пащі. Далеко від серця земель Орди ці орки живуть серед руїн Табору Анґерфанґ у драговинах Багнокраю. Щоб їх вистежити, доведеться ступити на спірні землі, де панують ворожі рештки клану, які зневажають сучасну Орду так само, як охоче вирізають дослідників Альянсу."},{t="Повернення до Раджета",b="Зі здобутими жезлами й Відновленим фоліантом чорнокнижник повертається за море до вежі Страгада Фарсана над Раджетом. Страгад зустрічає заклинача з похмурим задоволенням. Складники для обряду виклику зібрано — усе готово до небезпечного випробування волі в сутичці з неприборканим звіром Викривленого Нижнього Світу."}},faq={{q="Яка мета цього завдання?",a="Це третій крок у ланцюжку завдань для чорнокнижників Орди, які вчаться закликати мисливця Скверни. Треба доставити відновлений Фоліант Кабали й три жезли спрямування Страгадові Фарсану, що живе над Раджетом.",al={"навіщо це завдання","мета завдання","для чого фоліант кабали"}},{q="Хто такий Джора Аннісон?",a="Джора Аннісон — чорнокнижник і вчений з Відступників, що працює в Магічному Кварталі Андерсіті. Він вивчає таємні й темні тексти й допомагає іншим практикам, складаючи докупи розірвані гримуари на кшталт Фоліанта Кабали.",al={"хто така джора","джора аннісон лор"}},{q="Навіщо потрібні жезли спрямування?",a="Щоб закликати й скорити мисливця Скверни, потрібен точний надприродний контроль. Жезли — фокусувальні провідники, що врівноважують і формують коло закликання, аби чорнокнижник скорив демона, а не сам став його здобиччю.",al={"навіщо жезли спрямування","призначення жезлів"}},{q="Де шукати орків Драконячої Пащі для цього завдання?",a="Клан Драконячої Пащі утримує Табір Анґерфанґ у Багнокраї — землях Альянсу за морем, у Каз Модані. Жадані жезли спрямування носять саме їхні кістяні вартові.",al={"де орки драконячої пащі","драконяча паща вологі землі","табір ангерфанґ"}},{q="Хто такий Страгад Фарсан?",a="Страгад Фарсан — впливовий чорнокнижник-людина, союзник темних чаклунів Орди, що працює у відлюдній вежі на кручах над гоблінським портом Раджет у Пустках.",al={"хто такий страгад","страгад фарсан ретчет"}},{q="Що буде після цього завдання?",a="Ця доставка веде просто до завдання «Зв'язування», де Страгад наказує чорнокнижникові накреслити коло закликання й зійтися в магічному бою із закликаним мисливцем Скверни, щоб скорити звіра.",al={"що далі","наступне завдання після фоліанта"}}},fp="17,320,33.453.0,25.411.0,17.365.1,34.199.0,21.231.0,34.222.0,52.199.0,22.192.0,41.191.1"}
P.entries["quest:1806"] = {n="Випробування праведності",s="Випробування праведності завершується біля кузні Джордана Стілвелла поза Айронфорджем у Дун Мороґу. Зібравши небезпечні складники по всіх Східних Королівствах і Калімдорі, паладин чекає, поки коваль створює могутній бойовий молот. Це знаменує перехід учня в визнаного захисника Світла.",h="Випробування праведності завершується біля кузні Джордана Стілвелла поза Айронфорджем у Дун Мороґу.",kw={"випробування праведності","кулак верігана","бош веріган","джордан стілвелл","паладин","бойовий молот","айронфордж"},ang={["class:Paladin"]="Цей обряд посвяти винагороджує ваші небезпечні мандри далекими землями Кулаком Верігана — знаковою зброєю, присвяченою обстоюванню праведності.",["profession:Blacksmithing"]="Спостерігати за Джорданом Стілвеллом біля ковадла — бачити, як майстерність може вкласти святе призначення в сиру сталь і здобуті матеріали.",["race:Dwarf"]="Викуваний тут молот увічнює пам'ять Боша Верігана, шанованого дворфійського паладина, який утілював стійкість Каз Модану."},sec={{t="Данина коваля",b="Майстер-коваль Джордан Стілвелл працює біля воріт Айронфорджа. Хоч він і зізнається в дрібці заздрості до мандрівних паладинів, він глибоко пишається тим, що підтримує справу своїм молотом і ковадлом. Коли йому приносять рідкісні матеріали, зібрані в тіньових криптах, затонулих руїнах і небезпечних копальнях, Стілвелл виконує обіцянку й кує зброю, гідну справжнього захисника."},{t="Спадщина Боша Верігана",b="Готовий бойовий молот охрещено Кулаком Верігана на честь Боша Верігана, шанованого дворфійського паладина й близького особистого друга Джордана Стілвелла. Передаючи цю священну зброю в руки молодого захисника від себе й від дружини, Стілвелл дбає, щоб пам'ять і доблесть його полеглого друга жили далі проти темряви, що загрожує Азероту."}},faq={{q="Що відбувається на цьому етапі завдання?",a="Джордан Стілвелл підходить до ковадла й кує розпечений метал, з'єднуючи складники, які ви зібрали за час своїх тяжких випробувань. Попрацювавши біля горна, він повертається й вручає вам готову зброю.",al={"кінець випробування праведності","джордан кує зброю","сцена веріґана"}},{q="Хто такий Бош Веріґан?",a="Бош Веріґан був шанованим паладином-дворфом і близьким другом Джордана Стілвелла. На його честь Джордан назвав щойно викуваний дворучний молот, ушановуючи його відданість Святому Світлу.",al={"хто такий веріґан","кулак веріґана","бош веріґан"}},{q="Де відбувається кування?",a="Кування відбувається одразу за великою брамою Айронфорджа, серед засніжених вершин Дун Мороґу, де Джордан Стілвелл тримає свою кузню й ковадло.",al={"місце джордана стілвелла","де кузня","ковадло дун морога"}},{q="Навіщо Джорданові рідкісні матеріали з усього світу?",a="Джордан задумав зброю винятково врівноважену й сповнену святого резонансу. Щоб викувати річ, здатну витримати святий гнів паладина, йому були потрібні рідкісні руди, деревина й самоцвіти, які можна здобути лише в небезпечних куточках світу.",al={"навіщо збирати матеріали","складники випробування праведності"}},{q="Чи б'ється Джордан Стілвелл сам?",a="Джордан Стілвелл — коваль, а не мандрівний воїн. Хоч він і зізнається, що часом заздрить шукачам пригод, які мандрують світом, своє справжнє покликання й гордість він знаходить у тому, щоб кувати зброю для захисників Світла.",al={"чи джордан воїн","джордан стілвелл боєць"}},{q="Що означає для паладина отримати цей молот?",a="Отримати молот — значить успішно завершити довгі випробування паладина. Це доказ того, що його власник має мужність, наполегливість і святу віру, потрібні, щоб боронити Світло в найнебезпечніших куточках Азерота.",al={"значення кулака веріґана","обряд паладина"}}},fp="25,320,17.391.0,27.358.0,43.211.0,21.190.0,35.152.0,59.243.0,50.225.0,54.228.0"}
P.entries["quest:181"] = {n="Подивись на зорі",s="Це завдання — останній розділ задуму Вікторі Призм'Антраса зібрати в Даркширі прилад для споглядання зірок. Телескоп уже майже готовий, тож Вікторі посилає мандрівників до небезпечного Огрського Кургану Вул'Ґол по лінзу, досить велику для його пристрою: монокль, який носить огр Ззарк'Вул.",h="Це завдання — останній розділ задуму Вікторі Призм'Антраса зібрати в Даркширі прилад для споглядання зірок.",kw={"подивись на зорі","ззарк'вул","огрський курган вул'ґол","коґ ґлітцспіннер","монокль","телескоп"},ang={["faction:Alliance"]="Даркшир ледве виживає серед жахіть і звірів, тож прагнення Вікторі до небесних знань стає незгасним, хай і дивакуватим, маяком людської стійкості.",["profession:Engineering"]="І маги, і майстри оцінять зухвалість задуму: замінити астрономічну лінзу величезним огрським моноклем, щоб досягти потрібної фокусної відстані.",["race:Gnome"]="Пристрій тримається на гномських кресленнях і вимагає геніальної польової імпровізації — як-от перетворити окуляри громила на точну оптику."},sec={{t="Остання деталь",b="Будуючи свій телескоп, Вікторі Призм'Антрас увесь час спирався на креслення гномського інженера Коґа Ґлітцспіннера. Латунні труби й міцні кріплення можна було роздобути чи зібрати з місцевих матеріалів, але приладові потрібна була надзвичайно велика фокусувальна лінза. Звичайним збільшувальним скельцям і оптичним деталям від торговців зі Стормвінда просто бракувало діаметра, якого вимагав сміливий задум Коґа, — тож Вікторі звернув погляд на несподівану й небезпечну альтернативу."},{t="Скельце огра",b="У тіні південних пагорбів лежить Огрський Курган Вул'Ґол — табір, що кишить ворожими громилами-ограми. Серед них живе Ззарк'Вул — особливий огр, відомий тим, що носить скляний монокль, досить великий, щоб стати лінзою обсерваторії. Пробившись углиб кургану й забравши скельце в Ззарк'Вула, ви виконаєте креслення Коґа, і Вікторі зможе завершити телескоп та зазирнути в небеса над темними кронами Сутінколісся."}},faq={{q="Хто такий Вікторі Призм'Антрас?",a="Вікторі Призм'Антрас — астроном і вчений, що живе в хатині на пагорбі в Даркширі. Попри морок, що огортає Сутінколісся, він і далі завзято добудовує свій телескоп, щоб вивчати зорі.",al={"хто такий вікторі","вікторі призм'антрас"}},{q="Де знайти Ззарк'Вула?",a="Ззарк'Вул живе на півдні Сутінколісся, в Огрському Кургані Вул'Ґол. Він никає табором і печерами кургану, тож шукачам доведеться пробиратися крізь добре охоронювані володіння огрів.",al={"місце ззарк'вула","де огр","місце монокля огра"}},{q="Звідки в огра монокль?",a="Огри не славляться ні вченістю, ні тонкою оптикою, проте Ззарк'Вул носить величезний монокль. Через свої незвичні розміри це єдина лінза в краю, достатньо велика для креслень телескопа від Коґа.",al={"чому в огра монокль","монокль огра лор"}},{q="Що буде, коли пристрій завершено?",a="Здобувши монокль, Вікторі вставляє на місце останню лінзу. Коли телескоп повністю зібрано, Вікторі може знову вивчати небо, і похмура лісова земля внизу йому вже не завадить.",al={"телескоп готовий","кінець завдання"}},{q="Хто сконструював телескоп?",a="Креслення пристрою надав інженер на ім'я Коґ; його складний задум вимагав особливих деталей, металевого каркаса й лінзи, значно більшої за звичайні дворфійські чи гномські окуляри.",al={"креслення коґа","хто збудував телескоп"}},{q="Чи безпечно йти в Огрський Курган Вул'Ґол самому?",a="Ні. Огрський Курган Вул'Ґол густо населений ворожими ограми, які часто патрулюють гуртом або стережуть вузькі проходи. Пробиратися вглиб кургану на пошуки Ззарк'Вула для мандрівника-одинака дуже небезпечно.",al={"складність вул'ґола","чи безпечно в огрському кургані"}}},fp="17,312,15.508.0,19.438.1,28.210.0,27.220.0,35.226.0,42.197.0,27.202.0,42.212.0"}
P.entries["quest:1818"] = {n="Поговори з Діллінджером",s="«Поговори з Діллінджером» — воєнний наказ Орди, виданий в Андерсіті. Остіл Де Мон посилає дужих бійців до Вартового Смерті Діллінджера в Бріллі, щоб ті взялися за небезпечне бойове доручення на службі Леді Сильвани.",h="«Поговори з Діллінджером» — воєнний наказ Орди, виданий в Андерсіті.",kw={"поговори з діллінджером","вартовий смерті діллінджер","остіл де мон","брілл","галявини тірісфалю","воїн"},ang={["class:Warrior"]="Командири вартових смерті понад усе цінують бойову загартованість, тож це доручення — пряма перевірка ваших бойових умінь на передовій.",["faction:Horde"]="Відгукуючись на заклики боронити Андерсіті, ви зміцнюєте єдність між союзниками з Калімдору й Відступниками, що нещодавно влилися в Орду.",["race:Undead"]="Для щойно визволених Відступників відгукнутися на поклик Діллінджера — важливий крок, щоб довести відданість Темній Леді й обороні Тірісфалю."},sec={{t="Виклик на передову",b="У підземних залах Андерсіті Остіл Де Мон пильно видивляється перспективних бійців, готових служити Темній Леді. Коли вартовим смерті на поверхні потрібні вправні руки, Де Мон відсилає ще не випробуваних шукачів пригод із королівської столиці в поле. Вартовий Смерті Діллінджер, що відповідає за безпеку на західних околицях Брілла, попросив прислати когось із бойовим вишколом для нагальної справи."},{t="Випробування вірних",b="Брілл стоїть просто на передовій Галявин Тірісфалю, де Відступники мусять постійно доводити свою бойову перевагу над ворожими загрозами. Пост Діллінджера біля сільського цвинтаря — найкраще місце, щоб давати раду місцевим вторгненням. Для молодого воїна прибути до Діллінджера — не просто доручення: це офіційне випробування бойової вправності й політичної вірності щойно викуваному народові Відступників."}},faq={{q="Хто посилає мене на це доручення?",a="Остіл Де Мон з Андерсіті вишукує можливих бійців і посилає їх на допомогу Вартовому Смерті Діллінджеру.",al={"хто дає завдання","остіл де мон","хто дає поговори з діллінджером"}},{q="Де знайти Вартового Смерті Діллінджера?",a="Вартовий Смерті Діллінджер стоїть на західній околиці Брілла в Галявинах Тірісфалю, біля входу на цвинтар.",al={"місце діллінджера","де діллінджер","знайти діллінджера"}},{q="Навіщо з'являтися до Діллінджера?",a="Діллінджерові потрібен вправний боєць для бойового доручення: захистити Брілл і довести свою відданість справі Відступників.",al={"навіщо говорити з діллінджером","мета діллінджера"}},{q="Яке доручення приготував Діллінджер?",a="Щойно ви з'явитеся до Вартового Смерті Діллінджера, він доручить вам вистежити небезпечну загрозу на ім'я Улаг Різник.",al={"чого хоче діллінджер","наступне завдання діллінджера"}},{q="Чи отримують цей наказ інші раси Орди?",a="Взятися за доручення може будь-який воїн Орди, що здобув довіру урядовців Андерсіті, хоча передусім воно розраховане на перевірку новобранців, які боронять Галявини Тірісфалю.",al={"чи лише для нежиті","чи орки можуть це"}},{q="Чому цей наказ дають в Андерсіті, а не в Бріллі?",a="Остіл Де Мон — вербувальник у столиці: він спрямовує щойно загартованих шукачів пригод до командирів на прикордонні, яким нагально потрібна сила.",al={"чому початок в андерсіті","роль остіла де мона"}}},fp="20,221,22.434.0,20.419.0,29.117.0,40.111.0,46.129.0,45.117.1,40.168.0,62.153.0"}
P.entries["quest:1819"] = {n="Улаг Різник",s="Улаг Різник — обряд посвяти для молодих воїнів Відступників у Галявинах Тірісфалю. Вартовий Смерті Діллінджер доручає вам звільнити й стратити поневоленого воїна Погибелі, ув'язненого в північному мавзолеї, — випробування вашої бойової рішучості, що здобуде вам повагу Вартових Смерті.",h="Улаг Різник — обряд посвяти для молодих воїнів Відступників у Галявинах Тірісфалю.",kw={"улаг різник","діллінджер","брілл","мавзолей","погибель","воїн","випробування"},ang={["class:Warrior"]="Це випробування — ранній полігон для воїнів Відступників: воно перевіряє вашу відвагу в сутичці з могутнім, підкореним чужій волі поборником Погибелі.",["race:Undead"]="Доля Улага показує жахливу правду про владу Погибелі — трагічну межу між Відступниками, які вирвалися на волю, і тими, чий розум досі в рабстві Короля-Ліча."},sec={{t="Скутий раб Погибелі",b="Коли Погибель прокотилася Лордероном, Відступникам вдалося захопити незвичайного воїна-нежить, який назвався Улагом Різником. Розум Улага лишався ясним і притомним, та дух його нерозривно скоряла психічна воля Короля-Ліча. Прагнучи зрозуміти, як саме Погибель сковує вільну волю, Відступники тримали його під магічною печаттю в мавзолеї на північ від Брілла, сподіваючись розірвати духовні ланцюги цієї сутності."},{t="Випробування ката",b="Усі спроби вирвати Улага з ментальних лещат Короля-Ліча зазнали невдачі. Збагнувши, що справжню свободу йому може дати лише знищення, Вартовий Смерті Діллінджер перетворив бранця на бойове випробування для молодих воїнів Відступників. Зрушивши камінь-череп біля входу до склепу, воїн ламає захисні печаті, випускає Улага з ув'язнення — і дарує йому звільнення лезом сокири."}},faq={{q="Хто такий Улаг Різник?",a="Улаг Різник — воїн-нежить, якого Відступники схопили під час навали Погибелі на Галявини Тірісфалю. Дивовижно, але він зберіг вільний розум і особистість, проте й далі цілковито корився подумковим наказам Короля-Ліча.",al={"улаг лор","хто такий улаг","особа улага різника"}},{q="Чому Улага ув'язнили під мавзолеєм?",a="Учені й солдати Відступників ув'язнили його під магічною печаттю, щоб вивчити, як діє влада Короля-Ліча над розумом. Вони сподівалися знайти спосіб розірвати псіонічний зв'язок, що тримав його, але досліди не вдалися.",al={"чому улага ув'язнили","в'язень мавзолею тіріфальські гаї"}},{q="Чому Вартові Смерті тепер хочуть убити Улага?",a="Визнавши, що вирвати Улага з лабет Короля-Ліча не вдасться, Відступники вирішили, що смерть — єдина милість, яка лишилася. Вартовий Смерті Діллінджер вирішив зробити цю страту перевіркою бойової відваги й дисципліни для молодих воїнів.",al={"чому вбити улага","причина вбити улага"}},{q="Як викликати Улага?",a="Він ув'язнений під мавзолеєм трохи на північ від Брілла. Якщо скористатися кам'яним черепом біля гробниці, магічна печать, що тримає його, спадає, і Улаг повстає й нападає.",al={"як викликати улага","де улаг","череп улага"}},{q="Хто дає завдання вбити Улага?",a="Вартовий Смерті Діллінджер, що стереже західний шлях з Брілла в Галявинах Тірісфалю, дає це доручення саме воїнам-Відступникам, які прагнуть подальшої науки.",al={"хто дає завдання улага","хто посилає до улага"}},{q="Що буде після перемоги над Улагом?",a="Переконавшись, що Улаг загинув, Вартовий Смерті Діллінджер визнає вашу доблесть і посилає вас до Коулмена Фартінґа в Бріллі, щоб продовжити навчання.",al={"після улага","продовження завдання улага"}}},fp="16,280,22.455.0,23.417.0,24.233.0,44.246.0,44.236.0,21.178.0,33.174.0,36.156.0"}
P.entries["quest:182"] = {n="Тролляча печера",s="Доручене горянином Ґреліном Вайтбірдом, це завдання посилає шукачів пригод винищити молодих тролів Морозогривів, що збираються в південних печерах Долини Холодного Хребта. Поки Сенат Айронфорджа заклопотаний дедалі гострішою кризою з трогами, самотні розвідники й охочі новобранці мусять давати раду прикордонним сутичкам, перш ніж тролі закріпляться назавжди.",h="Доручене горянином Ґреліном Вайтбірдом, це завдання посилає шукачів пригод винищити молодих тролів...",kw={"тролляча печера","ґрелін вайтбірд","морозогриви","тролі","долина холодного хребта","розвідка","печера"},ang={["class:Hunter"]="Скелі довкола південної печери — суворий полігон для молодих слідопитів, що вчаться виганяти ворожу здобич із гірських висот.",["race:Dwarf"]="Для молодих дворфів Бронзбірдів, що виходять у сніги, винищення загонів Морозогривів — і справа прикордонної безпеки, і давня гірська ворожнеча.",["race:Gnome"]="Знайшовши притулок у Дун Мороґу після падіння Гномреґану, гноми охоче дають свій розум і зброю, щоб позбавити дворфів-господарів довколишніх загроз."},sec={{t="Очі на холоді",b="Поки регулярні сили Айронфорджа поглинуті відбиттям набігів трогів Кам'янощелепів по снігових полях, південні підступи не можна лишати без нагляду. Ґреліна Вайтбірда та його брата Сеніра гірська влада відрядила оцінити, чи становлять тутешні крижані тролі безпосередню небезпеку для серця краю. З кручі над замерзлою долиною Ґрелін сам-один стежить за їхніми пересуваннями."},{t="Випереджувальний удар",b="Розвідка Ґреліна показала, що місцевий клан Морозогривів почав оселятися в глибокій печері вздовж південного хребта Долини Холодного Хребта. Вважаючи повну військову мобілізацію марною тратою дворфійських сил, розвідник волів найняти вправних місцевих добровольців, щоб винищити зухвалих молодиків. Прорідити їхніх молодих бійців — означає зірвати їхній табір, перш ніж Морозогриви зможуть здійснити узгоджені набіги на сусідні дворфійські обійстя."}},faq={{q="Чому Айронфордж не посилає регулярних солдатів проти цих тролів?",a="Сенат Айронфорджа й дворфійське військо розпорошені, бо мусять стримувати раптову нищівну навалу трогів по всьому Дун Мороґу. Дрібні загрози на кшталт невеликих ватаг тролів лишають розвідникам, як-от Ґреліну Вайтбірду, а ті наймають незалежних шукачів пригод.",al={"чому немає армії дворфів","де вартові","чому наймають шукачів пригод"}},{q="Хто такі тролі Морозогриви?",a="Морозогриви — корінне плем'я крижаних тролів, споконвіку мешканців холодних скель Дун Мороґу. Віддавна ворожі до дворфів Бронзбірдів, вони постійно сутичкуються з горянами за мисливські угіддя, землю й давні гірські перевали.",al={"клан морозогривів","тролі дун морога","хто такі морозогриви"}},{q="Де розташована тролляча печера?",a="Печера схована в південному гірському хребті Долини Холодного Хребта, на південь від спостережного табору Ґреліна Вайтбірда.",al={"місце тролячої печери","де печера","де молодняк"}},{q="Хто такий Ґрелін Вайтбірд?",a="Ґрелін Вайтбірд — розвідник з Айронфорджа, що стоїть у Долині Холодного Хребта. Разом із братом Сеніром, який оглядає інші куточки Дун Мороґу, Ґрелін стежить за ворожими тролями й доповідає дворфійським очільникам.",al={"ґрелін","хто дає завдання","вайтбірд"}},{q="Чому Ґрелін полює саме на молодняк Морозогривів?",a="Табір на півдні Долини Холодного Хребта — поселення, що швидко росте й повне молодих воїнів. Знищивши їхніх бійців, поки ті не підросли, можна не дати ватазі набратися сили й загрожувати дворфійським шляхам постачання.",al={"чому молодняк","чому молоді тролі"}},{q="Що буде, коли проріджено печеру?",a="Повернувшись, ви дізнаєтеся, що вночі тролі помстилися: напали на табір Ґреліна й поцупили його особистий польовий щоденник, тож його доведеться негайно повернути з глибин їхніх лігв.",al={"що далі","продовження тролячої печери"}}},fp="14,348,16.431.0,19.464.0,70.270.0,29.237.0,32.120.0,25.216.0,53.218.0,36.197.1"}
P.entries["quest:1820"] = {n="Поговори з Колманом",s="«Поговори з Колманом» — перехідне завдання в Галявинах Тірісфалю для тих, хто вже довів свою вартість у боротьбі з Погибеллю. Вартовий Смерті Діллінджер відсилає здібних воїнів із міської площі до місцевої таверни — допомогти Коулмену Фартінґу з його особистими та фракційними порахунками.",h="«Поговори з Колманом» — перехідне завдання в Галявинах Тірісфалю для тих, хто вже довів свою вартість у...",kw={"коулмен фартінґ","брілл","таверна","діллінджер","вендета","тірісфаль"},ang={["faction:Horde"]="Для мандрівників, що допомагають убезпечити Лордерон, знайомство з місцевими жителями Брілла — надійна опора для дій по всіх Галявинах Тірісфалю.",["race:Undead"]="Багато Відступників поряд із вірністю Темній Леді плекають особисті образи; прохання Коулмена Фартінґа показують, як тісно у Тірісфалі переплітаються особиста втрата й захист нації."},sec={{t="Слово від варти",b="Допомігши приборкати серйозні місцеві загрози — скажімо, упокоївши небезпечні рештки Погибелі на кшталт Улага Різника, — шукачі пригод здобувають особисту довіру Вартового Смерті Діллінджера. Як один із вартових, що пильнують дороги до Брілла, Діллінджер сам судить, хто здатен на більше, ніж звичайні обходи периметра, і скеровує вмілих бійців до городян, яким потрібна особлива послуга."},{t="Приватна вендета",b="Не кожен конфлікт у Галявинах Тірісфалю ведеться за наказом верховного командування з Андерсіті. По всьому зруйнованому королівству Лордерон уцілілі мерці носять у собі глибокі образи, пов'язані з землями, родинами й статками, що лишилися в минулому. Коулмен Фартінґ вичікує в Таверні «Шибеничний Кінець», шукаючи знаряддя помсти, щоб ударити по загрозах, які й досі тиняються біля колишніх поселень на кшталт Млинів Аґаманда."}},faq={{q="Де знайти Коулмена Фартінґа?",a="Коулмен Фартінґ чекає в таверні «Шибеничний Кінець» у східній частині Брілла в Галявинах Тірісфалю.",al={"місце коулмена фартінґа","де коулмен фартінґ","знайти фартінґа брилл"}},{q="Хто посилає поговорити з Коулменом?",a="Вартовий Смерті Діллінджер, що стереже шлях до Брілла, посилає вас до Коулмена, коли ви доведете свою бойову вправність.",al={"хто дає поговори з колманом","завдання діллінджера"}},{q="Яку роботу має Коулмен Фартінґ?",a="Коулменові потрібен вправний боєць, який стане знаряддям помсти ворогам Відступників, — ідеться про давні володіння Аґамандів.",al={"чого хоче коулмен","завдання коулмена фартінґа"}},{q="Що треба зробити, перш ніж отримати це завдання?",a="Вартовий Смерті Діллінджер посилає вас до Коулмена лише тоді, коли ви доведете Відступникам свою відданість і бойову вправність, перемігши Улага Різника.",al={"передумови поговори з колманом","вимога улага"}},{q="Чи дає це доручення вагомі нагороди?",a="Це доручення лише знайомить вас із Фартінґом у корчмі й відкриває низку його особистих прохань, а саме по собі не дає ні доброго спорядження, ні грошей.",al={"нагороди поговори з колманом","чи варто робити"}},{q="Що таке таверна «Шибеничний Кінець»?",a="Таверна «Шибеничний Кінець» — головний заїзд Брілла: місце зустрічей, відпочинку й неофіційний осередок приватних угод серед місцевої нежиті.",al={"таверна брилла","шибеничний кінець"}}},fp="18,283,21.406.0,18.413.0,34.123.0,33.132.0,45.174.0,57.145.0,53.164.0,32.162.0"}
P.entries["quest:1821"] = {n="Реліквії роду Аґамандів",s="Коулмен Фартінґ доручає шукачам пригод сплюндрувати Родинний Склеп Аґамандів на північному краю Млинів Аґаманда. Гнаний гіркою образою за власну смертну загибель, він прагне відібрати в колишніх господарів їхню родову зброю і стерти останні рештки їхньої гідності.",h="Коулмен Фартінґ доручає шукачам пригод сплюндрувати Родинний Склеп Аґамандів на північному краю Млинів...",kw={"аґаманди","склеп","реліквії","коулмен фартінґ","млини аґаманда","родова зброя"},ang={["class:Rogue"]="Прослизнути повз гулів, що чигають у темряві, і поцупити стародавню зброю з охоронюваних поховальних склепінь — для майстрів тіні справа звична.",["faction:Horde"]="Зачистка склепу підриває укорінену владу Погибелі над північчю Галявин Тірісфалю, роблячи край безпечнішим для мандрівників Орди.",["race:Undead"]="Гірке завдання Коулмена Фартінґа втілює давні образи й незагоєні рани, які чимало Відступників несуть зі смертного життя в нежиття."},sec={{t="Гірка образа слуги",b="Перш ніж Третя війна спустошила Лордерон, Коулмен Фартінґ служив заможній і впливовій родині Аґамандів на їхніх розлогих млинах у Галявинах Тірісфалю. Хай що сталося під час падіння маєтку, у своїй смерті Фартінґ цілковито звинувачує колишніх панів. Тепер, піднятий у нежитті серед Відступників, він дивиться на падіння Аґамандів зі злісним задоволенням, радіючи, що колись горда династія обернулася на безтямних прислужників Короля-Ліча."},{t="Осквернення склепу",b="Щоб остаточно загасити рештки родинної слави, Фартінґ посилає шукачів пригод до Родинного Склепу Аґамандів, схованого під північними кручами млинів. У його населених привидами кам'яних залах неспокійні мерці блукають пліч-о-пліч із недобитками Погибелі. Фартінґ вимагає добути чотири славетні реліквії — родовий меч, сокиру, кинджал і булаву Аґамандів, — щоб спадок їхнього роду позбувся останньої крихти честі."}},faq={{q="Ким був Коулмен Фартінґ за життя?",a="Коулмен Фартінґ був слугою заможної родини Аґамандів у Млинах Аґаманда ще до навали Погибелі на Лордерон. Він загинув під час лиха й звинувачує у своїй смерті господарів; ця пекуча образа не згасла й у нежитті.",al={"хто такий коулмен фартінґ","передісторія коулмена","історія фартінґа"}},{q="Навіщо Коулменові Фартінґу родинні реліквії?",a="Фартінґ прагне повної помсти колишнім господарям. Пограбувавши з родинного склепу їхні родові меч, сокиру, кинджал і булаву, він хоче позбавити занепалий рід останніх решток честі й пам'яті.",al={"навіщо красти реліквії","мотив коулмена","навіщо брати зброю"}},{q="Що сталося з родиною Аґамандів?",a="Родина Аґамандів загинула, коли Погибель пронеслася Галявинами Тірісфалю. Замість знайти спокій у смерті, вони повстали безвольними рабами-нежиттю, скореними волі Короля-Ліча, і тепер блукають своїми зруйнованими млинами й склепом.",al={"доля аґамандів","чи аґаманди живі","що з аґамандами тепер"}},{q="Де розташований Родинний Склеп Аґамандів?",a="Склеп лежить на північній околиці Млинів Аґаманда, врізаний у скелясті урвища над спаплюженими хуторами на півночі Галявин Тірісфалю.",al={"місце склепу","де склеп","мапа склепу аґамандів"}},{q="Яка зброя зберігається в склепі?",a="У склепі зберігаються чотири родові зброї цього роду: Меч Родини Аґаманд, Сокира Родини Аґаманд, Кинджал Родини Аґаманд і Булава Родини Аґаманд.",al={"які реліквії","чотири реліквії","зброя аґамандів"}},{q="Чому Відступники нападають на Аґамандів, якщо і ті, й інші — нежить?",a="Відступники мають вільну волю й борються за власне виживання, а Аґаманди-нежить лишаються безвольними рабами Погибелі й служать Королеві-Лічу, якого Відступники зневажають.",al={"нежить проти нежиті","чому б'ються з аґамандами","конфлікт відступників і погибелі"}}},fp="17,272,25.468.0,21.443.0,33.266.0,45.219.0,36.230.0,42.144.0,39.181.0,63.180.0"}
P.entries["quest:1824"] = {n="Випробування на Полі Велетнів",s="«Випробування на Полі Велетнів» — обрядове завдання для воїнів, яке дає Руґа Рейджтотем у Таборі Тауражо. У межах вишколу молодих бійців посилають на південь, до кишучих кучугур Поля Велетнів, щоб убивати чужинських комахоподібних загарбників. Кандидати мають зібрати кілька вусиків, що ще сіпаються, і щодуху примчати з ними назад, поки біологічний доказ не завмер.",h="«Випробування на Полі Велетнів» — обрядове завдання для воїнів, яке дає Руґа Рейджтотем у Таборі Тауражо.",kw={"випробування на полі велетнів","руґа рейджтотем","силітиди","сіпливе вусико","табір тауражо","воїн"},ang={["class:Warrior"]="Це випробування — важливий обряд посвяти приблизно на двадцятому рівні: воно перевіряє, чи вміє воїн швидко розправлятися з роями супротивників і зберігати витривалість у суворо обмежений час.",["faction:Horde"]="Орда насторожено стежить за поширенням силітидів на півдні Пусток і вважає кожне навчальне випробування передовою розвідкою проти загрози, що повзе.",["race:Tauren"]="Для тауренів-оборонців очищення оскверненого Поля Велетнів допомагає захистити їхні мисливські угіддя довкола Табору Тауражо від неприродного вулика-загарбника."},sec={{t="Випробування швидкості й сталі",b="Наставники воїнів в Орді рідко задовольняються самим лише бойовим умінням, не перевіривши стійкості й швидкості. Руґа Рейджтотем кидає виклик молодим воїнам у Таборі Тауражо: довести себе в бою з незнайомим супротивником. Від новачків вимагають не лише вбивати загарбників — вони мусять відтяти свіжі вусики й повернутися до Тауражо за пів години, поки зрізані тканини не перестали сіпатися, а для цього треба швидко орієнтуватися на півдні Пусток."},{t="Непрохані гості",b="Мета випробування — вулики силітидів, що розростаються на Полі Велетнів, під велетенськими скам'янілими реберними кістяками. Ці повзучі хітинові комахи — недавні прибульці в Пустках, і вони непокоять тауренських мисливців і шаманів, що наглядають за саванами. Руґа з тривогою зауважує, що їхня поява не віщує Калімдору нічого доброго, тож випробування-винищення має подвійну мету: перевірити бойове чуття молодого воїна й зібрати відомості про загрозу, що нависла над природою."}},faq={{q="Чому на вусики дано обмежений час?",a="Руґа Рейджтотем вимагає, щоб вусики ще сіпалися, коли їх принесуть до Табору Тауражо, тож воїни мають лише тридцять хвилин, щоб упоратися з полюванням і повернутися. Така свіжість доводить, що претендент швидко здолав сілітида в чесному бою, а не підібрав мертвий панцир.",al={"чому обмежений час","таймер вусиків","скільки часу"}},{q="Які істоти живуть на Полі Велетнів?",a="Поле Велетнів кишить сілітидами — дивною й агресивною расою комах-копачів. Вони нарили величезні горби й вулики під давніми скам'янілостями, порушуючи місцеву природу й насторожуючи Орду.",al={"які це комахи","істоти поля велетнів","що таке сіліти"}},{q="Хто такий Руґа Рейджтотем?",a="Руґа Рейджтотем — таурен, наставник воїнів, що стоїть у Таборі Тауражо в південних Пустках. Він проводить випробування, що перевіряють уміння, стійкість і швидкість воїнів Орди, які прагнуть піднятися вище.",al={"руґа","хто дає завдання","руґа рейджтотем лор"}},{q="Де розташоване Поле Велетнів?",a="Поле Велетнів лежить одразу на південь від Табору Тауражо, обабіч шляху перед південним перевалом до Тисячі Голок. Його легко впізнати за височенними кістяними ребрами й горбами сілітидів.",al={"де поле велетнів","місце поля велетнів","де шукати комах"}},{q="Куди веде цей ланцюжок навчання далі?",a="Коли воїн вчасно принесе вусики, що ще сіпаються, Руґа посилає його до Тун'ґріма Файрґейза — старого орка-коваля, що живе на пагорбі на схід від Перехрестя й кує обладунки для випробуваних воїнів.",al={"наступне завдання","що далі","продовження воїна"}},{q="Чому таурени непокояться через комах?",a="Сілітиди — неприродні прибульці в Пустках. Руґа каже, що їхня поява не віщує краю нічого доброго, і підозрює, що їхнє агресивне риття й поширення провіщають набагато більшу небезпеку, яка ворушиться під пісками.",al={"чому таурени переймаються","вісник комах","загроза сілітидів"}}},fp="28,361,25.458.0,19.485.0,42.297.0,43.221.0,22.208.0,37.205.0,41.226.0,47.220.0"}
P.entries["quest:1825"] = {n="Поговори з Тун'ґрімом",s="Це доручення скеровує молодих воїнів Орди до Тун'ґріма Файрґейза — знаного оркського коваля, що отаборився в Пустках. Довівши себе у важких фізичних випробуваннях, воїни отримують запрошення: їм викують обладунок на знак визнання їхньої доблесті. Завдання — важливий місток між загальними випробуваннями воїнів і куванням жорстокого обладунку.",h="Це доручення скеровує молодих воїнів Орди до Тун'ґріма Файрґейза — знаного оркського коваля, що отаборився в...",kw={"поговори з тун'ґрімом","тун'ґрім файрґейз","руґа рейджтотем","жорстокий обладунок","воїн","перехрестя"},ang={["class:Warrior"]="Це завдання — важливий обряд посвяти, що підносить вас від бійця-новачка до визнаного звитяжця, гідного обладунку, викуваного на замовлення.",["faction:Horde"]="Бронники Орди пишаються тим, що озброюють найзапекліших оборонців, і дбають, щоб ті, хто б'ється на рубежах, носили спорядження, гідне їхніх бойових звершень.",["profession:Blacksmithing"]="Тун'ґрім Файрґейз уособлює традиційну оркську ковальську філософію: майстерний обладунок треба заслужити бойовими випробуваннями, а не просто монетою."},sec={{t="Поклик коваля",b="Довівши свій гарт у сутичках із вуликами силітидів під час «Випробування на Полі Велетнів», воїни Орди отримують від Руґи Рейджтотема більше, ніж звичайну похвалу. Звістка про їхню витривалість і бойову вправність швидко доходить до Тун'ґріма Файрґейза — знаного оркського коваля, чий табір стоїть на кряжі на схід від Перехрестя. Упізнавши воїна, гідного своєї майстерності, Тун'ґрім передає, що хоче викувати для нього надзвичайні бойові лати."},{t="Мірило майстра",b="Тун'ґрім Файрґейз не кує для звичайних солдатів. Для бронника з такою славою сталь має відповідати духові того, хто понесе її в бій. Дійти до його табору — означає переступити поріг простої муштри ополченця й бути готовим до виснажливих особливих доручень, потрібних, щоб зібрати рідкісні ремісничі реагенти по всьому Калімдору."}},faq={{q="Хто такий Тун'ґрім Файрґейз?",a="Тун'ґрім Файрґейз — шанований орк-коваль, що отаборився на скелястому хребті трохи на схід від Перехрестя в Пустках. Він кує на замовлення грізні обладунки для воїнів Орди, які довели свою доблесть у небезпечних випробуваннях.",al={"хто такий тун'ґрім","тун'ґрім лор","тун'ґрім файрґейз"}},{q="Чому Руґа Рейджтотем посилає мене до нього?",a="Руґа Рейджтотем бачить, що, вистоявши проти сілітидів у південних Пустках, ви переросли прості випробування. Він посилає вас до Тун'ґріма, щоб майстер-коваль винагородив вашу службу Орді, викувавши особливий обладунок.",al={"чому говорити з тун'ґрімом","чому руґа посилає"}},{q="Де знайти табір Тун'ґріма?",a="Тун'ґрім отаборився на високих кручах на схід від Перехрестя в Пустках, звідки видно суху савану.",al={"де тун'ґрім","місце тун'ґріма","знайти тун'ґріма файрґейза"}},{q="Що буде після розмови з Тун'ґрімом?",a="Зустріч із Тун'ґрімом відкриває ланцюжок завдань про Жорстокий обладунок, що веде воїнів у далекі краї по міцні матеріали, як-от димчасті залізні зливки й залізні бруски, щоб викувати кольчугу на замовлення.",al={"наступне завдання після тун'ґріма","чого хоче тун'ґрім"}},{q="Чи доступне це завдання всім класам?",a="Ні. Це завдання й увесь пов'язаний із ним ланцюжок про обладунок — частина бойового вишколу лише для воїнів Орди.",al={"чи не воїни можуть це","чи лише для воїнів"}},{q="Яке випробування треба пройти перед цією зустріччю?",a="Перед цим дорученням воїни мусили вирушити в південні Пустки й пройти Випробування на Полі Велетнів, зібравши вусики сілітидів, що ще сіпаються, щоб довести свою бойову витривалість.",al={"передумова","що я робив перед цим"}}},fp="20,365,21.456.0,19.360.0,26.226.0,39.239.0,34.116.0,43.192.0,39.124.0,44.189.0"}
P.entries["quest:183"] = {n="Мисливець на вепрів",s="Мисливець на вепрів — раннє доручення від дворфа-мисливця Таліна Кіная в Долині Холодного Хребта. Сплеск місцевої популяції скельних вепрів зробив ліси надто небезпечними, і молодим новобранцям доручають винищити зухвалих звірів, щоб досвідчені мисливці могли спокійно йти по сліду.",h="Мисливець на вепрів — раннє доручення від дворфа-мисливця Таліна Кіная в Долині Холодного Хребта.",kw={"мисливець на вепрів","талін кінай","скельні вепри","вепр","долина холодного хребта","анвілмар","полювання"},ang={["class:Hunter"]="Талін Кінай утілює пряме дворфійське ставлення до вистежування: тримайте приціл твердо, шануйте звірів і розчищайте хащі, коли дичина стає надто ворожою.",["race:Dwarf"]="Жити в горах — означає ділити землю з лютою звіриною. Винищити войовничих скельних вепрів довкола Анвілмара — обряд посвяти для кожного молодого дворфа, що робить перші кроки за межі кузні.",["race:Gnome"]="Для гномів-біженців, що щойно прибули з Гномреґану, зустріч із лютими дикими вепрами Дун Мороґу — суворе, практичне знайомство з життям у суворому дворфійському краї."},sec={{t="Переповнена долина",b="Долина Холодного Хребта зазвичай тихий, захищений навчальний майданчик для молодих горян і вчених Айронфорджа. Та в суворому зимовому кліматі звірина часто стає неспокійною й надто численною. Талін Кінай, досвідчений мисливець, що стоїть біля Анвілмара, помічає, що зухвалі малі скельні вепри розплодилися так швидко, що становлять справжню загрозу для кожного, хто блукає засніженими стежками."},{t="Доглядаючи сніги",b="Полювання — наріжний камінь дворфійського життя: воно дає м'ясо, шкуру й необхідну практику польового ремесла. Та коли дичина стає напастю, що нападає, щойно побачить, треба винищити зайве, щоб відновити рівновагу. Прорідивши скельних вепрів на схилах долини, молоді шукачі пригод доводять свою бойову готовність і дають місцевим мисливцям простір для їхнього ремесла, щоб ті не були задавлені кількістю."}},faq={{q="Хто такий Талін Кінай?",a="Талін Кінай — дворф-мисливець, що стоїть у Долині Холодного Хребта біля Анвілмара. Днями він вистежує дичину на снігу й допомагає навчати молодих шукачів пригод, як на ділі позбуватися ворожих звірів.",al={"талін кінай","хто дає мисливця на вепрів","нпц мисливець на вепрів"}},{q="Чим так допікають скельні вепри?",a="Малих скельних вепрів у Долині Холодного Хребта незвично розплодилося, і вони без жодної причини кидаються на кожного, кого побачать. Через таку кількість звичайні мандри й полювання стали для місцевих небезпечними.",al={"чому вбивати вепрів","проблема вепрів холодного хребта","чим небезпечні вепри"}},{q="Де водяться скельні вепри?",a="Малі скельні вепри никають відкритими засніженими рівнинами й рідколіссям довкола Анвілмара по всій Долині Холодного Хребта.",al={"де вепри","місце скельних вепрів","мапа скельних вепрів"}},{q="Чи пов'язане це завдання з більшою загрозою в долині?",a="Ні. На відміну від навали трогів, що непокоїть дворфійські застави, це завдання — просто впорядкування місцевої живності, щоб стежки були безпечні, а Талін міг полювати спокійно.",al={"чи є наступне завдання","ланцюжок мисливця на вепрів","історія за вепрами"}},{q="Чим скельні вепри пристосовані до Дун Мороґу?",a="Скельні вепри — витривалі товстошкірі свині, створені, щоб витримувати морози Дун Мороґу. Агресивна вдача й гострі ікла дають їм змогу добувати поживу з мерзлої землі й відбиватися від гірських хижаків.",al={"лор скельних вепрів","вепри дворфів","дика природа дун мороґу"}},{q="Чому Талін Кінай не вб'є вепрів сам?",a="Талін зауважує, що агресивних вепрів так багато, що його неквапливі полювання стали неприємно небезпечними. Тож він залучає завзятих новачків, що проходять через Анвілмар, щоб ті проріджили стадо й він міг повернутися до звичного вистежування.",al={"чому талін потрібна допомога","талін лінивий","чому талін сам не полює"}}},fp="15,279,16.412.0,17.384.0,21.214.0,38.203.0,34.120.0,57.168.0,43.215.0,49.224.0"}
P.entries["quest:1838"] = {n="Жорстокий обладунок",s="«Жорстокий обладунок» — обряд посвяти для воїнів Орди під наглядом майже сліпого коваля Тун'ґріма Файрґейза на півночі Пусток. Прагнучи викувати обладунок, гідний молодого звитяжця, Тун'ґрім посилає досвідчених воїнів у далекі краї по рідкісні реагенти й екзотичні плавильні присадки. Виконавши вказане в його сувої, воїн дає почин куванню цілого комплекту жорстокого бойового спорядження.",h="«Жорстокий обладунок» — обряд посвяти для воїнів Орди під наглядом майже сліпого коваля Тун'ґріма Файрґейза...",kw={"жорстокий обладунок","тун'ґрім файрґейз","жорстока кольчуга","порошковий азурит","закопчений залізний злиток","воїн"},ang={["class:Warrior"]="Це завдання — визначальна віха для воїнів Орди: вони доводять свою доблесть і витривалість на кількох континентах, щоб заслужити бойовий обладунок, викуваний на замовлення.",["faction:Horde"]="Комплекти жорстокого обладунку — свідчення єдності Орди: вони поєднують окремі ремісничі традиції ковалів-орків, тауренів, тролів і Відступників в одне бойове спорядження.",["profession:Blacksmithing"]="Сувій Тун'ґріма показує передову металургійну алхімію: закопчене залізо, порошковий азурит і флогістон підносять звичайне плавлення заліза на новий рівень."},sec={{t="Поклик майстра",b="На скелястих пагорбах півночі Пусток старий оркський коваль Тун'ґрім Файрґейз уважно прислухається до вітрів війни. Хоч його зір слабне й затьмарюється, у кузні йому досі немає рівних. Почувши чутки про воїна, чия сила й доблесть переважають звичайних солдатів, Тун'ґрім вирішує викувати міцну кольчугу, що витримає найзапекліші сутички Калімдору й Східних Королівств."},{t="Пошуки через континенти",b="Щоб викувати обладунок такого ґатунку, звичайної руди замало. Насилу, при світлі вогню, слабкими очима Тун'ґрім пише точний сувій із переліком складників для основи — нагрудника. Потрібні звичайне очищене залізо, рідкісні закопчені залізні злитки, які носять кобольди-копачі, порошковий азурит, який добувають рудокопи за морем, і пляшечка мінливого флогістону. Лише воїн, готовий витримати випробування в далеких краях, може сподіватися побачити цей обладунок викуваним."},{t="Перший удар молота",b="Доставка цих рідкісних припасів — лише початок задуму Тун'ґріма. Прийнявши матеріали й розпаливши горно, щоб викувати Жорстоку Кольчугу, старий коваль визнає, що один майстер не завершить такого честолюбного задуму. Щоб створити повний комплект, треба покликати вправних майстрів з інших народів Орди — тауренського майстра шоломів, троля-майстра рукавиць і майстриню-нежить, що кує поножі за морем."}},faq={{q="Хто такий Тун'ґрім Файрґейз?",a="Тун'ґрім Файрґейз — шанований орк-коваль, ветеран, що живе на пагорбі над північними Пустками. Хоча зір його підводить, біля ковадла чуття в нього гостре, і він кує на замовлення могутні бойові обладунки для воїнів Орди, які прославилися доблесними вчинками.",al={"хто такий тун'ґрім","тун'ґрім файрґейз лор","історія тун'ґріма"}},{q="Що таке Жорстокий обладунок?",a="Жорстокий обладунок — знаний комплект загартованої в боях кольчуги, створений саме для бувалих воїнів Орди. Його кують спільними зусиллями ковалів Орди, і кожна частина вимагає небезпечних подорожей по рідкісні алхімічні реагенти, очищені руди й давні прийоми.",al={"що таке жорстокий обладунок","лор комплекту жорстокого обладунку","ланцюжок обладунку воїна"}},{q="Навіщо Тун'ґрімові такі незвичні складники?",a="Звичайне залізо надто крихке, щоб витримати важкі удари, яких зазнає боєць на передовій. Незвичні реагенти, як-от азуритовий порошок, димчасті залізні зливки й нестійкий флогістон, слугують флюсом і засобами гартування, і Тун'ґрім наділяє метал неймовірною стійкістю й міцністю.",al={"навіщо порошок азуриту","навіщо флогістон","для чого реагенти"}},{q="Чи кує Тун'ґрім увесь комплект сам?",a="Ні. Тун'ґрім сам кує головну частину — кольчугу, а по відповідні шолом, рукавиці й поножі посилає воїна до інших майстрів Орди, зокрема до Орма Стоунгуфа, Ула'елека й Велори Найтлі.",al={"чи тун'ґрім кує все сам","хто кує частини жорстокого обладунку"}},{q="Куди веде цей ланцюжок завдань далі?",a="Це випробування веде просто до кування Жорстокої Кольчуги й водночас відкриває шлях до ковалів у Тандер Блафі, Селі Сен'джин і Андерсіті, щоб зібрати решту жорстоких бойових обладунків.",al={"що після жорстокого обладунку","продовження жорстокого обладунку"}},{q="Чому воїнові доводиться мандрувати так далеко по ці матеріали?",a="Це випробування — і перевірка бойової завзятості, і урок кмітливості. Щоб заслужити обладунок від майстра, воїн мусить пробиратися ворожими землями, спускатися в небезпечні копальні й добувати складники, до яких звичайним людям не дотягтися.",al={"чому їхати до східних королівств","чому стільки матеріалів"}}},fp="12,365,18.438.0,26.474.0,30.423.1,26.284.0,21.277.0,49.286.0,44.234.1,38.221.1,61.236.0"}
P.entries["quest:1839"] = {n="Ула'елек і Жорстокі Латні Рукавиці",s="Це завдання веде молодих воїнів Орди з висот Пусток назад до узбережжя Дуротару. За дорученням коваля Тун'ґріма Файрґейза ви маєте розшукати майстра з Темного Спису Ула'елека в Селі Сен'джин, щоб викувати свої Жорстокі Латні Рукавиці.",h="Це завдання веде молодих воїнів Орди з висот Пусток назад до узбережжя Дуротару.",kw={"ула'елек","жорстокі латні рукавиці","село сен'джин","тун'ґрім файрґейз","темний спис","воїн"},ang={["class:Warrior"]="Ланцюжок завдань про жорстокий обладунок — важливий обряд посвяти для воїнів Орди, що знаменує їхнє перетворення на загартованих у боях звитяжців передової.",["faction:Horde"]="Спільна праця оркських ковалів-майстрів у Пустках і тролів-ковалів у Дуротарі показує співпрацю, що скріплює молодий союз Тралла.",["race:Troll"]="Відвідини Ула'елека підкреслюють внесок племені Темного Спису у воєнні зусилля Орди — вправним ковальством і злагодою з духами."},sec={{t="Подорож до узбережжя",b="Довівши свою доблесть по всіх Пустках і взявшись збирати комплект жорстокого обладунку, воїни вирушають на схід за вказівкою Тун'ґріма Файрґейза. Старий оркський коваль не кує кожну частину сам на своїй гірській кручі — він покладається на мережу вправних майстрів по всіх землях Орди. Щоб викувати важкі латні рукавиці для звитяжця, що росте в силі, він посилає бійців до скелястих південних берегів Дуротару."},{t="Очі лоа",b="У Селі Сен'джин серед своїх родичів із Темного Спису працює троль-бронник Ула'елек. Він аж ніяк не заскочений: Ула'елек розповідає, що Тун'ґрім уже передав звістку про ваші звершення, — а головне, самі духи бачили ваші перемоги в бою. Для воїна, що здобуває місце серед добірних бійців Орди, майстерність і визнання духів ідуть пліч-о-пліч."}},faq={{q="Хто дає завдання «Ула'елек і Жорстокі Латні Рукавиці»?",a="Це завдання дає Тун'ґрім Файрґейз — шанований орк-бронник, що живе в горах над Пустками.",al={"хто дає завдання","хто починає ула'елек і жорстокі рукавиці","завдання тун'ґріма файрґейза"}},{q="Де знайти Ула'елека?",a="Ула'елек перебуває в Селі Сен'джин на південному узбережжі Дуротару.",al={"місце ула'елека","де ула'елек","ула'елек сен'джин"}},{q="Що таке комплект Жорстокого обладунку?",a="Жорстокий обладунок — комплект кольчужних і латних обладунків на замовлення, створений саме для бувалих воїнів Орди десь тридцятого рівня; його кують союзні ковалі по всьому Калімдору.",al={"жорстокий обладунок","що таке жорстокі рукавиці","обладунок воїна тридцятого рівня"}},{q="Що буде, коли дістанешся Ула'елека?",a="Привітавшись і віддавши належне вашим бойовим звершенням, Ула'елек доручить вам зібрати незвичні матеріали для Жорстоких Латних Рукавиць — почати доведеться з копит сатирів.",al={"наступне завдання","після розмови з ула'елеком","завдання копит сатирів"}},{q="Чому Тун'ґрім посилає вас до троля-бронника?",a="Тун'ґрім розподіляє кування Жорстокого обладунку між найкращими вузькими майстрами Орди, а рукавиці довіряє ремісникам з Темного Спису, як-от Ула'елеку.",al={"чому ула'елек","чому йти до села сен'джин","троль-коваль жорстокий обладунок"}},{q="Чи мають гравці Альянсу схоже завдання?",a="Воїни Альянсу проходять схоже бойове випробування, щоб здобути власний обладунок для свого класу, але ланцюжок про Жорстокий обладунок і робота Ула'елека — лише для Орди.",al={"жорстокі рукавиці альянсу","аналог для альянсу"}}},fp="33,247,22.423.0,19.383.0,54.108.0,26.87.0,29.179.0,37.185.0,50.160.0,53.176.0"}
P.entries["quest:184"] = {n="Грамота Фурлброу",s="«Грамота Фурлброу» — викрадений документ на землю, який носять при собі злодії Дефіасу в Лісі Елвінн. Повернувши його вигнаному Фермерові Фурлброу біля кордону Вестфолу, ви даєте подружжю-втікачам єдину надію колись повернути свою відібрану садибу.",h="«Грамота Фурлброу» — викрадений документ на землю, який носять при собі злодії Дефіасу в Лісі Елвінн.",kw={"грамота фурлброу","фермер фурлброу","верна фурлброу","ліс елвінн","братство дефіас","вестфол"},ang={["class:Paladin"]="Повертати вкрадені грамоти знедоленим біженцям — означає виконувати святі обітниці: боронити беззахисних і нести справедливість у беззаконні прикордонні землі.",["faction:Alliance"]="Лихо родини Фурлброу показує, що корона Стормвінда не здатна захистити своїх платників податків поза укріпленими мурами столиці."},sec={{t="Підказка на вкраденому папері",b="У сутичках із розбійниками Дефіасу в Лісі Елвінн мандрівники нерідко знаходять зім'яту грамоту на землю з підписами Теодора й Верни Фурлброу. На звороті пергаменту корявий почерк розкриває задум розбійників: силою вигнавши літнього фермера з його землі, вони перенесли документ через річку до Елвінну, щоб за його зразком підробляти грамоти на інші захоплені землі. Нашкрябана записка також згадує, що Фурлброу бачили на дорозі просто за кордоном — вони застрягли там зі зламаним возом."},{t="Лихо фермерів Вестфолу",b="Утрата родини Фурлброу — символ трагедії, що охопила Вестфол. Армії Стормвінда немає, ресурси королівства виснажені, і Братство Дефіас вигнало десятки родин із прадідівської землі, силою й юридичними хитрощами зміцнюючи владу над житницею королівства. Хоч Теодор і Верна покидають ферму заради власної безпеки, законна грамота зберігає за ними єдине право на землю проти бунтівників — на випадок, якщо в краї колись знову запанує лад."}},faq={{q="Де знайти цю грамоту?",a="Грамота випадає з різних членів Братства Дефіас, що ховаються на півдні й заході Лісу Елвінн, — скажімо, біля Пристані Джерода чи в місцевих таборах.",al={"де випадає грамота","як отримати грамоту фурлброу","звідки грамота"}},{q="Де шукати Фермера Фурлброу?",a="Фермер Фурлброу та його дружина Верна застрягли біля зламаного воза на головному шляху одразу на в'їзді у Вестфол, невдовзі після мосту, що веде на захід від Лісу Елвінн.",al={"місце фурлброу","куди здати грамоту фурлброу","де фермер"}},{q="Навіщо грамота знадобилася Дефіас?",a="Записка на звороті показує, що бандити збиралися взяти справжню грамоту Фурлброу за зразок, щоб підробляти права на інші володіння в краю й закріпити свою владу над захопленими фермами фальшивими паперами.",al={"чому бандити вкрали грамоту","навіщо дефіас грамоти"}},{q="Чи повертаються Фурлброу на свою ферму?",a="Найближчим часом — ні. Подружжя тікає з краю через беззаконня й напади бандитів. Проте з грамотою в руках вони зможуть законно повернути собі землю, якщо у Вестфолі колись настане спокій.",al={"чи фурлброу повертаються додому","що буде з фермою фурлброу"}},{q="Чому Стормвінд не захищає ці ферми?",a="Стормвінд паралізований раптовим зникненням короля Варіана Рінна й внутрішньою політичною напругою. Королівські сили зосереджені на столиці, тож окраїнні землі на кшталт Вестфолу мусять самі боронитися від Братства Дефіас, що дедалі міцнішає.",al={"чому немає вартових у вестфолі","чому стормвінд ігнорує вестфол"}},{q="Як у цьому завданні пов'язані Елвінн і Вестфол?",a="Це завдання — ниточка, що веде шукачів пригод з Лісу Елвінн за річку, у Вестфол, і показує, як глибоко мережа Дефіас сягає в серцевинні землі королівства.",al={"чому грамота в елвінні","зв'язок між зонами"}}},fp="15,251,22.516.0,32.511.0,26.182.0,25.170.0,52.223.0,42.207.0,43.256.0,65.189.0"}
P.entries["quest:1840"] = {n="Орм Стоунгуф і Жорстокий Шолом",s="Це доручення скеровує молодих воїнів Орди до Тандер Блафа, до майстра-коваля Орма Стоунгуфа. Його рекомендує Тун'ґрім Файрґейз: Орм володіє особливим ремеслом, потрібним, щоб викувати Жорстокий Шолом.",h="Це доручення скеровує молодих воїнів Орди до Тандер Блафа, до майстра-коваля Орма Стоунгуфа.",kw={"орм стоунгуф","жорстокий шолом","тун'ґрім файрґейз","воїн","коваль","тандер блаф","жорстокий обладунок"},ang={["class:Warrior"]="Це завдання знаменує перехід до важкого захисту голови й відсилає воїнів до одного з найкращих майстрів-ковалів Орди.",["faction:Horde"]="Це завдання показує співпрацю між орками — майстрами зброї в Пустках — і ремісниками-тауренами на висотах Тандер Блафа."},sec={{t="Рекомендація в залізі",b="Довівши свою гартованість і зібравши частини Жорстокого Обладунку в Пустках, воїни вирушають вище — до міста на столових горах, Тандер Блафа. Тун'ґрім Файрґейз, сам вправний зброяр, визнає межі свого вміння й відсилає своїх чемпіонів до Орма Стоунгуфа. Ремесло Орма славиться на весь Калімдор, надто ж його вміння виготовляти міцні бойові шоломи з рідкісних трофеїв, здобутих у лютих звірів."},{t="Майстер біля ставка",b="Орм живе й працює на високих кручах Малгору, біля спокійних вод під височенним центральним тотемом міста. Коли приходить воїн із вісткою від Тун'ґріма, Орм відкладає буденну роботу, щоб обговорити вимогливі складники, потрібні для шолома, справді гідного передової Орди."}},faq={{q="Хто такий Орм Стоунгуф?",a="Орм Стоунгуф — вправний таурен-бронник, що живе в Тандер Блафі. Відомий своєю майстерністю, він допомагає воїнам, яких посилає Тун'ґрім Файрґейз, виготовити особливий бойовий шолом.",al={"орм стоунгуф","хто такий орм"}},{q="Де знайти Орма Стоунгуфа?",a="Він у самому серці Тандер Блафа — стоїть біля водойми неподалік величезного центрального тотема міста.",al={"де орм","місце орма стоунгуфа","знайти орма"}},{q="Чому Тун'ґрім Файрґейз посилає до Тандер Блафа?",a="Тун'ґрім може викувати нагрудник та інші частини Жорстокого комплекту, але визнає, що саме Орм Стоунгуф має точні знання, потрібні, щоб зробити Жорстокий Шолом.",al={"чому тандер блаф","чому до орма"}},{q="Що таке Жорстокий Шолом?",a="Жорстокий Шолом — знаковий шолом, який кують для воїнів Орди, що здобули звання ветеранів. Для нього потрібні небезпечні матеріали, здобуті зі звірів по всьому Калімдору.",al={"завдання жорстокий шолом","що таке жорстокий шолом"}},{q="Що Орм просить далі?",a="Щойно ви поговорите з Ормом, він посилає вас по потрібні для шолома мисливські трофеї — почати доведеться з полювання на химер у дикій глушині, щоб здобути ріг химери.",al={"наступне завдання","після орма стоунгуфа","завдання рога химери"}},{q="Чи може це завдання взяти будь-який клас?",a="Ні. Цей ланцюжок завдань — лише для воїнів, які досить просунулися в бойовому вишколі й виконали перші завдання Тун'ґріма щодо обладунку.",al={"чи лише для воїнів","хто може виконати завдання"}}},fp="33,213,24.405.0,23.328.0,21.185.0,33.119.0,54.180.0,24.168.0,27.164.1,30.146.0"}
P.entries["quest:1841"] = {n="Велора Найтлі і Жорстокі Поножі",kw={"велора найтлі","жорстокі поножі","андерсіті","торговий квартал","тун'ґрім файрґейз","воїн"},ang={["faction:Horde"]="Ланцюжок завдань про жорстокий обладунок скріплює молоду Орду: оркам, тролям і тауренам із Калімдору доводиться напряму співпрацювати з майстрами-Відступниками у Східних Королівствах.",["race:Undead"]="Велора Найтлі показує, що Відступники зберегли вишукані культурні вміння й мистецьку спадщину загиблого королівства Лордерон."},sec={{t="Подорож за море",b="Довівши свій гарт старому ковалеві Тун'ґрімові Файрґейзу на його сторожовій кручі в Пустках, воїни беруться збирати славетний жорстокий обладунок. Тун'ґрім не може викувати весь комплект сам і скеровує молодих звитяжців до вправних союзників по всій Орді. По поножі він посилає їх на схід за Велике море, до підземного королівства Відступників, — до майстрині, чию роботу шанували задовго до падіння північних людських королівств."},{t="Мистецтво Велори Найтлі",b="До своєї загибелі під час навали Погибелі на північ Велора Найтлі славилася як одна з найкращих бронниць Королівства Лордерон. Хоч вона втратила смертне життя, а її батьківщину спаплюжено, смерть не применшила її металургійної майстерності. Тепер вона працює в Торговому Кварталі Андерсіті, обертає своє давнє людське ремесло на допомогу воїнам Орди й зберігає сухий, моторошний дотеп щодо свого стану нежиті."}},faq={{q="Хто така Велора Найтлі?",a="Велору Найтлі колись славили як одну з найкращих бронниць королівства Лордерон. Після Третьої війни й воскресіння серед Відступників вона перебралася до Торгового Кварталу Андерсіті, де й далі займається ковальством на користь Орди.",al={"лор велори найтлі","хто така велора","коваль відступників велора"}},{q="Чому Тун'ґрім посилає мене до Андерсіті?",a="While Thun'grim Firegaze oversees your training in the Barrens, crafting the full Brutal Armor set requires specialized artisans across the Horde. He recognizes Velora's unmatched reputation for armor and dispatches you to Lordaeron to commission the legguards directly.",al={"чому до андерсіті","завдання тун'ґріма андерсіті","воїн з пусток до андерсіті"}},{q="Де в Андерсіті знайти Велору Найтлі?",a="Велора Найтлі працює біля горнів у Торговому Кварталі Андерсіті, серед інших майстрів і ковалів, що служать Леді Сильвані Віндраннер.",al={"місце велори найтлі","де велора найтлі","знайти велору найтлі"}},{q="Що далі після розмови з Велорою Найтлі?",a="Velora asks you to collect shinbones from Dragonmaw orcs in the Wetlands so she can use them to craft your Brutal Legguards.",al={"наступне завдання після велори","завдання гомілкових кісток","чого хоче велора"}},{q="Чи жартує Велора про те, що вона нежить?",a="Так. Коли ви здолаєте шлях і заговорите з нею, вона сухо жартує, хто для кого кує обладунок — вона для вас чи навпаки, — і зауважує, що почуття гумору втратила приблизно тоді ж, коли втратила нюх і перестала дихати.",al={"жарти велори","діалог коваля-нежиті","гумор велори"}},{q="Чи Жорстокий обладунок лише для воїнів?",a="Так, випробування Жорстокого обладунку — зокрема й пошуки Велори Найтлі заради поножів — це особливий обряд бойового зростання лише для воїнів Орди, що здобувають досвід.",al={"чи інші класи жорсткий обладунок","жорстокий обладунок лише для воїнів"}}},fp="38,330,24.463.0,29.458.0,21.266.0,40.270.0,48.168.0,43.124.1,49.242.0,34.197.0"}
P.entries["quest:1842"] = {n="Копита сатирів",s="«Копита сатирів» — завдання від троля-ремісника Ула'елека з Села Сен'джин. Щоб викувати пару наділених силою жорстоких латних рукавиць, воїни мають вирушити на північ, в Ашенваль, полювати на сатирів і здобути їхні магічно набряклі, нерозколоті копита.",h="«Копита сатирів» — завдання від троля-ремісника Ула'елека з Села Сен'джин.",kw={"копита сатирів","сатири","ашенваль","ула'елек","сен'джин","рукавиці","воїн"},ang={["class:Warrior"]="Це завдання — частина обряду поступу воїна, що випробовує його бойову стійкість проти хитрих демонічних засідників заради особистих обладунків.",["faction:Horde"]="Це полювання виводить воїнів Орди з посушливих рівнин Дуротару вглиб спірних земель нічних ельфів в Ашенвалі.",["race:Troll"]="Методи Ула'елека показують прагматичну вдачу ремесла Темного Списа: висмоктувати сиру сутність із полеглих магічних ворогів замість покладатися лише на звичайне ковальство."},sec={{t="Приборкання оскверненої сутності",b="Щоб викувати обладунки, здатні змагатися з найжорстокішими силами Калімдору, ремісник Темного Списа Ула'елек дивиться далі за буденне залізо та шкіру. Він посилає майбутніх воїнів на північ, у давні ліси Ашенвалю, де в тутешніх ковенах сатирів гніздиться невигасла демонічна скверна."},{t="Набряк магії Ашенвалю",b="За словами Ула'елека, сатири північно-східного Ашенвалю живляться, висмоктуючи приховану чистоту лісу й обертаючи її на мерзенну силу. Ті демони, що найглибше нажерлися цього позиченого життя, мають неприродно набряклі копита, які втратили природну розколину. Ула'елек має намір витягти цю зосереджену магічну енергію і вплести її просто в рукавиці, які кує."}},faq={{q="Навіщо Ула'елеку копита сатирів?",a="Копита потрібні Ула'елеку, щоб наснажити жорстокі рукавиці, які він кує. Він хоче витягти зосереджену лісову магію, яку сатири висмоктали, спотворили й зібрали у своїх роздутих ногах.",al={"навіщо копита сатирів","призначення копит","для чого копита"}},{q="Де водяться сатири?",a="Вони живуть на північному сході Ашенвалю, гніздяться серед осквернених давніх руїн і живляться рештками магічної енергії глибокого лісу.",al={"де сатири","місце сатирів","де взяти копита сатирів"}},{q="Чим особливе нерозщеплене копито?",a="Відсутність розщепу свідчить, що сатир наситився надмірною кількістю чистої магії Ашенвалю, і його кінцівки розпухли від украденої сили.",al={"лор нерозщепленого копита","чому нерозщеплене","набряклі копита"}},{q="Хто такий Ула'елек?",a="Ула'елек — вправний троль-бронник з Темного Спису, що живе в Селі Сен'джин на півдні Дуротару й допомагає воїнам виготовляти спорядження для випробувань.",al={"хто такий ула'елек","хто дає завдання","троль у сен'джині"}},{q="Який обладунок кує Ула'елек?",a="Він збирається викувати Жорстокі Латні Рукавиці — важкий захист для рук, сповнений украденої магічної сили, для воїнів Орди, що набираються досвіду.",al={"які жорстокі рукавиці","завдання рукавиць","нагорода обладунок"}},{q="Чи служать тутешні сатири Палаючому Легіону?",a="Так. Сатири — давні нічні ельфи, перетворені демонічними угодами, і їхні спільноти, що досі ховаються в лісах Калімдору, й далі поширюють скверну на службі демонічним силам.",al={"вірність сатирів","чи сатири легіон"}}},fp="12,253,28.286.0,30.413.0,36.195.0,27.145.0,36.161.0,16.157.0,31.140.0,44.180.0"}
P.entries["quest:1843"] = {n="Жорстокі Латні Рукавиці",s="«Жорстокі Латні Рукавиці» — вінець ремесла майстра для загартованих воїнів Орди. Коли рідкісні складники зібрано в далеких землях, ремісник Ула'елек виготовляє грізну пару рукавиць, покликаних принести честь і майстру, і носієві.",h="«Жорстокі Латні Рукавиці» — вінець ремесла майстра для загартованих воїнів Орди.",kw={"жорстокі латні рукавиці","рукавиці","ула'елек","воїн","обладунки","ремесло","дуротар"},ang={["class:Warrior"]="Ці рукавиці знаменують перехід воїна до дисциплінованого бойового лідерства і слугують надійною частиною захисного спорядження, викуваного саме для важкого ближнього бою.",["faction:Horde"]="Ремесло Орди тримається на тривкій традиції та бойовій гордості, щоб чемпіони несли в бій духовну вагу й честь своїх майстрів."},sec={{t="Шедевр ремісника",b="Викувати обладунок, гідний загартованого воїна передової, — для ремісників Орди більше ніж просте металоробство: це духовна справа. Ула'елек, ремісник із Дуротару, вкладає свій рід і вміння в ці жорстокі латні рукавиці. Використовуючи загартовані трофеї, здобуті з небезпечних супротивників, він створює обладунок, що витримує люті удари й водночас посилює наступальну міць носія."},{t="Честь предків",b="В орчих і тролячих традиціях добра зброя й обладунки несуть у бій престиж кузні та дух майстра. Вручаючи воїну готові рукавиці, Ула'елек довіряє йому спадщину своїх предків. Від чемпіона, який носить їх у бою, чекають відваги, бойової дисципліни та сили, гідних цієї майстерності."}},faq={{q="Хто такий Ула'елек?",a="Ула'елек — майстер з Дуротару, що допомагає воїнам Орди здобути добротні обладунки на замовлення. Він вимагає незвичних матеріалів, щоб його ковальство шанувало і ремесло, і традиції його предків.",al={"ула'елек","хто дає жорстокі рукавиці","хто дає завдання"}},{q="Навіщо для цих рукавиць знадобилися копита сатирів?",a="Роздуті нерозщеплені копита сатирів зберігають силу, яку ті висмоктали з магії Ашенвалю. Ула'елек витягає цю силу з копит і вкладає її в роботу, тож рукавиці сповнені могутньої магії.",al={"чому копита сатирів","частини сатирів","які матеріали"}},{q="Що для Ула'елека означає, коли хтось носить ці рукавиці?",a="Для Ула'елека ці рукавиці — вершина його майстерності. Довірити їх гідному воїнові — велика честь для його ремесла й предків, що пов'язує його працю з бойовими перемогами Орди.",al={"честь предків","честь ула'елека"}},{q="Де відбувається це завдання?",a="Кування завершується в Дуротарі — посушливому серці земель орків і тролів Темного Спису, де Ула'елек оглядає здобуті матеріали й вручає готовий обладунок.",al={"місце","де здати жорстокі рукавиці"}},{q="Чи це випробування для всіх шукачів пригод?",a="Цей шлях прокладено саме для воїнів передової, які довели свою витривалість і бойову відданість, — він знаменує їхнє зростання до досвідченіших бойових ролей в Орді.",al={"чи лише для воїнів","вимога до класу"}},{q="Що далі після отримання рукавиць?",a="Вручення рукавиць завершує це випробування, і воїн, повністю спорядившись, готовий зустріти більші загрози на розтерзаних війною полях битв Азерота.",al={"наступне завдання","продовження жорстоких рукавиць"}}},fp="16,262,25.416.0,15.367.0,16.212.0,49.203.0,52.214.0,32.168.0,43.180.0,41.182.0"}
P.entries["quest:1844"] = {n="Ріг химери",s="У межах воїнського обряду, що веде до створення Жорстокого Шолома, Орм Стоунгуф доручає молодому чемпіонові вирушити до спустошеної Обвугленої Долини. Там воїн має вполювати збожеволілу матір-химеру й здобути її загартований ріг — це водночас акт милосердя й доказ сили.",h="У межах воїнського обряду, що веде до створення Жорстокого Шолома, Орм Стоунгуф доручає молодому чемпіонові...",kw={"ріг химери","химера","обвуглена долина","орм стоунгуф","жорстокий шолом","гори кам'яного кігтя","воїн"},ang={["class:Warrior"]="Це випробування перевіряє вміння воїна вполювати самотніх звірів-ватажків у жорстоких краях і дає право носити Жорстокий Шолом.",["faction:Horde"]="Воїни Орди, що вирушають із Притулку Сонячної Скелі, заглиблюються в спірні нетрі Гір Кам'яного Кігтя, щоб викувати зброю для захисту Калімдору.",["race:Tauren"]="Орм Стоунгуф підходить до війни з шанобливістю тауренів, нагадуючи воїнам, що навіть у насильстві позбавити змученого звіра страждань означає вшанувати Земну Матір."},sec={{t="Випробування рішучості",b="Орм Стоунгуф готовий викувати для воїнів Орди легендарний Жорстокий Шолом, але бойова традиція вимагає, щоб власник спершу довів свою гартованість. Орм не просить просто металу чи монет: він вимагає доказу бойової вправності й готовності глянути в очі похмурим шрамам, які лишила по собі нищівна війна."},{t="Шрами Обвугленої Долини",b="Завдання веде воїнів у південно-західні краї Гір Кам'яного Кігтя, до попелястої пустки, відомої як Обвуглена Долина. Колись пишна й зелена, долина згоріла й обернулася на димну пустелю. Звірі, що вижили й блукають її вкритими сажею вирвами, покручені болем і люттю, — надто могутні химери, що в'ють гнізда серед мертвих дерев і пекучих парових джерел."},{t="Милосердя в бою",b="На думку коваля-таурена, вбивство матері-химери має дві мети. Воно дає загартований ріг, потрібний для шолома, а водночас кладе край мукам істоти. Здолавши матір-химеру, воїн стає і катом, і знаряддям милосердя для дикого духа, якого довело до божевілля знищення рідного дому."}},faq={{q="Хто такий Орм Стоунгуф?",a="Орм Стоунгуф — вправний таурен-коваль з Тандер Блафа, що допомагає бувалим воїнам Орди виготовляти знакові частини їхнього класового обладунку, зокрема Жорстокий Шолом.",al={"орм стоунгуф лор","хто такий орм стоунгуф","коваль тандер блафа орм"}},{q="Навіщо Ормові гальванізований ріг?",a="Гальванізований ріг — і міцна складова Жорстокого Шолома, і відчутний доказ того, що воїн має відвагу вистежити й здолати небезпечного хижака-ватажка в суворій місцевості.",al={"навіщо гальванізований ріг","чому гальванізований ріг","ріг для жорстокого шолома"}},{q="Що за химери живуть у Горах Кам'яного Кігтя?",a="Химери — великі двоголові крилаті створіння, корінні мешканці диких країв Калімдору, часто пов'язані з давніми святилищами нічних ельфів. Ті, що вижили в Обвугленій Долині, геть збожеволіли від вогню й руйнування своїх гніздовищ.",al={"химери кам'яного кігтя","лор химер","що таке химери"}},{q="Яке місце це завдання посідає в навчанні воїна?",a="Десь на тридцятому рівні воїнів Орди посилають до майстрів на кшталт Орма Стоунгуфа проходити небезпечні випробування. Подолавши їх, вони можуть носити важкий шипастий Жорстокий обладунок, створений для поборників на полі бою.",al={"ланцюжок жорстокого шолома воїна","воїн тридцятого рівня тандер блаф","лінія жорстокого обладунку"}},{q="Чому Орм подає полювання як милосердя?",a="Культура тауренів наголошує на гармонії з землею та її створіннями. Мешканці Обвугленої Долини безупинно страждають від спустошення свого краю, тож убити матріарха — значить позбавити змученого звіра нескінченних мук, а не безглуздо вбивати.",al={"чому милосердя для матріарха","звільнити її від мук"}}},fp="14,275,17.316.0,29.393.0,15.348.0,21.180.0,38.210.0,33.251.0,46.244.0,47.285.0"}
P.entries["quest:1845"] = {n="Жорстокий Шолом",s="«Жорстокий Шолом» — кульмінація важкого воїнського випробування, яке веде Орм Стоунгуф на Тандер Блафі. Зібравши рідкісні трофеї звірів по всьому Калімдору, молодий воїн отримує грізний рогатий шолом як свідчення своєї сили.",h="«Жорстокий Шолом» — кульмінація важкого воїнського випробування, яке веде Орм Стоунгуф на Тандер Блафі.",kw={"жорстокий шолом","орм стоунгуф","ріг химери","воїн","тандер блаф","земна мати","обряд посвяти"},ang={["class:Warrior"]="Цей обряд — важлива віха для воїнів Орди: він відкриває їм важкі обладунки, виготовлені з лютих звірів і благословенні досвідченими наставниками-ветеранами.",["faction:Horde"]="Випробування Жорстокого Обладунку гарантує, що чемпіони під стягом Орди мають ту фізичну витривалість і мисливську вправність, якої вимагають від них провідники.",["race:Tauren"]="Шолом, вручений у Тандер Блафі, відображає традицію тауренів перетворювати мисливські трофеї на захисне бойове спорядження під благодаттю Земної Матері."},sec={{t="Обряд воїна",b="Орм Стоунгуф — суворий коваль у Тандер Блафі, що проводить воїнів Орди крізь виснажливі обряди посвяти. Ці випробування вимагають доказів бойової спроможності й кидають учнів у небезпечні краї полювати на лютих звірів і здобувати рідкісні трофеї. Лише тих, хто відповідає суворим вимогам Орма, він приймає, щоб завершити їхній обладунок."},{t="Дар Земної Матері",b="Принісши Ормові Стоунгуфу рідкісний ріг химери, воїн доводить свою рішучість перед лицем дикої природи. На знак визнання Орм вручає йому Жорстокий Шолом — важкий, грізний латний шолом, створений, щоб ушанувати звіра й підсилити власника в бою на передовій. Вручаючи шолом, Орм призиває благословення Земної Матері й наперед тішиться більшими подвигами, які воїнові судилося звершити по всьому Азероту."}},faq={{q="Хто вручає Жорстокий Шолом?",a="Орм Стоунгуф, шанований таурен-коваль з Тандер Блафа, вручає Жорстокий Шолом воїнам Орди, які пройдуть його випробування.",al={"хто дає жорстокий шолом","нпц жорстокий шолом","завдання орма стоунгуфа"}},{q="Яке завдання треба виконати, перш ніж отримати шолом?",a="Треба пройти випробування «Ріг химери»: вполювати лютих звірів у дикій глушині й принести їхній ріг Ормові Стоунгуфу в Тандер Блаф.",al={"передумова жорстокого шолома","завдання рога химери"}},{q="Де перебуває Орм Стоунгуф?",a="Орм Стоунгуф стоїть біля водойми коло великого центрального тотема у високому місті на столових горах — Тандер Блафі.",al={"місце орма стоунгуфа","де орм стоунгуф"}},{q="Чому Орм Стоунгуф звертається до Земної Матері?",a="Як таурен, Орм шанує Земну Матір як творчиню й духовну охоронницю світу. Благословляючи її ім'ям готовий шолом воїна, він виявляє давню віру тауренів у те, що сила в бою має бути врівноважена духовною шанобою.",al={"чому земна мати","земна мати лор"}},{q="Чи відкрите це випробування для будь-якого шукача пригод?",a="Ні. Випробування та його нагороди з Жорстокого обладунку — лише для воїнів Орди, які доводять свою загартованість у класових завданнях.",al={"чи кожен може отримати жорстокий шолом","клас жорстокого шолома"}},{q="Яке значення має комплект Жорстокого обладунку?",a="Частини Жорстокого обладунку уособлюють шлях воїна від новобранця до добірного поборника Орди; їх кують з матеріалів, здобутих з найлютіших хижаків Калімдору.",al={"лор жорстокого обладунку","чому жорстокий шолом"}}},fp="11,259,16.365.0,27.412.0,27.130.0,53.168.0,31.105.0,46.254.0,37.127.0,49.188.0"}
P.entries["quest:1846"] = {n="Гомілкові кістки Драконячої Пащі",s="«Гомілкові кістки Драконячої Пащі» — завдання для воїнів Орди, яке дає зброярка Велора Найтлі в Андерсіті. Щоб викувати міцні Жорстокі Поножі, воїнів посилають у Багнокрай по надзвичайно товсті гомілкові кістки ворожих орків Драконячої Пащі.",h="«Гомілкові кістки Драконячої Пащі» — завдання для воїнів Орди, яке дає зброярка Велора Найтлі в Андерсіті.",kw={"гомілкові кістки драконячої пащі","велора найтлі","жорстокі поножі","драконяча паща","багнокрай","каз модан","воїн"},ang={["class:Warrior"]="Це випробування перевіряє і вашу фізичну витривалість у полі, і готовність збирати моторошні матеріали заради кращого обладунку.",["faction:Horde"]="Розбиваючи клан-ренегат Драконячої Пащі в Каз Модані, ви послаблюєте небезпечні рештки Старої Орди й додаєте сили героям нового союзу Тралла.",["race:Orc"]="Для орків, вірних Оргріммару, винищення нерозкаяних орків Драконячої Пащі — суворе нагадування про скверну в минулому їхнього народу й криваву ціну спокути.",["race:Undead"]="Те, як прагматично Велора Найтлі використовує людиноподібні рештки, — взірець мислення Відступників: будь-який доступний ресурс, хай який моторошний, можна обернути на зброю."},sec={{t="Моторошний каркас",b="Обладунок, гідний загартованого воїна передової, потребує незвичних матеріалів. Узявшись виготовити Жорстокі Поножі, зброярка-Відступниця Велора Найтлі вимагає опорної скоби з товстої, тривкої кістки. Замість звичайних звірів вона спрямовує молодих воїнів до орків Драконячої Пащі в Багнокраї: їхні щільні кістяки дають потрібну міцність, щоб витримати важкі удари в бою."},{t="Перевірка на злам",b="Здобути кістки Драконячої Пащі — лише половина справи. Велора велить воїнам власноруч перевіряти кожну кістку просто на місці: будь-який зразок, що ламається в голих руках, для кузні зовсім непридатний. Воїни мусять обнишпорити табори ренегатів серед скель Багнокраю, ламаючи слабкі кістки, доки вісім справді міцних не витримають випробування силою."}},faq={{q="Чому Велорі Найтлі потрібні саме гомілкові кістки орків?",a="Велорі потрібен щільний, товстий матеріал, щоб зробити з нього опорний каркас для Жорстоких Поножів. Вона вважає, що орки Драконячої Пащі з Багнокраю підходять якнайкраще: їхній важкий, потужний кістяк дає набагато більшу жорсткість, ніж звичайна дичина чи знайдені рештки.",al={"чому гомілкові кістки орків","чому кістки драконячої пащі","кістяний обладунок велори"}},{q="Чому воїни Орди можуть вільно полювати на орків Драконячої Пащі?",a="Рештки клану Драконячої Пащі, що засіли в Багнокраї, — ворожі ренегати, які чіпляються за темну спадщину Другої війни. Вони не визнають сучасної Орди Тралла, тож вважаються ворогами держави й законною здобиччю для шукачів пригод з Орди.",al={"чи драконяча паща в орді","чому битися з драконячою пащею","становище драконячої пащі в орді"}},{q="Де шукати орків Драконячої Пащі для цього завдання?",a="Вони живуть у Багнокраї, на південь від Аратійського нагір'я за Мостом Тандол. Воїни зазвичай полюють на них серед гірських круч біля Табору Анґерфанґ, на південний захід від головного північного шляху.",al={"місце драконячої пащі","де гомілкові кістки драконячої пащі","місце табору ангерфанґ"}},{q="Чому під час завдання стільки кісток ламається?",a="Для кування обладунку Велорі потрібні лише найщільніші кістки. За її настановами воїни перевіряють кожну кістку руками: та, що ламається від звичайної сили, надто крихка, щоб захистити ноги воїна в бою, і її викидають.",al={"зламані гомілкові кістки","чому кістки ламаються","перевірка міцної кістки"}},{q="Хто така Велора Найтлі?",a="Велора Найтлі — бронниця з Відступників, що працює в Андерсіті. Сувора, з моторошно сухим гумором і схильністю до похмурих жартів, вона допомагає воїнам Орди виготовляти особливе бойове спорядження для загартованих ветеранів.",al={"лор велори найтлі","хто така велора","збройник андерсіті"}},{q="Яку частину обладунку кують з цих кісток?",a="Зібрані кістки стають внутрішнім каркасом Жорстоких Поножів — міцних кольчужних поножів для воїнів Орди середнього рівня.",al={"нагорода за гомілкові кістки","навіщо гомілкові кістки","жорстокі поножі"}}},fp="19,266,19.437.0,18.377.0,55.285.0,56.245.0,44.222.0,51.239.0,21.229.0,44.141.0"}
P.entries["quest:1848"] = {n="Жорстока Кольчуга",s="«Жорстока Кольчуга» — завершення виснажливого обряду посвяти для воїнів Орди в Пустках. Зібравши рідкісні матеріали й довівши свій гарт у сутичках із небезпечними ворогами в різних краях, воїни приносять здобуте відлюдькуватому ковалеві Тун'ґрімові Файрґейзу. Натомість він викує міцну кольчугу, що витримає найзапекліші бої.",h="«Жорстока Кольчуга» — завершення виснажливого обряду посвяти для воїнів Орди в Пустках.",kw={"жорстока кольчуга","тун'ґрім файрґейз","жорстокий обладунок","воїн","ковальство","пустки"},ang={["class:Warrior"]="Жорстока Кольчуга — визначне досягнення для молодих воїнів Орди: вона знаменує перехід від зеленого новобранця до загартованого бійця в кольчузі, викуваній саме для нього.",["faction:Horde"]="Викувана з трофеїв, здобутих кров'ю в диких краях Калімдору, кольчуга відбиває головні чесноти Орди — бойову самостійність і силу.",["profession:Blacksmithing"]="Спостерігати за роботою Тун'ґріма — це урок традиційного оркського ковальства, де бойовий дух і стійкість вковують просто в сталь."},sec={{t="Шедевр коваля",b="На скелястих пагорбах півночі Пусток Тун'ґрім Файрґейз кує обладунки далеко не для кожного. Відлюдькуватий орк вимагає, щоб молоді воїни обійшли далекі краї й здобули міцні частини звірів, рідкісний метал і алхімічні реагенти, — і лише тоді він береться роздмухувати міхи. Готова кольчуга — не просто захисне спорядження, а незнищенна відзнака витривалості й гарту, яку впізнають бувалі бійці по всій Орді."},{t="Викувана в злигоднях",b="Доручення Тун'ґріма навмисно суворе. Справжня зброя й обладунок Орди мають від самого народження нести піт і кров свого власника. Вручаючи готову Жорстоку Кольчугу, коваль не сипле квітчастими похвалами — лише чекає, що обладунок проявить себе в жорстокому бою й повернеться з оповідями про кров і честь."}},faq={{q="Що таке Жорстока Кольчуга?",a="Жорстока Кольчуга — міцний нагрудник, викуваний на замовлення орком-ковалем Тун'ґрімом Файрґейзом. Це найвища нагорода для воїнів Орди, які доводять свою бойову вправність, збираючи рідкісні матеріали в кількох небезпечних краях.",al={"що таке жорстока кольчуга","завдання жорстокої кольчуги","хто кує жорстоку кольчугу"}},{q="Хто такий Тун'ґрім Файрґейз?",a="Тун'ґрім Файрґейз — відлюдний коваль-ветеран, що живе на гірському відрозі в північних Пустках, трохи на схід від шляху між Перехрестям і Оргріммаром. Він випробовує молодих воїнів і кує їм особливі обладунки, коли ті доведуть, що на них заслуговують.",al={"хто такий тун'ґрім","тун'ґрім файрґейз","де тун'ґрім"}},{q="Чому Тун'ґрім вимагає стільки зусиль, перш ніж викувати обладунок?",a="У традиції воїнів Орди труднощі важать не менше за бойову вправність. Тун'ґрім вважає, що добротна кольчуга змарнується на тому, хто не пролив власної крові й не тяжко трудився, щоб здобути рідкісні складники для її кування.",al={"чому збирати стільки матеріалів","вимоги жорстокого обладунку","випробування тун'ґріма"}},{q="Куди веде цей ланцюжок завдань далі?",a="Це завдання — останній крок випробувань Жорстокого обладунку. Коли Тун'ґрім вручить вам готову кольчугу, його робота для вас завершена, і ви можете йти в ній у бій по всьому Калімдору й Східних Королівствах.",al={"що після жорстокої кольчуги","наступне завдання після жорстокої кольчуги","чи є продовження"}},{q="Чи доступне завдання про Жорстоку Кольчугу Альянсу?",a="Ні. Жорстока Кольчуга — випробування лише для Орди. Воїни Альянсу проходять окремий бойовий обряд за участю ковалів Айронфорджа й довколишніх дворфійських земель, щоб здобути власний знаковий обладунок.",al={"чи альянс отримає жорстоку кольчугу","аналог для альянсу","чи лише для орди"}},{q="Де в Пустках знайти Тун'ґріма?",a="Тун'ґрім живе на високому хребті в північних Пустках, на південь від Річки Південної Люті й трохи на схід від головного гірського шляху, що веде на північ до Дуротару.",al={"місце тун'ґріма","де тун'ґрім у пустках","як знайти тун'ґріма"}}},fp="14,363,21.433.0,18.356.0,27.241.0,26.255.0,68.223.0,38.233.0,54.212.0,44.169.0"}
P.entries["quest:1858"] = {n="Розтрощена Рука",s="Це випробування розбійника — останній крок посвяти в лави Розтрощеної Руки в Оргріммарі. Терзок доручає розбійникам-початківцям відімкнути здобуту сумку, витягнувши ключ у нічого не підозрюваного спільника.",h="Це випробування розбійника — останній крок посвяти в лави Розтрощеної Руки в Оргріммарі.",kw={"розтрощена рука","терзок","ґамон","тазан","обчищання кишень","розбійник"},ang={["class:Rogue"]="Цей обряд посвяти вчить основ розбійницького ремесла: вистежити неуважну ціль у людному місці, непомітно витягти ключ і здобути важливі відомості.",["faction:Horde"]="Під бойовою честю нової Орди Тралла криється потреба в таємній розвідці, яку тихо веде Розтрощена Рука глибоко в Оргріммарі."},sec={{t="Випробування спритності",b="Здобувши замкнену сумку Тазана, розбійники-початківці бачать, що без ключа вона нічого не варта. Замість ламати хитрий замок грубою силою, Розтрощена Рука вимагає справжнього вміння. Терзок вказує посвяченим на Ґамона — неуважного п'яничку-таурена, що частенько засиджується в таверні Оргріммара й раніше допомагав Тазанові: ідеальна жертва для тихої крадіжки."},{t="Ласкаво просимо в тінь",b="Звільнивши Ґамона від ключа так, щоб не сполошити всю таверну, посвячений відмикає сумку й забирає журнал Тазана. Принісши здобуте Терзокові в Тіньову Розколину, він задовольняє суворі вимоги гільдії. Чисто виконавши роботу, кандидат офіційно стає визнаним агентом Розтрощеної Руки."}},faq={{q="Хто такий Ґамон і чому ключ у нього?",a="Ґамон був помічником Тазана — агента, чию торбу розслідує Терзок. Торбу Тазан носив при собі, а ключ залишив Ґамонові, нічого не підозрюючому пияку, який днями просиджує в головній корчмі Оргріммара.",al={"чому ґамон","у кого ключ","ключ ґамона"}},{q="Що в торбі Тазана?",a="У замкненій торбі лежить журнал Тазана. У ньому відомості, що цікавлять Терзока й Розтрощену Руку, а здобувши його, новачок доводить, що вміє таємно добувати важливі дані.",al={"журнал тазана","вміст торби","що в торбі"}},{q="Що таке Розтрощена Рука в Оргріммарі?",a="Колись це був сумнозвісний орчий клан з Дренору, відомий самокалічінням і безжальністю, а в Оргріммарі Розтрощена Рука стала головною гільдією вбивць, шпигунів і розбійників Орди, що діє з підземної Тіньової Розколини.",al={"що таке розтрощена рука","розбійники розтрощеної руки","розбійники оргріммара"}},{q="Де працює Терзок?",a="Терзок працює в Тіньовій Розколині — сутінковій мережі печер, схованій під скелястими хребтами Оргріммара, де подалі від денного світла процвітають чорнокнижники, розбійники й мистецтво тіні.",al={"де терзок","місце терзока","тренер розбійників тіньової розколини"}},{q="Чому Терзок просто не розкриє торбу силою?",a="Торба має складний замок, але головне — це перевірка дисципліни розбійника. Розтрощена Рука цінує точну, витончену крадіжку, а не галасливе нищення.",al={"чому красти кишенею","чому потрібен ключ"}},{q="Що буде після цього завдання?",a="Це доручення завершує ланцюжок посвяти. Віддавши журнал Тазана, ви стаєте визнаним членом Розтрощеної Руки й отримуєте знаряддя, що знадобиться у ваших майбутніх таємних справах.",al={"нагорода розтрощеної руки","кінець ланцюжка"}}},fp="18,216,18.387.0,22.353.0,42.243.0,31.216.0,40.250.0,27.179.0,48.194.0,30.223.1"}
P.entries["quest:1859"] = {n="Терзок",s="Терзок — виклик для обдарованих розбійників Орди, що діють біля Долини Випробувань і Села Сен'джин. Наставник розбійників Каплак помічає ваш хист до насильства й потайливості й нишком скеровує вас до печерної Тіньової Розколини, на зустріч з агентом Розтрощеної Руки.",h="Терзок — виклик для обдарованих розбійників Орди, що діють біля Долини Випробувань і Села Сен'джин.",kw={"терзок","каплак","розтрощена рука","тіньова розколина","розбійник","дуротар"},ang={["class:Rogue"]="Цей виклик знаменує ваш офіційний вступ до Розтрощеної Руки й пов'язує вашу самотню роботу в Дуротарі з організованою шпигунською мережею, що діє по всій Орді.",["faction:Horde"]="Хоч Тралл проповідує честь і дух воїна, існування Терзока та його мережі доводить, що Орда розуміє практичну потребу в невидимих клинках і таємних збирачах відомостей."},sec={{t="Виклик пошепки",b="Не всі слуги нової Орди б'ються при денному світлі під стягом Траллової честі. Коли юні розбійники починають здобувати собі ім'я в Дуротарі, Каплак відводить їх убік і стиха заводить розмову. Звістка про агента, що поєднує смертоносну вправність із готовністю обходити правила відкритої війни, швидко доходить до вух підпільної гільдії в Оргріммарі."},{t="У Тіньову Розколину",b="Каплак посилає посвяченого глибоко під червоні кам'яні кручі Оргріммара, у Тіньову Розколину. Подалі від пильних очей міської варти в сутінках чекає Терзок. Ця зустріч — точка посвяти: вона приводить самотніх кишенькових злодіїв і майстрів засідок у впорядковані лави Розтрощеної Руки — таємної мережі, що служить Орді кинджалами в темряві."}},faq={{q="Хто такий Терзок?",a="Терзок — агент Розтрощеної Руки, що працює в підземній Тіньовій Розколині в Оргріммарі. Він оцінює перспективних молодих розбійників, які приходять з тренувальних таборів Дуротару, і приймає їх на службу гільдії.",al={"хто такий терзок","терзок лор","нпц терзок"}},{q="Чому Каплак посилає мене до нього?",a="Каплак бачить, що ви вправні в бою й маєте хист до скрадання та хитрощів. Знаючи, що Розтрощена Рука завжди шукає здібних шибайголів для поповнення лав, він передає вам Терзокове запрошення.",al={"чому до терзока","завдання каплака","чому в оргріммар"}},{q="Що таке Розтрощена Рука в Оргріммарі?",a="Назва походить від давнього клану з Дренору, але в сучасному Оргріммарі Розтрощена Рука — таємна гільдія вбивць, шпигунів і злодіїв на службі Орди. Вони беруться за потрібну, але морально неоднозначну роботу, якої шляхетні воїни Тралла не можуть виконувати відкрито.",al={"що таке розтрощена рука","розтрощена рука оргріммар","гільдія розбійників орди"}},{q="Де розташована Тіньова Розколина?",a="Тіньова Розколина — величезна печера під центром Оргріммара, до якої ведуть темні проходи з Долини Сили й Долини Честі. Там, подалі від чужих очей, живуть міські чорнокнижники й розбійники.",al={"де тіньова розколина","як знайти терзока","місце тіньової розколини"}},{q="Що далі після зустрічі з Терзоком?",a="Привітавшись, Терзок одразу знайомить вас з обов'язками служби в Розтрощеній Руці й дає завдання, щоб ви довели свою вправність, уміння скрадатися й відданість мережі.",al={"наступне завдання","чого хоче терзок","після терзока"}},{q="Чи отримують це завдання не розбійники?",a="Ні. Це завдання пропонують лише розбійникам, які набралися певного досвіду; воно знаменує їхній перехід від місцевих сутичок до офіційної служби в розвідувальній мережі Орди.",al={"чи інші класи можуть це","чи лише для розбійників","завдання розбійника"}}},fp="7,282,19.368.0,24.369.0,15.228.0,31.243.0,40.284.0,37.237.0,33.190.0,33.200.0"}
P.entries["quest:1860"] = {n="Поговори з Дженнеєю",s="«Поговори з Дженнеєю» — вступний виклик для магів-новачків Альянсу, які переросли початкове навчання в Лісі Елвінн. За дорученням наставника Залдімара Вефгеллта з Ґолдширу учні мають з'явитися просто до Дженнеї Кеннон у Святилище Чародія в Стормвінді.",h="«Поговори з Дженнеєю» — вступний виклик для магів-новачків Альянсу, які переросли початкове навчання в Лісі...",kw={"поговори з дженнеєю","дженнея кеннон","залдімар вефгеллт","святилище чародія","маг","ґолдшир"},ang={["class:Mage"]="Це доручення знаменує ваш перехід від сільського чарування в Ґолдширі до офіційної участі в справах вищих магів, що працюють у Святилищі Чародія в Стормвінді.",["faction:Alliance"]="Безпека Лісу Елвінн і Стормвінда тримається не лише на піхоті, а й на пильності тайної магії, за якою стежать просто зі столичної магічної академії."},sec={{t="Виклик до Святилища Чародія",b="Щойно учень-маг виявить достатню майстерність у простих заклинаннях у Ґолдширі, Залдімар Вефгеллт розуміє: польова наука під проводом місцевих наставників вичерпала себе. Замість того щоб без кінця затримуватися в селищах Елвінна, здібних чарівників скеровують до самого Стормвінда. У серці Кварталу магів здіймається Святилище Чародія — просторий осередок тайних досліджень і навчання, де старші маги королівства керують ширшими магічними справами."},{t="Справи безпеки королівства",b="Залдімар наголошує: з'явитися до Стормвінда — це куди більше, ніж звичайне переведення на вищий щабель навчання. Виникла конкретна справа, що безпосередньо стосується безпеки і Лісу Елвінн, і Стормвінда. Прибувши, учень доповідає Дженнеї Кеннон — досвідченій чарівниці, що відає важливими місцевими дорученнями. Дженнея тримається стримано й обережно, не поспішаючи відкривати великі таємниці щойно прибулому учневі, але саме з цієї зустрічі починається безпосереднє служіння ордену чарівників."}},faq={{q="Хто посилає мене на це завдання?",a="Залдімар Вефгеллт, наставник магів з людей у Корчмі «Лев'яча Гордість» у Ґолдширі, дає це завдання, щойно ви досягнете достатньої чародійської вправності.",al={"хто дає завдання","хто починає завдання","залдімар"}},{q="Де знайти Дженнею Кеннон?",a="Дженнея Кеннон перебуває у Святилищі Чародія в центрі Кварталу магів Стормвінда. Вона навчається в містичних залах святилища.",al={"місце дженнеї кеннон","де дженнея","знайти дженнею"}},{q="Що таке Святилище Чародія?",a="Святилище Чародія — знана магічна вежа в Кварталі магів Стормвінда. Це головна академія, бібліотека й осередок магів і вчених-чародіїв королівства.",al={"що таке святилище чародія","вежа магів стормвінд"}},{q="Чому Залдімар посилає мене до Дженнеї, а не займається цим сам?",a="Залдімар навчає молодих магів основ у Ґолдширі, а за більшими загрозами в краю й особливими завданнями, що стосуються королівства, наглядають вищі за рангом учені зі столиці, як-от Дженнея Кеннон.",al={"чому до стормвінда","чому дженнея"}},{q="Що буде, коли з'явитися до Дженнеї Кеннон?",a="Щойно ви з'явитеся до Дженнеї, вона доручить вам дослідити загадкові магічні аномалії довкола Дзеркального Озера в Лісі Елвінн.",al={"що далі","наступне завдання","наступний крок"}},{q="Чи доступне це завдання будь-якому класу?",a="Ні. Це завдання — лише для магів; це класовий обряд посвяти, що переводить учня з сільського навчання до офіційних лав чародійської спільноти Стормвінда.",al={"чи не маги можуть це","лише для магів","вимога до класу"}}},fp="17,310,30.503.0,27.490.0,27.159.0,31.170.0,29.189.0,67.208.0,46.135.1,37.190.0"}
P.entries["quest:1861"] = {n="Дзеркальне Озеро",s="«Дзеркальне Озеро» — вступне дослідницьке завдання для магів-початківців Альянсу, які навчаються в Кварталі магів Стормвінда. За дорученням Дженнеї Кеннон підмайстри вирушають на південний захід від міської брами, щоб узяти пробу води з водоспаду Дзеркального Озера на залишкове магічне забруднення.",h="«Дзеркальне Озеро» — вступне дослідницьке завдання для магів-початківців Альянсу, які навчаються в Кварталі...",kw={"дзеркальне озеро","маг","дженнея кеннон","святилище чародія","проба води","стормвінд"},ang={["class:Mage"]="Це завдання знаменує перехід підмайстра від запилюжених фоліантів у Святилищі Чародія до дослідження справжніх магічних явищ, і винагородою стає перший справжній посох мага або куля для другої руки.",["faction:Alliance"]="Дбати про безпеку природних багатств Елвінну — один із непомітних способів, якими маги Святилища Чародія оберігають серце королівства.",["race:Human"]="Дзеркальне Озеро живить довколишні поля й річки Елвінну, тож його чистота життєво важлива для щоденного здоров'я мешканців Стормвінда."},sec={{t="Лей-лінії та зміщені потоки",b="За останні десятиліття Азерот пережив катастрофічні магічні потрясіння — від відкриття Темного Порталу до Третьої війни й битви біля Гори Гіджал. Ці жорстокі удари зірвали прадавні чародійські потоки з їхніх колись стійких русел. У Святилищі Чародія в Стормвінді маги на кшталт Дженнеї Кеннон пильно стежать за цими зсувами, побоюючись, що зміщені потоки магічної сили просочаться в довколишні нетрі й отруять місцеву природу."},{t="Проба води",b="Дзеркальне Озеро притулилося під скелями на південний захід від брами Стормвінда й слугує головним природним водосховищем, яке живлять гірські водоспади. Від цих вод залежить уся округа, тож Дженнея посилає магів-новачків зі скляною пляшкою просто до підніжжя водоспаду. Зібрані свіжі бризки дають Святилищу змогу провести тонкі ворожіння й реагентні проби, щоб з'ясувати, чи не почала дика магія просочуватися в питну воду."}},faq={{q="Навіщо Дженнеї Кеннон зразок води з Дзеркального Озера?",a="Великі магічні війни по всьому Азероту порушили природні лей-потоки. Дженнея Кеннон боїться, що збурена чародійська енергія просочується в підземні води довкола Стормвінда, а це може зашкодити кожному, хто п'є з озера.",al={"навіщо вода дзеркального озера","зразок води дженнеї","мета завдання"}},{q="Де саме Дзеркальне Озеро?",a="Дзеркальне Озеро лежить на північному заході Лісу Елвінн, тулячись до високих круч трохи на південний захід від головної брами Стормвінда. Потрібний зразок беруть з водойми біля підніжжя його каскадного водоспаду.",al={"де дзеркальне озеро","місце дзеркального озера","знайти дзеркальне озеро"}},{q="Що буде, якщо вода отруєна?",a="Дженнея боїться, що коли довго пити воду, отруєну магією, це зашкодить тим, хто залежить від озера. Точні наслідки поки невідомі.",al={"чи вода отруєна","що якщо вода магічна","наслідки магічної скверни"}},{q="Хто може взятися за це доручення?",a="Це доручення — саме для магів-початківців Альянсу; це одне з їхніх перших практичних польових завдань для Святилища Чародія.",al={"хто отримує завдання дзеркального озера","чи дзеркальне озеро лише для магів"}},{q="Чи веде це завдання до подальших розслідувань?",a="Воно завершує перше доручення, що почалося з виклику Дженнеї Кеннон: учень отримує своє перше офіційне знаряддя мага й обов'язок стежити за магічними збуреннями по всьому королівству.",al={"що після дзеркального озера","ланцюжок дзеркального озера"}},{q="Що взагалі розхитало магічні потоки?",a="Дженнея пояснює зміну потоків великими магічними битвами світу, не називаючи якоїсь конкретної битви чи події.",al={"чому зіпсовані магічні лінії","сенс містичної боротьби","що зламало магію"}}},fp="11,279,31.453.0,18.464.0,60.237.0,29.215.0,37.141.0,31.177.0,47.214.0,67.127.0"}
P.entries["quest:1879"] = {n="Поговори з Бінк",s="«Поговори з Бінк» — виклик Альянсу, що скеровує магів-новачків із Дун Мороґу до столиці, Айронфорджа. Надісланий Маґісом Спаркмантлом, він посилає перспективних заклиначів на допомогу Бінк, дослідниці таємних мистецтв, що працює в Залі Таїнств.",h="«Поговори з Бінк» — виклик Альянсу, що скеровує магів-новачків із Дун Мороґу до столиці, Айронфорджа.",kw={"поговори з бінк","бінк","маґіс спаркмантл","маг","зала таїнств","містичний квартал","айронфордж"},ang={["class:Mage"]="Цей виклик знаменує ваш відхід від вступного вишколу в долині до ширших справ учених чародіїв Айронфорджа.",["faction:Alliance"]="Спільні студії в Залі Таїнств показують тісне поєднання гномського розуму й дворфійської гостинності під прапором Альянсу.",["race:Gnome"]="Бінк і Маґіс Спаркмантл утілюють продовження гномської традиції таємних мистецтв у гостинних залах Айронфорджа після втрати Гномреґану."},sec={{t="Виклик від колеги",b="Маги-новачки, що навчаються серед холодних скель Дун Мороґу, зрештою потрапляють на око Маґісу Спаркмантлу. Помітивши, що учень переріс елементарні вправи довкола Хараноса, Спаркмантл передає слово від своєї колеги, Бінк. Прохання точне й безкомпромісне: Бінк потрібен фахівець із таємних мистецтв, і вона відмовляється довіряти справу будь-кому, хто не володіє магією."},{t="Зала Таїнств",b="Завдання веде молодих магів до Кварталу містиків Айронфорджа, де вчені, жерці й чародії збираються під високими кам'яними склепіннями Зали Таїнств. Тут Бінк веде свої студії, оцінюючи прибулих учнів гострим поглядом. На її думку, сирий потенціал — лише початок: недисциплінований заклинач у таємних справах швидко стає небезпекою, а не помічником."}},faq={{q="Хто дає це завдання?",a="Маґіс Спаркмантл пропонує це завдання магам-початківцям Альянсу, які просунулися в першому навчанні в Дун Мороґу.",al={"хто дає завдання","де почати","хто дає поговори з бінк"}},{q="Де знайти Бінк?",a="Бінк перебуває в Залі Таїнств, що в Кварталі містиків на півночі Айронфорджа.",al={"місце бінк","де бінк","знайти бінк"}},{q="Чому Бінк потрібен саме маг?",a="Бінк проводить дослідження, пов'язане безпосередньо з чародійською енергією й чутливим вимірювальним обладнанням. Вона вважає, що не маги не впораються з магічними тонкощами й небезпеками цієї справи.",al={"чому лише маги","вимога до магів","бінк хоче лише магів"}},{q="Що буде після зустрічі з Бінк?",a="Привітавшись і оцінивши ваші здібності, Бінк залучає вас до свого дослідження — далі йде завдання «Магонезрівнянний Гізмонітор».",al={"наступне завдання","продовження бінк","що після бінк"}},{q="Чи доступне це завдання іншим класам, крім магів?",a="Ні. Це завдання створене лише для магів як перехід від місцевого навчання до особливих доручень у столиці.",al={"чи інші класи можуть це","чи лише для магів","специфічне для магів"}},{q="Що таке Зала Таїнств?",a="Зала Таїнств — осередок чародійських і святих наук в Айронфорджі, де працюють наставники, учені й дослідники магічних мистецтв і дворфів, і гномів.",al={"зала таїнств айронфордж","що таке зала таїнств"}}},fp="15,259,21.388.0,21.404.0,21.113.0,22.108.0,31.192.0,32.141.0,52.134.0,30.172.0"}
P.entries["quest:1881"] = {n="Поговори з Анастасією",s="«Поговори з Анастасією» — вступний виклик, що скеровує перспективних магів-Відступників до Анастасії Гартвелл в Андерсіті. Наставник магів Кейн Файрсонг посилає молодого заклинача до Магічного Кварталу, щоб той узявся за важливу роботу для магів Відступників. Цей короткий виклик готує ґрунт для розслідувань у спустошених землях Галявин Тірісфалю.",h="«Поговори з Анастасією» — вступний виклик, що скеровує перспективних магів-Відступників до Анастасії Гартвелл...",kw={"поговори з анастасією","анастасія гартвелл","кейн файрсонг","магічний квартал","маг","андерсіті"},ang={["class:Mage"]="Це завдання знаменує ваш перехід від початкового магічного навчання до активної служби магам Андерсіті.",["race:Undead"]="Для магів-Відступників поклик Гартвелл — нагода обернути інтелектуальне минуле Лордерона проти його теперішніх небезпек."},sec={{t="Поклик до Магічного Кварталу",b="Коли молоді заклиначі відточують перші вміння під наглядом Кейна Файрсонга, невдовзі їх скеровують глибше в столицю. Маги Відступників мають власний осередок у Магічному Кварталі Андерсіті, де провадять і магічні студії, і стратегічну оборону всього Лордерона. Кейн Файрсонг оцінює учнів: звичайних новачків він відсіює, а тих, хто виявляє справжній хист, посилає просто до старших майстрів, яким потрібні вправні помічники в полі."},{t="Задуми Анастасії Гартвелл",b="Анастасія Гартвелл — одна з чільних наставниць магів в Андерсіті. Вона не лишає здібних учнів у безпеці вивчати дрібні заклинання, а не гаючи часу залучає їх до служби земельним і практичним інтересам Відступників. Відгукнутися на її виклик — це і обряд посвяти для знавців магії, і вступ до похмурих, прагматичних магічних пошуків, якими живе нежить, що вирвалася з-під влади Погибелі."}},faq={{q="Хто посилає поговорити з Анастасією Гартвелл?",a="Кейн Файрсонг, наставник магів з Відступників, посилає вас до неї, побачивши, що ваш чародійський хист достатньо розвинений, щоб допомагати в складніших справах у столиці.",al={"хто дає поговори з анастасією","хто дає завдання поговори з анастасією","виклик кейна файрсонґа"}},{q="Де знайти Анастасію Гартвелл?",a="Анастасія Гартвелл перебуває в Магічному Кварталі Андерсіті, де керує практиками чародійських мистецтв серед Відступників і навчає їх.",al={"де анастасія гартвелл","місце анастасії гартвелл","знайти анастасію"}},{q="Яка мета цього виклику?",a="Анастасія шукає вправного чарівника для практичних доручень за міськими мурами — почати доведеться з польових завдань у Галявинах Тірісфалю, як-от обстежити Хутір Балнірів.",al={"чому вона мене кличе","мета поговори з анастасією","що потрібно анастасії"}},{q="Яке завдання йде після «Поговори з Анастасією»?",a="З'явившись до Анастасії, ви одразу отримуєте завдання «Ферма Балнірів», яке відправляє вас на схід Галявин Тірісфалю по левову пащу з городу хутора.",al={"яке завдання далі","наступне завдання після анастасії","продовження анастасії"}},{q="Чи це завдання лише для певних класів?",a="Так, це завдання призначене саме для магів-Відступників — це сходинка на класовому шляху, коли вони здобувають першу вправність десь на десятому рівні.",al={"чи це завдання лише для магів","хто може поговорити з анастасією","вимога до класу"}},{q="Чому маги-Відступники мають в Андерсіті власний квартал?",a="Магічний Квартал — окреме пристановище, де чародії, чорнокнижники й дослідники з Відступників можуть навчатися й чаклувати подалі від решти міста, продовжуючи свої давні, ще з часів до Третьої війни, традиції в надрах Лордерону.",al={"чому квартал магів","маги відступників андерсіті"}}},fp="20,370,27.494.0,29.442.0,47.178.0,38.152.0,36.183.0,40.160.0,41.163.0,67.227.0"}
P.entries["quest:1882"] = {n="Ферма Балнірів",s="«Ферма Балнірів» — одне з перших випробувань для молодих магів-Відступників, яке дає Анастасія Гартвелл у Магічному Кварталі Андерсіті. Учнів посилають на схід Галявин Тірісфалю по ротики з покинутого хутора, що стоїть небезпечно близько до кордону Чумних Земель. Квіти слугують барометрами магічної скверни, яка підповзає зі сходу, спустошеного Погибеллю.",h="«Ферма Балнірів» — одне з перших випробувань для молодих магів-Відступників, яке дає Анастасія Гартвелл у...",kw={"ферма балнірів","хутір балнірів","ротики балніра","анастасія гартвелл","західні чумні землі","галявини тірісфалю","маг"},ang={["class:Mage"]="Це раннє випробування вчить магів-початківців, що їхні магічні студії конче потрібні, аби стежити за чужою магічною скверною й боронитися від неї.",["profession:Herbalism"]="Ротики Балніра — приклад того, як рослини можуть водночас накопичувати магічне забруднення й показувати його рівень.",["race:Undead"]="Для Відступників захист кордонів Галявин Тірісфалю від навали Погибелі — питання негайного виживання й незалежності."},sec={{t="Магічний барометр",b="Поки Королівське Аптекарське Товариство здебільшого вивчає дію некромантії й розкладу, маги Відступників і самі пильно стежать за прикордонням. Анастасія Гартвелл доручає заклиначам-початківцям вирушити на Хутір Балнірів на сході Галявин Тірісфалю. Ротики, що ростуть у садах хутора, від природи чутливі до мінливих магічних потоків і вбирають розлиту довкола енергію з ґрунту й повітря. Вивчаючи ці квіти, учені-маги в Андерсіті можуть виміряти, чи не просочилася заразна скверна володінь Короля-Ліча крізь заслін у сам Тірісфаль."},{t="Східний кордон",b="Хутір Балнірів стоїть на краю галявин, неприємно близько до поораної заразою глушини Західних Чумних Земель. Відступники розуміють, що чума Короля-Ліча — некерована руйнівна сила, яка гноїть саму землю. Хоч Відступники й самі вдаються до темних мистецтв, нестримна скверна Погибелі загрожує їхнім кордонам і безпеці. Анастасія має намір передати зібрані ротики аптекарям, поєднавши магічні спостереження з алхімічними дослідами, щоб захистити відвойоване серце Лордерона."}},faq={{q="Чому Анастасії Гартвелл потрібна саме левова паща?",a="Левова паща з Хутора Балнірів має особливу природну чутливість до навколишніх магічних сил. Оскільки ці квіти вбирають енергію просто із землі й повітря, вивчивши їх, маги-Відступники можуть з'ясувати, чи не отруює чародійська й некромантська пошесть сусідніх Чумних Земель Галявини Тірісфалю.",al={"чому левова паща","призначення левової пащі балнірів","для чого левова паща"}},{q="Де розташований Хутір Балнірів?",a="Хутір лежить на сході Галявин Тірісфалю, ближче до межі, де галявини підступають до спаплюженого прикордоння Західних Чумних Земель. Левова паща росте на зарослих ділянках і городах довкола занедбаних будівель хутора.",al={"місце хутора балнірів","де ферма балнірів","знайти хутір балнірів"}},{q="Хто така Анастасія Гартвелл?",a="Анастасія Гартвелл — знана маг і наставниця з Відступників, що живе в Кварталі магів Андерсіті. Вона веде новоспечених чарівників-нежить, навчаючи їх дисципліни, чародійської рівноваги й практичного захисту кордонів від ворожих сил.",al={"лор анастасії гартвелл","хто така анастасія"}},{q="Чому магам-Відступникам не байдуже, як зупинити чуму?",a="Хоча Відступники й самі експериментують із власними чумами й пошестями, заразну магію Погибелі від Короля-Ліча вони вважають некерованим збоченням. Якщо її не стримати, скверна Погибелі поглине Галявини Тірісфалю цілком і підважить незалежність Відступників.",al={"чому зупинити чуму","чи відступники ненавидять чуму"}},{q="Що стається з квітами, коли ви їх зберете?",a="Отримавши левову пащу, Анастасія готується передати її аптекарям Андерсіті. Алхіміки й маги разом розтинають зразки, щоб оцінити, наскільки глибоко Погибель отруїла ґрунт і рослинність.",al={"що анастасія робить із квітами","кому квіти левової пащі"}},{q="Чи це завдання лише для магів?",a="Так. Це окреме класове завдання лише для молодих магів-Відступників, які вже пройшли перші уроки в Похоронному Подзвоні й прибули до столиці довести, що опанували чародійську теорію.",al={"чи хутір балнірів лише для магів","завдання класу магів"}}},fp="20,416,19.614.0,18.566.0,58.297.0,38.248.0,26.261.0,53.269.0,51.231.0,34.219.0"}
P.entries["quest:1885"] = {n="Меннет Каркад",s="«Меннет Каркад» — вступне завдання для розбійників в Андерсіті, що приводить перспективних агентів до лав скрадачів смерті. За вказівкою Маріон Колл молоді вбивці мають з'явитися просто до Меннета Каркада глибоко в Кварталі Розбійників.",h="«Меннет Каркад» — вступне завдання для розбійників в Андерсіті, що приводить перспективних агентів до лав...",kw={"меннет каркад","маріон колл","скрадачі смерті","квартал розбійників","розбійник","андерсіті"},ang={["class:Rogue"]="Цей виклик знаменує ваш перехід від непевного кишенькового злодюжки до визнаного агента скрадачів смерті — елітної тіньової мережі Відступників.",["race:Undead"]="Скрадачі смерті — запорука виживання Відступників: вони полюють на багряних фанатиків і рештки Погибелі та оберігають королеву Сильвану від прихованих загроз."},sec={{t="Виклик із тіні",b="У темних коридорах Андерсіті чутки тихо передаються між таємними агентами Відступників. Коли розвідник чи вбивця привертає увагу вищого проводу, йому надсилають запрошення. Маріон Колл переказує, що Меннет Каркад, помітна постать серед кураторів розбійників, особисто звернув увагу на новачка. Знаючи смертоносну славу розвідки Відступників, знехтувати таким наказом — не вихід."},{t="До лав скрадачів смерті",b="Меннет Каркад чекає в затінених нішах Кварталу Розбійників: він стежить за новобранцями й оцінює їхню готовність. Ті, хто відгукнеться на його поклик, вступають не до звичайної злодійської гільдії — їх випробовують на вступ до скрадачів смерті, грізної служби шпигунства й таємних убивств Відступників. Швидка покора — лише перше, найпростіше випробування для кожного, хто хоче служити Темній Леді з тіні."}},faq={{q="Хто такий Меннет Каркад?",a="Меннет Каркад — наставник розбійників і куратор Скрадачів смерті, що працює в Кварталі Розбійників Андерсіті. Він наглядає за перспективними таємними агентами й дає важливі доручення від імені проводу Відступників.",al={"лор меннета каркада","хто такий каркад"}},{q="Що буде, якщо знехтувати викликом Меннета Каркада?",a="Marion Call warns that you would not want to know what happened to those who ignored Carkad's call. She leaves their exact fate unexplained.",al={"ігнорувати каркада","що буде, якщо знехтувати викликом"}},{q="Хто такі Скрадачі смерті?",a="Скрадачі смерті — добірний орден розбійників, шпигунів і вбивць на службі Відступників. Діючи з тіней Андерсіті, вони усувають важливі цілі, збирають розвідані й боронять Лордерон від ворогів, як-от Багряний Хрестовий Похід і Погибель.",al={"лор скрадачів смерті","хто такі скрадачі смерті"}},{q="Де знайти Меннета Каркада?",a="Меннет Каркад перебуває в Кварталі Розбійників Андерсіті, зазвичай серед інших таємних агентів, наставників і припасів для мистецтва тіні.",al={"місце каркада","де меннет каркад"}},{q="Хто дає завдання розшукати Меннета Каркада?",a="Це завдання дає Маріон Колл у таверні «Шибеничний Кінець» у Бріллі: вона помічає, як зростає ваша вправність, і попереджає, що Каркад чекає швидкого послуху.",al={"хто починає це завдання","завдання кліч маріон"}},{q="Що буде, коли з'явитися до Меннета Каркада?",a="Щойно ви з'явитеся до Меннета Каркада, починається безпосередня служба Скрадачам смерті — з доручень, що мають довести вашу кмітливість і відданість справі Відступників.",al={"наступне завдання після каркада","чого хоче каркад"}}},fp="13,256,26.446.0,25.425.0,21.216.0,56.140.0,26.268.0,31.150.0,46.154.0,44.173.0"}
P.entries["quest:1886"] = {n="Смертолови",s="Це завдання — випробування для новачків, які прагнуть до лав скрадачів смерті, таємної й смертоносної служби, що підкоряється лордові Варіматрасу в Андерсіті. Доручення дає Меннет Каркад у Кварталі Розбійників, і воно вимагає безжальної кмітливості, щоб перехопити гінця в дорозі. Виконавши його, агент отримує доступ до глибших таємних задумів у королівстві Відступників.",h="Це завдання — випробування для новачків, які прагнуть до лав скрадачів смерті, таємної й смертоносної служби...",kw={"скрадачі смерті","меннет каркад","астор гадрен","варіматрас","квартал розбійників","розбійник"},ang={["class:Rogue"]="Для розбійників-Відступників вступ до скрадачів смерті — найвищий щабель служби державі: так вуличні пройдисвіти стають присяжними знаряддями Варіматраса й Темної Леді.",["faction:Horde"]="Скрадачі смерті діють у глибокій таємниці: вони підтримують важливі розвідувальні мережі Відступників, а південні союзники Орди здебільшого й гадки не мають про їхні темніші внутрішні справи.",["race:Undead"]="Скрадачі смерті — залізна хватка внутрішньої безпеки Лордерона: вони пильно й підозріливо стежать і за зовнішніми ворогами, і за можливими зрадниками серед Відступників."},sec={{t="Випробування в тіні",b="Скрадачі смерті приймають до своїх лав не кожного. Цей таємний орден, що підкоряється просто жахолордові Варіматрасу, водночас і таємна поліція, і елітний загін убивць Відступників. Щоб привернути його увагу, кандидат мусить показати хитрість, стриманість і готовність без вагань усувати цілі. У затінених кутках Кварталу Розбійників куратор Меннет Каркад призначає вступне випробування, що відсіює слабких і надто розбірливих."},{t="Перехоплення",b="Ціль новачка — Астор Гадрен, гонець, що мандрує дорогою між Андерсіті й Срібноліссям. Каркад не дає жодних тактичних порад: як здобути рекомендаційний лист Гадрена, агент вирішує сам. Головне — перехопити Астора, забрати його документи й дати скрадачам смерті змогу видати свого новобранця за очікуваного посланця до агента на ім'я Андрон."}},faq={{q="Хто такі Скрадачі смерті?",a="Скрадачі смерті — добірна гілка скрадання й убивств серед Відступників. Їхній осередок — у Кварталі Розбійників Андерсіті; вони займаються шпигунством, таємними стратами й збиранням відомостей і звітують безпосередньо лордові Варіматрасу.",al={"лор скрадачів смерті","хто такі скрадачі смерті","розбійники-нежить"}},{q="Хто такий Меннет Каркад?",a="Меннет Каркад — куратор Скрадачів смерті, що працює в Кварталі Розбійників Андерсіті. Він проводить перші випробування й перевіряє новобранців, які хочуть приєднатися до таємних лав.",al={"роль меннета каркада","хто дає завдання"}},{q="Навіщо Меннетові лист Астора Гадрена?",a="Астор Гадрен — гонець, що мандрує між Срібноліссям і Андерсіті. Здобувши його рекомендаційний лист, Скрадачі смерті можуть підставити замість Гадрена свого нового агента, щоб обдурити його знайомого на ім'я Андрон.",al={"лист астора гадрена","навіщо перехопити гінця","рекомендаційний лист астора"}},{q="Куди мандрує Астор Гадрен?",a="Астор Гадрен ходить шляхом, що сполучає Андерсіті й Срібнолісся, і доставляє листування між краями для своїх знайомих.",al={"маршрут астора гадрена","місце астора гадрена","де астор"}},{q="Хто такий лорд Варіматрас?",a="Варіматрас — жахолорд-натрезим, що уклав союз із королевою Сильваною Віндраннер, аби зберегти власне існування. З Королівського Кварталу він наглядає за безпекою, обороною й таємними операціями Андерсіті.",al={"роль варіматраса","володар жаху в андерсіті"}},{q="Що буде після цього випробування?",a="Пройшовши випробування, агент доводить свою вправність, і далі на нього чекає таємне доручення: видати себе за Астора, доставити його папери й проникнути в оборудки Андрона.",al={"що далі","продовження лінії скрадачів смерті"}}},fp="17,363,21.480.0,16.414.1,26.240.0,21.173.0,43.231.0,31.151.0,24.201.0,30.158.1"}
P.entries["quest:1898"] = {n="Смертолови",s="Це таємне доручення посилає агента під прикриттям у темні закутки Андерсіті, щоб випитати все в необачного змовника. Діючи за наказом, що надійшов від лорда Варіматраса, ви видаєте себе за очікуваного гінця, щоб викрити зраду в самій столиці Відступників.",h="Це таємне доручення посилає агента під прикриттям у темні закутки Андерсіті, щоб випитати все в необачного...",kw={"скрадачі смерті","андрон ґант","меннет каркад","астор гадрен","варіматрас","аптекаріум"},ang={["class:Rogue"]="Проникнути в шпигунську мережу під іменем мертвого, щоб виманити необачного змовника, — це прийом просто з підручника скрадачів смерті.",["faction:Horde"]="Під поверхнею Андерсіті кишать політичні інтриги — доказ того, що навіть у межах Орди довіра — рідкісний скарб.",["race:Undead"]="Для Відступників пильність — це виживання. Кожного громадянина, викритого в допомозі чужим угрупованням, може негайно знищити таємна поліція Темної Леді."},sec={{t="Павутина обману",b="Скрадачі смерті не лише усувають зовнішні загрози Відступникам — вони й безжально пильнують власних громадян. Через підозри лорда Варіматраса скрадач смерті Меннет Каркад запускає план проникнення. Маючи підроблений чи здобутий рекомендаційний лист Астора Гадрена, ви маєте приспати пильність місцевого крамаря на ім'я Андрон Ґант."},{t="Крамниця біля Апотекаріуму",b="Андрон Ґант тримає крамницю неподалік мерзенних випарів і булькотливих казанів Апотекаріуму. Меннет вважає крамаря дурнуватим і неуважним — йому забракне кмітливості, щоб розкусити самозванця. Показавши лист, ви утверджуєте своє прикриття гінця, і Ґант охоче втрачає пильність та сам розповідає подробиці своїх оборудок із невідомою третьою стороною."}},faq={{q="Хто такий Андрон Ґант?",a="Андрон Ґант — крамар з Андерсіті, чия крамниця біля Апотекаріуму. Він привернув увагу Скрадачів смерті і лорда Варіматраса, бо нібито передає відомості й допомогу якійсь невідомій сторонній силі.",al={"андрон ґант","хто такий ґант","де андрон ґант"}},{q="Чому лорда Варіматраса цікавить цей крамар?",a="Варіматрас підозрює, що Ґант співпрацює з якоюсь організацією поза Відступниками. Щоб уберегти місто й викорінити можливу змову, жахолорд вимагає конкретних доказів зв'язків і намірів Ґанта.",al={"чому варіматрас цікавиться","варіматрас андрон ґант","чому шпигувати за андроном"}},{q="Як обдурити Андрона Ґанта?",a="Меннет Каркад дає вам Рекомендаційний Лист Астора. Ґант чекав гінця, а Скрадачі смерті вважають його не надто кмітливим, тож досить показати йому папери, щоб здобути його довіру.",al={"лист астора","як обдурити андрона ґанта","маскування гінця"}},{q="Що за угруповання — Скрадачі смерті?",a="Скрадачі смерті — добірний орден розбійників і таємна розвідка Відступників. Діючи з тіней під проводом королеви Сильвани й лорда Варіматраса, вони викорінюють заколоти, шкодять ворогам і усувають внутрішні загрози.",al={"лор скрадачів смерті","хто такі скрадачі смерті","розбійники андерсіті"}},{q="Де знайти Андрона Ґанта?",a="Він сидить у своїй крамниці біля входу до кварталу Апотекаріуму в Андерсіті й веде справи під пильним оком Королівського Аптекарського Товариства та Скрадачів смерті.",al={"місце андрона ґанта","де крамниця ґанта"}},{q="Що буде, коли Ґант прийме лист?",a="Ґант без жодної підозри бере лист і вважає вас звичайним гінцем. Він одразу натякає на співпрацю зі спільними знайомими, що триває, — і це відкриває шлях до нових доказів його зради.",al={"що робить ґант","реакція ґанта"}}},fp="17,276,15.416.0,30.377.1,19.228.0,52.214.0,40.225.0,33.235.0,31.189.0,43.228.1"}
P.entries["quest:1899"] = {n="Смертолови",s="Це доручення — важливий крок до укладення домовленості між інформатором Андроном Ґантом і скрадачами смерті Андерсіті. Заручившись його співпрацею, агент доставляє докладний гросбух Ґанта просто в руки Меннета Каркада в Кварталі Розбійників. Ця передача знаменує перехід від простих розпитувань до глибших, таємніших операцій на користь держави Відступників.",h="Це доручення — важливий крок до укладення домовленості між інформатором Андроном Ґантом і скрадачами смерті...",kw={"скрадачі смерті","андрон ґант","гросбух","меннет каркад","квартал розбійників"},ang={["class:Rogue"]="Для молодого розбійника в Андерсіті делікатні доручення гінця для Меннета Каркада — базова перевірка стриманості: так агент доводить, що вміє вести таємні справи, не привертаючи зайвої уваги.",["race:Undead"]="Внутрішня безпека в Андерсіті — питання виживання: допомагаючи скрадачам смерті, ви прямо зміцнюєте владу Темної Леді над столицею проти живих лазутчиків і суперницької нежиті."},sec={{t="Гонець у тіні",b="Скрадачі смерті покладаються не лише на грубу силу чи тіньову магію: їхні операції значною мірою тримаються на буденних гросбухах, записаних іменах і ретельному стеженні. Андрон Ґант, що діє в Андерсіті, погоджується віддати особистий гросбух, напханий відомостями, яких так прагнуть убивці. Замість того щоб мати справу просто зі смертоносним ядром організації, Ґант довіряється посередникові-гінцю — і в цьому видно обережність, типову для кожного, хто торгує відомостями серед мертвих."},{t="Розвіддані в Кварталі Розбійників",b="Доставлений Меннетові Каркаду в Кварталі Розбійників, гросбух виявляється куди промовистішим, ніж сподівалися скрадачі смерті. Замість побіжних нотаток записи Ґанта дають конкретні зачіпки, що дозволяють Каркаду розширити розслідування. У такому підозріливому й розколотому світі, як королівство Відступників, перевірений паперовий слід конче потрібен, щоб викорінювати внутрішню крамолу й стежити за зовнішніми загрозами, перш ніж вони вдарять по столиці."}},faq={{q="Що в Гросбуху Андрона?",a="У гросбуху — делікатні відомості й записи, які зібрав Андрон Ґант. Точний вміст уголос не зачитують, але Меннет Каркад зауважує, що там значно більше подробиць і цінних розвіданих, ніж Скрадачі смерті спершу від нього чекали.",al={"вміст гросбуха андрона","що в гросбуху","гросбух скрадачів смерті"}},{q="Хто такі Скрадачі смерті?",a="Скрадачі смерті — провідна таємна організація й гільдія вбивць Відступників. Їхній осередок — у Кварталі Розбійників Андерсіті; вони — очі, вуха й приховані кинджали Леді Сильвани Віндраннер, що займаються шпигунством, розвідкою й цілеспрямованими вбивствами по всьому Лордерону.",al={"лор скрадачів смерті","хто такі скрадачі смерті","розбійники андерсіті"}},{q="Чому Ґант хоче й надалі мати справу з тим самим гінцем?",a="У каламутній, недовірливій атмосфері Андерсіті рідко трапляється посланець, який доставляє делікатні документи, нічого не крадучи й не підробляючи. Ґант прямо просить, щоб надалі справи вів той самий гонець, — так менше ризику, і налагоджена домовленість зберігається.",al={"чому ґант вас любить","довіра андрона ґанта","гінець ґанта"}},{q="Хто такий Меннет Каркад?",a="Меннет Каркад — досвідчений агент Скрадачів смерті, що стоїть у Кварталі Розбійників. Він координує місцевих агентів, збирає польові розвідані від донощиків на кшталт Андрона Ґанта й керує таємними дорученнями по всій столиці й довколишніх землях.",al={"лор меннета каркада","хто такий каркад"}},{q="Де розташований Квартал Розбійників?",a="Квартал Розбійників — південна частина Андерсіті. Це головний осередок агентів-скрадачів, злодіїв і вбивць Відступників, із тренувальними майданчиками й темними нішами далеко від людних площ верхніх руїн.",al={"місце кварталу розбійників","де квартал розбійників","квартал розбійників андерсіті"}},{q="Навіщо Відступникам власна внутрішня розвідка?",a="Оточений з усіх боків Погибеллю, Багряним Хрестовим Походом і недовірливими рештками Альянсу, молодий народ Відступників постійно потерпає від загрози проникнення й заколоту. Скрадачі смерті викорінюють змови в межах Лордерону, щоб молода влада вистояла.",al={"чому скрадачі смерті існують","шпигуни відступників","розвідка андерсіті"}}},fp="17,408,24.503.0,35.465.1,27.270.0,26.299.0,55.305.0,21.265.0,37.248.0,57.274.0"}
P.entries["quest:19"] = {n="Таріл'зун",s="Маршал Марріс оголошує нагороду за Таріл'зуна, хитрого ватажка скороходів Блекрок, що не дають спокою дорогам біля Фортеці Кам'яної Варти. Його смерть — важливий крок до того, щоб зламати владу клану Блекрок над північним Редріджем. Відрубана голова ватажка, принесена до Лейкширу, — тяжко здобута перемога знесиленої міської варти.",h="Маршал Марріс оголошує нагороду за Таріл'зуна, хитрого ватажка скороходів Блекрок, що не дають спокою дорогам...",kw={"таріл'зун","скороходи блекрок","маршал марріс","фортеця кам'яної варти","лейкшир","нагорода"},ang={["faction:Alliance"]="Лейкшир здебільшого відрізаний від прямого підкріплення зі Стормвінда, тож нагорода за Таріл'зуна — життєво важливий місцевий захід, щоб не допустити облоги містечка.",["race:Human"]="Присутність Блекрок у Редріджі — болюче нагадування про Першу й Другу війни, а смерть Таріл'зуна повертає королівству відібрану землю.",["race:Orc"]="Таріл'зун належить до темних решток Старої Орди під прапором Блекрок і служить володарям, які відкидають новий лад Тралла за морем."},sec={{t="Дорога до Кам'яної Варти",b="Звивистий перевал між Лейкширом і Фортецею Кам'яної Варти перетворився на смугу раптових засідок. Скороходи й ренегати Блекрок нишпорять кам'янистими хребтами, перехоплюють розвідників і загрожують кожному підкріпленню, що намагається пробитися до фортеці. Маршал Марріс вважає, що ці злагоджені удари спрямовує Таріл'зун, і оголошує, що його треба знищити, інакше Лейкшир опиниться в цілковитій облозі."},{t="Обезголовити скороходів",b="Таріл'зун — небезпечний тип польового командира: лютий, хитрий і здатний згуртувати розрізнених орків-грабіжників у дієвий загін. Щоб здобути його голову в тіні Кам'яної Варти, доведеться прорубатися крізь укріплені застави Блекрок. Його смерть руйнує злагодженість патрулів скороходів і відкриває Альянсові шлях до гарнізону, що засів у самій фортеці."}},faq={{q="Хто такий Таріл'зун?",a="Таріл'зун — грізний командир орків Блекрок, що керує розвідниками й ренегатами, які влаштовують засідки на стежках між Лейкширом і Фортецею Кам'яної Варти.",al={"хто такий таріл'зун","таріл'зун лор","бос таріл'зун"}},{q="Де знайти Таріл'зуна?",a="Таріл'зун стоїть біля Фортеці Кам'яної Варти на північному сході Редріджу й командує розвідниками, які патрулюють довколишні перевали й застави.",al={"де таріл'зун","місце таріл'зуна","знайти таріл'зуна"}},{q="Навіщо Маршалові Маррісу його голова?",a="Марріс бачить у Таріл'зуні хитрого тактика, що спрямовує засідки, які не дають спокою Редріджу. Голова ватажка означає, що розвідники лишилися без проводу, і стає незаперечним доказом того, що загрозу усунуто.",al={"чому вбити таріл'зуна","причина винагороди за таріл'зуна"}},{q="Що буде після перемоги над Таріл'зуном?",a="Загибель Таріл'зуна розладнує дії розвідників, і захисники Лейкшира разом із шукачами пригод можуть просунутися глибше до Фортеці Кам'яної Варти, щоб зійтися з головним гарнізоном Блекрок.",al={"завдання після таріл'зуна","що після таріл'зуна"}},{q="Що орки Блекрок роблять у Горах Редріджу?",a="Рештки клану Блекрок просунулися на південь з Палаючих Степів у Редрідж і укріпили старі людські застави, як-от Фортецю Кам'яної Варти, щоб загрожувати Східним Королівствам, поки військо Стормвінда розпорошене.",al={"чому орки блекрок у редріджі","орки кам'яної варти передісторія"}},{q="Що треба зробити, перш ніж полювати на Таріл'зуна?",a="Маршал Марріс вимагає, щоб шукачі пригод спершу довели свою загартованість, проріджуючи загарбників у завданні «Загроза Блекрок», і лише тоді посилає їх по самого Таріл'зуна.",al={"передумова таріл'зуна","як відкрити завдання таріл'зуна"}}},fp="10,342,22.432.0,27.419.0,18.176.0,30.144.0,38.216.0,42.185.0,45.218.0,62.173.0"}
P.entries["quest:1918"] = {n="Опоганений елемент",s="Убиваючи збурених водяних елементалів довкола Озера Містраль, шукачі пригод знаходять мерзенну сяйливу кулю отруєної води. Прагнучи зрозуміти, що отруїло озеро та його стихійних духів, вони несуть зразок до Мастока Врайлгісса на Заставу Розщепленого Дерева.",h="Убиваючи збурених водяних елементалів довкола Озера Містраль, шукачі пригод знаходять мерзенну сяйливу кулю...",kw={"опоганений елемент","озеро містраль","водяні елементалі","масток врайлгісс","земляне кільце","завдання"},ang={["class:Shaman"]="Спотворений стан духів Озера Містраль глибоко тривожить шаманів, які чують біль стихій і розуміють, що без втручання Земляного Кільця не обійтися.",["faction:Horde"]="Застава Розщепленого Дерева не може дозволити, щоб у неї під боком гноїлася хаотична стихійна загроза, поки вартові Альянсу й фурболги загрожують шляхам постачання Орди.",["race:Tauren"]="Таурени-мандрівники відчувають глибокий обов'язок свого народу зцілювати отруєні води землі, тож відновлення Озера Містраль для них — нагальна духовна справа."},sec={{t="Отруєні води Озера Містраль",b="Озеро Містраль на південному сході Ашенвалю потрапило в тяжку біду. Водяні елементалі, що живуть на його мілинах, стали жорстоко агресивними й помітно зіпсованими. Убиті, вони лишають по собі не чисту стихійну есенцію, а дивні, яскраво сяйливі кулі гнилої рідини. Хай яка порча оселилася над озером, вона зосереджена в цих кулях, — а отже, заворушення значно серйозніше, ніж звичайна природна агресивність."},{t="По пораду до Розщепленого Дерева",b="Не розуміючи, яка мерзенна магія тут діє, розвідники Орди звертаються по пораду до гарнізону Застави Розщепленого Дерева. Масток Врайлгісс, один із наглядачів застави, спершу гидливо відсахується від мерзенного зразка. Вояк, а не вчений, Масток швидко розуміє, що звичайна сталь не вилікує хворої води, і посилає шукача пригод до знавців стихій із Земляного Кільця."}},faq={{q="Що в Опоганеній Водяній Кулі?",a="У кулі — огидний зосереджений зразок скверни, що нині отруює Озеро Містраль. Вона утворюється з решток убитих елементалів, і це доводить, що їхня духовна скверна цілком відчутна й потужна.",al={"вміст опоганеної кулі","що у водяній кулі","водяна куля містралового озера"}},{q="Де починається це завдання?",a="Завдання починається з предмета, що випадає під час боїв з розлюченими чи опоганеними водяними елементалями Озера Містраль у південній частині центрального Ашенвалю.",al={"де знайти водяну кулю","як почати опоганений елемент","початок завдання"}},{q="Чому Масток Врайлгісс не хоче мати з цим нічого спільного?",a="Масток Врайлгісс — офіцер Орди на Заставі Розщепленого Дерева, якого обходять передусім виживання війська й постачання. Розбиратися в хворих магічних водах — не його справа, тож він радить звернутися до Земляного Кільця.",al={"хто такий масток","чому говорити з мастоком","роль масток врайлгісс"}},{q="Чому це цікавить Земляне Кільце?",a="Земляне Кільце — орден шаманів, що вивчає стихії, угамовує їх і відновлює між ними гармонію. Зіпсовані елементалі на кшталт тих, що в Озері Містраль, якраз підлягають їхньому духовному відомству.",al={"чому земляне кільце","зв'язок земляного кільця","хто такі земляне кільце"}},{q="Куди веде розслідування далі?",a="Масток спрямовує вас до Дже'ню Санкреа — шамана Земляного Кільця, що стоїть на західному узбережжі Ашенвалю, на Березі Зорам'ґар, і може як слід оглянути опоганену реліквію.",al={"що далі","наступне завдання після опоганеного елемента","куди йти далі"}}},fp="20,271,30.469.0,30.429.1,40.219.0,28.140.0,53.222.0,44.208.0,39.175.1"}
P.entries["quest:1938"] = {n="Трактат Ура про Магію Тіні",s="«Трактат Ура про Магію Тіні» — завдання, яке дає Верховний Чаклун Андромат у Кварталі магів Стормвінда. Він доручає шукачам пригод повернути заборонений, магічно запечатаний фоліант, з яким утік маг-ренегат Морґант, сховавшись у Вежі Ілґалара в Горах Редріджу.",h="«Трактат Ура про Магію Тіні» — завдання, яке дає Верховний Чаклун Андромат у Кварталі магів Стормвінда.",kw={"трактат ура","магія тіні","морґант","вежа ілґалара","верховний чаклун андромат","гори редріджу"},ang={["class:Mage"]="Маги Стормвінда серйозно ставляться до внутрішньої дисципліни: довіреним чарівникам доручають розгрібати небезпечні наслідки, які залишив по собі товариш, що звернувся до забороненої магії тіні.",["class:Warlock"]="Поки Кірін-Тор і маги Стормвінда бояться трактатів Ура про тіні, чорнокнижники нерідко жадають саме тих сил — призову з інших світів і темних чарів, — що запечатані в них.",["faction:Alliance"]="Повернувши викрадений фоліант, ви вбережете кордони Редріджу від дедалі більшої магічної загрози Морґанта й захистите королівство Стормвінд від свавільної тайної магії."},sec={{t="Розкол у вежі",b="Колись давно троє обдарованих магів навчалися разом у Святилищі Чародія в Стормвінді. З часом один із них, Морґант, піддався спокусам темних мистецтв і магії тіні. Попри відчайдушні застереження товаришів, які благали його відвернутися від цієї згубної сили, він не захотів зректися своєї одержимості. Його офіційно вигнали з магічного ордену міста, але пішов він не з порожніми руками: він викрав небезпечну працю Ура — сумнозвісного архімага, чиї дослідження виходили далеко за межі визнаної тайної науки."},{t="Лігво занепалого мага",b="Морґант звив собі нове кубло далеко від пильного ока Стормвінда, захопивши Вежу Ілґалара на висотах Гір Редріджу. Верховний Чаклун Андромат не може допустити, щоб такі небезпечні знання лишалися в руках вигнанця, що практикує заборонене чаклунство. Доручивши шукачам пригод Альянсу прорвати оборону вежі, Андромат прагне повернути фоліант, перш ніж упадуть його захисні чари."},{t="Захисні чари вціліли",b="Коли трактат вдається забрати з бібліотеки Ілґалара й повернути до Святилища Чародія, Андромат відчуває величезне полегшення. Він боявся, що Морґант уже розплутав його захисні чари або сховав книгу так, що не дістати. На щастя, магічні печаті на трактаті Ура витримали — і магові-ренегату не вдалося випустити на волю згубні таємниці, ув'язнені на його сторінках."}},faq={{q="Хто написав трактат?",a="Трактат написав Ур — легендарний маг з Даларана, знаний своїми таємничими дослідженнями позасвітових істот і магії тіні.",al={"хто такий ур","автор трактату","автор трактату ура"}},{q="Хто викрав Трактат Ура про Магію Тіні?",a="Морґант, колишній маг зі Стормвінда, викрав книгу, коли піддався темній магії й був вигнаний зі Святилища Чародія.",al={"хто вкрав книгу","хто забрав трактат","книга морганта"}},{q="Де зберігається книга?",a="Книга зберігається в бібліотеці Вежі Ілґалара, високо в Горах Редріджу, де Морґант облаштував свій новий притулок.",al={"де трактат","місце книги вежі ілґалара","де знайти трактат ура"}},{q="Чи вдалося Морґантові прочитати книгу?",a="Ні. Коли трактат повертають Верховному Чаклунові Андромату, той підтверджує, що захисні печаті на книзі втрималися, тож Морґант так і не зміг її відкрити.",al={"чи морґант відкрив книгу","чи відкрили трактат","чи зламані печаті"}},{q="Чому маги Стормвінда хочуть повернути книгу?",a="У фоліанті — глибокі таємниці магії тіні, що можуть згубити недосвідчених. Маги Стормвінда вважають, що лишати його в руках ренегата на кшталт Морґанта надто небезпечно.",al={"навіщо повернути книгу","чому трактат небезпечний","мета андромата"}},{q="Хто дає це завдання?",a="Це завдання пропонує Верховний Чаклун Андромат, що перебуває у Святилищі Чародія в Кварталі магів Стормвінда.",al={"хто дає завдання","де взяти завдання трактату ура","завдання андромата"}}},fp="29,282,21.515.0,22.395.0,12.383.1,23.135.0,40.123.0,23.145.0,37.174.1,49.186.0,21.118.0"}
P.entries["quest:1939"] = {n="Верховний Чаклун Андромат",s="«Верховний Чаклун Андромат» — короткий виклик, що скеровує магів Альянсу на вершину Святилища Чародія в Стормвінді. Верховний Чаклун Андромат — один із найвидатніших архімагів королівства поза відрізаними рештками Даларана.",h="«Верховний Чаклун Андромат» — короткий виклик, що скеровує магів Альянсу на вершину Святилища Чародія в...",kw={"верховний чаклун андромат","святилище чародія","даларан","дженнея кеннон","маг","архімаг"},ang={["class:Mage"]="Цей виклик позначає ваш перехід від звичних вправ у чаруванні під наглядом Дженнеї Кеннон до безпосередніх досліджень небезпечних, особливих знань разом з одним із провідних архімагів Стормвінда.",["faction:Alliance"]="Поки північні союзники відрізані за захисною сферою Даларана, Альянс значною мірою покладається на власне Святилище Стормвінда, щоб навчати магів і протистояти надприродним загрозам."},sec={{t="Виклик до вежі",b="У Кварталі магів Стормвінда наставниця учнів Дженнея Кеннон скеровує здібних чарівників нагору, на самий верх Святилища Чародія. Верховний Чаклун Андромат, один із найстарших за рангом знавців тайної магії, що досі діють у південних королівствах, особисто бажає зустрітися з молодими магами, готовими до вагоміших обов'язків."},{t="Майстер поза Далараном",b="Північна держава магів Даларан зазнала руйнації в Третій війні, а її вцілілі чарівники замкнулися під непрозорим мерехтливим фіолетовим куполом, — тож маги на кшталт Андромата мають неабияке стратегічне значення. Не маючи вільного доступу до бібліотек Фіалкової Цитаделі, Альянс безпосередньо покладається на старших архімагів у Стормвінді, які вивчають давні загрози й спрямовують дослідження темних, заборонених мистецтв."}},faq={{q="Хто такий Верховний Чаклун Андромат?",a="Верховний Чаклун Андромат — шанований старший маг, що мешкає на самій вершині Святилища Чародія в Стормвінді. Колеги визнають його одним з наймогутніших і найобізнаніших чарівників світу з тих, хто не замкнений у Даларані.",al={"хто такий андромат","андромат лор","верховний чаклун стормвінда"}},{q="Де знайти Верховного Чаклуна Андромата?",a="Він на самій вершині Святилища Чародія — гвинтової вежі в Кварталі магів Стормвінда.",al={"місце андромата","де андромат","знайти верховного чаклуна андромата"}},{q="Чому Дженнея Кеннон посилає мене до нього?",a="Дженнея Кеннон помічає перспективних чарівників, які переросли базову науку, і посилає їх до Андромата по мудру пораду й особливі, небезпечні дослідницькі доручення.",al={"чому говорити з андроматом","дженнея кеннон направляє"}},{q="У чому Андроматові потрібна допомога?",a="Андромат залучає вправних магів до дослідження темних чародійських таємниць — зокрема посилає їх повернути небезпечний давній том: Трактат Ура про Магію Тіні.",al={"лінія завдань андромата","чого хоче андромат"}},{q="Чому кажуть, що Даларан «замкнений»?",a="Після того як Палаючий Легіон спустошив його під час Третьої війни, вцілілі чарівники Кірін-Тору звели над містом непроникний захисний магічний щит і відбудовують його, відгородившись від більшості зовнішніх справ.",al={"чому даларан замкнений","стан даларана","що сталося з дараланом"}},{q="Чи це завдання лише для магів?",a="Так. Цей виклик — частина окремого шляху навчання й завдань для магів Альянсу, які вдосконалюють своє ремесло.",al={"чи не маги можуть це","завдання лише для магів"}}},fp="23,257,20.356.0,24.416.0,31.258.0,41.114.0,42.168.0,35.167.1,42.249.0,33.108.0"}
P.entries["quest:1940"] = {n="Бездоганний Павучий Шовк",s="«Бездоганний Павучий Шовк» — посвятне доручення для молодих магів Альянсу, яке дає Верховний Чаклун Андромат у Стормвінді. Щоб заслужити вбрання, гідне адепта, чарівника відсилають у темні ліси Сутінколісся по найкращий шовк падложерних самітників. Зібрані мотки доставляють кравчині Вінн Ларсон у Кварталі магів, щоб вона пошила зачаровану мантію.",h="«Бездоганний Павучий Шовк» — посвятне доручення для молодих магів Альянсу, яке дає Верховний Чаклун Андромат...",kw={"бездоганний павучий шовк","верховний чаклун андромат","вінн ларсон","сутінколісся","маг","мантія"},ang={["class:Mage"]="Цей обряд посвяти — місток між учнівством і справжньою майстерністю: кожен маг Стормвінда носить мантію, виткану з того, що здобув, власноруч подолавши небезпеку.",["faction:Alliance"]="Сутінколісся лишається небезпечним прикордонням для підданих Стормвінда, тож магам доводиться виходити зі столичного прихистку по рідкісні місцеві ресурси.",["profession:Tailoring"]="Методи Вінн Ларсон показують, як із добірних волокон диких чудовиськ виходять тканини, чутливі до магії, — куди кращі за звичайну овечу вовну чи льон."},sec={{t="Вбрання адепта",b="У Святилищі Чародія визнання вимірюють не лише владою над тайною магією, а й вбранням, яке носять чарівники. Верховний Чаклун Андромат бачить, коли учень переріс звичайну учнівську роботу, і велить йому замовити вбрання, гідне адепта. Маг не може просто купити готову річ: він мусить довести і вправність у полі, і розбірливість, власноруч добувши бездоганний, незаплямований шовк у небезпечних тварин."},{t="Ткацький верстат Сутінколісся",b="Потрібного матеріалу не знайти на звичайних торгових ятках. Його треба обережно добути з отруйних павуків — падложерних самітників, що чатують у примарних сутінках Сутінколісся. Вісім добірних мотків несуть через усе місто до крамниці «Одяг Ларсонів» у Кварталі магів, де кравчиня Вінн Ларсон готова спрясти з тонких ниток мантію, сповнену тайної сили."}},faq={{q="Хто посилає магів на це доручення?",a="Верховний Чаклун Андромат, що очолює Святилище Чародія в Стормвінді, пропонує це завдання чарівникам, які довели свою відданість.",al={"хто дає бездоганний павучий шовк","хто дає завдання","завдання андромата"}},{q="Де збирають шовк?",a="Шовк збирають з падложерних самітників, що никають похмурими лісами й заплетеними павутинням галявинами Сутінколісся.",al={"де брати шовк","місце бездоганного шовку","місце самітників падальниць"}},{q="Хто шиє з шовку робу?",a="Ткацтвом і шиттям займається Вінн Ларсон — кравчиня з крамниці одягу «Ларсон» у Кварталі магів Стормвінда.",al={"хто пряде шовк","вінн ларсон","одяг ларсон"}},{q="Чому маги шиють одяг з павучого шовку?",a="Бездоганний павучий шовк природно міцний і має надзвичайно тонке плетиво, тож з нього виходить легка тканина, здатна втримувати тонкі чари й не обтяжувати чарівника.",al={"чому павучий шовк","магічні робі з павучого шовку"}},{q="Що буде, коли доставити шовк?",a="Оглянувши шовк і попрацювавши за ткацьким верстатом, Вінн вручає магові готове Вбрання Астрального Вузла.",al={"наступне завдання після шовку","що буде далі"}},{q="Чи годиться будь-який павучий шовк із Сутінколісся?",a="Ні. Для тонких чарів, якими славиться крамниця «Ларсон», потрібні саме бездоганні зразки, обережно здобуті з падложерних самітників; грубішого павутиння там не приймають.",al={"чи звичайний шовк годиться","бездоганний чи звичайний шовк"}}},fp="20,381,22.460.0,20.400.0,35.146.0,28.117.0,34.131.0,42.185.0,37.113.0,44.163.0"}
P.entries["quest:1941"] = {n="Маноткана Роба",s="«Маноткана Роба» завершує сміливе кравецьке замовлення в самому серці Стормвінда. Вінн Ларсон вручає готове зачароване вбрання з добірних матеріалів — горду візитівку родинної крамниці. Для молодих чарівників ця роба — один із перших знаків відданості тайній магії й доброї людської майстерності.",h="«Маноткана Роба» завершує сміливе кравецьке замовлення в самому серці Стормвінда.",kw={"маноткана роба","вінн ларсон","одяг ларсонів","квартал магів","кравецтво","маг"},ang={["class:Mage"]="Для молодого мага, що навчається у вежах Стормвінда, вдягти пошиту на замовлення Маноткану Робу — знак переходу до серйозних польових досліджень і самостійного чарування.",["faction:Alliance"]="Споряджаючи перспективних героїв у місцевих крамницях столиці, Стормвінд показує свій престиж і самодостатність у неспокійних краях.",["profession:Tailoring"]="Робота Вінн Ларсон показує високий рівень людського кравецтва: як із земних матеріалів виткати тканину, що приборкує й гартує нестійку тайну силу."},sec={{t="«Одяг Ларсонів»",b="У гамірному Кварталі магів Стормвінда крамниця «Одяг Ларсонів» обслуговує адептів тайних мистецтв, яким потрібне вбрання, здатне проводити нестійкі енергії. Пошиття вишуканого магічного вбрання вимагає рідкісних матеріалів, ретельної голки й пильного ока до ниток, які не розплутаються від містичного резонансу. Вінн Ларсон особисто пишається кожною річчю, що виходить з її крамниці, і вважає кожну мантію, яку носять у мандрах, ходячим свідченням слави імені Ларсонів."},{t="Виткані чари",b="Маноткана Роба створена на допомогу молодим магам: вона дає зручність, свободу рухів і практичну стійкість, потрібну в мандрах спірними землями. Коли потрібні складники доставлено, Вінн сама робить останній стібок і вручає готове вбрання не як звичайний товар, а як шедевр, що має привертати погляди й славити якість кравецтва Ларсонів по всьому королівству."}},faq={{q="Хто шиє Маноткану Робу?",a="Вінн Ларсон шиє її у своїй крамниці одягу «Ларсон» у Кварталі магів Стормвінда.",al={"хто шиє маноткану робу","вінн ларсон роба","одяг ларсон"}},{q="Чому Вінн Ларсон хоче, щоб ви носили робу з гордістю?",a="Вінн вважає цю робу одним зі своїх найкращих витворів. Вона просить шукачів пригод розповідати про крамницю «Ларсон» щоразу, коли хтось милуватиметься роботою, — для неї це жива реклама.",al={"чому носити з гордістю","реклама ларсон","діалог вінн"}},{q="Де розташована крамниця «Ларсон»?",a="Крамниця — у Кварталі магів Стормвінда, неподалік академій і святилищ, де збираються чарівники Альянсу.",al={"місце крамниці ларсон","де вінн ларсон","кравецька крамниця кварталу магів"}},{q="Що за одяг — Маноткана Роба?",a="Це зачарована тканинна роба для практиків магії, пошита так, щоб спрямовувати містичну енергію й водночас бути зручною в небезпечних мандрах.",al={"лор манотканої роби","що таке маноткана роба","що робить роба"}},{q="Чи це частина довшого ланцюжка завдань?",a="Так, це замовлення — останній крок кравецького ланцюжка завдань, у якому ви допомагаєте Вінн Ларсон з матеріалами для її роботи.",al={"ланцюжок маноткана роба","ланцюжок завдань робі","кінець лінії"}},{q="Яка фракція може взятися за це завдання?",a="Це завдання лише для Альянсу, бо Вінн Ларсон працює виключно в столиці — Стормвінді.",al={"роба альянсу чи орди","чи орда отримає маноткану робу","вимога до фракції"}}},fp="14,347,16.468.0,13.412.0,30.95.0,59.208.0,34.134.0,41.159.0,35.135.0,38.123.0"}
P.entries["quest:1942"] = {n="Вбрання Астрального Вузла",s="«Вбрання Астрального Вузла» — вершина відданої кравецької праці в Стормвінді. Подолавши дикі краї, щоб зібрати рідкісний павучий шовк, шукач пригод приносить матеріали вправній кравчині Вінн Ларсон. Результат — вишукана магічна тканина, що пасує і для небезпечних мандрів, і для світських зібрань.",h="«Вбрання Астрального Вузла» — вершина відданої кравецької праці в Стормвінді.",kw={"вбрання астрального вузла","вінн ларсон","павучий шовк","квартал магів","кравецтво","маг"},ang={["class:Mage"]="Вбрання Астрального Вузла поєднує тайну гідність Кварталу магів Стормвінда з практичними чарами, потрібними в мандрах за укріпленими мурами королівства.",["faction:Alliance"]="Ремісники Стормвінда пишаються тим, що постачають героям Альянсу спорядження, гідне і королівських зал, і небезпечної передової.",["profession:Tailoring"]="Робота Вінн Ларсон — вершина майстерності з Бездоганним Павучим Шовком: вона показує, як сировину від чудовиськ можна перетворити на розкішне вбрання."},sec={{t="Дотепність ткалі",b="У гамірному Кварталі магів Стормвінда кравці й швачки обшивають і тайну еліту, і знать, що навідується до міста. Вінн Ларсон — одна з таких майстринь, знана вмінням ткати з Бездоганного Павучого Шовку міцне зачароване вбрання. Вона славиться грайливим гумором і, перш ніж віддати свій майстерно пошитий витвір, жартує, що залишить собі кілька клаптиків дорогоцінного шовку для власного гардеробу."},{t="Вишуканість на всі випадки",b="Вбрання Астрального Вузла цінують чарівники, що носять тканинний одяг і вимагають від нього і стійкості, і вишуканості. Виткане з тонкого, проте міцного шовку, зібраного в небезпечних павуків, це вбрання здатне витримати тяготи бою й водночас зберігає бездоганний вигляд, якого чекають на урочистих бенкетах у Фортеці Стормвінда."}},faq={{q="Що таке Вбрання Астрального Вузла?",a="Це майстерно пошитий одяг від Вінн Ларсон зі Стормвінда. Зроблене з бездоганного павучого шовку, воно призначене для тих, хто носить тканинне вбрання, — і для пригод із боями, і для урочистих світських подій.",al={"що таке вбрання астрального вузла","роба астрального вузла","одяг астрального вузла"}},{q="Хто шиє Вбрання Астрального Вузла?",a="Вінн Ларсон, кравчиня з Кварталу магів Стормвінда, шиє його, щойно отримає потрібні незвичні матеріали.",al={"хто шиє астральний вузол","завдання вінн ларсон","кравець астрального вузла"}},{q="Які матеріали потрібні для цього вбрання?",a="Для вбрання потрібен бездоганний павучий шовк, зібраний зі смертоносних павуків у диких краях світу, і кравецькі прийоми, що зберігають природну міцність шовку та його здатність утримувати чари.",al={"матеріали астрального вузла","потрібний павучий шовк","як це робиться"}},{q="Чому Вінн Ларсон жартує, що лишить собі рештки шовку?",a="Бездоганний павучий шовк надзвичайно рідкісний і цінний серед кравців. Вінн жартує, що могла б пошити вбрання трохи коротшим і приберегти кілька клаптиків для себе, проте віддає роботу повністю.",al={"чи вона вкрала мій шовк","жарт вінн ларсон","коротка роба"}},{q="Де саме в Стормвінді шиють це вбрання?",a="Вінн Ларсон працює в Кварталі магів Стормвінда — кварталі вчених, чародіїв і вузьких майстрів одягу, які знаються на зачарованих тканинах.",al={"де вінн ларсон","місце астрального вузла","куди здати астральний вузол"}},{q="Хто зазвичай носить Вбрання Астрального Вузла?",a="Його здобувають і полюбляють маги Альянсу — за легке захисне плетиво й гідний вигляд.",al={"хто користується астральним вузлом","для якого класу","хто носить"}}},fp="19,317,14.408.0,18.327.0,32.228.0,35.136.0,53.212.0,56.207.0,50.158.0,44.99.0"}
P.entries["quest:1943"] = {n="Поговори з Дейно",s="«Поговори з Дейно» — виклик, що скеровує обдарованих магів Орди до вправної чарівниці в Оргріммарі. Дейно, тролиця-магиня з Долини Духів, шукає адепта для важливої справи на користь їхнього ремесла. Хто відгукнеться на її поклик, тому відкриється шлях до глибшого вивчення магії й важливих доручень по всьому Калімдору.",h="«Поговори з Дейно» — виклик, що скеровує обдарованих магів Орди до вправної чарівниці в Оргріммарі.",kw={"поговори з дейно","дейно","маг","долина духів","анастасія гартвелл","оргріммар"},ang={["class:Mage"]="Це завдання — переломний крок у вашому офіційному арканному навчанні, що пов'язує вас зі старшими заклиначами Оргріммара.",["faction:Horde"]="Цей виклик пов'язує місцевих наставників із Лордерону й Дуротару з арканним проводом, що зосереджується в Оргріммарі.",["race:Troll"]="Дейно втілює зосереджену арканну дисципліну, яку опановують лише обрані з племені Темного Спису."},sec={{t="Виклик до Оргріммара",b="Коли знавці арканного відточують свої вміння в Орді, наставники в Андерсіті й Калімдорі бачать, коли учень готовий до вимогливіших справ. Наставники на кшталт Анастасії Гартвелл в Андерсіті чи Квітаса в Дуротарі скеровують молодих магів до Оргріммара. Там, у кварталі, де переважають тролі, на них чекають особливіші знання й небезпечні доручення."},{t="Долина Духів і Оселя Темного Терну",b="Дейно живе в Оселі Темного Терну в Долині Духів Оргріммара. Серед Темного Спису віддані знавці арканного трапляються порівняно рідко — куди рідше, ніж знахарі й жерці, — тож Дейно — помітний авторитет у столиці. Вона дбає не лише про місцеві справи, а й про ширші інтереси магів Орди й шукає честолюбних чарівників, готових кинути виклик далеким небезпекам."}},faq={{q="Хто посилає поговорити з Дейно?",a="Наставники магів, як-от Анастасія Гартвелл у Магічному Кварталі Андерсіті чи Квітас у Дуротарі, посилають до Оргріммара молодих магів, щойно ті наберуться достатньої вправності.",al={"хто дає завдання","хто це починає","де взяти поговори з дейно"}},{q="Де знайти Дейно?",a="Дейно перебуває в Оселі Темного Терну, що в Долині Духів у західній частині Оргріммара.",al={"місце дейно","де дейно","місце ложі темних шипів"}},{q="Чому Дейно потрібна допомога?",a="Дейно опікується важливими дослідженнями й справами, вкрай потрібними спільноті магів Орди. Вона залучає вправних чарівників, щоб ті вирушали в небезпечні краї по рідкісні магічні ресурси.",al={"чому дейно потрібна допомога","чого хоче дейно"}},{q="Що буде, коли з'явитися до Дейно?",a="Щойно ви з'явитеся до Дейно, вона розповість про свою справу й дасть наступне доручення — почати доведеться з того, щоб набрати Води Ксавіана.",al={"наступне завдання","що буде далі","продовження"}},{q="Чи доступне це завдання всім класам?",a="Ні. Це завдання пропонують лише магам Орди в межах їхнього окремого класового шляху й навчання.",al={"чи лише для магів","чи чорнокнижники можуть це","обмеження класу"}},{q="Чи багато в Орді тролів-магів?",a="Серед тролів Темного Спису чародійська магія трапляється рідше, ніж духовне шаманство, вуду чи служіння лоа. Проте такі постаті, як Дейно, показують, що дехто з тролів досконало опанував вивчення чародійських сил.",al={"тролі-маги орди","маги темних списів лор"}}},fp="16,334,22.391.0,41.411.0,34.164.0,23.111.0,31.186.0,38.141.0,39.118.0,36.217.0"}
P.entries["quest:1944"] = {n="Води Ксавіана",s="«Води Ксавіана» — завдання для магів Орди, яке дає Дейно в Оргріммарі. Прагнучи збагнути прадавні ельфійські таємниці, вона доручає своєму учневі вирушити до руїн Ксавіана в Ашенвалі й набрати зразок води з його найвищого водоспаду.",h="«Води Ксавіана» — завдання для магів Орди, яке дає Дейно в Оргріммарі.",kw={"води ксавіана","дейно","ксавіан","маг","сатири","завдання"},ang={["class:Mage"]="Це завдання — особливий навчальний обряд для магів Орди, що перевіряє, чи здатні вони вирушити у ворожу глушину й здобути неприборкані таємні реагенти.",["faction:Horde"]="Застава Розщепленого Дерева — найближчий плацдарм Орди на сході Ашенвалю, звідки можна вирушати в кишучу сатирами глушину довкола Ксавіана."},sec={{t="Цікавість чарівниці",b="У темних закутках Долини Духів магиня-тролиця Дейно шукає по всьому Калімдору залишкові вмістища первісної таємної сили. Її погляд падає на Ксавіан — прадавнє місто нічних ельфів, заховане глибоко в східних хащах Ашенвалю. Серед учених ходять перекази, що до Розколу місто було просякнуте магічним знанням, а його води, кажуть, досі зберігають могутні таємні властивості, які сучасні чаклуни прагнуть розібрати до найдрібніших подробиць."},{t="Руїни Ксавіана",b="Дістатися джерела цих вод — непросте доручення. Ксавіан більше не належить мирним ельфійським мудрецям: він лежить у руїнах, і його заполонили дикі, зіпсовані сатири, що люто стережуть свою територію від чужинців. Допитливим магам доведеться пробратися повз Сатирнаар і пройти небезпечними протоками, уникаючи і хижих звірів, і демонічних вартових, щоб наповнити флакон Дейно біля підніжжя височенного міського водоспаду."}},faq={{q="Хто така Дейно?",a="Дейно — тролиця, наставниця магів і вчена з Долини Духів в Оргріммарі. Вона навчає магів Орди й досліджує реліквії давньої магії Калімдору.",al={"хто дає води ксавіана","дейно оргріммар"}},{q="Де розташований Ксавіан?",a="Ксавіан — давнє зруйноване місто на північному сході Ашенвалю, на північ від Застави Розщепленого Дерева й трохи на північний захід від твердині сатирів Сатирнаар.",al={"місце ксавіана","де ксавіан","як знайти ксавіан"}},{q="Навіщо Дейно ця вода?",a="За свідченнями вчених, колись Ксавіан зберігав величезні магічні знання, і вважають, що в його водах досі лишилася чародійська сила. Дейно хоче свіжий зразок просто з джерела водоспаду, щоб дослідити його властивості.",al={"навіщо вода ксавіана","мета води ксавіана"}},{q="Які небезпеки стережуть руїни Ксавіана?",a="Руїни кишать сатирами — демонічними, зіпсованими скверною істотами, які ненавидять чужинців і люто боронять свою землю від цікавих магів.",al={"вороги ксавіана","хто керує ксавіаном"}},{q="Де саме набирати зразок води?",a="Зразок треба зачерпнути в Дейнину пляшку з водойми біля самого підніжжя найвищого водоспаду в руїнах Ксавіана.",al={"місце водоспаду","де наповнити флакон","водоспад ксавіана"}},{q="Що далі, коли повернути зразок Дейно?",a="Задоволена зразком води, Дейно посилає мага на наступний етап досліджень — до дріад Ашенвалю, у завданні «Сестри-реготухи».",al={"продовження вод ксавіана","наступне завдання після вод ксавіана"}}},fp="16,230,18.440.0,19.426.0,13.165.0,24.152.0,31.207.0,39.147.0,44.129.0,52.147.1"}
P.entries["quest:1945"] = {n="Сестри-реготухи",s="«Сестри-реготухи» — завдання Орди, яке посилає магів у серце Ашенвалю по зачаровані пасма волосся диких дріад. Матеріал призначено для Кіл'гали, досвідченого кравця-троля на Перехресті, який спряде з нього посилену мантію мага. Полювання на доньок Кенарія підкреслює невпинне тертя між чаклунами Орди та споконвічними захисниками прадавнього лісу.",h="«Сестри-реготухи» — завдання Орди, яке посилає магів у серце Ашенвалю по зачаровані пасма волосся диких дріад.",kw={"сестри-реготухи","дріади","кіл'гала","дейно","кравецтво","маг","завдання"},ang={["class:Mage"]="Цей обряд посвяти вчить молодих магів, що навіть священних лісових духів Ашенвалю можна використати як матеріал для чарівного ремесла.",["faction:Horde"]="Убивство дріад Ашенвалю загострює конфлікт між загарбницькою присутністю Орди та священними охоронцями лісу, вірними нічним ельфам.",["profession:Tailoring"]="Завдання показує рідкісне мистецтво вплітати живі чарівні волокна в тканинний обладунок — майстерний прийом, яким володіє Кіл'гала на Перехресті."},sec={{t="Таємне ткацтво",b="Після того як молоді маги здобули зіпсовану воду з Ксавіана, Дейно в Оргріммарі посилає їх допомогти пошити власні зачаровані шати. Таке чарівне кравецтво вимагає матеріалів, сповнених сирої магічної сутності. Пасма дріад, природно просякнуті первісною життєвою силою лісу, мають усе потрібне, щоб виткати складні чарівні вбрання, здатні захищати чаклуна й посилювати його силу."},{t="На полюванні в Рейнвуді",b="Щоб здобути ці пасма, магам доведеться вирушити на південь, до Притулку Рейнвуд в Ашенвалі. Сестри-реготухи — моторні лісові дріади, союзниці нічних ельфів — люто стережуть ці гаї і від лісорубів, і від будь-яких чужинців. Лісові чарівні істоти ніколи добровільно не віддадуть свого волосся чаклунам Орди, тож за здобич неминуче доводиться платити кров'ю під покровом прадавніх дерев."},{t="Право ткалі",b="Зібрані пасма несуть на південь через кордон, до курного поселення Перехрестя в Пустках. Там кравець-троль Кіл'гала без жодних докорів сумління приймає цю данину. Ледь іронічно визнаючи втрату лісових створінь, Кіл'гала не гає часу й одразу пускає зачаровані пасма в діло, бо знає: сила в Орді часто вимагає непохитної рішучості."}},faq={{q="Хто дає завдання полювати на сестер-реготух?",a="Дейно, тролиця-маг з Оселі Темного Терну в Оргріммарі, посилає магів у це доручення як нагороду й підготовку до виготовлення їхніх класових роб.",al={"хто дає сестер-реготух","хто дає завдання сестри-реготухи","завдання дейно"}},{q="Хто такі реготливі сестри?",a="Реготливі сестри — дріади, доньки напівбога Кенарія. Верхня частина тіла в них, як у жінок з нічних ельфів, а нижня — як у оленят; вони оберігають ліси й священні галявини Ашенвалю.",al={"що таке реготлива сестра","реготлива сестра дріада","чи реготливі сестри дріади"}},{q="Де знайти реготливих сестер?",a="Вони блукають лісами біля Притулку Рейнвуд і галявини Реготливої Сестри в центральному Ашенвалі, неподалік торгового шляху.",al={"місце реготливих сестер","де реготливі сестри","де знайти реготливих сестер"}},{q="Навіщо Кіл'галі волосся дріад?",a="Волосся дріад просякнуте природними чарами, тож це ідеальна нитка, яку Кіл'гала вплітає в особливі роби з магічним резонансом для чародійських мистецтв.",al={"чому волосся дріад","чому волосся реготливої сестри","навіщо волосся"}},{q="Куди нести зібране волосся?",a="Віднесіть волосся Кіл'галі — майстрові-кравцю з гамірної застави Перехрестя в Пустках.",al={"де кіл'гала","здати сестер-реготух","кравчиня чорнокнижників перехрестя"}},{q="Що буде, коли Кіл'гала візьме волосся?",a="Отримавши волосся, Кіл'гала трохи працює з матеріалом, а тоді пропонує наступне завдання — «Вбрання з Мережива Нижнього Світу», щоб завершити робу.",al={"наступне завдання після сестер-реготух","після сестер-реготух","продовження вбрання з мережива"}}},fp="16,400,18.441.0,18.412.0,24.410.0,51.141.0,30.199.0,40.135.0,34.164.0,49.117.0,43.160.0"}
P.entries["quest:1946"] = {n="Вбрання з Мережива Нижнього Світу",s="«Вбрання з Мережива Нижнього Світу» завершує особливу ремісничу роботу кравця Кіл'гали в Пустках. Вплітаючи зібране волосся дріад у тонку тканину, кравець створює зачароване вбрання, гідне заклиначів.",h="«Вбрання з Мережива Нижнього Світу» завершує особливу ремісничу роботу кравця Кіл'гали в Пустках.",kw={"вбрання з мережива нижнього світу","кіл'гала","дейно","дріади","маг","кравецтво"},ang={["class:Mage"]="Вбрання з мережива Нижнього Світу — важлива віха для магів, що зростають у силі: воно поєднує випробування в дикому Ашенвалі з майстерністю Кіл'гали під наглядом Дейно.",["faction:Horde"]="Збирання складників у священних лісах Калімдору, щоб спорядити заклиначів Орди, показує тривале суперництво між Ордою й лісовими оборонцями Ашенвалю.",["profession:Tailoring"]="Ремесло Кіл'гали показує, як екзотичні складники на кшталт волосся дріад можна спрясти в тканину з природним магічним захистом."},sec={{t="Плетіння мережива Нижнього Світу",b="Кіл'гала, що працює на Перехресті в Пустках, береться за тонку справу — виготовлення мережива Нижнього Світу. Для цього потрібні рідкісні складники, що відгукуються на магію, — а саме коси, зрізані з дріад, яких в Ашенвалі звуть регітливими сестрами. Так кравець вплітає природні лісові чари просто в зручну, міцну тканину."},{t="Послуги для Оргріммара",b="Кіл'гала не просто займається своїм ремеслом — у нього є й особисті причини дбати про якість вбрання. Він дуже хоче догодити Дейно, шанованій тролиці-магині з Долини Духів в Оргріммарі. Шиючи виняткове вбрання для молодих заклиначів, Кіл'гала сподівається здобути й зберегти прихильність Дейно."}},faq={{q="Що таке мереживо Нижнього Світу?",a="Мереживо Нижнього Світу — зачарована тканина, яку виготовляє Кіл'гала. Її ткуть з магічних матеріалів, а саме з кіс реготливих сестер, тож вона й міцна, і природно сповнена чародійського резонансу.",al={"мереживо нижнього світу","що таке вбрання з мережива"}},{q="Хто шиє Вбрання з Мережива Нижнього Світу?",a="Кіл'гала, вправний кравець Орди з Перехрестя в Пустках, шиє вбрання, щойно отримає потрібне волосся дріад з Ашенвалю.",al={"хто шиє мереживо","кіл'гала мереживо нижнього світу"}},{q="Чому Кіл'гала згадує Дейно?",a="Дейно — впливова тролиця, наставниця магів, що живе в Долині Духів в Оргріммарі. Кіл'гала дуже хоче бути в неї на доброму рахунку й сподівається, що ваше задоволення його роботою прислужиться його репутації.",al={"хто така дейно","чому дейно"}},{q="Звідки взялися матеріали для вбрання?",a="Головний матеріал — волосся реготливих сестер, невловних дріад, що живуть у лісах Ашенвалю.",al={"матеріали мережива","волосся дріад тканина"}},{q="Для кого шиють це вбрання?",a="Передусім для чарівників, особливо магів-учнів, яким потрібні роби, що спрямовують чародійську енергію й не сковують рухів.",al={"хто користується мереживом","клас мережива"}},{q="Де знайти Кіл'галу?",a="Кіл'гала живе на Перехресті — поселенні на перетині шляхів у самому серці Пусток.",al={"місце кіл'гали","де кіл'гала"}}},fp="19,223,23.343.0,20.351.0,20.207.0,35.155.0,32.208.0,50.126.0,29.151.0,26.107.0"}
P.entries["quest:1950"] = {n="Вивідати подробиці",s="Магус Тірт замкнув важливу книгу заклять у магічно запечатаній скрині, але не може пригадати фразу, що її відмикає. Щоб дістати том, вам доведеться розшукати його зниклого учня десь біля траси в Мерехтливих Низинах і вивідати в нього забуті слова.",h="Магус Тірт замкнув важливу книгу заклять у магічно запечатаній скрині, але не може пригадати фразу, що її...",kw={"вивідати подробиці","магус тірт","джонсон","курка","перевтілення","мерехтливі низини"},ang={["class:Mage"]="Справа з Тіртом — кумедне, але повчальне видовище небезпек прокляття перевтілення й тієї неуважності, що може спіткати могутніх учених."},sec={{t="Магус і його пам'ять",b="Магус Тірт — дивакуватий чарівник, що мешкає на потрісканому соляному дні Мерехтливих Низин у Тисячі Голок. Він має езотеричні знання й томи, яких відчайдушно шукають маги, що прагнуть зростати, але мати з ним справу — випробування терпіння. Тірт покладається на помічника в усіх буденних дрібницях, зокрема й у паролях, що стережуть його чародійські сховища. Тож маги, яким доручено забрати книгу сили, швидко дізнаються: Тірт замкнув том за чарівними словами, які геть вилетіли йому з голови."},{t="Куряча справа",b="Щоб розшукати учня Тірта, Джонсона, мало просто блукати загонами біля Перегонів Міражу. Розпитавши гоблінів і гномів, що порядкують на трасі, дізнаєшся, що Джонсон став жертвою класичної професійної небезпеки на службі в химерного чарівника: перетворення. Зачарований господарем у звичайнісіньку курку, Джонсон блукає солончаками й не може вимовити ні слова — доки поруч не опиниться мандрівник і на мить не розвіє магічний туман, щоб той зміг прокудкудакати забутий пароль."}},faq={{q="Хто такий Магус Тірт?",a="Магус Тірт — відлюдний чарівник з людей, що живе біля Перегонів Міражу в Мерехтливих Низинах Тисячі Голок. Він має глибокі чародійські знання, по які приходять маги, що прагнуть удосконалити ремесло.",al={"лор тірта","хто такий магус тірт","тірт мерехтливі рівнини"}},{q="Чому Тіртові потрібен пароль до власної скриньки?",a="Тірт замкнув свою скриньку магічно, на промовлену фразу, а такі буденні дрібниці, як паролі, мав пам'ятати його помічник. Розсіяний, як завжди, він забув слова, щойно учень зник.",al={"чому тірт забув","пароль скриньки тірта"}},{q="Куди подівся учень?",a="Джонсон утік недалеко. Він блукає біля перегонової траси на схід від табору Тірта, але знайти його непросто, бо Тірт перетворив його на курку.",al={"знайти помічника тірта","де учень","місце учня"}},{q="Чому учня перетворили на курку?",a="Тірт наклав на Джонсона прокляття, а тоді забув про це. Дізнавшись, що сталося з помічником, Тірт невиразно припускає, що невдячний учень на це заслужив.",al={"чому учень курка","тірт перетворив учня"}},{q="Що в скриньці Тірта?",a="У магічно замкненій скрині — книга з ритуалами й настановами, потрібними для подальшого навчання мага та виготовлення магічного знаряддя.",al={"вміст скриньки тірта","яка книга в скрині"}},{q="Хто може взятися за це доручення?",a="Це доручення — частина окремого випробування лише для магів, які шукають особливої науки й матеріалів, щоб виготовити могутню чарівну паличку.",al={"чи не маги можуть вивідати подробиці","чи лише для магів"}}},fp="13,283,22.549.0,9.526.1,19.201.0,48.218.0,28.167.1,45.186.1,33.143.0,28.138.0"}
P.entries["quest:1959"] = {n="Доповісти Анастасії",s="«Доповісти Анастасії» — поклик, який отримують маги Орди, що набираються сили в Калімдорі та Східних Королівствах. Анастасія Гартвелл, знана чарівниця з Магічного Кварталу Андерсіті, помітила в місті невідоме магічне збурення, і їй потрібні вправні чарівники, щоб його розслідувати.",h="«Доповісти Анастасії» — поклик, який отримують маги Орди, що набираються сили в Калімдорі та Східних...",kw={"доповісти анастасії","анастасія гартвелл","маг","магічний квартал","андерсіті","аптекаріум","таємна магія"},ang={["class:Mage"]="Це завдання — важлива віха для магів Орди: воно виводить їх із місцевих навчальних застав і знайомить із глибшими таємницями — і небезпеками — таємної магії, що визрівають під руїнами Лордерона.",["faction:Horde"]="Цей поклик показує співпрацю між Відступниками й рештою Орди: магічні таланти всіх її народів служать захистові спільних інтересів.",["race:Undead"]="Магів-Відступників кличуть додому, до Магічного Кварталу Андерсіті, щоб допомогти вберегти їхнє молоде королівство від невидимих магічних загроз у його власних стінах."},sec={{t="Поклик таємної магії",b="Звістки серед чарівників Орди ширяться швидко. Чи то навчаючись на кручах Тандер Блафа, чи в запиленій спеці Дуротару, чи серед руїн Лордерона, достатньо обдаровані маги отримують чіткий наказ. Знавці таємної магії в Андерсіті відчули незбагненне збурення, що прокочується їхніми володіннями, і їм потрібна допомога на місці."},{t="Чарівниця Андерсіті",b="Анастасія Гартвелл опікується справами таємної магії з Магічного Кварталу Андерсіті. Коли маг прибуває, вона підтверджує тривожні вісті: у підземному місті зафіксовано аномальну енергію. Природа цієї магії досі зовсім невідома — не доведено ні що вона нешкідлива, ні що відверто ворожа, — тож Анастасії потрібен вправний чарівник, щоб тихо розшукати її джерело, почавши з міського Апотекаріуму."}},faq={{q="Хто така Анастасія Гартвелл?",a="Анастасія Гартвелл — маг і чародійська наставниця з Відступників, що працює в Магічному Кварталі Андерсіті. Вона веде молодих практиків і пильно стежить за чародійськими аномаліями в столиці Відступників.",al={"лор анастасії гартвелл","хто така анастасія","гартвелл андерсіті"}},{q="Де перебуває Анастасія Гартвелл?",a="Вона в Магічному Кварталі Андерсіті, у північній дузі підземного міста, серед інших наставників-чарівників і чародійських дослідників.",al={"де анастасія","місце гартвелл","мапа анастасії в андерсіті"}},{q="Чому магів з Тандер Блафа чи Пусток кличуть до Андерсіті?",a="Відступники мають власних фахівців-чародіїв, але незвичні магічні аномалії загрожують усій присутності Орди в Лордероні. Наставники на Калімдорі посилають своїх перспективних учнів до Андерсіті, щоб ті допомогли й набули практичного досвіду зі складними магічними явищами.",al={"чому їхати до андерсіті","чому доповісти анастасії","завдання мага тандер блафа"}},{q="Яке збурення розслідує Анастасія?",a="Маги виявили в місті незрозумілі магічні коливання. На час виклику Анастасія Гартвелл ще не з'ясувала, чи ця енергія ворожа, випадкова чи нешкідлива, тож починає обережне розслідування.",al={"яке збурення","магічне збурення андерсіті","що негаразд в андерсіті"}},{q="Хто дає це завдання?",a="Цей виклик можуть передати різні наставники магів Орди, щойно чарівник набереться досвіду, зокрема Утел'най в Оргріммарі, Терстон Ксейн у Тандер Блафі, Кейн Файрсонг у Бріллі та Ун'Тува в Селі Сен'джин.",al={"хто дає доповісти анастасії","хто починає доповісти анастасії"}},{q="Що буде, коли з'явитися до Анастасії?",a="Поговоривши з Анастасією й вислухавши її, ви одразу отримуєте доручення глибше дослідити збурення — почати доведеться з Апотекаріуму міста, у завданні «Обстежити крамницю алхіміка».",al={"наступне завдання після доповіді","продовження доповісти анастасії"}}},fp="19,292,20.385.0,25.418.0,26.229.0,36.183.0,80.273.0,52.238.0,21.220.0,42.221.0"}
P.entries["quest:1960"] = {n="Розслідування в алхімічній крамниці",s="«Розслідування в алхімічній крамниці» — завдання в Андерсіті для магів Орди, яким належить розібратися з магічною аномалією в Апотекаріумі. Під проводом Анастасії Гартвелл заклиначі вистежують і ловлять невидимих істот із чистої магічної енергії, що розгулюють крамницею Алджернона.",h="«Розслідування в алхімічній крамниці» — завдання в Андерсіті для магів Орди, яким належить розібратися з...",kw={"розслідування в алхімічній крамниці","анастасія гартвелл","алджернон","аптекаріум","заклинання прояву","породження розлому","маг"},ang={["class:Mage"]="Це завдання перевіряє, як учень володіє чистою магічною силою: тут потрібні особливі заклинання прояву й посудини для утримання, а не лише руйнівна міць.",["race:Undead"]="Хоч аптекарі-Відступники здебільшого зосереджені на алхімії й чумах, це завдання показує, як пильно магічні вчені Андерсіті оберігають місто від магічного проникнення."},sec={{t="Неспокій в Апотекаріумі",b="Андерсіті не звикати до неприродних явищ, але нещодавно в Апотекаріумі виникла проблема суто магічного походження. В алхімічній крамниці Алджернона помітили незримих магічних істот, що безгучно блукали між булькотливими казанами й отруйними реагентами. Розпізнавши неприродний розрив у потоці магії, наставниця магів Андерсіті Анастасія Гартвелл посилає здібних учнів розслідувати справу й приборкати істот, перш ніж ті завдадуть непоправної шкоди."},{t="Прояв і утримання",b="Оскільки істоти невидимі й цілком складаються з сирої магічної сили, звичайні способи вистежування марні. Анастасія дає учням особливе Заклинання Прояву, що знімає з істот невидимість, і міцні скриньки зберігання. Щойно породження розлому проявляться, їх треба здолати й надійно запечатати в скриньках, перш ніж вони розпадуться ще більше чи зашкодять алхімікам за роботою."},{t="Випадковість чи напад?",b="Коли зразки впіймано, Анастасію починає турбувати їхнє походження. Мимовільний розрив у потоці магії — уже тривожно, але навмисний прорив означав би діяльний, злагоджений магічний напад на столицю Відступників. Упійманих істот передають на вивчення, щоб з'ясувати, чи Апотекаріум просто спіткав магічний нещасний випадок, чи він опинився на передовій цілеспрямованої загрози."}},faq={{q="Хто дає це завдання і де його знайти?",a="Це завдання пропонує Анастасія Гартвелл — наставниця магів у Магічному Кварталі Андерсіті.",al={"хто дає завдання","де почати","місце анастасії"}},{q="Де відбувається збурення?",a="Збурення зосереджене довкола алхімічної крамниці Алджернона в кварталі Апотекаріуму в Андерсіті.",al={"куди йти","місце алхімічної крамниці","де алджернон"}},{q="Що за істоти никають крамницею?",a="Це породження розлому — невидимі істоти, цілковито складені із зосередженої магічної енергії, що з'явилися через аномалію в місцевих магічних потоках.",al={"які це монстри","невидимі істоти","породження розколини"}},{q="Як упіймати цих істот?",a="Треба прочитати в крамниці Заклинання Прояву, щоб виявити породження розлому, послабити їх закляттями, а тоді скористатися скринькою-пасткою, щоб замкнути їх усередині.",al={"як упіймати їх","як користуватися скринею","як завершити"}},{q="Чому Анастасія хоче впіймати цих істот живими?",a="Анастасії та вченим Андерсіті потрібні живі зразки, щоб з'ясувати, чи цей розрив у магії — природний, випадковий розлам, чи навмисний напад на місто якоїсь сторонньої магічної сили.",al={"чому впіймати їх","призначення скринь утримання","навіщо їх вивчати"}},{q="Чи можуть це завдання виконати інші класи, крім магів?",a="Ні, це завдання — частина раннього навчання лише для магів Орди.",al={"лише маги","хто може взяти це завдання"}}},fp="30,277,33.479.0,29.435.0,27.417.1,46.109.0,33.123.0,42.144.0,33.168.0,55.195.0,43.101.0"}
P.entries["quest:1961"] = {n="Збір матеріалів",s="«Збір матеріалів» — обряд посвяти для молодих магів Орди, що навчаються в Андерсіті. Анастасія Гартвелл посилає учнів у Срібнолісся, щоб відібрати магічні самоцвіти в чарівників Даларана й зібрати все потрібне для першої справжньої мантії мага.",h="«Збір матеріалів» — обряд посвяти для молодих магів Орди, що навчаються в Андерсіті.",kw={"збір матеріалів","анастасія гартвелл","самоцвіт мани з даларана","йозеф ґреґоріан","амбермілл","мантія","маг"},ang={["class:Mage"]="Це завдання — переломна мить для магів Орди: ви змінюєте просте учнівське вбрання на пошиту на замовлення мантію, в яку вплетено здобуту магічну силу.",["profession:Tailoring"]="Цей процес показує, як звичайне лляне полотно можна поєднати з могутніми самоцвітами мани, щоб створити міцний зачарований одяг.",["race:Undead"]="Це завдання показує безжальний світогляд Відступників: колишня спорідненість із чарівниками Даларана не дає їм жодної пощади, якщо ці живі маги надто слабкі, щоб утримати Срібнолісся."},sec={{t="Обряд магічного визнання",b="У магічних покоях Магічного Кварталу маги-початківці мусять довести, що володіють не лише сирими заклинаннями. Щоб заслужити свою першу справжню мантію — офіційне вбрання, яке засвідчує їхнє становище й особисту гідність, — учні за вказівкою Анастасії Гартвелл мають здобути сировину для зачарованої тканини: сувій простого лляного полотна й кілька могутніх Самоцвітів Мани з Даларана."},{t="Прагматизм Відступників",b="Самоцвіти мани не можна просто купити чи створити чарами: їх доводиться виривати в магів Даларана, що стоять у Срібноліссі, особливо довкола Амбермілла. Анастасія Гартвелл холодно зауважує, що хоч магічні вчення Даларана й перегукуються з їхніми власними, сентиментальним ваганням в Андерсіті не місце. В очах Відступників, якщо живі чарівники не здатні захистити свої реліквії, вони втрачають і скарби, і життя."},{t="Кравець Магічного Кварталу",b="Зібрані полотно й самоцвіти доставляють Йозефові Ґреґоріану — кравцеві з Магічного Кварталу. Ґреґоріан охоче визнає, що йому бракує магічного хисту, щоб оцінити бездоганну якість зачарованих каменів Даларана, але він володіє рідкісною майстерністю, потрібною, щоб уплести їхню сиру силу просто в тканину мантії."}},faq={{q="Яка мета завдання «Збір матеріалів»?",a="Це завдання — посвята для магів Орди. Виконавши його, ви постачаєте кравцеві Йозефові Ґреґоріану потрібні складники — полотно й самоцвіти мани, — щоб пошити новачкові його першу справжню зачаровану мантію.",al={"навіщо збір матеріалів","мета збору матеріалів","завдання робі мага андерсіті"}},{q="Чому Анастасія Гартвелл посилає вас по магів Даларана?",a="Чарівники Даларана, що стоять у Срібноліссі, носять очищені самоцвіти мани, здатні спрямовувати потужні магічні потоки. Гартвелл дивиться на цих живих магів прагматично: попри спільне інтелектуальне коріння, слабкість у полі означає, що їхні життя й припаси дістаються Відступникам.",al={"чому вбивати магів даларана","лор самоцвітів мани даларана","чому маги сільверпайна"}},{q="Де шукати чарівників Даларана?",a="Їх можна зустріти в Срібноліссі: вони займають застави й угіддя на південний схід від Гробниці, довкола поселення Амбермілл.",al={"де самоцвіти мани даларана","місце магів сільверпайна","маги амбермілла"}},{q="Хто такий Йозеф Ґреґоріан?",a="Йозеф Ґреґоріан — кравець-нежить, що працює в Магічному Кварталі Андерсіті. Він майстер, а не чарівник, але спеціалізується на шитті зачарованого одягу, як-от мантій чарівного вогню.",al={"йозеф ґреґоріан андерсіті","хто кравець у кварталі магів","кравець ґреґоріан"}},{q="Що шиють з цих матеріалів?",a="З полотна й даларанських самоцвітів мани Йозеф Ґреґоріан шиє Мантію Чарівного Вогню — класичне вбрання, що знаменує перехід учня до звання справжнього мага.",al={"яку робу отримаєш","роби вогню чар нагорода","нагорода роба збору матеріалів"}},{q="Чому Анастасії трохи неприємно вбивати магів Даларана?",a="Багато чарівників-Відступників, зокрема й сама Гартвелл, за життя навчалися за даларанськими традиціями й поділяють схожі інтелектуальні й магічні погляди. Проте, попри цю спорідненість, виживання й потреба беруть гору над почуттями.",al={"почуття гартвелл до даларана","відступники проти даларана","лор анастасії гартвелл"}}},fp="19,297,25.384.0,26.464.0,31.334.0,43.208.0,57.284.0,38.149.0,23.214.0,44.158.0,67.222.0"}
P.entries["quest:1962"] = {n="Мантія Чарівного Вогню",s="«Мантія Чарівного Вогню» — завершальний обряд у навчанні молодих магів Орди в Андерсіті, який довершує кравець Йозеф Ґреґоріан. Зібравши рідкісні складники в різних куточках світу, учень отримує зачароване вбрання, пошите на замовлення, — знак дедалі більшої влади над магією.",h="«Мантія Чарівного Вогню» — завершальний обряд у навчанні молодих магів Орди в Андерсіті, який довершує...",kw={"мантія чарівного вогню","йозеф ґреґоріан","кравецтво","магічний квартал","маг","андерсіті"},ang={["class:Mage"]="Здобути цю мантію — один із перших обрядів посвяти для заклиначів Орди: вона дає вам пошите на замовлення вбрання, що витримує нестійку енергію вогню й магії.",["profession:Tailoring"]="Це завдання показує, як звичайну тканину підсилюють незвичними реагентами, щоб вона витримувала й підсилювала потужні магічні потоки.",["race:Undead"]="Заклиначі-Відступники в Андерсіті зберігають магічну дисципліну на зразок даларанської, поєднуючи давні магічні традиції з новим існуванням серед руїн Лордерона."},sec={{t="Шати мага",b="Для учнів, що опановують магічні мистецтва в Лордероні, звичайні плащі й буденний одяг майже не допомагають спрямовувати сирі потойбічні сили чи захищатися від них. Йозеф Ґреґоріан, кравець із Магічного Кварталу Андерсіті, тче справжнє магічне вбрання з особливих матеріалів, які збирають здібні заклиначі Орди. Останній стібок Мантії Чарівного Вогню знаменує перехід учня від простих заклинань до визнаного чародія, що володіє і чистою магією, і вогнем."},{t="Вплетена сила",b="Пошити вбрання, здатне безпечно зосереджувати потужну магію, — вимоглива справа. Це не просто кравецтво: для таких мантій потрібні особливі алхімічні й магічні складники, здобуті в небезпечних випробуваннях. Коли все зібрано й принесено до майстерні Ґреґоріана, кравець одразу сплітає складники докупи й дарує молодому магові відчутний знак становища й захисту."}},faq={{q="Яка мета завдання «Мантія Чарівного Вогню»?",a="Це останній крок раннього класового обряду для магів Орди: зібравши для кравця Йозефа Ґреґоріана складники, вони отримують особливо зачаровану мантію.",al={"мета мантії чарівного вогню","що робить мантія чарівного вогню","навіщо це завдання"}},{q="Хто такий Йозеф Ґреґоріан?",a="Йозеф Ґреґоріан — кравець з Відступників, що працює в кравецькій майстерні Магічного Кварталу в Андерсіті. Він шиє перший справжній класовий одяг для новоспечених магів, яких посилає до нього Анастасія Гартвелл.",al={"хто такий йозеф","хто шиє робу","йозеф ґреґоріан андерсіті"}},{q="Де відбувається це завдання?",a="Усе відбувається в Магічному Кварталі Андерсіті, просто в кравецькій майстерні Йозефа Ґреґоріана.",al={"місце мантії чарівного вогню","куди здати мантію чарівного вогню"}},{q="Чому для цього завдання не треба нікуди йти?",a="Усю роботу ви виконали в попередньому дорученні — «Збір матеріалів». Щойно ви віддасте Йозефові реагенти, він за мить шиє вбрання й одразу вручає вам готову мантію.",al={"чому миттєво","як виконати мантію чарівного вогню","автозавершення роби"}},{q="Чи можуть цю мантію отримати інші класи, крім магів?",a="Ні. Увесь ланцюжок завдань і зачароване вбрання, яке він дає, — лише для магів, що служать Орді.",al={"чи лише для магів","чи чорнокнижник може отримати","хто може виконати мантію чарівного вогню"}},{q="З яких матеріалів шиють цю мантію?",a="Мантію шиють з рідкісних припасів, зібраних у попередньому завданні: полотна й даларанських самоцвітів мани, здобутих у магів Кірін-Тору в Срібноліссі.",al={"що йде на робу","інгредієнти роби","здавання збору матеріалів"}}},fp="15,301,17.487.0,11.426.0,49.191.0,23.199.0,33.120.0,62.209.0,48.110.0,49.183.0"}
P.entries["quest:1963"] = {n="Розтрощена Рука",s="Це випробування розбійника, яке дає Терзок у Тіньовій Розколині, перевіряє посвячених, що прагнуть вступити до таємної гільдії Розтрощеної Руки. Щоб довести свою смертоносну вправність, розбійники-початківці мусять вистежити троля-контрабандиста Тазана й забрати його замкнену сумку.",h="Це випробування розбійника, яке дає Терзок у Тіньовій Розколині, перевіряє посвячених, що прагнуть вступити...",kw={"розтрощена рука","терзок","тазан","раджет","контрабандист","розбійник"},ang={["class:Rogue"]="Цей обряд посвяти вводить юних розбійників Орди до лав Розтрощеної Руки й ставить безжальну вправність, убивства й користь вище за відкритий бій.",["faction:Horde"]="Розтрощена Рука уособлює ідейні тертя в Оргріммарі, де потаємні угруповання тихо кидають виклик обережному баченню Тралла щодо молодої Орди."},sec={{t="Тіні в Розколині",b="Під гамірними вулицями Оргріммара лежить підземний морок Тіньової Розколини. Тут діє Розтрощена Рука — таємний орден убивць і злодіїв, що сягає корінням давніх оркських традицій. Поки Вождь Тралл проповідує честь, дипломатію й обачність у правлінні молодою Ордою, провід Розтрощеної Руки вважає, що така нерішучість послаблює їхній народ. Вони прагнуть повернути бойову першість таємним насильством — ножами й отрутою там, де атака на полі бою може не вдатися."},{t="Доля контрабандиста",b="Щоб відсіяти незграбних і слабких, куратор Терзок пропонує простий контракт: усунути Тазана, свавільного троля, що діє в Пустках біля Раджета. Тазан торгує з прибережними піратами й володіє делікатними відомостями, яких прагне гільдія. Здобута замкнена сумка підтверджує, що розбійник уміє вистежити здобич за міськими мурами, хоча щоб дістати її вміст, знадобиться ще більше вправності."}},faq={{q="Що таке Розтрощена Рука в Оргріммарі?",a="Розтрощена Рука — таємна гільдія розбійників, розвідників і вбивць Орди, що діє з Тіньової Розколини в Оргріммарі. Колись це був давній орчий клан, відомий жорстоким самокалічінням, а в сучасній Орді вони — тіньова мережа розвідки й ліквідацій, що віддає перевагу безжальному прагматизмові над обережною дипломатією Тралла.",al={"хто такі розтрощена рука","розбійники розтрощеної руки","мета розтрощеної руки"}},{q="Хто такий Терзок?",a="Терзок — куратор Розтрощеної Руки в Тіньовій Розколині. Він випробовує майбутніх розбійників, щоб переконатися, що ті мають хитрість і смертоносність, потрібні для служби гільдії, і відкрито скептично ставиться до стриманості Тралла.",al={"роль терзока","хто дає завдання","терзок оргріммар"}},{q="Чому Терзок хоче смерті Тазана?",a="Тазан — троль-контрабандист, що веде незаконну торгівлю з піратами Південних Морів біля порту Раджет. Хай яку контрабанду він возить, у його торбі ще й важливі відомості, які Розтрощена Рука хоче мати для власних таємних операцій.",al={"чому вбити тазана","лор тазана","що зробив тазан"}},{q="Де шукати Тазана?",a="Тазан діє в Пустках — никає біля узбережжя й піратських схованок на південь від Раджета.",al={"місце тазана","де тазан","знайти тазана"}},{q="Що буде, коли здобути торбу Тазана?",a="Коли торбу приносять Терзокові, з'ясовується, що вона замкнена. Задоволений загибеллю Тазана, але потребуючи відомостей усередині, Терзок робить із цього наступну перевірку — чи вміє розбійник відмикати замки.",al={"наступне завдання","замкнена торба","що робити з торбою"}},{q="Чи знає Тралл про методи Розтрощеної Руки?",a="Формально Розтрощена Рука служить Орді, але її члени діють здебільшого з тіні й зневажають обережне керівництво Тралла. Вони тихцем розбудовують власні розвідувальні мережі, щоб усувати загрози, перш ніж дипломатія Вождя загальмує справу.",al={"тралл і розтрощена рука","чи вождь схвалює","тралл і розбійники"}}},fp="18,266,20.505.0,17.421.1,40.345.0,15.226.0,33.250.0,23.97.0,46.211.1,52.286.0"}
P.entries["quest:1978"] = {n="Смертолови",s="Це доручення знаменує офіційний вступ здібного агента до лав скрадачів смерті — ордену вбивць і шпигунів Відступників. Доставивши Гросбух Андрона просто жахолордові Варіматрасу, гонець передає докази таємної діяльності Синдикату найвищому проводові Андерсіті.",h="Це доручення знаменує офіційний вступ здібного агента до лав скрадачів смерті — ордену вбивць і шпигунів...",kw={"скрадачі смерті","гросбух андрона","синдикат","варіматрас","альтерак","королівський квартал"},ang={["class:Rogue"]="Ця посвята — офіційний вступ до розбійницьких лав Відступників: прості кишенькові злодюжки стають агентами державної розвідки.",["faction:Horde"]="Хоч це внутрішня справа безпеки Відступників, нагляд за людськими рештками Альтераку захищає північні землі Орди від підривних диверсій.",["race:Undead"]="Для Відступників вступ до скрадачів смерті — пряма присяга оберігати хитку незалежність Лордерона від уцілілих людей і зрадників, що причаїлися."},sec={{t="Посвята в тінях",b="Після того як агент здобув викривальні записи Андрона Ґанта, Меннет Каркад офіційно приймає його до скрадачів смерті. Ця організація — очі, вуха й кинджали Леді Сильвани по всьому Лордерону: вона покладається на розвідувальні мережі, безжальну дієвість і скритність, щоб усувати загрози, перш ніж ті вийдуть на світло. Офіційне визнання в ордені — великий рубіж для кожного молодого розбійника чи розвідника в Андерсіті."},{t="Слід Синдикату",b="Здобич цього таємного розслідування — Гросбух Андрона, що викриває незаконні зв'язки місцевих агентів із Синдикатом. Колись Синдикат був шляхетною аристократією занепалого людського королівства Альтерак, але після краху свого королівства в Другій війні вдався до розбою й підривної діяльності. Каркад здивовано й зневажливо відзначає, як низько скотилися занепалі лорди Альтераку, що опустилися до дрібних змов, аби видряпати назад хоч трохи влади."},{t="Аудієнція в жахолорда",b="Через делікатність відомостей гросбух доставляють просто Варіматрасові в Королівський Квартал Андерсіті. Цей командувач-натрезим керує тактичною розвідкою Відступників на службі Сильвани Віндраннер. Задоволений ініціативою скрадачів смерті, Варіматрас схвально відзначає вправність агента й зауважує, що його розвідці завжди знадобиться той, хто досягає результату."}},faq={{q="Хто такі Скрадачі смерті?",a="Скрадачі смерті — провідний орден шпигунства, розвідки й убивств Відступників. Їхній осередок — у Кварталі Розбійників Андерсіті; вони діють по всьому Лордерону, знешкоджуючи політичних суперників, проникаючи у ворожі угруповання й боронячи королівство Відступників від зовнішніх і внутрішніх підступів.",al={"хто такі скрадачі смерті","лор скрадачів смерті","вбивці відступників"}},{q="До чого тут Синдикат?",a="Здобутий гросбух розкриває таємні зв'язки із Синдикатом — вигнаною аристократією Альтераку, що вдалася до організованого бандитизму. Відступники пильно стежать за рештками Альтераку на своїх землях, бо агенти Синдикату постійно шукають нагоди повернути втрачені володіння й грабувати північний Лордерон.",al={"чому синдикат","зв'язок з альтераком","гросбух синдикату"}},{q="Чому доповідати треба просто Варіматрасові?",a="Варіматрас — тактичний радник королеви Сильвани, що наглядає за безпекою та розвідкою Андерсіті. Важливі відкриття про чужоземні змови — як-от таємні операції Синдикату — мають розглядатися на найвищому рівні, щоб узгодити ширші військові й дипломатичні заходи у відповідь.",al={"чому варіматрас","хто такий варіматрас","роль володаря жаху"}},{q="Хто такий Меннет Каркад?",a="Меннет Каркад — старший куратор і зв'язковий Скрадачів смерті в Андерсіті. Він наглядає за польовими агентами, оцінює новобранців і перебирає зібрані відомості, перш ніж передати найважливіше вище.",al={"роль меннета каркада","хто дає завдання каркад"}},{q="Де відбувається ця аудієнція?",a="Аудієнція відбувається в Залі Темної Леді в Королівському Кварталі, глибоко в Андерсіті. Варіматрас стоїть поруч із королевою Сильваною Віндраннер у самому серці влади Відступників.",al={"де варіматрас","місце зали темної пані"}},{q="Що буде після вступу до Скрадачів смерті?",a="Підтвердивши свої повноваження й довівши свою надійність і Меннетові Каркаду, і Варіматрасові, ви стаєте довіреним польовим агентом Відступників, і попереду — нові розвідувальні доручення й замовлення на ліквідацію по всіх спірних землях Лордерону.",al={"продовження лінії скрадачів смерті","що далі"}}},fp="17,326,26.441.0,24.431.1,27.427.0,27.311.0,30.341.0,35.327.0,22.243.0,36.206.0,45.277.0"}
P.entries["quest:199"] = {n="Насувається темна загроза",s="Це завдання — мить, коли розслідування диверсії на Каменетесній Греблі натрапляє на речовий доказ лихого задуму. Знайшовши підозрілу бочку, заховану біля велетенської дворфійської споруди, шукачі пригод беруть зразок дивно пахучого порошку й несуть його Головному Інженерові Гіндервіру VII.",h="Це завдання — мить, коли розслідування диверсії на Каменетесній Греблі натрапляє на речовий доказ лихого...",kw={"насувається темна загроза","каменетесна гребля","гіндервір","порошок","диверсія","лох модан"},ang={["profession:Engineering"]="Інженер одразу відчуває небезпеку, побачивши нестійкі порошки, навмисно закладені в найвразливіших місцях великої греблі.",["race:Dwarf"]="Каменетесна Гребля — одне з найвеличніших будівельних досягнень дворфів Айронфорджа. Будь-яка загроза її цілісності б'є просто по безпеці й гордості Каз Модану.",["race:Gnome"]="Гномський розум цінує точність дворфійських споруд, тож хімічна природа цієї грубої диверсії особливо тривожить."},sec={{t="Підозріла знахідка",b="Каменетесна Гребля — величний тріумф дворфійської інженерії, що стримує неосяжні води озера. Проте чутки про диверсію привернули пильну увагу до навколишнього берега. Біля самої води захована бочка, якій тут не місце, а в ній — зловісна речовина: дивний, їдкий порошок, що явно не належить до звичайних припасів для догляду за греблею."},{t="Тривога на греблі",b="Коли зразок невідомого порошку показують Головному Інженерові Гіндервіру VII, справджуються найгірші побоювання влади Лох Модану. Інженер одразу розуміє, що проти греблі змовляється чужа сила, — і розслідування з простої підозри обертається нагальною справою оборони краю."}},faq={{q="Що за дивний пахучий порошок?",a="Дивний пахучий порошок з бочки — вибухова чи алхімічна речовина, підкладена біля підніжжя Каменетесної Греблі. Це прямий доказ того, що ворог замишляє зруйнувати чи пошкодити велику загату.",al={"дивний порошок","що в бочці","порошок із підозрілої бочки"}},{q="Хто такий Головний Інженер Гіндервір VII?",a="Головний Інженер Гіндервір VII — дворфійський майстер-інженер, що відповідає за обслуговування, цілісність і безпеку Каменетесної Греблі в Лох Модані.",al={"хто такий гіндервір","головний інженер гіндервір","інженер греблі"}},{q="Де знайти підозрілу бочку?",a="Підозріла бочка схована на березі біля основи Каменетесної Греблі на півночі Лох Модану.",al={"місце бочки","де бочка","бочка лох модан"}},{q="Чому ціль — саме Каменетесна Гребля?",a="Каменетесна Гребля стримує величезне водосховище Лох Модану. Якщо її прорве, катастрофічна повінь промчить Багнокраєм унизу, підірве торговельні шляхи Альянсу й спустошить дворфійські володіння по всьому Каз Модану.",al={"чому знищити греблю","диверсія на греблі","загроза лох модану"}},{q="Хто залишив тут підозрілу бочку?",a="Бочку підклали агенти, що хочуть розхитати дворфійські землі, і Головний Інженер Гіндервір починає ширше розслідування, щоб з'ясувати, хто стоїть за змовою.",al={"хто підклав бочку","диверсанти","хто залишив порошок"}},{q="Що робити, коли порошок зібрано?",a="Віднесіть зразок просто Головному Інженерові Гіндервіру VII на вершину Каменетесної Греблі, щоб він оглянув речовину й підготував відповідь.",al={"що далі","здати порошок","з ким говорити"}}},fp="19,308,22.377.0,16.319.1,36.233.0,37.149.0,37.124.0,43.226.0,36.168.0,45.139.0"}
P.entries["quest:1998"] = {n="Фенвік Татрос",s="Меннет Каркад посилає здібних розбійників Андерсіті вистежити Фенвіка Татроса — за наказом самого лорда Варіматраса. Татроса підозрюють у тому, що він збирає незалежні загони нежиті на берегах у Срібноліссі. Усунувши його, агент доводить скрадачам смерті свою вартість і відкриває собі шлях до тонкощів ремесла.",h="Меннет Каркад посилає здібних розбійників Андерсіті вистежити Фенвіка Татроса — за наказом самого лорда...",kw={"фенвік татрос","меннет каркад","варіматрас","скрадачі смерті","озеро лордамер","срібнолісся","розбійник"},ang={["class:Rogue"]="Це замовлення — полігон для розбійників-Відступників: воно підтверджує вашу скритність і смертоносність, перш ніж вам довірять глибші знаряддя ремесла скрадачів смерті.",["race:Undead"]="Відступники не можуть терпіти суперницьких угруповань нежиті, що претендують на владу так близько від Столиці, — тож голова Татроса стає політичною потребою."},sec={{t="Наказ жахолорда",b="У темних коридорах Кварталу Розбійників Меннет Каркад веде внутрішні замовлення й навчання скрадачів смерті — таємного розвідувального крила Відступників. Коли лорд Варіматрас спускає першочергову ціль, таке доручення не дають новобранцям абияк. Фенвік Татрос привернув увагу жахолорда, закріпившись серед вільної нежиті в Срібноліссі. Якщо його не зупинити, незалежний провід нежиті може зашкодити Відступникам, які згуртовують під своєю владою старі володіння Лордерона."},{t="Трухлявий причал на Лордамері",b="За розвідданими скрадачів смерті, Татрос не ховається ні в глибоких фортецях, ні в склепах. Розвідники вистежили його біля трухлявого причалу на березі Озера Лордамер у Срібноліссі. Щоб убити його там, треба пройти спірною глушиною, де панують дикі звірі, гнилошкірі гноли й рештки Погибелі. Його відрубана голова — той відчутний доказ, якого вимагає Варіматрас, перш ніж допустити агента до глибших таємних операцій."}},faq={{q="Хто такий Фенвік Татрос?",a="Фенвік Татрос — ватажок нежиті, що діє на берегах Озера Лордамір у Срібноліссі. На відміну від Відступників, які служать Леді Сильвані, Татрос керує осередками нежиті, що лишаються незалежними чи ворожими до Андерсіті, тож лорд Варіматрас наказав його стратити.",al={"лор фенвіка","хто такий татрос","передісторія фенвіка татроса"}},{q="Чому Варіматрас хоче смерті Фенвіка Татроса?",a="Варіматрас бачить у Татросі загрозу, що зростає: той може згуртувати бездомну нежить Срібнолісся проти Відступників. Щоб убезпечити кордони довкола Андерсіті, кожного ватажка-суперника, що загрожує цілковитій владі Сильвани в краю, треба швидко усунути.",al={"варіматрас татрос","чому вбити фенвіка"}},{q="Хто такі Скрадачі смерті?",a="Скрадачі смерті — провідна служба шпигунства, убивств і розвідки Відступників. Діючи з Кварталу Розбійників Андерсіті, вони працюють по всьому Лордерону: усувають внутрішні загрози, стежать за суперниками й захищають землі для Темної Леді.",al={"лор скрадачів смерті","що таке скрадачі смерті","фракція розбійників-нежиті"}},{q="Де знайти Фенвіка Татроса?",a="За звітами Скрадачів смерті, Татрос перебуває біля зруйнованої, напівзгнилої пристані на березі Озера Лордамір на північному сході Срібнолісся.",al={"де фенвік","пристань фенвіка","татрос озеро лордамер"}},{q="Що дає це доручення в Скрадачів смерті?",a="Стративши Татроса, агент доводить Меннетові Каркаду й Скрадачам смерті свою вправність і відданість. Переконавшись у вашій надійності, Каркад пропонує вдосконалити ваше мистецтво тіні особливою ремісничою наукою.",al={"нагорода фенвіка","що після фенвіка"}},{q="Хто такий Меннет Каркад?",a="Меннет Каркад — наставник розбійників і куратор Скрадачів смерті у Кварталі Розбійників Андерсіті. Він наглядає за польовими агентами й дає доручення, безпосередньо пов'язані з безпекою королівства Відступників.",al={"меннет каркад","хто дає завдання фенвіка"}}},fp="15,348,28.525.0,30.480.0,23.290.0,47.256.0,26.279.0,33.129.0,62.236.0,21.206.0"}
P.entries["quest:1999"] = {n="Знаряддя ремесла",s="«Знаряддя ремесла» — вступне завдання для розбійників Орди, яке дає Меннет Каркад в Андерсіті. За наказом лорда Варіматраса агенти мають здобути відмички й пробратися в Амбермілл, щоб викрасти таємні звіти Кірін-Тору про теперішній стан Даларана.",h="«Знаряддя ремесла» — вступне завдання для розбійників Орди, яке дає Меннет Каркад в Андерсіті.",kw={"знаряддя ремесла","відмички","амбермілл","звіт про стан даларана","естель джендрі","меннет каркад","розбійник"},ang={["class:Rogue"]="Це завдання — обряд посвяти для розбійників Орди: вам треба здобути справжні відмички й покластися на скритність і спритність, а не на грубу силу.",["faction:Horde"]="Здобуваючи людські розвіддані в Срібноліссі, ви зміцнюєте позиції Орди на півночі Лордерона проти решток Альянсу.",["race:Undead"]="Проникнувши в Амбермілл, Відступники перехитрують тих самих магів Кірін-Тору, які прагнуть забрати Лордерон собі, вирвавши його з могили."},sec={{t="Очі на Амбермілл",b="Допитавши полоненого мага Кірін-Тору, скрадачі смерті дізналися, що важливі відомості про руїни Даларана сховано в Амберміллі. Срібнолісся лишається хиткою передовою, а маги-люди, що стережуть селище, пильно бережуть своє листування. За наказом лорда Варіматраса куратор скрадачів смерті Меннет Каркад посилає здібних агентів прослизнути повз вартових Кірін-Тору й здобути Звіт про Стан Даларана."},{t="Мистецтво зламу",b="На відміну від прямолінійних убивств, це завдання — практичний полігон проникнення й зламу замків. Перш ніж рушити на ворожі землі Кірін-Тору, агенти отримують від Естель Джендрі особливе злодійське знаряддя. Зламана замкнена скриня в Амберміллі доводить, що агент переріс вуличну грубу силу й став незамінним шпигуном Відступників."}},faq={{q="Хто дає це доручення?",a="Завдання дає Меннет Каркад, майстер-розбійник зі Скрадачів смерті у Кварталі Розбійників Андерсіті. А загальний наказ іде просто від лорда Варіматраса, який наглядає за розвідкою Відступників.",al={"хто дає знаряддя ремесла","хто дає завдання","завдання меннета каркада"}},{q="Що таке Звіт про Стан Даларана?",a="Це запечатане донесення Кірін-Тору про становище в Даларані. Слідчі Скрадачів смерті вивідали, де воно, в ув'язненого мага-людини, і Андерсіті дізнався, що важливі відомості про їхніх південних сусідів легко здобути.",al={"що за документи","папери кірін тор","звіт про стан"}},{q="Де зберігається звіт?",a="Звіт лежить у замкненій скрині на заставі Кірін-Тору в Амбермілі, на півдні Срібнолісся.",al={"де знайти документи","місце скрині амбермілла","де звіт про стан"}},{q="Хто дає відмички?",a="Естель Джендрі, постачальниця з Кварталу Розбійників Андерсіті, дає потрібне злодійське знаряддя, щоб відімкнути скриню Кірін-Тору.",al={"де взяти відмички","роль естель ґендрі","знаряддя крамаря"}},{q="Чому Даларан зараз важливий для Відступників?",a="Уцілілі чарівники Даларана відбудовують своє місто біля південного кордону Срібнолісся. Відступники стежать за Кірін-Тором, щоб захистити власні володіння в Лордероні.",al={"чому даларан важливий","відступники проти даларана","загроза кірін тор"}},{q="Що треба виконати, перш ніж узятися за це доручення?",a="Агенти мусять спершу виконати замовлення на вбивство «Фенвік Татрос» — вистежити ціль у Срібноліссі, — і лише тоді Меннет Каркад довірить їм делікатну справу з проникненням.",al={"передумова","яке завдання перед цим","завдання фенвіка татроса"}}},fp="18,265,17.457.0,21.418.0,24.235.0,34.246.0,25.125.0,35.145.0,51.179.0,63.183.0"}
P.entries["quest:2"] = {n="Кіготь Шарпталона",s="«Кіготь Шарпталона» — завдання-трофей про перемогу над лютим гіпогрифом Шарпталоном в Ашенвалі. Принісши відтятий кіготь істоти Сенані Тандергарт на Заставу Розщепленого Дерева, ви доведете свою вправність і захистите шляхи постачання Орди крізь прадавній ліс.",h="«Кіготь Шарпталона» — завдання-трофей про перемогу над лютим гіпогрифом Шарпталоном в Ашенвалі.",kw={"кіготь шарпталона","шарпталон","гіпогриф","сенані тандергарт","полювання","завдання"},ang={["class:Hunter"]="Здолати легендарного крилатого хижака на кшталт Шарпталона — найвище випробування вміння вистежувати й влучно стріляти під густим лісовим покровом Ашенвалю.",["faction:Horde"]="Перемога над Шарпталоном убезпечує важливі стежки для лісозаготівель Бойової Пісні й захищає беззахисних пеонів, що ходять між передовими заставами й Заставою Розщепленого Дерева.",["race:Orc"]="Знищення крилатих страховиськ у лісі полегшує виснажливу лісозаготівельну кампанію клану Бойової Пісні.",["race:Tauren"]="Дотримуючись мисливських обрядів під проводом Сенані Тандергарт, ви виявляєте споконвічну тауренську шану до випробування себе в двобої з найлютішими звірами природи."},sec={{t="Лихо лісових стежок",b="Поки Орда намагається видобувати ресурси в Ашенвалі, тутешні звірі виявляються не менш небезпечними, ніж вартові нічних ельфів. Шарпталон, сумно відомий своєю лютістю гіпогриф, чатував у кронах і на стежках, що ведуть до Застави Розщепленого Дерева. Звір полював на беззахисних пеонів і гінців, які ходили між передовими лісозаготівельними таборами й заставою, і тяжко заважав діям Орди в краї."},{t="Доказ полювання",b="Під проводом тауренської мисливиці Сенані Тандергарт слідопити Орди мають вичистити найнебезпечніших хижаків, що чатують під лісовим покровом Ашенвалю. Величезний кіготь, відтятий у Шарпталона, — незаперечний доказ того, що небесне страховисько загинуло. Трофей, принесений на Заставу Розщепленого Дерева, здобуває шану серед захисників застави й полегшує життя наляканим робітникам, яким доводиться ходити лісом."}},faq={{q="Хто такий Шарпталон?",a="Шарпталон — хижий гіпогриф з власним ім'ям, що живе в Ашенвалі. Відомий своєю лютістю, він раз у раз нападав на мандрівників у давніх лісах.",al={"хто такий шарпталон","шарпталон моб","що за звір шарпталон"}},{q="Навіщо Сенані Тандергарт кіготь?",a="Сенані Тандергарт керує Полюванням в Ашенвалі із Застави Розщепленого Дерева. Кіготь — речовий доказ того, що великого хижака, який загрожував робітникам і шляхам постачання Орди, знищено.",al={"навіщо кіготь сенані","трофей сенані тандергарт","призначення пазура шарпталона"}},{q="Кому здавати Кіготь Шарпталона?",a="Кіготь треба віддати Сенані Тандергарт — тауренці, що перебуває на Заставі Розщепленого Дерева на сході Ашенвалю.",al={"де здати кіготь","хто бере кіготь","місце здавання пазура"}},{q="Як смерть Шарпталона допомагає Орді?",a="Шарпталон раз у раз нападав на пеонів, що ходили між віддаленими лісопильнями й Заставою Розщепленого Дерева. Убивши звіра, ви робите безпечнішим шлях для припасів, деревини й гінців.",al={"чому вбити шарпталона","інтерес орди до шарпталона"}},{q="Чи це завдання — частина більшого ланцюжка?",a="Так. Воно входить до «Полювання в Ашенвалі» — низки випробувань із вистежування звірів від Сенані Тандергарт, що завершується завданням «Полювання завершено».",al={"ланцюжок полювання ашенвалю","ланцюжок завдань шарпталона"}},{q="Хто така Сенані Тандергарт?",a="Сенані Тандергарт — тауренка-мисливиця із Застави Розщепленого Дерева, яка стежить за рівновагою лісу й випробовує загартованість мисливців Орди проти найнебезпечніших створінь Ашенвалю.",al={"лор сенані","хто така сенані"}}},fp="17,275,30.407.0,17.424.0,19.162.0,43.195.0,37.104.0,43.178.0,37.146.0,27.194.0"}
P.entries["quest:20"] = {n="Загроза Блекроку",s="Маршал Марріс із Лейкширу доручає шукачам пригод винищувати агресивних орків Блекрок, що підступають до Редріджу. Забираючи в них зужиті в боях сокири, захисники містечка сподіваються прорвати облогу, яка дедалі щільніше стискає поселення.",h="Маршал Марріс із Лейкширу доручає шукачам пригод винищувати агресивних орків Блекрок, що підступають до...",kw={"загроза блекроку","орки блекрок","маршал марріс","зужита в боях сокира","лейкшир","редрідж"},ang={["class:Warrior"]="Зійтися щит у щит із досвідченими мародерами Блекрок — жорстке випробування бойової дисципліни й стійкості на передовій.",["faction:Alliance"]="Захист Лейкширу вкрай важливий, щоб утримати південний кордон королівства Стормвінд від давніх ворогів.",["race:Human"]="Клан Блекрок зруйнував давнє королівство Стормвінд у Першій війні; нова зустріч із ним у Редріджі пробуджує гірку пам'ять поколінь."},sec={{t="Містечко в облозі",b="Лейкшир затиснутий з кількох боків, але найгрізніша загроза — орки Блекрок, що ринули сюди з вогняних Палаючих Степів. Просунувшись на південь, у Редрідж, ці досвідчені грабіжники захопили опорні пункти й блукають скелястими перевалами. Через них містяни фактично замкнені в поселенні: торгівля, збиральництво й подорожі північними дорогами зупинилися."},{t="Удар по авангарду",b="Маршал Марріс, командир знесиленої варти Лейкширу, не може виділити загін, щоб прямо штурмувати ворожі позиції. Натомість він залучає мандрівних шукачів пригод, щоб ті знекровлювали передових розвідників і піхоту загарбників. Вимагаючи їхні грубі, зужиті в боях сокири як доказ загибелі, Марріс прагне зменшити число загарбників і довкола Кам'яної Варти на півночі, і в скелястих закутках південно-східного Редріджу."}},faq={{q="Звідки взялися ці орки Блекрок?",a="Вони прийшли на південь зубчастими гірськими перевалами з Палаючих Степів, де довкола Гори Блекрок стоїть їхня споконвічна твердиня.",al={"звідки орки","вторгнення блекрок у редрідж","чому орки в редріджі"}},{q="Хто дає це завдання?",a="Маршал Марріс — старший військовий офіцер, якому доручено боронити Лейкшир і підтримувати лад, поки кільце довкола містечка дедалі тісніше.",al={"хто дає загрозу блекроку","хто дає завдання","завдання маршала маррісі"}},{q="Де шукати загарбників Блекрок?",a="Вони займають північне нагір'я довкола Фортеці Кам'яної Варти, а також закріпилися в південно-східному закутку Гір Редріджу.",al={"де орки блекрок","місця пошарпаних сокир","табори орків редріджа"}},{q="Навіщо Маршалові Маррісу пошарбані в боях сокири?",a="Пошарбані сокири — незаперечний речовий доказ того, що шукач пригод справді бився з мародерами Блекрок, які загрожують долині, і вбивав їх.",al={"навіщо сокири","доказ смерті","призначення пошарпаної сокири"}},{q="Що буде після перемоги над цими розвідниками?",a="Коли авангард проріджено, Маршал Марріс наказує вдарити по місцевому ватажкові Блекрок, що засів у горах, — Таріл'зунові.",al={"що після загрози блекроку","наступне завдання після загрози блекроку","хто веде орків"}},{q="Чи належать ці орки до Орди Тралла?",a="Ні. Клан Блекрок, що діє тут, — рештки Старої Орди, люто ворожі до Альянсу; вони діють незалежно від нової Орди Тралла на Калімдорі.",al={"чи це орки орди","чи клан блекрок частина орди тралла","дружні орки в редріджі"}}},fp="16,228,18.405.0,21.413.0,41.142.0,21.135.0,42.147.0,48.154.0,45.136.1,44.183.0"}
P.entries["quest:2038"] = {n="Зниклі припаси Бінґлза",s="Коли дивакуватий гномський інженер Бінґлз Бластенгаймер аварійно посадив свій гірокоптер у води озера, на нього напали місцеві троги й поцупили його найпотрібніше спорядження. Застрягши на південно-східному березі, він просить повернути вкрадені гайковий ключ, викрутку, молот і саморобну вибухівку з Вибухокапсулятора, щоб полагодити машину й знову долучитися до боротьби за Гномреґан.",h="Коли дивакуватий гномський інженер Бінґлз Бластенгаймер аварійно посадив свій гірокоптер у води озера, на...",kw={"зниклі припаси бінґлза","бінґлз бластенгаймер","гірокоптер","троги","лох модан","гномреґан","інструменти"},ang={["faction:Alliance"]="Допомагаючи пілотові Альянсу в серці Лох Модану, ви вбезпечуєте водні шляхи й підтримуєте ширшу війну за повернення втрачених земель Каз Модану.",["profession:Engineering"]="Залишити особливі інструменти й нестійкі боєприпаси на кшталт Вибухокапсулятора Бластенгаймера в незграбних руках трогів — образа для ремесла й катастрофа, що тільки чекає своєї миті.",["race:Dwarf"]="Навала трогів на острівцях озера загрожує місцевій торгівлі й подорожам, тож будь-який удар по їхніх таборах — бажана послуга горянам.",["race:Gnome"]="Кожен повернений інструмент на крок наближає гномський народ до повітряного контрнаступу на трогів і прокажених гномів, що душать Гномреґан."},sec={{t="Мокре приземлення",b="Бінґлз Бластенгаймер вів свій гірокоптер над Лох Моданом, коли несподівана аварія скинула його просто в холодні води озера. Уціліти після удару — вже неабияка удача, але вибратися на берег виявилося лише половиною біди. Троги, що кишать на центральних острівцях озера, одразу скористалися його скрутою: обсіли приголомшеного пілота й розтягли найцінніші його речі."},{t="Гномська винахідливість в облозі",b="Троги-грабіжники розкидали найпотрібніше спорядження Бінґлза по своїх острівних таборах. Серед зниклого — його звичайні польові інструменти: гайковий ключ, викрутка й молот, а ще його гордість, винахід під назвою Вибухокапсулятор Бластенгаймера. Втратити звичайне начиння прикро й саме собою, але потужна нестійка вибухівка в краї, де й так кишать троги, — пряма небезпека для кожного, хто мандрує Лох Моданом."},{t="За Гномреґан",b="Бінґлз не просто катається в небі Каз Модану заради втіхи: він вважає себе повітряним авангардом визволення своєї занепалої батьківщини. Гномреґан нині захопили підземні троги й опромінені прокажені гноми, і Бінґлз мріє про рішучий удар з повітря, що зламає ворожу хватку. Та без інструментів і вибухівки, без яких не відбудувати літальну машину, його великий повітряний похід міцно застряг в очереті."}},faq={{q="Чому Бінґлз Бластенгаймер застряг у Лох Модані?",a="Бінґлз урізався своїм гірокоптером просто в озеро. Поки він оговтувався від аварії на південно-східному березі, на нього напали троги з сусідніх островів і поцупили його знаряддя й експериментальні боєприпаси.",al={"чому бінґлз тут","як бінґлз розбився","аварія бінґлза"}},{q="Які припаси вкрали троги?",a="Троги потягли чотири важливі речі: гайковий ключ Бінґлза, викрутку, молоток і особливий вибуховий заряд — Бластенкепер Бластенгаймера.",al={"що вкрали троги","припаси бінґлза","які предмети бінґлза"}},{q="Куди троги понесли речі Бінґлза?",a="Троги віднесли вкрадене до своїх таборів на островах у північній частині озера, розкидавши відра з інструментами й вибухівку по скелястих берегах.",al={"де інструменти бінґлза","острів трогів","де бластенкепер"}},{q="Що таке Бластенкепер?",a="Бластенкепер — власний вибуховий пристрій Бінґлза Бластенгаймера, призначений для бойових повітряних ударів по ворогах, що захопили Гномреґан.",al={"що таке бластенкепер","бластенгаймер бластенкепер","вибухівка бінґлза"}},{q="Про який рух говорить Бінґлз?",a="Бінґлз відданий справі повернення Гномреґана. Він хоче розгорнути кампанію повітряних бомбардувань, щоб вичистити підземних трогів і гномів-прокажених, які тримають гномську столицю в полоні.",al={"який рух","за гномреґан","справа бінґлза"}},{q="Чому Бінґлз не може сам повернути припаси?",a="Після катастрофічної аварії Бінґлз лишився сам-один, мокрий до нитки й геть без зброї. Вийти без зброї й без літальної машини проти укріпленого табору лютих трогів через відкриту воду — для інженера-одинака це самогубство.",al={"чому бінґлз сам не дістане","чому бінґлз чекає"}}},fp="25,387,14.419.0,29.443.0,14.446.0,52.210.0,40.155.0,40.188.0,26.169.0,38.192.0,48.227.0"}
P.entries["quest:2039"] = {n="Знайти Бінглза",s="Знайти Бінґлза — завдання Альянсу, яке в Айронфорджі дає гном Ґноарн. Він тривожиться за льотчика, що понад тиждень тому зник під час повітряної розвідки над занепалим Гномреґаном, і посилає шукачів пригод прочесати береги Лох Модану. Слід зниклого пілота веде просто до Бінґлза Бластенгаймера — живого й неушкодженого, але в розпачливій потребі механічних запчастин.",h="Знайти Бінґлза — завдання Альянсу, яке в Айронфорджі дає гном Ґноарн.",kw={"бінґлз","ґноарн","лох модан","гномреґан","льотчик","троги"},ang={["faction:Alliance"]="Розвідники Альянсу часто стають ланкою зв'язку між залами Айронфорджа й польовими загонами в Лох Модані.",["profession:Engineering"]="Інженери оцінять професійні ризики гномської авіації, де загублена гайка на крилі чи вибух двигуна — звичайнісінький вівторок.",["race:Gnome"]="Для гномів порятунок Бінґлза — це надія колись повернути Гномреґан, де на рахунку кожен розвідник і кожна літальна машина."},sec={{t="Зниклий пілот",b="У гамірному гномському кварталі Айронфорджа, Містечку Майстрів, неспокійно: тут бідкаються за зниклими родичами й утраченими машинами. Гнома-льотчика Бінґлза Бластенгаймера відрядили на повітряну розвідку над зараженими радіацією руїнами Гномреґана. Коли минуло понад тиждень без жодної звістки, Ґноарн почав боятися найгіршого: що Бінґлз став жертвою професійного ризику гномської інженерії й просто підірвав себе в небі. Востаннє дивакуватого льотчика бачили десь над водами Лох Модану."},{t="Біля озера",b="Замість купи уламків, що тліють, шукачі знаходять Бінґлза живим і бадьорим на березі Лох Модану. Його анітрохи не бентежить довга відсутність, а сумніви в його льотній майстерності навіть трохи ображають. Застряглий тут винахідник цілком захоплений своєю великою справою. Замість того щоб поспішити з доповіддю до Ґноарна, Бінґлз одразу просить рятівника про допомогу: троги поцупили його інструменти й вибухівку Бластенкеппер, а без них він не повернеться до служби гномській справі."}},faq={{q="Хто такий Бінґлз Бластенгаймер?",a="Бінґлз Бластенгаймер — дивакуватий гном-авіатор і механік. Його відправили в повітря вести спостереження над полеглим Гномреґаном, але він розбив свою літальну машину біля Лох Модану.",al={"хто такий бінґлз","лор бінґлза бластенгаймера","хто той пілот"}},{q="Навіщо Бінґлз літав над Гномреґаном?",a="Гномський провід і майстри постійно стежать за Гномреґаном після його трагічного падіння під навалою трогів і радіації. Бінґлз піднявся в небо, щоб розвідати згори позиції ворога й стан довкілля, допомагаючи загальній справі повернення дому.",al={"місія бінґлза","чому бінґлз літав","розвідка гномреґана"}},{q="Де знайти Бінґлза?",a="Бінґлз застряг на південно-східному березі озера в Лох Модані, де намагається дати раду своїй розбитій літальній машині.",al={"де бінґлз","місце бінґлза","де знайти бінґлза"}},{q="Хто такий Ґноарн?",a="Ґноарн — гном-координатор з Містечка Майстрів в Айронфорджі. Він стежить за гномським особовим складом і місіями, і саме він починає пошуки, коли Бінґлз не повертається вчасно.",al={"хто такий ґноарн","хто дає завдання ґноарн"}},{q="Що буде, коли знайти Бінґлза?",a="Знайшовши Бінґлза, ви отримуєте наступне завдання — «Зниклі припаси Бінґлза», де треба забрати в трогів на островах озера його гайковий ключ, викрутку, молоток і вибухівку Бластенкепер.",al={"що після пошуку бінґлза","завдання крилатої гайки","продовження бінґлза"}},{q="Чи постраждав Бінґлз в аварії?",a="Бінґлз цілий і неушкоджений, хоча його гордість трохи зачепило те, що Ґноарн засумнівався в його льотній майстерності. Насправді його турбує лише те, як повернути знаряддя й вибухівку, які поцупили троги.",al={"чи бінґлз поранений","чи бінґлз помер"}}},fp="12,409,15.522.0,16.513.0,29.203.0,39.253.0,25.145.0,14.187.0,35.197.0,31.191.0"}
P.entries["quest:2040"] = {n="Підземний штурм",s="«Підземний штурм» — завдання Альянсу, яке дає Шоні Тихий у Дворфійському Кварталі Стормвінда. Допомагаючи гномам-вигнанцям, шукачі пригод вирушають до Мертвих Копалень, щоб зняти ціле енергетичне ядро з гоблінського потрощувача. Цій здобичі судилося живити бурильні машини, що мають очолити визволення Гномреґана.",h="«Підземний штурм» — завдання Альянсу, яке дає Шоні Тихий у Дворфійському Кварталі Стормвінда.",kw={"підземний штурм","шоні тихий","гномреґан","потрощувач","мертві копальні","ґноам спрекльспрокет"},ang={["faction:Alliance"]="Допомагаючи гномам-вигнанцям із Дворфійського Кварталу, ви зміцнюєте зв'язок між Стормвіндом і його союзниками у вигнанні та завдаєте удару по постачанню Дефіас.",["profession:Engineering"]="Майстри оцінять зухвалу інженерну думку: розібрати енергоядро грубого гоблінського потрощувача, щоб живити ним точну гномську прохідницьку техніку.",["race:Gnome"]="Для гномів-вигнанців ця здобич — особистий крок до того, щоб пробити скелясті стіни загиблої домівки й вигнати трогів із Гномреґана."},sec={{t="Відчайдушна винахідливість",b="Після того як Гномреґан упав під натиском первісних трогів, уцілілі гномські майстри опинилися у вигнанні в Каз Модані та Стормвінді. Замість того щоб упадати у відчай, інженери на кшталт Шоні вже розробляють механічні операції, щоб прорватися до втраченої домівки. Головна перешкода — щільна скельна порода довкола технократичного міста, і щоб її здолати, потрібні величезні прохідницькі машини — гіросвердломатичні екскаваціонатори. На людських землях бракує потрібних джерел енергії, тож гноми звернули погляд на несподівану й небезпечну альтернативу: важку гоблінську техніку, що працює в злочинному підпіллі."},{t="Грабунок ливарень Дефіас",b="Глибоко у звивистих шахтах Мертвих Копалень у Вестфолі Братство Дефіас Едвіна Венкліфа тримає гоблінських інженерів, що виготовляють бойові машини, зокрема й цілком робочий гоблінський потрощувач. Шоні посилає агентів Альянсу проникнути до цієї ливарні, знищити чи розібрати неповороткий автомат і забрати його особливе серце — Ґноам Спрекльспрокет. Заволодівши потужним гоблінським джерелом живлення, гноми-вигнанці отримають досить механічної сили, щоб пробуритися крізь підземний рубіж і почати контрнаступ за Гномреґан."}},faq={{q="Хто дає завдання «Підземний штурм»?",a="Це завдання дає Шоні Тиха — гномська інженерка з Дворфійського Кварталу Стормвінда. Шукачі пригод часто приходять до неї після розмов з іншими гномами, які згадують її амбітні задуми.",al={"хто дає підземний штурм","хто дає завдання підземний штурм","завдання шоні"}},{q="Де знайти Ґноам Спрекльспрокет?",a="Ґноам Спрекльспрокет здобувають з робочого гоблінського подрібнювача глибоко в ливарних тунелях Мертвих Копалень у Вестфолі.",al={"місце ґноам спрекльспрокет","де спрекльспрокет","деталь подрібнювача мертві копальні"}},{q="Навіщо Шоні деталі гоблінського подрібнювача?",a="Гномським гіробуроматичним екскаватораторам потрібне величезне переносне джерело живлення, щоб прорватися крізь укріплені підземні рубежі довкола Гномреґана. Потужне енергетичне ядро гоблінського подрібнювача Братства Дефіас дає саме ту механічну силу, якої потребують бури.",al={"чому гоблінські деталі","живлення подрібнювача","призначення спрекльспрокета"}},{q="Яка ширша мета цієї місії?",a="Ця місія готує майбутнє визволення Гномреґана. Запустивши важкі бури, гноми-вигнанці збираються прокопатися просто крізь скелясті рубежі свого захопленого міста й раптово вдарити по трогах, що його окупували.",al={"навіщо підземний штурм","завдання відвоювання гномреґана","план штурму гномів"}},{q="Що сталося з Гномреґаном, що довелося планувати цей штурм?",a="Гномреґан захлеснула навала трогів, що вийшли з глибин під містом. Під час хаотичної оборони місто отруїла токсична радіація, і вцілілі гноми мусили тікати біженцями до Айронфорджа й Стормвінда.",al={"чому впав гномреґан","що сталося з гномреґаном","вторгнення трогів"}},{q="Чи в союзі Братство Дефіас і троги?",a="Ні, вони ніяк не пов'язані. Братство Дефіас лише найняло гоблінів-майстрів будувати бойові машини у Вестфолі. Шоні просто використовує присутність Дефіас у Мертвих Копальнях як зручне джерело потужної гоблінської техніки.",al={"дефіас і троги","чи троги з дефіас"}}},fp="19,356,21.658.0,28.571.0,40.214.0,43.135.0,49.279.0,41.251.0,67.253.0,49.230.0"}
P.entries["quest:2041"] = {n="Поговори з Шоні",s="Це завдання скеровує шукачів пригод Альянсу із залів Айронфорджа до Шоні Тихого в Стормвінді. Шоні очолює підземний штурмовий загін, що має підтримати відвоювання Гномреґана.",h="Це завдання скеровує шукачів пригод Альянсу із залів Айронфорджа до Шоні Тихого в Стормвінді.",kw={"шоні тихий","гномреґан","глибинний трамвай","стормвінд","екскаваціонатор","гноми"},ang={["faction:Alliance"]="Це доручення показує, як тісно пов'язані столиці Альянсу: Глибинний трамвай швидко перевозить людей між Айронфорджем і Стормвіндом.",["profession:Engineering"]="Задум Шоні — гіросвердломатичні екскаваціонатори, складне досягнення гномської механіки, створене для прокладання тунелів глибоко під землею.",["race:Gnome"]="Кожен гном в Айронфорджі мріє повернути свій заражений радіацією дім; виконуючи накази Шоні, ви робите власний внесок у зусилля винахідників, що мають відвоювати Гномреґан."},sec={{t="Поклик із Містечка Майстрів",b="Після радіоактивного падіння й зради Гномреґана вцілілі гноми облаштували в Айронфорджі квартал вигнанців. Їхні інженери, механіки й стратеги без упину шукають способу прорватися до втраченого дому. Хоч головний штаб і досі в Містечку Майстрів, підготовка до наступу сягає далеко за межі Каз Модану. Заповзятливих шукачів пригод із гірського міста посилають на південь, до Стормвінда, де готують особливу військову техніку для підземної війни."},{t="Підземні задуми",b="Шоні Тихий командує добірною підземною штурмовою командою, що стоїть серед ковадел і горнів Дворфійського Кварталу Стормвінда. Щоб прорити ходи вглиб, до секторів, де кишать троги, саперам Шоні потрібні особливі машини — гіросвердломатичні екскаваціонатори. Дістатися до Шоні нескладно завдяки новому Глибинному трамваю, що під горами сполучає Айронфордж просто зі Стормвіндом."}},faq={{q="Хто така Шоні Тиха?",a="Шоні Тиха — гномська офіцерка, що працює в Стормвінді. Попри своє тихе прізвисько, вона командує загоном підземного штурму, якому доручено будувати й розгортати важке копальне обладнання, щоб допомогти повернути Гномреґан.",al={"хто така шоні","шоні тиха","хто той нпц"}},{q="Де знайти Шоні Тиху?",a="Шоні перебуває в Дворфійському Кварталі Стормвінда, біля наставників ковальства й кузень, за кілька кроків від станції Глибинного трамвая.",al={"де шоні","місце шоні","координати шоні"}},{q="Як дістатися зі Айронфорджа до Стормвінда?",a="Найшвидше — Глибинним трамваєм, дивом інженерії, станція якого в північно-східній частині Містечка Майстрів в Айронфорджі. Він везе мандрівників просто до Дворфійського Кварталу Стормвінда, без мандрів дикими краями.",al={"подорож до стормвінда","з айронфорджа до стормвінда","як дістатися стормвінда"}},{q="У чому Шоні потрібна допомога?",a="Шоні споряджає загін підземного штурму, і їй потрібні важливі деталі для гіробуроматичних екскаватораторів — ця справа зрештою приведе шукачів пригод до Вестфолу й Мертвих Копалень.",al={"мета завдання шоні","чого хоче шоні"}},{q="Чи обов'язкове це завдання, щоб отримати «Підземний штурм»?",a="Ні, це необов'язкове завдання-підказка. Можна самому прийти до Дворфійського Кварталу Стормвінда й поговорити із Шоні, щоб узяти «Підземний штурм».",al={"чи обов'язково поговори з шоні","чи можна пропустити шоні"}},{q="Як це пов'язано з Гномреґаном?",a="Гномський провід збирає сили й копальну техніку, щоб пробити оборону Гномреґана. Загін Шоні розробляє підземний бурильний апарат, без якого не прорватися в отруєне місто.",al={"чому гномреґан","зв'язок з гномами"}}},fp="16,216,22.487.0,22.407.0,25.235.0,35.148.0,41.216.0,31.196.0,50.165.0,36.210.0"}
P.entries["quest:2078"] = {n="Помста Джайромаста",s="Ґелкак Джайромаст жадає розплати з місцевими мурлоками, які пограбували його розбитий корабель біля берегів Темного Узбережжя. Щоб здійснити свою вендету, ексцентричний капітан посилає шукачів пригод знову запустити свого механічного першого помічника — Трешвакінатор 4100.",h="Ґелкак Джайромаст жадає розплати з місцевими мурлоками, які пограбували його розбитий корабель біля берегів...",kw={"помста джайромаста","ґелкак джайромаст","трешвакінатор 4100","перший помічник","мурлоки","темне узбережжя"},ang={["faction:Alliance"]="Позбувшись несправних машин і агресивних мурлоків, ви допоможете вберегти узбережжя для подорожей Альянсу між Обердайном і землями на півдні.",["profession:Engineering"]="Механічний перший помічник Ґелкака показує, наскільки капітан, що застряг на березі, залежить від свого інженерного спорядження.",["race:Gnome"]="Гноми впізнають у заводному ключі звичний спосіб запустити механічний автомат."},sec={{t="Капітанська вендета",b="Застрягши на імлистих берегах Темного Узбережжя, Ґелкак Джайромаст не хоче миритися з поразкою від прибережних мурлоків. Зібравши уламки, потрібні для своїх задумів, ексцентричний капітан прагне повної відплати племені та його ватажкові. Замість того щоб брести в прибій з абордажною шаблею в руці, Ґелкак покладається на важку інженерію й довіряє заводний ключ кожному сухопутному щурові, якому вистачить сміливості впоратися з його механічним підлеглим."},{t="Бунт першого помічника",b="Вірний перший помічник Ґелкака — не просолений дворф і не моряк, а Трешвакінатор 4100: брязкітливий механічний голем, покинутий на мілині на південь від корабельних решток. Заводна автоматика обіцяє легку розправу над мурлоками, та саме ця машина виявляється небезпечно ненадійною. Коли її заводять і ведуть назад до капітана, конструкція дає катастрофічний збій, сприймає рятівника й творця за ворогів — і на пляжі зав'язується бій."}},faq={{q="Хто такий помічник Ґелкака?",a="Помічник Ґелкака — Трешвакінатор 4100, механічний голем-автомат, що лежить на узбережжі на південь від табору капітана, який зазнав корабельної аварії.",al={"помічник","помічник ґелкака","хто помічник"}},{q="Чому Ґелкак прагне помсти?",a="Корабель Ґелкака розбився біля Темного Узбережжя, а місцеві мурлоки Сірої Імли розтягли його майно й не дають спокою вцілілій команді. Ґелкак збирається розчавити плем'я та їхнього вождя за допомогою свого голема.",al={"чому помста","помста мурлоків","мотив ґелкака"}},{q="Що буде, коли привести Трешвакінатора назад?",a="Увімкнувши помічника ключем, проведіть його назад до Ґелкака. Як він поведеться, коли дійде до капітана, ви побачите під час супроводу.",al={"напад трешвакінатора","збій робота","чому голем нападає"}},{q="Що робити з Ключем Гіромаста, коли завдання виконано?",a="Ключ запускає Трешвакінатора. Коли місію завершено, він більше ні до чого.",al={"використання ключа гіромаста","залишити ключ гіромаста","чи можна видалити ключ"}},{q="Звідки в Ґелкака Трешвакінатор?",a="Голем — частина вантажу й спорядження, врятованого з невдалого плавання Ґелкака вздовж північного Калімдору; його створили як важку механічну силу для команди.",al={"хто створив трешвакінатора","походження трешвакінатора"}},{q="Чи здається Ґелкак, коли голема знищено?",a="Які плани має Ґелкак і як він відповість на вашу роботу, з'ясується, коли ви приведете назад його помічника.",al={"що з ґелкаком","після помсти джайромаста"}}},fp="18,252,20.490.0,23.473.1,27.138.0,29.206.0,54.140.1,59.97.1,42.159.0,49.93.1"}
P.entries["quest:2098"] = {n="Пропажа Джайромаста",s="Ексцентричний гном-пірат Ґелкак Джайромаст, що зазнав корабельної аварії біля імлистих берегів Темного Узбережжя, шукає допомоги, щоб відновити свого механічного першого помічника. Його незамінний заводний ключ розбився об каміння, а уламки розтягли місцеві звірі й мурлоки. Повернути три частини — перший крок до того, щоб знову поставити команду до ладу.",h="Ексцентричний гном-пірат Ґелкак Джайромаст, що зазнав корабельної аварії біля імлистих берегів Темного...",kw={"пропажа джайромаста","ґелкак джайромаст","заводний ключ","мурлоки сірої імли","трешадони","південні моря"},ang={["profession:Engineering"]="Інженери оцінять, як складно підтримувати годинникові механізми в робочому стані після бурхливої корабельної аварії в солоній воді.",["race:Gnome"]="Гноми одразу впізнають, що Ґелкак покладається на годинникові механізми, а не на товаришів із плоті й крові, — хоч його піратське життя для їхнього народу доволі незвичне."},sec={{t="Викинутий морем на Темне Узбережжя",b="Ґелкак Джайромаст — дивне видовище на похмурих пісках Темного Узбережжя: гном-пірат, що застряг далеко від звичних морських шляхів Південних Морів. За словами Ґелкака, його судно спіткав сумний кінець просто біля берега — його атакували й потопили агресивні трешадони. Викинутий на берег серед уламків, він опинився геть сам, відрізаний від своєї вірної команди."},{t="Розтягнутий ключ",b="Найбільше Ґелкака турбують не харчі й не золото, а його перший помічник. Щоб запустити цього товариша й керувати ним, потрібен особливий ключ, який розлетівся на три уламки, коли Ґелкака кинуло на кам'янисті мілини. Не встиг він зібрати уламки, як місцеві звірі — рифові повзуни, що снують пляжем, височенні лісові довгоступи біля лісу та падальники з місцевого племені мурлоків Сірої Імли — розхапали блискучі металеві шматки."},{t="Дивний товариш",b="Ґелкак говорить про свого першого помічника з палкою відданістю морського капітана, хоча слова про те, що товариша треба «поставити до ладу», натякають на незвичайного члена команди. Гном-мореплавець, що застряг на чужих берегах, природно покладається на механічну винахідливість, і зібрати розбитий ключ украй важливо, щоб знову запустити ту годинникову дивовижу, яку Ґелкак витяг із глибин."}},faq={{q="Хто такий Ґелкак Джайромаст?",a="Ґелкак Джайромаст — дивакуватий гном-пірат, чий корабель розбився біля узбережжя Темного Узбережжя, коли на нього напали й потопили хижі трешадони.",al={"ґелкак джайромаст","хто гном-пірат","гном-пірат темного узбережжя"}},{q="Для чого потрібен ключ?",a="Ключ потрібен, щоб знову запустити й завести помічника Ґелкака — механічне створіння, що вимкнулося під час злощасної корабельної аварії.",al={"навіщо ґелкаку ключ","призначення ключа ґелкака","ключ помічника"}},{q="Куди поділися три частини ключа?",a="Коли ключ зламався на березі, його частини розтягли місцеві створіння: верхню забрали лісоступи, середню — мурлоки Сірої Імли, а нижню — прибережні рифові повзуни.",al={"де частини ключа","хто вкрав ключ","зламаний ключ темне узбережжя"}},{q="Що гном-пірат робив біля Темного Узбережжя?",a="Ґелкак плавав водами північного Калімдору в пошуках здобичі, але ворожі трешадони раптово поклали край його подорожі.",al={"чому ґелкак на темному узбережжі","пірати темного узбережжя"}},{q="Що буде, коли ключ складено?",a="Щойно в Ґелкака будуть усі три частини ключа, він зможе завести свого товариша — це веде просто до завдання «Помста Джайромаста».",al={"що після ключа","продовження пропажі джайромаста"}},{q="Що за мурлоки тримають частину ключа?",a="Середню частину підібрало плем'я мурлоків Сірої Імли, що оселилося серед уламків затонулих кораблів на мілинах Темного Узбережжя.",al={"мурлоки темного узбережжя","мурлоки сірої мли ключ","мурлоки розбитого корабля"}}},fp="20,328,21.381.0,17.468.0,20.376.1,23.148.0,25.145.0,41.194.0,46.137.0,42.144.1,42.150.0"}
P.entries["quest:21"] = {n="Сутичка на Ехо-Рідж",s="«Сутичка на Ехо-Рідж» — пряма військова операція за наказом Маршала Макбрайда: очистити Шахту Ехо-Рідж від кобольдів-робітників. Після першої розвідки цей удар має не дати підземній заразі закріпитися в Долині Нортширу назавжди.",h="«Сутичка на Ехо-Рідж» — пряма військова операція за наказом Маршала Макбрайда: очистити Шахту Ехо-Рідж від...",kw={"ехо-рідж","кобольди","шахта","сутичка","маршал макбрайд","нортшир"},ang={["class:Warrior"]="Підземні бійки проти роїв робітників дають молодим воїнам перший смак ближнього бою проти багатьох укріплених ворогів.",["faction:Alliance"]="Кожна відбита в чудовиськ шахта дає камінь і руду, без яких не відбудувати й не зміцнити людські поселення після війни.",["profession:Mining"]="Зачистка шахти від зарази повертає надію, що цінні рудні жили Долини Нортширу знову можна буде безпечно розробляти й виплавляти.",["race:Human"]="Зачистка Ехо-Ріджу — перше справжнє бойове випробування новобранця на захист рідного королівства, у якому він доводить свою доблесть просто перед військовим командуванням Стормвінда."},sec={{t="Зачистка шахти",b="Щойно розвідка підтвердила, що кобольди заполонили Шахту Ехо-Рідж, Маршал Макбрайд не гаючись організував рішучу контратаку. Якщо підземних шкідників не чіпати, вони швидко укріплюють тунелі, накопичують крадені запаси й плодяться без упину. Щоб захистити Долину Нортширу — важливий землеробський і духовний осередок, — місцевий гарнізон покладається на новобранців: ті мають стати до бою з кобольдами-робітниками й проріджувати їхні лави, поки ті не вкоренилися ще глибше."},{t="Тонка оборона",b="Те, що для прямого лобового штурму доводиться залучати щойно зарахованих новобранців, свідчить про виснажений стан армії Стормвінда. Передові гарнізони розтягнуті вздовж південних кордонів, по всьому Елвінну ширяться чутки про заворушення, тож місцевим офіцерам на кшталт Макбрайда доводиться збирати будь-які охочі руки. Успішна сутичка на Ехо-Рідж доводить надійність новобранця, здобуває йому справжню повагу й готує до важливіших місій деінде в королівстві."}},faq={{q="Чому кобольди заполонили Шахту Ехо-Рідж?",a="Кобольдів природно вабить до багатих на руду підземних тунелів і покинутих кар'єрів. Військо Стормвінда розпорошене, тож неохоронювані місця на кшталт Ехо-Ріджу легко стали здобиччю для паразитів, що шукають, де вирити нори, накопичити золото й закріпитися під землею.",al={"чому кобольди в шахті","кобольди ехо-рідж","що роблять кобольди"}},{q="Хто наказує провести сутичку?",a="Операцією командує Маршал Макбрайд — старший офіцер Армії Стормвінда в Абатстві Нортшира. Він відповідає за оборону долини й мусить підтримувати лад, попри брак військових.",al={"хто дає сутичку","накази маршала макбрайда"}},{q="Яке стратегічне значення має Шахта Ехо-Рідж?",a="Ехо-Рідж дає камінь і руду, без яких не обійтися ні в утриманні Нортширу, ні в ширшій відбудові Стормвінда. Якщо дати кобольдам розплодитися просто на північній межі Нортширу, це стане прямою загрозою для абатства й сусідніх виноградників.",al={"чому важлива ехо-рідж","значення шахти ехо-рідж"}},{q="Куди веде це доручення далі?",a="Коли шахту очищено від першого опору кобольдів-робітників, Маршал Макбрайд визнає бойову вправність шукача пригод і посилає його до Ґолдширу допомагати ширшій обороні краю.",al={"яке завдання після сутички","наступний крок після ехо-рідж"}},{q="Чому Армія Стормвінда не зачистить шахту сама?",a="Армії Стормвінда гостро бракує людей: вона ледве боронить далекі кордони й відповідає на розбій по всьому Елвінну. Офіцери на кшталт Макбрайда мусять покладатися на щойно присягнулих новобранців, щоб ті впоралися з місцевими загрозами, поки досвідчені вартові тримають оборону.",al={"чому новобранці","де солдати стормвінда"}},{q="Чи досить кобольди розумні, щоб бути організованою військовою загрозою?",a="Поодинці кобольди-робітники боягузливі й простакуваті, але великою зграєю вони небезпечно територіальні й агресивні. Якщо їх не стримувати, вони швидко риють заплутані тунелі, ставлять пастки в печерах і закликають до себе більших, краще озброєних паразитів.",al={"чи кобольди розумні","рівень небезпеки кобольдів"}}},fp="22,283,16.486.0,14.500.0,46.266.0,24.223.0,52.263.0,34.203.0,57.260.0,66.252.0"}
P.entries["quest:2118"] = {n="Заражені землі",s="«Заражені землі» — завдання Альянсу, яке дає Тарнаріун Трітендер на Темному Узбережжі. Прагнучи зупинити порчу, що вражає місцевих звірів, Тарнаріун доручає шукачам пригод живцем упіймати скаженого будякового ведмедя за допомогою зачарованої реліквії, щоб спробувати його вилікувати.",h="«Заражені землі» — завдання Альянсу, яке дає Тарнаріун Трітендер на Темному Узбережжі.",kw={"заражені землі","тарнаріун трітендер","надія тарнаріуна","будякові ведмеді","порча","темне узбережжя"},ang={["class:Druid"]="Друїди поділяють горе Тарнаріуна, бачачи спотворену природу, а трагічна загибель ведмедя підкреслює, як глибоко проникла підступна хвороба землі.",["faction:Alliance"]="Мандрівникам Альянсу на півночі Калімдору доводиться зважати на неприборкану порчу, що підступає просто до меж заселених земель.",["race:NightElf"]="Для калдореїв бачити, як рослини й звірі Темного Узбережжя занепадають і впадають у скажене божевілля, — образа Кенарію й рівновазі природи, яку вони присягнули берегти."},sec={{t="Пошесть у нетрях",b="Лісами Темного Узбережжя повзе зловісна недуга, що перетворює звірів на шалені, агресивні тіні самих себе. Найбільше від цього божевілля потерпають місцеві будякові ведмеді: їх охоплює скажений шал, що загрожує і мандрівникам, і крихкій природній гармонії узбережжя. Вартові нічних ельфів часто відповідають на це сталлю, а друїди прагнуть зрозуміти й вилікувати першопричину."},{t="Надія Тарнаріуна",b="Не бажаючи вбивати зіпсованих звірів, не спробувавши їх урятувати, Тарнаріун Трітендер змайстрував особливу пастку — Надію Тарнаріуна. Шукачі пригод кладуть пристрій на лісову підстилку, і його лагідне світло на якийсь час заспокоює розум розлюченого будякового ведмедя. Угамований звір покірно йде за мандрівником до табору Тарнаріуна для вивчення."},{t="Трагічні ліки",b="Коли шукач пригод приводить зараженого ведмедя до табору, Тарнаріун одразу намагається вигнати хворобу відновлювальною магією. На жаль, перша спроба закінчується катастрофою: вирування очищувальних енергій перевантажує ослаблений організм звіра, і той падає й гине на місці. Ця невдача показує, як глибоко вкоренилася темна моровиця."}},faq={{q="Хто дає завдання «Заражені землі»?",a="Це завдання дає Тарнаріун Трітендер — друїд з нічних ельфів в Обердайні на Темному Узбережжі, який прагне вилікувати хворих звірів.",al={"хто дає заражені землі","завдання тарнаріуна темне узбережжя","хто починає заражені землі"}},{q="Яка мета завдання «Заражені землі»?",a="Треба скористатися виданим предметом — Надією Тарнаріуна, — щоб упіймати й угамувати Скаженого Будякового Ведмедя на Темному Узбережжі, а тоді привести приборкану тварину живою до Тарнаріуна.",al={"мета заражених земель","що робити в заражених землях","як упіймати ведмедя темне узбережжя"}},{q="Що стається з ведмедем, коли його привести?",a="Тарнаріун намагається очистити тварину цілющою магією, але хвороба зайшла надто далеко. Тварина не витримує й гине одразу після лікування.",al={"чи ведмідь помирає","результат лікування ведмедя","смерть ведмедя заражені землі"}},{q="Яким предметом ловлять ведмедя?",a="Тарнаріун дає зачарований пристрій-пастку на ім'я Надія Тарнаріуна: він випромінює заспокійливе світло, що угамовує розлюченого ведмедя, і той іде за вами.",al={"пастка заражених земель","надія тарнаріуна предмет","клітка для ведмедя"}},{q="Яке завдання йде після «Заражених земель»?",a="«Заражені землі» — перший розділ ланцюжка з трьох частин. Далі відкривається завдання «Очищення заражених», яке зрештою веде до останнього — «Надія Тарнаріуна».",al={"наступне завдання після заражених земель","ланцюжок заражених земель","продовження тарнаріуна"}},{q="Чому будякові ведмеді скажені?",a="Темним Узбережжям повзе нищівна пошесть, що отруює розум і тіло місцевих звірів і доводить шляхетних будякових ведмедів до безтямної люті.",al={"чому ведмеді хворі на узбережжі","чума ведмедів темного узбережжя","скверна темного узбережжя"}}},fp="13,269,26.422.0,17.371.0,15.390.1,34.139.0,39.161.0,48.186.1,41.155.0,33.189.0,32.171.0"}
P.entries["quest:2138"] = {n="Очищення заражених",s="«Очищення заражених» — завдання Альянсу на Темному Узбережжі, яке дає Тарнаріун Трітендер в Обердайні. Коли спроба лікування не зупиняє лісової хвороби, доглядач неохоче наказує вибити скажених будякових ведмедів, що блукають імлистими нетрями. Це гіркий поворотний момент, коли збереження поступається стримуванню.",h="«Очищення заражених» — завдання Альянсу на Темному Узбережжі, яке дає Тарнаріун Трітендер в Обердайні.",kw={"очищення заражених","тарнаріун трітендер","будякові ведмеді","обердайн","моровиця","темне узбережжя"},ang={["class:Druid"]="Друїдам, що шанують диких ведмежих духів, наказ Тарнаріуна особливо болить: це вчинок милосердя й лісового сортування, а не звичайне полювання.",["class:Hunter"]="Мисливці розуміють, що іноді хворих хижаків доводиться відстрілювати, щоб уберегти ширшу природу, навіть коли першопричину ще не з'ясовано.",["race:NightElf"]="Для калдореїв наказ убивати зіпсованих звірів — тяжкий тягар, що показує, як глибоко повоєнна порча проникла на землю їхніх предків."},sec={{t="Гірка необхідність",b="Тарнаріун Трітендер довгі години шукав засобу, щоб зупинити повзучу недугу, яка нівечить звірів Темного Узбережжя. Попри спробу очистити впійманого ведмедя, будякові ведмеді лишаються тяжко хворими й лютими. Вичерпавши лагідніші способи, нічний ельф-доглядач доходить висновку, що єдиний негайний спосіб не дати звірам калічити інших створінь і розносити хворобу далі давніми лісами — це вбити їх."},{t="Стримати дику природу",b="Убити двадцять скажених ведмедів — болісний обов'язок для кожного служителя природи. Тарнаріун прямо визнає, що вбивство звірів не вилікує прихованої моровиці, але дає захисникам Обердайна дорогоцінний час. Доки не вдасться знайти й перерізати головне джерело лісової порчі, проріджування агресивних звірів лишається для поселення єдиним захистом від катастрофи."}},faq={{q="Чому Тарнаріун хоче вбити будякових ведмедів, а не вилікувати?",a="Тарнаріун уже намагався очистити впійманого ведмедя, але ліки не допомогли, і звір загинув. Хворі ведмеді шаленіють і загрожують іншим створінням, тож убити їх — останній засіб, щоб уповільнити поширення хвороби.",al={"чому вбити ведмедів","чому не вилікувати ведмедів","завдання тарнаріуна про ведмедів"}},{q="Хто такий Тарнаріун Трітендер?",a="Тарнаріун — нічний ельф, охоронець природи з Обердайна. Він вивчає хвороби, що вразили рослини й тварин Темного Узбережжя, і намагається зберегти природну рівновагу проти скверни, що поширюється.",al={"роль тарнаріуна","хто дає очищення заражених"}},{q="Чи справді вбивство скажених ведмедів зупиняє пошесть?",a="Ні. Тарнаріун прямо попереджає, що вбивство скажених ведмедів не спинить пошесті. Це лише дає лісові й мешканцям Обердайна дорогоцінний час, уповільнюючи зараження й насильство.",al={"чи це виправить узбережжя","чи чуму зупинено"}},{q="Що далі після «Очищення заражених»?",a="Коли ви повернетеся до Тарнаріуна, він просить вас приготуватися душею до нового кровопролиття й пропонує наступне завдання — «Надія Тарнаріуна», щоб і далі боротися з ураженими звірами.",al={"наступне завдання після очищення","що після очищення заражених"}},{q="Де водяться скажені будякові ведмеді?",a="Скажені будякові ведмеді никають прибережними й глибинними лісами центральної частини Темного Узбережжя, часто серед туманних сосон на південь і схід від Обердайна.",al={"місце скажених будякових ведмедів","де ведмеді темне узбережжя"}},{q="Що зробило будякових ведмедів скаженими?",a="Ведмеді — жертви загадкової скверни, що прокочується лісами північного Калімдору й перетворює мирних звірів на шалених, агресивних тварюк, яких не бере навіть Тарнаріунове лікування.",al={"чому ведмеді хворі","хвороба ведмедів узбережжя"}}},fp="25,344,18.466.0,20.402.1,67.232.0,29.192.0,53.202.0,43.189.0,40.159.0,42.192.0"}
P.entries["quest:2139"] = {n="Надія Тарнаріуна",s="«Надія Тарнаріуна» — похмуре завершення зусиль Тарнаріуна Трітендера стримати хворобу звірів Темного Узбережжя. Після того як по всіх лісах із милосердя вбито чимало заражених звірів, звитяжцеві Альянсу доручають здолати скажену Матір Лігва на північний схід від Обердайна.",h="«Надія Тарнаріуна» — похмуре завершення зусиль Тарнаріуна Трітендера стримати хворобу звірів Темного...",kw={"надія тарнаріуна","матір лігва","тарнаріун трітендер","будякові ведмеді","башал'аран","обердайн"},ang={["class:Druid"]="Друїди високо шанують ведмедів за науками Урсока. Убити зіпсовану Матір Лігва — урочисте нагадування про крихку рівновагу природи й трагедії, які несе порча.",["class:Hunter"]="Мисливці розуміють трагедію верховного хижака, якого хвороба звела з розуму, і знають, коли вбити зараженого звіра — найщиріший прояв милосердя.",["faction:Alliance"]="Захищаючи Обердайн, Альянс зміцнює опору на північному узбережжі Калімдору й доводить, що готовий боронити землі нічних ельфів від дедалі грізніших загроз дикої природи.",["race:NightElf"]="Для нічних ельфів убивати лісових звірів — тим паче ведмедицю-матріарха — суперечить їхній глибинній шані до природи, тож цей обов'язок — гірка й сумна необхідність."},sec={{t="Трагічна необхідність",b="Після Третьої війни дикі створіння Темного Узбережжя почали піддаватися протиприродній, скаженій хворобі. Тарнаріун Трітендер, що живе в Обердайні, днями доручав мандрівникам добивати заражених звірів, щоб полегшити муки лісу. Але відстріл скажених будякових ведмедів лише лікував симптоми. Щоб зупинити поширення, він вирішив, що треба вирізати джерело серед місцевих ведмедів — матріарха, відому як Матір Лігва."},{t="Матір Лігва",b="Матір Лігва, що ховається в печері на північний схід від Обердайна, біля давніх руїн Башал'Арана, колись була важливою охоронницею лісової звірини. Поглинута шаленою недугою, що шириться північчю Калімдору, вона раз у раз народжувала й вигодовувала виводки скажених ведмежат. Вистеживши матріарха в її лігві, герої Альянсу поклали край її мукам і стримали навалу шалених ведмедів, що нишпорили прибережним трактом."},{t="Сувора правда Калімдору",b="Після загибелі Матері Лігва Тарнаріун висловлює глибоку вдячність, хоч і затьмарену сумом. Для калдореїв підіймати зброю на лісових створінь — болісний обов'язок. Та поки темні сили тиснуть на їхній новий дім, а багато хто впадає у відчай чи шукає прихистку, такі вчинки доводять: захисники Обердайна готові нести тяжкий моральний тягар, потрібний, щоб уберегти свої ліси."}},faq={{q="Хто такий Тарнаріун Трітендер?",a="Тарнаріун Трітендер — нічний ельф, охоронець природи з Обердайна. Пригнічений пошестю й божевіллям, що спотворюють звірів Темного Узбережжя, він керує зусиллями з їхнього вивчення, вистежування й зрештою — позбавлення від мук.",al={"тарнаріун","хто дає надію тарнаріуна","трітендер обердайн"}},{q="Де живе Матір Лігва?",a="Вона живе в печері серед пагорбів на північний схід від Обердайна, трохи на схід від руїн Башал'Арана.",al={"де матір лігва","печера матері лігва","знайти матір лігва"}},{q="Чому Матір Лігва треба вбити, а не вилікувати?",a="Хвороба, що лютує серед звірів Темного Узбережжя, глибоко вкорінилася й доводить тварин до шаленства. Ліків поки немає, а Матір Лігва ще й вирощує скажений молодняк, тож Тарнаріун вирішив, що лише її смерть зупинить подальше поширення хвороби.",al={"чи можна врятувати матір лігва","чому вбити матір лігва","вилікувати матір лігва"}},{q="Які завдання ведуть до «Надії Тарнаріуна»?",a="Це завдання — останній крок ланцюжка з трьох частин. Він починається із «Заражених земель», продовжується «Очищенням заражених» і завершується «Надією Тарнаріуна».",al={"передумови надії тарнаріуна","ланцюжок тарнаріуна"}},{q="Що робить звірів Темного Узбережжя хворими?",a="Тарнаріун не називає джерела. Він знає лише, що Темним Узбережжям поширюється хвороба, яка опановує розум і тіло всіх, кого торкнеться, і що найдужче вона вразила будякових ведмедів.",al={"чому ведмеді скажені на узбережжі","причина чуми тварин узбережжя","що осквернило ведмедів"}},{q="Чому Тарнаріун згадує людей, що тікають до укріплених земель?",a="Обердайн — незахищена прибережна застава, яку обступили привиди, зіпсовані звірі й ворожі створіння. Цивілізація нічних ельфів ледве відбудовується після навали Палаючого Легіону, і дехто з мешканців, не витримуючи, ховається чи відступає до безпечніших твердинь Альянсу.",al={"тікають з обердайна","укріплені землі альянсу"}}},fp="17,272,18.445.0,14.431.1,28.400.0,29.234.0,32.110.0,51.305.0,41.170.0,45.198.0,63.294.0"}
P.entries["quest:214"] = {n="Червоні шовкові бандани",s="«Червоні шовкові бандани» — доручення Розвідника Рієлла від імені Народного ополчення. Воно скеровує шукачів пригод з Альянсу до Мертвих Копалень полювати на високопоставлених агентів Дефіас і приносити як доказ їхні впізнавані червоні шовкові маски.",h="«Червоні шовкові бандани» — доручення Розвідника Рієлла від імені Народного ополчення.",kw={"червоні шовкові бандани","розвідник рієлл","мертві копальні","братство дефіас","шовк","народне ополчення"},ang={["class:Rogue"]="Червоні шовкові маски Дефіас — сумнозвісна традиція підпільного ремесла: їх носять бувалі головорізи й таємні змовники.",["faction:Alliance"]="Кожен офіцер, що впав у Мертвих Копальнях, послаблює задушливу хватку Братства на горлі житниці Королівства Стормвінд.",["profession:Tailoring"]="Тонкий червоний шовк — дорога розкіш для звичайних бандитів, і це добре показує, як щедро споряджене й фінансоване керівництво Братства."},sec={{t="Ієрархія в тканині",b="Звичайні кишенькові злодії й грабіжники з великої дороги по всьому Вестфолу пов'язують обличчя грубою червоною тканиною, але Братство Дефіас дотримується суворої внутрішньої ієрархії, і її видно з матерії. Розвідник Рієлл і Народне ополчення з'ясували: рядові бандити носять грубе полотно, а старші змовники й агенти з найближчого кола вирізняються тонким червоним шовком. Полювання на ці бандани — прицільний удар по досвідчених офіцерах, що керують заколотом Едвіна Венкліфа."},{t="Удар у серце",b="Шовк означає старшинство, тож найбільше таких високопоставлених розбійників зібралося глибоко в Мертвих Копальнях під Мунбруком. Вартові й розвідники за межами Сентінел Гілла покладаються на вільних звитяжців, готових пробитися в спірні підземні тунелі. Кожна здобута шовкова бандана — це на одного лейтенанта менше, хто готує засідки, охороняє схованки зброї чи насаджує владу Венкліфа по всьому Вестфолу."}},faq={{q="Чому Дефіас носять червоні бандани?",a="Червона бандана — спільна емблема й візитівка Братства Дефіас по всіх землях Стормвінда. Вона приховує обличчя й водночас показує належність до бунтівного руху Едвіна Венкліфа.",al={"значення масок дефіас","чому червоні маски","форма дефіас"}},{q="Чим червоні шовкові бандани відрізняються від звичайних?",a="За словами Розвідника Рієлла, тканина вказує на становище в Братстві. Звичайні вуличні головорізи носять грубу дешеву тканину, а ветерани, офіцери й довірені помічники отримують червоний шовк.",al={"чому червоний шовк","шовк проти тканини дефіас","різниця шовкової бандани"}},{q="Хто такий Розвідник Рієлл?",a="Розвідник Рієлл — агент Народного ополчення у Вестфолі, якому доручено стежити за пересуванням Дефіас і спрямовувати шукачів пригод на їхні твердині довкола Мертвих Копалень.",al={"розвідник рієлл вестфол","хто дає червоні шовкові бандани"}},{q="Де шукати Дефіас із шовковими банданами?",a="Вони зосереджені в Мертвих Копальнях і довкола них, під містечком Мунбрук, де старші загони Едвіна Венкліфа керують підземними справами.",al={"де шукати шовкові бандани","місце шовкових бандан мертві копальні"}},{q="Що таке Народне ополчення?",a="Народне ополчення — добровольча оборонна сила, яку створили Ґраян Стаутмантл і обложені фермери Вестфолу, щоб захистити свої землі, коли армія Стормвінда не надала їм належних гарнізонів.",al={"хто такі народне ополчення","народне ополчення вестфол"}},{q="Чи мають ці бандани якусь користь, крім доказу вбивства?",a="Для Народного ополчення вони — лише незаперечний доказ того, що високопоставлених злочинців усунуто, а отже, командну структуру Братства послаблено.",al={"чи можна носити червону шовкову бандану","для чого бандани"}}},fp="17,240,20.475.0,17.421.0,36.216.0,70.196.0,19.186.0,51.149.0,29.201.0,57.165.0"}
P.entries["quest:2159"] = {n="Посилка для Доланаара",s="«Посилка для Доланаара» — доручення для молодих нічних ельфів, що покидають затишне віття Тінедолу заради ширших просторів Тельдрассила. Портанніус, затриманий справами з тутешніми друїдами, доручає мандрівникам віднести пакунок трав на південь, Корчмареві Келдаміру. Проста подорож позначає перехід посвяченого в гамірний осередок Доланаара.",h="«Посилка для Доланаара» — доручення для молодих нічних ельфів, що покидають затишне віття Тінедолу заради...",kw={"посилка для доланаара","портанніус","корчмар келдамір","трави","тінедол","доланаар","тельдрассил"},ang={["class:Druid"]="Заклопотаність Портанніуса друїдами Тінедолу натякає на глибші духовні обов'язки й порушення природної рівноваги, якими переймається Коло Кенарія у вітті.",["profession:Herbalism"]="Доставка показує, які важливі сирі трави з родючих ґрунтів Тінедолу для цілителів, кухарів і доглядачів Доланаара.",["race:NightElf"]="Узятися за це завдання означає для нічного ельфа покинути захищену колиску Алдрассила заради ширшої відповідальності за захист Тельдрассила."},sec={{t="Гінець для Тінедолу",b="Перш ніж нові шукачі пригод покинуть навчальні угіддя Тінедолу, Портанніус шукає когось, хто прямує дорогою до решти Тельдрассила. Заклопотаний нагальними справами з друїдами, що доглядають долину, він не може відірватися, щоб самому бігати з буденними дорученнями. Натомість він вкладає в руки майбутнього героя в'язку свіжозібраних трав, щоб важливі припаси дісталися на південь лісовою стежкою."},{t="Дорога до Доланаара",b="Південна дорога з відлюдної долини веде мандрівників до Доланаара — одного з найважливіших поселень нічних ельфів на великому вітті Тельдрассила. Там Корчмар Келдамір порядкує гостинністю, відпочинком і припасами для подорожніх, вартових і друїдів. Приймаючи трави від імені Портанніуса, Келдамір користається нагодою закликати молодих шукачів пригод дати спочинок розуму й духові, перш ніж стати проти скверни, що шириться світовим деревом."}},faq={{q="Хто такий Портанніус?",a="Портанніус — нічний ельф, що живе в Тінедолі, першій долині Тельдрассила. Він тісно співпрацює з місцевими друїдами й просить мандрівників, які покидають долину, віднести від його імені припаси на південь.",al={"портанніус","хто дає доставку для доланаара","хто дає завдання портанніус"}},{q="Чому Портанніус не може сам доставити трави?",a="Портанніус має нагальні, незавершені справи з друїдами Тінедолу. Обов'язки тримають його в затишній долині, тож він мусить покладатися на мандрівних шукачів пригод.",al={"чому портанніусу потрібна допомога","чому портанніус не може піти"}},{q="Що в посилці?",a="У посилці — трави, зібрані в Тінедолі, для корчми в Доланаарі.",al={"вміст посилки доланаара","які це трави"}},{q="Хто такий Корчмар Келдамір?",a="Корчмар Келдамір тримає корчму в Доланаарі. Крім гостинності, ночівлі й каменів повернення для мандрівників, він часто влаштовує торгівлю й обмін припасами з іншими поселеннями Тельдрассила.",al={"келдамір","корчмар доланаара","хто отримує трави"}},{q="Де розташований Доланаар?",a="Доланаар лежить на південь від Тінедолу. Головний шлях, що веде з виходу долини, приводить мандрівників просто в центр містечка.",al={"де доланаар","місце доланаара","як дістатися доланаара"}},{q="Чому ця доставка важлива для молодих шукачів пригод?",a="Це знайомство зі світом за межами Тінедолу: воно заохочує новачків вийти за межі тренувальних угідь і відкрити для себе корчму, наставників і послуги Доланаара.",al={"значення доставки","навіщо доставляти трави"}}},fp="17,359,26.414.0,20.466.0,19.211.0,48.201.0,27.111.0,26.216.0,26.140.0,53.187.0"}
P.entries["quest:2160"] = {n="Припаси для Таннока",s="Припаси для Таннока — доручення для шукачів пригод-початківців, що залишають Долину Холодного Хребта небезпечним гірським перевалом у великий Дун Мороґ. Гном-майстер Гендс Спрінґспрокет посилає ящик потрібних харчів Танноку Фростгаммеру до корчми при Ґуральні Тандербрю в Хараносі в обхід кишачих трогами стежок, що перерізали звичну торгівлю.",h="Припаси для Таннока — доручення для шукачів пригод-початківців, що залишають Долину Холодного Хребта...",kw={"припаси для таннока","гендс спрінґспрокет","таннок фростгаммер","ящик","перевал холодного кряжа","ґуральня тандербрю","харанос"},ang={["faction:Alliance"]="Відновлення торгівлі між відрізаними заставами тримає внутрішні лінії постачання Айронфорджа в русі попри дикі набіги трогів.",["race:Dwarf"]="Пронести припаси з Анвілмара до Хараноса — ваш обряд посвяти: вихід із захищеної долини на службу ширшому королівству Айронфорджа.",["race:Gnome"]="Допомога Гендсу Спрінґспрокету показує надійну співпрацю між вигнанцями Гномреґану та їхніми дворфійськими господарями в Дун Мороґу."},sec={{t="Заблокована долина",b="Долина Холодного Хребта традиційно полігон і прихисток для молодих дворфів Айронфорджа й уцілілих вигнанців Гномреґану, але недавні події підірвали її зв'язок із рештою Дун Мороґу. Набіги трогів заполонили Перевал Холодного Кряжа, і гірську тіснину стало небезпечно переходити. Горяни розтягнуті тонко, стережучи поселення й оборонні периметри, тож заплановані супроводи припасів затримуються на багато днів."},{t="Гендс і помічник корчмаря",b="Гендс Спрінґспрокет, гном, що зупинився в Анвілмарі, опинився з ящиком життєво важливих корчемних припасів для Хараноса й без жодного безпечного способу доправити його особисто. Знаючи, що витривалі шукачі пригод уже готуються кинути виклик небезпечному перевалу, він залучає мандрівників, що вирушають у дорогу, пронести вантаж Танноку Фростгаммеру, помічникові в людній корчмі Тандербрю."},{t="Гостинне вогнище в Хараносі",b="Дістатися Хараноса — для шукача пригод вхід у ширший світ Дун Мороґу. Таннок Фростгаммер радо приймає доставку, зауважуючи, що звісток з Анвілмара бракувало, відколи троги зірвали рух через перевал. Доправлений крам відновлює крихку лінію зв'язку й торгівлі між двома відрізаними дворфійськими громадами."}},faq={{q="Хто такий Гендс Спрінґспрокет?",a="Гендс Спрінґспрокет — заповзятливий гном з Анвілмара в Долині Холодного Хребта. Він не може сам пройти небезпечним гірським перевалом, тож покладається на вправних мандрівників, щоб ті доставили товари до Хараноса.",al={"гендс спрінґспрокет","хто дає завдання","хто дає припаси таннока"}},{q="Хто такий Таннок Фростгаммер?",a="Таннок Фростгаммер — помічник корчмаря в Ґуральні Тандербрю в Хараносі. Він допомагає з господарством корчми й приймає припаси з таких застав, як Анвілмар.",al={"таннок","таннок фростгаммер","помічник корчмаря хараноса"}},{q="Чому Гендс не може сам доставити припаси?",a="Перевал, що сполучає Долину Холодного Хребта з Хараносом, заполонили ворожі троги. Гендс не має чим пробиватися сам, а супровід горян добряче затримується.",al={"чому гендс не може сам","чому потрібен шукач пригод","чому перевал небезпечний"}},{q="Де корчма в Хараносі?",a="Таннок Фростгаммер — у Ґуральні Тандербрю, великій корчмі в самому центрі Хараноса, на головному шляху, що веде на схід до Айронфорджа.",al={"де таннок","місце винокурні тандербрю","місце корчми хараноса"}},{q="Що в Ящику із Припасами для Корчми?",a="У ящику — найпотрібніші корчемні дрібниці й харчі, зібрані в Анвілмарі, щоб поповнити запаси корчми Тандербрю в Хараносі.",al={"що в ящику","ящик припасів корчми"}},{q="Чому зв'язок між Анвілмаром і Хараносом обірвано?",a="Троги, що вилізли з підземних тунелів, заполонили Перевал Холодного Кряжа. Через їхню агресію пішки вже не пройти, і звичайне листування між Долиною Холодного Хребта й рештою Дун Мороґу обірвалося.",al={"чому мало вістей з анвілмара","проблема трогів на перевалі"}}},fp="18,367,18.421.0,35.383.0,30.353.0,28.205.0,26.196.0,45.192.0,37.174.0,41.140.0,59.201.0"}
P.entries["quest:2161"] = {n="Тягар пеона",s="«Тягар пеона» — вступне завдання з доставки від Укора, стривоженого орка-робітника, що застряг на стежці за межами Долини Випробувань. Спробувавши доставити харчі новобранцям, яким вони виявилися непотрібні, Укор доручає мандрівникам безпечно повернути важкий вантаж до Гострого Пагорба.",h="«Тягар пеона» — вступне завдання з доставки від Укора, стривоженого орка-робітника, що застряг на стежці за...",kw={"тягар пеона","укор","пеон","робітник","припаси","гострий пагорб","долина випробувань"},ang={["faction:Horde"]="Цей перехід — вихід із тренувальних земель, що знайомить мандрівників із Гострим Пагорбом, головним осередком оборони й постачання Орди в південному Дуроторі.",["race:Orc"]="Орча культура цінує фізичну міць і відвагу, тож пеони на кшталт Укора опиняються на самому дні суспільної ієрархії; виконати його доручення — означає побачити, як навіть скромна праця тримає молоду націю Дуротару на плаву."},sec={{t="Доставка не за адресою",b="Укор — щирий пеон, що вирушив із Гострого Пагорба з добрими намірами, тягнучи важкий пакунок харчів до Долини Випробувань. Вірячи, що новобранцям у червоному каньйоні конче потрібні харчі, він подолав дорогу лише для того, щоб його відіслали геть. Наглядачі випробувань навмисне тримають припаси мізерними: як згодом зауважує Корчмар Ґроск, виживання на пісному харчі вважають способом гартувати дисципліну й витривалість молодих воїнів Орди."},{t="Небезпеки червоної пустки",b="Хоч Укор дістався перевалу, повертатися випаленою сонцем землею Дуротару йому страшно. Скелі вздовж стежки кишать агресивними скорпідами, отруйними павуками й вепрами, що нишпорять довкола. Без зброї, броні й бойового духу, якого чекають від орчих бійців, наляканий робітник чекає при дорозі й благає кожного шукача пригод, що покидає тренувальні землі, узяти на себе його тягар і повернути його до корчми."}},faq={{q="Хто такий Укор?",a="Укор — орк-пеон, що стоїть при шляху з Долини Випробувань. Добрий, але боязкий, він вирушив доставити харчі з Гострого Пагорба, а тоді зрозумів, що надто боїться місцевих звірів, щоб повернутися самому.",al={"укор","хто пеон на дорозі","пеон біля долини випробувань"}},{q="Чому наставникам у Долині Випробувань не потрібна була їжа?",a="Наглядачі в Долині Випробувань вірять у сувору дисципліну для молодих новобранців. Як жартома зауважує Корчмар Ґроск, наставники воліють тримати учнів голодними, щоб загартувати їх і зміцнити дух, тож Укорова щедра доставка там нікому не знадобилася.",al={"чому відмовилися від їжі","чому укор ніс їжу","голод корчмаря ґроска"}},{q="Куди треба доставити вантаж?",a="Вантаж треба віднести на північ головним шляхом Дуротару до Гострого Пагорба й віддати Корчмареві Ґроску в місцевій корчмі.",al={"де разор гілл","кому віддати їжу","куди доставити тягар укора"}},{q="Чим ця подорож небезпечна для пеона?",a="Скелясті пустирі Дуротару кишать агресивними скорпідами, отруйними павуками-повзунами й дикими вепрами. Досвідчені новобранці дадуть раду таким тварюкам, але незахищений і ненавчений робітник на кшталт Укора, якщо на нього нападуть, має мало шансів.",al={"чому укор боїться","небезпеки дороги дуротара"}},{q="Яка роль пеонів в Орді?",a="Пеони — найнижчий щабель орчого суспільства: вони виконують чорну роботу — тягають припаси, рубають ліс, зводять укріплення. Бійців і поборників славлять, а пеонів часто не помічають, хоча саме вони годують і доглядають поселення.",al={"пеони орків лор","статус пеонів","хто такі пеони"}},{q="Хто такий Корчмар Ґроск?",a="Корчмар Ґроск тримає корчму на Гострому Пагорбі. Він дає раду ночівлі й припасам містечка, пропонує мандрівним воїнам їжу, питво й тепло вогнища й нагадує новобранцям, що перш ніж рушати у світ, треба добре відпочити.",al={"корчмар ґроск","ґроск разор гілл","корчмар разор гілл"}}},fp="15,305,20.477.0,23.460.0,12.254.0,62.278.0,36.156.0,44.229.0,39.269.0,23.222.0"}
P.entries["quest:217"] = {n="На захист королівських земель",s="Завдання «На захист королівських земель» завершується прямим ударом по ватажках навали трогів у Лох Модані. Дворфійські розвідники з'ясували, що за лютим нашестям стоїть Ватажок Ґраумуґ зі своїми охоронцями-громилами, що засіли глибоко в Долині Кам'яного Уламка. Капітан Руґелфусс доручає сміливим шукачам пригод з Альянсу вбити ватажка, щоб зламати дух трогів і повернути південні кордони королівства.",h="Завдання «На захист королівських земель» завершується прямим ударом по ватажках навали трогів у Лох Модані.",kw={"на захист королівських земель","ґраумуґ","троги","долина кам'яного уламка","капітан руґелфусс","лох модан","завдання"},ang={["faction:Alliance"]="Захищаючи Лох Модан, ви зберігаєте важливе суходільне сполучення між Айронфорджем і східним порубіжжям, а з ним — безпечне постачання для всіх сил Альянсу.",["race:Dwarf"]="Для дворфів відкинути трогів з давньої землі Каз Модану — справа захисту батьківщини й честі, щоб гірські твердині не опоганила підземна напасть."},sec={{t="Відтяти голову зграї",b="Невгамовна загроза трогів у південному Лох Модані виявилася чимось більшим, ніж безладне підземне повзання. Розвідники Капітана Руґелфусса з'ясували, що троги Кам'яного Уламка діють під грубим проводом ватажка на ім'я Ґраумуґ. На відміну від звичайних розпорошених грабіжників, ця зграя нападає злагоджено й люто і, якщо її не спинити, загрожує заполонити Королівські землі. Дворфійські оборонці сподіваються, що бій у самому лігві й страта Ґраумуґа разом із його особистими громилами розладнають зграю й зупинять навалу."},{t="У лігво Кам'яного Уламка",b="Ґраумуґ тримає оборону в темній печері, захованій у південно-східних скелях Долини Кам'яного Уламка. В оточенні найвірніших громил — Гнешера й Бійцівського — ватажок становить небезпечне випробування для вояків-одинаків. Знищення цього найближчого кола кидає решту трогів у сум'яття й дає знесиленим горянам так потрібну можливість укріпити дороги й загнати потвор назад у темні глибини."}},faq={{q="Хто такий Ґраумуґ?",a="Ґраумуґ — лютий вождь трогів, що згуртовує трогів Кам'яного Уламка на півдні Лох Модану. Дворфійські розвідники встановили, що саме він стоїть за організованими нападами, які непокоять долину; при ньому завжди двоє грізних охоронців — Гнешер і Бійцівський.",al={"ґраумуґ лор","хто ватажок трогів","вождь ґраумуґ"}},{q="Де шукати Ґраумуґа та його охоронців?",a="Ґраумуґ, Гнешер і Бійцівський засіли в печері на південно-східному краю Долини Кам'яного Уламка в Лох Модані. Вони разом живуть у глибоких закамарках печери.",al={"місце ґраумуґа","де ґраумуґ","де знайти ґраумуґа"}},{q="Хто такий Капітан Руґелфусс?",a="Капітан Руґелфусс — дворфійський офіцер з Південної Вартової Вежі в Лох Модані. Він керує обороною від навали трогів і віддає накази, щоб уберегти цілісність королівських земель.",al={"руґелфусс","роль капітана руґелфусса","хто дає захист королівських земель"}},{q="Чому треба вбити й охоронців Ґраумуґа?",a="Гнешер і Бійцівський — особисті охоронці Ґраумуґа, що ніколи не відходять від нього. Щоб усунути вождя й остаточно обезголовити наступ трогів, обох важких охоронців треба здолати разом з ватажком.",al={"чому вбивати охоронців","нашер і бійцюга","охоронці ґраумуґа"}},{q="Що буде, коли Ґраумуґа усунуто?",a="Загибель Ґраумуґа дає Лох Модану життєво потрібний перепочинок. Без вождя, що спрямовував набіги, троги Кам'яного Уламка втрачають злагодженість, і місцеве дворфійське ополчення має шанс утримати кордони й загнати тварюк під землю.",al={"наслідок вбивства ґраумуґа","троги після ґраумуґа","чи врятували лох модан"}},{q="Чому троги вдираються в Лох Модан?",a="Троги здавна гніздилися глибоко в підземних залах під Каз Моданом. Розкопки й розпечатані печери дали їм змогу вирватися на поверхню, де вони агресивно витісняють поселення й нападають на мандрівників на королівських шляхах.",al={"чому троги тут","вторгнення трогів лох модан","походження трогів кам'яного уламка"}}},fp="30,391,22.553.0,23.450.0,15.278.0,41.171.0,25.246.0,43.231.0,41.266.1,35.241.0"}
P.entries["quest:2178"] = {n="Легкий хліб зі степових довгоступів",s="«Легкий хліб зі степових довгоступів» — місцеве кулінарне доручення від Аланндаріан Найтсонг в Обердайні. Вона охоче поділиться своїм цінним рецептом печені з довгоступа, якщо шукач пригод вполює лютих лісових довгоступів, що блукають Темним Узбережжям, і принесе їхнє м'ясо.",h="«Легкий хліб зі степових довгоступів» — місцеве кулінарне доручення від Аланндаріан Найтсонг в Обердайні.",kw={"печеня з довгоступа","аланндаріан найтсонг","лісові довгоступи","кулінарія","обердайн","темне узбережжя"},ang={["class:Hunter"]="Лісові довгоступи — це і прудка дичина, і можливі звірі-супутники: на імлистих стежках Темного Узбережжя на них можна добре повправлятися у вистежуванні й полюванні.",["profession:Cooking"]="Це доручення — неодмінне для кухарів, що мандрують Темним Узбережжям: нагородою за нього стає рецепт поживної Печені з Довгоступа з місцевої дичини.",["race:NightElf"]="Жити в гармонії з Калімдором часто означає жити з того, що дає земля, і ситна печеня з довгоступа стала звичною прибережною стравою нічних ельфів Обердайна."},sec={{t="Смак дикої природи",b="Обердайн, може, й тихе портове селище, але щоб вижити на узбережжі, треба вміти добре користатися місцевою звіриною. Аланндаріан Найтсонг вигадала таємний рецепт ситної печені з довгоступа — смачної страви з високих прудконогих лісових довгоступів, що нишпорять тінистими лісами Темного Узбережжя. Вона не роздає кулінарних секретів просто так, а просить кухарів-початківців і мисливців самим вирушити й вполювати цих птахів."},{t="Полювання на лісових довгоступів",b="Лісові довгоступи — прудкі гостродзьобі хижі птахи, що блукають оповитими імлою лісами й пляжами на північ і на південь від Обердайна. Роздратовані, вони бувають норовливими й агресивними, але їхнє соковите м'ясо — чудова основа для наваристої печені. Свіже м'ясо наповнить голодний казанок Аланндаріан і принесе мисливцеві її заповітний рецепт."}},faq={{q="Хто така Аланндаріан Найтсонг?",a="Аланндаріан Найтсонг — нічна ельфійка з Обердайна на Темному Узбережжі. Відома своїм казанком печені з довгоступа, що вічно булькає на вогні, вона охоче вчить свого куховарства мандрівників, які доведуть свою мисливську вправність.",al={"аланндаріан","хто такий аланндаріан найтсонг","кухар обердайна"}},{q="Де взяти м'ясо довгоступа?",a="М'ясо довгоступа здобувають, полюючи на лісоступів по всьому Темному Узбережжю. Ці великі нелітаючі птахи никають і піщаними берегами, і лісовими гаями довкола Обердайна.",al={"місце м'яса довгоступа","де лісоступи","як дістати м'ясо довгоступа"}},{q="Яка мета цього завдання?",a="Завдання доручає вам уполювати лісоступів і принести Аланндаріан Найтсонг п'ять шматків м'яса — а натомість навчитися готувати Печеню з Довгоступа.",al={"навіщо легкий хліб","мета завдання","мета легкого хліба"}},{q="Чи небезпечно полювати на лісоступів?",a="Лісоступи — птахи, що боронять свою землю гострими дзьобами й прудкими ногами, тож вони агресивні, коли до них наближаються. Проте пристойно спорядженому шукачеві пригод полювання на них не загрожує.",al={"чи лісоступи складні","небезпека лісоступів"}},{q="Чи відкриває це завдання кулінарний рецепт?",a="Так. Отримавши м'ясо, Аланндаріан ділиться своїми кулінарними секретами й навчає шукачів пригод рецепта Печені з Довгоступа.",al={"чи є рецепт","рецепт рагу з довгоступа","нагорода кулінарія"}},{q="Де відбувається це завдання?",a="Завдання починається й завершується в поселенні Обердайн, а полюють у дикій глушині Темного Узбережжя.",al={"зона завдання","де легкий хліб"}}},fp="19,267,19.430.0,26.361.0,29.202.0,33.176.0,34.165.0,41.196.0,40.133.0,33.119.0"}
P.entries["quest:218"] = {n="Вкрадений щоденник",s="Вкрадений щоденник — раннє завдання Альянсу в Дун Мороґу, у якому Ґрелін Вайтбірд доручає шукачам пригод увійти до тролячої печери в Долині Холодного Хребта й повернути його вкрадений записник. Щоб забрати його, ви мусите здолати грізного тролячого ватажка Ґрік'ніра Холодного. Повернення щоденника дає Ґреліну змогу завершити оцінку тролячої загрози в Долині Холодного Хребта.",h="Вкрадений щоденник — раннє завдання Альянсу в Дун Мороґу, у якому Ґрелін Вайтбірд доручає шукачам пригод...",kw={"вкрадений щоденник","ґрелін вайтбірд","ґрік'нір холодний","троляча печера","морозогриви","тролі","долина холодного хребта"},ang={["faction:Alliance"]="Придушення зухвалого племені Морозогривів гарантує, що початкові долини Дун Мороґу лишаться захищеними від внутрішніх заворушень.",["race:Dwarf"]="Знищення ватажків Морозогривів у Долині Холодного Хребта захищає молодих дворфійських новобранців, що роблять перші кроки за межі Анвілмара.",["race:Gnome"]="Гномські біженці, що знайшли прихисток в Анвілмарі, покладаються на безпеку перевалів Долини Холодного Хребта, поки перегруповуються на дворфійській землі."},sec={{t="Загублені нотатки вченого",b="Ґрелін Вайтбірд спостерігає за тролями Морозогривами, що наступають на Долину Холодного Хребта, й веде докладні нотатки про їхні звички й раптову зухвалість. Під час заворушень незвично кремезний троль утік з його особистим щоденником і сховався в глибині їхнього лігва. Для Ґреліна втрата не лише сентиментальна: у записнику — основна частина його розвідки, і офіційна оцінка стоїть на місці, доки його не повернуть із печери."},{t="Сутичка з Ґрік'ніром Холодним",b="Здоровань, що забрав щоденник, — Ґрік'нір Холодний, могутній троль Морозогрив із прикметним розписом на тілі й обличчі, який править у серці тролячої печери долини. Убити Ґрік'ніра — означає зламати місцеве керівництво тролів печери й повернути щоденник Ґреліна. Коли ватажка знищено, Ґрелін почувається досить упевнено, щоб доповісти, що становище з тролями в долині під контролем, і надсилає завершені висновки своєму братові Сеніру."}},faq={{q="Хто забрав щоденник Ґреліна Вайтбірда?",a="Щоденник забрав Ґрік'нір Холодний — великий троль-Морозогрив з дивними знаками на шкірі й обличчі, що ховається глибоко в троллячій печері.",al={"хто вкрав щоденник","у кого щоденник ґреліна","злодій щоденника"}},{q="Де знайти Ґрік'ніра Холодного?",a="Ґрік'нір Холодний — у троллячій печері на півдні Долини Холодного Хребта.",al={"де ґрік'нір","місце ґрік'ніра","як знайти ґрік'ніра"}},{q="Чому щоденник такий важливий для Ґреліна?",a="У щоденнику — нотатки й спостереження Ґреліна Вайтбірда про діяльність тролів у Долині Холодного Хребта. Без нього він не складе повного звіту для свого брата Сеніра.",al={"чому ґрелін хоче щоденник","що в щоденнику ґреліна"}},{q="Що буде, коли повернути щоденник?",a="Отримавши щоденник, Ґрелін завершує звіт про становище з тролями в Долині Холодного Хребта й просить вас доставити його спостереження братові, Сенірові Вайтбірду, до Хараноса.",al={"що після вкраденого щоденника","наступне завдання вкраденого щоденника"}},{q="Чи виганяють після цього тролів-Морозогривів з Долини Холодного Хребта?",a="Ґрелін вважає, що після загибелі Ґрік'ніра з тролями в Долині Холодного Хребта дали раду, хоча Морозогриви й далі становлять незмінну загрозу на ширших гірських перевалах Дун Мороґу.",al={"чи тролів переможено в холодному хребті","чи безпечний холодний хребет від тролів"}},{q="Хто такий Сенір Вайтбірд?",a="Сенір Вайтбірд — брат Ґреліна, розвідник Альянсу, що стоїть за межами Долини Холодного Хребта, біля Хараноса, і збирає відомості про загрози королівству.",al={"хто такий сенір","брат ґреліна сенір"}}},fp="18,368,22.459.0,29.474.0,37.160.0,37.95.0,39.176.0,42.193.1,67.198.0,24.160.0"}
P.entries["quest:219"] = {n="Зник безвісти",s="Зник безвісти — завдання Альянсу в Горах Редріджу: вирвати Капрала Кішана з полону орків Блекрок і супроводити його додому. Коли його загін винищили на пагорбах, Кішана оглушили й затягли до печерної фортеці. Безпечно привівши пораненого солдата до Лейкширу, ви допоможете місцевому гарнізону дізнатися похмуру долю зниклих бійців.",h="Зник безвісти — завдання Альянсу в Горах Редріджу: вирвати Капрала Кішана з полону орків Блекрок і...",kw={"зник безвісти","капрал кішан","супровід","орки блекрок","маршал марріс","лейкшир"},ang={["class:Warrior"]="Щоб вирвати Кішана з озброєного табору орків, доведеться тримати передову проти хвиль безжальних нападників Блекрок, прикриваючи контуженого товариша.",["faction:Alliance"]="Гарнізон Лейкширу виснажений до краю, тож кожен врятований солдат вкрай важливий для оборони королівства від клану Блекрок."},sec={{t="Розгромлений загін",b="Гори Редріджу стають дедалі небезпечнішими, відколи з північних вершин спускаються орки Блекрок. Патрулі міської варти раз у раз потрапляють у засідки, і загонові Капрала Кішана дісталося найтяжче. Ворогів було значно більше, і більшість солдатів його загону порубали на місці. Кішан уцілів лише тому, що нищівний удар оглушив його, перш ніж його встигли стратити, тож орки затягли його до своєї печери як полоненого."},{t="Втеча з печер",b="Побитий, контужений і замкнений глибоко на ворожій території, Кішан не міг сам спуститися з гори. Дорога до безпечного Лейкширу веде повз загони орків, що кишать на хребтах. Коли він живим дістається до Ратуші, Маршал Марріс нарешті може полегшено зітхнути: він давно намагався з'ясувати, що сталося зі зниклим загоном, і водночас готував Лейкшир до нових нападів."}},faq={{q="Хто такий Капрал Кішан?",a="Капрал Кішан — піхотинець Альянсу, що служить у Горах Редріджу. Під час патрулювання скелястих пагорбів орки Блекрок розгромили його загін; він — єдиний відомий уцілілий, і його потягли в полон.",al={"капрал кішан","хто такий кішан","кішан лор"}},{q="Де тримають Капрала Кішана?",a="Його тримають глибоко в печері, що кишить орками, на північних пагорбах Редріджу, серед ворожих воїнів Блекрок.",al={"де кішан","місце кішана","печера кішана"}},{q="Що сталося з рештою загону Кішана?",a="За словами Кішана, орки Блекрок влаштували засідку й розгромили його загін, убивши майже всіх ще в першій сутичці.",al={"загін кішана","що сталося з полком","люди кішана"}},{q="Хто посилає гравців рятувати Кішана?",a="Завдання починається просто з самого Капрала Кішана в печері-в'язниці, коли шукачі пригод з Альянсу знаходять і звільняють його.",al={"хто дає зник безвісти","хто дає завдання","де взяти зник безвісти"}},{q="Куди йде Кішан, коли його звільнено?",a="Його треба супроводити схилом униз до містечка Лейкшир, де він доповідає Маршалові Маррісу в ратуші.",al={"здати зник безвісти","куди тікає кішан","куди йде кішан"}},{q="Що орки Блекрок роблять у Редріджі?",a="Клан Блекрок пробивається на південь зі своїх твердинь у Палаючих Степах у Редрідж, загрожуючи погано укріпленому Лейкширу й влаштовуючи засідки на королівські патрулі.",al={"орки блекрок у редріджі","чому орки в лейкширі","вторгнення блекрок"}}},fp="17,365,18.474.0,21.424.0,24.243.0,36.128.0,44.138.0,36.131.0,40.123.0,39.181.0"}
P.entries["quest:22"] = {n="Пиріг із Печінки Кровоікла",s="«Пиріг із Печінки Кровоікла» — кулінарне доручення для Салми Салдін на Фермі Салдина у Вестфолі. Житницю королівства спустошили посуха й розбійники, тож місцеві господарі покладаються на полювання на агресивних кабанів, щоб поставити на стіл ситну страву. Допомога Салмі дарує рідкісний смак затишку й домашньої гостинності посеред похмурого прикордоння.",h="«Пиріг із Печінки Кровоікла» — кулінарне доручення для Салми Салдін на Фермі Салдина у Вестфолі.",kw={"пиріг із печінки кровоікла","салма салдін","кривавоіклі","кулінарія","ферма салдина","вестфол"},ang={["faction:Alliance"]="Допомагаючи сільським господарям на кшталт Салдінів, ви безпосередньо підтримуєте вірні людські родини, що силкуються втримати прикордоння королівства без армії Стормвінда.",["profession:Cooking"]="Страва Салми показує традиційну сільську людську кухню: городні пахощі на кшталт часнику, розмарину й кропу перетворюють тельбухи дичини на звичну щоденну їжу."},sec={{t="Гостинність прикордоння",b="Колись Вестфол був родючою житницею Стормвінда, але останні роки принесли тяжкі часи. Занедбане господарство, розбійники на шляхах і зарослі поля перетворили щоденне життя нечисленних поселенців на виснажливу боротьбу. На Фермі Салдина Салма Салдін невтомно працює, щоб зберегти затишок домашнього вогнища попри небезпеки, що підступають. Приготувати традиційний м'ясний пиріг — одна з небагатьох скромних розкошів, доступних господарям, які намагаються зберегти свій уклад."},{t="Дикі звірі Вестфолу",b="Рівнини Вестфолу кишать кривавоіклими — агресивними дикими кабанами з цупкою шкурою й лютими іклами. Для самотніх наймитів вони небезпечні, але водночас це важливе джерело м'яса для родин, відрізаних від звичної торгівлі. Рецепт Салми вимагає ретельного приготування — товченого розмарину, січеного часнику, дрібно нарізаного кропу й підливи, що повільно томиться, — щоб гострі на запах тельбухи цих витривалих звірів стали багатою, смачною учтою."}},faq={{q="Хто така Салма Салдін?",a="Салма Салдін — витривала господиня, що живе з чоловіком, Фермером Салдіном, на їхній фермі в центрі Вестфолу. Відома своєю домашньою кухнею, вона щосили підтримує бойовий дух, попри небезпеку від бандитів і диких звірів.",al={"салма салдін","хто така салма","дружина салдіна"}},{q="Навіщо Салмі печінка кровоіклів?",a="Салма пече свій славетний м'ясний пиріг, щоб почастувати чоловіка. Тісто вже спечене, приправи готові — бракує лише печінки місцевих кровоіклів, щоб дотушкувати начинку.",al={"навіщо печінка кровоікла","з чого пиріг","призначення печінки"}},{q="Де у Вестфолі зазвичай водяться кровоікли?",a="Кровоікли никають усюди золотими рівнинами й занедбаними ланами Вестфолу: риють покинуті поля й блукають ґрунтовими дорогами.",al={"місця кровоіклів","де вепри","полювання на печінку кровоікла"}},{q="Чи небезпечні кровоікли для місцевих фермерів?",a="Так. Кровоікли — агресивні дикі вепри з гострими іклами, що люто боронять свою землю. Вони становлять серйозну загрозу для худоби й беззахисних мандрівників на рівнинах.",al={"чи кровоікли ворожі","небезпека вепрів вестфол"}},{q="Чому у Вестфолі зараз так бракує їжі?",a="Через виснажливі посухи, брак королівської підтримки зі Стормвінда й набіги організованих бандитів багато фермерів покинули свої землі, і колишня житниця королівства стала злиденним прикордонням, що ледве зводить кінці з кінцями.",al={"голод вестфолу","чому немає їжі у вестфолі","важкі часи вестфолу"}},{q="Чи допоможе це завдання фермі Салдінів вижити?",a="Воно не розв'яже ширших бід Вестфолу, але свіже м'ясо безпосередньо годує родину Салдінів і дає мандрівникам ситні харчі в дорогу.",al={"чи пиріг важливий","їжа салдінів"}}},fp="18,375,20.494.0,23.417.0,21.245.0,36.213.0,48.163.0,45.169.0,44.233.0,56.180.0"}
P.entries["quest:220"] = {n="Поклик води",s="На цьому етапі шаманського випробування новачок має принести очищену воду через Пустки назад, до узбережжя, де чекає Іслен Вотерсір. Приготований і благословенний самітницею Брайн, цей фіал містить каталізатор, потрібний, щоб виготовити духовну сапту. Готовий напій відкриє духів стихій, що живуть у далеких водах Срібнолісся.",h="На цьому етапі шаманського випробування новачок має принести очищену воду через Пустки назад, до узбережжя...",kw={"поклик води","іслен вотерсір","брайн","фіал найчистішої води","сапта","тотем води"},ang={["class:Shaman"]="Кожен шаман Орди мусить пройти обряди «Поклику води», щоб поспілкуватися з духами й здобути право носити свій Тотем Води, що владарює над зціленням і відновленням.",["faction:Horde"]="Випробування охоплює Калімдор і Лордерон і показує, наскільки широко розкинулася Орда: молоді новачки мандрують із Пусток до Срібнолісся, яке тримають Відступники."},sec={{t="Повернення на берег",b="Пройшовши південні Пустки й виконавши випробування Брайн, новачок-шаман отримує Фіал Найчистішої Води. Наповнена з незайманих джерел і освячена відлюдними обрядами Брайн, ця посудина втілює чисту силу стихії. Безпечно донести її на східне узбережжя, де чатує Іслен Вотерсір, — важлива ланка, що поєднує простонародну мудрість Брайн з урочистими обрядами тотема."},{t="Призначення сапти",b="Отримавши чисту воду, Іслен пояснює, що смертні очі не так легко бачать невловимих духів води. Щоб розмовляти з ними, новачок мусить випити особливий напій, відомий як сапта. Вода від Брайн стане могутньою основою для цього напою й відкриє чуття шамана до сил, прихованих від звичайного погляду. Та, як застерігає Іслен, єднання — лише пів шляху: самі духи вимагають випробування."},{t="Переправа до Лордерону",b="Іслен відкриває, що кульмінація випробування відбудеться не на сухих просторах Калімдору. Шаман мусить вирушити далеко за море, до прадавніх, оповитих туманом берегів Срібнолісся, трохи на південь від Андерсіті. Там, біля відлюдного святилища, треба випити сапту, щоб новачок міг зустрітися з елементалями віч-на-віч і здобути право прикликати Тотем Води."}},faq={{q="Що у Фіалі Найчистішої Води?",a="У фіалі — вода, яку новачок набрав з чистих джерел і освятив обрядами відлюдника Брайна. Це незіпсована стихійна вода, без якої не зварити алхімічну сапту, потрібну для спілкування з духами води.",al={"фіал найчистішої води","вода брайн","що дала мені брайн"}},{q="Хто така Іслен Вотерсір?",a="Іслен Вотерсір — старійшина-шаманка, що живе на відлюдному південно-східному узбережжі Пусток, на південь від Раджета. Вона — головна наставниця шаманів Орди, які прагнуть поєднатися зі стихією води й здобути свій Тотем Води.",al={"іслен","хто така іслен вотерсір","іслен вотерсір лор"}},{q="Що таке сапта?",a="Сапта — обрядовий настій, який готують шамани-наставники. Випита, вона змінює сприйняття, і шаман може ясно бачити й спілкуватися з духами стихій, яких смертне око зазвичай не помічає.",al={"значення сапти","водяна сапта","що робить сапта"}},{q="Чому далі треба йти в Срібнолісся?",a="Святилище стихії, пов'язане з цим єднанням, лежить у прибережних водах Срібнолісся, на південь від Андерсіті у Східних Королівствах. Духи, що живуть там, потребують єднання й останнього випробування, перш ніж дарувати владу над своєю стихією.",al={"чому срібнолісся","тотем води срібнолісся","святиня в срібноліссі"}},{q="Де живе Брайн?",a="Брайн живе у відлюдній хатині високо в пагорбах південних Пусток, на захід від шляху, що веде вниз до Великого Підйомника й Тисячі Голок.",al={"місце брайн","де брайн","знайти брайн"}},{q="Чи може шаман обійтися без сапти?",a="Ні. Обряди єднання вимагають, щоб дух шамана був налаштований на невидимий світ. Без містка сприйняття, який дає сапта, до духів води в святилищі не звернутися й не кинути їм виклик.",al={"пропустити сапту","чи сапта обов'язкова","видіння шамана"}}},fp="13,347,19.429.0,24.445.0,23.397.1,40.257.0,23.238.0,16.225.0,46.247.0,22.146.0,39.206.0"}
P.entries["quest:2205"] = {n="Знайти SI:7",s="«Знайти SI:7» — вступне доручення, яке Керін Сильвій дає молодим розбійникам у Лісі Елвінн. Із невеликим пакунком із Ґолдширу до Стормвінда агенти-новачки вирушають на знайомство з Майстром Матіасом Шоу — очільником таємної розвідувальної мережі корони.",h="«Знайти SI:7» — вступне доручення, яке Керін Сильвій дає молодим розбійникам у Лісі Елвінн.",kw={"знайти si:7","si:7","керін сильвій","матіас шоу","старе місто","розбійник"},ang={["class:Rogue"]="Це доручення знаменує офіційний вступ розбійника на службу до найкращої шпигунської служби Стормвінда — від дрібних провулкових хитрощів до королівської розвідки.",["faction:Alliance"]="SI:7 — очі й вуха корони, що стежать за загрозами зсередини й ззовні й тихо оберігають королівство, поки король Варіан Рінн зник безвісти."},sec={{t="Випробування гінця",b="У корчмі «Лев'яча Гордість» у Ґолдширі наставниця розбійників Керін Сильвій не марнує часу на улесливість до новачків. Вважаючи, що свіжі учні скидаються радше на розносників сиру, ніж на вправних таємних агентів, Сильвій усе ж передає доручення: віднести запечатаний пакунок до столиці. Це і звичайна робота гінця, і тиха перевірка розвідників, що вступають на ширшу службу королівству."},{t="За зачиненими дверима Старого Міста",b="Мета — глибоко в Старому Місті, гамірному й пошарпаному кварталі Стормвінда. У південно-східному куточку кварталу сховався штаб SI:7 — Сьомого відділу розвідки Стормвінда. Тут Майстер Матіас Шоу керує таємними операціями королівства. Приймаючи пакунок зі своїм звичним сухим скептицизмом, Шоу оцінює, чи має мандрівник досить завзяття для справжнього шпигунства."}},faq={{q="Що таке SI:7?",a="SI:7 означає «Розвідка Стормвінда, Відділ 7». Це таємна служба розвідки й прихованих операцій Королівства Стормвінд, яку очолює Майстер Матіас Шоу з осередку в Старому Місті.",al={"що означає si 7","що таке si7","si:7 лор"}},{q="Хто така Керін Сильвій?",a="Керін Сильвій — наставниця розбійників у Корчмі «Лев'яча Гордість» у Ґолдширі. Співпрацюючи з SI:7, вона оцінює місцевих новобранців і спрямовує перспективних розвідників до Майстра Матіаса Шоу в Стормвінді.",al={"керін сильвій","тренер розбійників ґолдшира"}},{q="Де в Стормвінді знайти Матіаса Шоу?",a="Майстер Матіас Шоу — на верхньому поверсі осередку SI:7 у південно-східному куті Старого Міста в Стормвінді, за міськими наставниками розбійників.",al={"де шоу","знайти матіаса шоу","місце матіаса шоу"}},{q="Що буде, коли доставити пакунок Шоу?",a="Щойно ви з'явитеся до Матіаса Шоу, він одразу перевірить ваші практичні навички розбійника, відправивши на таємну операцію до Пристані Джерода: треба поцупити розклад відправлень у начальника доків Дефіас.",al={"наступне завдання після пошуку si 7","чого хоче шоу"}},{q="Чому Керін глузує з гравця, перш ніж віддати доставку?",a="Агенти SI:7 пишаються високою вправністю й гострим чуттям. Сильвій суворо поводиться з новачками, щоб оцінити їхню вдачу й переконатися, що до Майстра Шоу дістануться лише ті, хто має товсту шкіру й справжню рішучість.",al={"чому керін ображає мене","образа доставки сиру"}}},fp="14,267,16.414.0,31.426.0,13.207.0,21.216.0,43.175.0,50.191.1,64.212.0"}
P.entries["quest:2206"] = {n="Хапай і тікай",s="«Хапай і тікай» — таємне доручення, яке Майстер Матіас Шоу, очільник SI:7, дає перспективним розбійникам. Агенти мають проникнути на Пристань Джерода й викрасти в Братства Дефіас відомості про перевезення.",h="«Хапай і тікай» — таємне доручення, яке Майстер Матіас Шоу, очільник SI:7, дає перспективним розбійникам.",kw={"хапай і тікай","si:7","матіас шоу","пристань джерода","братство дефіас","розбійник"},ang={["class:Rogue"]="Це доручення — офіційне знайомство розбійника з SI:7: воно перевіряє скритність і чуття кишенькового злодія, а нагородою стають визнання й особливий клинок від Матіаса Шоу.",["faction:Alliance"]="Перехоплюючи шляхи постачання Дефіас на Пристані Джерода, ви захищаєте Ліс Елвінн і підточуєте злочинне угруповання, що загрожує землям довкола Стормвінда."},sec={{t="Випробування майстерності",b="Для молодого агента в Стормвінді постати перед Майстром Матіасом Шоу — справжній вступний іспит до таємної розвідки королівства. Шоу не покладається на грубу силу — він вимагає доказів вправності й скритності. Тихо прибирати ключових осіб і добувати важливі папери, не втягуючи королівство у відкритий скандал, — ось головне покликання SI:7, а ця операція стає для новачка полігоном."},{t="Контрабандисти на річці",b="Пристань Джерода стоїть на річці в південному Елвінні, на південь від Ґолдширу й трохи на схід від Виноградників Маклюрів. Колись це була тиха місцева пристань, але Братство Дефіас захопило її й проклало тут незаконний шлях перевезень. Переправляючи водою контрабандну зброю, припаси й крам від Редріджу аж до Вестфолу, злодії цілком оминають королівські дорожні патрулі."},{t="Право на заперечення",b="Перш ніж відіслати агентів у поле, Шоу чітко викладає незмінне правило SI:7: якщо агента схоплять, викриють чи вб'ють, Корона та її шпигуни зречуться будь-якого знання про нього. Розклад Начальника Доків Дефіасу стає важливим доказом шляхів постачання Братства, а офіційна причетність Стормвінда лишається в тіні."}},faq={{q="Хто дає завдання «Хапай і тікай»?",a="Майстер Матіас Шоу, очільник розвідки Стормвінда SI:7, дає це завдання в осередку SI:7 у Старому Місті.",al={"хто дає хапай і тікай","хто дає завдання"}},{q="Де розташована Пристань Джерода?",a="Пристань Джерода — причал на річці на півдні Лісу Елвінн, на південь від Ґолдширу й трохи на схід від Виноградників Маклюрів. Братство Дефіас захопило там причали й портовий будинок.",al={"місце пристані джерода","де пристань джерода","місце начальника доку"}},{q="Що Дефіас переправляють через Пристань Джерода?",a="Дефіас користуються Пристанню Джерода, щоб переправляти водою великі партії контрабанди й припасів між Редріджем і Вестфолом, оминаючи королівські варти й дорожні застави.",al={"що вони контрабандою","контрабанда дефіас"}},{q="У кого Розклад Відправлень Дефіасу?",a="Розклад відправлень має при собі Начальник Доків Дефіасу, що стереже портовий будинок на Пристані Джерода.",al={"де розклад відправлень","хто дропає розклад","начальник доку дефіас"}},{q="Що буде, якщо агента схоплять під час цієї місії?",a="Як попереджає Майстер Матіас Шоу, SI:7 суворо дотримується правдоподібного заперечення. Якщо агента викриють чи схоплять, SI:7 відмовиться від будь-якого зв'язку з ним.",al={"що якщо провалю","si7 відмовиться"}},{q="Чому SI:7 цікавить цей розклад відправлень?",a="Документ розкриває, як Братство Дефіас переправляє контрабанду між Редріджем і Вестфолом. Здобувши його, розвідка Стормвінда може скласти мапу ворожого постачання, не сполохавши угруповання.",al={"чому потрібен розклад","розклад відправлень si7"}}},fp="15,223,20.422.0,22.390.0,21.390.0,38.132.0,25.200.0,54.184.0,41.119.0,61.160.0,48.206.0"}
P.entries["quest:221"] = {n="Воргени в лісі",s="Зграя Найтбейн підступає дедалі ближче до Даркшира, і Калор доручає шукачам пригод знищити її основну силу — рядових переслідувачів. Ці люті Темні Бігуни заполонили сусідній Гнилий Сад і загрожують цілком оточити обложене місто.",h="Зграя Найтбейн підступає дедалі ближче до Даркшира, і Калор доручає шукачам пригод знищити її основну силу —...",kw={"воргени в лісі","калор","нічна згуба","темні бігуни","гнилий сад","даркшир"},ang={["class:Hunter"]="Стрімкий наступ протиприродних двоногих вовків у Гнилому Саду дає мисливцям похмурий урок: як мати справу з потойбічними звірями, чиї інстинкти суперечать природному ладу Азероту.",["faction:Alliance"]="Корона Стормвінда майже не надіслала до Сутінколісся підкріплень, тож місцеві добровольчі загони на кшталт Нічної Варти цілком покладаються на мандрівних героїв Альянсу, щоб проріджувати зграї хижаків, що підступають."},sec={{t="Кільце стискається",b="Розвідники спершу натрапляли на поодиноких воргенів, що плели тіньову магію на околицях лісу, але виправи Калора виявили значно нагальнішу тактичну загрозу. Більші й прудкіші звірі, відомі як Темні Бігуни Найтбейн, скупчилися в Гнилому Саду, трохи на південний захід від Даркшира. Ці хижаки не просто чатують під кронами: вони становлять основну частину зграї й облаштовують плацдарм на відстані удару від міської брами."},{t="Невичерпна хвиля",b="Винищення Темних Бігунів на якийсь час притуплює наступ зграї, але Нічній Варті від цього не легше. Калор із дедалі більшим жахом зауважує, що на місце кожного вбитого звіра одразу приходить інший, що нишпорить у тумані. Надприродна живучість Найтбейн й те, як швидко поповнюються її лави, спантеличують захисників міста, і їм доводиться звертатися до досвідчених мисливців на чудовиськ, як-от Майстра Джонатана Каревіна, щоб з'ясувати, яка мерзенна сила прикликала цих чужинських потвор до Сутінколісся."}},faq={{q="Хто такі темні бігуни Найтбейн?",a="Темні бігуни Найтбейн — більші, кремезніші воргени, які становлять головні передові сили зграї, що не дає спокою Сутінколіссю. На відміну від чаклунів-тінеткачів, темні бігуни покладаються на швидкість, пазурі й неприборкану хижацьку лють.",al={"темні бігуни","хто такі темні бігуни","темний бігун найтбейн"}},{q="Де розташований Гнилий Сад?",a="Гнилий Сад лежить трохи на південний захід від Даркшира. Колись тут були родючі угіддя, а тепер — зіпсована, спаплюжена галявина, яку зграя Найтбейн захопила як передовий плацдарм біля містечка.",al={"місце гнилого саду","де гнилий сад"}},{q="Хто такий Калор?",a="Калор — слідопит і член Нічної Варти в Даркширі. Він розвідує околиці поселення й стежить за пересуваннями агресивних зграй воргенів, що загрожують виживанню містечка.",al={"хто такий калор","калор сутінколісся","калор дає завдання"}},{q="Чому захисникам здається, що воргенам немає ліку?",a="Захисники ще не розуміють надприродної природи воргенів. Вони вважають, що якась зла сила закликає чи притягує звірів у Сутінколісся, тож нові хвилі з'являються так само швидко, як гинуть попередні.",al={"чому стільки воргенів","невичерпні воргени","звідки беруться воргени"}},{q="Хто такий майстер Каревін?",a="Майстер Джонатан Каревін — досвідчений мисливець і стрілець з Даркшира. Нічна Варта цілком довіряє його знанням, сподіваючись, що він знайде корінь потворної навали, яка мучить край.",al={"майстер каревін","джонатан каревін","хто такий каревін"}},{q="Яке місце це завдання посідає в обороні Даркшира?",a="Даркшир — відрізане поселення, де тануть запаси, а допомоги зі Стормвінда немає. Очистивши Гнилий Сад, ви не даєте зграї Найтбейн влаштовувати прямі нищівні засідки на південно-західних околицях містечка.",al={"чому вбивати темних бігунів","оборона даркшира"}}},fp="19,266,22.451.0,21.497.1,32.243.0,37.199.0,13.203.0,56.242.0,22.219.0,53.221.0"}
P.entries["quest:222"] = {n="Воргени в лісі",s="Зграя Найтбейн дедалі міцніше стискає Сутінколісся, і Калор скеровує шукачів пригод ударити по найнебезпечніших її загонах. Несучи бій просто до південних лігв і шахт, захисники відкидають дику загрозу, що підступає до Даркшира.",h="Зграя Найтбейн дедалі міцніше стискає Сутінколісся, і Калор скеровує шукачів пригод ударити по...",kw={"воргени в лісі","калор","нічна згуба","мерзенні ікла","осквернені","даркшир"},ang={["class:Hunter"]="Хитрість зграї Найтбейн робить її протиприродною здобиччю: слідопитам, які наближаються до її темних лігв, треба бути напоготові.",["faction:Alliance"]="Даркшир стоїть самотою на похмурому півдні королівства; очищаючи південні печери, ви допомагаєте вберегти крихкі шляхи постачання й уцілілі хутори Сутінколісся."},sec={{t="Дикий плацдарм",b="Навала воргенів у Сутінколіссі — аж ніяк не бездумний хаос. Відвоювавши собі територію в темних просторах на південь від Даркшира, звірі, відомі як Найтбейн, почали облаштовувати укріплені табори. Калор із дедалі більшим жахом спостерігає, як удалині мерехтять їхні вогнища, і зауважує, що створіння зайняли глибокі печери й покинуті шахти. Серед них Мерзенні Ікла й Осквернені — найлютіші породи, що вирізняються дикою жорстокістю й упертістю, здатною прорвати оборону міста."},{t="Рекомендація Калора",b="Калор — пильний вербувальник на передовій оборони Даркшира, хоча й не має ілюзій щодо жахливої природи вовкоподібних загарбників. Зламати хребет Мерзенним Іклам і Оскверненим — випробування для будь-якого героя. Ті, кому вдасться винищити ці загартовані зграї, здобувають не лише монети, а й повагу Калора та особисту рекомендацію до Майстра Каревіна — відлюдного очільника ширшого наступу проти воргенської навали."}},faq={{q="Де шукати Мерзенні Ікла й Опоганених?",a="Ці небезпечні породи зграї Найтбейн збираються біля печер і копальні на півдні Сутінколісся, часто довкола помітних вогнищ.",al={"де опоганені","де мерзенні ікла","місця воргенів сутінколісся"}},{q="Хто такий Калор?",a="Калор — відданий мешканець Даркшира, що стежить за загрозою від воргенів у лісі й залучає вправних шукачів пригод, щоб стримати наступ цих створінь.",al={"калор даркшир","хто дає воргени в лісі 3"}},{q="Хто такий майстер Каревін?",a="Майстер Каревін — це Джонатан Каревін з Даркшира, чия родина воює зі злом цього краю; він керує зусиллями, щоб викорінити загрозу від воргенів з довколишніх земель.",al={"майстер каревін","каревін сутінколісся"}},{q="Звідки у воргенів вогнища?",a="Попри потворну вовчу подобу, воргени Найтбейн виявляють моторошний розум: збираються в упорядкованих таборах, користуються вогнем і утримують укріплені позиції, як-от копальні.",al={"чому воргени палять вогнища","вогнища найтбейн"}},{q="Що буде після цього полювання?",a="Вразивши Калора, ви отримуєте рекомендаційний лист, з яким вирушаєте просто до майстра Каревіна, щоб допомогти йому на наступному етапі полювання.",al={"наступне завдання після воргенів у лісі 3","продовження воргенів у лісі"}},{q="Чому Даркшир так непокоять саме ці воргени?",a="Мерзенні Ікла й Опоганені — одні з найсмертоносніших і найагресивніших членів зграї. Якщо не стримати їх біля південних копалень, звірі можуть цілком заполонити довколишні шляхи.",al={"чому найтбейн мерзенні ікла","небезпека мерзенних іклів"}}},fp="19,242,16.538.0,19.475.1,50.158.0,13.150.0,22.188.0,32.189.0,40.135.0,58.205.0"}
P.entries["quest:223"] = {n="Воргени в лісі",s="Це доручення — доставити рекомендаційний лист Калора Джонатанові Каревіну в Даркширі, і ним завершується ваше полювання на диких воргенів Сутінколісся. Вражений вашою звитягою проти звіриних загарбників, Калор скеровує вас просто до людини, що бореться з глибшими загрозами серед тіней.",h="Це доручення — доставити рекомендаційний лист Калора Джонатанові Каревіну в Даркширі, і ним завершується ваше...",kw={"воргени в лісі","калор","джонатан каревін","погибель роланда","рекомендація","даркшир"},ang={["class:Paladin"]="Каревін вітає перевірених союзників закликами до Святого Світла, шукаючи святих звитяжців, готових твердо стояти проти розгулу нечестивого зла в Сутінколіссі.",["class:Priest"]="Прощальне благословення Каревіна, «Слава у Світлі», відлунює відчайдушною вірою останніх захисників Даркшира перед обличчям нескінченної темної скверни.",["faction:Alliance"]="Королівство Стормвінд не може виділити вояків для прикордоння Сутінколісся, тож незалежні шукачі пригод з Альянсу й самочинні захисники на кшталт Каревіна — єдиний рубіж оборони міста."},sec={{t="Рідкісна рекомендація",b="Винищивши зграю Найтбейн, що нишпорила біля Погибелі Роланда й темними галявинами, ви здобуваєте тяжко зароблену повагу Калора. Калор, що несе варту на темних рубежах лісу, рідко роздає похвали, а тим паче офіційні рекомендації. Простягаючи вицвілий клапоть пергаменту, він доручає вам передати його слово просто Джонатанові Каревіну в Даркширі й зауважує: якби в них було більше бійців вашого гарту, їхній невеличкий загін нарешті перевершив би знесилену Нічну Варту міста."},{t="Варта Каревіна",b="Джонатан Каревін діє в Даркширі під величезним тиском: він насторожено ставиться до чужинців і вічно не має часу. Місту загрожують не лише слинаві воргени, а й неспокійна нежить, тіньові демонічні сили та зрадливі культисти, що допомагають скверні зсередини. Палка рекомендація Калора розтоплює холодність Каревіна й підтверджує, що ви — надійний клинок, відданий збереженню Світла серед задушливих жахіть Сутінколісся."}},faq={{q="Хто посилає мене на це доручення?",a="Вас посилає Калор. Побачивши, як ви впоралися з ненажерливими зграями воргенів по всьому Сутінколіссю, він дає вам вицвілий рекомендаційний лист для свого спільника — Джонатана Каревіна.",al={"хто дає завдання","хто це починає","калор"}},{q="Хто такий Джонатан Каревін?",a="Джонатан Каревін — похмурий, зосереджений мешканець Даркшира, що керує боротьбою з надприродним злом, яке загрожує містечку. Він насторожено ставиться до чужинців, але разом із довіреними людьми, як-от Калор, викорінює нежить, демонів і їхніх пособників.",al={"каревін","хто такий каревін","майстер каревін"}},{q="Чому Калор так зневажливо ставиться до Нічної Варти?",a="Калор натякає, що офіційна Нічна Варта містечка ледве тримається й надто розпорошена, щоб упоратися з усіма жахами, які заполонили Сутінколісся. Він вважає, що кілька вправних, відданих бійців поза офіційною бюрократією зроблять проти тіней, що насуваються, значно більше.",al={"калор нічна варта","переважають нічну варту","чому змагатися з нічною вартою"}},{q="Про які загрози попереджає Каревін, коли отримує лист?",a="Прочитавши рекомендацію, Каревін попереджає, що Даркширові загрожують з усіх боків: ненажерливі воргени, блукаюча нежить, демони-загарбники й підступні культисти чи пособники, що їм допомагають. Він радить завжди бути пильними й довіряти лише перевіреним союзникам.",al={"вороги каревіна","що каже каревін","з ким ми боремося"}},{q="Чи доведеться в цьому завданні битися?",a="Ні. Цей останній крок — суто доставка. Після небезпечних полювань на воргенів Найтбейн по всьому Сутінколіссю в попередніх частинах ланцюжка треба лише безпечно доставити лист Калора Каревінові в Даркшир.",al={"чи буде бій","чи щось вбивати","лише доставка"}},{q="Де знайти Джонатана Каревіна?",a="Джонатан Каревін — у містечку Даркшир у Сутінколіссі, де він займається нагальними справами хиткої оборони містечка.",al={"місце каревіна","де каревін","куди здати"}}},fp="19,285,21.503.0,15.479.0,29.213.0,24.271.0,46.276.0,51.271.0,35.246.0,34.140.0"}
P.entries["quest:224"] = {n="На захист королівських земель",s="Горянин Кобблфлінт стереже південну вежу в Долині Королів і відчайдушно шукає підмоги проти трогів Кам'яного Уламка, що підступають усе ближче. Військо Айронфорджа розпорошене по далеких фронтах, тож оборона південних перевалів Лох Модану лягає на плечі добровольців з Альянсу, що проходять повз.",h="Горянин Кобблфлінт стереже південну вежу в Долині Королів і відчайдушно шукає підмоги проти трогів Кам'яного...",kw={"на захист королівських земель","горянин кобблфлінт","долина королів","троги","долина кам'яного уламка","лох модан"},ang={["class:Hunter"]="Скелі й виступи Долини Кам'яного Уламка — ідеальна місцина, щоб з висоти знімати агресивних вартових трогів і їхні розвідувальні загони.",["faction:Alliance"]="Допомагаючи захистити Долину Королів, ви показуєте силу союзу Альянсу й відповідаєте на благання Айронфорджа, коли дворфійські загони воюють на далеких союзницьких фронтах.",["race:Dwarf"]="Для дворфійських шукачів пригод відгукнутися на заклик Кобблфлінта — важлива справа захисту батьківщини: прадідівські долини Короля Маґні не повинні дістатися підземній напасті, поки військо воює деінде."},sec={{t="Тонка лінія в Долині Королів",b="Велетенські дворфійські пам'ятники, вирізьблені в горах Долини Королів, нависають над залогою, що ледве тримається. Горянин Кобблфлінт і його товариші-вартові на південній сторожовій вежі протистоять дедалі більшій навалі трогів, які виринають просто зі скель. Більшу частину регулярного війська Короля Маґні Бронзбірда відіслано далеко на підтримку союзників з Альянсу, тож тил покладається на місцеві патрулі й найманих бійців, щоб край не заполонили."},{t="Навала Кам'яного Уламка",b="Підземна загроза бере початок у Долині Кам'яного Уламка — скелястому яру, що врізається в південні вершини Лох Модану. Троги та їхні розвідники масово прогризлися на поверхню й облаштували на дні долини укріплені табори. Якщо їх не спинити, їхні розвідувальні загони загрожуватимуть важливим дорогам, що з'єднують Лох Модан із південними перевалами, — і горяни змушені вести безперервну війну на виснаження."}},faq={{q="Чому гарнізонові Лох Модану так бракує людей?",a="Король Маґні Бронзбірд відправив значну частину війська Айронфорджа на далекі поля битв і застави Альянсу по всьому Азероту. Через це рідні землі на кшталт Лох Модану захищають переважно невеликі патрулі горян, які мусять кликати мандрівних шукачів пригод, щоб стримати навали в краю.",al={"чому мало вартових","де солдати айронфорджа","чому не вистачає людей"}},{q="Хто такий Горянин Кобблфлінт?",a="Горянин Кобблфлінт — дворфійський вартовий на південній вартовій вежі в Долині Королів. Він керує охороною вздовж південного кордону Лох Модану й спрямовує контратаки на племена трогів, що там гніздяться.",al={"кобблфлінт","хто дає завдання","дає завдання"}},{q="Де розташована Долина Кам'яного Уламка?",a="Долина Кам'яного Уламка лежить на південь від Телсамара; вхід до неї — біля головного шляху, ще до величезних статуй дворфів у Долині Королів. На її скелястому дні троги мають кілька таборів.",al={"місце кам'яного уламка","де троги","знайти долину кам'яного уламка"}},{q="Чому троги такі небезпечні для дворфів?",a="Троги — агресивні підземні громили, що прогризаються крізь суцільну скелю, оминаючи звичайні мури й укріплення на поверхні. Вони можуть без попередження вирватися з-під доріг, поселень і копалень, тож дворфійська влада вважає їхнє нестримне розмноження смертельною загрозою для безпеки Айронфорджа.",al={"загроза трогів","чому битися з трогами","чи троги небезпечні"}},{q="До кого звертатися після допомоги Кобблфлінтові?",a="Коли ви проріджите лави трогів Кам'яного Уламка та їхніх розвідників, Кобблфлінт посилає вас до Горянина Ґравелґоу в сусідній вартовій вежі — той керує наступним етапом патрулювання вздовж долини.",al={"наступне завдання","куди йти після","граветгав"}},{q="Чи організовані троги Кам'яного Уламка?",a="Попри первісність, клан Кам'яного Уламка має зачатки організації: розсилає розвідників стежити за шляхами, а поруч із ними — громил-піхотинців, що тримають оборонні табори по всій ущелині.",al={"розвідники трогів","чи троги розумні","структура кам'яного уламка"}}},fp="30,289,34.477.0,27.426.0,49.323.0,31.239.0,38.219.0,54.314.0,44.226.0,39.218.0"}
P.entries["quest:2242"] = {n="Доля кличе",s="«Доля кличе» — таємне розслідування, яке доручає Сюрна, щоб знайти джерело скверни, що просочується гіллям Тельдрассилу. Агент має прослизнути повз ворожого сатира на ім'я Сетір Прадавній біля Галявини Оракула або зійтися з ним у бою — і забрати його щоденник.",h="«Доля кличе» — таємне розслідування, яке доручає Сюрна, щоб знайти джерело скверни, що просочується гіллям...",kw={"доля кличе","сюрна","сетір прадавній","щоденник сетіра","галявина оракула","розбійник","скверна"},ang={["class:Rogue"]="Це завдання дають наставники скритності самого Дарнасуса, і воно перевіряє, чи здатен лазутчик поцупити важливі відомості просто з-під носа небезпечного сатира.",["faction:Alliance"]="Це відкриття пов'язує місцевий неспокій у лісах Тельдрассилу з ширшою скверною на континенті й готує ґрунт для сил Альянсу, що вирушають до північного Калімдору.",["race:NightElf"]="Для захисників-калдореїв звістка про те, що давнє прокляття Темного Узбережжя перекинулося через море на Тельдрассил, означає грізну загрозу їхньому священному прихистку."},sec={{t="Тиха розвідка",b="Провід нічних ельфів у Дарнасусі з тихою тривогою стежить за дедалі тяжчою недугою Тельдрассилу. Замість посилати озброєні патрулі на певну смерть, наставниця розбійників Сюрна шукає когось, хто здатен на тонку роботу. Сетір Прадавній, сатир, що влаштувався на віддаленій гілці біля Галявини Оракула, відбивав і всі спроби взяти його силою, і всі дипломатичні кроки. Щоб дізнатися, що йому відомо, треба прослизнути до його лігва й забрати його особисті речі."},{t="Тінь, що насувається з Темного Узбережжя",b="Сторінки щоденника Сетіра відкривають похмурі істини. Підступна скверна, що загрожує новонародженому Світовому Древу, напряму пов'язана з давньою гниллю й зіпсуттям, які пожирають ліси й ріки за туманним морем, на Темному Узбережжі. Це не окрема хвороба ґрунту: недуга вказує на ширше, навмисне зло, що загрожує серцю земель калдореїв."}},faq={{q="Хто такий Сетір Прадавній?",a="Сетір Прадавній — невловний сатир, що ховається на гілляці на північній околиці Галявини Оракула на Тельдрассилі. Ворожий і хитрий, він відбив і збройні напади, і мирні спроби дізнатися, що він знає про скверну на острові.",al={"сетір","хто такий сетір","сатир у галявині оракула"}},{q="Навіщо Сюрні щоденник Сетіра?",a="Сюрна вірить, що Сетір знає щось важливе про неприродну хворобу, яка поширюється Тельдрассилом. В особистому щоденнику сатира — записи про його справи й природу темної скверни.",al={"чому щоденник сетіра","мета сюрни","що в щоденнику"}},{q="Що розкриває щоденник наприкінці?",a="Щоденник підтверджує, що хвороба, яка опанувала гілля Тельдрассила, пов'язана з глибшою демонічною пошестю, що вразила давні ліси й узбережжя Темного Узбережжя за протокою.",al={"лор щоденника","що знайшов сетір","зв'язок з темним узбережжям"}},{q="Де взяти це завдання?",a="Завдання дає Сюрна — наставниця розбійників, що ховається в тінях Дарнасуса, — після першої перевірки вашої вправності.",al={"де взяти доля кличе","хто дає доля кличе","дає доля кличе"}},{q="Куди йти шукачам пригод після цього доручення?",a="Сюрна зауважує, що ви зробили для Тельдрассила в цій справі все можливе, і спрямовує молодих захисників на Темне Узбережжя, де чекає справжній корінь скверни на суходолі.",al={"що далі","наступний крок після долі кличе","після сетіра"}},{q="Чому скверною в лісі займається наставниця розбійників, а не друїди?",a="Звичайні методи — і збройні загони, і друїдська дипломатія — проти Сетіра провалилися зі смертельними наслідками. Коли відкриті спроби заходять у криваві глухі кути, Сюрна вдається до таємної розвідки й проникнення.",al={"чому завдання розбійника","чому сюрна","чому не ценаріонське коло"}}},fp="13,276,23.456.0,31.375.1,26.260.0,38.206.0,45.186.1,29.148.0,58.174.1,68.211.0"}
P.entries["quest:2259"] = {n="Еріон Шейдвіспер",s="«Еріон Шейдвіспер» — простий заклик, що скеровує розбійників Альянсу, які набираються досвіду, до Дарнасуса. Послання передає Джаннок Бризсонг: воно веде мандрівників до Ценаріонського Анклаву, де на них чекає Еріон, щоб відкрити їм шлях за межі рідних земель.",h="«Еріон Шейдвіспер» — простий заклик, що скеровує розбійників Альянсу, які набираються досвіду, до Дарнасуса.",kw={"еріон шейдвіспер","джаннок бризсонг","ценаріонський анклав","дарнасус","розбійник","сюрна"},ang={["class:Rogue"]="Це завдання-перехід позначає ваш вихід за межі учнівської роботи на Тельдрассилі й веде вас просто до Еріона Шейдвіспера — по доручення, що вимагають вправності, якої не здобути в початкових лісах.",["faction:Alliance"]="Завдання велить агентам Альянсу на півночі Калімдору порадитися з кураторами в Дарнасусі, перш ніж вирушати на спірні землі.",["race:NightElf"]="Для нічних ельфів, що ходять тінями, з'явитися до Еріона в Дарнасусі — важливий обряд посвяти: від охорони рідних земель до ширших обов'язків на континенті."},sec={{t="Виклик до Анклаву",b="Коли розбійник здобуває собі ім'я в околицях Тельдрассилу, Джаннок Бризсонг дбає, щоб його хист не пропав марно. Розвіюючи тривожні думки про те, що його пошлють до вимогливої наставниці Сюрни, Джаннок натомість скеровує агента просто в серце Дарнасуса. Там, у зеленому гіллі Ценаріонського Анклаву, Еріон Шейдвіспер опікується справами, що потребують тихішого й тоншого підходу."},{t="Погляд за обрій",b="Зустріч з Еріоном — важливий поворот для кожного розбійника, що діє на землях нічних ельфів. З його привітання ясно: захищені ліси Тельдрассилу вже не вміщають обов'язків агента. Еріон скеровує вправні руки назовні, у ширший і небезпечніший світ, і стає трампліном до доручень за морем."}},faq={{q="Хто посилає шукати Еріона Шейдвіспера?",a="Виклик передає Джаннок Бризсонг: він каже негайно вирушати до Дарнасуса й поговорити з Еріоном Шейдвіспером у Ценаріонському Анклаві.",al={"хто дає завдання","хто дає еріона шейдвіспера","завдання джанока бризсонґа"}},{q="Де знайти Еріона Шейдвіспера?",a="Еріон Шейдвіспер — у Ценаріонському Анклаві в Дарнасусі, серед дерев на верхніх ярусах анклаву.",al={"місце еріона","де еріон","де знайти еріона шейдвіспера"}},{q="Чому Джаннок згадує Сюрну?",a="Сюрна — знана наставниця розбійників у Дарнасусі, відома суворістю й вимогливою наукою. Джаннок жартома запевняє вас, що у вас немає клопотів і що вас не тягнуть на її виснажливі уроки.",al={"хто така сюрна","чому не сюрна","джаннок про сюрну"}},{q="Що буде, коли доповісти Еріонові?",a="Вислухавши вашу доповідь, Еріон дає вам наступне доручення в завданні «Веління Еріона», відправляючи вас за межі Тельдрассила, щоб розширити ваші справи на Калімдорі.",al={"що далі","продовження еріона","завдання після еріона шейдвіспера"}},{q="Якою роботою опікується Еріон?",a="Еріон координує операції й спрямовує молодих розбійників у Дарнасусі — це куратор, який пов'язує місцевих агентів з ширшими місіями в мережі Альянсу.",al={"чи еріон тренер розбійників","роль еріона шейдвіспера","що робить еріон"}},{q="Чому куратор розбійників працює в Ценаріонському Анклаві?",a="Ценаріонський Анклав відомий передусім друїдами й шануванням природи, але його розлогі тінисті дерева дають досить усамітнення, щоб потайні агенти могли збиратися й вести справи подалі від Храму Місяця.",al={"розбійник ценаріонського анклаву","чому друїдський район для розбійника"}}},fp="18,245,24.444.0,19.359.0,41.142.0,36.127.0,31.217.0,38.164.0,37.170.0,57.221.0"}
P.entries["quest:226"] = {n="Вовки наступають на п'яти",s="«Вовки наступають на п'яти» — завдання Альянсу, яке дає Ларс у Таборі Свена на заході Сутінколісся. Полюючи на скажених і голодних лютих вовків, що нишпорять довколишнім лісом, мандрівники усувають нагальні загрози з глушини, щоб Свен і Ларс могли зосередитися на помсті некромантові Морбенту Фелу.",h="«Вовки наступають на п'яти» — завдання Альянсу, яке дає Ларс у Таборі Свена на заході Сутінколісся.",kw={"вовки наступають на п'яти","ларс","табір свена","люті вовки","морбент фел","сутінколісся"},ang={["class:Hunter"]="Приручати чи винищувати спотворену живність Сутінколісся треба з неабиякою пильністю: ці люті вовки значно відчайдушніші й жорстокіші за звичайних лісових звірів.",["faction:Alliance"]="Допомога Ларсові зміцнює віддалений табір Свена й забезпечує союзникам плацдарм проти сил нежиті, що терзають західне Сутінколісся."},sec={{t="Хиткий табір",b="Сховавшись серед західних пагорбів Сутінколісся біля кордону з Вестфолом, Свен Йорґен і його товариш Ларс тримають відрізану заставу. Живучи далеко від Даркшира, вони виживають лише завдяки тому, що самі збирають їжу й полюють. Та щоразу, коли Ларс несе свіжу здобич темним лісом, він стає спокусливою ціллю для ненажерливих хижаків, що чатують у тіні річкових берегів і підліску."},{t="Очистити ліс",b="Місцеві зграї голодних і скажених лютих вовків блукають здебільшого на північ і схід від табору, ближче до річки. Винищуючи цих несамовитих звірів, мандрівники знімають облогу з Ларсового полювання. Коли вовків стає менше, обом чоловікам більше не доводиться щодня битися за шматок хліба, і вони можуть цілком зосередитися на некроманті Морбенті Фелі, що причаївся далі на схід."}},faq={{q="Хто такий Ларс?",a="Ларс — загартований виживальник, що допомагає Свенові Йорґену в невеликому таборі серед пагорбів західного Сутінколісся. Він щодня полює й добуває харч для табору, поки Свен одержимий помстою темним силам, що загрожують краю.",al={"ларс","хто дає вовки наступають на п'яти","дає ларс"}},{q="Де никають вовки?",a="Люті вовки никають лісами одразу на північ і схід від Табору Свена, особливо вздовж берегів річки, що відділяє Сутінколісся від північних країв.",al={"місце вовків","де скажені вовки","де голодні вовки"}},{q="Чому люті вовки такі агресивні?",a="Дика природа Сутінколісся занепала під тінню, що насувається. Дичини обмаль, і люті вовки ледь не мруть з голоду, а хвороба чи темна скверна зробила багатьох скаженими й нестямно жорстокими до кожного, хто несе свіже м'ясо.",al={"чому вовки агресивні","скажені вовки сутінколісся"}},{q="Хто такий Морбент Фел?",a="Морбент Фел — могутній некромант, що чаклує темні мистецтва на цвинтарі й у курганах на сході. Свен і Ларс мають до нього гірку образу й готуються його здолати, щойно забезпечать собі найпотрібніше для виживання.",al={"морбент фел","некромант","хто некромант на сході"}},{q="Що за спалахові пакунки дає в нагороду Ларс?",a="Спалахові пакунки — сліпучі пристрої, які виготовляють мешканці Даркшира. Співчутливі містяни передали їх до табору Свена, щоб допомогти йому в боротьбі з нежиттю й звірами, що заполонили ліс.",al={"спалахові пакунки","нагорода ларса","що таке спалаховий пакунок"}},{q="Чому Свен і Ларс не живуть у Даркширі?",a="Родину Свена спіткала трагедія, що зробила з нього озлобленого, одержимого месника. Замість ховатися за Нічною Вартою в Даркширі, Свен і Ларс отаборилися в дикій глушині, щоб самим вистежувати зло, яке мучить ліс.",al={"чому жити в таборі","місце табору свена","чому не в місті"}}},fp="19,311,17.404.0,18.401.0,12.237.0,30.163.0,38.246.0,19.223.0,50.197.0,42.242.0"}
P.entries["quest:2260"] = {n="Веління Еріона",s="«Веління Еріона» — заклик, що його надсилають обдарованим розбійникам нічних ельфів у Дарнасусі. Помітивши їхній хист до скритності, наставник розбійників Еріон Шейдвіспер посилає їх через море до Стормвінда — з'явитися просто до Розвідки Стормвінда.",h="«Веління Еріона» — заклик, що його надсилають обдарованим розбійникам нічних ельфів у Дарнасусі.",kw={"веління еріона","еріон шейдвіспер","si:7","розвідка стормвінда","рензік","старе місто","розбійник"},ang={["class:Rogue"]="Цей заклик знаменує ваш перехід від місцевих сутичок у Калімдорі до ширшого світу шпигунства на континенті й смертоносної науки SI:7.",["faction:Alliance"]="SI:7 зосереджує у своїх руках таємні операції Альянсу, щоб обдарованих розвідників будь-якої раси союзу можна було послати туди, де вони найпотрібніші короні.",["race:NightElf"]="Покинути прихисток Дарнасуса й Тельдрассилу заради служби людській розвідці в кам'яних провулках Стормвінда — для калдорейських нишпорок це часто справжній культурний шок."},sec={{t="Заклик через море",b="Розбійники нічних ельфів, що діють у затінку Тельдрассилу, зазвичай відточують майстерність під тихим наглядом наставників на кшталт Еріона Шейдвіспера. Та коли агент виявляє винятковий хист, чутка про нього лине далеко за гілля Світового Древа. Через Еріона Розвідка Стормвінда, більш відома як SI:7, надсилає пряме запрошення перетнути Велике Море й прибути до столиці людей."},{t="На службі SI:7",b="Шлях нелегкий: він веде агента з північних окраїн Калімдору через доки Темного Узбережжя чи Багнокраю аж до гомінких вулиць Стормвінда. У столиці агент має непомітно дістатися Старого Міста й з'явитися до штаб-квартири SI:7. Там на новачка чекає Рензік \"Ніж\", щоб оцінити його й відчинити двері до вищого шпигунства, майстерності отрут і таємних операцій на користь Альянсу."}},faq={{q="Хто посилає мене на це доручення?",a="Еріон Шейдвіспер, наставник розбійників у Дарнасусі, дає вам це доручення, коли ваші перші звершення привертають увагу розвідувальних мереж за морем.",al={"хто дає завдання","еріон шейдвіспер","хто мені це дав"}},{q="Чому розвідка Стормвінда звертається до нічного ельфа?",a="Нічні ельфи мають власні традиції скрадання, але Альянс значною мірою покладається на SI:7 у таємній розвідці й диверсіях. Розвідка Стормвінда постійно шукає вправних розбійників будь-якої раси Альянсу, щоб поповнити свої лави.",al={"чому si:7","чому стормвінд","чому люди цікавляться"}},{q="Де знайти Рензіка «Ніж»?",a="Рензік «Ніж» перебуває в осередку SI:7, захованому в кварталі Старе Місто в Стормвінді.",al={"місце рензіка","де ніж","знайти рензіка"}},{q="Чи це завдання лише для розбійників?",a="Так. Це класове завдання для розбійників Альянсу, що має привести агентів з Калімдору до головного осередку розвідувального вишколу Альянсу в Стормвінді.",al={"лише розбійники","чи інші класи можуть це","завдання розбійника"}},{q="Що буде після зустрічі з Рензіком?",a="Доповідь Рензікові залучає вас до навчальних операцій SI:7 у Східних Королівствах, відкриваючи шлях до особливого вишколу й таємних доручень по всіх людських землях.",al={"наступне завдання","що я отримаю","після рензіка"}},{q="Як нічному ельфові на цьому етапі дістатися Стормвінда?",a="Треба сісти на корабель в Обердайні на Темному Узбережжі й перепливти море до Гавані Менетіл у Багнокраї, здолати небезпечний шлях через Лох Модан і Дун Мороґ до Айронфорджа, а тоді Глибинним трамваєм доїхати до Стормвінда.",al={"як дістатися стормвінда","подорож до стормвінда","шлях до стормвінда"}}},fp="14,262,24.399.0,28.426.0,29.161.0,53.256.0,34.128.0,30.153.0,34.182.0,57.225.0"}
P.entries["quest:2281"] = {n="Рандеву в Редріджі",s="«Рандеву в Редріджі» — доручення для розбійників Альянсу, яке надходить зі штабу розвідки Стормвінда. Розуміючи, що зеленим новобранцям бракує вправності для небезпечних операцій у полі, SI:7 відсилає перспективних агентів до Лейкширу відшліфувати майстерність під наглядом бувалих оперативників.",h="«Рандеву в Редріджі» — доручення для розбійників Альянсу, яке надходить зі штабу розвідки Стормвінда.",kw={"рандеву в редріджі","si:7","луціус","лейкшир","рензік","розбійник"},ang={["class:Rogue"]="Ця операція знаменує вступ розбійника до справжньої польової роботи SI:7: від крадіжок у провулках ви переходите до розважливого державного шпигунства.",["faction:Alliance"]="Це доручення показує, як далеко сягає таємна рука Стормвінда: її тихі агенти чатують навіть у віддалених поселеннях на кшталт Лейкширу."},sec={{t="Мірило виживання",b="У потаємних залах SI:7 у Стормвінді заступник очільника Рензік «Ніж» говорить прямо: новачки живуть недовго. Кинути необтесаних агентів просто у ворожі операції — означає отримати трупи замість розвідданих. Щоб уникнути марних утрат, новобранців із хистом відсилають на схід, у Гори Редріджу, вчитися в Луціуса — агента, що чатує на пристанях біля озера."},{t="Очі в Лейкширі",b="Лейкшир — ідеальний плацдарм для таємного вишколу. Затиснуте між гнолами й орками Блекрок, прикордонне містечко дає вдосталь справжньої небезпеки, а гамірні причали — чудове прикриття для агента на кшталт Луціуса: тут він може оцінити скритність, спритність і вміння розбійника зламувати замки, не привертаючи уваги ні містян, ні міської варти."}},faq={{q="Хто дає завдання «Рандеву в Редріджі»?",a="Рензік «Ніж», гоблін-шпигун з осередку SI:7 у Старому Місті Стормвінда, дає це доручення розбійникам, які з'явилися до розвідувального командування.",al={"хто дає рандеву в редріджі","завдання рандеву в редріджі","хто дає завдання"}},{q="Де шукати Луціуса?",a="Луціус стоїть на дерев'яних причалах Лейкшира в Горах Редріджу, розчиняючись серед місцевих гультяїв і рибалок біля води.",al={"де луціус","місце луціуса","знайти луціуса"}},{q="Чому SI:7 посилає розбійників у Редрідж?",a="Рензік вважає зелених розбійників непридатними для відповідальних розвідувальних доручень. Луціусові доручено обтесати їх і перевірити практичні навички, як-от кишенькові крадіжки й відмикання замків, в умовах прикордоння.",al={"чому лейкшир","мета рандеву в редріджі","чому редрідж"}},{q="Що далі після «Рандеву в Редріджі»?",a="Доповідь Луціусові веде просто до навчальних вправ, починаючи з «Млина Альтера», де агентові доведеться випробувати своє вміння скрадатися й спритність рук.",al={"наступне завдання","продовження рандеву в редріджі","після рандеву в редріджі"}},{q="Чи доступне це завдання іншим класам, крім розбійників?",a="Ні. «Рандеву в Редріджі» — класове завдання лише для розбійників Альянсу, створене для польового вишколу SI:7.",al={"чи воїни можуть рандеву в редріджі","чи лише для розбійників","вимога до класу"}},{q="Чому Рензік працює на розвідку Стормвінда?",a="Хоч Рензік «Ніж» і гоблін, він — один з найдовіреніших помічників шпигунського майстра Матіаса Шоу й керує набором і вишколом агентів з глибин твердині SI:7.",al={"чому гоблін у si7","рензік лор","гоблін у стормвінді"}}},fp="19,288,21.416.0,17.368.0,40.178.0,24.146.0,38.227.0,48.172.0,53.101.0,48.175.0"}
P.entries["quest:2282"] = {n="Млин Альтера",s="Млин Альтера — важливе навчальне завдання, яке Луціус у Лейкширі дає розбійникам Альянсу. Отримавши набір злодійських знарядь, новачки вирушають до сусіднього млина, щоб пробратися туди, де пильнують орки Блекрок, зламати замкнену скриню й забрати Жетон Злодійства.",h="Млин Альтера — важливе навчальне завдання, яке Луціус у Лейкширі дає розбійникам Альянсу.",kw={"млин альтера","луціус","розбійник","жетон злодійства","сертифікат злодійства","si:7"},ang={["class:Rogue"]="Цей обряд посвяти дає вам найпотрібніші відмички й польові повноваження та випробовує вашу терплячість і вміння скрадатися серед патрулів орків Блекрок.",["faction:Alliance"]="Навчання вправних злодіїв і лазутчиків на околицях Лейкширу зміцнює розвідку Альянсу й водночас дає змогу пильно стежити за пересуваннями Блекрок."},sec={{t="Випробування спритності й витонченості",b="У Лейкширі наставники розбійників не марнують часу на заумні лекції, коли замкнена скриня навчить швидше. Луціус посилає здібних учнів на північний схід дорогою до Млина Альтера, вручаючи їм перший набір злодійських знарядь. Щоб здобути офіційний Сертифікат Злодійства, новачки мають прослизнути в покинутий млин, відімкнути особисту скриньку Луціуса й принести схований у ній жетон."},{t="Тіні серед пилок",b="Колись Млин Альтера був звичайною лісопилкою, але віднедавна привернув небезпечну увагу орків Блекрок, що підступають до Редріджу. Луціус радо вважає ворожих вояків додатковою частиною практичного іспиту. Непомітно скрадатися ворожою територією й відмикати замки — саме таке випробування SI:7 очікує від своїх агентів."}},faq={{q="Яка мета доручення в Млині Альтера?",a="Це практичний польовий іспит для розбійників Альянсу, що вчаться відмикати замки. Луціус дає вам злодійське знаряддя й вимагає дістати певну річ із замкненої скрині, щоб довести вашу спритність.",al={"навіщо йти до млина альтера","мета завдання","що дає це завдання"}},{q="Хто такий Луціус?",a="Луціус — досвідчений наставник розбійників, що працює з Лейкшира в Горах Редріджу. Роками він навчає розбійників-новобранців, яких надсилають до нього знайомі по всьому Альянсу, перевіряючи їхнє вміння скрадатися й спритність рук.",al={"хто такий луціус","луціус лейкшир","хто дає це завдання"}},{q="Де розташований Млин Альтера?",a="Млин Альтера стоїть трохи осторонь шляху на північний схід і схід від Лейкшира, тулячись до передгір'їв перед вищими гірськими перевалами.",al={"де млин","місце млина альтера","як знайти млин альтера"}},{q="Звідки біля Млина Альтера орки?",a="Орки клану Блекрок спустилися з висот Кам'яної Варти й палаючих хребтів над нею, нападаючи на людські поселення й закріплюючись по всьому Редріджу, зокрема й довкола покинутого млина.",al={"чому тут орки","орки блекрок редрідж","хто тримає млин альтера"}},{q="Яку нагороду дає Луціус за виконання завдання?",a="Луціус вручає вам Сертифікат Злодійства, визнаючи, що ви опанували основи роботи із замками й відмичками й тепер можете діяти як повністю атестований польовий розбійник.",al={"яка нагорода","свідоцтво злодійства","нагорода за завдання"}},{q="Яке місце це завдання посідає у вишколі розбійників Альянсу?",a="Розбійників з усіх земель Альянсу знайомі — як-от куратори SI:7 Матіаса Шоу в Стормвінді — посилають на зустріч із Луціусом у Лейкширі. Доручення в Млині Альтера — практична вершина їхнього базового польового вишколу.",al={"ланцюжок розбійника","зв'язок з si7","продовження рандеву в редріджі"}}},fp="13,289,27.415.0,23.376.0,52.231.0,14.228.0,31.143.0,40.223.0,55.174.0,64.236.0"}
P.entries["quest:23"] = {n="Лапа Урсанґуса",s="Це завдання — доказ перемоги над Урсанґусом, одним із найлютіших і найлегендарніших хижаків Ашенвалю. Принісши відтяту лапу звіра Сенані Тандергарт на Заставу Розщепленого Дерева, ви здобудете шану серед слідопитів Орди й відкриєте несподіваний зв'язок між великим ведмедем і місцевими нічними ельфами.",h="Це завдання — доказ перемоги над Урсанґусом, одним із найлютіших і найлегендарніших хижаків Ашенвалю.",kw={"лапа урсанґуса","урсанґус","ведмідь","сенані тандергарт","полювання ашенваля","завдання"},ang={["class:Hunter"]="Вистежити й здолати одного з найдавніших і найсмертоносніших хижаків Ашенвалю — найкраще випробування вміння читати сліди, виживати й битися.",["faction:Horde"]="Мисливці Орди вважають Урсанґуса небезпечною здобиччю, перемога над якою приносить шану на Заставі Розщепленого Дерева.",["race:Tauren"]="Для тауренських мисливців здобути лапу Урсанґуса — священна справа: так вони вшановують звіра, водночас виявляючи бойову рішучість і шану до духів полювання."},sec={{t="Трофей великого полювання",b="У межах Полювання Ашенвалю слідопити із Застави Розщепленого Дерева мають вистежувати прадавніх звірів, що панують у густих лісових хащах. Урсанґус — один із найлютіших серед цих верховних хижаків: він убив чимало мандрівників і воїнів, які стали йому на шляху. Здолати такого звіра — неабиякий подвиг, а його лапа — незаперечний доказ того, що могутня істота нарешті знайшла рівного собі суперника."},{t="Слід нічних ельфів",b="Якщо придивитися до лапи Урсанґуса, на ній видно невеликий знак у формі чверті півмісяця, вирізаний чи випалений на шкурі. Коли лапу приносять Сенані Тандергарт, вона розпізнає в цій мітці явну ознаку впливу калдореїв. Нічні ельфи часто навчають грізних лісових звірів і заприязнюються з ними, щоб боронити свої священні кордони, — отже, Урсанґус, найпевніше, був не просто диким хижаком, а мимовільним охоронцем чи зброєю Альянсу."}},faq={{q="Хто такий Урсанґус?",a="Урсанґус — надзвичайно великий і смертоносний ведмідь, що никає лісами Ашенвалю. Його бояться і мисливці, і мандрівники; він забрав незліченні життя, перш ніж полягти від мисливців Орди.",al={"хто такий урсанґус","ведмідь урсанґус","урсанґус лор"}},{q="Що означає емблема півмісяця на лапі?",a="Коли розглядаєте трофей, емблема чверті місяця лишається загадкою. Сенані Тандергарт може її оглянути, коли ви принесете лапу.",al={"півмісяць на лапі","емблема на лапі","чому півмісяць"}},{q="Кому нести Лапу Урсанґуса?",a="Лапу треба віднести Сенані Тандергарт — тауренці-мисливиці із Застави Розщепленого Дерева на сході Ашенвалю.",al={"куди здати лапу","кому потрібна лапа урсанґуса","місце сенані тандергарт"}},{q="Яке місце це посідає в Полюванні в Ашенвалі?",a="Урсанґус — один з трьох великих звірів, на яких полюють у Полюванні в Ашенвалі, разом із Шадумброю та Шарпталоном. Щоб завершити весь обряд, треба здолати всіх трьох і принести їхні трофеї.",al={"ланцюжок полювання в ашенвалі","що таке полювання","лінія полювання"}},{q="Чому Орда полює на великих звірів Ашенвалю?",a="Мисливці Орди, особливо таурени й орки із Застави Розщепленого Дерева, полюють на цих верховних хижаків і щоб випробувати свою бойову вправність, і щоб приборкати найсмертоносніші загрози біля своїх вразливих шляхів постачання й таборів.",al={"чому полювати на ведмедів","лор полювання розщепленого дерева"}},{q="Що буде, коли здати лапу?",a="Щойно ви зберете трофеї Урсанґуса та інших визначених звірів, Сенані Тандергарт визнає ваш тріумф у завершальному випробуванні — «Полювання завершено».",al={"наступне завдання після лапи","що після урсанґуса"}}},fp="15,321,26.441.0,24.456.1,18.193.0,46.130.0,34.122.0,42.198.0,55.224.0,38.177.0"}
P.entries["quest:230"] = {n="Табір Свена",s="«Табір Свена» — завдання Альянсу в Сутінколіссі, що відкриває важливу підказку в трагедії на хуторі Йорґенів. Відкопавши з купи пухкої землі на покинутій фермі закопаний щоденник без назви, шукачі пригод з'ясовують, хто бачив різанину родини Свена Йорґена.",h="«Табір Свена» — завдання Альянсу в Сутінколіссі, що відкриває важливу підказку в трагедії на хуторі Йорґенів.",kw={"табір свена","свен йорґен","хутір йорґенів","щоденник","різанина","сутінколісся"},ang={["faction:Alliance"]="Розслідування різанини Йорґенів — частина ширшої боротьби Альянсу за те, щоб збагнути темні сили, що насуваються на Сутінколісся."},sec={{t="Підказка в землі",b="Темні вершники вигнали Свена Йорґена з дому, а коли він повернувся, то знайшов свою родину вбитою, а ферму — в руїнах. Поглинутий горем і жагою помсти, він послав союзників обшукати згарище хутора. Під купою свіжоскопаної землі лежала закопана невеличка заляпана книжка, кинута серед хаосу."},{t="Мовчазний свідок",b="Коли книгу приносять Свенові в його табір на західних пагорбах, вона відкриває моторошну подробицю: якась темна постать спостерігала за жахливою різаниною його родини. Замість того щоб дати Свенові спокій, щоденник спрямовує його горе на пошуки цього невідомого свідка — і на вимогу відповідей."}},faq={{q="Що за книга в купі землі?",a="Це безіменний, заляпаний землею щоденник, закопаний на фермі Йорґенів. Його записи доводять, що якийсь невідомий спостерігав за різаниною родини Свена Йорґена.",al={"яка це книга","книга з ферми свена","що я відкопав"}},{q="Куди веде це завдання далі?",a="Доставка книги Свенові Йорґену веде просто до завдання «Таємнича постать» — починаються пошуки таємничого свідка.",al={"що далі","наступне завдання після табору свена","хто той тінь"}},{q="Де знайти Свена Йорґена?",a="Свен знайшов притулок у таборі на північно-західних пагорбах Сутінколісся, де похмуро думає про долю своєї родини й замишляє помсту.",al={"де свен","місце свена йорґена","куди це здати"}},{q="Чому книгу закопали на фермі?",a="Книгу сховали в купі пухкої землі серед зруйнованої садиби: її або поспіхом викинув, або навмисно приховав спостерігач, що лишався на місці нападу.",al={"чому закопали","хто сховав книгу","купа розритої землі"}},{q="Хто вбив родину Свена?",a="Таємничі темні вершники промчали фермою, вирізавши Свенову рідню й перетворивши колись мирну садибу на руїну, що кишить нежиттю.",al={"хто напав на ферму","хто вбив родину свена","убивці родини свена"}},{q="Яка фракція може виконати це завдання?",a="Це завдання лише для гравців Альянсу, бо Свен Йорґен просить допомоги лише в захисників Сутінколісся й Альянсу.",al={"чи лише для альянсу","чи орда може табір свена"}}},fp="11,291,18.318.0,16.303.1,44.160.0,32.135.0,29.144.0,36.168.0,25.144.0,37.123.0"}
P.entries["quest:2300"] = {n="SI:7",s="Цей наказ кличе перспективних молодих розбійників із Лісу Елвінн просто в серце таємної розвідувальної мережі Стормвінда. За вказівкою Керін Сильвій із Ґолдширу агенти мають негайно з'явитися до Рензіка «Ножа» в Старому Місті. Відгукнувшись на цей виклик, агент вступає на службу під командою Майстра Матіаса Шоу.",h="Цей наказ кличе перспективних молодих розбійників із Лісу Елвінн просто в серце таємної розвідувальної мережі...",kw={"si:7","рензік ніж","керін сильвій","матіас шоу","старе місто","розбійник"},ang={["class:Rogue"]="Цей виклик знаменує ваш перехід від пройдисвіта на місцевих підробітках до визнаного агента офіційної розвідки Стормвінда.",["faction:Alliance"]="SI:7 — таємний щит Альянсу: служба бере на себе небезпечні шпигунські операції, яких звичайні маршали й піхота не можуть відкрито вести."},sec={{t="Виклик до Старого Міста",b="Наставниця розбійників Керін Сильвій, що тримається в корчмі «Лев'яча Гордість» у Ґолдширі, пильно стежить за місцевими новобранцями. Коли розбійник виявляє досить хитрості й уміння проти дедалі більшої загрози Дефіас, Сильвій передає звістку зі штабу. Виклик короткий і без церемоній: негайно з'явитися до Рензіка «Ножа». Лишивши позаду поля Елвінна, агент вирушає просто в потаємне серце столиці."},{t="Приховані очі Стормвінда",b="За фасадом непримітної казарми в Старому Місті ховається штаб SI:7 — найкращої розвідувальної служби Стормвінда. Під командою Майстра Матіаса Шоу SI:7 веде таємні операції, розвідку й ліквідації по всьому королівству й далеко за його межами. Рензік «Ніж», гострий на язик заступник Шоу, особисто перевіряє перспективних польових агентів, перш ніж відіслати їх на ризиковані операції, яких офіційне військо королівства не може й торкнутися."}},faq={{q="Хто посилає мене доповісти до SI:7?",a="Наказ дає Керін Сильвій, наставниця розбійників у Корчмі «Лев'яча Гордість» у Ґолдширі. Щойно ви доведете свою вправність у полі, Сильвій передає вам розпорядження з'явитися до осередку в Стормвінді.",al={"хто дає завдання","керін сильвій"}},{q="Хто такий Рензік «Ніж»?",a="Рензік «Ніж» — агент-гоблін, заступник очільника SI:7, що працює безпосередньо під началом Майстра Матіаса Шоу. Він оцінює польових агентів і координує таємні розвідувальні доручення з осередку SI:7 у Старому Місті.",al={"рензік ніж","хто такий рензік","рензік"}},{q="Що таке SI:7?",a="SI:7 — скорочення від «Розвідка Стормвінда, Відділ 7» — це таємна служба шпигунства, розвідки й убивств Королівства Стормвінд. Під проводом Матіаса Шоу її агенти збирають відомості про загрози короні, з якими звичайні вартові й солдати впоратися не можуть.",al={"що таке si7","що робить si7","розвідка стормвінда"}},{q="Де розташований осередок SI:7?",a="Осередок SI:7 — у східній частині Старого Міста в Стормвінді. Він діє з укріпленого гільдійського дому й навчальних казарм, захованих подалі від головних вулиць.",al={"де si7","місце si7","де рензік"}},{q="Що буде, коли доповісти Рензікові?",a="Коли ви з'явитеся до Рензіка, він перевірить вашу готовність і дасть польове доручення за міськими мурами — відправить на зустріч з агентом у Редріджі.",al={"наступне завдання","що буде далі","рандеву в редріджі"}},{q="Чому Керін Сильвій називає мене «рибкою»?",a="Це жаргонне слово для неперевіреного новачка чи новобранця. Агенти служби вживають барвисті, колючі прізвиська, щоб тримати новачків на землі, доки ті не проявлять себе на справжніх дорученнях.",al={"чому називає рибкою","значення рибки"}}},fp="4,339,21.429.0,23.473.0,31.223.0,25.240.0,13.281.0,39.184.0,39.170.1,38.192.0"}
P.entries["quest:233"] = {n="Доставка пошти в Долині Холодного Хребта",s="Доставка пошти в Долині Холодного Хребта — просте кур'єрське доручення, яке Стен Стаутарм в Анвілмарі довіряє новобранцям. Гірські перевали часто забиті снігом, а троги тиснуть поруч, тож рознесення свіжої кореспонденції до таборів уздовж замерзлого озера тримає відрізаних захисників долини на зв'язку.",h="Доставка пошти в Долині Холодного Хребта — просте кур'єрське доручення, яке Стен Стаутарм в Анвілмарі довіряє...",kw={"доставка пошти","стен стаутарм","талін кінай","листи","долина холодного хребта","анвілмар","кур'єр"},ang={["faction:Alliance"]="Кожна застава в Долині Холодного Хребта відіграє роль у безпеці Дун Мороґу, тож надійне листування необхідне для ранньої військової координації.",["race:Dwarf"]="Носити звістки між заставами підкреслює спільну твердість дворфів Айронфорджа, яка тримає навіть найдальших розвідників долини пов'язаними зі своїми кланами.",["race:Gnome"]="Як гостям і союзникам у Дун Мороґу після падіння Гномреґану, допомога з лініями зв'язку зміцнює довіру місцевих дворфійських захисників."},sec={{t="Кур'єр у снігу",b="Життя в Долині Холодного Хребта відлюдне навіть у найспокійнішу пору. Коли зимові кур'єри щасливо долають гірський перевал із поштою з решти Дун Мороґу, листи швидко громадяться в Анвілмарі. Стен Стаутарм, заклопотаний місцевим постачанням і безпекою, покладається на мандрівних новобранців, щоб ті несли ці згортки західною дорогою, а не лишали важливі звістки припадати пилом у залі."},{t="Прикордонні застави",b="Адресат, Талін Кінай, стоїть на варті біля замерзлого озера на заході, стежачи за пересуваннями трогів і небезпечною звіриною. Навіть на холоді слово з Айронфорджа й довколишніх застав лишається дорогим. Однак сортування пошти в суворих гірських умовах рідко буває бездоганним, і листи для різних розвідників часто мандрують разом в одному згортку."}},faq={{q="Хто починає доставку пошти?",a="Завдання з доставкою дає Стен Стаутарм біля Анвілмара. Він отримав купу листів, щойно доставлених через гірський перевал, але не може покинути свої обов'язки, щоб рознести їх сам.",al={"хто дає завдання","хто дає доставку пошти долини холодного хребта","завдання стена стаутарма"}},{q="Де знайти Таліна Кіная?",a="Талін Кінай отаборився на захід від Анвілмара, просто при дорозі біля замерзлого озера в Долині Холодного Хребта.",al={"де талін кінай","місце таліна кіная","знайти таліна кіная"}},{q="Чи всі листи в купі справді для Таліна?",a="Ні. Перебираючи пачку, Талін виявляє, що один лист адресований Ґреліну Вайтбірду, який стоїть неподалік у долині.",al={"чи вся пошта для таліна","лист ґреліна вайтбірда","переплутана пошта"}},{q="Чому Стенові потрібен шукач пригод, щоб рознести пошту?",a="Анвілмар саме відбиває навали трогів і місцеві загрози, тож дворфійські захисники на кшталт Стена прикуті до нагальних справ постачання й оборони. Мандрівники й молоді новобранці — найшвидший спосіб доправити листи до віддалених застав.",al={"навіщо розносити пошту","чому стен не рознесе","обов'язок доставки пошти"}},{q="Чи веде це завдання до інших доручень?",a="Так. Коли доставку завершено, Талін просить вас віднести хибно адресований лист Ґреліну Вайтбірду — це друга частина ланцюжка з доставкою пошти.",al={"наступне завдання","ланцюжок пошти","продовження доставки пошти"}},{q="Звідки взялися листи?",a="Листи прийшли перевалом, що веде в Долину Холодного Хребта, — їх надіслали в цю затишну улоговину з ширших земель Дун Мороґу й Айронфорджа.",al={"звідки пошта","джерело листів"}}},fp="30,297,21.405.0,17.372.0,29.210.0,31.118.0,52.151.1,49.265.0,36.148.1,43.146.0"}
P.entries["quest:234"] = {n="Доставка пошти в Долині Холодного Хребта",s="Це доручення завершує кур'єрський рейс засніженими заметами Долини Холодного Хребта. Передати послання від горянина Таліна Кіная далі південно-східною дорогою — означає, що Ґрелін Вайтбірд лишається на зв'язку з дворфійською столицею.",h="Це доручення завершує кур'єрський рейс засніженими заметами Долини Холодного Хребта.",kw={"доставка пошти","талін кінай","ґрелін вайтбірд","послання","долина холодного хребта","кур'єр","айронфордж"},ang={["faction:Alliance"]="Надійні кур'єрські маршрути підступними засніженими перевалами постачають віддаленим розвідникам Альянсу накази й життєво важливі відомості.",["race:Dwarf"]="Кожна застава в Дун Мороґу розраховує на депеші з престолу Короля Маґні в Айронфорджі, щоб оборона королівства лишалася узгодженою."},sec={{t="Ланка до гори",b="Навіть у такій відрізаній улоговині, як Долина Холодного Хребта, новини й офіційне листування мусять мандрувати. Поки Анвілмар — адміністративне серце долини, польові розвідники й вартові вздовж стежок покладаються на піших кур'єрів, щоб передавати послання між високими перевалами й Айронфорджем."},{t="Слово для Вайтбірда",b="Ґрелін Вайтбірд тримає невеликий табір дорогою на південний схід від поста Таліна Кіная. Зносячи крижані замети й постійні наскоки трогів, досвідчені горяни на цих віддалених спостережних пунктах залежать від регулярних послань, щоб знати про ширші справи в Дун Мороґу й королівстві за його межами."}},faq={{q="Хто такий Ґрелін Вайтбірд?",a="Ґрелін Вайтбірд — дворф-ветеран, що стоїть на заставі при південно-східному шляху Долини Холодного Хребта. Він стежить за дорогами долини й пильнує місцеві загрози, як-от трогів і звірів, що підступають.",al={"ґрелін","інфо про ґреліна вайтбірда","хто такий ґрелін"}},{q="Звідки прийшов цей лист?",a="Лист надіслали з дворфійської столиці Айронфорджа. Його привезли в Долину Холодного Хребта, а тоді місцеві гінці й вартові несли його гірськими перевалами, аж поки він не дійшов до адресата.",al={"звідки лист","лист із айронфорджа","хто надіслав лист"}},{q="Чому тут пошту доставляють пішки?",a="Долину Холодного Хребта оточують стрімкі, скуті морозом вершини, і вона відрізана від головних шляхів Дун Мороґу. Грифонових маршрутів до віддалених польових таборів немає, тож донесення між заставами носять у руках довірені мандрівники й горяни.",al={"чому кур'єр пішки","чому розносити пошту","немає скриньок у холодному хребті"}},{q="Де табір Ґреліна Вайтбірда?",a="Його табір далі південно-східним шляхом через Долину Холодного Хребта, за мисливськими й розвідувальними угіддями верхнього перевалу.",al={"де табір ґреліна","місце ґреліна вайтбірда","знайти ґреліна"}},{q="Хто передав лист для Ґреліна?",a="Лист передав Талін Кінай, досвідчений мисливець і розвідник, що стоїть при перевалі, коли той прийшов з головного збірного табору біля Анвілмара.",al={"хто передав лист","роль таліна кіная","хто починає завдання"}},{q="Що буде, коли Ґрелін отримає пошту?",a="Отримавши новини з Айронфорджа, Ґрелін зосереджується на нагальних небезпеках, що загрожують долині, і часто посилає новобранців допомогти проти місцевих тролів-Морозогривів і нападів трогів.",al={"що далі після пошти","наступне завдання ґреліна","після доставки пошти"}}},fp="30,230,22.291.0,19.316.0,25.214.0,32.205.0,35.246.0,42.146.0,47.173.0,44.197.0"}
P.entries["quest:235"] = {n="Полювання в Ашенвалі",s="Цей наказ Воєзвісника Ґорлаха в Оргріммарі кличе молодих шукачів пригод Орди на північ, за Пустки, у давні ліси Ашенвалю. Їм велять з'явитися до Сенані Тандергарт на Заставі Розщепленого Дерева, щоб долучитися до полювання й посилити прикордоння Орди, що дедалі розширюється.",h="Цей наказ Воєзвісника Ґорлаха в Оргріммарі кличе молодих шукачів пригод Орди на північ, за Пустки, у давні...",kw={"полювання в ашенвалі","ашенваль","сенані тандергарт","застава розщепленого дерева","воєзвісник ґорлах","мисливець"},ang={["class:Hunter"]="Густі хащі й небезпечні звірі Ашенвалю — найкращий дикий полігон для молодих слідопитів, що відгукуються на поклик Сенані Тандергарт.",["faction:Horde"]="Похід в Ашенваль перевіряє, чи зможе щойно об'єднана Орда вийти за межі сухих скель Дуротару на багату ресурсами, але ворожу чужу землю.",["race:Tauren"]="Служба під проводом Сенані Тандергарт дає шукачам пригод-тауренам змогу принести глибоку шану до великого полювання в неприборкані північні ліси."},sec={{t="Поклик дикої природи",b="Оргріммар вирує бойовим запалом, але молодому місту для зростання потрібні горами деревина, м'ясо й безпечні торгові шляхи. Воєзвісник Ґорлах — голос верховного командування Орди: він скеровує і бувалих мандрівників, і новобранців до діючих походів. Для воїнів, що змужніли в Дуротарі й Пустках, давні ліси Ашенвалю — наступне випробування і для слави, і для виживання."},{t="Підступне прикордоння",b="Перетнувши північну межу Пусток, мандрівники потрапляють просто в Ашенваль, де Орда тримає два головні оплоти: Заставу Розщепленого Дерева в східних лісах і Заставу Зорам'гар на західному узбережжі. На Заставі Розщепленого Дерева операціями керує Сенані Тандергарт: вона збирає слідопитів і мисливців, щоб приборкати кишучі звірами хащі й дати відсіч ворожим вартовим нічних ельфів, що оспорюють права Орди."}},faq={{q="Хто дає це завдання і де його знайти?",a="Це завдання пропонує Воєзвісник Ґорлах в Оргріммарі, столиці Орди. Він — офіцер, що кличе вправних шукачів пригод у походи за межі Дуротару.",al={"хто дає завдання","де ґорлак","хто дає полювання в ашенвалі"}},{q="Де розташована Застава Розщепленого Дерева?",a="Застава Розщепленого Дерева лежить одразу на північ від Пусток, на сході Ашенвалю, при головному лісовому шляху, що веде на схід до Азшари.",al={"місце застави розщепленого дерева","де застава","як дістатися розщепленого дерева"}},{q="Хто така Сенані Тандергарт?",a="Сенані Тандергарт — досвідчена тауренка-слідопитка із Застави Розщепленого Дерева. Вона керує полюванням по всьому Ашенвалю й оцінює шукачів пригод, які хочуть узяти участь у місцевих випробуваннях.",al={"хто така сенані","місце сенані тандергарт","нпц здавання"}},{q="Яка мета Полювання в Ашенвалі?",a="Полювання дає Орді змогу добувати дичину, заготовляти цінні шкури й знищувати верховних хижаків, що загрожують патрулям довкола Застави Розщепленого Дерева й сусіднім лісорубкам.",al={"навіщо полювання в ашенвалі","історія полювання","мета орди в ашенвалі"}},{q="Які ще застави має Орда в Ашенвалі?",a="Крім Застави Розщепленого Дерева, Орда тримає табір на далекому західному краю лісу, на Березі Зорам.",al={"бази орди в ашенвалі","застава зорам-стренд","застави ашенвалю"}},{q="Чи доведеться в цьому завданні битися?",a="Ні. Це завдання — лише підказка, що спрямовує вас безпечно пройти з Оргріммара через Пустки й доповісти Сенані Тандергарт.",al={"чи буде бій","чи щось вбивати","проста здача"}}},fp="18,314,17.436.0,22.438.0,48.176.0,27.143.0,27.198.0,42.177.0,53.129.0,35.156.0"}
P.entries["quest:2359"] = {n="Вежа Клавена",s="«Вежа Клавена» — таємна операція SI:7 із проникнення, яку доручають розбійникам Альянсу у Вестфолі. Діючи за розвідданими Агента Кірнена, агенти мають поцупити ключ, пробратися до пильно охоронюваної застави Дефіас і викрасти зловісні документи, пов'язані з неприродними експериментами.",h="«Вежа Клавена» — таємна операція SI:7 із проникнення, яку доручають розбійникам Альянсу у Вестфолі.",kw={"вежа клавена","клавен мортвейк","агент кірнен","si:7","занзіл","вестфол","братство дефіас"},ang={["class:Rogue"]="Це таємне проникнення — визначальний обряд посвяти для розбійників Альянсу: воно вимагає майстерно володіти скритністю, кишеньковими крадіжками, зламуванням замків і вмінням користатися слабкими місцями ворога.",["faction:Alliance"]="Викриття змови Дефіас у вежі показує, що бунтівники — не просто ображені каменярі, а небезпечні змовники, готові знатися з тролями джунглів і темною алхімією, аби загрожувати королівству.",["race:Human"]="Людей-захисників Стормвінда жахає видовище колишніх співвітчизників, перетворених на бездумних мерців-трутнів у Вестфолі."},sec={{t="Засідка у Вестфолі",b="На південно-східному краю Вестфолу, біля річки й на північ від Кинджальних Пагорбів, здіймається самотній кам'яний шпиль, який захопило Братство Дефіас. Злодії й розбійники Братства — люди — звична річ на цих рівнинах, та після тижнів самотнього стеження Агент Кірнен помітив дивні зміни. Нещодавно сюди прибув химерний вантаж просто з темних лісів Сутінколісся — під охороною потворних, спотворених вартових, геть не схожих на звичайних грабіжників."},{t="Шпиль і вартовий із шипами",b="Вежею командує Клавен Мортвейк, а стережуть її дивно змінені вартові, що дихають важко й хрипко. Серед цих вартових, які ледве човгають, є кремезний зомбі, прошитий залізними шипами, — у нього Ключ від Вежі Дефіасу. Щоб викрасти ключ, потрібні тиша й спритність; маючи його, агент оминає наземну оборону, прослизає на верхні поверхи твердині й відмикає скриню із Сутінколісся, замкнену на висячий замок."},{t="Зілля Занзіла",b="Особистий щоденник Клавена Мортвейка, знайдений у скрині, розповідає про похмурий союз Дефіас, Венчурної Компанії та тролів джунглів Стренглторна. Записи свідчать: знахар Занзіл відкрив алхімічну отруту, здатну піднімати бездумних, слухняних мерців-трутнів. Для Майстра Матіаса Шоу й SI:7 це відкриття оголює дедалі ширші амбіції Дефіас — і робить добре знання отрут обов'язковим для агентів служби."}},faq={{q="Де розташована Вежа Клавена?",a="Вежа Клавена стоїть на південно-східному краю Вестфолу, біля річки й на північ від Пагорбів Кинджала. Це надійний, укріплений притулок Братства Дефіас.",al={"місце вежі клавена","де вежа клавена","вежа дефіас у вестфолі"}},{q="Хто така Агент Кірнен?",a="Агент Кірнен — агентка розвідки Стормвінда, SI:7. Тижнями вона потай стежить за Вежею Клавена з табору неподалік, відстежуючи дивні вантажі й готуючи проникнення.",al={"агент кірнен","хто дає вежу клавена","хто розбійник у вестфолі"}},{q="Чим незвичні вартові у Вежі Клавена?",a="На відміну від звичайних бандитів-людей з Дефіас, вежу стережуть мутовані трутні-нежить. Це безвольні робітники, створені незвичним алхімічним варивом, яке привозять у Вестфол.",al={"чому вартові зомбі","вартові вежі клавена","що за вартові вежі"}},{q="Звідки в Дефіас слуги-нежить?",a="Дефіас роздобули особливе отруйне вариво, яке зготував знахар-троль з джунглів Занзіл у Долині Стренглторну. Через оборудки за участю Венчурної Компанії цю отруту ввезли, щоб перетворювати живих на слухняних трутнів.",al={"звідки зомбі в дефіас","чому в дефіас нежить","занзіл дефіас"}},{q="Хто такий Клавен Мортвейк?",a="Клавен Мортвейк — високопоставлений наглядач Дефіас у вежі. Він приймав темні вантажі із Сутінколісся й вів особистий щоденник, де описував їхню зловісну алхімію.",al={"клавен мортвейк лор","хто такий клавен мортвейк","клавен"}},{q="Чому Матіаса Шоу цікавить здобутий щоденник?",a="Майстрові Матіасові Шоу потрібні дієві відомості про союзи Дефіас і небезпечних чужоземних агентів. Дізнавшись, що тролі Занзіла можуть творити нежиття отрутою, SI:7 усвідомлює нову серйозну загрозу для Стормвінда й мусить ретельно навчати своїх агентів мистецтва отрут.",al={"чому шоу хоче щоденник","si7 отрута занзіла","матіас шоу клавен"}}},fp="14,279,22.463.0,30.420.1,19.466.2,32.172.0,21.203.0,48.205.1,41.233.1,23.189.0,55.291.1"}
P.entries["quest:237"] = {n="На захист королівських земель",s="Це військове доручення Горянина Ґравелґоу — зупинити наступ трогів у південному Лох Модані. Регулярні дворфійські сили зайняті в далеких походах Альянсу, тож місцеві застави мусять покладатися на добровольців, які винищать небезпечних черепотовчів і провидців Кам'яного Уламка, перш ніж ті заполонять Долину Королів.",h="Це військове доручення Горянина Ґравелґоу — зупинити наступ трогів у південному Лох Модані.",kw={"на захист королівських земель","горянин ґравелґоу","долина королів","троги","кам'яний уламок","підкріплення"},ang={["faction:Alliance"]="Це доручення оголює високу ціну ширшої війни Альянсу: заради далеких земель рідні краї самих членів союзу лишилися беззахисними перед місцевими загрозами.",["race:Dwarf"]="Для дворфа захист Долини Королів — особиста справа: ця земля вшановує найвеличніших правителів Айронфорджа, і бачити, як її топчуть троги, поки ваші родичі стікають кров'ю на далеких полях битв, — гірка пігулка."},sec={{t="Тонка оборона",b="Горяни, що стоять на південному перевалі до Дун Мороґу, розпорошені небезпечно тонко. Король Маґні Бронзбірд віддав значну частину дворфійського війська на ширший фронт Альянсу, тож на таких заставах, як сторожові вежі Долини Королів, бракує регулярної піхоти. Горянин Ґравелґоу покладається на сторонніх добровольців, які роблять зухвалі випереджальні вилазки в Долину Кам'яного Уламка й тримають підземних загарбників на відстані, поки місцеві залоги чекають на підкріплення, якого може й не бути."},{t="Шамани й громили Кам'яного Уламка",b="Троги Кам'яного Уламка — не бездумні звірі, що блукають навмання: їхні бойові ватаги діють злагоджено завдяки грубій силі та примітивній стихійній магії. Ґравелґоу націлюється на досвідчених бійців племені — черепотовчів — і на їхніх духовних проводирів, провидців. Знищення цих командирів передової збиває плем'я з ритму, кидає його південні табори в сум'яття й не дає здійняти масовий наступ на дорогу до Айронфорджа."},{t="Похмурі вісті з фронту",b="Коли ви доповідаєте про успіх, Ґравелґоу ділиться гіркою новиною: обіцяне дворфійське підкріплення не прийде. Тяжкі втрати на далекому фронті Альянсу вичерпали резерви Айронфорджа, і тепер захист серця королівства в Лох Модані цілком лежить на місцевих горянах і найманцях, що проходять повз."}},faq={{q="Де знайти Горянина Ґравелґоу?",a="Горянин Ґравелґоу стоїть на південній вартовій вежі при шляху через Долину Королів і стереже перевал, що сполучає Лох Модан з Дун Мороґом.",al={"місце ґравелґоу","де ґравелґоу","здати ґравелґоу"}},{q="Чому дворфам-горянам так бракує людей?",a="Король Маґні Бронзбірд відправив більшу частину постійного війська Айронфорджа на ширші фронти Альянсу за кордоном. Втрати деінде зростають, тож на прикордонних заставах, як-от у Лох Модані, лишилися мізерні залоги, змушені покладатися на мандрівних добровольців.",al={"чому дворфам бракує людей","де підкріплення","армія айронфорджа лох модан"}},{q="Де шукати черепотовчів і провидців Кам'яного Уламка?",a="Вони збираються переважно в південних таборах Долини Кам'яного Уламка, на схід від Долини Королів. Невеликий гурт можна знайти й на найпівнічнішому острові на Озері.",al={"місце черепотовчів","місце провидців кам'яного уламка","де троги"}},{q="Чому ціль — саме черепотовчі й провидці?",a="Черепотовчі — головні ударні загони племені Кам'яного Уламка, а провидці володіють грубою магією й керують нижчими трогами. Знищивши і тих, і тих, ви позбавляєте загарбників і сили, і містичного проводу.",al={"чому вбивати провидців","чому черепотовчі","цілі трогів"}},{q="Куди Ґравелґоу посилає далі?",a="Ґравелґоу посилає вас до Горянина Воллбанґа на південній вартовій вежі в Долині Королів — допомогти на наступному етапі оборони долини.",al={"наступне завдання ґравелґоу","хто такий воллбенг","після захисту королівських земель"}}},fp="30,343,14.495.0,34.424.0,27.317.1,39.164.0,48.259.0,61.203.0,48.228.0,35.163.1"}
P.entries["quest:2378"] = {n="Знайти Розтрощену Руку",s="Знайти Розтрощену Руку — завдання-мандрівка, що посилає обдарованих розбійників-Відступників із Галявин Тірісфалю за море, до Дуротару. За вказівкою скрадачів смерті посвячений вирушає в тіньове підчерево Оргріммара, щоб навчитися особливих мистецтв у клану Розтрощеної Руки.",h="Знайти Розтрощену Руку — завдання-мандрівка, що посилає обдарованих розбійників-Відступників із Галявин...",kw={"знайти розтрощену руку","розтрощена рука","шентул","меннет каркад","скрадачі смерті","тіньова розколина"},ang={["class:Rogue"]="Це завдання пов'язує місцевий вишкіл із ширшою злочинною й таємною мережею Орди й знайомить розбійників із головними наставниками підпілля в Калімдорі.",["faction:Horde"]="Це доручення показує, що співпраця в Орді сягає далі за піхотинців і шаманів передової: таємні служби Оргріммара й Андерсіті діють злагоджено.",["race:Undead"]="Для юних розбійників-Відступників це офіційний перехід від боротьби з рештками Погибелі в Лордероні до входження в серце Орди в Дуротарі."},sec={{t="Союз тіней",b="Хоч Відступники плекають власний таємний орден — скрадачів смерті, — їхній союз з Ордою відкриває шляхи до співпраці в темніших мистецтвах. Меннет Каркад, побачивши, як розбійник довів свою вартість у Галявинах Тірісфалю, розуміє, що тому потрібна ширша наука. Він посилає обдарованих тіньових агентів шукати Розтрощену Руку в Оргріммарі, спираючись на тихе партнерство між нежиттю Лордерону й оркською гільдією вбивць у Калімдорі."},{t="У Тіньову Розколину",b="Мандрівка закінчується глибоко в Тіньовій Розколині — підземній печері під Оргріммаром, де чорнокнижники, розбійники й приборкувачі демонів займаються ремеслами, на які мешканці поверхні воліють не дивитися. Там чекає Шентул, наставник Розтрощеної Руки. Самою лише репутацією його не вразиш: суворий троль із неприхованим скепсисом оцінює новоприбулого агента-нежить, прагнучи перевірити, чи має цей посланець справжню хитрість, чи даремно перепливав Велике Море."}},faq={{q="Хто дає завдання «Знайти Розтрощену Руку»?",a="Завдання дає Меннет Каркад, наставник Скрадачів смерті у Кварталі Розбійників Андерсіті, коли розбійник доведе свої базові вміння в Галявинах Тірісфалю.",al={"хто дає знайти розтрощену руку","завдання меннета каркада","хто посилає в оргріммар"}},{q="Де знайти Шентула?",a="Шентул — у Тіньовій Розколині, темній ущелині під центральними шляхами Оргріммара.",al={"знайти шентула","місце шентула","де шентул в оргріммарі"}},{q="Як пов'язані Скрадачі смерті й Розтрощена Рука?",a="Скрадачі смерті — розвідувальна мережа й гільдія вбивць Відступників, а Розтрощена Рука виконує схожу таємну роль для Орди в Оргріммарі. Вони співпрацюють як офіційні союзники, ділячись поглибленим вишколом і таємними замовленнями між фракціями Орди.",al={"скрадачі смерті й розтрощена рука","розбійники відступників і орків","чому в оргріммар"}},{q="Чому Шентул називає мене нікчемою?",a="Розтрощена Рука понад усе цінує фізичну стійкість і безжальну хитрість. Шентул постійно ображає й применшує новачків, щоб збити з них пиху й перевірити, чи вистачить їм рішучості витримати суворий вишкіл убивці.",al={"діалог шентула","чому шентул злий","текст завершення шентула"}},{q="Що буде, коли дістатися Шентула?",a="Шентул одразу береться за агента: пропонує завдання «Зандо'зан», а згодом посилає на південь до Раджета на практичні польові операції в Пустках.",al={"що після знайти розтрощену руку","наступне завдання після шентула","ланцюжок розтрощеної руки"}},{q="Чи можуть отримати це завдання розбійники не з Відступників?",a="Ні. «Знайти Розтрощену Руку» — варіант для Відступників, який дають Скрадачі смерті. Розбійники-орки й тролі в Дуротарі отримують схоже перехідне завдання — «До Оргріммара!».",al={"розбійник-орк знайти розтрощену руку","версія тролів","інший шлях до оргріммара"}}},fp="23,266,19.462.0,24.474.0,44.169.0,26.105.0,74.297.0,38.228.0,37.178.0,39.189.0"}
P.entries["quest:2379"] = {n="Зандо'зан",s="Це доручення скеровує обдарованих розбійників Орди відрекомендуватися Зандо'занові глибоко в Тіньовій Розколині Оргріммара. Посланий наставником Шентулом, посвячений робить перші кроки в таємні лави й заборонені прийоми Розтрощеної Руки.",h="Це доручення скеровує обдарованих розбійників Орди відрекомендуватися Зандо'занові глибоко в Тіньовій...",kw={"зандо'зан","шентул","розтрощена рука","тіньова розколина","розбійник","посвята"},ang={["class:Rogue"]="Це завдання знаменує ваш офіційний вступ до таємного апарату Розтрощеної Руки: з невишколеного бійця на ножах ви стаєте визнаним агентом Орди.",["faction:Horde"]="Хоч вождь часто говорить про честь і лобову атаку, Розтрощена Рука бере на себе вкрай потрібне шпигунство й таємну брудну роботу, що вберігає молоду Орду від невидимих загроз."},sec={{t="Прогулянка в тінь",b="Оргріммар може здаватися фортецею грубої сили й бойової дисципліни, але його правителі знають, що самими м'язами не виграти кожної війни. У підземному мороці Тіньової Розколини діє Розтрощена Рука — таємна гільдія, що веде для Орди шпигунство, диверсії й крадіжки. Коли наставник розбійників Шентул вирішує, що посвячений досить обдарований, він посилає його просто до Зандо'зана на спеціальний вишкіл агента."},{t="Довести свою вартість",b="Зандо'зан не роздає поваги кожному зеленому розбійникові, що забрів до печери. Прийти до нього — означає офіційно розпочати посвяту в тонші таємні мистецтва, і почати з делікатних умінь — потайливості, хитрощів і крадіжки. Зустріч із Зандо'заном перекидає місток від грубих вуличних кишенькових злодіїв до організованих розвідників і готує розбійника до складної роботи в полі, далеко від безпеки червоних мурів столичного каньйону."}},faq={{q="Хто такий Зандо'зан?",a="Зандо'зан — наставник розбійників і куратор Розтрощеної Руки, що живе в підземній Тіньовій Розколині Оргріммара. Він оцінює новобранців і навчає їх практичного скрадання, зламу й агентського ремесла.",al={"зандо'зан","хто такий зандо'зан","зандо'зан тіньова розколина"}},{q="Чому Шентул посилає розбійників до Зандо'зана?",a="Шентул бачить, коли молодий розбійник переріс прості бійки й потребує особливого вишколу як агент Розтрощеної Руки. Зандо'зан веде уроки зламу й роботи із замками, без яких не обійтися в таємних польових операціях.",al={"чому говорити з зандо'заном","шентул зандо'зан","мета завдання"}},{q="Що таке Розтрощена Рука в Оргріммарі?",a="Колись це був жорстокий орчий клан з Дренору, відомий обрядовим самокалічінням, а в Дуротарі Розтрощена Рука стала таємною розвідкою й службою вбивств Орди. Вони діють з тіней Оргріммара: шпигують, орудують отрутами, розвідують.",al={"що таке розтрощена рука","розтрощена рука оргріммар","розбійники орди розтрощена рука"}},{q="Куди веде цей ланцюжок навчання далі?",a="Коли ви з'явитеся до Зандо'зана, він посилає вас до Раджета на узбережжі Пусток — до гоблінського зв'язкового на ім'я Вреникс, і там починається практична польова робота з відмикання замків.",al={"наступне завдання","що після зандо'зана","вренікс із раджета"}},{q="Де знайти Зандо'зана?",a="Він ховається в Тіньовій Розколині — глибокій мережі печер, видовбаних під центром Оргріммара, де подалі від денного світла збираються чорнокнижники, жерці тіні й агенти-розбійники.",al={"місце зандо'зана","де зандо'зан","як знайти зандо'зана"}},{q="Чому Зандо'зан перепрошує, коли ми зустрічаємося?",a="Мабуть, до вашого приходу Зандо'зан мав сумніви й не вірив у вашу витримку. Побачивши вас перед собою, готових до навчання, він мусить визнати вашу відданість і відмовитися від початкового скепсису.",al={"чому зандо'зан перепрошує","діалог завершення зандо'зана"}}},fp="9,249,23.461.0,19.441.0,17.220.0,47.240.0,40.273.0,41.190.1,27.182.0,45.195.0"}
P.entries["quest:2380"] = {n="До Оргріммара",s="Цей вступний виклик посилає розбійника Орди з Гострого Пагорба до столиці. За наказом Каплака посвячений спускається під землю, у Тіньову Розколину, щоб з'явитися до Шентула й глибше увійти в мережу Розтрощеної Руки.",h="Цей вступний виклик посилає розбійника Орди з Гострого Пагорба до столиці.",kw={"до оргріммара","каплак","шентул","тіньова розколина","розтрощена рука","розбійник"},ang={["class:Rogue"]="Це доручення знаменує ваш офіційний вступ до таємної мережі столиці: від грубих прикордонних бійок ви переходите до мистецтва отрут, крадіжок і обману під наглядом Шентула.",["faction:Horde"]="Тихе невдоволення Шентула показує тертя між новим почесним шляхом Тралла й тіньовими рештками старих кланових організацій, що виживають під Оргріммаром."},sec={{t="Виклик у тінь",b="Набивши руку по всьому Дуротару, розбійники-початківці зрештою привертають увагу впливовіших кураторів. У Гострому Пагорбі Каплак прямо визнає, що хист агента — хоч і неотесаний — помітили. Замість лишатися серед червоних скель, агента скеровують на північ, у печерні провулки Оргріммара."},{t="Під пильним оком Тралла",b="Зустріч із Шентулом у підземній Тіньовій Розколині відкриває глибшу напругу під засадничими ідеалами Орди. Шентул не приховує, що пильно стежить за політичними реформами Вождя Тралла. Для Розтрощеної Руки груба сила й відкритий спротив ніколи не вбережуть її інтересів: виживання й вплив вимагають терпіння, хитрощів і витонченого обману."}},faq={{q="Хто посилає мене на це завдання?",a="Каплак, наставник розбійників на Гострому Пагорбі, передає виклик, переконавшись, що ваші вміння привернули увагу начальства в Оргріммарі.",al={"хто дає завдання","хто дає до оргріммара","завдання каплака"}},{q="Де знайти Шентула?",a="Шентул — у Тіньовій Розколині, похмурому підземному кварталі глибоко під Оргріммаром, де збираються розбійники, чорнокнижники й інші вигнанці.",al={"місце шентула","де шентул","шентул тіньова розколина"}},{q="Які наміри Розтрощеної Руки в Оргріммарі?",a="Розтрощена Рука — гільдія розвідки й убивств у складі Орди. Формально вона частина нової столиці, але ватажки на кшталт Шентула насторожено ставляться до шляхетних реформ Тралла й роблять ставку на скрадання, щоб зберегти вплив і вижити.",al={"мотиви розтрощеної руки","чому розтрощена рука в оргріммарі","розтрощена рука тралл"}},{q="Чому мене посилають саме на цьому етапі?",a="Агентів-новачків, які проявили себе в простій розвідці й сутичках, залучають до офіційніших обов'язків гільдії — починаючи з відмикання замків і таємної польової роботи, яку дають у столиці.",al={"розбійник шістнадцятого рівня","чому йти в оргріммар зараз","виклик тренування розбійників"}},{q="Чим це завдання відрізняється від «Знайти Розтрощену Руку»?",a="Обидва — вступні завдання-підказки, що ведуть розбійників до Шентула в Оргріммар; залежно від того, де ви навчаєтеся чи берете накази, ви отримуєте одне або друге, щоб рушити тим самим ланцюжком навчання.",al={"до оргріммара проти знайти розтрощену руку","інше завдання-хлібні крихти"}},{q="Що буде, коли з'явитися до Шентула?",a="Шентул перевіряє вашу вправність і веде далі ланцюжком, знайомлячи із зв'язковими на кшталт Зандо'зана, а згодом — з таємною роботою за участю гоблінських знайомих у Раджеті.",al={"наступне завдання після до оргріммара","що дає шентул"}}},fp="13,301,24.353.0,27.382.1,27.157.0,25.157.0,49.250.0,47.188.0,54.189.0,41.174.0"}
P.entries["quest:2381"] = {n="Пограбування грабіжників",s="Це обряд посвяти, який доручає гоблін Вреникс Жалюгідний у Раджеті: він випробовує молодого розбійника Орди в сутичці з Флібустьєрами Південних морів. Пробравшись на піратський корабель «Лезо Припливу», посланці мусять оминути головорізів, зламати замки в трюмі й знешкодити жахливого пернатого охоронця за допомогою гоблінської техніки, щоб здобути Скарб Південних Морів.",h="Це обряд посвяти, який доручає гоблін Вреникс Жалюгідний у Раджеті: він випробовує молодого розбійника Орди в...",kw={"пограбування грабіжників","вреникс жалюгідний","скарб південних морів","поллі","будяковий чай","розбійник"},ang={["class:Rogue"]="Цей обряд посвяти вчить головного мистецтва — зламувати замки під тиском — і винагороджує цінним рецептом Будякового чаю, тож це незамінна віха для кожного агента на службі Орди.",["faction:Horde"]="Розтрощена Рука використовує нейтральні гоблінські зв'язки в Раджеті, щоб випробовувати майбутніх польових агентів у сутичках із Флібустьєрами Південних морів, які загрожують узбережжю Пусток.",["profession:Cooking"]="Завдання дає кулінарний рецепт Будякового чаю, і розбійники, що мають хист до кухні, можуть заварювати власні бадьорливі напої з простих трав і води."},sec={{t="Випробування скритності й сталі",b="Для молодого агента Розтрощеної Руки груба сила нічого не варта без спритності. Вреникс Жалюгідний, гоблінський посередник у Раджеті, влаштовує польове випробування. Він посилає розбійників на південь випаленим сонцем узбережжям Пусток до бухти, де стоїть на якорі «Лезо Припливу» — корабель Флібустьєрів Південних морів. Завдання лише здається простим: непомітно пробратися на борт, проникнути в піратське лігво, де вишколюють власних кишенькових злодіїв, зламати скрині в глибокому трюмі й принести їхню цінну здобич."},{t="Поллі й штуковина",b="Щоб дістатися до скарбу, спритних пальців замало. Вреникс попереджає, що попередніх злодіїв йому повертали по частинах — здебільшого через охоронця найнижчого трюму: напрочуд люту папугу на ім'я Поллі. Проти цього крилатого жаху Вреникс дає дослідний пристрій, відомий як Е.К.А.К. Якщо кинути цю штуковину в лютого птаха, щойно зламано піратську скриню, вона дезорієнтує й послаблює звіра — і неминучий смертний вирок стає двобоєм, який можна виграти."}},faq={{q="Хто такий Вреникс Жалюгідний?",a="Вреникс Жалюгідний — гоблін-розбійник і зв'язковий у нейтральному порту Раджет. Співпрацюючи з агентами Розтрощеної Руки з Оргріммара, він випробовує молодих злодіїв, посилаючи їх на піратську територію вправлятися у відмиканні замків і повертати вкрадену здобич.",al={"вреникс","хто такий вреникс","гоблін-розбійник раджета"}},{q="Де стоїть «Лезо Припливу»?",a="«Лезо Припливу» стоїть на якорі на південь від Раджета, на східному узбережжі Пусток, у схованці Флібустьєрів Південних морів. Корабель — і база, і навчальне лігво для піратських шибеників.",al={"місце лезо припливу","де піратський корабель","де пірати південних морів"}},{q="Що таке Е.К.А.К. і як ним користуватися?",a="Е.К.А.К. — експериментальна гоблінська штуковина, яку видає Штукотронний Апарат Ренікса. Її застосовують проти Поллі — смертоносного велетенського папуги, що стереже Скарб Південних Морів у череві «Леза Припливу», — і вона так послаблює звіра, що його можна здолати.",al={"що таке е.к.а.к.","е.к.а.к.","як перемогти поллі"}},{q="Чому місце для відмикання замків на кораблі таке важливе?",a="Друга палуба «Леза Припливу» — навчальна кімната піратів Південних Морів. Там стоять скриньки, що знову з'являються, і розбійники можуть потренуватися відмикати замки в польових умовах, перш ніж братися за головну скриню внизу.",al={"відмикання замків","корабель для тренування","відмикання скринь у пустках"}},{q="Чому це доручення таке важливе для розбійників?",a="Пограбування доводить вартість розбійника мережі Розтрощеної Руки. Як вашу частку, Вреникс дає вам таємний рецепт Будякового чаю — безцінного трав'яного напою, що швидко відновлює бойову енергію розбійника.",al={"чому важливо для розбійників","чай з будяка розбійник","нагорода розбійника"}},{q="Хто така Поллі?",a="Поллі — злющий сторожовий папуга Флібустьєрів Південних морів у нижньому трюмі «Леза Припливу». Якщо не послабити птаха гоблінською технікою, він смертельно небезпечний для недосвідчених зломщиків.",al={"поллі","гігантський папуга","бос лезо припливу"}}},fp="25,348,27.537.0,19.489.1,27.264.0,32.195.0,40.257.0,52.248.0,40.228.0,13.214.0"}
P.entries["quest:2382"] = {n="Ренікс із Раджета",s="Це доручення для розбійників Орди веде агентів з Оргріммара до гоблінського порту Раджет. Навіжений троль Зандо'зан посилає їх на південь допомогти гоблінові з сумнівною славою — Врениксові Жалюгідному.",h="Це доручення для розбійників Орди веде агентів з Оргріммара до гоблінського порту Раджет.",kw={"вреникс жалюгідний","раджет","зандо'зан","пророцтво","розтрощена рука","розбійник"},ang={["class:Rogue"]="Ця мандрівка — важливий крок у вишколі розбійника Орди: вона виводить молодих агентів із безпечного Оргріммара на нейтральну піратську територію.",["faction:Horde"]="Розтрощена Рука має очі й вуха за межами Дуротару й часто покладається на нейтральні порти, як-от Раджет, щоб виконувати делікатні контракти."},sec={{t="Пророк у тіні",b="У звивистих щілинах Тіньової Розколини в Оргріммарі гільдія розбійників провадить свої справи здебільшого непомітно. Агентів, що приходять до Зандо'зана, зустрічають несамовиті марення й зловісні пророцтва — зокрема темні видіння про те, як Вождя Тралла вб'ють отрутою й клинком. Замість пояснити своє пророцтво, дивакуватий троль хутко відсилає агентів до портового містечка Раджет у Пустках."},{t="Раджетський вирішувач проблем",b="Нейтральний порт Раджет на узбережжі на схід від Перехрестя дає притулок усіляким пройдисвітам, найманцям і механікам. У цьому гамірному пристановищі й діє Вреникс Жалюгідний, хоча на дивацтва Зандо'зана в нього мало терпіння. За словами Вреникса, попередні новобранці троля скінчили погано — у водах затоки, що кишать хижаками."}},faq={{q="Хто посилає до Раджета?",a="Зандо'зан, троль з Розтрощеної Руки в Тіньовій Розколині Оргріммара, посилає вас із цим дорученням, перед тим вибовкавши якісь дивні видіння.",al={"хто дає завдання","хто посилає до раджета","зандо'зан"}},{q="Хто такий Вреникс Жалюгідний?",a="Вреникс Жалюгідний — гоблінський зв'язковий з портового містечка Раджет. Він опікується таємними дорученнями й механічним припасом для розбійників, що діють у Пустках.",al={"хто такий вреникс","вреникс раджет","особа вренікса"}},{q="Що сталося з агентами, яких посилали до мене?",a="За словами Вреникса, попередні п'ятеро агентів, яких надіслав Зандо'зан, провалили свої доручення й пішли на корм акулам біля узбережжя Раджета.",al={"попередні розбійники","їжа для акул","інші новобранці"}},{q="Що Зандо'зан казав про Тралла?",a="Зандо'зан запевняє, що бачив видіння, ніби Траллові встромили в спину отруєний кинджал, але швидко замовкає й переводить розмову на інше.",al={"пророцтво тралла","тралла отруєно","видіння зандо'зана про тралла"}},{q="Де розташований Раджет?",a="Раджет — на східному узбережжі Пусток, просто на схід від Перехрестя. З Дуротаром його сполучають шляхи, що ведуть на південь від Річки Південної Люті.",al={"де раджет","знайти раджет","місце раджета"}},{q="Що далі після зустрічі з Врениксом?",a="Привітавшись, Вреникс дає вам завдання «Пограбування грабіжників» — треба проникнути до Флібустьєрів Південних морів на узбережжі на південь від Раджета.",al={"наступне завдання","після вренікса","продовження раджета"}}},fp="17,236,24.403.0,24.363.0,25.146.0,27.167.0,47.147.0,50.159.0,25.164.0,37.155.1"}
P.entries["quest:239"] = {n="Гарнізону Вестбрука потрібна допомога!",s="Маршал Дуґан відряджає вільних шукачів пригод на захід, до Гарнізону Вестбрук — застави, що стереже кордон Лісу Елвінн із Вестфолом. Армія Стормвінда розкидана по всьому королівству, тож Помічник Рейнер і його вартові без регулярних підкріплень опиняються під дедалі більшим тиском агресивних гнолів Річколапів і бродячих злодіїв.",h="Маршал Дуґан відряджає вільних шукачів пригод на захід, до Гарнізону Вестбрук — застави, що стереже кордон...",kw={"гарнізон вестбрук","помічник рейнер","гноли","річколапи","вестфол","ліс елвінн","маршал дуґан"},ang={["faction:Alliance"]="Добровольці Альянсу беруть тут на себе роль регулярних солдатів — виконують чорну роботу, щоб ключові землі не скотилися в цілковитий хаос.",["race:Human"]="Для людей Стормвінда цей наказ — тривожна ознака занедбаності королівства: він на власні очі показує, якою тонкою стала оборона корони після зникнення Короля."},sec={{t="Розтягнуте прикордоння",b="Гарнізон Вестбрук позначає західний край Лісу Елвінн — саме там, де обжиті ліси поступаються неспокійним рівнинам Вестфолу. Що зухвалішими стають загони гнолів і бандити вздовж річок і західних доріг, то наполегливіше невеликий гарнізон застави благає про підкріплення. Однак ані Маршал Дуґан, ані урядники Ґолдшира не мають вільних професійних солдатів Стормвінда, тож місцевим командирам лишається тільки наймати мандрівних найманців і шукачів пригод."},{t="Загроза з-за струмка",b="Головна небезпека для Помічника Рейнера та його людей — зграя гнолів Річколапів, чиї загони нападають на подорожніх і сусідні садиби. Діючи на прикордонні між Елвінном і Вестфолом, ці гноли скористалися з того, що Стормвінд відволікли політичні й військові клопоти, і просунулися вглиб обжитих земель. Гарнізон Вестбрук — остання лінія оборони, яка не дає їм безкарно гуляти серцем лісу."}},faq={{q="Чому Стормвінд не може послати до Гарнізону Вестбрук регулярних солдатів?",a="Постійне військо Стормвінда вкрай розпорошене по багатьох рубежах. Король Варіан Рінн зник, королівство роздирають внутрішні чвари, тож верховне командування не хоче чи не може посилати регулярних солдатів на сільські застави, і містечкові маршали на кшталт Дуґана мусять покладатися на вільних добровольців.",al={"чому немає військ стормвінда","чому шукачі пригод","де армія стормвінда"}},{q="Де розташований Гарнізон Вестбрук?",a="Гарнізон стоїть на західному краю Лісу Елвінн. Ідіть головним шляхом на захід від Ґолдширу повз невеликий струмок — укріплена вежа буде праворуч, перед самим кордоном із Вестфолом.",al={"місце гарнізону вестбрук","як дістатися вестбрука","де помічник рейнер"}},{q="Які загрози непокоять гарнізон?",a="Помічник Рейнер відбиває невпинні набіги гнолів-Річколапів, а ще дедалі більше злодіїв і бандитів, що діють у прикордонні між Вестфолом і Лісом Елвінн.",al={"що нападає на вестбрук","чому рейнеру потрібна допомога","хто нападає на гарнізон вестбрука"}},{q="Хто такий Помічник Рейнер?",a="Помічник Рейнер — офіцер Стормвінда, що командує Гарнізоном Вестбрук. Йому доручено тримати західний кордон, і через гострий брак офіційних підкріплень він мусить звертатися до добровольців і найманців.",al={"лор рейнера","помічник рейнер","хто такий рейнер"}},{q="Що буде, коли з'явитися до Помічника Рейнера?",a="Помічник Рейнер одразу залучає вас до боротьби з місцевими гнолами-Річколапами й призначає винагороду за їхні нашийники, щоб проріджити їхні лави й захистити прикордонний шлях.",al={"що далі","ланцюжок вестбрука","завдання рейнера"}},{q="Чому гноли пруть у Ліс Елвінн?",a="Гноли-Річколапи облаштували табори вздовж річок, що відділяють Елвінн від Вестфолу. Скориставшись тим, що вояків на кордоні поменшало, вони так осміліли, що нападають на торговельні шляхи й просуваються до ферм у глибині Елвінну.",al={"гноли ріверпо елвінн","чому тут гноли","проблема гнолів"}}},fp="30,345,25.500.0,27.446.0,64.313.0,36.200.0,40.188.0,21.244.0,46.162.0,46.249.0"}
P.entries["quest:2399"] = {n="Пророслі віяла",s="Після ботанічних дослідів Деналана біля Озера Ал'Амет посаджене насіння листя вкорінюється й розквітає. Ця тиха мить — успішний урожай у розумінні дивної й життєво важливої рослинності Тельдрассила. Мандрівники, що оглядають грядки, можуть на власні очі побачити стрімкий ріст.",h="Після ботанічних дослідів Деналана біля Озера Ал'Амет посаджене насіння листя вкорінюється й розквітає.",kw={"пророслі віяла","мерехтливе листя","деналан","озеро ал'амет","грядка","ботаніка","тельдрассил"},ang={["class:Druid"]="Друїди, що спостерігають за грядкою Деналана, можуть оцінити тиху рівновагу природи, бачачи, як життя квітне під уважним доглядом навіть посеред дедалі більших небезпек Тельдрассила.",["profession:Herbalism"]="Дослідження Деналана відбивають практичне мистецтво збирання й вивчення неповторної рослинності Тельдрассила і показують, як швидко тутешнє насіння пристосовується до доглянутого ґрунту.",["race:NightElf"]="Догляд за щойно пророслою рослинністю відбиває обов'язок калдореїв стежити за життям, що вкорінюється на їхньому молодому Світовому Дереві, і плекати його."},sec={{t="Сад біля Озера Ал'Амет",b="Сховавшись біля Озера Ал'Амет, ботанік Деналан присвятив себе опису незвичайної рослинності Тельдрассила. Коли він посіяв насіння, здобуте з таємничого мерехтливого листя, ґрунт швидко дав результат. У його доглянутій грядці з багатого суглинку вистрілюють дивні, тремтливі віяла листя, що просяться, аби їх зібрали й дослідили."},{t="Дивна рослинність Світового Дерева",b="Тельдрассил молодий, неосяжний і повниться стрімким природним розвитком, який і захоплює, і тривожить травників — нічних ельфів. Мерехтливе листя та його пророслі пагони — приклад того, як швидко життя хапається за віття великого дерева, натякаючи на могутню, але непередбачувану життєву силу, вплетену в ґрунт острова."}},faq={{q="Що таке пророслі віяла?",a="Це дорослі рослини, що проросли з насіння, яке Деналан посіяв у своєму таборі біля озера. Виплекані з мерехтливих віял, знайдених в інших куточках Тельдрассила, ці дивні рослини тремтять від енергії, коли їх пора збирати.",al={"пророслі віяла","що це за рослини","віяла деналана"}},{q="Де Деналанів сад?",a="Деналан тримає сад і дослідницький табір на східному березі Озера Ал'Амет, на південний схід від Доланаара на Тельдрассилі.",al={"місце деналана","де деналан","сад біля озера веллспрінг"}},{q="Навіщо Деналан садить ці віяла?",a="Деналан вивчає дивний і стрімкий ріст рослин Тельдрассила. Висіваючи насіння в підготовлений ґрунт, він досліджує їхню природу й перевіряє, чи мають вони корисні цілющі чи лікарські властивості.",al={"навіщо садити віяла","експеримент деналана","призначення віял"}},{q="Чи небезпечні пророслі віяла?",a="Ні. На відміну від деяких зіпсованих чи ворожих рослин деінде на гіллі Тельдрассила, ці пророслі віяла — нешкідливі ботанічні зразки, що чекають, поки їх зірвуть.",al={"чи віяла небезпечні","чи віяла нападають","чи рослина шкідлива"}},{q="Що йде перед цим завданням?",a="Спершу шукачі пригод знаходять у дикій глушині Тельдрассила мерехтливе віяло й приносять його Деналану, а той висіває насіння у своїй грядці й чекає, поки воно проросте.",al={"передумова пророслих віял","яке завдання спершу"}},{q="Чому віяла тремтять?",a="Віяла тремтять, чекаючи, поки їх зірвуть. Що спричиняє цей рух, джерело не пояснює.",al={"тремтячі віяла","чому вони тремтять"}}},fp="19,281,25.337.0,35.336.0,29.224.0,34.120.0,36.220.0,34.166.0,29.166.0,26.96.0"}
P.entries["quest:24"] = {n="Голова Шадумбри",s="Це завдання — доказ перемоги над Шадумброю, сумно відомою лютою нічним шаблезубом, що чатує на західних стежках Ашенвалю. Принісши відтяту голову звіра Сенані Тандергарт на Заставу Розщепленого Дерева, ви пройдете важливе випробування Полювання Ашенвалю й убезпечите шляхи до Зорамського Узмор'я.",h="Це завдання — доказ перемоги над Шадумброю, сумно відомою лютою нічним шаблезубом, що чатує на західних...",kw={"голова шадумбри","шадумбра","нічний шаблезуб","сенані тандергарт","полювання ашенваля","завдання"},ang={["class:Hunter"]="Вистежити й здолати невловиму нічного шаблезуба на кшталт Шадумбри — взірцеве випробування влучності, терпіння й уміння виживати в густому лісі.",["faction:Horde"]="Застава Розщепленого Дерева лишається відрізаною твердинею Орди; знищення місцевих загроз на кшталт Шадумбри тримає відкритими важливі шляхи постачання до Зорамського Узмор'я.",["race:Tauren"]="Для тауренів полювання на звіра такого гарту, як Шадумбра, шанує природний лад Земної Матері: це випробування вправності в двобої з верховним хижаком і водночас захист одноплемінників у дорозі."},sec={{t="Загроза західної дороги",b="Шадумбра — не звичайна хижачка серед височенних дерев Ашенвалю. Велика нічний шаблезуб чатувала в глушині на захід від Застави Розщепленого Дерева, полюючи на розвідників і гінців Орди, що намагалися дістатися Зорамського Узмор'я. Її швидкість, потайність і несамовита лють робили піші подорожі небезпечними, і захисники Розщепленого Дерева щоразу нервували, коли дозори рушали на захід."},{t="Доказ полювання",b="У межах Полювання Ашенвалю тауренська мисливиця Сенані Тандергарт кидає звитяжцям Орди виклик: вистежити й уполювати верховних хижаків лісу. Голова Шадумбри — не просто похмурий показ звитяги: це незаперечний доказ того, що дороги стали безпечнішими, а мисливець подолав одного з найсмертоносніших споконвічних хижаків Калімдору."}},faq={{q="Хто така Шадумбра?",a="Шадумбра — надзвичайно лютий нічний шаблезуб, що никав лісами на захід від Застави Розщепленого Дерева. Відома засідками на мандрівників, які йшли довгим шляхом до узбережжя, вона вважалася одним з найнебезпечніших звірів Ашенвалю.",al={"що таке шадумбра","шадумбра лор","хто та кішка"}},{q="Навіщо Сенані Тандергарт голова?",a="Сенані Тандергарт керує Полюванням в Ашенвалі із Застави Розщепленого Дерева. Голова — і традиційний трофей вражаючого полювання, і підтвердження того, що загрозу для мандрівників на захід усунуто.",al={"навіщо голова","трофей сенані тандергарт","доказ полювання в ашенвалі"}},{q="Яке місце це посідає в Полюванні в Ашенвалі?",a="Це одне з головних випробувань, що починаються після того, як ви візьмете «Полювання в Ашенвалі». Убивши Шадумбру разом з іншими великими звірами лісу, як-от Урсанґусом і Шарпталоном, ви здобуваєте остаточне визнання й завдання «Полювання завершено».",al={"що таке полювання в ашенвалі","лінія полювання","наступне завдання полювання"}},{q="Чому для Орди важливо позбутися цього звіра?",a="Застава Розщепленого Дерева залежить від розвідників і гінців, що ходять на захід до табору Орди — Застави Зорам'гар на Березі Зорам. Хижа вдача Шадумбри була постійною загрозою для ордійців, що ходили пішки диким лісом.",al={"чому орді важливо","небезпека дороги зорам-стренд","безпека застави розщепленого дерева"}},{q="Де знайти Шадумбру?",a="Шадумбра скрадається лісами на захід від Застави Розщепленого Дерева, никаючи між деревами від шляху до давніх руїн нічних ельфів, розкиданих по центральному й західному Ашенвалю.",al={"місце шадумбри","де шадумбра","знайти шадумбру"}},{q="Чи в союзі Шадумбра з нічними ельфами?",a="Ні. Нічних шаблезубів ельфи часто приручають і шанують, але Шадумбра — дикий, лютий жах лісу, що діє суто з хижацького інстинкту й загрожує кожному, хто ступить на її землю.",al={"чи шадумбра улюбленець","улюбленець вартових","шадумбра нічний ельф"}}},fp="16,309,28.368.0,17.354.0,18.236.0,43.224.0,44.236.0,50.233.0,29.180.0,41.202.0"}
P.entries["quest:240"] = {n="Повернення до Джіттерса",s="«Повернення до Джіттерса» завершує кулінарне доручення Шеф-кухаря Ґруала в Сутінколіссі. Приготувавши свої сумнозвісні «крабові» котлети зі слизьких ніг місцевих отруйних павуків-тенетників, Ґруал посилає вас назад до голодного, переляканого самітника на Воронячому Пагорбі. Доставлена страва нарешті вгамовує відчайдушний голод Тремтія.",h="«Повернення до Джіттерса» завершує кулінарне доручення Шеф-кухаря Ґруала в Сутінколіссі.",kw={"повернення до джіттерса","тремтій","шеф-кухар ґруал","крабові котлети","воронячий пагорб","кулінарія"},ang={["faction:Alliance"]="Мізерний і незвичний харч Даркшира показує, наскільки місто відрізане від ширших шляхів постачання Стормвінда: місцевим лишається покладатися на те, що повзає в тіні.",["profession:Cooking"]="Уміння Шеф-кухаря Ґруала обернути слизькі ноги отруйних павуків на їстівні котлети свідчить про вперту винахідливість, якої прикордоння вимагає від кухарів."},sec={{t="Сумнівний делікатес",b="У Сутінколіссі бракує звичної худоби й морської живності, тож Шеф-кухар Ґруал із Таверни «Багряний Крук» імпровізує з тим, що дає зотлілий ліс. У його знаменитих Сутінкових Крабових Котлетах немає ані крихти справжнього краба: замість нього там слизькі ноги отруйних павуків-тенетників, що повзають лісом. Ґруал вважає це винахідливою кухнею; людина з делікатним шлунком, певно, подивилася б на це з жахом."},{t="Заспокоїти Тремтія",b="Тремтій днями сидить, зіщулившись, на Воронячому Пагорбі, цілком поглинутий страхом і паралізований жахіттями, що вигнали його з лісу. Знесилений переляком, він не може набратися відваги, щоб полювати чи шукати їжу, і порожній шлунок лише посилює його муки. Теплі котлети дарують тремтячому волоцюзі рідкісну мить полегшення — він надто голодний, щоб питати, якого це «краба» використав Шеф-кухар Ґруал."}},faq={{q="Що в Сутінкових Крабових Котлетах?",a="У Сутінколіссі крабів немає. Шеф-кухар Ґруал робить свої фірмові котлети з драглистих лап місцевих павуків-отрутоплетів, приправляючи їх так, щоб вони смакували, як звичайні котлети з морепродуктів.",al={"інгредієнти крабових котлет","з чого сутінкові крабові котлети","чи справжній краб"}},{q="Чи знає Тремтій, що котлети з павучого слизу?",a="Шеф-кухар Ґруал тримає свій кулінарний секрет при собі, а Тремтій надто голодний і наляканий, щоб розпитувати про рецепт. Він жадібно їх уминає, нічого не підозрюючи.",al={"чи тремтій знає","чи тремтій знає про павуків"}},{q="Чому Тремтій не міг сам роздобути їжу?",a="Після пережитого в диких лісах Сутінколісся Тремтія геть опанував страх. Скутий панікою, він не наважується відходити від своєї схованки на Воронячому Пагорбі й покладається на співчутливих мандрівників, щоб ті приносили йому харч.",al={"чому тремтій голодний","чому тремтій не полює"}},{q="Хто такий Шеф-кухар Ґруал?",a="Шеф-кухар Ґруал — кухар у Таверні «Багряний Крук» у Даркширі. У містечку, відрізаному тінями й звірами, він пускає в діло будь-які незвичні складники, які приносять збирачі, аби таверна не лишалася без їжі.",al={"роль шефа ґруала","кухар даркшира"}},{q="Де починається цей ланцюжок завдань?",a="Доручення починається з Тремтія на Воронячому Пагорбі, який просить допомогти з порожнім шлунком у завданні «Бурчання в животі Тремтія»; далі — полювання на павуків-отрутоплетів для Шеф-кухаря Ґруала, а тоді — повернення сюди з готовою стравою.",al={"як почати їжу тремтія","початок ланцюжка тремтія"}},{q="Чи оговтується Тремтій, коли поїсть?",a="Їжа вгамовує його голод і заслуговує вам його щиру вдячність, але не лікує глибокого душевного жаху. Він і далі тривожний, і його переслідують темні таємниці лісу.",al={"чи тремтій одужав","чи їжа допомагає тремтію"}}},fp="17,299,18.423.0,24.416.0,32.168.0,51.177.0,38.240.0,18.209.0,34.216.0,34.204.0"}
P.entries["quest:2438"] = {n="Смарагдовий Ловець Снів",s="Таллонкай Свіфтрут у Доланаарі просить шукачів пригод повернути дорогу родинну реліквію з його покинутої оселі в Селі Зоряного Вітерця. Смарагдовий Ловець Снів, подарований йому друїдським сторожем Ґероласом Талветреном, лишився там, коли споганені фурболги Вузлошкірів заполонили тихе поселення. Повернення цього амулета не дасть його лагідній магії природи потрапити в огидні руки.",h="Таллонкай Свіфтрут у Доланаарі просить шукачів пригод повернути дорогу родинну реліквію з його покинутої...",kw={"смарагдовий ловець снів","таллонкай свіфтрут","ґеролас талветрен","село зоряного вітерця","вузлошкіри","фурболги","доланаар"},ang={["class:Druid"]="Амулет — безпосередній витвір Ґероласа Талветрена, сторожа, що доглядає ваших сплячих родичів у Курганному Лігві Бан'етіл, тож його повернення — справа друїдської честі.",["faction:Alliance"]="Допомога вигнаним калдореям Доланаара зміцнює місцеву стабільність, поки Тельдрассил бореться зі скверною, що шириться серед племен фурболгів.",["race:NightElf"]="Зоряний Вітерець колись був тихим прихистком для вашого народу. Допомогти Таллонкаю повернути його спадок — маленький удар по безумству, що охоплює звірину Тельдрассила."},sec={{t="Друїдський талісман",b="Смарагдовий ловець снів — значно більше ніж оздобна дрібничка. Створений Ґероласом Талветреном, шанованим сторожем сплячих друїдів у Курганному Лігві Бан'етіл, амулет мав спрямовувати безтурботні течії Смарагдового Сну. Черпаючи цю чисту духовну силу, ловець снів дарує носієві спокій і удачу. Такі знаки надзвичайно рідкісні, і дістають їх лише небагато довірених, чиє життя сплетене з опікою над лісом."},{t="Втеча із Села Зоряного Вітерця",b="Донедавна Село Зоряного Вітерця було мирним поселенням серед віття Тельдрассила. Тихе життя скінчилося, коли тутешні фурболги Вузлошкірів піддалися несамовитому безумству й вигнали нічних ельфів з їхніх споконвічних осель. У жаху й сум'ятті евакуації Таллонкай був змушений лишити свій найдорожчий скарб у шухляді комода в південно-східній частині села, безсилий повернути його самотужки."},{t="Загроза скверни",b="Залишити осередок магії Смарагдового Сну в серці захопленого села — великий ризик. Вузлошкіри вже довели свою податливість до темних впливів, і артефакт, що пульсує силами Сну, легко можна споганити чи обернути на зброю. Безпечне повернення ловця снів віддає Таллонкаю частку спадку Зоряного Вітерця, перш ніж фурболги чи інші огидні мешканці встигнуть осквернити його незгаслу магію."}},faq={{q="Що таке Смарагдовий Ловець Снів?",a="Це рідкісний амулет, створений Ґероласом Талветреном, охоронцем друїдів у Курганному Лігві Бан'етіл. Ловець снів черпає енергію зі Смарагдового Сну й дарує тому, хто його носить, удачу й духовну гармонію.",al={"що таке ловець снів","лор ловця снів","смарагдовий ловець снів"}},{q="Чому ловця снів залишили в Селі Зоряного Вітерця?",a="Село Зоряного Вітерця блискавично захопили, коли місцеві фурболги-Вузлошкіри впали в шалене, зіпсоване скверною буйство. Таллонкай Свіфтрут мусив рятуватися втечею до Доланаара, залишивши дорогоцінну родинну реліквію в комоді своєї спальні.",al={"чому залишили","комод села зоряного вітерця","комод таллонкая"}},{q="Хто такий Таллонкай Свіфтрут?",a="Таллонкай — біженець з нічних ельфів, що нині мешкає в Доланаарі. Урятувавшись під час падіння Села Зоряного Вітерця, він шукає сміливців, які повернуться в захоплені руїни, щоб урятувати його родинні реліквії й уберегти друїдські святині.",al={"хто такий таллонкай","таллонкай свіфтрут"}},{q="Хто зробив ловця снів?",a="Його виготовив і подарував Ґеролас Талветрен — охоронець, що пильнує сплячих друїдів у Курганному Лігві Бан'етіл.",al={"хто зробив","ґаєролас талвезрен ловець снів","ґаєролас"}},{q="Де в Селі Зоряного Вітерця шукати ловця снів?",a="Він лежить в особистому комоді Таллонкая, у найдальшому південно-східному будинку Села Зоряного Вітерця, яким тепер никають ворожі фурболги-Вузлошкіри.",al={"де комод","місце комода зоряного вітерця","знайти ловця снів"}},{q="Що буде, коли повернути ловця снів?",a="Оглянувши амулет, Таллонкай виявляє, що бракує смарагду: його вкрав ватажок Вузлошкірів Фероцитас, Пожирач Снів, — і це веде просто до полювання на нього.",al={"продовження завдання","наступне завдання після ловця снів"}}},fp="24,377,18.471.0,26.451.0,24.410.1,33.219.0,59.242.0,27.237.0,26.128.0,56.172.0,48.185.1"}
P.entries["quest:244"] = {n="Гноли підступають",s="Гноли підступають — завдання Альянсу, яке попереджає варту Лейкширу про гнолів, що нишпорять небезпечно близько до кордону з Елвінном. Вартовий Паркер помічає табори, що скупчуються вздовж прикордонного перевалу, й посилає подорожніх попередити Помічника Фелдона. Ця звістка підтверджує дедалі більші побоювання Лейкширу: звіролюди погрожують зовсім відрізати Редрідж.",h="Гноли підступають — завдання Альянсу, яке попереджає варту Лейкширу про гнолів, що нишпорять небезпечно...",kw={"гноли підступають","вартовий паркер","помічник фелдон","гноли","ліс елвінн","лейкшир"},ang={["faction:Alliance"]="Відрізаність Лейкширу загрожує східному фронтові Альянсу, тож вісті з кордону вкрай важливі для подорожніх і валок із припасами.",["race:Human"]="Звіролюди, що підступили на відстань погляду до Лісу Елвінн, показують, наскільки вразливими стали серцевинні землі королівства за відсутності короля."},sec={{t="Пильне око на кордоні",b="Дорога, що пов'язує Ліс Елвінн із Горами Редріджу, мала б бути одним із найбезпечніших шляхів королівства, та поріділе військо Стормвінда майже не охороняє її. Вартовий Паркер стоїть на західній прикордонній стежці й стежить за рухом. Йому вдається тримати гравійну дорогу відкритою для возів із припасами, проте його розвідувальні обходи на північ і схід показують, що загони гнолів спустилися зі скель і отаборилися загрозливо близько до шляху."},{t="Містечко в облозі",b="Отримавши звістку біля мосту Лейкширу, Помічник Фелдон розуміє, що становище гірше, ніж він гадав. Гноли Редріджу не просто грабують околиці міста: їхні передові загони біля кордону з Елвінном означають, що вони можуть оточити Лейкшир і вдертися в серце королівства. Стормвінд ігнорує прохання про підкріплення, тож варта Лейкширу погано готова до загрози з двох боків."}},faq={{q="Хто дає це завдання?",a="Це завдання пропонує Вартовий Паркер при шляху на заході Гір Редріджу, біля переходу до Лісу Елвінн.",al={"хто дає завдання","де почати","місце вартового паркера"}},{q="Де знайти Помічника Фелдона?",a="Помічник Фелдон стоїть у Лейкширі, патрулюючи місцевість трохи на південь від великого кам'яного мосту містечка.",al={"місце фелдона","хто помічник фелдон","місце здавання"}},{q="Чому гноли — це біда для шляху?",a="Шлях до Лісу Елвінн — єдина безпечна суходільна нитка, що пов'язує Лейкшир з рештою королівства. Якщо гноли захоплять західні схили, містечко фактично залишиться без припасів і без шляху до втечі.",al={"чому гноли важливі","проблема гнолів редріджа","небезпека дороги"}},{q="Чому Стормвінд не посилає допомоги Лейкширу?",a="Король Варіан Рінн зник, королівство виснажене заворушеннями, тож Верховний Лорд Болвар і двір відмовилися посилати королівські війська в Редрідж, і оборона Лейкшира цілком лягла на місцевих помічників шерифа й добровольців.",al={"де вартові стормвінда","немає підкріплення","оборона лейкшира"}},{q="Що буде, коли доповісти про гнолів?",a="Помічник Фелдон просить вас ближче розвідати табори гнолів у завданні «Оцінка загрози», щоб з'ясувати, скільки їх насправді.",al={"наступне завдання","продовження ланцюжка"}},{q="Які зграї гнолів тут підступають?",a="Гноли Редріджу, що збираються на пагорбах як зграя гнолів Редріджу, дедалі сміливішають і діють злагодженіше, поки влада людей у краю слабшає.",al={"які гноли","клани гнолів редріджа"}}},fp="18,361,18.460.0,18.417.0,22.121.0,31.108.0,40.190.0,45.214.0,40.159.0,39.159.0"}
P.entries["quest:245"] = {n="Восьминога напасть",s="«Восьминога напасть» — замовлення ополчення, яке дає Спостерігач Доддс у Сутінколіссі. Західний кордон заполонили агресивні отруйні павуки-тенетники, і нечисленна Нічна Варта покладається на мандрівних шукачів пригод, щоб винищити виводок, доки в їхніх тенетах не опинилися нові вартові.",h="«Восьминога напасть» — замовлення ополчення, яке дає Спостерігач Доддс у Сутінколіссі.",kw={"восьминога напасть","спостерігач доддс","павуки","нічна варта","алтея ебонлок","сутінколісся"},ang={["class:Hunter"]="Отруйні павуки-тенетники Сутінколісся — люті звірі: щоб успішно на них полювати, потрібні обережні кроки й запас протиотрути.",["faction:Alliance"]="Нічна Варта стоїть зовсім сама, без допомоги Дому Вельмож, тож будь-яка підтримка мандрівників Альянсу життєво важлива, щоб дороги лишалися відкритими."},sec={{t="Кордон в облозі",b="Уздовж західної дороги, що з'єднує Вестфол із Сутінколіссям, густе склепіння лісу поступається сплутаним хащам, обплетеним павутинням. Коли темрява стиснула Велике Селище й обернула його на той проклятий ліс, який знаємо нині, місцеві павуки перетворилися на жахливих хижаків. Тепер карликові отруйні тенетники роями кишать у чагарях, загрожують подорожнім і підступають до крихких оборонних рубежів Нічної Варти."},{t="Тягар Нічної Варти",b="Спостерігач Доддс, що стоїть на посту далеко від безпечного Даркшира, відчайдушно потерпає від браку людей. Командир Алтея Ебонлок не може виділити підкріплення для віддалених застав, коли нежить і воргени тиснуть на саме місто. Лишившись сам-один, Доддс уже бачив, як павуки забирали його товаришів: людей знаходили підвішеними догори ногами в кронах, а паралізувальна отрута поволі розчиняла їх, перетворюючи на поживу."}},faq={{q="Хто дає це завдання?",a="Спостерігач Доддс, член Нічної Варти з невеликого табору в Сутінколіссі, пропонує це завдання мандрівникам, здатним вичистити павуків.",al={"хто дає завдання","хто дає восьминогу напасть","наглядач доддс"}},{q="Чому Нічна Варта не може сама впоратися з павуками?",a="Командир Алтея Ебонлок мусить тримати свій мізерний гарнізон біля Даркшира, щоб відбивати невпинні напади нежиті. Доддсові бракує людей, щоб штурмувати заражені гнізда на кордоні, не покидаючи свого посту.",al={"чому потрібна допомога","чому кличуть шукачів пригод","нестача ополчення даркшира"}},{q="Де водяться ці павуки?",a="Карликові павуки-отрутоплети густо гніздяться в західних лісах Сутінколісся, ховаючись у чагарях одразу при головному шляху з Вестфолу.",al={"місце павуків","де пігмейські павуки","павуки в лісі"}},{q="Чим ці павуки такі небезпечні для варти?",a="Крім того, що їх сила-силенна, вони мають потужну отруту, яка паралізує й розчиняє плоть, тож заплутані вартові Нічної Варти безпорадно висять на гіллі, легка здобич.",al={"павучий отрута","отрута павуків","жертви павуків"}},{q="Чи це єдині павуки в Сутінколіссі?",a="Ні. Карликові отрутоплети — лише дрібний виплід. Глибше в лісі живуть значно більші й смертоносніші особини, ще небезпечніші для мандрівників.",al={"інші павуки сутінколісся","види павуків","павуки отруйні павутини"}},{q="Чому павуків і комах так агресивно побільшало?",a="Всепроникна магічна скверна, що огортає Сутінколісся, спотворила місцеву живність, і по всьому спаплюженому лісі звірі стали агресивнішими, більшими й смертоноснішими.",al={"чому стільки павуків","скверна сутінколісся природа","походження павуків"}}},fp="20,268,20.429.0,29.421.0,22.145.0,56.206.0,32.143.0,51.178.0,39.165.0,63.171.0"}
P.entries["quest:2458"] = {n="Глибоке прикриття",s="Глибоке прикриття — таємне доручення, яке Шентул в Оргріммарі дає обдарованим розбійникам Орди. Агент вирушає до бурових угідь Венчурної Компанії біля Багнистого Болота, щоб таємно зв'язатися з упровадженим туди агентом Розтрощеної Руки.",h="Глибоке прикриття — таємне доручення, яке Шентул в Оргріммарі дає обдарованим розбійникам Орди.",kw={"глибоке прикриття","наглядач фіззул","шентул","венчурна компанія","багнисте болото","розтрощена рука"},ang={["class:Rogue"]="Це доручення — важлива віха для розбійників Орди: з простих вуличних розвідників вони стають довіреними агентами, здатними таємно координувати дії в полі.",["faction:Horde"]="Безупинна суцільна вирубка й буріння Венчурної Компанії в Пустках загрожують владі Орди над її землями й природним багатствам, тож без рішучого шпигунства не обійтися."},sec={{t="Шпигун серед зисколюбців",b="Розтрощена Рука — таємна гільдія розвідників і вбивць Орди, що тихо обстоює інтереси Оргріммара безжально практичними засобами. Цілий рік гільдія трудилася, щоб упровадити агента в ієрархію хижацької Венчурної Компанії. Цей агент, Наглядач Фіззул, зумів утертися в довіру на їхньому промисловому буровому пості на північ від Багнистого Болота."},{t="Знаки й сигнали",b="Робота глибоко в найманських лавах не прощає помилок. Фіззул грає роль безжального наглядача, щоб догодити корпоративному начальству, тож будь-який непрошений гість ризикує наразитися на негайний напад. Щоб підтвердити, хто вони, розбійники мусять випустити дві сигнальні ракети з особливої сигнальної рушниці так, щоб їх бачили з його вежі, тихо підійти й віддати таємний салют Розтрощеної Руки — і лише тоді вони отримають його донесення про дедалі зухваліші задуми Венчурної Компанії."}},faq={{q="Хто такий Наглядач Фіззул?",a="Наглядач Фіззул — агент Розтрощеної Руки під глибоким прикриттям, впроваджений в ієрархію Венчурної Компанії на північ від Багнистого Болота. Цілий рік він видирався на керівну посаду серед найманців, стежачи за їхніми справами й передаючи відомості до Оргріммара.",al={"фіззул","хто такий фіззул","наглядач фіззул"}},{q="Чому Фіззул нападає, якщо не подати йому правильного знаку?",a="Фіззул підтримує легенду грубого, безжального наглядача Венчурної Компанії. Якщо хтось наближається до його посту, не подавши точного сигналу двома ракетами й салюту Розтрощеної Руки, він мусить вважати його ворожим зайдою чи агентом конкурентів і нападає одразу, щоб не зірвати маскування.",al={"чому фіззул нападає","фіззул ворожий","фіззул мене вбиває"}},{q="Де стоїть вежа Венчурної Компанії?",a="Вежа височіє над промисловими розробками трохи на північ від Багнистого Болота, у центрально-північній частині Пусток.",al={"місце фіззула","місце вежі","де вежа багнистого болота"}},{q="Навіщо Орда шпигує за Венчурною Компанією?",a="Венчурна Компанія сумно відома безоглядним хижацьким видобутком, визиском і безжальним насильством по всьому Калімдору. Нещодавні розвідані Розтрощеної Руки показали, що картель готує в Пустках велику оборудку, тож Шентул задіяв свого агента.",al={"чому шпигувати за венчурною компанією","загроза венчурної компанії"}},{q="Що буде, коли встановити зв'язок із Фіззулом?",a="Коли зв'язок безпечно встановлено, Фіззул дає розбійникові вказівки проникнути до сусідньої вежі Венчурної Компанії, перебити її мешканців, зокрема Великого Наглядача Пузіка Ґаллівікса, і викрасти запас Зміненої Суміші Занзіла — так розбійник доведе гільдії свою вартість.",al={"що далі після глибокого прикриття","після фіззула"}},{q="Що таке Розтрощена Рука?",a="Розтрощена Рука — тіньова мережа розбійників, шпигунів і вбивць, що діє з Тіньової Розколини в Оргріммарі. Колись сумнозвісний клан на Дренорі, у новій Орді вони — таємна розвідувальна служба Орди.",al={"розтрощена рука","хто такі розтрощена рука"}}},fp="10,261,22.401.0,17.460.0,26.284.0,58.308.0,43.136.0,47.276.0,47.264.1,27.233.0"}
P.entries["quest:2459"] = {n="Фероцитас, Пожирач Снів",s="«Фероцитас, Пожирач Снів» — завдання Альянсу, яке дає Таллонкай Свіфтрут у Доланаарі. Повернувши собі пошкоджений родинний ловець снів, Таллонкай виявляє, що його могутнє смарагдове осердя видерли фурболґи Вузлошкіри, що живуть на північ від Села Зоряного Вітерця. Шукачів пригод посилають знищити зіпсутих містиків і відібрати вкрадений самоцвіт у їхнього ватажка — Фероцитаса.",h="«Фероцитас, Пожирач Снів» — завдання Альянсу, яке дає Таллонкай Свіфтрут у Доланаарі.",kw={"фероцитас","ловець снів","вузлошкіри","фурболґи","тельдрассил","доланаар","таллонкай"},ang={["class:Druid"]="Ловці снів — могутні знаряддя, пов'язані зі Смарагдовим Сном; бачити, як один із них осквернив зіпсутий фурболґ, — означає вимагати швидкої відплати від імені природи.",["race:NightElf"]="Вузлошкіри колись були союзниками калдорей, тож зіпсуття їхніх містиків і крадіжка священних талісманів — гірка трагедія для кожного нічного ельфа, що боронить Тельдрассил."},sec={{t="Осквернена реліквія",b="Коли Таллонкай Свіфтрут оглянув ловець снів, повернутий зі зіпсутих хащ, полегшення швидко змінилося розпачем. Священну реліквію спаплюжили: яскравий смарагд, її серцевину, вирвали з плетеної рами. Серед нічних ельфів ходили чутки, що ватага містиків Вузлошкірів на північ від Села Зоряного Вітерця підпала під вплив фурболґа-ватажка на ім'я Фероцитас, Пожирач Снів, який зухвало носив на шиї сяйливий зелений камінь. Знаючи, що в лапах цього створіння священний самоцвіт і марний, і спотворений, Таллонкай послав захисників відібрати його."},{t="Очищення від містиків",b="Фурболґи Вузлошкіри, що населяють північні околиці Тельдрассила, колись були мирними сусідами, та зіпсуття, яке дедалі глибше просякає Світове Дерево, ввергло їх у шал і безумство. Їхні містики, що колись творили лагідні обряди природи, почали черпати з викривлених магічних потоків. Вистеживши Фероцитаса й прорубавшись крізь почет містиків, які стережуть його лісовий сховок, мандрівники повертають лісові рівновагу й добувають самоцвіт Таллонкая, щоб ловець снів нарешті став цілим."}},faq={{q="Де знайти Фероцитаса, Пожирача Снів?",a="Фероцитас, Пожирач Снів, — у лісі на північ від Села Зоряного Вітерця на Тельдрассилі, серед зіпсованих скверною містиків-Вузлошкірів та інших лісових небезпек.",al={"місце фероцитаса","де фероцитас","знайти пожирача снів"}},{q="Хто такий Фероцитас?",a="Фероцитас — ватажок фурболгів-Вузлошкірів, що командує ватагою зіпсованих скверною містиків на північ від Села Зоряного Вітерця. Він вийняв смарагд з ловця снів Таллонкая Свіфтрута й зробив з нього грубе намисто.",al={"хто такий фероцитас","фероцитас лор","що таке пожирач снів"}},{q="Чому Таллонкай Свіфтрут хоче повернути самоцвіт?",a="Зниклий смарагд — головне джерело сили ловця снів Таллонкая. Без нього талісман не полагодити, і він не зможе спрямовувати захисну енергію Смарагдового Сну.",al={"чому таллонкай хоче самоцвіт","призначення самоцвіту таллонкая"}},{q="Чи можуть Вузлошкіри справді користуватися магією смарагду?",a="Ні. За словами Таллонкая Свіфтрута, магічні властивості смарагду цілком марні для створінь на кшталт Фероцитаса й містиків-Вузлошкірів — вони жадали його просто як блискучу цяцьку.",al={"чи вузлошкіри можуть користуватися ловцем снів","чи фероцитас користується смарагдом"}},{q="Що буде після цього завдання?",a="Це завдання — останній розділ ланцюжка з двох частин, що почався зі «Смарагдового Ловця Снів». Коли ви принесете самоцвіт Таллонкаєві в Доланаар, він нарешті зможе полагодити свою реліквію.",al={"завдання після фероцитаса","наступне завдання ловця снів"}},{q="Чому містики-Вузлошкіри ворожі?",a="Як і чимало звірів і племен фурболгів по всьому Тельдрассилу, Вузлошкіри піддалися дивній скверні, що спотворює гілля щойно посадженого Світового Дерева, затьмарює їм розум і робить їх агресивними.",al={"чому вузлошкіри ворожі","скверна вузлошкірів"}}},fp="25,360,18.578.0,19.503.0,42.163.0,17.219.0,49.174.0,51.191.0,30.184.0,38.218.0"}
P.entries["quest:246"] = {n="Оцінка загрози",s="Оцінка загрози — оборонна розвідувальна операція, яку замовив Помічник Фелдон у Лейкширі. Місцевий гарнізон виснажений, підкріплення від Стормвінда немає, тож шукачів пригод наймають винищувати зграї гнолів, що підступають уздовж південної дороги, і з'ясувати, наскільки сильна ця дедалі більша загроза.",h="Оцінка загрози — оборонна розвідувальна операція, яку замовив Помічник Фелдон у Лейкширі.",kw={"оцінка загрози","помічник фелдон","гноли","розвідка","лейкшир","редрідж"},ang={["class:Warrior"]="Помічник Фелдон просить про наступальну розвідку боєм — випробування для озброєного бійця, здатного вриватися в укріплені ворожі табори й ламати їхній авангард.",["faction:Alliance"]="Редрідж оголює тріщини в серці Альянсу: занедбані прикордонні поселення змушені наймати вільних звитяжців, щоб вижити, поки столиця відводить очі.",["race:Human"]="Для людей-захисників оборона Лейкширу — особиста справа: ці прикордонні родини розплачуються за політичний параліч у Фортеці Стормвінда."},sec={{t="Напружене прикордоння",b="Лейкшир бореться за виживання на кількох фронтах. Між загонами орків Блекрок, що спускаються з висот, і агресивними зграями гнолів, що тероризують долини, місцеві захисники не можуть виділити людей навіть на звичайні розвідувальні патрулі. Коли перші донесення підтвердили, що гноли наближаються до кордону, Помічник Фелдон звернувся по допомогу ззовні. Замість того щоб посилати в глушину штатних вартових, містечко платить мандрівним звитяжцям, щоб ті власноруч перевірили сили ворога."},{t="Розвідка боєм",b="Доручення веде розвідників уздовж південної дороги Редріджу, просто в табори дворняг і браконьєрів Редріджу. Це збирання відомостей шляхом виснаження: знищити передових розвідників, перерізати шляхи постачання й з'ясувати, чи зграї — просто мандрівні падальники, чи частина організованої військової сили, що загрожує поселенню. Криваві сутички дають Фелдонові точні цифри, потрібні, щоб спланувати виснажену оборону Лейкширу."}},faq={{q="Чому Помічник Фелдон посилає шукачів пригод, а не міських вартових?",a="Гарнізонові Лейкшира вкрай бракує людей. Підкріплень зі Стормвінда немає, ворожі сили тиснуть з усіх боків, тож міська варта не може виділити солдатів для довгих патрулів уздовж південного шляху.",al={"чому наймають шукачів пригод","де вартові","нестача вартових лейкшира"}},{q="Де шукати гнолів для цього доручення?",a="Редріджські дворняги й браконьєри стоять розкиданими таборами вздовж південного шляху й на низьких передгір'ях Гір Редріджу, на південь від Лейкшира, біля прикордонних перевалів.",al={"де гноли редріджа","місця гнолів редріджа","гноли південної дороги"}},{q="Яка стратегічна мета винищення цих гнолів?",a="Операція має дві мети: відкинути передових розвідників, що підбираються до шляху, і здобути з перших рук військові відомості про чисельність, зброю й дисципліну гнолів Редріджу.",al={"навіщо вбивати гнолів","мета оцінки загрози","оборона лейкшира"}},{q="Чи допомагає Стормвінд боротися з гнолами?",a="Ні. Дім Вельмож і регентська рада Стормвінда відмовили окраїнам на кшталт Редріджу в підтримці регулярного війська, тож місцева влада — як-от Магістрат Соломон і Помічник Фелдон — мусить покладатися на найманців.",al={"підкріплення стормвінда","чому стормвінд не допомагає","армія стормвінда лейкшир"}},{q="Що Помічник Фелдон робить із вашою доповіддю?",a="Помічник Фелдон оцінює силу й завзятість зграй, переконується, що південні гноли — серйозна військова загроза, а не поодинокі звірі, і посилає вас допомогти іншим очільникам містечка зміцнити оборону.",al={"реакція фелдона","що після оцінки загрози","здати звіт"}},{q="Як це завдання пов'язане з попереднім?",a="Це пряме продовження завдання «Гноли підступають». Після того як ви вперше попередили гарнізон про пересування гнолів, Фелдон доручив цей бойовий патруль, щоб оцінити, наскільки серйозне вторгнення.",al={"зв'язок ланцюжка завдань","продовження гнолів підступають","передумова"}}},fp="20,305,19.493.0,23.461.0,63.247.0,46.170.0,54.208.0,47.229.0,44.231.0,46.193.0"}
P.entries["quest:2460"] = {n="Салют Розтрощеної Руки",s="Салют Розтрощеної Руки — обряд посвяти, який проводить Шентул у Тіньовій Розколині Оргріммара. Опанувавши цей особливий знак упізнавання, молоді розбійники вчаться безпечно розпізнавати своїх товаришів — агентів Розтрощеної Руки — у полі.",h="Салют Розтрощеної Руки — обряд посвяти, який проводить Шентул у Тіньовій Розколині Оргріммара.",kw={"салют розтрощеної руки","шентул","розтрощена рука","знаки","тіньова розколина","розбійник"},ang={["class:Rogue"]="Для розбійника Орди опанувати таємні знаки Розтрощеної Руки — це перехід від звичайного кишенькового злодія до довіреного агента розвідувальної мережі Оргріммара.",["faction:Horde"]="Хоч Вождь Тралл веде Орду шляхом честі, вона неабияк покладається на таємні методи Розтрощеної Руки, щоб знешкоджувати загрози, перш ніж ті вийдуть на поверхню."},sec={{t="Знаки й тіні",b="У темних тунелях Тіньової Розколини Розтрощена Рука діє як таємне розвідувальне й каральне крило Орди Тралла. З огляду на небезпечну й таємну природу їхніх доручень агенти не можуть покладатися на відкриті стяги чи звичну військову геральдику. Шентул навчає щойно посвячених розбійників Салюту Розтрощеної Руки — особливого жесту, що слугує безпомилковим мовчазним сигналом між своїми."},{t="Підготовка до роботи в полі",b="Опанувати салют — не просто церемоніальна вправа, а життєво важливе ремесло. Розбійники-агенти, яких посилають на небезпечні терени або яким доручають проникнути до ворожих угруповань, мусять перевіряти свої зв'язки, не сполохавши ні сторонніх, ні цілей. Шентул наполягає, щоб агент упізнавав і повторював цей жест без жодних зусиль, перш ніж довірити йому таємну роботу в полі."}},faq={{q="Навіщо потрібен Салют Розтрощеної Руки?",a="Салют Розтрощеної Руки — таємний знак розпізнавання серед членів Розтрощеної Руки. Він дає агентам змогу впізнати одне одного під глибоким прикриттям чи на ворожій землі, не розкриваючи чужинцям справжньої належності.",al={"навіщо мені салют","мета салюту розтрощеної руки","що робить салют"}},{q="Хто навчає Салюту Розтрощеної Руки?",a="Салюту навчає Шентул — наставник розбійників, що перебуває глибоко в Тіньовій Розколині під Оргріммаром.",al={"хто дає завдання","хто такий шентул","де вивчити салют"}},{q="Яка організація користується цим жестом?",a="Ним користується Розтрощена Рука — орден орків-розбійників, шпигунів і вбивць, що служить сучасній Орді з тіней Оргріммара.",al={"клан розтрощеної руки","хто такі розтрощена рука","яка гільдія"}},{q="Чому треба навчитися салюту, перш ніж виходити в поле?",a="Агенти, яких посилають на проникнення, — скажімо, щоб вийти на зв'язок з агентами під прикриттям, — покладаються на салют, щоб не зірвати прикриття й не сплутати ворога із союзником.",al={"чому вчити салют","чи салют обов'язковий"}},{q="Де відбувається це навчання?",a="Навчання відбувається в Тіньовій Розколині — підземному кварталі під Оргріммаром, де подалі від чужих очей збираються розбійники, чорнокнижники й інші практики заборонених мистецтв.",al={"місце салюту","де шентул"}},{q="Яке доручення йде після того, як опануєш салют?",a="Коли Шентул задоволений тим, як агент опанував салют, він посилає його на операції під глибоким прикриттям, перевіряючи, чи вміє той користуватися знаком, щоб вийти на зв'язок з агентами в полі.",al={"що далі","наступне завдання після салюту","завдання глибоке прикриття"}}},fp="20,257,17.431.0,25.365.0,44.230.0,33.111.0,36.141.0,65.174.0,36.193.0,51.183.0"}
P.entries["quest:247"] = {n="Полювання завершено",s="«Полювання завершено» — вінець великих звіриних випробувань Сенані Тандергарт в Ашенвалі. Убивши Урсанґуса, Шадумбру й Шарпталона, звитяжець Орди доводить свою силу, завзяття й первісну мисливську вправність у спірному лісі.",h="«Полювання завершено» — вінець великих звіриних випробувань Сенані Тандергарт в Ашенвалі.",kw={"полювання завершено","сенані тандергарт","урсанґус","шадумбра","шарпталон","завдання"},ang={["class:Hunter"]="Здолати трьох верховних хижаків Ашенвалю — остаточний обряд майстерності слідопита й стрільця, що доводить: ваше чуття не поступається чуттю самих диких звірів.",["faction:Horde"]="Приборкання звірів Ашенвалю допомагає Орді закріпитися в небезпечному, ворожому лісі, повному і хижаків, і вартових Альянсу.",["race:Tauren"]="Для шу'гало полювання на Урсанґуса, Шадумбру й Шарпталона — освячене часом випробування шани, рівноваги й гордості за предків."},sec={{t="Доказ мисливця",b="Сенані Тандергарт, що служить серед сил Орди в Ашенвалі, випробовує мандрівників не лише на вірність вождеві, а й на розуміння законів дикого виживання. Полювання Ашенвалю має на меті трьох легендарних хижаків, що чатують під прадавнім гіллям: ведмедя Урсанґуса, кішку Шадумбру та лютого гіпогрифа Шарпталона. Убивши всіх трьох і здобувши їхні трофеї, звитяжець доводить, що в його жилах тече справжня мисливська кров."},{t="Шана предкам",b="Для тауренів полювання — священна дія рівноваги й шани навіть посеред воєнного фронту. Здолавши верховних страховиськ Ашенвалю, мисливець ушановує духів землі й здобуває благословення предків від Тандергарт. Полювання завершується урочистою похвалою та знаком прихильності, що утверджує славу звитяжця по всьому лісу."}},faq={{q="Хто дає це завдання і де його знайти?",a="Завдання завершує Сенані Тандергарт — тауренка-мисливиця, що стоїть з Ордою в давніх лісах Ашенвалю.",al={"хто дає завдання","куди здати","місце сенані тандергарт"}},{q="Що треба зробити, щоб завершити полювання?",a="Треба вбити трьох верховних хижаків, що никають Ашенвалем, і принести докази їхньої загибелі: лапу ведмедя Урсанґуса, голову нічного шаблезуба Шадумбри й кіготь гіпогрифа Шарпталона.",al={"яких звірів убити","передумови","які тварини"}},{q="Чому Сенані Тандергарт хоче смерті цих звірів?",a="Полювання — випробування сили й завзятості. Здолавши таких грізних звірів, мандрівник доводить, що має справжнє серце й чуття хижака, здатного вижити в підступних нетрях Ашенвалю.",al={"чому сенані хоче смерті звірів","мотив сенані","мета полювання"}},{q="Яке культурне значення має полювання для Орди?",a="Для тауренів на кшталт Сенані Тандергарт випробувати себе в боротьбі з могутніми звірами — шляхетна традиція, мила духам і предкам. Вона показує панування над дикою природою без безрозсудної ганьби.",al={"лор полювання таурени","культурне значення","чому таурени полюють на звірів"}},{q="Чи визнає це випробування вся Орда?",a="Так. Завершивши полювання, ви в очах Орди в Ашенвалі стаєте визнаним мисливцем і здобуваєте благословення предків і повагу товаришів.",al={"визнання орди","чи офіційне","відзнака орди"}},{q="На яких трьох звірів полюють у Полюванні в Ашенвалі?",a="Цілі — великий ведмідь Урсанґус, потайний нічний шаблезуб Шадумбра й смертоносний гіпогриф Шарпталон.",al={"три звірі","цілі полювання","названі тварини"}}},fp="18,243,16.447.0,22.354.0,49.128.0,47.201.0,53.215.0,59.217.0,45.164.0,54.114.0"}
P.entries["quest:2478"] = {n="Місія: можлива, але малоймовірна",s="Це важливе доручення перевіряє потайливість, злодійські й бойові вміння розбійника Орди на свавільному форпості Венчурної Компанії в північних Пустках. Агенти проникають на нафтову вежу, вбивають Великого Наглядача Пузіка Ґаллівікса й забирають сильнодійну хімічну суміш для Розтрощеної Руки.",h="Це важливе доручення перевіряє потайливість, злодійські й бойові вміння розбійника Орди на свавільному...",kw={"місія","пузік ґаллівікс","наглядач фіззул","наглядач сіліксиз","мікстура занзіла","розтрощена рука"},ang={["class:Rogue"]="Цей обряд посвяти вчить практичної роботи в полі — відмикання замків, обчищання кишень і використання слабких місць ворога — і відчиняє двері до смертоносного ремесла й отрут Розтрощеної Руки.",["faction:Horde"]="Розтрощена Рука діє з тіней Оргріммара й стежить за небезпечними корпоративними зайдами на кшталт Венчурної Компанії, що грабують Пустки."},sec={{t="Проникнення до Венчурної Компанії",b="North of the Sludge Fen oil rigs, the Venture Company maintains an isolated drilling tower. Under orders from Taskmaster Fizzule, an embedded Shattered Hand operative posing as a Venture Company supervisor, rogues are instructed to use classic underworld methods rather than outright assault. Fizzule asks rogues to pickpocket a key directly off Foreman Silixiz and keep it for him before mounting an ascent through heavily altered workers and sentries."},{t="Хімічна катастрофа",b="На мешканців вежі глибоко вплинула дослідна речовина — змінена мікстура Занзіла. Отрута послабила вартових, і вони стали напрочуд уразливими до стрімких ударів, кровотечних атак і раптових засідок, — але й зробила весь об'єкт украй нестабільним. На верхівці чатує Великий Наглядач Пузік Ґаллівікс, що стереже скриньку з самим цим мінливим зіллям."},{t="Ціна обов'язку",b="Зламавши скриньку Ґаллівікса, розбійник неминуче вдихає підступні випари зміненої мікстури й підхоплює виснажливу, тривалу недугу, що зриває потайливість і висмоктує сили. Доручення завершується в Оргріммарі в наставника Розтрощеної Руки Шентула: він отримує голову Ґаллівікса й зразок суміші, тихо шкодує, що прикриття Фіззула викрито, і посилає вмирущого агента шукати ліки."}},faq={{q="Де стоїть вежа Венчурної Компанії?",a="Вежа стоїть на півночі Пусток, трохи на північ від бурових розробок на Багнистому Болоті. Її оточують ворожі робітники Венчурної Компанії, а Наглядач Фіззул ховається біля дерева одразу на схід.",al={"місце вежі венчурної компанії","де вежа ґаллівікса","вежа багнистого болота"}},{q="Як здобути ключ від вежі?",a="Ключ від вежі має Наглядач Сіліксиз, що походжає біля підніжжя вежі. Треба підкрастися й обчистити його кишені; якщо вбити його, ключа не отримаєте.",al={"ключ від вежі сіліксіза","як дістати ключ вежі","де ключ"}},{q="Що таке Змінена Суміш Занзіла?",a="Це алхімічне вариво за рецептами сумнозвісного троля-знахаря Занзіла. Венчурна Компанія роздобула цю речовину, але її нестійкі випари отруїли робітників у вежі: вони стали хворими, мутованими й вразливими до бойових прийомів розбійника.",al={"суміш занзіла","яка це отрута","змінена суміш"}},{q="Чому я не можу скрадатися, коли відкрив скриньку?",a="Відкриваючи скриньку Ґаллівікса, ви вивільняєте зосереджені випари зміненої суміші. Отруйне ослаблення тримається днями, висмоктує ваші сили й не дає залишатися непоміченими, доки вас не вилікує досвідчений аптекар.",al={"дотик занзіла","отруєний після скрині","не можу скрадатися","семиденна отрута"}},{q="Хто такий Наглядач Фіззул?",a="Фіззул — агент під глибоким прикриттям від Розтрощеної Руки, гільдії розбійників Орди. Дворф із Темного Заліза, що видає себе за безжального наглядача Венчурної Компанії в Пустках, він спрямовує новобранців шкодити майну Венчурної Компанії, не розкриваючи свого прикриття.",al={"фіззул","хто дав завдання","фіззул лор"}},{q="Хто такий Великий Наглядач Пузік Ґаллівікс?",a="Великий Наглядач Пузік Ґаллівікс — гоблін, що керує вежею Венчурної Компанії біля Багнистого Болота. Він стереже вкрадений запас вариву Занзіла, доки його не вб'ють агенти Розтрощеної Руки.",al={"пузік ґаллівікс","чи ґаллівікс у пустках","наглядач ґаллівікс"}}},fp="34,289,31.453.0,22.399.1,17.431.2,39.228.0,39.188.0,33.268.0,53.233.1,26.255.0,36.201.0"}
P.entries["quest:2479"] = {n="Допомога Гінотта",s="Допомога Гінотта — нагальна подорож розбійників Орди, уражених виснажливою тропічною отрутою. Підхоплена під час таємної вилазки в Пустках, ця недуга вимагає особливих знань Сержа Гінотта з Таррен Мілла. Його допомога обіцяє і рятівні ліки, і науку виготовлення смертоносних отрут.",h="Допомога Гінотта — нагальна подорож розбійників Орди, уражених виснажливою тропічною отрутою.",kw={"допомога гінотта","серж гінотт","таррен мілл","мікстура занзіла","отрути","розбійник"},ang={["class:Rogue"]="Цей обряд посвяти перекидає міст від простої потайливості до алхімічного мистецтва: він випробовує витривалість розбійника й відчиняє двері до власноруч зварених отрут.",["faction:Horde"]="Це доручення показує практичну співпрацю, що поєднує розбійників-орків і тролів Калімдору зі зловісними алхімічними знаннями Відступників у Лордероні."},sec={{t="Отруйна халепа",b="Після зухвалого проникнення у вежу Венчурної Компанії на північ від Багнистого Болота розбійники опиняються ураженими зміненою мікстурою Занзіла. Отрута спустошує тіло, притуплює реакцію й загрожує самому життю. Розуміючи, наскільки тяжке ураження, наставник розбійників Шентул в Оргріммарі визнає, що місцеві засоби безсилі, і посилає отруєного агента за море, до Східних Королівств."},{t="Дорога до Таррен Мілла",b="Пошуки ліків ведуть на південь континенту Лордерон, до селища Таррен Мілл у Передгір'ї Гілсбреда. Там живе Серж Гінотт — аптекар, чия пристрасть до згубних зіль робить його ідеальним знавцем, щоб дослідити екзотичний зразок. Поки звичайні цілителі сахалися отрути Занзіла, Гінотт береться до смертоносної суміші з професійним захватом: він прагне розібрати мерзенне зілля на складники й навчити гідних розбійників варити власні отрути."}},faq={{q="Навіщо мені до Сержа Гінотта?",a="Серж Гінотт — досвідчений аптекар з Таррен Мілла, що спеціалізується на рідкісних отрутах і протиотрутах. Звичайні цілителі не здатні вивести змінену суміш Занзіла, тож лише Гінотт може дослідити сполуку, врятувати вам життя й навчити мистецтва отрут.",al={"чому гінотт","хто лікує отруту","роль сержа гінотта"}},{q="Де розташований Таррен Мілл?",a="Таррен Мілл — поселення Відступників на півночі Передгір'я Гілсбреда. З Оргріммара летіть дирижаблем до Андерсіті в Галявинах Тірісфалю, а тоді йдіть на південь через Срібнолісся й поверніть на схід шляхом до Гілсбреда.",al={"місце таррен мілл","як дістатися таррен мілл","де гінотт"}},{q="Як я взагалі отруївся?",a="Ви заразилися під час таємного завдання «Місія: можлива, але малоймовірна» у вежі Венчурної Компанії на північ від Багнистого Болота в Пустках. Відкривши добре захищену скриню, ви вдихнули змінену суміш Занзіла, і вас скувало виснажливе, затяжне нездужання.",al={"як я отруївся","отрута місії можлива","чому я отруєний"}},{q="Що буде, коли Серж Гінотт отримає зразок?",a="Отримавши зразок, Гінотт досліджує його властивості й готує протиотруту, щоб очистити ваш організм. Вилікувавши отруєння, він ділиться своїм досвідом, і розбійники можуть опанувати варіння й застосування власних отрут.",al={"продовження гінотта","чи мене вилікують","після допомоги гінотта"}},{q="Хто такий Шентул і чому він мене відіслав?",a="Шентул — наставник розбійників Розтрощеної Руки в Тіньовій Розколині Оргріммара. Він наглядав за вашим випробуванням у Пустках і зрозумів, що вариво Занзіла далеко за межами того, що знають лікарі Оргріммара, тож потрібен фахівець у Гілсбреді.",al={"хто такий шентул","шентул оргріммар","чому тренер відіслав мене"}},{q="Чи може це завдання виконати інший клас?",a="Ні. Це доручення — частина окремого шляху навчання розбійників, що відкриває основне вміння варити отрути й ліки.",al={"чи лише для розбійників","чи воїни можуть допомогу гінотта"}}},fp="19,359,19.431.0,22.461.0,34.289.0,29.229.0,42.263.0,52.233.1,44.265.0,40.137.0"}
P.entries["quest:248"] = {n="Шукати далі",s="«Шукати далі» — шпигунська місія Альянсу, якою керує чарівник Теокрітус через зачарований канал зв'язку. Щоб розібратися в напруженні між магом-відступником Морґантом і орками Блекрок, ви маєте пробратися до сторожової вежі біля Фортеці Кам'яної Варти й сховати зачарований гліф у непримітній посудині.",h="«Шукати далі» — шпигунська місія Альянсу, якою керує чарівник Теокрітус через зачарований канал зв'язку.",kw={"теокрітус","морґант","гліф азори","кам'яна варта","чорна скеля","редрідж","шпигунство"},ang={["class:Mage"]="Теокрітус покладається на витончену магію далекого ворожіння через Гліф Азори — так Кірін-Тор і маги Азори налагоджують магічне стеження на ворожих територіях.",["faction:Alliance"]="Фортеця Кам'яної Варти лишається головною твердинею клану Блекрок в Редріджі. Відомості про їхні чвари з Морґантом конче потрібні для оборони Лейкшира."},sec={{t="Розкол у Редріджі",b="Зі свого святилища в Лісі Елвінн чарівник Теокрітус за допомогою ворожильної магії пильно стежить за східним Редріджем. Спостерігаючи за Вежею Ілґалара, він помічає раптовий розбрат між Морґантом, чорнокнижником-відступником із людського роду, та орками Блекрок, що закріпилися у Фортеці Кам'яної Варти. Замість діяти спільно проти Королівства Стормвінд ці ворожі сили зчепилися за якусь невідому здобич, і Теокрітус вирішує втрутитися, перш ніж шальки терезів хитнуться."},{t="Око на Кам'яній Варті",b="Щоб пробити оборону Фортеці Кам'яної Варти, Теокрітусу потрібна друга магічна точка опори. Він наказує шукачам пригод піднятися на вцілілу сторожову вежу, що стоїть поруч зі зруйнованою твердинею. Там, серед гарнізонного мотлоху, порожній глек, викинутий орківськими вартовими, стає ідеальною непримітною схованкою. Щойно Гліф Азори закріплено всередині посудини, Теокрітус зможе подумки перебирати думки тих, хто перебуває в Кам'яній Варті, і дізнатися, що посварило Морґанта з орками Блекрок."}},faq={{q="Хто посилає мене на це доручення?",a="Завдання дає Теокрітус, маг з Азори, промовляючи крізь Стару статую лева в Горах Редріджу після того, як ви виконали його попереднє доручення.",al={"хто дає завдання","стара статуя лева"}},{q="Навіщо Теокрітус шпигує за Фортецею Кам'яної Варти?",a="Теокрітус помітив, що між Морґантом, чаклуном-ренегатом з Вежі Ілґалара, і орками Блекрок, які засіли у Фортеці Кам'яної Варти, назріває відкрита ворожнеча. Він хоче з'ясувати, що спричинило їхній конфлікт.",al={"навіщо шпигувати за орками","мета теокрітуса","чому кам'яна варта"}},{q="Де посудина?",a="Посудина — порожній глек на бочках на самій вершині вцілілої сторожової вежі, що стоїть просто біля головного входу до Фортеці Кам'яної Варти.",al={"де посудина","місце порожнього глека","де сторожова вежа"}},{q="Що робить Гліф Азори?",a="Він — магічне знаряддя для ясновидіння й ворожіння, що дає Теокрітусові змогу здалеку стежити за околицями й зазирати в думки орків Блекрок у фортеці.",al={"мета гліфа азори","що робить гліф"}},{q="Що далі, коли гліф підкинуто?",a="Щойно Теокрітус розгадає причину конфлікту, він доручає вам вистежити самого Морґанта у Вежі Ілґалара й принести його Амулет Тіні.",al={"наступне завдання","що буде далі","продовження шукати далі"}},{q="Чому саме порожній глек?",a="Магічна шпигунська руна потребує непримітної посудини, щоб вартові її не помітили й не знищили. Покинутий, смердючий глек з-під пійла, забутий на бочках, — ідеальна схованка.",al={"чому порожній глек","лор порожнього глека"}}},fp="15,307,18.487.0,21.494.1,29.154.0,44.210.0,31.155.0,32.177.0,38.158.1,21.179.0"}
P.entries["quest:2480"] = {n="Допомога Гінотта",s="«Допомога Гінотта» — завершення шляху розбійника Орди, що мусить здолати смертельну повзучу отруту Занзіла. Звернувшись до аптекаря Сержа Гінотта в Таррен Міллі, отруєний агент отримує протиотруту й перші уроки алхімічного отруйництва.",h="«Допомога Гінотта» — завершення шляху розбійника Орди, що мусить здолати смертельну повзучу отруту Занзіла.",kw={"допомога гінотта","серж гінотт","занзіл","отрути","розбійники","таррен мілл","завдання"},ang={["class:Rogue"]="Цей обряд посвяти виліковує виснажливу недугу, якої ви зазнали під час випробування, і відкриває знання, потрібні, щоб варити бойові отрути.",["faction:Horde"]="Алхімія Відступників незамінна для потаємних агентів Орди: вона перетворює екзотичні отрути тролів джунглів на звичні польові знання.",["race:Undead"]="Аптекар Гінотт уособлює відсторонене наукове захоплення Королівського Аптекарського Товариства будь-якою отрутою, створеною зі справжньою майстерністю, хоч би звідки вона походила."},sec={{t="Отруйний шедевр",b="Підхопивши під час доручення в Пустках заразну отруту, що каламутить розум, розбійники Орди вирушають на північ, до Таррен Мілла, по пораду до Сержа Гінотта. Цей хімік-Відступник, цілком відданий своїй справі, ставиться з професійним захватом до отрути, яку зварив вигнанець-троль із джунглів Занзіл. Байдужий до особи й родоводу троля, Гінотт відверто хвалить безжальну дієвість варива й прагне вивчити, як воно діє, перш ніж створити протиотруту."},{t="Протиотрута й ремесло",b="Щоб створити ліки, треба лише терпіння, поки Гінотт виокремлює діючі речовини. Готове вариво зупиняє повзуче божевілля, хоч хімік і визнає, що позбутися затхлого смороду воно не допоможе. Очистившись від виснажливої отрути, розбійники з жертв стають знавцями: спираючись на те, що Гінотт збагнув у роботі Занзіла, вони опановують приготування власних бойових отрут."}},faq={{q="Що відбувається в завданні «Допомога Гінотта»?",a="Треба лише трохи зачекати в Таррен Міллі, поки Серж Гінотт готує протиотруту. Коли він домішає вариво, поговоріть із ним, щоб випити ліки й очиститися від отрути Занзіла.",al={"що робити","проходження допомоги гінотта","як завершити завдання"}},{q="Хто такий Серж Гінотт?",a="Серж Гінотт — алхімік і знавець отрут з Відступників, що працює в Таррен Міллі в Передгір'ї Гілсбреда. Він допомагає своїм особливим ремеслом розбійникам Орди, які шукають ліків від незвичних недуг і хочуть опанувати тонкощі приготування отрут.",al={"лор сержа гінотта","хто такий гінотт","аптекар таррен мілл"}},{q="Чому отрута так вражає Сержа Гінотта?",a="Гінотт вважає рецепт Занзіла дивом алхімічного задуму через могутнє поєднання повзучого божевілля й фізичного виснаження. Навіть знешкоджуючи його, він відверто захоплюється майстерністю, з якою створено таке руйнівне вариво.",al={"реакція гінотта на отруту","чому гінотту подобається"}},{q="Що за стійкий запах згадує Гінотт?",a="Суміш Занзіла має різкий, нудотний сморід, що в'їдається в пори жертви. Протиотрута Гінотта успішно спиняє дію отрути й прояснює розум, але не одразу позбавляє від гидкого смороду, що лишається.",al={"чому смердить","запах божевілля","запах завдання"}},{q="Яка нагорода за це завдання?",a="Це завдання знімає затяжне ослаблення, підхоплене під час класового ланцюжка розбійників, і відкриває шлях до вміння Отрути розбійника, з яким гравці можуть варити власні виснажливі отрути для клинків.",al={"що отримають розбійники","нагорода допомоги гінотта"}},{q="Де здавати це завдання?",a="Завдання починається й завершується просто в Сержа Гінотта в Таррен Міллі, на півночі Передгір'я Гілсбреда.",al={"де гінотт","місце здавання"}}},fp="19,279,19.460.0,26.398.1,40.200.0,20.237.0,44.239.0,44.244.0,45.206.0,30.118.0"}
P.entries["quest:249"] = {n="Морґант",s="Морґант — завдання-кульмінація, що завершує довге розслідування мага Теокрітуса щодо зловісного суперника, який засів у Редріджі. Шукачам пригод доручено зупинити темного чорнокнижника, що шукає давню реліквію жахливої сили, — для цього треба прорватися до Вежі Ілґалара й покласти край його підступам.",h="Морґант — завдання-кульмінація, що завершує довге розслідування мага Теокрітуса щодо зловісного суперника...",kw={"морґант","теокрітус","вежа ілґалара","вежа азори","коса елуни","амулет тіні","чорнокнижник"},ang={["class:Mage"]="Теокрітус уособлює сумлінну вчену традицію людських магів, які з високих веж стежать за чаклунами-ренегатами, оберігаючи королівство.",["class:Warlock"]="Морґант уособлює небезпеку неприборканих прагнень до скверни й тіні: хто тягнеться до реліквій на кшталт Коси Елуни, той швидко накликає на себе загибель.",["faction:Alliance"]="Перемога над Морґантом захищає вразливі східні кордони Стормвінда, щоб край Редрідж не поринув у темне чаклунство.",["race:NightElf"]="Чутки про Косу Елуни в людських руках мали б глибоко стривожити калдореїв, адже ім'я цієї реліквії зачіпає священні й небезпечні таємниці."},sec={{t="Пильне око за кордоном",b="Зі свого святилища у Вежі Азори на сході Лісу Елвінн маг Теокрітус пильно стежив за скелями Редріджу за допомогою віщувальних чарів. Те, що він побачив, підтвердило його найгірші побоювання: чорнокнижник Морґант, що засів у Вежі Ілґалара, наполегливо шукав легендарну Косу Елуни. Збагнувши, що чорнокнижник ось-ось заволодіє цією темною могутністю, Теокрітус закликав відважних звитяжців Альянсу втрутитися, поки тінь Морґанта не впала на все королівство Стормвінд."},{t="Штурм вежі",b="Вежа Ілґалара височіє над улоговиною Редріджу; довкола неї кишать гноли й вирують викривлені таємні енергії. На її вершині чекав Морґант, озброєний тіньовою магією, що беріг свої дослідження. Щоб зійтися з чорнокнижником, треба було пройти ворожими землями, знищити заклинача власноруч і забрати його Амулет Тіні як незаперечний доказ того, що вежа впала, а загрозу знищено."},{t="Тінь Коси не зникає",b="Хоч перемога над Морґантом усуває нагальну й катастрофічну загрозу для Стормвінда, його пошуки Коси Елуни показують, як далеко сягає темна легенда цього артефакту. Теокрітус полегшено зітхає, отримавши Амулет Тіні, та справжнє місце, де лежить давня коса, і лихо, яке вона може накликати, лишаються тривожною таємницею для всіх довколишніх провінцій."}},faq={{q="Хто такий Морґант?",a="Морґант — могутній чорнокнижник-ренегат, що живе на вершині Вежі Ілґалара в Горах Редріджу. Він вивчає темні мистецтва й шукає Косу Елуни — артефакт, здатний вивільнити згубну магію.",al={"особа морґанта","хто такий морґант","передісторія морґанта"}},{q="Де стоїть Вежа Ілґалара?",a="Вежа Ілґалара — на північно-східних висотах Гір Редріджу, на північ від Озера Незрушне, за таборами гнолів на Хребтовому Мисі.",al={"місце вежі ілґалара","де вежа морґанта","вежа редріджа"}},{q="Чому Теокрітус хоче смерті Морґанта?",a="За допомогою ясновидіння Теокрітус дізнався, що Морґант полює на Косу Елуни, і злякався, що чорнокнижник от-от її здобуде. Така темна сила стала б катастрофічною загрозою для Редріджу й сусіднього королівства Стормвінд.",al={"мотив теокрітуса","чому вбити морґанта","причина завдання теокрітуса"}},{q="Що таке Коса Елуни?",a="Коса Елуни — давній, оповитий таємницею артефакт, знаний величезною хаотичною силою, що може спотворювати звірів, закликати кошмарних потвор і псувати магію. Чорнокнижники й темні чаклуни жадають її заради величезної тіньової енергії, яку вона вивільняє.",al={"лор коси елуни","що таке коса","чому коса небезпечна"}},{q="Що таке Амулет Тіні?",a="Амулет Тіні — магічний талісман Морґанта: і знаряддя для його темних мистецтв, і незаперечний доказ його поразки, коли його приносять Теокрітусові у Вежу Азори.",al={"підвіска тіні","підвіска морґанта","доказ смерті морґанта"}},{q="Який ланцюжок завдань веде до цього?",a="Це завдання — фінал ланцюжка з чотирьох частин, що починається з «Пошуків для Теокрітуса» в Лісі Елвінн, далі йдуть «Пильне око» й «Шукати далі», де треба здобути знаряддя й налаштувати ясновидіння, щоб стежити за вежею Морґанта.",al={"ланцюжок морґанта","передумови морґанта","як відкрити морґанта"}}},fp="8,293,27.510.0,18.392.0,29.391.1,16.235.0,30.168.0,39.245.0,28.250.0,30.192.0,34.236.0"}
P.entries["quest:2498"] = {n="Повернення до Деналана",s="«Повернення до Деналана» — завдання Альянсу, що пов'язує ботаніків, які досліджують зіпсуття в Тельдрассилі. Вивчивши мохові нарости, що вразили місцевих деревляників, Релліан Ґрінспайр відсилає вас назад на південь, до Озера Ал'Амет, допомогти Деналанові з тривожним новим відкриттям.",h="«Повернення до Деналана» — завдання Альянсу, що пов'язує ботаніків, які досліджують зіпсуття в Тельдрассилі.",kw={"деналан","релліан ґрінспайр","деревляники","озеро ал'амет","тельдрассил","зіпсуття"},ang={["class:Druid"]="Дослідження неприродних пухлин на лісових духах зачіпає саму суть покликання Кола Кенарія — берегти природну рівновагу й очищати підступну пошесть.",["race:NightElf"]="Деревляники — живе втілення життєвої сили Тельдрассила; допомогти Деналанові — частина священного обов'язку зцілити зіпсуття, що загрожує новій домівці вашого народу."},sec={{t="Звістка крізь гілля",b="Оглядаючи дивні мохові пухлини на деревляниках Тельдрассила, Релліан Ґрінспайр одержує термінову звістку від свого колеги Деналана. Деналан, що облаштувався на тихому березі Озера Ал'Амет, гадає, що нарешті виявив причину цих неприродних наростів на духах лісу. Усвідомлюючи, наскільки це серйозно, Релліан негайно відряджає вас назад на південь — підставити плече."},{t="Загроза біля озера",b="Дослідження Деналана біля Озера Ал'Амет мають вирішальне значення для розуміння недуг, що розповзаються молодим Світовим Деревом. Те, що починалося як вивчення зіпсутих рослин і хворих деревляників, швидко переростає у відкрите протистояння з ураженими створіннями, які отруюють гілля, — і першим із них стає зіпсутий деревляник Похмуродуб."}},faq={{q="Хто такий Деналан?",a="Деналан — дослідник і природознавець з нічних ельфів, що працює біля Озера Ал'Амет на півдні Тельдрассила. Він вивчає рослинність острова, дивні мутації паростків і неприродні недуги, що поширюються серед місцевих деревляників.",al={"деналан лор","хто такий деналан","деналан озеро ал'амет"}},{q="Чому Релліан Ґрінспайр посилає вас назад до Озера Ал'Амет?",a="Релліан отримує звістку, що Деналан, схоже, знайшов причину пухлин, які спотворюють деревляників. Ситуація стрімко розвивається й дедалі більше загрожує лісові, тож Релліан посилає вас негайно допомогти на місці.",al={"чому назад до деналана","завдання релліана ґрінспайра"}},{q="Що за пухлини вражають деревляників?",a="Деревляники — мирні духи природи, народжені з рослин острова, але всепроникна скверна, що вкорінюється на Тельдрассилі, змушує їх обростати дивними моховитими наростами. Ці пухлини роблять істот ворожими й шаленими.",al={"пухлини деревляників","чому в деревляників пухлини","мохові пухлини"}},{q="Де знайти Деналана?",a="Деналан отаборився на березі Озера Ал'Амет, трохи на південь від Доланаара, у південних лісах Тельдрассила.",al={"місце деналана","де деналан"}},{q="Що буде, коли дістатися Деналана?",a="Деналан радіє вашій допомозі й каже, що натрапив на щось тривожне. Наступне завдання він пояснить, коли ви дістанетеся його табору.",al={"що далі","продовження похмуродуба"}},{q="Як це доручення пов'язує Релліана й Деналана?",a="The errand links Rellian Greenspyre's timberling research in Darnassus to Denalan's camp at Lake Al'Ameth, carrying Rellian's study of the tumors to Denalan's new discovery about their cause.",al={"чому релліан посилає до деналана","мета повернення до деналана"}}},fp="17,276,27.417.0,22.343.1,15.250.0,59.260.0,47.227.0,25.121.0,37.126.1,49.191.0"}
P.entries["quest:2499"] = {n="Похмуродуб",s="Деналан просить шукачів пригод покласти край Похмуродубові — могутньому деревлянику, якого зіпсував величезний наріст. Знавіснілий звір, що оселився в печері на південному березі Озера Ал'Амет, тепер розносить пошесть серед місцевої живності.",h="Деналан просить шукачів пригод покласти край Похмуродубові — могутньому деревлянику, якого зіпсував...",kw={"похмуродуб","деревляник","деналан","озеро ал'амет","тельдрассил","пухлина"},ang={["class:Druid"]="Бачити деревляника-охоронця, спотвореного дивними пухлинами, — для друїдів моторошне нагадування, що юна екосистема Тельдрассила глибоко хвора.",["profession:Herbalism"]="Травники, що допомагають Деналанові, на власні очі бачать, як рослинне життя під впливом незримої гнилі перетворюється на злоякісну мохову пошесть.",["race:NightElf"]="Трагічне падіння Похмуродуба б'є в саме серце громади нічних ельфів, загрожуючи озеру, що лежить просто в тіні Алдрассила."},sec={{t="Полеглий охоронець",b="Похмуродуб колись був великим проводирем деревляників — лісових духів, що доглядають буйне гілля Тельдрассила. На жаль, зіпсуття, яке повзе Світовим Деревом, не розрізняє простої живності й давніх захисників. Доведений до шалу велетенською пухлиною, що набрякла на його корі, Похмуродуб став посудиною пошесті, а не опікуном росту."},{t="Очищення Озера Ал'Амет",b="Причаївшись у печері на південному березі Озера Ал'Амет, Похмуродуб своєю отруйною присутністю труїть довколишні води й лісових звірів. Деналан, не здатний стати проти чудовиська сам, прагне його знищення не зі злості — а щоб милосердно відтяти джерело зіпсуття й дослідити химерну розрослу пухлину, що мучить духів озера."}},faq={{q="Хто такий Похмуродуб?",a="Похмуродуб — величезний деревляник, дух лісу, пов'язаний з рослинністю Тельдрассила. Колись його шанували як шляхетного ватажка свого роду, аж поки він не став жертвою злоякісного наросту.",al={"хто такий похмуродуб","похмуродуб лор","що за істота похмуродуб"}},{q="Чому Похмуродуба треба знищити?",a="Похмуродуба вразила велетенська пухлина, що затьмарила йому розум і зробила його люто агресивним. Сама його присутність у печері біля Озера Ал'Амет поширює дивну пошесть на сусідніх деревляників і звірів.",al={"чому вбити похмуродуба","похмуродуб ворожий"}},{q="Де живе Похмуродуб?",a="Похмуродуб живе глибоко в печері на південному березі Озера Ал'Амет на півдні Тельдрассила.",al={"місце похмуродуба","де печера похмуродуба"}},{q="Хто такий Деналан і чому він вивчає пухлину?",a="Деналан — травник і природознавець, що живе на східному березі Озера Ал'Амет. Він вивчає рослини й тварин Світового Дерева, прагнучи зрозуміти й вилікувати дивну гниль, що вражає місцевих деревляників.",al={"хто дає завдання похмуродуба","деналан похмуродуб"}},{q="Що спричинило пухлину на Похмуродубі?",a="Пухлина — ознака глибшої, підступної хвороби, що повзе ґрунтом і корінням Тельдрассила й нівечить духів природи зсередини.",al={"чому в деревляників пухлини","джерело скверни"}},{q="Чи Похмуродуба вже не врятувати?",a="Коли шукачі пригод зустрічають його, недуга зайшла надто далеко. Пухлина цілком спотворила істоту, і Деналанові не лишається нічого іншого, як просити милосердно її вбити.",al={"чи можна вилікувати похмуродуба","вилікувати похмуродуба"}}},fp="10,235,17.379.0,21.354.0,19.184.0,33.228.0,29.113.0,48.228.0,36.144.0,28.179.0"}
P.entries["quest:25"] = {n="Глухий кут у Кам'яному Кігті",s="«Глухий кут у Кам'яному Кігті» — доручення Орди від Мастока Врайлгісса із Застави Розщепленого Дерева: треба вберегти важливий прохід до Гір Кам'яного Кігтя. Опоганені водяні елементалі в Озері Містраль зупинили обози з припасами, тож Орда винищує ворожих духів і розвідує ельфійську альтанку, з якої видно пересування Альянсу неподалік.",h="«Глухий кут у Кам'яному Кігті» — доручення Орди від Мастока Врайлгісса із Застави Розщепленого Дерева: треба...",kw={"глухий кут у кам'яному кігті","масток врайлгісс","озеро містраль","стежка глибокого кігтя","тайдресс","завдання"},ang={["class:Shaman"]="Спотворений стан водяних елементалів Озера Містраль розкриває глибокий розлад стихій, що пускає коріння в прадавніх лісах Ашенвалю.",["faction:Horde"]="Застава Розщепленого Дерева не вистоїть без відкритих шляхів постачання; убезпечити Стежку Глибокого Кігтя вкрай важливо, щоб підтримувати зв'язок і торгівлю з Кам'яним Кігтем.",["race:Orc"]="Воїни Орди залежать від деревини й стежок Ашенвалю, без яких не вижити їхнім поселенням, тож перерізані гірські шляхи постачання — неприпустимі."},sec={{t="Задушений шлях постачання",b="Щоб утримати опору Орди в Ашенвалі, потрібен безперервний потік деревини, припасів і гінців між лісом і вершинами Гір Кам'яного Кігтя. Ця важлива артерія — Стежка Глибокого Кігтя — пролягає повз західний берег Озера Містраль. Коли води раптом ожили й закипіли ворожими елементалями, рух намертво зупинився. Обози потрапляли під удари розлючених водяних духів, і Масток Врайлгісс вимагає діяти негайно, поки шляхи постачання не обвалилися остаточно."},{t="Зіпсовані води",b="Озеро Містраль більше не тихий лісовий прихисток. Елементалі, що пливуть у його глибинах, стали опоганеними, агресивними й непередбачуваними: вони навмання б'ють кожного, хто намагається пройти довколишніми стежками. Винищити цих водяних почвар — і зламати владу могутнішого духа Тайдресс — вкрай важливо, щоб повернути бодай якусь безпеку. Та походження їхньої порчі лишається зловісною загадкою посеред ширшого сум'яття, що охопило священні гаї Ашенвалю."},{t="Очі над водою",b="Окрім приборкання розлючених духів озера, Орда бачить на центральному острові Озера Містраль стратегічну нагоду. На острівці стоїть прадавня альтанка нічних ельфів, звідки відкривається чудовий огляд через воду на сусіднє поселення нічних ельфів — Притулок Срібного Вітру. Обстеживши споруду, розвідники Орди з'ясовують, чи можуть руїни стати передовим спостережним постом, щоб командири Розщепленого Дерева могли непомітно пильнувати своїх суперників на Калімдорі."}},faq={{q="Що спричинило глухий кут біля Кам'яного Кігтя?",a="Опоганені водяні елементалі, що живуть в Озері Містраль, розлютилися й нападають на мандрівників на сусідній Стежці Глибокого Кігтя. Через цю агресію зупинилися перевезення припасів між Ашенвалем і Горами Кам'яного Кігтя.",al={"чому транспорт зупинився","стежка глибокого кігтя заблокована","що зупинило шлях постачання"}},{q="Хто наказує позбутися елементалів?",a="Масток Врайлгісс, орк із Застави Розщепленого Дерева на сході Ашенвалю, дає це доручення, щоб відновити торговельні шляхи Орди й розвідати позиції Альянсу.",al={"хто дає глухий кут у кам'яному кігті","завдання масток врайлгісс","хто такий масток"}},{q="Навіщо розвідувати альтанку посеред Озера Містраль?",a="Альтанка дає високу оглядову точку над озером і дивиться просто на сусідній табір Альянсу. Масток хоче оцінити її як таємний спостережний пост, щоб стежити за пересуванням ворога.",al={"навіщо розвідувати альтанку","призначення альтанки озера містраль","спостережний пункт альтанки"}},{q="Що таке Стежка Глибокого Кігтя?",a="Стежка Глибокого Кігтя — головна гірська стежка, що сполучає південно-західні краї Ашенвалю з Горами Кам'яного Кігтя й пролягає просто повз західний берег Озера Містраль.",al={"місце стежки глибокого кігтя","шлях до кам'яного кігтя","дорога кам'яного кігтя"}},{q="Чому водяні елементалі Озера Містраль опоганені?",a="Темна енергія й повсюдне сум'яття в Ашенвалі порушили природну рівновагу: духи Озера Містраль збожеволіли, і їхні зазвичай спокійні води стали ворожими до чужинців.",al={"чому елементалі опоганені","вода озера містраль опоганена","походження опоганених елементалів"}},{q="За якою заставою Альянсу стежать з альтанки?",a="Альтанка дивиться на Притулок Срібного Вітру — поселення нічних ельфів трохи на північ від озера, яке стережуть Вартові, що боронять Ашенваль від лісозаготівель Орди.",al={"яка застава альянсу біля озера містраль","застава альянсу ашенваль"}}},fp="21,348,21.541.0,20.486.0,21.491.0,47.227.0,34.165.0,51.195.0,27.184.0,54.190.0,56.177.0"}
P.entries["quest:250"] = {n="Насувається темна загроза",s="Головний Інженер Гіндервір VII боїться, що після нападів у Багнокраї наступною ціллю дворфів Темного Заліза стане Каменетесна Гребля. Більшу частину залоги греблі перекинули деінде, тож шукачів пригод посилають розвідати, що роблять сапери Темного Заліза, які чатують біля східного схилу.",h="Головний Інженер Гіндервір VII боїться, що після нападів у Багнокраї наступною ціллю дворфів Темного Заліза...",kw={"насувається темна загроза","каменетесна гребля","гіндервір","темне залізо","сапери","лох модан","завдання"},ang={["faction:Alliance"]="Поки фронтові армії розпорошені по всьому континенту, новобранці Альянсу мусять заповнити прогалину й захистити важливі тилові вузли постачання та споруди краю.",["profession:Engineering"]="Інженери оцінять і захопливий розмах греблі, і підступну небезпеку саперів, що закладають нестійку хімічну вибухівку під несучі підвалини.",["race:Dwarf"]="Каменетесна Гребля — шедевр дворфійського ремесла й предмет гордості; бачити, як їй загрожують підступні родичі з Темного Заліза, — і розслідування стає справою оборони всього народу."},sec={{t="Беззахисне диво",b="Каменетесна Гребля — одна з найвеличніших інженерних звитяг Айронфорджа, що стримує неосяжні води Лох Модану. Проте через війни в Каз Модані й за його межами більшу частину охорони греблі перекинули на фронт Альянсу. Через нестачу вояків Головний Інженер Гіндервір VII і його нечисленна команда майже беззахисні перед злагодженим нападом — і саме тоді, коли вороги підкрадаються дедалі ближче до велетенської споруди."},{t="Відлуння з півночі",b="Тривога Гіндервіра має підстави: на північ від кордону нещодавно сталося лихо. Дворфи Темного Заліза завдали смертоносного злагодженого удару в Багнокраї: пошкодили стратегічний Міст Тандол і розграбували місто-фортецю Дун Модр. Помітивши відомих саперів Темного Заліза, що снують біля східного схилу греблі, Гіндервір розпізнає закономірність: клан-відщепенець націлився знищити наступною життєву артерію озера."},{t="Підозріла бочка",b="Розвідка нижніх укріплень підтверджує найгірші побоювання інженера. Серед скель, де збиралися сапери, стоїть покинута, підозріла бочка, напхана нестійким, дивно пахучим порошком. Це прямий доказ того, що Темне Залізо щосили готує підрив, аби розколоти фундамент Каменетесної Греблі."}},faq={{q="Чому Головного Інженера Гіндервіра непокоїть гребля?",a="Сили Темного Заліза нещодавно спустошили північні гарнізони: пошкодили Міст Тандол і пограбували Дун Модр. Побачивши саперів Темного Заліза, що никали біля східного пандуса Каменетесної Греблі, Гіндервір переконався, що наступна їхня ціль — гребля.",al={"чому гіндервір турбується","загроза каменетесній греблі","чому нападати на греблю"}},{q="Куди подівся гарнізон греблі?",a="Більшість охорони Каменетесної Греблі, зокрема найкращого інспектора Гіндервіра, перевели на підтримку ширшого фронту Альянсу, тож ця важлива споруда лишилася майже без захисту.",al={"чому на греблі немає вартових","охорона греблі","де солдати"}},{q="Що знаходять біля східного пандуса?",a="Біля східного пандуса, де помітили саперів Темного Заліза, слідчі знаходять підозрілу бочку з дивним пахучим порошком — це підтверджує, що дворфи Темного Заліза закладають вибухівку, щоб зруйнувати споруду.",al={"яка зачіпка","зачіпка підозрілої бочки","що роблять сапери"}},{q="Яке стратегічне значення має Каменетесна Гребля?",a="Каменетесна Гребля стримує водосховище Лох Модану. Якщо її прорве, потоп завдасть величезних руйнувань нижче за течією, у Багнокраї, і водночас осушить серце дворфійських земель.",al={"чому знищити греблю","що якщо гребля прорветься","лор греблі"}},{q="Що за напад на Дун Модр згадує Гіндервір?",a="Дун Модр — укріплена дворфійська застава на півночі Багнокраю, біля Мосту Тандол. Диверсанти Темного Заліза захопили містечко й ударили по сусідньому Мосту Тандол, перерізавши важливі суходільні шляхи постачання.",al={"напад на дун модр","що сталося в дун модрі","знищення мосту тандол"}},{q="Хто такі дворфи Темного Заліза, що метять у Лох Модан?",a="Клан Темного Заліза — запеклі суперники дворфів Бронзбірдів ще з часів Війни Трьох Молотів. Діючи з Гори Блекрок і Палючої Ущелини, вони раз у раз шкодять спорудам і прикордонній обороні Бронзбірдів.",al={"хто такі темного заліза","мотив саперів темного заліза","чому темне залізо ненавидить айронфордж"}}},fp="19,296,19.451.0,21.422.0,19.330.1,55.245.0,32.204.0,37.226.1,59.198.0,56.211.0,51.241.0"}
P.entries["quest:251"] = {n="Перекласти записку Аберкромбі",s="«Перекласти записку Аберкромбі» — завдання Альянсу в Даркширі, у якому шукач пригод несе нерозбірливий лист до міського вченого. Лорд Елло Ебонлок не може второпати послання відлюдника й покладається на знання Сірри Вон'Інді про маловідомі письмена. Саме тоді провід Даркшира усвідомлює, що за дивними дорученнями Аберкромбі ховається щось значно навмисніше.",h="«Перекласти записку Аберкромбі» — завдання Альянсу в Даркширі, у якому шукач пригод несе нерозбірливий лист...",kw={"перекласти записку аберкромбі","аберкромбі","сірра вон'інді","елло ебонлок","даркшир","шифр"},ang={["class:Mage"]="Маги, обізнані з маловідомими діалектами й чародійськими транскрипціями, оцінять роль Сірри Вон'Інді як місцевого знавця езотеричних письмен у Даркширі.",["faction:Alliance"]="Для захисників Альянсу, що допомагають Сутінколіссю, це доручення показує, наскільки вразливим і самотнім почувається провід Даркшира серед темряви довкола."},sec={{t="Нерозбірливе послання",b="Коли Аберкромбі надсилає меру Елло Ебонлоку запечатаний лист, той чекає від цвинтарного відлюдника дивакуватого прохання чи гіркого белькотіння. Натомість пергамент списаний дивним, загадковим письмом, зовсім не схожим на звичайну загальну мову. Не маючи вченої підготовки, щоб розшифрувати стародавні чи езотеричні мови, мер Ебонлок усе ж не відкидає листа: він знає, що в Сутінколіссі навіть божевільний відлюдник може становити загрозу."},{t="Учений Даркшира",b="Щоб розгадати шифр, Ебонлок посилає мандрівників через площу до Сірри Вон'Інді. Сірра — знавець езотеричних знань Даркшира, обізнаний у стародавніх мистецтвах і забутих мовах. Хоч Сірра й кепкує з розуму Аберкромбі — мовляв, у того, хто живе біля проклятого цвинтаря, мізки, певно, давно згнили, — він ставиться до пергаменту досить серйозно, щоб узятися за копітку роботу з переписування."},{t="Зазирнути в думки відлюдника",b="Переданий лист запускає для міста похмуре викриття. Досі Аберкромбі здавався кволим старим самітником, що випрошує припаси й захист від гулів, але його зашифрований лист до мера видає значно темніший розум — і неминучу розплату, до якої Даркшир зовсім не готовий."}},faq={{q="Чому мер Ебонлок не може сам прочитати записку?",a="Лист від Аберкромбі написаний незвичним письмом чи давнім шифром. Мер Елло Ебонлок — урядовець і шляхтич, а не мовознавець, тож він віддає його Сіррі Вон'Інді — даркширському знавцеві давніх мистецтв і таємних мов.",al={"чому елло не прочитає записку","переклад листа ебонлока","навіщо перекладач"}},{q="Хто такий Сірра Вон'Інді?",a="Сірра Вон'Інді — учений мешканець Даркшира. Знаний своїми знаннями маловідомих мов, історії й давніх мистецтв, він — той учений, до якого містечко звертається щоразу, коли з темного лісу з'являються загадкові тексти чи реліквії.",al={"хто такий сірра вон'інді","хто перекладач","науковець даркшира"}},{q="Де живе Аберкромбі?",a="Аберкромбі живе в убогій халупі трохи на північний схід від Цвинтаря Воронячого Пагорба на заході Сутінколісся, серед неспокійної нежиті й хижих звірів.",al={"де аберкромбі","місце самітника","аберкромбі сутінколісся"}},{q="Як Сірра реагує на записку Аберкромбі?",a="Сірра відверто сумнівається в здоровому глузді Аберкромбі й зауважує, що в того, хто готовий жити поруч із цвинтарем, мабуть, мізки згнили. Проте він погоджується оглянути лист і береться перекладати його таємниче письмо.",al={"що сірра думає про аберкромбі","діалог сірри вон'інді"}},{q="Що буде, коли віддати записку Сіррі?",a="Сірра Вон'Інді просить шукача пригод зачекати, поки він розшифровує текст. Коли переклад готовий, вміст розкриває справжні наміри Аберкромбі, і загроза для Даркшира зростає.",al={"наступне завдання після перекладу записки","що після перекладу записки аберкромбі"}},{q="Чому Аберкромбі написав мерові Ебонлоку?",a="Аберкромбі надіслав записку під виглядом листування з керівництвом містечка, але сховав свої слова за таємним письмом, щоб приховати зловісні задуми, доки не буде готовий ударити.",al={"чому аберкромбі надіслав лист","мета записки самітника"}}},fp="28,401,25.450.0,24.403.0,32.329.1,48.261.0,22.238.0,28.158.0,47.214.0,44.203.1,45.181.1"}
P.entries["quest:2518"] = {n="Сльози Місяця",s="«Сльози Місяця» — скорботне завдання, яке дає Жриця А'мура в Храмі Місяця. Велика павучиха Леді Сатра, колись улюблениця богині Елуни, поринула в безумство, і Сестринство Елуни мусить подарувати їй милосердну смерть і забрати її священні павутинні залози.",h="«Сльози Місяця» — скорботне завдання, яке дає Жриця А'мура в Храмі Місяця.",kw={"сльози місяця","леді сатра","жриця а'мура","храм місяця","сестринство елуни","павучиха","озеро джерела"},ang={["class:Druid"]="Друїди бачать у раптовій люті й муках Сатри ще один тривожний симптом розладу Тельдрассилу, тож відновити її дух — необхідність для рівноваги природи.",["class:Priest"]="Жерці Сестринства Елуни розуміють, що милосердя часом потребує скорботного удару, а завершує його обрядова пожертва, яка повертає зіпсовану душу в обійми Богині.",["race:NightElf"]="Для калдореїв смерть Сатри — болісне нагадування, що скверна, яка торкнулася диких куточків Тельдрассилу, не милує ні простого звіра, ні священних супутників Елуни."},sec={{t="Падіння улюбленої істоти",b="У спокійних стінах Храму Місяця в Дарнасусі Жриця А'мура оплакує трагічну долю Леді Сатри. Колись Сатру шанували як благословенне створіння Елуни. Під нічним небом вона ткала тонку сріблясту павутину, що ловила вечірній туман, який осідав на гіллі Тельдрассилу. Мерехтлива роса, зібрана її павутиною, мала дивовижну цілющу силу, і Сестринство Елуни дбайливо збирало й зберігало її для своїх священних обрядів."},{t="Милосердя для Сатри",b="Як і чимало звірів на молодому Світовому Древі, Леді Сатра недавно стала жертвою нестримного безумства. Її скверна загрожує не лише мандрівникам, а й її власним ще не вилупленим виводкам на північних околицях біля Озера Джерела. Не маючи змоги очистити її, доки вона шаленіє й лютує, Сестринство вирішило, що припинити її страждання — єдиний милосердний шлях, який лишився. Здобувши її сріблясті павутинні залози, жриці хочуть покласти її рештки на вівтар Елуни й молитися, щоб Богиня Місяця дарувала їй спокій і чисте відродження."}},faq={{q="Хто така Леді Сатра?",a="Леді Сатра — велична давня павучиха, споконвічна мешканка Тельдрассила. Здавна її шанували як улюбленицю Елуни, і вона славилася тим, що плела сріблясті тенета, які вловлювали нічний туман, сповнений природної цілющої сили.",al={"лор леді сатри","хто така леді сатра","передісторія сатри","павучиха сатра"}},{q="Чому Леді Сатру доводиться вбити?",a="Її опанувало повзуче божевілля, що вразило звірів Тельдрассила. Вона стала люто нестямною й небезпечною і для свого потомства, і для інших, тож жриці вирішили, що вбити її — це милосердя.",al={"чому вбити сатру","чи можна врятувати сатру","чому сатра агресивна"}},{q="Де знайти Леді Сатру?",a="Леді Сатра влаштувала лігво в північній глушині Тельдрассила, біля берегів Озера Джерела.",al={"місце леді сатри","де сатра","знайти сатру"}},{q="Для чого використовували тенета Леді Сатри?",a="Її тенета вловлювали вечірній туман, і з нього утворювалася потужна срібляста роса, знана глибокою цілющою силою, — Сестринство Елуни зберігало її в Храмі Місяця.",al={"значення сліз місяця","для чого тенета сатри","лор сріблястої роси"}},{q="Хто дає завдання «Сльози Місяця»?",a="Жриця А'мура, служниця Храму Місяця в Дарнасусі, дає це завдання довіреним шукачам пригод з Альянсу.",al={"хто дає сльози місяця","хто дає завдання сльози місяця","жриця а'мура"}},{q="Що жриці зроблять з павутинними залозами Сатри?",a="Їх приносять Елуні на храмовому вівтарі як освячення, просячи богиню прийняти дух Сатри, благословити її й дати їй відродитися в мирному спокої.",al={"що буде з павутинними залозами","призначення павутинних залоз","жертва елуні"}}},fp="17,276,25.482.0,17.570.1,20.203.0,40.218.0,28.105.0,39.159.0,38.132.0,55.174.0"}
P.entries["quest:2519"] = {n="Храм Місяця",s="«Храм Місяця» — вступне завдання в Дарнасусі, у якому Сестра Аквінн скеровує шукачів пригод до Жриці А'мури. Сестринству Елуни потрібна допомога для стражденної прадавньої істоти, що живе в гіллі Тельдрассилу. Це перший заклик до скорботного обряду милосердя.",h="«Храм Місяця» — вступне завдання в Дарнасусі, у якому Сестра Аквінн скеровує шукачів пригод до Жриці А'мури.",kw={"храм місяця","сестра аквінн","жриця а'мура","храмові сади","сестринство елуни","дарнасус"},ang={["class:Druid"]="Друїди глибоко переймаються кожною великою дикою істотою в біді, тож заклик із Храмових Садів для них — нагальна справа природної гармонії.",["class:Priest"]="Жерців, що ходять Дарнасусом, природно вабить праця Сестринства: вони допомагають іншим служителям божественного в обрядах зцілення й милосердя.",["race:NightElf"]="Для нічних ельфів відгукнутися на прохання Сестри Аквінн — частина їхнього обов'язку берегти священну природу Тельдрассилу й шанувати настанови жрецтва Елуни."},sec={{t="Благання в Садах",b="Прогулюючись поміж вод і тінистих гаїв Храмових Садів, мандрівники зустрічають Сестру Аквінн — віддану служительку Елуни. Відчувши вправні руки, вона звертається по допомогу від імені свого ордену. Шанована лісова істота страждає, і Сестри не можуть упоратися з цим самі."},{t="До Храму Місяця",b="Сестра Аквінн скеровує охочих до величного Храму Місяця, що на південний схід звідти. Там Жриця А'мура керує обрядами й практичними справами, потрібними, щоб допомогти неспокійним звірам Тельдрассилу, і готує співчутливих союзників до скорботного обов'язку милосердя."}},faq={{q="Хто дає завдання «Храм Місяця»?",a="Завдання дає Сестра Аквінн. Вона стоїть надворі, у кварталі Храмових Садів Дарнасуса.",al={"хто дає завдання храм місяця","де взяти храм місяця","хто дає храм місяця"}},{q="Де знайти Жрицю А'муру?",a="Жриця А'мура — у величному Храмі Місяця, трохи на південний схід від Храмових Садів у Дарнасусі.",al={"де жриця а'мура","знайти а'муру","місце жриці а'мури"}},{q="Що за створіння потребує допомоги?",a="Ідеться про Сатру — шановану павучиху Тельдрассила, чия біда веде до обряду милосердя під наглядом жриць.",al={"яке створіння потребує допомоги","хто лісове створіння","про що цей ланцюжок"}},{q="Чи обов'язкове це завдання, щоб продовжити ланцюжок?",a="Ні. «Храм Місяця» — необов'язкове завдання-підказка. Можна одразу поговорити з Жрицею А'мурою в храмі й узятися за обрядові завдання, не заходячи спершу до Сестри Аквінн.",al={"чи храм місяця обов'язковий","чи можна пропустити храм місяця","храм місяця хлібні крихти"}},{q="Яке завдання йде після цього?",a="Жриця А'мура пропонує завдання «Сльози Місяця» й посилає вас по священні матеріали, потрібні, щоб очистити Сатру й упокоїти її.",al={"наступне завдання після храму місяця","продовження храму місяця","що далі"}},{q="Чому Сестринство Елуни просить допомоги в чужинців?",a="Скверна, що засіла в рослинах і тваринах Тельдрассила, виснажує сили Сестринства, тож жриці мусять залучати вправних мандрівників, які шанують природу й Богиню.",al={"чому просять чужинців","чому жриці потрібна допомога","мотив сестри аквінни"}}},fp="22,303,21.286.0,20.283.0,44.114.0,35.125.0,37.137.0,46.199.0,34.137.0,57.181.0"}
P.entries["quest:252"] = {n="Переклад для Елло",s="«Переклад для Елло» — ключове завдання в історії Аберкромбі в Сутінколіссі. Попросивши Сірру Вон'Інді розшифрувати загадкові записи відлюдника, шукач пригод має доставити перекладений пергамент просто Лордові Елло Ебонлоку в Даркширі.",h="«Переклад для Елло» — ключове завдання в історії Аберкромбі в Сутінколіссі.",kw={"переклад для елло","аберкромбі","сірра вон'інді","елло ебонлок","стітчес","даркшир"},ang={["faction:Alliance"]="Для захисників Альянсу ця мить — болісний урок підступності Сутінколісся: недоречна довіра в лісі може наразити на небезпеку ціле поселення безневинних людей."},sec={{t="Запізніле прозріння",b="Кілька днів старий відлюдник Аберкромбі ганяв мандрівників із дорученнями по всьому Сутінколіссю, вдаючи кволого старого, що ледве виживає. Він просив нитку, законсервовані реагенти й особисті речі. Лише коли Сірра Вон'Інді нарешті розшифровує його таємний пергамент, правда виходить назовні: добрий старий — божевільний бальзамувальник, а зібрані складники пішли на страхітливу зброю помсти, спрямовану просто на Даркшир."},{t="Дорога до Даркшира",b="Коли Лорд Елло Ебонлок читає перекладений лист, з обличчя мера збігає вся барва. Хай якими шляхетними були наміри шукача пригод, доставлені ним останні припаси дали Аберкромбі змогу завершити своє жахливе творіння — Стітчеса. Щойно лист передано, велетень рушає просто на схід дорогою від Цвинтаря Воронячого Пагорба, вбиваючи кожен патруль Нічної Варти на своєму шляху."}},faq={{q="Що написано в перекладеному листі?",a="Сірра боїться, що Аберкромбі накоїв щось невимовне. Перекладений лист треба терміново віднести Лордові Елло Ебонлоку, який зможе оцінити небезпеку для Даркшира.",al={"що в листі","текст листа аберкромбі","що перекладено"}},{q="Хто такий Сірра Вон'Інді?",a="Сірра Вон'Інді — учений з Даркшира. Його мовознавчі й аналітичні знання дають йому змогу розшифрувати таємничі записки й листи Аберкромбі, коли інші не можуть прочитати його письма.",al={"хто такий сірра","сірра вон'інді лор"}},{q="Чому лорд Елло звинувачує гравця?",a="Як відреагує Лорд Елло, стане відомо, коли він прочитає перекладений лист. Розслідування вимагає якнайшвидше донести йому це застереження.",al={"чому елло сердиться","чи я спричинив стітчес","реакція елло"}},{q="Що відбувається одразу після цього завдання?",a="Віднесіть перекладений лист Лордові Елло Ебонлоку в Даркшир. Його відповідь і небезпека, про яку попереджає лист, з'ясуються, коли він його прочитає.",al={"що викликає стітчес","чи з'являється стітчес","подія стітчес"}},{q="Куди йде Стітчес після цього?",a="Стітчес пов'язаний із дорогою між Цвинтарем Воронячого Пагорба й Даркширом. Його роль у задумі Аберкромбі розкривається під час розслідування.",al={"шлях стітчеса","куди йде стітчес"}},{q="Яке завдання далі?",a="Після доставки листа лорд Елло посилає шукачів пригод розслідувати решту підступів Аберкромбі в завданні «Наречена Бальзамувальника», щоб викорінити інші задуми некроманта.",al={"наступне завдання","після перекладу для елло"}}},fp="19,263,21.435.1,21.418.1,41.169.2,22.206.0,36.145.2,53.137.2,34.149.2,22.212.1"}
P.entries["quest:2520"] = {n="Жертва Сатри",s="«Жертва Сатри» — завершення скорботного обряду в Храмі Місяця в Дарнасусі. Гравцям довіряють рештки Леді Сатри: вони підносять павутинні залози полеглої істоти священним водам Елуни, щоб очистити її душу від скверни й упокоїти її дух.",h="«Жертва Сатри» — завершення скорботного обряду в Храмі Місяця в Дарнасусі.",kw={"жертва сатри","леді сатра","храм місяця","жриця а'мура","очищення","сестринство елуни","фонтан"},ang={["class:Druid"]="Друїди, що оплакують хворобу, яка точить Тельдрассил, знаходять розраду в тому, що полеглих звірів можна очищенням повернути до природного кола життя.",["class:Priest"]="Жерці в Храмі Місяця на власні очі бачать, як святе світло Елуни та священні води зцілюють душі, розірвані безумством і скверною.",["race:NightElf"]="Для нічних ельфів цей обряд — вияв їхнього урочистого обов'язку перед рослинами й тваринами Калімдору: навіть коли істоту доводиться вбити, її дух шанують і очищають благодаттю Елуни."},sec={{t="Очищення у священних водах",b="Після трагічної загибелі Леді Сатри Жриця А'мура покладає на посвячуваних останній духовний обов'язок. Велика павучиха стала жертвою темного безумства, що ширилося Тельдрассилом, і її колись мирна вдача обернулася безтямною люттю. Жрецтво Елуни не вважає її смерть простим відстрілом — воно прагне спасти її полеглу сутність. Коли її сріблясті павутинні залози кладуть у центральний фонтан Храму Місяця, освячені води змивають скверну й дарують їй звільнення."},{t="Оновлення Сатри",b="Пожертва Елуні одразу приносить духовне єднання. Щойно залози торкаються осяяного місяцем басейну, з глибини здіймається примарна постать Леді Сатри — спокійна й очищена від недуги, що звела її з розуму. Сестринство Елуни вважає цей обряд необхідним спасінням: утрата великої істоти болить, але віра нічних ельфів учить, що завдяки священному очищенню вона колись зможе відродитися з незаплямованим духом."}},faq={{q="Ким була Леді Сатра?",a="Леді Сатра була великою павучихою з Тельдрассила, яку опанувала повзуча скверна, що вразила звірів Світового Дерева. Збожеволілу від скверни, її довелося вбити, щоб освятити її останки.",al={"леді сатра","хто така сатра","що таке сатра"}},{q="Де приносять жертву?",a="Жертву кладуть у святий фонтан посеред Храму Місяця — головного святилища Сестринства Елуни в Дарнасусі.",al={"де покласти жертву","місце фонтана","фонтан храму"}},{q="Що відбувається, коли покласти павутинні залози у фонтан?",a="Коли сріблясті залози занурюються в благословенні води, у басейні ненадовго з'являється очищений Дух Сатри: він вільно й спокійно ходить, і це знак, що Елуна прийняла жертву.",al={"що буде біля фонтана","дух сатри фонтан"}},{q="Чому Леді Сатра мусила загинути?",a="Скверна, що отруїла її розум, засіла надто глибоко, щоб вилікувати її живою. Жриця А'мура й Сестринство вірили, що єдиний спосіб урятувати її душу — припинити її страждання й очистити останки святими водами Елуни.",al={"чому сатра мусила загинути","чи можна було врятувати сатру","божевілля сатри"}},{q="Хто дає завдання «Жертва Сатри»?",a="Завдання дає й приймає Жриця А'мура, що служить у Храмі Місяця в Дарнасусі, над центральною залою.",al={"хто дає завдання","куди здати","місце а'мури"}},{q="На якій вірі нічних ельфів тримається цей обряд?",a="Нічні ельфи вірять, що душі, очищені Матір'ю-Місяцем, можуть відродитися в природному світі з оновленим і чистим духом, вільним від стійкої плями скверни.",al={"реінкарнація нічних ельфів","очищення елуни","лор відродження"}}},fp="19,288,28.530.0,22.470.1,21.213.0,31.158.0,59.182.1,33.217.0,40.144.0,54.185.0"}
P.entries["quest:253"] = {n="Наречена бальзамувальника",s="«Наречена бальзамувальника» — небезпечне доручення Лорда Елло Ебонлока в Даркширі. Склавши докупи тривожну правду про легендарного Бальзамувальника, провід міста посилає вас на прокляті цвинтарі Сутінколісся знайти місце спочинку його воскреслої дружини. Вирвавши живе серце алхіміка з проклятих решток Елізи, ви позбавите його нечестивої сили.",h="«Наречена бальзамувальника» — небезпечне доручення Лорда Елло Ебонлока в Даркширі.",kw={"наречена бальзамувальника","бальзамувальник","еліза","елло ебонлок","серце","даркшир"},ang={["class:Paladin"]="Паладини бачать у мерзенному оживленні Елізи образу Світла й природного ладу, тож охоче знищують цю трупоїдну потвору й перерізають блюзнірську рятівну нитку некроманта.",["class:Priest"]="Жерці розуміють трагедію вдівця, що з горя піддався темним мистецтвам, але знають: спрагла плоті пародія на життя, якою стала Еліза, мусить бути остаточно упокоєна святою силою.",["faction:Alliance"]="Нічна Варта ледве встигає відбиватися від диких жахіть Сутінколісся, тож захисник Альянсу мусить стати на оборону Даркшира від цього давнього, повзучого божевілля."},sec={{t="Казка на ніч, що ожила",b="Роками батьки в Сутінколіссі лякали дітей казкою про Бальзамувальника. За переказом, колись він був добрим алхіміком, але розум його розколовся після трагічної смерті коханої дружини Елізи. У відчайдушному прагненні обдурити смерть він звернувся до мерзенного чаклунства й пішов на найвищу жертву: вирізав власне серце, що ще билося, і вклав його в груди дружини. Лорд Елло Ебонлок довго вважав це звичайною сільською байкою, але останні викриття довели: Бальзамувальник ходить серед них, а його мерзенна робота гноїться під цвинтарною землею."},{t="Воскресла наречена",b="Обряд таки повернув Елізу до руху, але темна некромантія завжди бере жахливу плату. Оживлена викраденою іскрою життя, Еліза обернулася на ненажерливу потвору, прокляту невситимим голодом до живої людської плоті. Нажаханий, але не здатний знищити своє творіння, Бальзамувальник змушений був сховати наречену в самотній могилі, таємно навідуючи її й задумуючи нові мерзоти. Щоб роззброїти некроманта, Лорд Ебонлок посилає відважних розкопати могилу Елізи, знищити спраглу плоті потвору й забрати ще пульсуючий орган, що живить його темне мистецтво."},{t="Щит Даркшира",b="Коли ви вириваєте серце, що ще б'ється, з напівзотлілих грудей Елізи й приносите його до Даркшира, Лорд Ебонлок полегшено зітхає. Мер не збирається просто знищити серце — він хоче обернути темне ремесло алхіміка проти нього самого. Він вірить, що моторошна магія, яка лишилася в серці, стане оберегом і щитом для Даркшира й убереже знесилене місто від будь-якого гніву, який ослаблений Бальзамувальник ще міг би накликати з помсти."}},faq={{q="Хто такий Бальзамувальник?",a="Бальзамувальник колись був алхіміком у Сутінколіссі й збожеволів, коли померла його дружина Еліза. Вдавшись до некромантії, він вирізав власне живе серце й поклав його в тіло Елізи, щоб воскресити її, а сам перетворився на невловну потвору.",al={"лор бальзамувальника","хто такий бальзамувальник","передісторія бальзамувальника"}},{q="Чому Елізу поховали, якщо її повернули до життя?",a="Алхімікові вдалося оживити Елізу власним серцем, але темна магія прокляла її ненаситним голодом до живої людської плоті. Не маючи змоги безпечно тримати її серед людей чи вгамувати її звірячий апетит, він мусив тримати її похованою на цвинтарі.",al={"чому еліза похована","могила елізи","чому еліза в могилі"}},{q="Навіщо лордові Ебонлоку Серце Бальзамувальника?",a="According to the tale Ello recounts, the heart is the source of the Embalmer's power. He asks you to retrieve it from Eliza's grave while it still beats, believing this will break that power.",al={"навіщо взяти серце","призначення серця бальзамувальника"}},{q="Звідки починається цей ланцюжок завдань?",a="Завдання йде безпосередньо за «Перекладом для Елло», де лордові Елло Ебонлоку доставляють старі листи й дослідження, що доводять: Бальзамувальник з місцевих дитячих страшилок — цілком реальна й небезпечна загроза.",al={"передумова завдання","як отримати наречену бальзамувальника","попереднє завдання бальзамувальника"}},{q="Чи здобуте серце назавжди долає Бальзамувальника?",a="Ello believes that retrieving the heart will break the Embalmer's power. The result of the mission is revealed when you return to Darkshire.",al={"чи бальзамувальник мертвий","чи це вбиває бальзамувальника"}},{q="Хто дає це завдання?",a="Лорд Елло Ебонлок, мер і очільник Даркшира, дає завдання в Ратуші Даркшира, дізнавшись моторошну правду, що стоїть за місцевими переказами.",al={"хто дає завдання","хто починає наречену бальзамувальника"}}},fp="21,386,26.579.0,21.604.1,17.464.2,20.253.0,53.261.0,50.191.0,34.210.0,58.140.1,21.162.0"}
P.entries["quest:254"] = {n="Копирсаючись у землі",s="«Копирсаючись у землі» — похмурий фінал пошуків зниклого серця Бальзамувальника в Сутінколіссі. У зловісній тиші Цвинтаря Воронячого Пагорба розворушена купа землі приховує поховане жахіття, що не бажає лишатися мертвим.",h="«Копирсаючись у землі» — похмурий фінал пошуків зниклого серця Бальзамувальника в Сутінколіссі.",kw={"копирсаючись у землі","еліза","бальзамувальник","аберкромбі","цвинтар воронячого пагорба","могила"},ang={["class:Paladin"]="Розкопувати свіжі могили — проти всіх похоронних обрядів Святого Світла, але вивільнити й знищити протиприродну потвору, замкнену всередині, — необхідний акт очищення.",["class:Priest"]="Шкрябання пазурів і скрегіт зубів під освяченою землею — образа вічного спокою, який Світло обіцяє померлим Сутінколісся.",["faction:Alliance"]="Нічна Варта невпинно бореться з жахіттями, що сунуть із Воронячого Пагорба; викорінити приховані Бальзамувальником жахіття конче потрібно для безпеки Даркшира."},sec={{t="Потривожена могила",b="Серед незліченних вивітрених надгробків Цвинтаря Воронячого Пагорба є клапоть нещодавно скопаної, ще пухкої землі з ім'ям Еліза. Чимало могил Сутінколісся осквернили падальники чи дикі гулі, але цю землю насипали навмисне. Розкопавши верхній шар, натрапляєш на розколоті дошки закопаної труни, у якій Бальзамувальник прагнув сховати від денного світла те, що від неї лишилося."},{t="Шкрябання зсередини",b="Під розколотими дошками лежить зовсім не спокійний мрець. Притиснувши віко, можна відчути шалене тремтіння — несамовите шкрябання довгих пазуристих пальців і глухе клацання гнилих щелеп. Моторошний експеримент Аберкромбі, Еліза, люто ворушиться у своїй сосновій в'язниці, а в її грудях б'ється зникле серце Бальзамувальника, — і вона чекає, доки необачні руки розкриють могилу."}},faq={{q="Що поховано в могилі Елізи?",a="Під землею — труна з Елізою, потворою-нежиттю, яку створив Бальзамувальник. Її замурували під землею з власним серцем Бальзамувальника в грудях.",al={"що в могилі","хто така еліза","вміст могили елізи"}},{q="Де ця могила?",a="Могила Елізи — на Цвинтарі Воронячого Пагорба на заході Сутінколісся, серед моря примарних склепів і блукаючої нежиті.",al={"де могила елізи","місце могили елізи","місце землі з могили"}},{q="Навіщо розкопувати труну?",a="Треба розкопати могилу, щоб зійтися з Елізою й забрати серце Бальзамувальника, завершивши розслідування його збочених задумів.",al={"чому розкопувати","мета розкопування","навіщо відкривати труну"}},{q="Що буде, коли відкрити труну?",a="Відкрита труна випускає Елізу з її неглибокої в'язниці, і вам доведеться знищити цю дряпучу, ненажерливу гуль, щоб забрати серце, замкнене разом із нею.",al={"що далі","труну відкрито","відкриття труни елізи"}},{q="Хто поклав Елізу в землю?",a="Її поклав туди Бальзамувальник, сховавши своє моторошне творіння разом зі своїм дорогоцінним серцем на розлогому цвинтарі Воронячого Пагорба.",al={"хто поховав елізу","хто її туди поклав"}},{q="Чи Еліза — звичайна гуль?",a="Еліза — покійна дружина самого Бальзамувальника, оживлена його темною магією з його серцем у грудях; вона значно сильніша й розважливіша за безмозких гулів, що никають шляхами Сутінколісся.",al={"що за монстр еліза","чи еліза гуль"}}},fp="24,239,17.422.0,21.384.1,32.188.1,28.122.0,39.157.1,39.161.1,28.141.1,27.186.1"}
P.entries["quest:2541"] = {n="Сплячий друїд",s="Глибоко в Курганному Лігві Бан'етіл сплячий нічний ельф Обен Рейджклов опинився у страшній магічній пастці. Ворожі шамани фурболґів Вузлошкірів відтяли його сновидний дух від тіла й мерзенними чарами оживили його плоть, зробивши з неї навіженого вартового.",h="Глибоко в Курганному Лігві Бан'етіл сплячий нічний ельф Обен Рейджклов опинився у страшній магічній пастці.",kw={"обен рейджклов","курганне лігво бан'етіл","вузлошкіри","шамани","вуду","смарагдовий сон","тельдрассил"},ang={["class:Druid"]="Для друїдів доля Обена — жах наяву: коли тіло викрадають, поки ви єднаєтеся зі Смарагдовим Сном, це руйнує саму основу друїдського сну.",["race:NightElf"]="Осквернення Курганного Лігва Бан'етіл показує, як низько впали фурболґи Вузлошкіри від своєї давньої спорідненості з калдореями."},sec={{t="Порушений сон",b="Друїди нічних ельфів сходять у курганні лігва по всьому Калімдору, щоб століттями спілкуватися з природою уві сні: їхні духи блукають Смарагдовим Сном, поки смертні тіла спочивають у кам'яних нішах. Але зіпсуття, що вразило Тельдрассил, штовхнуло місцеве плем'я фурболґів Вузлошкірів до відчайдушної дикості. У Курганному Лігві Бан'етіл шамани Вузлошкірів знайшли спосіб прорвати освячений спокій Обена Рейджклова й вирвати його живий дух зі сплячої оболонки."},{t="Вуду й зіпсуття",b="Замість убити Обена, шамани Вузлошкірів скористалися зловісним талісманом — Шаманським Вудуйським Оберегом — і силоміць оживили його порожню оболонку. Безпорадно ув'язнений у Смарагдовому Сні, вигнаний дух Обена може лише дивитися, як його тіло блукає коридорами й наосліп нападає на кожного, хто ступить до лігва. Щоб розплутати чари й знайти шлях до повернення тіла, його примарна проєкція доручає шукачам пригод здобути один з оберегів Вузлошкірів для вивчення."}},faq={{q="Хто такий Обен Рейджклов?",a="Обен Рейджклов — друїд з нічних ельфів, що поринув у священний сон у Курганному Лігві Бан'етіл, щоб поєднатися зі Смарагдовим Сном. Ворожі фурболги-Вузлошкіри заволоділи його тілом, і дух лишився без оселі.",al={"обен рейджклов","хто сплячий друїд","сплячий нічний ельф у лігві"}},{q="Чому тіло Обена нападає на людей?",a="Шамани Вузлошкірів провели обряд, що відділив свідомість Обена від плоті. Вони оживили його порожнє тіло темною магією, щоб воно було лютим вартовим у глибинах курганного лігва.",al={"чому обен ворожий","чому обен нападає","тіло обена нападає"}},{q="Що таке Шаманський Вудуйський Оберіг?",a="Це зачароване знаряддя, яке носять шамани Вузлошкірів у Курганному Лігві Бан'етіл. Його темною силою вони виривають духи сплячих друїдів з тіл і оживлюють порожні оболонки.",al={"шаманський оберіг","вудуйський оберіг тельдрассил","що таке вудуйський оберіг"}},{q="Де справжній дух Обена під час завдання?",a="Свідомість Обена блукає Смарагдовим Сном і не може повернутися до смертного тіла. З дійсним світом він може спілкуватися лише як мерехтливий дух біля місця свого спочинку.",al={"де обен","місце духа обена","смарагдовий сон обен"}},{q="Чому фурболги в Курганному Лігві Бан'етіл ворожі?",a="Плем'я Вузлошкірів стало жертвою скверни й божевілля, що наростають і нівечать звірів і ліси Тельдрассила, тож вони обернулися проти колишніх союзників — нічних ельфів — і оскверняють святі місця друїдів.",al={"чому вузлошкіри ворожі","скверна фурболгів тельдрассил","чому фурболги агресивні"}},{q="Чи можна врятувати тіло Обена, не вбиваючи його?",a="Перша надія Обена розірвати обряд — вивчити Шаманський Вудуйський Оберіг. Дослідивши мерзенні чари, що сковують його плоть, він сподівається зрозуміти цю магію й знайти вихід.",al={"врятувати обена рейджклова","чи можна врятувати обена","вилікувати обена"}}},fp="18,273,19.481.0,21.466.1,21.217.0,36.213.0,32.199.0,45.188.0,53.210.0,44.202.0"}
P.entries["quest:255"] = {n="Найманці",s="«Найманці» — угода про винагороду від Магістрата Блантноуза в Телсамарі: треба проредити огрів Мо'ґрош, що підступають у північно-східному Лох Модані. Військове підкріплення з Айронфорджа загрузло в місяцях бюрократичної тяганини, тож магістрат мусить наймати мандрівних шукачів пригод, щоб захистити вразливі поселення долини, розкопки й життєво важливу Каменетесну Греблю.",h="«Найманці» — угода про винагороду від Магістрата Блантноуза в Телсамарі: треба проредити огрів Мо'ґрош, що...",kw={"найманці","магістрат блантноуз","телсамар","огри","мо'ґрош","каменетесна гребля","лох модан"},ang={["faction:Alliance"]="Лох Модан — важливий коридор між Каз Моданом і північними королівствами; якщо огрячі набіги кинуть його в хаос, під загрозою опиняться шляхи постачання Альянсу по всіх Східних Королівствах.",["race:Dwarf"]="Перлина дворфійської інженерії — Каменетесна Гребля — лишилася без охорони через тяганину в Айронфорджі, тож заклик Блантноуза до зброї — особиста справа для кожного горянина чи мандрівника зі столиці."},sec={{t="Повільні колеса Айронфорджа",b="Телсамар на власній шкурі відчуває дворфійську бюрократію. Айронфорджу знадобилося цілих два місяці, щоб лише пообіцяти жменьку вояків на підсилення місцевої оборони Лох Модану, і ще два місяці мине, перш ніж ці загони мають прибути. Міська варта вже на межі сил, і Магістрат Блантноуз не може дозволити собі чекати чотири місяці, поки ворожі сили збираються просто за кордонами долини."},{t="Загроза в пагорбах",b="Огри Мо'ґрош укріпили табір у пагорбах на північний схід від озера. Їх дедалі більшає, і вони загрожують не лише Телсамару, а й Місцю розкопок Айронбенда та самій Каменетесній Греблі. Якщо на греблю нападуть чи пошкодять її, руйнування нижче за течією будуть нищівні. Офіційних загонів горян немає, тож Блантноуз звернувся до вільних найманців, щоб проредити лави огрів і виграти для долини час проти огрів і трогів."}},faq={{q="Чому Магістрат Блантноуз наймає найманців, а не користується вартою?",a="Айронфордж нестерпно повільно відповідає на благання Лох Модану про допомогу. Сенатові знадобилося два місяці, щоб ухвалити відправку бодай жмені солдатів, і ще два, поки вони справді прибудуть. Телсамарові, греблі й місцевим розкопкам загрожує безпосередня небезпека, тож Блантноузові не лишається нічого іншого, як платити незалежним шукачам пригод.",al={"чому наймати найманців","вартові телсамара","допомога айронфорджа"}},{q="Де живуть огри Мо'ґрош?",a="Огри Мо'ґрош населяють Твердиню Мо'ґрошів серед суворих круч і пагорбів на північний схід від великого озера Лох Модану.",al={"де огри","де мо'ґрош","табір мо'ґрош"}},{q="Чому Каменетесній Греблі загрожує небезпека?",a="Каменетесна Гребля регулює все озеро й є архітектурною перлиною дворфів. Військової оборони майже немає, а огри Мо'ґрош отаборилися неподалік, тож Блантноуз боїться, що організований напад пошкодить чи зруйнує величезну споруду й спричинить катастрофічну повінь.",al={"чому захищати греблю","огри і гребля"}},{q="Які ще загрози, крім огрів, нависли над Телсамаром?",a="По всьому озеру з підземних руїн і розкопок вирвалися троги. Блантноуз вважає їх величезною загрозою, але груба сила сусідньої твердині огрів змушує його наймати бійців, щоб відкинути Мо'ґрошів, а місцева варта могла зосередитися на трогах.",al={"інші загрози лох модану","загроза трогів"}}},fp="11,378,23.393.0,23.479.0,71.338.0,37.129.0,49.303.0,59.285.0"}
P.entries["quest:256"] = {n="РОЗШУКУЄТЬСЯ: Чок'сул",s="Оголошення, вивішене в Телсамарі Магістратом Блантноузом, закликає вбити Чок'сула — огрячого воєводу, що загрожує північно-східному Лох Модану. Вважають, що саме він організовує напади на місцеві поселення й важливі споруди, тож його голова принесе щедру нагороду від міської влади.",h="Оголошення, вивішене в Телсамарі Магістратом Блантноузом, закликає вбити Чок'сула — огрячого воєводу, що...",kw={"розшукується чок'сул","чок'сул","огри","магістрат блантноуз","телсамар","винагорода","лох модан"},ang={["faction:Alliance"]="Лох Модан — головний хліборобський і постачальний коридор до Дун Мороґу, тож спокій довкола Телсамара вкрай важливий для військових зусиль Альянсу.",["profession:Engineering"]="Каменетесна Гребля — одне з найвеличніших досягнень дворфійського будівництва; дозволити грубим огрям її пошкодити — немислимо для будь-якого поважного майстра.",["race:Dwarf"]="Захист Каменетесної Греблі й довколишніх археологічних розкопок — справа дворфійської гордості, спадщини й безпеки суверенних земель Айронфорджа."},sec={{t="Загроза озерному краю",b="Троги й дика звірина раз у раз пробують на міцність кордони Лох Модану, але поява злагоджених огрів — це вже загострення, якого місцеві дворфійські горяни не можуть не помічати. Отаборившись на суворих північно-східних околицях долини, ці звірюки вже не обмежуються простим грабунком. За словами місцевих розвідників і міської влади, їхні набіги цілеспрямовані, наполегливі й небезпечні."},{t="Ціна за голову Чок'сула",b="Магістрат Телсамара Блантноуз з'ясував, що Чок'сул — призвідник нападів на місто, на сусідні дворфійські розкопки й на саму Каменетесну Греблю. Боячись нищівної шкоди для гордості долини — її інженерного дива — і для життів мирних мешканців, магістрат оголосив винагороду за голову огрячого ватажка: мертвим будь-якою ціною, а як доказ потрібна його відтята голова."}},faq={{q="Хто оголосив винагороду за Чок'сула?",a="Магістрат Блантноуз, головний урядовець Телсамара, офіційно видав наказ від імені містечка, щоб захистити край від організованих набігів.",al={"хто хоче смерті чок'сула","хто призначив винагороду за чок'сула","плакат розшукується телсамар"}},{q="Чому Чок'сул — така важлива ціль?",a="Вважають, що саме Чок'сул спрямовує напади огрів на Телсамар, археологічні розкопки Айронфорджа й Каменетесну Греблю — а це і життя дворфів, і найважливіші споруди королівства.",al={"чому вбити чок'сула","що зробив чок'сул","загроза чок'сула"}},{q="Де знайти Чок'сула?",a="Він у таборі огрів серед суворих пагорбів у північно-східному куті Лох Модану.",al={"місце чок'сула","де чок'сул","табір огрів лох модан"}},{q="Який доказ потрібен Магістратові Блантноузу?",a="Треба принести відрубану голову Чок'сула просто Магістратові Блантноузу в Телсамар, щоб отримати винагороду й вдячність Айронфорджа.",al={"голова чок'сула","доказ винагороди","здати чок'сула"}},{q="Навіщо ограм нападати на Каменетесну Греблю?",a="Каменетесна Гребля стримує величезне озеро Лох Модану й є вершиною дворфійської інженерії. Зруйнувавши її, можна затопити Багнокрай і зірвати дворфійське постачання, тож для ворожих сил це першорядна тактична ціль.",al={"чому нападати на греблю","напад на каменетесну греблю"}},{q="Чи є інші огри, що діють разом із Чок'сулом?",a="Так, Чок'сул командує табором огрів на північно-східних пагорбах біля озера й спрямовує їхні набіги на довколишні землі.",al={"клан чок'сула","огри лох модану","прибічники чок'сула"}}},fp="16,301,20.404.0,28.402.0,34.154.0,55.232.0,28.110.0,45.134.0,44.240.0,44.154.0"}
P.entries["quest:2561"] = {n="Друїд Пазура",s="Глибоко в курганах Тельдрассила примарна подоба Обена Рейджклова просить про трагічне звільнення. Зіпсуті фурболґи наклали темні чари на його тілесну оболонку, тож вам доведеться знищити бездушну шкаралупу й розірвати пута, щоб його дух повернувся до Смарагдового Сну.",h="Глибоко в курганах Тельдрассила примарна подоба Обена Рейджклова просить про трагічне звільнення.",kw={"друїд пазура","обен рейджклов","вузлошкіри","вуду","смарагдовий сон","курган","тельдрассил"},ang={["class:Druid"]="Бачити сплячого Друїда Пазура, оскверненого зіпсутими фурболґами, — моторошне нагадування про те, як небезпечно залишати тіло без нагляду, єднаючись зі Смарагдовим Сном.",["race:NightElf"]="Тельдрассил мав стати прихистком для нічних ельфів, та стрімке зіпсуття корінних фурболґів, таких як Вузлошкіри, несе безпосередню загрозу навіть у їхніх священних курганах."},sec={{t="Відтятий дух",b="Спочиваючи в курганах під Тельдрассилом, Обен Рейджклов зазнав жахливої долі. Зіпсуті фурболґи Вузлошкіри наклали на його сонне тіло мерзенні чари вуду й відтяли дух від смертної плоті. Ув'язнений у Смарагдовому Сні, дух Обена блукає поблизу, не маючи ні спокою, ні змоги повернути собі тіло."},{t="Милосердя до плоті",b="Вивчення вудуйського оберега Вузлошкірів відкрило гірку правду: тілесна оболонка Обена цілком у владі фурболґів. Щоб зруйнувати чари, шукач пригод має зайти до сусідньої зали, здолати безтямну, ворожу подобу Обена Рейджклова й застосувати над його рештками оберіг фурболґів — лише так можна остаточно розбити магію, що тримає його душу."}},faq={{q="Чому я мушу вбити Обена Рейджклова?",a="Фурболги-Вузлошкіри наклали на Обена могутні вудуйські чари, поки він спав, і перетворили його тіло на бездушну маріонетку. Його плоть цілком у їхній владі, тож знищити тіло — єдиний спосіб розірвати чари й звільнити його дух.",al={"чому вбити обена","убити сплячого друїда","тіло обена рейджклова"}},{q="Для чого потрібен Вудуйський Талісман?",a="Талісман — ключ до чарів, що керують Обеном. Коли ви вб'єте його зіпсоване бездушне тіло, скористайтеся талісманом над останками — і темна магія, що тримає його дух у полоні, розплететься.",al={"навіщо вудуйський талісман","як користуватися талісманом","талісман вузлошкірів обен"}},{q="Куди йде Обен після цього завдання?",a="Коли його тіло вбито, а чари розвіяно, дух Обена Рейджклова звільняється від смертного світу. Нарешті він може вирушити в Смарагдовий Сон і спочити з миром.",al={"доля обена","що з обеном рейджкловом","чи обен виживе"}},{q="Чому Вузлошкіри вдаються до вуду?",a="Фурболги-Вузлошкіри глибоко занурилися в скверну й божевілля, відвернулися від споконвічної гармонії й узялися за мерзенне чаклунство й грубу темну магію, щоб підкорити створінь і сплячих друїдів довкола.",al={"вузлошкіри вудуйські","вуду вузлошкірів","чому фурболги мають обереги"}},{q="Ким був Обен Рейджклов?",a="Обен — нічний ельф, Друїд Пазура, що поринув у священний сон у курганах Тельдрассила, поєднуючись зі Смарагдовим Сном, аж поки фурболги-Вузлошкіри не порушили його спочинок і не поневолили його смертну оболонку.",al={"хто такий обен","обен лор","передісторія обена"}},{q="Чи говорить зі мною дух Обена, поки його тіло живе?",a="Так. Темні чари відірвали душу Обена від плоті. Його дух з'явився примарою біля входу до зали й аж ніяк не може керувати зачарованою порожньою оболонкою всередині чи повернутися в неї.",al={"дух і тіло обена","два обени","чому обен у двох місцях"}}},fp="17,284,16.324.0,19.345.1,36.287.0,34.201.0,36.194.1,41.219.0,22.210.0,61.197.0"}
P.entries["quest:257"] = {n="Похвальба мисливця",s="«Похвальба мисливця» — мисливське випробування на час, яке влаштовує Деріл Молодий на Хуторі Далекоходів у Лох Модані. Прагнучи похизуватися своєю нібито майстерністю, зарозумілий юнак підбурює шукачів пригод вистежити й убити шість гірських канюків, перш ніж мине п'ятнадцять хвилин.",h="«Похвальба мисливця» — мисливське випробування на час, яке влаштовує Деріл Молодий на Хуторі Далекоходів у...",kw={"похвальба мисливця","деріл молодий","хутір далекоходів","канюки","полювання","мисливець"},ang={["class:Hunter"]="Для стрільців і слідопитів змагання Деріла — кумедна нагода перестріляти хвалькуватого новачка на його ж землі й здобути надійний лук чи рушницю.",["faction:Alliance"]="Хутір Далекоходів — важлива застава Альянсу на південно-східних шляхах Лох Модану: тут дають прихисток і звідси вирушають на полювання суворими долинами.",["race:Dwarf"]="Бувалі горяни впізнають у Дерілових вихилясах класичну юнацьку браваду, на яку найкраще відповідати спокійною вправністю."},sec={{t="Зарозумілість молодого стрільця",b="Хутір Далекоходів — місце, де збираються найкращі слідопити й стрільці Каз Модану, але не всі під його дахом мають скромність бувалих мисливців. Деріл Молодий, який сам себе величає «Дерілом Сміливим», зверхньо відмахується від мандрівних шукачів пригод. Певний, що жовторотим чужинцям далеко до дворфійської мисливської вправності, він зухвало б'ється об заклад: уполюйте пів дюжини місцевих гірських канюків за чверть години — або визнайте поразку."},{t="Проріджуючи стерв'ятників",b="Гірські канюки кружляють над скелями й схилами Лох Модану, підбираючи рештки й полюючи на дрібнішу звірину. Зграєю вони небезпечні, але передусім це просте випробування мисливської швидкості, терпіння й влучності. Ті, хто вкладається в суворий час, швидко збивають пиху з Деріла: він неохоче розлучається з одним зі своїх луків чи рушниць — і готує нові мисливські виклики."}},faq={{q="Де відбувається це мисливське випробування?",a="Завдання починається на Хуторі Далекоходів у південно-східній глушині Лох Модану. Гірські канюки, на яких треба полювати, никають довколишніми скелями й відкритими хребтами по всьому краю.",al={"місце випробування","де деріл","де канюки"}},{q="Хто такий Деріл Молодий?",a="Деріл Молодий — честолюбний хвалькуватий юнак, що зупинився на Хуторі Далекоходів. Він звеличує себе «Дерілом Сміливим» і любить підбурювати мандрівників на мисливські випробування на час, щоб довести свою вигадану перевагу.",al={"хто такий деріл","деріл молодий лор","деріл далекоходець"}},{q="Чому на полювання дано обмежений час?",a="П'ятнадцять хвилин — частина Дерілового заліку. Він вважає, що вполювати диких канюків поспіхом — річ, звичайному шукачеві пригод не під силу.",al={"чому п'ятнадцять хвилин","таймер завдання","випробування на час"}},{q="Що буде, коли ви виграєте Дерілів виклик?",a="Приголомшений вашим успіхом, Деріл однаково не визнає справжньої поразки. Він дотримує слова й дає зброю, а тоді одразу пропонує нове полювання — «Виклик мисливця» — на більшу дичину.",al={"що далі","продовження похвальби","ланцюжок мисливця"}},{q="Чому полюють саме на гірських канюків?",a="Зграї гірських канюків гніздяться на скелястих схилах Лох Модану. Ці спритні летючі цілі якнайкраще перевіряють, чи має лучник або стрілець справжню польову дисципліну.",al={"чому канюки","призначення канюків","канюки лох модану"}},{q="Чи пов'язане це завдання з іншими справами Хутора Далекоходів?",a="Так. Перевірки Деріла ведуть просто до ширшої низки полювань для хутора, що завершується вистежуванням Старого Сажотлапа — ведмедя, який лишив шрами на Дерілові, — як частина задуму Вирина Свіфтвінда провчити хвалькуватого юнака.",al={"зв'язок з вірином","історія хутора","сюжет далекоходців"}}},fp="16,272,28.463.0,23.445.0,45.183.0,27.216.0,38.168.0,45.202.1,40.182.0,62.222.1"}
P.entries["quest:258"] = {n="Виклик мисливця",s="«Виклик мисливця» — мисливське випробування на час від зухвалого юнака Деріла Молодого з Хутора Далекоходів у південно-східному Лох Модані. Роздратований тим, що не зміг применшити ваш попередній успіх, Деріл закладається на останню сорочку, що ви не вистежите й не вполюєте п'ятьох старих гірських кабанів за дванадцять хвилин. Завдання перевіряє, наскільки швидко шукач пригод упорається з суворою місциною й небезпечною звіриною нагір'я.",h="«Виклик мисливця» — мисливське випробування на час від зухвалого юнака Деріла Молодого з Хутора Далекоходів у...",kw={"виклик мисливця","деріл молодий","хутір далекоходів","гірські кабани","полювання","лох модан"},ang={["class:Hunter"]="Для знавців слідів вистежити п'ятьох старих гірських кабанів у чагарях нагір'я за суворо відміряний час — класичне випробування вміння керувати полюванням і швидко добивати здобич.",["faction:Alliance"]="Хутір Далекоходів — важливий збірний пункт для лісовиків Альянсу, що захищають східний кордон Лох Модану від диких звірів і загроз нагір'я.",["race:Dwarf"]="Кожен дворф, що пройшов Долину Холодного Хребта, одразу збагне Дерілове порівняння, хоч витерпіти його поблажливий тон важче."},sec={{t="Юнацька похвальба",b="Деріл Молодий живе серед бувалих мисливців Хутора Далекоходів, та не має й краплі їхнього тихого терпіння. Брак років він надолужує галасом і перебільшеними мисливськими байками — зокрема довгими оповідками про те, як здобув свій «славетний» шрам. Не бажаючи визнавати чужу вправність, він раз у раз перекручує імена товаришів-мисливців і вигадує суворі випробування, щоб присоромити новачків і повернути собі роздуте шанування серед мешканців хутора."},{t="Полювання на нагір'ї",b="На відміну від простих кабанів Долини Холодного Хребта, де молоді дворфійські розвідники вперше вчаться свого ремесла, старі гірські кабани, що блукають скелями й схилами Лох Модану, величезні, товстошкірі й небезпечні, якщо їх розлютити. Деріл дає мисливцям лише дванадцять хвилин, щоб знайти, убити й підтвердити здобич — п'ятьох таких звірів. Якщо впоратися досить швидко, крикливий юнак ніяково задкує й удає, ніби й гадки не має про той розкішний заклад, який так легковажно уклав."}},faq={{q="Хто такий Деріл Молодий?",a="Деріл — молодий хвалькуватий мисливець-людина з Хутора Далекоходів на південному сході Лох Модану. Відчайдушно прагнучи здаватися таким самим грізним, як старші ветерани довкола, він без угаву вихваляє свою вправність, вигадує гучні оповідки й кидає мандрівним шукачам пригод виклики на складні полювання.",al={"хто такий деріл","деріл молодий лор","хутір далекоходців деріл"}},{q="Де шукати старих гірських вепрів?",a="Старі гірські вепри никають передгір'ями, лугами й хребтами довкола Хутора Далекоходів і на південних і східних просторах Лох Модану. Вони пасуться на пологих узвишшях між хутором і центром озера.",al={"місце старих гірських вепрів","де вепрі","місце полювання на вепрів"}},{q="Чому це полювання на час?",a="Деріл обмежує полювання дванадцятьма хвилинами, бо цілком певен, що ви не впораєтеся. Тісними строками він сподівається осоромити вас і довести, що ваші попередні мисливські успіхи — просто удача новачка.",al={"чому дванадцять хвилин","чому на час","таймер виклику мисливця"}},{q="Про що побився об заклад Деріл?",a="Пояснюючи умови, Деріл зухвало пообіцяв віддати вам останню сорочку, якщо ви вчасно вб'єте п'ятьох старих гірських вепрів. Звісно, коли ви з тріумфом повертаєтеся, він швиденько вдає, що жодного закладу не пам'ятає.",al={"парі деріла","сорочка з плечей","на що побився об заклад деріл"}},{q="Чим вони відрізняються від вепрів Долини Холодного Хребта?",a="Деріл окремо наголошує, що старі гірські вепри значно міцніші й агресивніші за дрібних, сумирних вепрів, на яких полюють дворфи-новачки в Долині Холодного Хребта. Дорослі вепри Лох Модану мають товщу шкуру й небезпечні ікла, нагострені об гірський граніт.",al={"вепри холодного хребта проти гірських","порівняння холодного хребта"}},{q="Куди веде цей мисливський ланцюжок далі?",a="Коли ви втихомирите Дерілову похвальбу, виконавши його виклик, увага на хуторі переходить до серйозніших справ — до сутички з небезпечним старим ведмедем Старим Сажотлапом у завданні «Помста Вирина».",al={"яке завдання далі","після виклику мисливця","мисливська лінія"}}},fp="20,428,15.498.0,17.493.0,27.290.0,43.243.0,23.224.0,24.262.0,48.260.0,40.220.1"}
P.entries["quest:26"] = {n="Урок, який слід засвоїти",s="«Урок, який слід засвоїти» — обряд посвяти для юних друїдів-тауренів, готових опанувати владу над водою. Це завдання дає Турак Рунтотем на висотах Тандер Блафа: воно скеровує учнів до Нічного Притулку в Місячному Гаю, щоб розпочати випробування під проводом Кола Кенарія.",h="«Урок, який слід засвоїти» — обряд посвяти для юних друїдів-тауренів, готових опанувати владу над водою.",kw={"урок, який слід засвоїти","друїд","водяна форма","турак рунтотем","нічний притулок","місячний гай","дендрит старблейз"},ang={["class:Druid"]="Цей обряд знаменує перехід від виживання на суходолі до справжньої гнучкості й відкриває шлях до вміння дихати й рухатися під водою.",["faction:Horde"]="Хоч друїди-таурени й вірні Орді, вони мусять шанувати священний нейтралітет Місячного Гаю, ступаючи пліч-о-пліч із нічними ельфами під спільним покровом Кенарія.",["race:Tauren"]="Це завдання засвідчує міцний зв'язок між друїдами-тауренами з Тандер Блафа й ширшим братством Кенарія, осередок якого — в Місячному Гаю."},sec={{t="Влада над глибинами",b="Опанувавши у формі ведмедя чисту фізичну міць, друїд звертається до гнучкості. Водні шляхи Азероту приховують небезпеки для тих, хто ходить суходолом, і потребують форми, пристосованої до холодних глибин і нищівних течій. Турак Рунтотем уважно стежить за учнями й обирає лише тих, хто довів свою відданість природі, перш ніж відіслати їх на північ вивчати водяну форму."},{t="Дорога до Нічного Притулку",b="Перевтілення у водяну форму вимагає глибокого духовного прозріння, тож учні мусять шукати настанов за межами круч Малгору. Турак велить учням вирушити до Місячного Гаю — священного прихистку під Горою Гіджал. Там, у мирному Нічному Притулку, прадавні наставники Кола Кенарія з нічних ельфів вітають братів і сестер-тауренів, долаючи фракційні чвари заради збереження спільного вчення Кенарія."},{t="Два випробування",b="Зустріч із Дендритом Старблейзом у Нічному Притулку — лише початок. Старійшина нічних ельфів застерігає, що владу над водами не можна просто подарувати — її треба заслужити випробуванням. Він попереджає кандидатів, що на них чекають два виснажливі випробування: одне перевіряє витривалість і самовладання під тиском води, а друге вимагає глибокого духовного розуміння самої водяної форми."}},faq={{q="Хто дає завдання «Урок, який слід засвоїти»?",a="Завдання дає Турак Рунтотем — наставник друїдів, що живе на Узвишші Старійшин у Тандер Блафі. Коли посвячений набереться досвіду, він посилає його по глибшу науку.",al={"хто дає урок, який слід засвоїти","де взяти урок, який слід засвоїти","завдання турака рунетотема"}},{q="Куди треба вирушити, щоб виконати це завдання?",a="Треба дістатися селища Нічний Притулок у священному лісі Місячного Гаю й поговорити з Дендритом Старблейзом з Кола Кенарія.",al={"куди здати урок, який слід засвоїти","місце дендрита старблейза","де нічний притулок"}},{q="До якого вміння веде цей ланцюжок завдань?",a="Це завдання — перший крок ланцюжка, що нагороджує друїдів Водяною подобою: вона дає змогу швидко плавати під водою й дихати під поверхнею скільки завгодно.",al={"яку форму дає","завдання водної форми","навіщо це завдання"}},{q="Чому друїди-таурени йдуть навчатися до нічного ельфа?",a="Коло Кенарія — нейтральне братство, віддане Кенарієві й збереженню природи. У Місячному Гаю політичні чвари між Ордою й Альянсом відкладають, тож нічні ельфи й таурени можуть разом опановувати священні мистецтва.",al={"чому місячний гай","чому дендрит старблейз","ценаріонське коло таурени"}},{q="Про які випробування говорить Дендрит Старблейз?",a="Дендрит пояснює, що вам доведеться пройти два окремі випробування: одне перевірить вашу витримку, коли доводиться діяти під тиском під водою, а друге — вашу духовну рішучість зрозуміти саму подобу.",al={"які два випробування","випробування дендрита","водні випробування"}},{q="Як друїдові на цьому етапі дістатися Місячного Гаю?",a="Друїди мають природний духовний зв'язок, що дарує їм закляття «Телепортація: Місячний Гай», — з ним вони переносяться з будь-якого куточка Азерота просто до спокійного селища Нічний Притулок.",al={"як дістатися місячного гаю","телепорт до місячного гаю","дістатися нічного притулку"}}},fp="17,281,21.406.0,22.424.0,15.395.0,38.190.0,39.150.0,43.182.0,52.251.0,45.220.0,47.177.0"}
P.entries["quest:262"] = {n="Таємнича постать",s="Самітник Свен Йорґен, якого переслідує різанина його родини, доручає вам з'ясувати, хто той таємничий чужинець, якого бачили біля його ферми тієї фатальної ночі. Маючи лише загадкову книгу, знайдену на руїнах, ви мусите розпитати мешканців Даркшира, щоб натрапити на слід чужинця.",h="Самітник Свен Йорґен, якого переслідує різанина його родини, доручає вам з'ясувати, хто той таємничий...",kw={"таємнича постать","свен йорґен","мадам єва","даркшир","книга","сутінколісся"},ang={["class:Priest"]="Розплутуючи віщування Мадам Єви, ви бачите, яка тонка межа між духовним ясновидінням, тіньовою магією й невидимими психічними відбитками, що лишаються на буденних речах.",["faction:Alliance"]="Даркшир не має підтримки Стормвінда, тож його травмовані прикордонники й місцеві віщуни цілком покладаються на мандрівних захисників Альянсу, щоб розслідувати смертоносні звірства в Сутінколіссі."},sec={{t="Відлуння різанини",b="Свен Йорґен переховується на безлюдних пагорбах Сутінколісся, зламаний жахливою різаниною своєї родини й робітників. Спершу він звинувачував таємничих чорних вершників, що тероризують ліс, але пам'ять мучить його ще однією подробицею: тихою темною постаттю, що чаїлася поблизу тієї ночі. Прагнучи відповідей, Свен довіряє вам єдиний речовий доказ, знайдений на згарищі, — дивну книгу, що лишилася на сплюндрованій фермі."},{t="По віщування до міста",b="У небезпечній глушині немає жодних прямих слідів, тож стежка веде назад на схід, до Даркшира. Свен сподівається, що хтось із забобонних містян упізнає дивну книгу. У Даркширі вистачає диваків і медіумів, передусім Мадам Єва: її окультне чуття й віщування дають змогу бачити більше, ніж звичайним оком, і читати духовні відбитки, що лишаються на загадкових реліквіях."},{t="Чужі нитки",b="Мадам Єва, оглянувши книгу, відчуває ледь помітні, але безпомилкові психічні відбитки. Жагуче прагнення Свена помститися нещодавно позначило сторінки, але глибша аура належить зовсім іншій людині. Єва провіщає, що справжній власник не був мешканцем ні Даркшира, ні Сутінколісся, — а отже, до початку кровопролиття фермою ходив чужинець."}},faq={{q="Хто такий Свен Йорґен?",a="Свен Йорґен — убитий горем фермер, що опинився у вигнанні на західних пагорбах Сутінколісся. Після того як темні вершники напали на його садибу й вирізали всю родину, він утік у глушину, охоплений горем, страхом і відчайдушною жагою помсти винним.",al={"хто такий свен","передісторія свена","свен йорґен"}},{q="Що за книгу знайдено на фермі Свена?",a="Книга — річ, знайдена серед землі й уламків зруйнованої садиби Свена. Вона належала невловному спостерігачеві, якого бачили в тінях під час нападу на його родину.",al={"яка це книга","книга з ферми свена","таємнича книга"}},{q="Навіщо нести книгу Мадам Єві?",a="Мадам Єва — даркширська провидиця й ворожка. Звичайні містяни мало що вичитають з неозначеної книги, а Єва ясновидінням читає залишкові психічні відбитки тих, хто володів річчю чи носив її.",al={"чому мадам єва","хто читає книгу","містик даркшира"}},{q="Що Мадам Єва дізнається з книги?",a="Мадам Єва відчуває потужний емоційний відбиток помсти, який лишив Свен, що нещодавно тримав книгу. Проте під ним вона вловлює слабкі сліди, які свідчать, що первісний власник був чужинцем, не з Даркшира.",al={"що каже єва","хазяїн книги","результат ворожіння"}},{q="Куди веде розслідування далі?",a="Дізнавшись, що власник був чужинцем, Мадам Єва посилає вас перебрати інші записи й обійти місця в Даркширі, шукаючи когось, хто пригадає незнайомого мандрівника, схожого на ту постать.",al={"що далі","наступне завдання після книги","хто та таємнича постать"}}},fp="18,315,21.485.0,26.421.0,15.376.1,19.278.0,38.201.0,32.250.0,41.221.1,40.222.1"}
P.entries["quest:263"] = {n="На захист королівських земель",s="Це доручення показує, як загострюється боротьба горян Айронфорджа з навалою трогів у південному Лох Модані. Зі своєї Південної Сторожової Вежі Горянин Воллбанґ посилає досвідчених новобранців у Долину Кам'яного Уламка проредити небезпечних шаманів-трогів і кістколамів передової. Пройшовши це випробування, ви здобуваєте повну довіру Воллбанґа й можливість стати перед капітаном, що командує залогою.",h="Це доручення показує, як загострюється боротьба горян Айронфорджа з навалою трогів у південному Лох Модані.",kw={"на захист королівських земель","горянин воллбанґ","долина кам'яного уламка","троги","шамани","лох модан"},ang={["class:Shaman"]="Сутичка з грубими чаклунами-трогами Кам'яного Уламка показує дику, неотесану земну магію, викривлену звірячими інстинктами.",["faction:Alliance"]="Допомагаючи Південній Сторожовій Вежі, ви зміцнюєте важливі торгові й подорожні шляхи, що з'єднують Дун Мороґ зі східними болотами й королівством Стормвінд.",["race:Dwarf"]="Для кожного дворфа відгукнутися на заклик Воллбанґа — справа захисту рідного дому: ви стаєте на захист хуторів Лох Модану, поки постійні армії ваших родичів воюють далеко за кордоном."},sec={{t="Тонка дворфійська лінія",b="Оборона Лох Модану на межі сил. Регулярні дворфійські резерви скликали на далекі фронти по всьому Азероту, і таким заставам, як Південна Сторожова Вежа, бракує людей. Горянин Воллбанґ і жменька його товаришів зазнають безупинного тиску клану Кам'яного Уламка, тож мусять щосили покладатися на мандрівників з Альянсу, щоб утримати південний перевал."},{t="Удар по авангарду Кам'яного Уламка",b="Цей похід не про те, щоб збивати поодиноких розвідників, — він б'є глибше, по самій верхівці Кам'яного Уламка. Троги-кістколами дають клану грубу силу, а їхні примітивні шамани плетуть земну магію, щоб згуртувати родичів. Знищення двадцятьох таких важливих цілей притуплює їхні вторгнення в низовини й прямо служить обороні королівства Короля Маґні Бронзбірда."}},faq={{q="Хто такий Горянин Воллбанґ?",a="Горянин Воллбанґ — дворф з Айронфорджа на Південній Вартовій Вежі в Лох Модані. Йому доручено стежити за трогами, що просочуються з гір, і координувати ополчення, щоб головний південний шлях лишався безпечним.",al={"воллбанґ","хто такий воллбанґ","горянин воллбанґ лор"}},{q="Чому горяни просять допомоги в мандрівників?",a="Військові резерви Айронфорджа відкликали на важливіші фронти по всьому королівству й за його межами. Через це прикордонним заставам, як-от південним вартовим вежам Лох Модану, вкрай бракує людей проти місцевих загроз.",al={"чому дворфам потрібна допомога","де вартові айронфорджа","чому немає резерву"}},{q="Де шукати цих трогів?",a="Вони густо зібралися в Долині Кам'яного Уламка, захованій серед суворих пагорбів на південний захід від Озера. Невеликі ватаги шаманів і кісткоїдів ховаються й на північних островах посеред самого озера.",al={"де троги кам'яного уламка","місце шамана кам'яного уламка","долина кам'яного уламка"}},{q="Чим загрозливий клан Кам'яного Уламка?",a="Троги швидко плодяться й заполоняють заселені землі суцільними підземними роями. Клан Кам'яного Уламка вдається до грубої стихійної магії через своїх шаманів і покладається на лютих кісткоїдів, щоб шматувати дворфійських розвідників, загрожуючи сусіднім поселенням і торговельним шляхам.",al={"чому троги небезпечні","загроза кам'яного уламка"}},{q="Що робить Горянин Воллбанґ після цього завдання?",a="Переконавшись, що ви — випробуваний боєць на службі короля Маґні, Воллбанґ посилає вас до Капітана Руґелфусса по стратегічні накази щодо оборони Лох Модану.",al={"що далі воллбанґ","хто той капітан"}},{q="Хто править Айронфорджем під час цієї кризи?",a="Король Маґні Бронзбірд править дворфійським королівством з Великої Кузні в Айронфорджі. Усе, що робиться для захисту Лох Модану, робиться в його ім'я й на захист його суверенних земель.",al={"хто король дворфів","король айронфорджа"}}},fp="30,419,19.376.0,36.389.0,28.237.0,51.240.0,31.205.0,43.280.0,50.173.0,39.188.0"}
P.entries["quest:264"] = {n="Допоки смерть не розлучить нас",s="«Допоки смерть не розлучить нас» — гірке, особисте завдання, що веде до Гробниці в Срібноліссі. Кларіс Фостер, Відступниця з Ставків Видінь під Тандер Блафом, посилає шукачів пригод викинути її амулет-пам'ятку на гробницю її покійного чоловіка Юріва. Завдання відкриває болісні людські розколи, які породили фанатизм і війна, коли чума поглинула Лордерон.",h="«Допоки смерть не розлучить нас» — гірке, особисте завдання, що веде до Гробниці в Срібноліссі.",kw={"допоки смерть не розлучить нас","кларіс фостер","юрів","гробниця","амулет","відступники"},ang={["class:Priest"]="Завдання малює похмуру картину віри: відданість Світлу може розірвати родину й посіяти тривалу гіркоту в тих, хто лишився.",["faction:Horde"]="Допомагаючи Кларіс, поборники Орди бачать особисті трагедії й незгасну злість, що об'єднують Відступників у Срібноліссі.",["race:Undead"]="Для Відступників історія Кларіс уособлює лицемірство живих: святі воїни в релігійному запалі покидали родини на загибель, а їхнім перетвореним рідним лишилося нести тягар пам'яті."},sec={{t="Гірка пам'ятка",b="Кларіс Фостер не має жодної ніжності до спогадів про свій смертний шлюб. Коли Лордерон розсипався, її чоловік Юрів покинув її з дітьми й пішов у хрестовий похід проти нежиті, що наступала, проголосивши, що служіння Святому Світлу понад усе. Зрештою його відданість не врятувала ні родини, ні його самого. Тепер, коли Кларіс піднято в нежиття, а Юрів гниє під оскверненим каменем, вона прагне лише позбутися останнього відчутного нагадування про його порушені обіцянки."},{t="Занедбана могила",b="Гробниця Юріва стоїть на кладовищі довкола Гробниці — посічена, засмічена й поросла бур'яном. Амулет Кларіс, покладений на вирізьблені руки на рельєфі, не приносить ні величної магії, ні духовного спокою — лише тьмяніє самоцвіт, і над могилами пробігає холодний, мовчазний подих вітру. Це суворе свідчення давніх образ, що досі живуть у полеглому народі Лордерона."}},faq={{q="Ким був Юрів?",a="Юрів був смертним чоловіком Кларіс Фостер. За життя він покинув її й дітей, щоб боротися з Погибеллю в ім'я Святого Світла, поставивши свій хрестовий похід вище за родину.",al={"хто такий юрів","юрів лор","чоловік кларіс"}},{q="Чому Кларіс так ненавидить покійного чоловіка?",a="Ніч за ніччю Кларіс чекала на Юріва, поки той ставив релігійний обов'язок на перше місце. Зрештою його хрестовий похід не вберіг їх: він лежить мертвий у занедбаній могилі, а вона проклята повстати тією самою нежиттю, з якою він воював.",al={"чому кларіс сердита","передісторія кларіс фостер"}},{q="Що буде, коли повернути кулон?",a="Коли кулон кладуть у кам'яні руки вирізьбленого рельєфу Юріва, самоцвіт помітно тьмяніє. Над Гробницею проноситься різкий, прохолодний вітер, і сплюндрована гробниця лишається в холодному, тихому забутті.",al={"кулон на могилі","кінець допоки смерть не розлучить нас"}},{q="Де гробниця Юріва?",a="Надгробок Юріва — на цвинтарі Гробниці, твердині Відступників на півночі Срібнолісся.",al={"де гробниця юріва","місце могили юріва"}},{q="Чому могила Юріва так пошкоджена?",a="Могилу посічено, закидано сміттям, і вона заросла бур'яном. Відступники, що живуть у Гробниці, не мають ні співчуття, ні пошани до хрестоносця, який загинув, воюючи з такими, як вони.",al={"чому могила осквернена","гробницю зневажено"}},{q="Чи вижили діти Кларіс?",a="Кларіс згадує, що Юрів покинув дітей разом із нею, але про їхню долю нічого не сказано. Зважаючи на цілковите спустошення Лордерону, вони, найпевніше, загинули трагічною смертю.",al={"що з дітьми","діти кларіс"}}},fp="22,379,17.477.0,19.397.0,14.194.0,47.254.0,41.200.1,30.127.0,32.187.0,31.186.0"}
P.entries["quest:265"] = {n="Пошуки в тіні тривають",s="Після віщування Мадам Єви розслідування веде з її світлиці до Писаря Долтрі в Даркширі. Ідеться про те, щоб з'ясувати походження щоденника, знайденого на руїнах сплюндрованого хутора Свена Йорґена.",h="Після віщування Мадам Єви розслідування веде з її світлиці до Писаря Долтрі в Даркширі.",kw={"пошуки в тіні тривають","писар долтрі","мадам єва","свен йорґен","щоденник","даркшир"},ang={["class:Rogue"]="Вистежувати знервовану ціль у місті за записами про покупки й враженнями торговців — класичне слідче ремесло.",["faction:Alliance"]="З'ясувати, хто постачав некромантів Сутінколісся й допомагав їм, — життєво важливо, щоб уберегти Даркшир і принести справедливість вирізаним хуторянам прикордоння."},sec={{t="Слідами палітурки",b="Оглянувши обгорілий щоденник, урятований після трагедії на фермі Свена, Мадам Єва розпізнала: хоч автор і був чужинцем, сама книга походить із Даркшира. Писар Долтрі часто продає чисті книги обліку й томи мандрівним ученим, заклиначам і літописцям. Ідучи слідом місцевої торгівлі, слідчі сподіваються за звичайними паперами впізнати невловимого й зловісного чужинця, що чаїться в похмурих гаях Сутінколісся."},{t="Нервовий покупець",b="Оглянувши книгу, Писар Долтрі чітко згадує ту покупку, попри безліч записів, що проходять через ратушу Даркшира. Приблизно місяць тому знервований, потайливий мандрівник купив чисту книгу, так і не назвавши свого імені. Тремтливі манери покупця й те, що він раз у раз озирався, добре врізалися писареві в пам'ять, — тож темна постать, яку бачив Свен, відкрито ходила серед мешканців Даркшира."}},faq={{q="Звідки взялася таємнича книга?",a="Мадам Єва каже, що автор книги — чужинець у Даркширі, але купили її в самому містечку. Писар Долтрі продає порожні книги й може пам'ятати покупця.",al={"походження книги","хто продав книгу","звідки книга"}},{q="Чому Мадам Єва посилає до Писаря Долтрі?",a="Мадам Єва впізнає за оправою й матеріалами, що книгу купили тут-таки, у містечку. Писар Долтрі продає порожні реєстри й щоденники місцевим і мандрівним ученим.",al={"чому долтрі","зв'язок єви і долтрі","хто зробив книгу"}},{q="Що Писар Долтрі пам'ятає про покупця?",a="Долтрі пам'ятає людей, які купували в нього книги останніми місяцями. Якщо показати йому том, він зможе з'ясувати, хто його придбав.",al={"хто купив книгу","опис покупця","вигляд таємничої постаті"}},{q="Як це пов'язано з фермою Свена?",a="Книгу знайшли на зруйнованій фермі Свена Йорґена на півдні Сутінколісся — вона лишилася там після кривавого нальоту, що знищив його родину й наймитів.",al={"зв'язок зі свеном","чому ми шукаємо","свен йорґен"}},{q="Куди веде розслідування далі?",a="Знервований незнайомець якийсь час провів у містечку, тож пошуки тривають у даркширській таверні «Багряний Крук» — може, хтось бачив, де він зупинявся чи з ким говорив.",al={"що далі","після долтрі","наступна зачіпка"}},{q="Чи загрожує Писареві Долтрі небезпека?",a="Долтрі допомагає встановити покупця серед своїх звичайних продажів книг. Із цієї розмови не видно, що йому особисто щось загрожує.",al={"небезпека для долтрі","чи долтрі в безпеці"}}},fp="28,217,19.483.0,15.449.1,40.149.0,45.199.0,48.132.0,37.154.0,39.178.1,26.132.0"}
P.entries["quest:266"] = {n="Розпитати в шинку",s="«Розпитати в шинку» — завдання Альянсу в Даркширі, що продовжує розслідування про таємничого чужинця, пов'язаного зі зруйнованою фермою Свена Йорґена. За порадою Писаря Долтрі шукачі пригод несуть знайдений щоденник до Таверни «Багряний Крук», щоб розпитати Шинкаря Смітса, хто в нього зупинявся.",h="«Розпитати в шинку» — завдання Альянсу в Даркширі, що продовжує розслідування про таємничого чужинця...",kw={"розпитати в шинку","шинкар смітс","багряний крук","писар долтрі","даркшир","воронячий пагорб"},ang={["class:Rogue"]="Простежити шлях параноїдального втікача від шинкових пліток до безлюдних руїн — саме те, у чому полягає слідче ремесло агента.",["faction:Alliance"]="Розслідування загроз усередині Даркшира допомагає захистити одне з найвразливіших і найвідрізаніших поселень Альянсу на півдні Східних Королівств."},sec={{t="Слід у «Багряному Круку»",b="Оглянувши пошарпану книгу з ферми Свена Йорґена, Писар Долтрі припускає, що будь-який чужинець у Даркширі майже напевно зазирав до місцевої таверни. Таверна «Багряний Крук» по той бік міста — єдине місце зборів і нічлігу в Даркширі, тож саме там найрозумніше шукати заїжджих гостей."},{t="Параноїдальний гість",b="Шинкар Смітс, побачивши книгу, підтверджує здогад Долтрі. Він одразу впізнає її й згадує постояльця, що кілька днів наймав кімнату й вечорами одержимо щось строчив за шинквасом. За словами шинкаря, гість утік із Даркшира в нестямі від жаху, переконаний, що його невідступно переслідує хтось невидимий. Його шлях пролягав на захід, похмурою дорогою до Воронячого Пагорба."}},faq={{q="Хто посилає до шинку?",a="Писар Долтрі, що веде міські записи в ратуші Даркшира, повертає щоденник і радить зазирнути до місцевої таверни — може, там хтось упізнає його власника.",al={"хто дає завдання","звідки починається розпитати в шинку"}},{q="Що за книгу ви несете?",a="Це пошарпаний щоденник, знайдений на зруйнованому хуторі Свена Йорґена на півдні Сутінколісся; вважають, що він належить таємничій постаті, яку бачили, як вона никала тими місцями.",al={"яка це книга","книга з ферми свена","щоденник"}},{q="Хто тримає таверну «Багряний Крук»?",a="Таверною «Багряний Крук» керує Шинкар Смітс: він наливає питво й здає кімнати мандрівникам, які ще наважуються заходити в Сутінколісся.",al={"хто тримає таверну","корчмар даркшира","хто такий смітс"}},{q="Що Шинкар Смітс розповідає про гостя?",a="Смітс пригадує, що власник щоденника винаймав кімнату кілька днів і ночами пив і писав. Тоді мандрівник у паніці втік на захід, бурмочучи, що на нього полює щось жахливе.",al={"що сказав смітс","що сталося з таємничою постаттю","що знає шинкар"}},{q="Куди втекла таємнича постать?",a="Він поспіхом подався на захід з Даркшира шукати схованку — це спрямовує шукачів до покинутого поселення й розлогого цвинтаря Воронячого Пагорба.",al={"куди він пішов","де таємнича постать","куди далі"}},{q="Яке завдання йде після «Розпитати в шинку»?",a="Шинкар Смітс радить вам іти слідом незнайомця на захід — у завданні «Пошуки таємничої постаті».",al={"наступне завдання","що після розпитати в шинку"}}},fp="18,299,27.363.0,18.419.1,25.172.0,34.162.0,31.143.0,51.205.0,34.157.0,38.112.0"}
P.entries["quest:267"] = {n="Загроза трогів",s="«Загроза трогів» — завдання Альянсу від Капітана Руґелфусса біля Південної брами Лох Модану. Місцевий Резерв Айронфорджа відкликали на фронти Альянсу, тож оборонців, що лишилися, ледве вистачає проти ворожих племен трогів у пагорбах. Шукачам пригод доручають винищувати трогів і приносити їхні кам'яні зуби, щоб послабити тиск на гірський перевал.",h="«Загроза трогів» — завдання Альянсу від Капітана Руґелфусса біля Південної брами Лох Модану.",kw={"загроза трогів","троги","капітан руґелфусс","південна брама","лох модан","кам'яні зуби","завдання"},ang={["faction:Alliance"]="Завдання показує, як зобов'язання Альянсу в далеких землях позбавили місцеві залоги, як-от у Лох Модані, оборонних резервів.",["race:Dwarf"]="Для дворфів винищувати трогів біля Південної брами — прямий обов'язок перед Каз Моданом, за який хвалить сам Король Маґні Бронзбірд."},sec={{t="Збідніле порубіжжя",b="Оборонна лінія на південному підступі до Лох Модану в хиткому становищі. Регулярних дворфійських горян і полки Резерву Айронфорджа відіслали на підсилення ширших фронтів Альянсу, і на південній сторожовій вежі лишилися тільки Капітан Руґелфусс і нечисленна залога. Суворий наказ не покидати браму не дає Руґелфуссу піти в наступ на нагір'я, тож сусідні поселенці й мандрівники беззахисні перед засідками."},{t="Спинити навалу",b="Троги, що живуть у навколишніх скелях, становлять дедалі більшу небезпеку для Каз Модану. Якщо їх не спинити, вони швидко розплодяться й заполонять дворфійські застави. Щоб виграти час і проредити напасть, Руґелфусс кличе мандрівних шукачів пригод атакувати трогів просто в їхніх норах на схилах і приносити вирвані кам'яні зуби як речовий доказ виконаного."}},faq={{q="Хто такий Капітан Руґелфусс?",a="Капітан Руґелфусс — офіцер дворфійського війська на вартовій вежі Південної Брами в Лох Модані. Йому доручено захищати перевал від вторгнень, попри гострий брак гарнізонних вояків.",al={"капітан руґелфусс","хто дає загрозу трогів","руґелфусс"}},{q="Чому Південній Брамі бракує людей?",a="Резерв Айронфорджа мобілізували й перекинули воювати на ширших фронтах Альянсу за кордоном. Біля брами лишився тільки невеликий загін, прикутий до оборонного посту й неспроможний завдавати відповідних ударів.",al={"чому немає вартових","немає резерву айронфорджа","де дворфійські солдати"}},{q="Що таке Кам'яні зуби трогів?",a="У трогів природно скам'янілі, кам'яноподібні зуби — відгомін їхнього підземного, земного походження. Капітан Руґелфусс вимагає їх як незаперечний речовий доказ того, що трогів убито.",al={"троги кам'яний зуб","кам'яні зуби","чому зуби трогів"}},{q="Де шукати трогів?",a="Троги населяють скелясті пагорби, яри й розкопки обабіч шляху біля Південної Брами в Лох Модані.",al={"де троги","місця трогів лох модан","де троги для завдання"}},{q="Чому троги саме зараз такі небезпечні?",a="Троги швидко плодяться, люто боронять свою землю й заполоняють заселені краї щоразу, як гарнізони відволікаються. Якщо їх не проріджувати, вони можуть перекрити перевали, що сполучають Лох Модан із сусідніми землями.",al={"чому троги небезпечні","проблема трогів","чого хочуть троги"}},{q="Як це завдання допомагає королю Маґні Бронзбірду?",a="Король Маґні Бронзбірд відповідає за безпеку всього Каз Модану. Проріджуючи трогів, поки армії Айронфорджа воюють за кордоном, шукачі пригод захищають внутрішні шляхи постачання королівства й вразливі прикордонні поселення.",al={"зв'язок з маґні бронзбірдом","чи маґні турбується","навіщо допомагати айронфорджу"}}},fp="16,396,19.487.0,17.370.0,25.221.0,38.228.0,27.201.0,29.137.0,43.244.0,58.247.0"}
P.entries["quest:268"] = {n="Повернення до Свена",s="Це завдання — мить, коли Свен Йорґен нарешті дізнається правду про жорстоку різанину своєї родини на Хуторі Йорґенів. Вистеживши втікача Тремтія, ви повертаєтеся до відрізаного табору Свена на межі з Вестфолом із завершеним щоденником волоцюги. Щоденник обіцяє відповіді на питання, що мучать Свена від самого нападу.",h="Це завдання — мить, коли Свен Йорґен нарешті дізнається правду про жорстоку різанину своєї родини на Хуторі...",kw={"повернення до свена","свен йорґен","тремтій","темні вершники","морбент фел","хутір йорґенів"},ang={["class:Paladin"]="Допомагаючи Свенові розкрити сили, що стоять за вбивством його родини, ви сповнюєте святий обов'язок захищати безневинних і шукати справедливості.",["faction:Alliance"]="Трагічна загибель Хутора Йорґенів — суворе нагадування про те, що Стормвінд цілком не зміг захистити прикордонні поселення Сутінколісся від тіней, що насуваються."},sec={{t="Сповідь боягуза",b="Коли напали на ферму Свена Йорґена, Тремтій утік у ліс у паніці, лишивши серед різанини тільки недописаний щоденник. Наляканий гнівом Свена й переслідуваний тим, що бачив, Тремтій сховався глибоко в Сутінколіссі. Коли його знаходять, він охоче віддає завершений щоденник, відчайдушно сподіваючись, що повна розповідь про напад звільнить його від зустрічі з мстивим фермером віч-на-віч."},{t="Темні вершники без масок",b="Дописана оповідь Тремтія нарешті складає для Свена жахливі шматки докупи. Різанина на його фермі не була випадковим наступом нежиті чи нападом диких звірів: її вчинили загадкові Темні Вершники, що шукали якийсь артефакт. Ба більше, Свен пригадує, як бачив тих самих постатей у каптурах на таємній зустрічі з некромантом Морбентом Фелом біля Покинутого Ряду. Щоденник Тремтія обертає сліпе горе Свена на цілеспрямоване полювання за відплатою темному чарівникові."}},faq={{q="Чому Тремтій так боїться Свена Йорґена?",a="Тремтій утік з ферми Свена й боїться гніву вбитого горем фермера. Він просить вас віднести його щоденник, щоб Свен прочитав його розповідь.",al={"чому тремтій боїться","тремтій боїться свена","що зробив тремтій"}},{q="Що в дописаному щоденнику Тремтія?",a="Це повна розповідь Тремтія про події на фермі Свена. Свенові треба прочитати її, щоб зрозуміти, що сталося з його родиною.",al={"що сказано в щоденнику","лор щоденника тремтія"}},{q="Хто такі Темні Вершники, про яких говорить Свен?",a="Темні Вершники — загадкові постаті в каптурах і плащах, що никають Сутінколіссям. Безжальні й смертоносні, вони прийшли в ліс, невпинно шукаючи могутніх магічних реліквій, і всюди, куди ступають, лишають смерть і руїну.",al={"хто такі темні вершники","вершники сутінколісся","чорні вершники"}},{q="Як Морбент Фел пов'язаний з нападом на ферму Свена?",a="Морбент Фел — могутній некромант на заході Сутінколісся. Його зв'язок із нападом розкривається завдяки розслідуванню Свена й щоденнику Тремтія.",al={"зв'язок морбента фела","чому морбент фел","хто такий морбент фел"}},{q="Де знайти Свена Йорґена?",a="Свен покинув свою зруйновану садибу й тепер живе в невеликому напруженому таборі серед північно-західних пагорбів Сутінколісся, біля переходу до Вестфолу.",al={"де свен","місце свена йорґена","табір свена"}},{q="Що буде, коли віддати Свенові щоденник?",a="Свен читає дописану розповідь Тремтія й просить вас довести свою бойову вправність у наступному завданні — «Довести свою вартість».",al={"наступне завдання після повернення до свена","лінія свена далі"}}},fp="14,359,21.425.0,25.487.1,43.136.0,38.122.1,42.213.0,58.151.1,31.175.0,43.119.1"}
P.entries["quest:269"] = {n="У пошуках мудрості",s="«У пошуках мудрості» — доручення Альянсу, у якому Завершений Щоденник Джиттерса треба доправити з обложених таборів Сутінколісся до безпечного Стормвінда. Свен Йорґен відсилає шукачів пригод порадитися з Єпископом Фартінґом у Соборі Світла — він сподівається, що свята порада підкаже, як знищити захищеного чарами некроманта Морбента Фела.",h="«У пошуках мудрості» — доручення Альянсу, у якому Завершений Щоденник Джиттерса треба доправити з обложених...",kw={"у пошуках мудрості","свен йорґен","єпископ фартінґ","морбент фел","сутінколісся","собор світла"},ang={["class:Paladin"]="Нести благання про святе заступництво з покинутого прикордоння в серце Собору Світла — пряме випробування обов'язку Срібної Длані: захищати забутих і викорінювати некромантію.",["class:Priest"]="Єпископ Фартінґ дає духовну пораду про те, як темні захисні чари розтлівають душу й тіло, і показує, що з чаклунством тіні борються не клинком, а зосередженим освяченням.",["faction:Alliance"]="Ця мандрівка підкреслює гіркий політичний розкол між захищеними мармуровими залами Стормвінда й покинутими містечками Сутінколісся, які не отримують жодної підтримки гарнізону."},sec={{t="Благання з темряви",b="Сутінколісся потерпає від давніх прокльонів, ненажерливої нежиті й дедалі більшої байдужості королівського двору Стормвінда. Свен Йорґен, що вцілів, але має розбите серце, отаборився біля кордону й знає: звичайною силою темних захисних чар некроманта Морбента Фела не пробити. Маючи складений докупи щоденник волоцюги Тремтія, Свен закликає мандрівних героїв звернутися не до корони, а до церкви — і відсилає їх на північ, дорогою до Собору Світла."},{t="Порада в Соборі",b="У величних залах Собору Стормвінда Єпископ Фартінґ — один із небагатьох достойників, що ще готові слухати благання Сутінколісся про допомогу. Переглянувши моторошну розповідь Тремтія, єпископ підтверджує страшну силу Морбента Фела. Некромант захищається мерзенним чаклунством, яке відбиває звичайні удари, тож сама лише безрозсудна відвага приведе тільки до різанини. Щоб здолати лиходія, треба здобути зачароване святе знаряддя."}},faq={{q="Чому Свен посилає вас до Єпископа Фартінґа, а не до короля Андуїна?",a="Знать і військо Стормвінда, паралізовані політичними чварами, здебільшого покинули Даркшир і довколишні землі напризволяще. Свен знає, що офіційним шляхом солдатів не дочекатися, але довіряє Єпископові Фартінґу — співчутливому, вченому служителеві Святого Світла, що розуміється на мерзенній магії.",al={"чому фартінґ","чому не дворяни стормвінда","стормвінд ігнорує сутінколісся"}},{q="Що таке щоденник Тремтія і навіщо він єпископові?",a="Тремтій записав події довкола нападу на ферму Свена. Свен надсилає дописану розповідь Єпископові Фартінґу, щоб той порадив шукачеві пригод, як готуватися до зустрічі з Морбентом Фелом.",al={"що таке щоденник тремтія","навіщо щоденник тремтія","дописаний щоденник тремтія"}},{q="Хто такий Морбент Фел?",a="Морбент Фел — могутній некромант, що чатує серед могил Воронячого Пагорба на заході Сутінколісся. Він командує ордами слуг-скелетів і захищає своє тіло потужними охоронними чарами, тож звичайна зброя його не бере.",al={"хто такий морбент фел","морбент фел лор"}},{q="Де знайти Єпископа Фартінґа?",a="Єпископ Фартінґ — у Соборі Світла, величному людському соборі, що панує над кварталом Соборна Площа в Стормвінді.",al={"де фартінґ","місце фартінґа","мапа єпископа фартінґа"}},{q="Що буде, коли Єпископ Фартінґ прочитає щоденник?",a="Єпископ Фартінґ пояснює, що звичайними ударами Морбентові Фелу не зашкодиш. Він радить шукачам пригод розшукати освячену реліквію, здатну розвіяти магічний захист некроманта, — так починаються пошуки Приреченого флоту.",al={"що далі у пошуках мудрості","продовження пошуків мудрості","після пошуків мудрості"}},{q="Де в Сутінколіссі живе Свен Йорґен?",a="Свен Йорґен переховується в невеликому таборі на північному заході Сутінколісся, біля прикордонної річки на південь від Лісу Елвінн і на захід від примарного Цвинтаря Воронячого Пагорба.",al={"де свен","місце свена йорґена","табір свена"}}},fp="14,313,23.454.0,24.452.1,65.301.0,57.189.0,19.236.0,33.144.0,53.243.1,40.159.0"}
P.entries["quest:27"] = {n="Урок, який слід засвоїти",s="«Урок, який слід засвоїти» — один із перших обрядів посвяти для друїдів Альянсу, що навчаються в Дарнасусі. Його дає Матренґіл Берволкер: він посилає посвячуваних до священного прихистку Місячного Гаю, щоб ті почали опановувати свою водяну подобу.",h="«Урок, який слід засвоїти» — один із перших обрядів посвяти для друїдів Альянсу, що навчаються в Дарнасусі.",kw={"урок, який слід засвоїти","матренґіл берволкер","місячний гай","нічний притулок","дендрит старблейз","водяна форма","друїд"},ang={["class:Druid"]="Це завдання — важлива віха в навчанні друїда: воно відкриває шлях до єднання з дарами Кенарія під хвилями.",["race:NightElf"]="Для калдореїв Дарнасуса відгукнутися на поклик Кола Кенарія в Місячному Гаю — шанована традиція, що пов'язує їх із прадавніми вчителями."},sec={{t="Поклик дикої природи",b="Матренґіл Берволкер наглядає за молодими друїдами нічних ельфів, що вправляються в гіллі Дарнасуса. Щойно посвячуваний доводить свій міцний зв'язок із природою й готовність узяти на себе більшу відповідальність, Матренґіл велить йому готуватися до наступної великої науки — влади над водами. Дари Кенарія вимагають суворого зосередження, а щоб долати глибини й не тонути, треба безпосередньо поєднатися зі старійшинами Кола Кенарія."},{t="Подорож до Нічного Притулку",b="Щоб іти далі, посвячуваний має покинути Дарнасус і вирушити до Місячного Гаю — прадавнього святилища, захованого під Горою Гіджал. У тихому поселенні Нічний Притулок на нього чекає Дендрит Старблейз. Як старший наставник Кола, Старблейз оцінює, чи готові молоді друїди, що вчаться змінювати подобу, до випробувань, які відкривають водяну форму, і застерігає: влада над водою потребує і тілесної витривалості, і сили духу."}},faq={{q="Хто посилає мене на це завдання?",a="Матренґіл Берволкер, наставник друїдів у Ценаріонському Анклаві в Дарнасусі, дає це завдання, коли ви досить зростете в перших друїдських мистецтвах.",al={"хто дає завдання","хто дає урок, який слід засвоїти","хто це починає"}},{q="Яка мета цього завдання?",a="Це перший крок для друїдів, які прагнуть здобути водяну подобу. Воно кличе посвяченого до Місячного Гаю по науку й випробування від старійшини Дендрита Старблейза.",al={"навіщо це завдання","вступ до водної форми","що я отримаю"}},{q="Де знайти Дендрита Старблейза?",a="Дендрит Старблейз живе в селищі Нічний Притулок на північному березі Озера Елуне'ара в Місячному Гаю.",al={"місце дендрита","де дендрит старблейз","знайти дендрита"}},{q="Як друїди дістаються Місячного Гаю для цього завдання?",a="Друїди мають духовне налаштування, що дає їм змогу телепортуватися просто до священного гаю Місячний Гай за допомогою вміння «Телепортація: Місячний Гай», оминаючи звичайні суходільні шляхи.",al={"як дістатися місячного гаю","дістатися нічного притулку"}},{q="Що далі після розмови з Дендритом Старблейзом?",a="Щойно ви поговорите з Дендритом Старблейзом, він одразу дає вам Випробування озера, щоб перевірити вашу витривалість і ясність розуму під водою.",al={"наступне завдання","що далі","після уроку, який слід засвоїти"}}},fp="17,229,20.481.0,21.444.0,27.169.0,34.178.0,36.122.0,45.189.0,48.160.0"}
P.entries["quest:270"] = {n="Приречений флот",s="«Приречений флот» — подорож на північ, у яку посилає Єпископ Фартінґ із Собору Світла в Стормвінді. Шукаючи спосіб здолати могутнього некроманта Морбента Фела, героїв відправляють через Каз Модан до затонулих уламків біля узбережжя Багнокраю.",h="«Приречений флот» — подорож на північ, у яку посилає Єпископ Фартінґ із Собору Світла в Стормвінді.",kw={"приречений флот","єпископ фартінґ","морбент фел","залізо лайтфорджу","багнокрай","гавань менетіл"},ang={["class:Paladin"]="Шукати святий метал, щоб покарати нечестивого некроманта, — це саме покликання паладина: викорінювати темряву зброєю, освяченою Світлом.",["class:Priest"]="Діючи за настановами Єпископа Фартінґа, жерці торкаються давніх знань Церкви про благословенні реліквії й освячені руди.",["faction:Alliance"]="Це завдання показує, як далеко сягають зв'язки Альянсу: відрізані людські міста півдня пов'язані з дворфійськими гаванями й давніми морськими шляхами.",["profession:Blacksmithing"]="Ковалі оцінять рідкісні знання про загартоване Світлом залізо — метал, просякнутий вірою, якому лише майстер здатен надати форми."},sec={{t="Зброя святої правди",b="Звичайна сталь виявилася безсилою проти темних захисних чарів, що оберігають Морбента Фела в його схованці на Покинутому Ряду. Щоб пробити такий некромантичний захист, Єпископ Фартінґ пояснює шукачам пригод, що треба викувати зброю, пов'язану зі Святим Світлом. Головна її складова — загартоване Світлом залізо, рідкісний освячений метал, чиї удари несуть святу правду й розсікають чародійський захист, від якого відскакують звичайні клинки."},{t="Уламки Третього флоту",b="На жаль, в обложеному Сутінколіссі загартоване Світлом залізо напоготові не тримають. Фартінґ пригадує, що багато років тому Третій флот острівної держави Кул Тірас зазнав катастрофи біля підступних берегів Багнокраю на північ від Айронфорджа. На борту одного з тих затонулих галеонів був вантаж цієї дорогоцінної руди. Шукачам пригод доведеться вирушити аж до Гавані Менетіл і порадитися з Ґлоріном Стілброу — дворфом, що найкраще знає болота та їхні корабельні уламки."}},faq={{q="Чому треба їхати аж у Багнокрай?",a="Темні чари захищають Морбента Фела від звичайних ударів. Єпископ Фартінґ знає, що зняти цей захист може лише зброя, викувана зі священного загартованого Світлом заліза, а єдиний відомий вантаж лежить серед розбитих кораблів Третього флоту Кул Тірасу біля Гавані Менетіл.",al={"чому їхати у багнокрай","чому менетіл","подорож до багнокраю"}},{q="Хто такий Морбент Фел?",a="Морбент Фел — зловісний некромант, що живе на Покинутому Ряду в Сутінколіссі. Його чаклунство підживлює чималу частину повстання нежиті, яке мучить край, тож його загибель — запорука виживання Даркшира.",al={"особа морбента фела","хто некромант","некромант сутінколісся"}},{q="Хто такий Ґлорін Стілброу?",a="Ґлорін Стілброу — дворф з Гавані Менетіл у Багнокраї. Він союзник Церкви Святого Світла й добре знає узбережжя, корабельні уламки й підйом затонулого майна в болотах.",al={"хто такий стілброу","роль стілброу"}},{q="Що таке загартоване Світлом залізо?",a="Загартоване Світлом залізо — особливо освячений метал, який високо цінують жерці. Зброя, викувана з нього, б'є святою силою й здатна розвіяти чи пробити темні щити й некромантські прокляття, перед якими звичайне залізо безсиле.",al={"що робить загартоване світлом залізо","метал світлокування","благословенне залізо"}},{q="Що сталося з Третім флотом Кул Тірасу?",a="Багато років тому Третій флот Кул Тірасу розбився й затонув біля зубчастого, болотистого узбережжя Багнокраю. Їхні корпуси досі лежать під водою біля берега, зберігаючи загублений вантаж, і їх стережуть утоплені моряки та водяні хижаки.",al={"доля третього флоту","кораблі кул тірасу в багнокраї","як затонули кораблі"}},{q="Чи доведеться в цьому завданні одразу битися?",a="Цей відрізок шляху — суто доставка. Він вимагає довгої подорожі із Сутінколісся через Королівство Стормвінд і Каз Модан аж до Гавані Менетіл, щоб зв'язатися з Ґлоріном Стілброу.",al={"чи буде бій","лише подорож"}}},fp="16,255,22.422.0,28.467.0,52.275.0,19.205.0,24.222.0,24.215.0,46.226.0,48.207.0"}
P.entries["quest:273"] = {n="Постачання розкопок",s="«Постачання розкопок» — завдання Альянсу в Лох Модані, у якому шукачі пригод наздоганяють вантаж пороху для Місця розкопок Айронбенда. Посланий Джерном Горнгелмом навздогін в'ючній валці, мандрівник іде її шляхом уздовж берега озера.",h="«Постачання розкопок» — завдання Альянсу в Лох Модані, у якому шукачі пригод наздоганяють вантаж пороху для...",kw={"постачання розкопок","джерн горнгелм","телсамар","лох модан","темне залізо","порох"},ang={["profession:Mining"]="Перевозити нестійкий вибуховий порох суворою місциною небезпечно й без зради, тож цей вантаж вкрай потрібен копачам на півдні."},sec={{t="Важкий вантаж уздовж берега",b="Місцю розкопок Айронбенда в південному Лох Модані потрібне постійне постачання вибухового пороху, щоб відкопувати давні артефакти титанів, поховані глибоко в горах. Коли порох доставили до Телсамара, місцевий інтендант Джерн Горнгелм доручив трьом дворфам — Гулдарові, Міранові й Саенові — повезти небезпечні бочки на південь прибережною дорогою. Обтяжена важким вантажем валка рухалася повільно, тож мандрівники з Телсамара мали змогу наздогнати її й допомогти в дорозі."},{t="Зрада в тіні",b="Наздогнавши в'ючний віз на південній дорозі, мандрівник бачить не звичайне перевезення, а хаос. На вантаж напали із засідки дворфи Темного Заліза, які прагнуть зірвати археологічні пошуки експедиції Бронзбірдів. Та гірше за сам напад — гірка зрада, яку він викрив: Саен, робітник, якому довіряли й з яким Гулдар працював майже рік, виявився прихильником Темного Заліза й допоміг улаштувати засідку."}},faq={{q="Хто дає завдання «Постачання розкопок»?",a="Джерн Горнгелм пропонує завдання в Телсамарі, коли ви принесете йому вибуховий порох. Він просить вас іти шляхом на південь уздовж озера, щоб наздогнати загін із припасами.",al={"хто дає постачання розкопок","хто починає постачання розкопок","де почати постачання розкопок"}},{q="Де знайти Гулдара й віз?",a="Гулдар і віз — на південь від Телсамара, на шляху, що огинає західний і південний вигин озера в напрямку до Місця розкопок Айронбенда.",al={"знайти гулдара","місце гулдара","де віз лох модан"}},{q="Навіщо Айронбендові везуть вибуховий порошок?",a="Шукач Айронбенд і його загін розкопують давні руїни й реліквії землян на південних розкопках. Вибуховий порошок потрібен, щоб розбивати важкий камінь і пробиватися крізь підземні шари.",al={"навіщо айронбенду порошок","вибуховий порошок айронбенда","навіщо порошок на розкопки"}},{q="Хто влаштував засідку на віз Гулдара?",a="Джерн гадає, що загін із припасами йде звичайною дорогою на південь від Телсамара, уздовж озера. Що сталося з возом, з'ясується, коли ви дістанетеся Гулдара.",al={"хто напав на віз","засідка на віз лох модан","хто напав на гулдара"}},{q="Яку роль у нападі відіграв Саен?",a="Саен їде разом із Гулдаром і Міраном, щоб перевезти важкі бочки з вибуховим порохом. Яку роль він відіграв у подіях на дорозі, з'ясується, коли ви наздоженете загін.",al={"хто такий саен","зрада саена","що зробив саен"}},{q="Яке завдання йде після того, як знайти Гулдара?",a="Розмова з Гулдаром завершує цей відрізок шляху. Його розповідь про вантаж дає наступний слід.",al={"наступне завдання після постачання розкопок","завдання після гулдара"}}},fp="26,264,29.503.0,24.444.1,48.166.0,40.167.0,42.201.0,28.159.1,39.159.1,43.107.1"}
P.entries["quest:274"] = {n="Насувається темна загроза",s="Після того як на Каменетесній Греблі знайшли підозрілий порошок, Ешлан Стоунсмерк у Дун Модрі розпізнає в ньому нестійкий сифоріум. Здатний на катастрофічні руйнування, якщо потрапить у воду, цей порошок — безпосередня загроза для краю й сусіднього дворфійського королівства. Стоунсмерк готує знешкоджувальний колоїд і передає звістку Головному Інженерові Гіндервіру VII, щоб відвернути лихо.",h="Після того як на Каменетесній Греблі знайшли підозрілий порошок, Ешлан Стоунсмерк у Дун Модрі розпізнає в...",kw={"насувається темна загроза","сифоріум","ешлан стоунсмерк","каменетесна гребля","гіндервір","знешкоджувальний колоїд"},ang={["faction:Alliance"]="Захисникам Альянсу треба діяти швидко, щоб допомогти Головному Інженерові Гіндервіру VII й убезпечити низини, перш ніж ворожі диверсанти зруйнують стратегічні споруди.",["profession:Engineering"]="Інженери впізнають у сифоріумі надзвичайно потужну нестійку сполуку, що вимагає делікатного поводження й точних хімічних протизаходів, аби уникнути нищівних ударних хвиль.",["race:Dwarf"]="Для дворфів Каз Модану сама думка про диверсантів із нестійким сифоріумом біля воріт до Дун Мороґа й Айронфорджа — загроза самому існуванню."},sec={{t="Вибухова знахідка",b="Оглянувши зразки, принесені з Каменетесної Греблі, Ешлан Стоунсмерк одразу впізнає характерні срібні кристали й особливий запах сифоріуму. У сухому стані сифоріум інертний, але з вологою реагує бурхливо — жахлива дійсність для греблі, що стримує води Лох Модану. Ешлан попереджає: неконтрольований вибух такої сполуки міг би вирвати Айронфордж із самої гори."},{t="Наввипередки з часом",b="Щоб протидіяти нестійкій вибухівці, Стоунсмерк готує особливий знешкоджувальний колоїд. Для нейтралізації реакції потрібна певна хімічна суміш: колоїд, змішаний з отрутою болотяного причаєнця, товченим кристалом Мо'ґрош і сльозою кроколіска. Часу обмаль, і Головного Інженера Гіндервіра VII треба попередити негайно, перш ніж волога спричинить катастрофу."}},faq={{q="Яку вибухівку знайшли в Багнокраї?",a="Ешлан Стоунсмерк упізнає загадкову речовину як порошок сіфоріуму — з характерними сріблястими кристаликами й різким хімічним запахом.",al={"що за порошок","що це за порошок","сіфоріумний порошок"}},{q="Чому сіфоріум тут такий небезпечний?",a="Сухий сіфоріум доволі безпечний, але від контакту з водою спричиняє катастрофічний вибух — тож Каменетесна Гребля, що стримує води Лох Модану, для нього надзвичайно небезпечне місце.",al={"чому сіфоріум небезпечний","чому сіфоріум вибухає"}},{q="Хто такий Ешлан Стоунсмерк?",a="Ешлан Стоунсмерк — дворф-фахівець Альянсу з Багнокраю, що має інженерні й хімічні знання, потрібні, щоб дослідити загадкові порошки й виготовити знешкоджувачі.",al={"хто такий ешлан","особа ешлана стоунсмерка"}},{q="Хто такий Головний Інженер Гіндервір VII?",a="Головний Інженер Гіндервір VII опікується інженерними й оборонними справами краю й працює на Каменетесній Греблі в Лох Модані, підтримуючи й оберігаючи дворфійські споруди.",al={"хто такий гіндервір","головний інженер гіндервір"}},{q="Як знешкодити сіфоріум?",a="Щоб зупинити хімічну реакцію, треба поєднати знешкоджувальний колоїд Ешлана з трьома рідкісними місцевими складниками: отрутою болотного чатувальника, товченим кристалом Мо'ґрош і сльозою кроколіска.",al={"як знешкодити сіфоріум","рецепт знешкодження сіфоріуму","рецепт розряджувального колоїду"}},{q="Яка небезпека загрожує Айронфорджу?",a="Ешлан попереджає, що некерований вибух у довколишніх гірських масивах може спричинити нищівний сейсмічний обвал, здатний вирвати Айронфордж просто з гори.",al={"чи айронфорджу загрожує небезпека","як загрожують айронфорджу"}}},fp="19,418,20.406.0,16.370.1,49.136.0,35.224.0,25.193.0,37.188.0,37.181.0,32.193.0"}
P.entries["quest:2745"] = {n="Проникнення в замок",s="Майстер-сироторговець і торговець розвідданими Еллінг Тріас відсилає вас до королівської резиденції — Фортеці Стормвінда. Ваше завдання — зустрітися з його товаришем-агентом Тиріоном, який тижнями стежить із садів фортеці за продажним вельможею Лордом Ґреґором Лесковаром.",h="Майстер-сироторговець і торговець розвідданими Еллінг Тріас відсилає вас до королівської резиденції — Фортеці...",kw={"проникнення в замок","тиріон","ґреґор лесковар","еллінг тріас","марзон тихий клинок","фортеця стормвінда"},ang={["class:Rogue"]="Проникнути до осідку людської знаті на допомогу двом бувалим підпільним агентам — означає показати тихе й смертоносне ремесло, потрібне, щоб захистити Стормвінд від тіней при його власному дворі.",["faction:Alliance"]="Поки король Варіан зник безвісти, королівство не може дозволити собі зради в найвищій палаті влади: викорінити змовників у Фортеці — вкрай важливо для стабільності держави.",["race:Gnome"]="Тиріон, що веде напружене багатотижневе таємне стеження у Фортеці Стормвінда, доводить: гномська винахідливість сягає далеко за межі механізмів — аж до ризикованого шпигунства."},sec={{t="Справа поза законом",b="When you bring your findings to Elling Trias in his Trade District cheese shop, he quickly grasps the gravity of the Defias threat nestled deep inside the kingdom's governance. Legal channels will not suffice to expose or punish someone as deeply entrenched and protected as Lord Gregor Lescovar. Trias offers a dangerous route forward: delivering extrajudicial justice within the very walls of Stormwind Keep to permanently sever the conspiracy."},{t="Очі в кущах",b="У високих залах Тріас діє не сам. Уже кілька тижнів агент на ім'я Тиріон — кмітливий гном, майстер маскування — чатує в дворах фортеці й доглянутих королівських садах. Тиріон стежить за пересуваннями Лесковара: хто заходить до його покоїв і коли зрадник радиться зі своїми таємними зв'язковими з Дефіас. Дістатися до Тиріона, не викликавши підозр Королівської варти, — наступна важлива ланка цього ланцюга."},{t="Зрада при дворі",b="Те, що такий високий вельможа, як Лесковар, змовляється просто з убивцями Дефіас на кшталт Марзона Тихого Клинка, показує, наскільки прогнило політичне серце Стормвінда за відсутності короля Варіана Рінна. Придворні вельможі смикають за ниточки зсередини, розбійники тиснуть на кордони з Вестфолу й Гір Редріджу — і удар по Лесковару стає спробою вирізати гнійну пухлину, перш ніж королівство розвалиться остаточно."}},faq={{q="Чому Еллінг Тріас хоче розв'язати це поза законом?",a="Лорд Лесковар має величезний вплив і багатство в Домі Вельмож. Звинувачувати високопоставленого лорда звичайним судовим шляхом без незаперечних — і політично згубних — доказів означало б, що докази, найпевніше, приховають, а викривачів стратять. Тріас розуміє, що єдиний надійний спосіб знешкодити загрозу — пряма таємна дія.",al={"чому поза законом","несудова справедливість тріаса","чому самосуд"}},{q="Де ховається Тиріон?",a="Тиріон ховається в королівських садах Фортеці Стормвінда — ліворуч від двору, щойно пройдете головну браму. Він зачаївся в кущах і стежить за покоями лорда Лесковара, не привертаючи уваги вартових.",al={"де тиріон","знайти тиріона","місце тиріона"}},{q="Хто такий Тиріон?",a="Тиріон — таємний агент і довірена людина Еллінга Тріаса. Кілька тижнів він стежив за Фортецею Стормвінда, вистежуючи лорда Ґреґора Лесковара й розплутуючи його таємні зв'язки з Дефіас.",al={"хто такий тиріон","гном тиріон","друг тріаса"}},{q="Хто такий лорд Лесковар?",a="Лорд Ґреґор Лесковар — знатний шляхтич Стормвінда, що таємно співпрацює з Братством Дефіас: він їхній високопоставлений крот, який підточує королівство зсередини, з самого королівського двору.",al={"лорд лесковар","хто такий лесковар","лесковар дефіас"}},{q="Хто такий Марзон?",a="Марзон, знаний як Тихий Клинок, — добірний убивця Дефіас, що безпосередньо зв'язується з лордом Лесковаром, щоб узгоджувати напади й убивства від імені Братства.",al={"марзон","марзон мовчазне лезо","мовчазне лезо"}},{q="Чому Тиріон непокоїться за свою репутацію?",a="Мало того що можна зірвати прикриття під час таємного стеження, — Тиріон уїдливо скаржиться, як підозріло й непристойно виглядає, коли поруч із ним у королівських кущах товчуться важкоозброєні шукачі пригод просто під носом у вартових замку.",al={"тиріон ховається в кущах","репутація в кущах"}}},fp="23,270,24.446.0,21.424.0,20.452.1,56.365.0,23.224.0,14.203.0,21.197.0,14.173.1,43.257.0"}
P.entries["quest:2746"] = {n="Речі неабиякої ваги",s="Щоб пронести свого механічного шпигуна до Фортеці Стормвінда й підслухати Лорда Лесковара, таємний агент Тиріон потребує дуже певного набору матеріалів для маскування. Вам доведеться добути тонкий шовк і хрусткі садові яблука, щоб скласти химерну личину, з якою можна непомітно оминути королівських вартових.",h="Щоб пронести свого механічного шпигуна до Фортеці Стормвінда й підслухати Лорда Лесковара, таємний агент...",kw={"речі неабиякої ваги","тиріон","ґреґор лесковар","шпигобот","молот присмерку","фортеця стормвінда"},ang={["class:Rogue"]="Робота пліч-о-пліч з агентами на кшталт Тиріона й Еллінга Тріаса показує незвичні методи стеження SI:7 — і те, як внутрішня розвідка діє просто під носом у знаті.",["faction:Alliance"]="Щоб уберегти юного короля Андуїна й Верховного Лорда Болвара Фордрагона, треба викорінити продажних аристократів, які змовляються з розбійниками в самій Фортеці Стормвінда.",["profession:Tailoring"]="Імпровізований задум Тиріона потребує справжньої шовкової тканини — нагадування кравцям, що добірні тканини потрібні для таємних інтриг не менше, ніж для урочистих суконь."},sec={{t="Стислі строки",b="Звістка від сироторговця Еллінга Тріаса прискорила операцію проти Лорда Ґреґора Лесковара. Підозрюючи, що підступи вельможі у Фортеці Стормвінда становлять безпосередню загрозу для королівства, Тріас наполіг на тому, щоб пересунути строки. Тиріон, що ховається в садах Фортеці Стормвінда, погоджується пришвидшити операцію, але наполягає: зібрати потрібне для проникнення спорядження треба ретельно."},{t="Мистецтво маскування",b="План Тиріона тримається на незвичайному знарядді — Шпигоботові, невеликому механічному пристрої, який має прослизнути повз пильну замкову варту до Лесковара у фортеці. Не покладаючись на саму лише скритність, Тиріон майструє химерне жіноче маскування, щоб відвести підозри. Щоб довершити цей маскарад, він посилає агентів до саду Клари одразу за міськими мурами по яблука потрібного розміру, а ще вимагає сувої шовкової тканини, щоб пошити ляльці вбрання."},{t="Викриття зради",b="Тиріон розкриває, що спершу стежив за Лордом Лесковаром зовсім не через Братство Дефіас, а через підозрілі ниточки, що пов'язували вельможу з культом Молота Присмерку. Відкриття, що Лесковар активно змовляється з Дефіас, робить його подальше перебування при королівському дворі неприпустимим — і звичайне стеження перетворюється на ризиковану пастку в самому серці королівства."}},faq={{q="Навіщо Тиріонові яблука й шовк?",a="Тиріон майструє своєму механічному розвідникові, Шпигоботу, своєрідне жіноче перевдягання, щоб той прослизнув повз королівську варту у Фортеці Стормвінда, не здійнявши тривоги. З шовку шиють імпровізоване вбрання, а яблука з ферми Клари надають саме тієї форми, якої бракує для повної ілюзії.",al={"навіщо яблука","навіщо яблука тиріону","матеріали маскування тиріона","маскування шпигобота"}},{q="На кого працює Тиріон?",a="Тиріон діє разом з Еллінгом Тріасом — продавцем сиру зі Старого Міста, що має в Стормвінді власну мережу друзів; Тріас визнає, що ця операція лише опосередковано робить послугу Матіасові Шоу й SI:7.",al={"кому звітує тиріон","вірність тиріона","еллінг тріас тиріон"}},{q="Де взяти яблука Клари?",a="Ферма Клари — одразу за міською брамою Стормвінда, на півночі Лісу Елвінн. Свіжі яблука можна зібрати просто в її скромному садку.",al={"місце ферми клари","де яблука клари","свіжі яблука стормвінд"}},{q="У чому Тиріон спершу підозрював лорда Лесковара?",a="Спершу Тиріон і Тріас ішли слідами, що вказували на зв'язки лорда Лесковара зі зловісним культом Молота Присмерку. Викриття його співпраці з Братством Дефіас довело, що його зрада сягає набагато глибше й безпосередньо загрожує короні.",al={"лесковар сутінковий молот","чому розслідували лесковара","історія тиріона і лесковара"}},{q="Що далі, коли доставиш ці речі?",a="Щойно Шпигобота спорядять і відправлять у фортецю, вам доручать особисто зійтися зі змовниками й знищити їх у наступному завданні — «Атака!».",al={"що далі","після речей неабиякої ваги","наступне завдання після речей неабиякої ваги"}},{q="Навіщо механічний шпигобот, а не прокрастися самому?",a="Фортецю Стормвінда пильно стережуть королівські вартові, які прискіпливо оглядають кожного, хто заходить до тронної зали й приватних дворів. Перевдягнений жрицею, Шпигобот може пройти повз варту й заговорити з Лесковаром, виманивши його в сад на зустріч із Марзоном, — туди, куди жодному відомому агентові не підібратися.",al={"навіщо шпигобот","чому не прокрастися самому","охорона замку стормвінда"}}},fp="25,301,21.425.0,23.479.0,18.415.1,43.293.0,26.209.0,31.150.0,58.253.1,51.173.1,62.299.0"}
P.entries["quest:275"] = {n="Виразки на землі",s="«Виразки на землі» — завдання Альянсу від Ретіеля Зеленовартового на східних гребенях Багнокраю. Відчуваючи, як болото охоплює неприродна хвороба, самотній охоронець — болотяна потвора — доручає мандрівникам винищити хворих болотяних повзунів, що нишпорять протоками. Упокоїти ці шкандибаючі рослинні жахіття — спроба Ретіеля збити дедалі сильнішу гарячку боліт.",h="«Виразки на землі» — завдання Альянсу від Ретіеля Зеленовартового на східних гребенях Багнокраю.",kw={"виразки на землі","ретіель зеленовартовий","болотяні повзуни","болота","багнокрай","скверна"},ang={["class:Druid"]="Місія Ретіеля прямо відбиває друїдський обов'язок зцілювати світ природи — очищати його від розбурханих стихійних пошестей, щоб земля повернулася до рівноваги.",["class:Shaman"]="Болотяні повзуни — спотворені втілення землі й води, тож знищити їх — означає вгамувати розладнаних духів стихій.",["race:NightElf"]="Самотній охоронець — болотяна потвора, що став союзником Стормвінда у Східних Королівствах, — показує: навіть духи самої землі шукають допомоги, щоб зцілити поранений край."},sec={{t="Болота, що гнояться",b="Зі свого гаю серед боліт Ретіель Зеленовартовий пильнує мокрі простори Багнокраю. Болота ніколи не були лагідними, але нещодавно трясовиною почала ширитися неприродна хвороба. Ретіель відчуває цю недугу як гарячку, що наростає в самій землі й обертає дику природу на безтямних, шкандибаючих потвор."},{t="Очищення драговини",b="Головна ознака цієї гнилі — поява болотяних повзунів: гниючих стихійних мас болотяної рослинності, що шкандибають протоками. Ретіель називає їх хворими виразками, що набрякають на тілі землі. Оскільки їхнє змучене існування лише сіє неспокій болотами, Зеленовартовий доручає мандрівним союзникам знищувати їх, щоб їхні сплутані рештки безпечно вляглися назад у багно."}},faq={{q="Хто такий Ретіель Зеленовартовий?",a="Ретіель Зеленовартовий — болотяне чудовисько, що живе в Гаю Зеленовартового на сході Багнокраю. Він присвятив себе збереженню природної рівноваги боліт, прагнучи вгамувати недуги землі й стримати зіпсовані стихійні нарости.",al={"хто такий ретіель","ретіель зеленовартовий лор","хто дає виразки на землі"}},{q="Хто такі болотяні повзуни?",a="Болотяні повзуни — ворожі рослинні й болотяні елементалі, що никають водними протоками Багнокраю. Вони схожі на громіздкі, перевальцьовуючі купи ожилих лоз, багна й гниючої болотяної рослинності.",al={"болотяні повзуни","що таке болотяний повзун","повзуни багнокраю"}},{q="Чому Ретіель хоче знищити болотяних повзунів?",a="Ретіель бачить у болотяних повзунах гарячкові, хворобливі прояви недуги, що наростає в болотах. Він вірить, що, знищивши їх, ви дасте їхній формі розчинитися й осісти назад у землю, заспокоївши розтривожений край.",al={"чому вбивати болотяних повзунів","чому виразки на землі"}},{q="Що спричиняє виразки в Багнокраї?",a="Ретіель визнає, що до кінця не знає, чому виразки в Багнокраї множаться. Він лише відчуває, як страждає й плаче земля, і лікує прояви, вгамовуючи заворушення стихій усюди, де вони спалахують.",al={"чому багнокрай хворий","причина хвороби багнокраю"}},{q="Де в Багнокраї водяться болотяні повзуни?",a="Болотяні повзуни никають уздовж вологих проток, багнистих берегів і центральних каналів, що перетинають Багнокрай, особливо біля глибших трясовин на захід від Гаю Зеленовартового.",al={"місця болотяних повзунів","де болотяні повзуни"}},{q="Чи пов'язане це завдання з іншими дорученнями Ретіеля?",a="Так. «Виразки на землі» йдуть за тривогою Ретіеля через гнолів-Мохошкірих, що палять дерева Багнокраю, у завданні «Табу на вогонь» — це частина його невпинних зусиль зберегти рівновагу боліт.",al={"лінія зеленовартових","завдання ретіеля"}}},fp="20,377,19.363.0,17.427.0,31.249.0,22.183.0,49.222.0,42.213.0,45.172.0,51.201.0"}
P.entries["quest:2751"] = {n="Варварські бійниці",s="Варварські бійниці — перше випробування, яке дає Орокк Омош, літній коваль з Оргріммара, що відчайдушно прагне зберегти спадщину предків. Не маючи спадкоємців, Орокк вимагає, щоб коваль-початківець довів, що опанував бронзу й основи ремесла, перш ніж він відкриє таємниці свого мистецтва.",h="Варварські бійниці — перше випробування, яке дає Орокк Омош, літній коваль з Оргріммара, що відчайдушно...",kw={"варварські бійниці","орокк омош","коваль","бронза","ковальство","оргріммар"},ang={["faction:Horde"]="Спадщина Омошів відбиває бойовий дух Орди: виріб із металу має пройти перевірку боєм і скупатися в крові ворогів.",["profession:Blacksmithing"]="Для ковалів Орди це завдання — важлива віха переходу від простих виробів із бронзи й міді до традицій обладунків середнього рівня."},sec={{t="Кінець роду Омош",b="Орокк Омош стоїть над ковадлами Оргріммара з важким тягарем на серці. Двадцять поколінь його родина працювала біля горна, перетворюючи незліченні тонни руди на нищівну зброю й міцні обладунки для Орди. На лихо, Орокк вважає себе особистою поразкою свого роду: він самотній і не може мати нащадків. Перед лицем цілковитого зникнення ремесла Омошів він вирішив відкласти родову гордість і пошукати учня, здатного продовжити збройові традиції його родини."},{t="Випробування металом і зубом",b="Орокк не передасть своїх таємниць аматорові. Щоб довести свою базову вправність біля ковадла, учень мусить принести два візерунчасті бронзові наручі, два бронзові дворучні мечі й пару гострих звірячих пазурів. Для Орокка справжнє ковальство — не мистецтво для пустої розкоші: найвища його честь — бачити обладунки й сталь, скупані в крові ворогів. Виконавши його вимоги, учень переконує старого коваля, що спадщина його роду, можливо, житиме в дусі, і відчиняє двері до глибших прийомів обробки металу."}},faq={{q="Хто такий Орокк Омош?",a="Орокк Омош — майстер-коваль з Оргріммара. Він — двадцяте покоління ковалів роду Омош, але не має ні рідні, ні спадкоємців, тож вирішив навчити чужинця, аби ремісничі таємниці його клану не зникли.",al={"орокк омош","хто такий орокк","коваль омош"}},{q="Чому Ороккові потрібен хтось інший, щоб навчати?",a="Орокк не може мати дітей, і в нього не лишилося рідні, яка успадкувала б майстерню. Без учня, якому можна передати креслення й прийоми, ковальські знання, тяжко здобуті двадцятьма поколіннями, помруть разом із ним.",al={"чому учень","спадкоємець орокка","чому спадщина омош згасає"}},{q="Які речі потрібні, щоб довести Ороккові свою вправність?",a="Орокк вимагає двоє візерункових бронзових наручів, два виковані бронзові дворучні мечі й два гострі пазурі лютих хижих звірів.",al={"що потрібно для варварських бійниць","речі для варварських бійниць","здати варварські бійниці"}},{q="Що далі після «Варварських бійниць»?",a="Задоволений вашим базовим опануванням бронзи, Орокк продовжує навчання завданням «Про залізні наплічники», ведучи до важчого кування заліза й складних латних обладунків.",al={"наступне завдання","ланцюжок після варварських бійниць","що далі"}}},fp="20,304,25.511.0,25.482.0,19.248.0,42.214.0,53.130.0,49.178.0"}
P.entries["quest:2753"] = {n="Утоптані в землю",s="Утоптані в землю — поглиблене ковальське випробування, яке дає Орокк Омош у Долині Честі Оргріммара. Викувавши чимало частин обладунку із зеленого заліза, ковалі доводять свою витривалість і опановують виготовлення важких залізних чобіт. Наприкінці вони здобувають таємні прийоми, що передаються в роду Омошів.",h="Утоптані в землю — поглиблене ковальське випробування, яке дає Орокк Омош у Долині Честі Оргріммара.",kw={"утоптані в землю","орокк омош","зелене залізо","залізні чоботи","коваль","долина честі"},ang={["faction:Horde"]="Уроки Орокка дають креслення міцних залізних обладунків, скроєних під жорстоке бойове вчення, якого тримаються на всіх фронтах Орди.",["profession:Blacksmithing"]="Це завдання — важлива віха для бронярів Орди: щоб відкрити особливі креслення чобіт, доведеться чимало виплавляти залізо й готувати зелену фарбу."},sec={{t="Випробування Омоша",b="Орокк Омош навчає бронярів в Оргріммарі, висуваючи нещадні фізичні вимоги. Для Орокка обробка металу — не лише нагрівати руду й вибивати форми молотом, а випробування витривалості на честь родового клану. Утоптані в землю — третє випробування в його суворому ланцюжку: він вимагає знову й знову кувати загартовані обладунки із зеленого заліза, щоб виплекати в майстрові силу й дисципліну."},{t="Спадщина вождя Ґорокка",b="Ковалі, що приносять замовлені комплекти спорядження із зеленого заліза, заслуговують на рідкісну похвалу від суворого броняра. Орокк порівнює майстра, що витримав цю виснажливу роботу, зі своїм дідом — вождем Ґорокком з роду Омош. Навзамін за викувані обладунки Орокк передає родове креслення міцних залізних чобіт — взуття, у якому воїни Орди топтатимуть ворогів."}},faq={{q="Хто дає завдання «Утоптані в землю»?",a="Це завдання дає Орокк Омош — орк-бронник з Долини Честі в Оргріммарі.",al={"хто дає завдання","хто дає утоптані в землю","місце орока омоша"}},{q="Що вимагає Орокк Омош для цього випробування?",a="Орокк вимагає чотири Зелені Залізні Шоломи, чотири пари Зелених Залізних Наручів і дві пари Зелених Залізних Поножів — так коваль доводить, що опанував роботу із зеленим залізом.",al={"що вимагає орокк омош","здати утоптані в землю","потрібні матеріали"}},{q="Який лор стоїть за ланцюжком навчання Омош?",a="Орокк Омош випробовує молодих ковалів виснажливою фізичною працею, шануючи бойову спадщину своїх предків. Він вірить, що важке ремесло бронника гартує силу, без якої не створити спорядження, здатного витримати жорстоку війну.",al={"чому орокк змушує кувати обладунок","лор клану омош"}},{q="Хто такий Вождь Ґорокк з роду Омош?",a="Вождь Ґорокк з роду Омош — дід Орокка Омоша. Орокк високо шанує бойову звитягу свого діда й порівнює з легендарним вождем кожного коваля, що витримає його важкі залізні випробування.",al={"вождь ґорокк","дід орокка"}},{q="Яке завдання йде перед «Утоптаними в землю»?",a="«Утоптані в землю» йдуть безпосередньо за завданням «Про залізні наплічники», продовжуючи багатоетапну низку випробувань Орокка в ремеслі бронника.",al={"передумова","попереднє завдання в ланцюжку"}},{q="Яке завдання йде після «Утоптаних у землю»?",a="Після цього завдання Орокк Омош пропонує «Роги Шаленства» — передостанній з двох уроків, що лишилися, перш ніж низка завершиться «Радощами роду Омош».",al={"наступне завдання","що після утоптаних в землю"}}},fp="19,326,19.394.0,22.381.0,41.101.0,45.150.0,49.229.0,29.204.0,40.131.0,60.143.0"}
P.entries["quest:2755"] = {n="Радощі роду Омош",s="Радощі роду Омош — зворушлива завершальна мить між ковалем Орокком Омошем і шукачем пригод, що допоміг йому в Оргріммарі. Розчулений до сліз, старий коваль запевняє, що йому просто сажа потрапила в око, а тоді показує заповітну родинну традицію. Виконавши запальний танок радості Омоша, він передає незвичайну частку родинної спадщини.",h="Радощі роду Омош — зворушлива завершальна мить між ковалем Орокком Омошем і шукачем пригод, що допоміг йому в...",kw={"радощі роду омош","орокк омош","танок радості","коваль","долина честі","оргріммар"},ang={["faction:Horde"]="Долина Честі — осередок бойової гордості, тож сльози радості Орокка й завзятий танок — зворушливе видовище серед брязкоту сталі Оргріммара.",["profession:Blacksmithing"]="Для ковалів, звиклих до суворого, мовчазного жару кузні, сентиментальний родинний танок Орокка — несподівано кумедний і ніжний погляд в особисте життя старого майстра."},sec={{t="Сльоза в сажі",b="Орокк Омош — кремезний коваль, що працює біля пекучого жару горна в Оргріммарі; він відомий радше важкими ударами по ковадлу, ніж виявом почуттів. Та, отримавши велику допомогу від шукача пригод, навіть цей загартований майстер не може стримати хвилювання. Він уперто запевняє, що йому в око потрапила сажинка, аби тільки не визнати, що плаче."},{t="Традиція Омошів",b="Замість тихо попрощатися, Орокк наполягає на тому, щоб відкрити ще одну, останню таємницю роду Омош, — тоді він зможе померти щасливим. Він одразу пускається в запальний і виснажливий танок радості Омоша, показуючи учневі цю жваву традицію, а потім навчає його бити залізним кулаком."}},faq={{q="Хто такий Орокк Омош?",a="Орокк Омош — орк-коваль з Долини Честі в Оргріммарі. Він палко пишається ремеслом і родоводом своєї родини, поєднуючи ковальську майстерність із живими родинними традиціями.",al={"хто такий орокк","передісторія орокка омоша","коваль орокк"}},{q="Чому Орокк плаче?",a="Орокк запевняє, що він не плаче — це просто кіптява з горна потрапила в око. Насправді він глибоко зворушений вашою допомогою, бо знайшов того, з ким гідно поділитися традиціями роду.",al={"чому орокк плаче","чи орокк сумний","кіптява в оці"}},{q="Що таке танець радості роду Омош?",a="Танець радості — енергійне дійство, яке передають у роду Омош з покоління в покоління. Для Орокка воно дуже виснажливе, бо він давно не танцював цього святкового танцю.",al={"танець омош","танець радості","що за танець"}},{q="Де відбувається це завдання?",a="Завдання відбувається в Оргріммарі, а саме біля ковальського горна в Долині Честі, де Орокк Омош кує свій метал.",al={"місце завдання","де радощі роду омош","кузня оргріммара"}},{q="Чого вас навчає Орокк?",a="Крім того, що Орокк показує енергійний танець радості роду Омош, він обіцяє передати знання про залізний кулак, скріплюючи зв'язок між ковалем і шукачем пригод.",al={"нагорода омош","чого я вчуся","кулак із заліза"}},{q="Чи можуть узяти участь у цьому завданні гравці Альянсу?",a="Ні. Орокк Омош — союзник Орди й живе за укріпленими мурами Оргріммара, тож ця пригода — лише для шукачів пригод з Орди.",al={"радощі омош альянс","чи лише для орди"}}},fp="13,351,19.368.0,19.304.0,19.194.0,20.228.0,31.197.0,33.137.0,26.164.0,47.149.0"}
P.entries["quest:276"] = {n="Тупіт лап",s="«Тупіт лап» — завдання Альянсу від Ретіеля Зеленовартового в Гаю Зеленовартового в Багнокраї. Стривожений тим, як стрімко множаться гноли-Мохошкірі біля Брами Алґаз, захисник — болотяна потвора — доручає шукачам пригод прорідити їхні лави, поки їхні вогнища й тупіт лап не знищили болото.",h="«Тупіт лап» — завдання Альянсу від Ретіеля Зеленовартового в Гаю Зеленовартового в Багнокраї.",kw={"тупіт лап","ретіель зеленовартовий","мохошкірі","гноли","брама алґаз","багнокрай"},ang={["class:Druid"]="Місія Ретіеля прямо відбиває кенарійський обов'язок підтримувати рівновагу природи — стримувати неприродні сплески чисельності, щоб болото не загинуло.",["race:Dwarf"]="Оскільки гноли кишать просто біля Брами Алґаз, прорідивши їх, ви не лише бережете драговину, а й убезпечуєте важливу дорогу між Айронфорджем і Гаванню Менетіл.",["race:NightElf"]="Нічні ельфи мають давній зв'язок із дикими духами природи, тож прохання Ретіеля зцілити болото для них — знайомий і шанований обов'язок."},sec={{t="Загроза, що ширшає драговиною",b="Багато років гноли-Мохошкірі жили в Багнокраї, не руйнуючи до краю його природного ладу. Та останнім часом їхні зграї розрослися й посунули на південь, до перевалу Дун Алґаз. Їхні важкі чоботи й лапи витоптують рідкісні болотяні рослини, а грубе вирубування оголює важливі гаї, щоб годувати вогнища в таборах. Якщо їх не спинити, зграї, що множаться, загрожують зруйнувати тендітну болотяну природу."},{t="Присуд Зеленовартового",b="Ретіель Зеленовартовий пильнує болота, дбаючи про рівновагу, а не про цивілізацію. Для Зеленовартового біда не в тому, що гноли існують, а в тому, що їх стало більше, ніж Багнокрай здатен прогодувати. Повертаючи чисельність гнолів-Мохошкірих і їхніх покручів до розумних меж, шукачі пригод допомагають уберегти болота й здобувають неохоче схвалення прадавнього охоронця дикої природи."}},faq={{q="Хто такий Ретіель Зеленовартовий?",a="Ретіель — болотяне чудовисько, що живе в Багнокраї при шляху між кордонами Айронфорджа й Араті. Відданий збереженню боліт, він стежить за здоров'ям краю й просить мандрівників стримувати тих, хто його нищить.",al={"лор ретіеля","хто дає тупіт лап","зеленовартовий багнокрай"}},{q="Чому гноли-Мохошкірі стали бідою саме тепер?",a="Колись зграя Мохошкірих жила в болотах, не завдаючи тривалої шкоди, але тепер, коли їх стрімко побільшало, вони вирубують ліс на дрова й витоптують ніжну болотяну рослинність.",al={"чому вбивати гнолів багнокраю","загроза мохошкірих гнолів"}},{q="Де гноли завдають цієї шкоди?",a="Гноли-Мохошкірі та їхні дворняги збираються великими гуртами на півдні Багнокраю, особливо біля дворфійського перевалу Дун Алґаз.",al={"де мохошкірі гноли","місце тупоту лап"}},{q="Що далі, коли гнолів проріджено?",a="Коли зграї проріджено, Ретіель глибше досліджує, чому вони так дивно поводяться й палять стільки дров, і посилає шукачів пригод на наступне завдання — «Табу на вогонь».",al={"наступне завдання після тупоту лап","продовження тупоту лап"}},{q="Чому Ретіель згадує, що його віру випробовували?",a="Ретіель каже вам, що його віру у ваш народ уже не раз випробовували, і насторожено ставиться до смертних та їхнього стрімкого поширення. Допомагаючи йому захищати дике болото, смертні шукачі пригод доводять, що можуть бути охоронцями природи, а не її визискувачами.",al={"діалог ретіеля","віру обкладали податком"}}},fp="13,305,21.407.0,26.403.0,31.235.0,42.207.0,41.145.0,36.169.1,49.255.0"}
P.entries["quest:277"] = {n="Табу на вогонь",s="«Табу на вогонь» — доручення від Ретіеля Зеленовартового на болотяних дорогах Багнокраю. Мучачись стражданнями місцевого лісу, болотяна потвора посилає мандрівників відібрати в гнолів-Мохошкірих грубі кремені, якими вони розпалюють і палять живе дерево. Позбавивши гнолів вогню, Ретіель сподівається вберегти прадавнє гілля боліт від полум'я.",h="«Табу на вогонь» — доручення від Ретіеля Зеленовартового на болотяних дорогах Багнокраю.",kw={"табу на вогонь","ретіель зеленовартовий","мохошкірі","кремені","гноли","багнокрай"},ang={["class:Druid"]="Як охоронці дикої природи, друїди поділяють благоговійний зв'язок Ретіеля з деревами й розуміють неприродний біль живого дерева, яке кидають у гнолівські ватри.",["faction:Alliance"]="Гноли-Мохошкірі загрожують мандрівникам, що проходять Багнокраєм; допомагаючи місцевим духам, ви вбезпечуєте торгові шляхи між Дун Мороґом і Араті."},sec={{t="Мука Зеленовартового",b="Rethiel the Greenwarden watches over the wilds of the Wetlands, maintaining a profound spiritual kinship with the trees of the marsh. While the natural cycle of rot and renewal belongs in a swamp, the deliberate destruction of the timber cuts deep into Rethiel's spirit. To a living spirit of the marsh, hearing the groans of living boughs chopped down and cast into hearthfires is an agony Rethiel can no longer endure in silence."},{t="Загасити Мохошкірих",b="The Mosshide pack ravages the wetlands for warmth and territory, felling green trees rather than gathering fallen deadwood. To curb their expansion without a prolonged war of attrition, Rethiel targets the key tool of their destruction: the crude flints used by the stronger gnolls. By stripping the pack of fire-making implements, Rethiel renders them unable to burn the felled timber. Rethiel personally shatters each collected stone and casts the dust into the sea, ensuring those sparks will never ignite the forest again."}},faq={{q="Хто такий Ретіель Зеленовартовий?",a="Rethiel the Greenwarden is a bog beast dwelling in the Wetlands. Bound deeply to the vitality of the local trees and plant life, Rethiel seeks to protect the wounded swamp from the depredations of the Mosshide gnolls.",al={"хто такий ретіель","ретіель зеленовартовий лор","хто дає табу на вогонь"}},{q="Чому Ретіелю потрібні грубі кремені, а не смерть ватажків гнолів?",a="Rethiel considers burning living wood an unpardonable violation. By seizing the flints, Rethiel directly prevents the gnolls from lighting fires to consume the wetland's trees, crippling their encampments and ending the destruction of living wood.",al={"чому кремені","чому взяти кремені","призначення грубого кременя"}},{q="Що стається з кременями, коли їх віддати?",a="Ретіель розтрощує грубі кремені на друзки й кидає рештки в море, щоб ними вже ніколи не можна було викресати іскру проти живого дерева.",al={"що вона робить із кременями","знищення кременів"}},{q="Які гноли носять кремені?",a="Грубі кремені носять сильніші члени зграї Мохошкірих. Дрібнішим гнолам-Мохошкірим і слабшим дворнягам знаряддя для розпалювання вогню не довіряють, і вони їх не мають.",al={"хто дропає кремені","які гноли мають грубий кремінь"}},{q="Навіщо Мохошкірі рубають дерева?",a="Гноли-Мохошкірі рубають живі дерева, щоб палити вогнища й зігріватися у вологому болоті, замість того щоб збирати сухий хмиз.",al={"чому гноли рубають дерева","мохошкірі рубають ліс"}},{q="Що далі, коли кремені зібрано?",a="Коли ви позбавите гнолів вогню, Ретіель посилає вас боротися з іншою пошестю, що вразила болота, — у наступному завданні «Виразки на землі».",al={"яке завдання після табу на вогонь","наступне завдання після кременів"}}},fp="10,366,23.431.0,27.526.0,31.217.0,72.247.0,51.154.0,30.175.0,41.147.0,43.152.1"}
P.entries["quest:278"] = {n="Насувається темна загроза",s="Це завдання — вирішальний крок у захисті Каменетесної Греблі від імовірної змови Темного Заліза. Головний Інженер Гіндервір VII доручає шукачам пригод зібрати по всьому Лох Модану рідкісні хімічні й органічні реагенти для знешкоджувальної суміші. Без цих складників оборонці не зможуть нейтралізувати вибухівку, закладену під велетенську кам'яну кладку.",h="Це завдання — вирішальний крок у захисті Каменетесної Греблі від імовірної змови Темного Заліза.",kw={"насувається темна загроза","гіндервір","каменетесна гребля","лісовий причаюн","кроколіски","мо'ґрош","знешкоджувальна суміш"},ang={["faction:Alliance"]="Якщо загрозу греблі не знешкодити, станеться катастрофа, яка переріже важливі суходільні шляхи постачання між Айронфорджем і північними королівствами.",["profession:Engineering"]="Інженери оцінять винахідливість Гіндервіра, що вигадав хімічний протизасіб, здатний просто в полі приборкати нестійкі підривні заряди.",["race:Dwarf"]="Для дворфів Каз Модану зупинити диверсію Темного Заліза на Каменетесній Греблі — важливий обов'язок захисту прадідівських земель і будівельних звитяг."},sec={{t="Небезпечний рецепт",b="Щоб протидіяти нестійким вибуховим сумішам диверсантів Темного Заліза, Головний Інженер Гіндервір VII покладається на незвичний хімічний нейтралізатор. Звичайна вода чи вогкий пісок тут не допоможуть: щоб знешкодити вибуховий порох Темного Заліза, потрібна сильна суміш з отрути місцевого Лісового Причаюна, сльози кроколіска з озера й кристала Мо'ґрош. Кожен складник має особливі активні властивості, без яких підривні заряди не стануть цілком безпечними."},{t="Небезпечні пошуки",b="У пошуках цих складників шукачі пригод вирушають у найворожіші закутки Лох Модану. Павуки-причаюни й озерні кроколіски — звичайна небезпека дикої природи, а от щоб здобути кристал Мо'ґрош, доведеться сунутися до огрячої твердині в північно-східних пагорбах. Огри Мо'ґрош ревно стережуть ці рідкісні мінерали, тож кожен, хто хоче захистити греблю, мусить пробиватися крізь табори звірюк, щоб здобути зразок."}},faq={{q="Навіщо Інженерові Гіндервіру саме ці реагенти?",a="Головний Інженер Гіндервір VII готує особливу знешкоджувальну суміш, щоб знешкодити вибухівку Темного Заліза. Їдка отрута чатувальників, виділення кроколісків і магічні мінерали з кристалів Мо'ґрош дають саме ті хімічні реакції, що роблять складні диверсійні заряди безпечними.",al={"навіщо павучий яд","навіщо сльоза кроколіска","реагенти розряджувальної суміші"}},{q="Звідки беруться кристали Мо'ґрош?",a="Кристали добувають і накопичують огри Мо'ґрош, що засіли на північно-східних пагорбах Лох Модану. Огри вважають їх рідкісним і цінним скарбом, тож щоб здобути хоч один, доведеться вирушити на їхню добре захищену землю.",al={"де кристали","місце кристала мо'ґрош","у кого кристал"}},{q="Яка темна загроза нависла над Лох Моданом?",a="Загроза — диверсанти з дворфів Темного Заліза, що прагнуть зруйнувати Каменетесну Греблю. Якщо знищити це величне диво інженерії, вода затопить Багнокрай унизу, переріже шляхи постачання Альянсу й спустошить край.",al={"яка темна загроза","хто нападає на греблю","сюжет насувається темна загроза"}},{q="Хто такий Головний Інженер Гіндервір VII?",a="Він — головний дворфійський інженер, що наглядає за роботою й цілісністю Каменетесної Греблі. Він керує і технічним обслуговуванням, і місцевою обороною від диверсій.",al={"хто такий гіндервір","головний інженер гіндервір"}},{q="Де шукати місцевих створінь?",a="Павуки Лісові Причаюни никають лісовою глушиною довкола долини, а кроколіски живуть у самому озері й на його берегах.",al={"де лурки","місце кроколісків","де шукати павуків"}},{q="Чому вартові Айронфорджа не зберуть ці речі самі?",a="Горяни й місцева варта розпорошені: вони боронять містечка на кшталт Телсамара й пильнують розвідників Темного Заліза. Особливі доручення з добування припасів і набіги на землі огрів зазвичай доручають вправним мандрівним шукачам пригод.",al={"чому допомагати гіндервіру","де вартові айронфорджа"}}},fp="19,371,17.497.0,18.434.0,58.296.0,37.248.0,44.225.0,37.186.0,44.140.0,61.241.0"}
P.entries["quest:280"] = {n="Насувається темна загроза",s="Відчайдушне термінове доручення Головного Інженера Гіндервіра VII — не дати зруйнувати Каменетесну Греблю. Диверсанти Темного Заліза заклали глибоко під водою вибуховий сіфоріумний заряд, і він загрожує розтрощити одне з найбільших інженерних див дворфійського королівства.",h="Відчайдушне термінове доручення Головного Інженера Гіндервіра VII — не дати зруйнувати Каменетесну Греблю.",kw={"насувається темна загроза","каменетесна гребля","гіндервір","сіфоріум","темне залізо","диверсія"},ang={["faction:Alliance"]="Руйнування Каменетесної Греблі спустошило б важливі шляхи сполучення між Каз Моданом і північними землями Альянсу.",["profession:Engineering"]="Робота просто із сіфоріумом і спеціальними знешкоджувальними речовинами — крайній, ризикований випадок застосування підривної справи й хімії протидії вибухам.",["race:Dwarf"]="Каменетесна Гребля — незнищенний пам'ятник дворфійського будівництва й гордості; захистити її від підступності Темного Заліза — справа першорядної ваги для кожного сина й доньки Айронфорджа.",["race:Gnome"]="Гномський розум оцінить і вишукану хімію Гіндервірового нейтралізатора, і жахливі руйнування, яких завдав би дворфійській інженерії сіфоріумний пролом."},sec={{t="Диверсія під водою",b="Головний Інженер Гіндервір VII помітив повстанців Темного Заліза, що пливли до підніжжя Каменетесної Греблі з величезною бочкою вибухового сіфоріуму. Поблизу не було горян, які могли б утрутитися, тож лазутчики закріпили заряд просто на підводному фундаменті греблі. Пролом випустив би всю воду озера в низовини, спричинивши нищівну повінь і підрізавши дворфійську торгівлю й сполучення в усьому краї."},{t="Небезпечний нейтралізатор",b="Швидко змішавши активні складники в знешкоджувальну суміш, Гіндервір посилає сміливого нирця просто до затопленої бомби. Щоб знешкодити сіфоріум, треба відкрутити затоплену бочку й влити хімічний розчин просто у вибуховий порох. Суміш спиняє відлік тихим підводним шипінням і приборкує заряд, перш ніж вибух устигне розірвати кладку."}},faq={{q="Яка мета цього завдання?",a="Треба пірнути у води Лох Модану до підніжжя Каменетесної Греблі, знайти підкладене барило із сіфоріумом і влити в нього знешкоджувальну суміш Головного Інженера Гіндервіра, щоб запобігти вибуху.",al={"мета завдання","що тут робити","мета насувається темна загроза 6"}},{q="Хто підклав барило з вибухівкою?",a="Повстанці Темного Заліза пробралися у води Лох Модану того ж дня, скориставшись відсутністю місцевих горян, і заклали заряд сіфоріуму просто біля підводної стіни греблі.",al={"хто підклав бомбу","хто заклав сіфоріум","винуватці темної загрози"}},{q="Що буде, якщо греблю зруйнують?",a="Каменетесна Гребля стримує величезне озеро Лох Модану. Якщо її розтрощать, незліченні тонни води ринуть у Багнокрай і довколишні долини, змиваючи шляхи, містечка й життя.",al={"навіщо рятувати греблю","що якщо бомба вибухне","ставки вибуху греблі"}},{q="Хто приготував знешкоджувальну суміш?",a="Головний Інженер Гіндервір VII приготував хімічний знешкоджувач із зібраних реагентів — суміш, здатну знешкодити заряд сіфоріуму, не спричинивши випадкового вибуху.",al={"хто зробив суміш","роль гіндервіра","хто зробив хімікат"}},{q="Де барило з вибухівкою?",a="Барило лежить під водою біля глибоко зануреної основи Каменетесної Греблі, з південного боку, що виходить на озеро.",al={"де бомба","місце барила","порошкове барило під водою"}},{q="Яку вибухівку використали?",a="Диверсанти Темного Заліза використали сіфоріум — потужну й нестійку руйнівну суміш, запаковану в герметичне водонепроникне барило.",al={"з чого бомба","тип бомби","яка вибухівка"}}},fp="19,296,28.448.0,22.400.1,31.209.0,30.208.0,37.212.0,36.197.0,35.120.0,32.125.0"}
P.entries["quest:282"] = {n="Спостереження Сеніра",s="Зібравши важливі відомості про місцеві загрози в Долині Холодного Хребта, Ґрелін Вайтбірд довіряє вам донести його висновки братові, Сеніру Вайтбірдому, в Харанос. Проте, щоб залишити захищену долину, треба пройти тунелем, який недавно захопили ворожі троги й який стереже Горянин Талос.",h="Зібравши важливі відомості про місцеві загрози в Долині Холодного Хребта, Ґрелін Вайтбірд довіряє вам донести...",kw={"спостереження сеніра","ґрелін вайтбірд","сенір вайтбірдий","горянин талос","звіт","тунель","троги","харанос"},ang={["faction:Alliance"]="Безпечний прохід між дворфійськими долинами критично важливий для оборони Айронфорджа й безпеки кур'єрів Альянсу.",["race:Dwarf"]="Для дворфійських горян і новобранців прохід східним тунелем — ваше перше офіційне відрядження за межі навчальних угідь Долини Холодного Хребта.",["race:Gnome"]="Для гномських біженців, що живуть серед Бронзбірдів, ця депеша — шлях із першого прихистку до ширших проблем, що охопили Дун Мороґ."},sec={{t="Кур'єр для Вайтбірдів",b="Ґрелін Вайтбірд доклав чимало зусиль, документуючи тролячу діяльність довкола Долини Холодного Хребта. Коли його щоденник поцупили, а потім повернули, стало ясно, що зібрані відомості надто важливі, щоб довіряти їх недосвідченому учневі. Бажаючи обминути проміжні руки, Ґрелін обирає загартованого шукача пригод, щоб той передав звіт просто його братові, Сеніру Вайтбірдому, який веде справи за межами долини, в Хараносі."},{t="Заблокований перевал до Хараноса",b="Залишити Долину Холодного Хребта більше не проста прогулянка головною дорогою. Східний тунель, що з'єднує долину з ширшим засніженим плато Дун Мороґу, брутально захопили троги-копачі. Щоб необережні цивільні не забрели в смертельну пастку, варта Айронфорджа поставила Горянина Талоса просто перед проходом. Лише мандрівникам із нагальною офіційною справою дозволено минути сторожовий пост і кинути виклик підземній пастці."}},faq={{q="Кому Ґрелін надсилає цей звіт?",a="Звіт адресовано Сенірові Вайтбірду, братові Ґреліна, що стоїть за горами, у Хараносі, й оцінює становище в краю.",al={"кому отримати звіт","сенір вайтбірд","одержувач звіту"}},{q="Чому учень Ґреліна не може доставити звіт?",a="Спершу Ґрелін збирався послати учня, але після недавніх клопотів із тролями-Морозогривами, що вкрали його щоденник, вирішив, що відомості надто важливі, щоб довіряти їх недосвідченим рукам.",al={"чому не учень","учень ґреліна"}},{q="Чому тунель з Долини Холодного Хребта охороняють?",a="Тунель, що сполучає Долину Холодного Хребта з рештою Дун Мороґу, цілком заполонили троги. Горянин Талос стоїть біля входу, щоб уберегти мирних мешканців, поки шлях не розчистять.",al={"чому талос охороняє","тунель заблоковано","чому тунель закритий"}},{q="Де знайти Горянина Талоса?",a="Талос стоїть на схід від Анвілмара й пильнує просто біля входу до тунелю, що веде з Долини Холодного Хребта до Хараноса.",al={"місце талоса","де талос","знайти горянина талоса"}},{q="Що дає змогу пройти тунелем, повним трогів?",a="Горянин Талос не пускає в тунель звичайних мандрівників, але термінове донесення від Ґреліна Вайтбірда доводить, що ваша справа достатньо важлива, щоб ризикнути.",al={"пройти тунель","дозвіл на тунель"}},{q="Що буде після розмови з Горянином Талосом?",a="Талос попереджає про небезпеки й підказує, як пройти небезпечним підземним шляхом, а тоді дозволяє вам рушати далі на схід до Хараноса.",al={"наступний крок","що після талоса"}}},fp="20,320,29.471.0,28.475.0,37.141.0,49.197.0,50.201.0,36.142.0,58.184.0,52.143.0"}
P.entries["quest:283"] = {n="Насувається темна загроза",s="«Насувається темна загроза» — нагальне доручення вберегти Лох Модан від лиха. Шукачам пригод з Альянсу треба застосувати хімічний нейтралізатор проти закладеного вибухового заряду, перш ніж Каменетесна Гребля зазнає нищівної шкоди.",h="«Насувається темна загроза» — нагальне доручення вберегти Лох Модан від лиха.",kw={"насувається темна загроза","каменетесна гребля","знешкоджувальна суміш","гіндервір","темне залізо","лох модан"},ang={["faction:Alliance"]="Відвернувши пролом греблі, ви зберігаєте ключові суходільні коридори між Айронфорджем і північними землями Араті та Лордерона.",["profession:Engineering"]="Знешкодити нестійкий підривний пристрій просто всередині велетенської споруди — яскравий доказ того, як важливі протизаходи й наука про вибухи.",["race:Dwarf"]="Каменетесна Гребля — вершина дворфійського каменярства; захищаючи її, ви бережете гордість і безпеку Айронфорджа від злоби Темного Заліза."},sec={{t="Відвернене лихо",b="Велетенська Каменетесна Гребля стримує неосяжні води озера, височіючи над низовинами Багнокраю. Коли диверсантам Темного Заліза вдалося закласти в споруду вибуховий заряд, усій долині загрожувала руїна. Знешкоджувальна Суміш змушує небезпечну бочку нешкідливо зашипіти — і безпосередня загроза дворфійській інженерії та незліченним життям нижче за течією минає."},{t="Полегшення Гіндервіра",b="Доповідь Головному Інженерові Гіндервіру VII приносить величезне полегшення наглядачам Айронфорджа на греблі. Гіндервір вітає цей вчинок як велику перемогу королівства Айронфордж і Альянсу. Та все ж те, що лазутчики Темного Заліза проникли так глибоко в Каз Модан, — похмуре нагадування: запеклі родичі й далі невтомно прагнуть знищити здобутки Айронфорджа."}},faq={{q="Яка мета цього ланцюжка завдань?",a="Ланцюжок зосереджений на тому, щоб викрити й зупинити змову дворфів Темного Заліза, які хотіли висадити вибухівку й зруйнувати Каменетесну Греблю.",al={"підсумок насувається темна загроза","мета завдання каменетесної греблі","навіщо знешкоджувати бомбу"}},{q="Хто заклав вибуховий заряд?",a="Барило з вибухівкою заклали дворфи-диверсанти з Темного Заліза, намагаючись зруйнувати величезну споруду.",al={"хто підклав бомбу","хто напав на греблю","темне залізо гребля"}},{q="Хто такий Головний Інженер Гіндервір VII?",a="Головний Інженер Гіндервір VII — дворфійський наглядач, що відповідає за обслуговування, роботу й оборону Каменетесної Греблі в Лох Модані.",al={"хто такий гіндервір","гіндервір лор","інженер на греблі"}},{q="Що сталося б, якби гребля прорвалася?",a="Якби Каменетесну Греблю прорвало, величезне водосховище Лох Модану бурхливо спорожніло б, затопивши Багнокрай нижче за течією й змивши шляхи, поселення й важливі транспортні маршрути.",al={"що якщо гребля зруйнується","наслідки прориву греблі","вибух греблі"}},{q="Як знешкодили вибухівку?",a="На заряд вилили особливо приготовану Знешкоджувальну Суміш, і барило з порохом безпечно відсичало, так і не вибухнувши.",al={"як зупинили бомбу","розряджувальна суміш","як знешкодити заряд"}},{q="Чи тепер Каменетесна Гребля в безпеці?",a="Безпосередній вибух вдалося відвернути й греблю врятовано, але Гіндервір зауважує, що оборона надійна лише на якийсь час: агенти Темного Заліза й далі загрожують краю.",al={"чи гребля тепер у безпеці","чи темного заліза немає","чи гребля безпечна назавжди"}}},fp="19,248,19.394.0,19.408.1,38.146.0,33.129.0,37.148.0,42.193.0,31.147.1,33.183.1"}
P.entries["quest:287"] = {n="Твердиня Морозогривів",s="Твердиня Морозогривів — розвідувальне завдання Альянсу, яке дає Сенір Вайтбірдий у Хараносі. Вистеживши ворожих тролів Морозогривів до їхньої добре охоронюваної печерної твердині біля Озера Крижаного Потоку, Сенір залучає відважних розвідників, щоб ті наважилися зайти всередину, знищили їхніх мисливців за головами й здобули життєво важливі відомості для його розвідувальних звітів.",h="Твердиня Морозогривів — розвідувальне завдання Альянсу, яке дає Сенір Вайтбірдий у Хараносі.",kw={"твердиня морозогривів","морозогриви","тролі","сенір вайтбірдий","озеро крижаного потоку","розвідка","мисливці за головами","харанос"},ang={["faction:Alliance"]="Безпека Дун Мороґу гарантує, що гірські дороги, які з'єднують Айронфордж із сусідніми королівствами, лишаться вільними від ворожих племінних засідок.",["race:Dwarf"]="Тролі Морозогриви оскаржують панування Айронфорджа на засніжених вершинах Дун Мороґу; розвідати їхню головну печерну твердиню критично важливо для оборони королівства.",["race:Gnome"]="Поки гноми оселилися по всьому Дун Мороґу й Хараносі після падіння Гномреґану, стримання наступу тролів Морозогривів береже крихкі коридори постачання біженців."},sec={{t="Розвідник, що відстає від графіка",b="Горянин і розвідник Сенір Вайтбірдий, що стоїть у Хараносі, мав стежити за загрозою тролів Морозогривів, яка насувається по всьому Дун Мороґу. Хоч він і успішно простежив зухвалі племена до їхнього головного печерного житла на південний захід від Села Брюнолл, сама кількість озброєних тролів змусила його завагатися. Не наважуючись ступити всередину сам і серйозно відстаючи з офіційними звітами, Сенір наймає подорожніх шукачів пригод вирушити в крижані закапелки замість нього."},{t="Прорив до печери",b="Твердиня вирізана в західних вершинах над Озером Крижаного Потоку — крижаний редут, набитий ворожими крижаними тролями. Щоб виконати завдання Сеніра, розвідники мусять пробитися глибоко підземними тунелями, винищити лютих Мисливців за головами Морозогривів, що стоять на виступах, і скласти карту внутрішнього розташування. Пережити цей спуск — здобути критично важливі відомості, потрібні Сеніру, щоб завершити висновки для військових командирів Айронфорджа."}},faq={{q="Де розташована Твердиня Морозогривів?",a="Твердиня Морозогривів — печера на південний захід від Села Брюнолл на далекому заході Дун Мороґу. З Хараноса йдіть шляхом на північ до мосту, далі вздовж замерзлої річки на захід повз Озеро Крижаного Потоку до Села Брюнолл, а тоді на південний захід у гори.",al={"знайти твердиню морозогривів","де печера","місце твердині морозогривів"}},{q="Хто такий Сенір Вайтбірд?",a="Сенір Вайтбірд — дворф-розвідник, що стоїть біля Ґуральні Тандербрю в Хараносі. Він стежить за загрозами по всьому Дун Мороґу й складає стратегічні розвідувальні звіти про агресивних тролів-Морозогривів.",al={"сенір вайтбірд","хто дає завдання","дає завдання хараніс"}},{q="Чому Сенір сам не обстежив твердиню?",a="Сенір розвідав вхід і з'ясував, де зосередилося плем'я, але печера так кишіла озброєними тролями, що він побоявся заходити сам. Дбаючи про власну безпеку й запізнюючись із розвідкою, він доручає небезпечну справу вправним шукачам пригод.",al={"чому сенір не пішов","чому сенір боїться"}},{q="Хто такі тролі-Морозогриви?",a="Морозогриви — корінне плем'я крижаних тролів, споконвічних мешканців засніжених скель Дун Мороґу. Запеклі вороги дворфів і гномів Айронфорджа, вони раз у раз нападають на торговельні шляхи, табори й поселення зі своїх схованок по всьому краю.",al={"морозогриви","тролі дун морога"}},{q="Що буде, коли твердиню розвідано?",a="Коли ви повернетеся з відомостями про будову твердині й утрати серед їхніх мисливців за головами, Сенір дописує звіт і одразу просить вас доставити термінові папери його начальству в Дун Мороґу.",al={"наступне завдання","що після твердині морозогривів","завдання звітів"}},{q="Як глибоко в печеру треба зайти?",a="Треба пройти далеко за поріг, у внутрішні зали, поки не розвідаєте будову печери й не вб'єте п'ятьох мисливців за головами з Морозогривів — так ви підтвердите, що глибини печери ретельно обстежено.",al={"повністю обстежити твердиню морозогривів","умова огляду печери"}}},fp="14,325,23.484.0,20.448.0,32.264.0,24.222.0,42.295.0,29.249.0,52.210.1,41.215.0"}
P.entries["quest:288"] = {n="Третій флот",s="Сидячи біля Таверни «Глибока Вода» в Гавані Менетіл, Перший Помічник Фіцсіммонс топить спогади в дворфійському меді. Він — єдиний уцілілий із Третього флоту Кул Тіраса, гордої морської сили, яку під час Другої війни біля берегів Багнокраю спалили червоні дракони, поневолені орками.",h="Сидячи біля Таверни «Глибока Вода» в Гавані Менетіл, Перший Помічник Фіцсіммонс топить спогади в...",kw={"третій флот","перший помічник фіцсіммонс","кул тірас","драконяча паща","ґрім батол","гавань менетіл"},ang={["faction:Alliance"]="Розповідь Фіцсіммонса про загибель «Володарки Хвиль» нагадує захисникам Альянсу про шрами, які лишили по всьому Каз Модану вершники драконів з Орди.",["race:Dwarf"]="Ґрім Батол кидав тінь на весь Каз Модан, а дракони, виведені в його глибинах, сіяли спустошення і на дворфійських землях, і серед союзників-людей.",["race:Human"]="Загибель Третього флоту — гірке нагадування про катастрофічні морські битви, які Кул Тірас і Альянс вели проти Драконячої Пащі."},sec={{t="Горе моряка",b="Перший Помічник Фіцсіммонс днями сидить, згорбившись, біля Таверни «Глибока Вода» в Гавані Менетіл, з нескінченним похміллям і спогадами, яких не може позбутися. Колись офіцер на борту «Володарки Хвиль» — лінійного корабля під морським стягом Кул Тіраса, — тепер він обмінює похмурі спогади на кухлі дворфійського меду. Кожен, хто пригостить його ще одним кухлем, почує розповідь очевидця про одну з найнищівніших морських різанин Другої війни."},{t="Вогонь над хвилями",b="Під час Другої війни Третій флот плив уздовж берегів Каз Модану, коли лихо впало з неба. Клан Драконячої Пащі, що підкорив червоне драконяче плем'я в Ґрім Батолі, обрушив драконячий вогонь на нічого не підозрюючі бойові кораблі. Фіцсіммонс пам'ятає, як безпорадні дерев'яні корпуси палали під височенними стовпами полум'я, тягнучи цілі команди на дно. Лише Фіцсіммонса викинуло на берег живим, а його полеглі брати лишилися на водяному цвинтарі, який тепер звуть Приреченим флотом."}},faq={{q="Хто такий Перший Помічник Фіцсіммонс?",a="Це старий моряк, що заливає свою травму біля Таверни «Глибока Вода» в Гавані Менетіл. Колишній перший помічник військового корабля Кул Тірасу «Володарка Хвиль», він — єдиний відомий уцілілий після загибелі Третього флоту.",al={"фіцсіммонс","хто той п'яний матрос","таверна фіцсіммонса"}},{q="Що сталося з Третім флотом?",a="Під час Другої війни Третій флот Кул Тірасу потрапив у засідку й згорів біля узбережжя Багнокраю. Орки з клану Драконячої Пащі на драконах обрушили на нього вогонь згори, і кораблі з моряками пішли на морське дно.",al={"доля третього флоту","як затонув флот","затонулі кораблі кул тірасу"}},{q="Чому дракони нападали на людські кораблі?",a="Під час Другої війни клан Драконячої Пащі поневолив червону драконицю Алекстразу за допомогою Душі Демона в сусідньому Ґрім Батолі. Скуті темним чаклунством, червоні дракони мусили служити Орді жахливими скакунами й облоговою зброєю.",al={"дракони драконячої пащі","червоні дракони багнокрай","чому орки на драконах"}},{q="Де саме затонули кораблі?",a="Обгорілі уламки лежать під водою біля західного узбережжя Багнокраю, на північ від Гавані Менетіл, — трагічне місце, яке тепер згадують як Приречений флот.",al={"де приречений флот","місце уламків у багнокраї","уламки третього флоту"}},{q="Якого напою хоче Фіцсіммонс?",a="Йому потрібен кухоль дворфійської медовухи, щоб розв'язати язик і вгамувати нестерпне похмілля; купити її можна просто в корчмаря в Таверні «Глибока Вода».",al={"медовуха фіцсіммонса","чого хоче фіцсіммонс","кухоль медовухи"}},{q="Якому народові служив Третій флот?",a="Флот належав Кул Тірасу — острівному морському королівству, чий грізний флот був кістяком морських сил Альянсу під час Другої війни.",al={"чи третій флот стормвінда","флот кул тірасу","кому належала володарка хвиль"}}},fp="15,281,16.454.0,19.494.0,30.221.0,33.230.0,39.231.0,34.150.0,33.169.0,38.159.0"}
P.entries["quest:289"] = {n="Проклята команда",s="Перший Помічник Фіцсіммонс, єдиний живий уцілілий із Третього флоту Кул Тіраса, просить милосердя для своїх загиблих побратимів. Скуті темною реліквією, схованою на борту їхніх затонулих кораблів біля берегів Багнокраю, утоплені моряки й морські піхотинці блукають уламками неспокійною нежиттю.",h="Перший Помічник Фіцсіммонс, єдиний живий уцілілий із Третього флоту Кул Тіраса, просить милосердя для своїх...",kw={"проклята команда","перший помічник фіцсіммонс","перший помічник снелліґ","третій флот","кул тірас","нежить"},ang={["class:Paladin"]="Моряки Третього флоту — невинні люди, яких обплутала нечестива реліквія; упокоюючи їх, ви очищаєте нечисте осквернення й несете світло в темні води.",["faction:Alliance"]="Кул Тірас здавна давав Великому Альянсу найкращих моряків; упокоїти їхніх змучених духів — скорботний обов'язок честі для кожного шукача пригод з Альянсу.",["race:Human"]="Мандрівники-люди відчувають братерство з цими полеглими моряками, визнаючи спільні морські традиції королівства Кул Тірас."},sec={{t="Неспокійний флот",b="Коли Третій флот Кул Тіраса розбився об зубчасті береги на північ від Гавані Менетіл, його трагедія не скінчилася під хвилями. Першому Помічникові Фіцсіммонсу пощастило вибратися на берег живим, але його товаришів спіткала доля, гірша за смерть. Загадковий і страшний скарб, схований глибоко в одному з корпусів, наслав на вмираючих моряків моторошні чари: прив'язав їхні душі до побитих морем дощок і позбавив спокою могили."},{t="Милосердя клинка",b="Фіцсіммонса, що вештається шинками Гавані Менетіл, переслідують нічні стогони й крики колишніх товаришів. Вірячи, що, упокоївши їхні ожилі тіла, він дасть їм звільнення, він посилає шукачів пригод у гнилі затоплені корпуси, щоб повалити проклятих моряків, досвідчених морських піхотинців і свого колишнього товариша, Першого Помічника Снелліґа, — і принести особисту табакерку Снелліґа як похмурий доказ того, що його друг нарешті упокоївся."}},faq={{q="Ким був Перший Помічник Снелліґ?",a="Перший Помічник Снелліґ служив у злощасному Третьому флоті Кул Тірасу разом із Першим Помічником Фіцсіммонсом. Коли флот розбився біля північного узбережжя Багнокраю, Снелліґ потонув з рештою команди, але зловісна реліквія на борту кораблів воскресила його. Тепер він — жахлива нежить, що блукає затопленим трюмом одного з уламків.",al={"снелліґ","перший помічник снелліґ","хто такий снелліґ"}},{q="Чому моряки й морські піхотинці прокляті?",a="За словами Фіцсіммонса, один з кораблів флоту віз прихований, лиховісний скарб. Коли кораблі розбилися біля узбережжя, темна енергія цього артефакту прикувала духи потоплих моряків до їхніх гнилих корпусів, не даючи душам відійти й прирікаючи їх на муки нежиття.",al={"чому вони нежить","прокляття третього флоту","причина прокляття моряків"}},{q="Де затонулі кораблі?",a="Зруйновані корпуси Третього флоту лежать під водою біля узбережжя на півночі Багнокраю, на північ від Гавані Менетіл. Проклята команда никає і затопленими палубами, і довколишніми водами, а сам Снелліґ ховається в розколотому корпусі південного корабля.",al={"де кораблі","місце уламків","де снелліґ"}},{q="Навіщо Фіцсіммонсові табакерка Снелліґа?",a="Табакерка була особистою пам'яткою Першого Помічника Снелліґа за життя. Принесена Фіцсіммонсові, вона стає відчутним доказом того, що його проклятий товариш нарешті звільнився зі своєї гнилої в'язниці під хвилями.",al={"табакерка снелліґа","табакерка","навіщо табакерка"}},{q="Хто такий Перший Помічник Фіцсіммонс?",a="Фіцсіммонс — моряк з Кул Тірасу й єдиний відомий живий уцілілий з Третього флоту. Зламаний горем і провиною, він лишається в Гавані Менетіл, і йому сняться жахи про потоплих побратимів; він відчайдушно шукає мандрівників, готових покласти край їхнім мукам.",al={"фіцсіммонс","перший помічник фіцсіммонс"}},{q="Чи справді вбивство команди знімає прокляття?",a="Убиваючи моряків і піхотинців, ви даруєте їхнім неспокійним духам тимчасовий перепочинок, але чари цілком не руйнуються. Корінь прокляття досі пов'язаний із загадковою реліквією, захованою серед уламків.",al={"чи прокляття знято","чи це кінець прокляття"}}},fp="15,279,16.458.0,18.456.1,27.357.0,39.307.0,35.267.0,45.234.0,30.256.0,47.232.1"}
P.entries["quest:290"] = {n="Зняти прокляття",s="Перший Помічник Фіцсіммонс вірить, що неспокійне прокляття, яке сковує його полеглих товаришів, походить від темного артефакту, захованого на борту їхнього розбитого корабля «Безстрашний». Щоб визволити побратимів, шукач пригод має зійтися з привидом Капітана Галіндора, забрати ключ від скрині й дістати реліквію із затопленого корпусу.",h="Перший Помічник Фіцсіммонс вірить, що неспокійне прокляття, яке сковує його полеглих товаришів, походить від...",kw={"зняти прокляття","перший помічник фіцсіммонс","капітан галіндор","безстрашний","третій флот","багнокрай"},ang={["class:Priest"]="Розплутувати духовні недуги й очищати сплюндровані реліквії може лише той, хто має духовну владу, — тому Фіцсіммонс довіряє остаточне очищення вмісту скрині жрецтву.",["faction:Alliance"]="Моряки Третього флоту за життя служили Альянсу, тож упокоїти їхні змучені душі — обов'язок честі для героїв Альянсу, що проходять через Гавань Менетіл."},sec={{t="Тягар капітана",b="Перший Помічник Фіцсіммонс пережив трагічну долю Третього флоту, але пам'ять про товаришів переслідує його і вдень, і вві сні. Він певен, що нежиття, яке скувало його товаришів, пов'язане із загадковим, зловісним предметом, замкненим у скрині його старого корабля «Безстрашний». Над уламками наглядають примарні рештки Капітана Галіндора, що навіть по смерті люто стереже ключ до найглибших таємниць корабля."},{t="Відімкнути глибини",b="Біля оповитого туманом узбережжя північного Багнокраю лежать розтрощені корпуси Третього флоту. У затопленому трюмі «Безстрашного» замкнена скриня ховає реліквію, що лежить в основі мук команди. Щоб повернути її, треба здолати змученого привида Галіндора на палубі, здобути іржавий ключ і спуститися в залиті водою нутрощі, щоб дістати темний артефакт і віддати його в святі руки для очищення."}},faq={{q="Який корабель обшукують у цьому завданні?",a="Ви обшукуєте «Безстрашний» — затонулий корабель Третього флоту біля північно-західного берега Багнокраю.",al={"який корабель","уламки безстрашного","де скриня"}},{q="Хто такий Капітан Галіндор?",a="Капітан Галіндор командував «Безстрашним». Після смерті його неспокійний дух блукає палубою розбитого корабля, вперто тримаючись за ключ від корабельної скрині.",al={"галіндор","лор капітана галіндора"}},{q="Чому Перший Помічник Фіцсіммонс хоче відкрити скриню?",a="Фіцсіммонс вірить, що в скрині заховано прокляту річ, через яку духи його товаришів-моряків мучаться в полоні, і відкрити її — єдиний спосіб дістати артефакт, щоб очистити його.",al={"мета фіцсіммонса","навіщо відкривати скриню","мета завдання"}},{q="Де скриня «Безстрашного»?",a="Скриня лежить під водою в нижньому трюмі «Безстрашного»; дістатися до неї можна крізь пробоїну в борту розбитого корабля під хвилями.",al={"місце скрині","де скриня","як знайти скриню"}},{q="Хто може очистити прокляту річ, коли її знайдуть?",a="Фіцсіммонс радить шукачам пригод віднести знайдену річ дворфійському жерцеві Ґлоріну Стілброу в Гавань Менетіл, щоб той очистив її від мерзенної скверни.",al={"хто очистить реліквію","хто такий ґлорін стілброу","куди нести прокляте"}},{q="Що взагалі спричинило корабельну аварію?",a="Під час Другої війни на Третій флот напали червоні дракони під владою орків: кораблі згоріли й затонули біля узбережжя Багнокраю, а проклятий скарб на борту тепер не дає потоплим командам спокою.",al={"як затонув третій флот","причина уламків третього флоту"}}},fp="17,312,18.449.0,20.413.1,46.118.0,24.184.0,58.212.0,42.146.0,55.151.0,45.210.0"}
P.entries["quest:2904"] = {n="Ну й халепа",s="Глибоко в опромінених руїнах Гномреґана серед трогів лежить побитий гоблін на ім'я Кернобі, на якого напали дворфи Темного Заліза. Порятунок гобліна відкриває тривожні відомості про причетність Темного Заліза до підземних бурових машин, і цю звістку треба донести аж до Буті Бей.",h="Глибоко в опромінених руїнах Гномреґана серед трогів лежить побитий гоблін на ім'я Кернобі, на якого напали...",kw={"ну й халепа","кернобі","гномреґан","темне залізо","буті бей","скуті","завдання"},ang={["faction:Alliance"]="Викриття змови Темного Заліза в межах Дун Мороґу підтверджує, що агенти імператора Тауріссана свідомо зривають зусилля Альянсу з відновлення Гномреґана.",["profession:Engineering"]="Відкриття, що механіки Темного Заліза будують величезну супербурову установку, одразу насторожить кожного інженера, що стежить за передовою підземною технікою.",["race:Gnome"]="Врятувати брата, що застряг у заражених глибинах Гномреґана, — справа честі, особливо коли проти вас об'єдналися злоба лазутчиків Темного Заліза й дикі троги."},sec={{t="Побитий, але живий",b="Пробираючись небезпечними внутрішніми залами Гномреґана, шукачі пригод знаходять Кернобі, покинутого в житловій частині. Жорстоко побитий і ледь притомний, гоблін вцілів у полоні дворфів Темного Заліза, які залишили його помирати серед диких трогів. Дружнє обличчя — його єдиний шанс пережити дорогу назад зараженими коридорами."},{t="Підземні задуми",b="Кернобі знає вкрай важливі відомості про темні сили, що діють під Дун Мороґом. Він розповідає, що клан Темного Заліза доклав руку до будівництва величезної супербурової установки. Поки Кернобі тікає за море до Раджета, щоб попередити гобліна-інженера Тінкервіза про загрозу, що назріває, свого рятівника він посилає на південь, до Буті Бей, передати звістку гоблінові-інженерові Скуті."}},faq={{q="Хто такий Кернобі?",a="Кернобі — гоблін, що пробрався глибоко в руїни Гномреґана. Дворфи Темного Заліза влаштували на нього засідку, побили до напівсмерті й кинули трогам, поки його не врятували.",al={"кернобі","хто такий кернобі"}},{q="Куди треба супроводити Кернобі?",a="Кернобі треба безпечно провести ворожими залами назад до безпечного виходу через Годинниковий Хід і верхніх вхідних коридорів полеглого міста.",al={"куди вести кернобі","місце супроводу","вихід із заводного забігу"}},{q="До чого тут дворфи Темного Заліза?",a="Дворфи Темного Заліза плетуть під землею змову: допомагають проєктувати й будувати величезну надпотужну бурову установку. Кернобі розкрив цей задум, перш ніж дворфи влаштували йому засідку.",al={"чому темне залізо","супермашина темного заліза","темне залізо в гномереґані"}},{q="Куди йде Кернобі після втечі?",a="Діставшись безпечного місця, Кернобі вирушає за море до Раджета в Пустках, щоб попередити майстра Тінкервіза про участь Темного Заліза в будівництві підземної бурової установки.",al={"куди пішов кернобі","кернобі ретчет","застереження мудрійця"}},{q="Чому треба доповісти Скуті в Буті Бей?",a="Скуті — гоблін-інженер з Буті Бей, що співпрацює з Тінкервізом і координує роботу з високотехнологічним підземним обладнанням і мережами транспондерів.",al={"чому скуті","здати в буті бей","зв'язок зі скуті"}},{q="Як це пов'язано з Мехінженером Термаплаґом?",a="Скуті розуміє, яку загрозу й далі становить Мехінженер Термаплаґ у Гномреґані. Допомога Кернобі дає підтримку й припаси шукачам пригод, які збираються повернутися й зійтися з віроломним Мехінженером.",al={"зв'язок з термаплаґом","бій з термаплаґом"}}},fp="11,308,19.359.0,20.385.1,16.180.0,32.155.0,40.186.0,38.175.1,43.178.0,46.204.0"}
P.entries["quest:291"] = {n="Звіти",s="Віднесіть звіт Сеніра Вайтбірдого про тролів-Морозогривів з Хараноса сенаторові Барінові Редстоуну в Айронфордж. Сенір попереджає, що сенатор має кислий норов, і просить не згадувати, хто допомагав збирати відомості.",h="Віднесіть звіт Сеніра Вайтбірдого про тролів-Морозогривів з Хараноса сенаторові Барінові Редстоуну в...",kw={"сенір вайтбірдий","барін редстоун","сенат","морозогриви","харанос","айронфордж","маґні"},ang={["faction:Alliance"]="Це доручення — перше знайомство з устроєм Айронфорджа й політичною бюрократією, яка визначає внутрішню політику Альянсу в Дун Мороґу.",["race:Dwarf"]="Для дворфів прийти з депешею до Високого Престолу — нагода на власні очі побачити тонку рівновагу між короною Маґні й парламентською владою дворфійського Сенату."},sec={{t="Депеша до столиці",b="Після сміливої розвідки в самому серці Твердині Морозогривів Сенір Вайтбірдий складає термінове донесення про дедалі більшу загрозу, яку тролі становлять для Дун Мороґа. Горянинові, що стоїть у Хараносі, потрібен гонець, який доставить ці відомості просто Сенаторові Барінові Редстоуну в Айронфордж. Дбаючи про власну репутацію в очах уряду, Вайтбірдий весело радить посланцеві не згадувати, хто насправді робив небезпечну чорну роботу серед засніжених скель."},{t="Тертя на Високому Престолі",b="Отримавши документ у королівських палатах, сенатор Редстоун одразу спалахує гнівом. Замість подякувати за відомості про пересування ворожих тролів, кислий сенатор обурюється, що Вайтбірдий прикрився особистою владою короля Маґні, щоб узаконити свої дії. Доставлений звіт відкриває давню боротьбу за владу в урядових залах Айронфорджа: Сенат глибоко обурений королівськими указами й самочинними польовими починаннями від імені короля."}},faq={{q="Хто такий Сенір Вайтбірд?",a="Сенір Вайтбірд — дворф-горянин, що стоїть біля Хараноса в Дун Мороґу. Він керує розвідкою й військовим спостереженням за племенами тролів-Морозогривів, що підступають до дворфійських поселень.",al={"сенір вайтбірд","хто дає звіти","вайтбірд хараніс"}},{q="Хто такий Сенатор Барін Редстоун?",a="Барін Редстоун — похмурий дворф-аристократ, сенатор, що перебуває в тронній залі Айронфорджа поруч із королем Маґні Бронзбірдом. Він ревно оберігає законодавчу владу й легко дратується через простих прохачів.",al={"барін редстоун","хто той сенатор","редстоун айронфордж"}},{q="Чому Сенатор Редстоун сердиться через звіт?",a="Сенір попереджає, що в Редстоуна кисла вдача. Як сенатор відреагує на звіт, ви побачите, коли його доставите.",al={"чому редстоун сердиться","чому сенатор кричить","сенат проти маґні"}},{q="Чому Сенір Вайтбірд просить приховати вашу допомогу?",a="Вайтбірд хоче, щоб начальство в Айронфорджі вірило, ніби він сам керував виснажливою польовою розвідкою й завершив її, — це зміцнить його становище, тож він не хоче визнавати, що справу виконав мандрівний шукач пригод.",al={"чому сенір бере заслуги","вайтбірд украв заслуги","таємниця сеніра"}},{q="Куди доставляють звіт?",a="Звіт доставляють Сенаторові Баріну Редстоуну до Високого Престолу Айронфорджа — великої зали, де король Маґні Бронзбірд вершить суд.",al={"куди здати звіти","місце баріна редстоуна","здати звіти"}},{q="Що це завдання розкриває про політику Айронфорджа?",a="Доставка знайомить із Сенатом Айронфорджа й урядовцями, які приймають звіти з прикордоння. Реакція Редстоуна дає змогу ближче зазирнути в цю політику.",al={"лор уряду айронфорджа","лор сенату дворфів","маґні проти сенату"}}},fp="11,209,25.484.0,25.493.1,24.200.0,30.215.0,47.121.1,55.213.0,30.144.0,53.151.1"}
P.entries["quest:292"] = {n="Око Палета",s="У цьому завданні шукач пригод дістає із затоплених уламків «Безстрашного» почорнілий пульсуючий самоцвіт — Прокляте Око Палета. Здобутий на прохання переслідуваного привидами моряка Фіцсіммонса, цей зловісний артефакт треба принести до Гавані Менетіл, щоб дворф-жрець Ґлорін Стілброу з'ясував, як очистити його від скверни.",h="У цьому завданні шукач пригод дістає із затоплених уламків «Безстрашного» почорнілий пульсуючий самоцвіт —...",kw={"око палета","прокляте око палета","ґлорін стілброу","безстрашний","затока барадін","третій флот"},ang={["class:Priest"]="Ідеться про осквернення священного артефакту, як-от Ока Палета, тож це розслідування прямо стосується жерців Святого Світла.",["faction:Alliance"]="Третій флот — експедиція Альянсу, загибель якої лишила Гавань Менетіл вразливою; повернення його решток допомагає попрощатися із загиблими товаришами.",["race:Dwarf"]="Пошук утрачених артефактів біля берегів Каз Модану перегукується з дворфійською відданістю поверненню прихованих реліквій — за допомоги духовенства Айронфорджа на кшталт Ґлоріна Стілброу."},sec={{t="Сплюндрована реліквія",b="Під підступними водами Затоки Барадін, у замкненій скрині затонулого корабля «Безстрашний», лежить зовсім не звичайний скарб. Скриня ховає почорнілу кулю, що пульсує тривожним сяйвом, — Око Палета. Замість випромінювати святе світло, цей камінь обернувся на знаряддя страждань, тісно пов'язане з неспокійними духами й загибеллю, що спіткала моряків Третього флоту."},{t="До жерців",b="Розуміючи, що така темна магія — не звичайна знахідка з уламків, артефакт одразу несуть на берег, до Гавані Менетіл. Там його оглядає Ґлорін Стілброу, дворф-жрець Святого Світла. Приголомшений тим, що така священна річ узагалі опинилася в Третього флоту, Ґлорін одразу впізнає її неприродну скверну й починає готувати обряди, потрібні, щоб зняти її темний вплив."}},faq={{q="Що таке Око Палета?",a="Око Палета — давній і могутній священний самоцвіт. Зазвичай такі пов'язують зі святою енергією, але цей був на борту затонулого корабля Третього флоту «Безстрашний», спотворився й став проклятим, випромінюючи темну магію.",al={"лор ока палета","хто такий палет","прокляте око палета"}},{q="Де знайшли Око?",a="Його дістали із замкненої скрині на затопленому уламку «Безстрашного», що лежить біля оповитого туманом узбережжя Багнокраю.",al={"де знайти око","місце ока палета","скриня безстрашного"}},{q="Чому Ґлоріна Стілброу цікавить артефакт?",a="Ґлорін Стілброу — дворфійський жрець з Гавані Менетіл. Як служитель Святого Світла, він має священні знання, щоб розпізнати давні реліквії й почати обряди, потрібні, щоб зламати зловісні прокляття.",al={"хто такий ґлорін стілброу","чому стілброу"}},{q="Звідки Фіцсіммонс знає про Око?",a="Фіцсіммонс — уцілілий з Третього флоту, якого досі переслідує ця трагедія. Травмований, він ховається в корчмі Менетілу й знав про темну реліквію, сховану серед уламків, що мучила його загиблих товаришів.",al={"зв'язок фіцсіммонса","чому фіцсіммонс послав мене"}},{q="Чому Око прокляте?",a="Достеменно не відомо, як саме воно зіпсувалося, але це пов'язано з надприродною загибеллю кораблів Третього флоту й неспокійною нежиттю, що їх населяє: артефакт увібрав темну енергію під час чи після катастрофи, що відправила флот на дно.",al={"чому око прокляте","походження прокляття ока"}},{q="Що буде, коли віддати Око Ґлорінові?",a="Ґлорін оглядає проклятий самоцвіт і вирішує, що його не можна лишати в такому зіпсованому стані, тож спрямовує шукача пригод очистити реліквію від згубного впливу.",al={"наступне завдання","що робити з оком"}}},fp="17,334,16.425.0,22.405.1,26.228.0,28.139.0,50.232.0,40.218.0,22.241.0,44.166.1"}
P.entries["quest:2922"] = {n="Врятуй мозок Техбота!",s="Тінкмайстер Оверспарк доручає шукачам пригод з Альянсу добути ядро пам'яті Техбота з опромінених руїн Гномреґана. Колись корисний механічний помічник зазнав тяжкої поляризації мозку під час падіння міста й почав шаленіти. Оверспарк сподівається, що, повернувши ядро, зможе виправити пошкодження й відновити своє улюблене творіння.",h="Тінкмайстер Оверспарк доручає шукачам пригод з Альянсу добути ядро пам'яті Техбота з опромінених руїн...",kw={"врятуй мозок техбота","техбот","ядро пам'яті","тінкмайстер оверспарк","гномреґан","завдання"},ang={["faction:Alliance"]="Повернення цінної втраченої техніки із зараженого периметра Гномреґана вкрай важливе для підтримки гномів-біженців, що знайшли прихисток в Айронфорджі.",["profession:Engineering"]="Перехід процесора Техбота з позитронного стану в негатронний — повчальна історія для майстрів, що працюють зі складними обчислювальними матрицями.",["race:Gnome"]="Для гномських інженерів Техбот — трагічна побічна жертва втрати рідного міста, що доводить: навіть найкращі здобутки їхнього розуму може спотворити катастрофа."},sec={{t="Перевернутий розум",b="До лиха, що забрало Гномреґан, Техбот був дивом гномської винахідливості. Сконструйований Головним Архітектором Тінкмайстром Оверспарком, автоматон допомагав дослідникам незліченними вбудованими пристроями й енциклопедичним сховищем технічних знань. Проте хаос вторгнення трогів і викид отруйного випромінювання не пощадили машину. Випадковий стрибок напруги вдарив по тендітній внутрішній будові Техбота й цілком поляризував його позитронний мозок, перевівши в нестійкий негатронний стан."},{t="Рятувальна операція",b="Замкнений у заражених залах Гномреґана, Техбот тепер блукає в маніакальному шаленстві й нападає на кожного, хто трапиться. Попри його буйну несправність, Оверспарк не хоче списувати свого цінного помічника на брухт. Він наймає вправних агентів, щоб ті вистежили скаженого автоматона, вийняли ядро пам'яті з металевого корпусу й безпечно доставили його до Айронфорджа, де Тінкмайстер розплутає поляризацію й полагодить розум Техбота."}},faq={{q="Хто такий Техбот?",a="Техбот — механічний помічник, якого винайшов Тінкмайстер Оверспарк. До падіння Гномреґана він допомагав Тінкмайстрові та його колегам своєю величезною базою знань і вбудованими штуковинами.",al={"хто такий техбот","лор техбота","техбот оверспарк"}},{q="Чому Техбот став ворожим?",a="Під час падіння Гномреґана випадкова електрична іскра вразила позитронний мозок Техбота. Розряд перевернув його нейронну налаштованість на негатронну, і привітна вдача обернулася шаленим буйством.",al={"чому техбот злий","що сталося з техботом","поляризація техбота"}},{q="Де знайти Техбота?",a="Техбот блукає зовнішніми коридорами й збірними залами Гномреґана — одразу за межами рубежів, де діють гноми-вигнанці й дворфійські експедиційні загони.",al={"де техбот","місце техбота","знайти техбота"}},{q="Хто дає це завдання?",a="Завдання пропонує Тінкмайстер Оверспарк у Містечку Майстрів в Айронфорджі, де він від імені Верховного Механіка Ґелбіна Меккаторка керує порятунком техніки й дослідженнями.",al={"хто дає врятуй мозок техбота","місце оверспарка"}},{q="Чи можна справді полагодити Техбота?",a="Тінкмайстер Оверспарк вірить, що ядро пам'яті Техбота дасть йому змогу встановити точну причину негатронної поляризації й повернути автомат до робочого стану.",al={"чи техбота полагодили","чи можна полагодити техбота","чи техбот виживе"}},{q="Що буде, коли повернути ядро пам'яті?",a="Отримавши ядро, Оверспарк одразу береться готуватися розібрати й переналаштувати перевернуті схеми, хоча знайти потрібне знаряддя в його захаращеній майстерні — окрема морока.",al={"кінець завдання техбота","здати ядро техбота"}}},fp="21,359,15.517.0,17.438.0,15.206.0,31.212.0,27.166.0,21.164.0,30.180.0,45.210.1"}
P.entries["quest:2923"] = {n="Тінкмайстер Оверспарк",s="Це доручення скеровує шукачів пригод з Альянсу зі Стормвінда до Містечка Майстрів в Айронфорджі, де Тінкмайстер Оверспарк оплакує трагічну несправність. Брат Сарно передає звістку, що механічне творіння Оверспарка, Техбот, збунтувалося серед опромінених руїн Гномреґана. Дістатися до Тінкмайстра — перший крок до повернення ядра пам'яті заблукалого конструкта.",h="Це доручення скеровує шукачів пригод з Альянсу зі Стормвінда до Містечка Майстрів в Айронфорджі, де...",kw={"тінкмайстер оверспарк","брат сарно","техбот","містечко майстрів","глибинний трамвай","завдання"},ang={["faction:Alliance"]="Допомога гномам-біженцям у Містечку Майстрів зміцнює важливі зв'язки між Стормвіндом і королівствами дворфів та гномів.",["profession:Engineering"]="Творіння Оверспарка — передній край гномської винахідливості, тож будь-яка нагода оглянути його збунтованих конструктів дуже повчальна.",["race:Gnome"]="Кожне врятоване творіння й повернене ядро пам'яті — це частинка вашої полеглої батьківщини, збережена, доки радіація й троги не знищили її остаточно."},sec={{t="Прохання із Собору",b="Брат Сарно, що опікується мандрівниками в Стормвінді, розповідає про прикру халепу, що назріває серед гномів-біженців. Тінкмайстер Оверспарк — один із блискучих розумів, що стояли за дивами Гномреґана, — у розпачі через зіпсуття Техбота, колись корисного механічного слуги, що вірно служив майстрам, доки місто не обернулося на руїни."},{t="До Містечка Майстрів",b="Завдання відправляє небайдужих Глибинним трамваєм до Айронфорджа, у гамірне Містечко Майстрів. Там Оверспарк відчайдушно кличе шукачів пригод, достатньо відважних, щоб знову зануритися в опромінені зали Гномреґана й урятувати те, що лишилося від розуму Техбота, перш ніж конструкт накоїть непоправної шкоди."}},faq={{q="Хто такий Тінкмайстер Оверспарк?",a="Тінкмайстер Оверспарк — гном-інженер і наставник гномської інженерії. Нині він працює в Містечку Майстрів в Айронфорджі й невтомно координує зусилля з повернення та порятунку гномської техніки зі зруйнованої столиці.",al={"оверспарк","хто такий оверспарк","тінкмайстер оверспарк"}},{q="Хто дає це завдання?",a="Брат Сарно, священник з людей у Стормвінді, дає шукачам пригод це завдання, щоб спрямувати їх до гномів, які потребують допомоги в Айронфорджі.",al={"хто дає завдання","де взяти тінкмайстра оверспарка"}},{q="Хто такий Техбот?",a="Техбот — механічне створіння, сконструйоване Тінкмайстром Оверспарком. Колись корисне й привітне знаряддя гномських інженерів, після катастрофічного падіння Гномреґана воно зламалося й здичавіло в опроміненому місті.",al={"техбот","що сталося з техботом"}},{q="Де знайти Тінкмайстра Оверспарка?",a="Оверспарк — у Містечку Майстрів, гномському кварталі у східній частині Айронфорджа, серед інших майстрів-біженців і експериментальних машин.",al={"місце оверспарка","де оверспарк"}},{q="Що далі після розмови з Оверспарком?",a="Коли ви з'явитеся до Оверспарка, він запропонує завдання «Врятуй мозок Техбота!»: треба вирушити в Гномреґан, вимкнути Техбота й забрати його ядро пам'яті, щоб його можна було відновити.",al={"наступне завдання","врятуй мозок техбота"}},{q="Чому Альянс цікавить зламана машина винахідника?",a="Крім співчуття до гномів-вигнанців, автомати, що здичавіли й блукають Гномреґаном, безпосередньо загрожують кожній експедиції, яка намагається повернути підземну столицю чи захистити кордони Дун Мороґу.",al={"чому альянс цікавиться техботом","важливість техбота"}}},fp="20,370,25.357.0,14.316.0,28.246.0,22.144.0,16.228.0,40.166.0,41.185.0,63.209.0"}
P.entries["quest:2924"] = {n="Необхідні штучні деталі",s="«Необхідні штучні деталі» — завдання для Альянсу, яке дає Клокморт Спаннерспан у Містечку Майстрів в Айронфорджі. Шукачам пригод доручено спуститися в глибини опромінених руїн Гномреґана й повернути важливі універсальні деталі, покинуті під час відчайдушної евакуації гномів.",h="«Необхідні штучні деталі» — завдання для Альянсу, яке дає Клокморт Спаннерспан у Містечку Майстрів в...",kw={"необхідні штучні деталі","штучний мозок","клокморт спаннерспан","містечко майстрів","гномреґан","завдання"},ang={["faction:Alliance"]="Допомагаючи гномам-вигнанцям повернути втрачену техніку, ви зміцнюєте технологічний хребет Альянсу, що тримається в Айронфорджі.",["profession:Engineering"]="Кожен інженер знає, яка це мука, коли бракує однієї-єдиної універсальної деталі; повернення цих пристроїв показує, наскільки витонченим було ремесло Гномреґана до падіння.",["race:Gnome"]="Повернення цих деталей — справа національної гордості й безперервності технологій, яка гарантує, що вигнання в Айронфорджі не зупинить гномської винахідливості."},sec={{t="Забуті під час утечі",b="Коли вторгнення трогів поглинуло Гномреґан, а отруйне випромінювання затопило його коридори, гноми, тікаючи, могли забрати лише те, що мали під рукою. Серед незліченних див, що лишилися позаду, були запаси Штучних Мозків — особливих, майже універсальних механічних деталей, які дуже цінують майстри й ремісники. Тепер, працюючи в Містечку Майстрів в Айронфорджі, майстер Клокморт Спаннерспан бачить, як без них зупинилися його новаторські досліди."},{t="У надрах екстраполяторів",b="Ці важливі пристрої зберігаються у важких паросилових сховищах, відомих як штучні екстраполятори, глибоко в полеглому місті. Щоб їх урятувати, доведеться пройти опроміненими залами, де кишать змутовані прокажені гноми, несправні оборонні автоматони й дикі троги. Повернувши дванадцять деталей, шукачі пригод дадуть Клокмортові змогу продовжити свою важливу роботу, щоб гномська винахідливість рухалася вперед навіть у вигнанні."}},faq={{q="Що таке необхідні штучні деталі?",a="Необхідна штучна деталь — майже універсальний механічний вузол, розроблений гномськими інженерами. Її високо цінують майстри й ковалі, бо це основний будівельний елемент для хитромудрих пристроїв і складних експериментальних машин.",al={"що таке необхідні штучні деталі","необхідні штучні","що це"}},{q="Хто дає завдання «Необхідні штучні деталі»?",a="Завдання дає Клокморт Спаннерспан — гномський інженер з Містечка Майстрів в Айронфорджі.",al={"хто дає завдання","хто це починає","де взяти необхідні штучні деталі"}},{q="Де в Гномреґані шукати необхідні штучні деталі?",a="Вони зберігаються глибоко в Гномреґані у контейнерах, які називають штучними екстраполяторами: ті схожі на високі парові шафи чи комірки, розкидані по нижніх залах.",al={"де вони","місце екстраполятора","як знайти штучні деталі"}},{q="Чому їх залишили в Гномреґані?",a="Під час раптової навали трогів і радіоактивної катастрофи, що настала потім, гноми тікали зі столиці в паніці. У хаосі евакуації запаси цих важливих деталей лишилися в нижніх майстернях.",al={"чому залишили","чому вони в гномереґані","лор штучних деталей"}},{q="Навіщо вони Клокмортові?",a="Клокмортові Спаннерспану потрібен чималий запас цих універсальних деталей для низки нових складних експериментів, які він готує у своїй майстерні в Айронфорджі.",al={"навіщо клокморту","план клокморта"}},{q="Чи треба виконати «Необхідне для Клокморта», перш ніж узяти це завдання?",a="Завдання-доставка «Необхідне для Клокморта» знайомить вас із Клокмортом і спрямовує до його майстерні, але воно не обов'язкове, щоб узяти «Необхідні штучні деталі».",al={"передумова","чи потрібне необхідне для клокморта"}}},fp="21,289,23.464.0,25.423.0,32.236.0,42.104.0,56.182.0,40.234.0,34.187.0,60.187.0"}
P.entries["quest:2925"] = {n="Необхідне для Клокморта",s="«Необхідне для Клокморта» — виклик із нагальною звісткою від нічного ельфа Матіеля для його друга-гнома Клокморта Спаннерспана. Не маючи змоги покинути свої обов'язки й вирушити до Дун Мороґу, Матіель просить мандрівників з Альянсу відгукнутися на прохання Клокморта про допомогу в Айронфорджі. Цей заклик веде шукачів пригод до Містечка Майстрів, де вони готуються до небезпечної вилазки в опромінені зали Гномреґана.",h="«Необхідне для Клокморта» — виклик із нагальною звісткою від нічного ельфа Матіеля для його друга-гнома...",kw={"необхідне для клокморта","клокморт спаннерспан","матіель","дарнасус","містечко майстрів","завдання"},ang={["faction:Alliance"]="Це завдання поєднує далекі куточки земель Альянсу, пов'язуючи краї нічних ельфів із гірськими залами Айронфорджа заради спільного захисту.",["race:Gnome"]="Для гномів кожне доручення, що веде шукачів пригод до Містечка Майстрів, допомагає у відчайдушній боротьбі за повернення втраченого дому — Гномреґана."},sec={{t="Заклик через континенти",b="Звістки линуть далеко навіть у неспокійні часи. Коли Клокмортові Спаннерспану знадобилися відважні союзники для вилазки в Гномреґан, він звернувся через море до свого знайомого, нічного ельфа Матіеля. Матіель, прив'язаний до власного посту, не може сам вирушити до гірського королівства, але й не хоче лишити прохання друга без відповіді. Тож він просить вправних шукачів пригод з Альянсу, що заходять до нього на Терасі Воїна в Дарнасусі, вирушити до Дун Мороґу замість нього."},{t="Дорога до Містечка Майстрів",b="Клокморт Спаннерспан працює в Містечку Майстрів — гамірному кварталі біженців в Айронфорджі, де збираються гноми, що втратили дім після катастрофічного падіння свого підземного міста. Серед дзижчання шестерень і хмар пари Клокморт виношує плани повернути важливі машини, що лишилися в заражених коридорах Гномреґана. Рекомендація Матіеля веде шукачів пригод просто до майстерні Клокморта, і ті долучаються до його зусиль із повернення втраченого."}},faq={{q="Хто дає завдання «Необхідне для Клокморта»?",a="Завдання пропонує Матіель — нічний ельф, що отримав звістку від свого друга-гнома Клокморта Спаннерспана. Матіель не може сам поїхати до Айронфорджа, тож просить довірених шукачів пригод з Альянсу вирушити замість нього.",al={"хто дає завдання","хто починає необхідне для клокморта","завдання матіеля"}},{q="Де знайти Клокморта Спаннерспана?",a="Клокморт Спаннерспан — у Містечку Майстрів, гномському кварталі Айронфорджа, серед майстерень і пристроїв, які встановили гноми, вигнані з утраченого дому.",al={"де клокморт","місце клокморта","клокморт спаннерспан айронфордж"}},{q="Чому Клокмортові потрібна допомога в Гномреґані?",a="Гномреґан захопили й отруїли токсичними опадами, і тепер там кишать троги, збожеволілі гноми-прокажені й автомати, що з'їхали з глузду. Клокмортові потрібні відважні шукачі пригод, які наважаться на ці небезпеки й дістануть з руїн найпотрібніші механічні деталі.",al={"чого хоче клокморт","чому місія в гномереґані","мета клокморта"}},{q="Чи обов'язкове це завдання, щоб увійти до Гномреґана?",a="Ні, це необов'язкове завдання-підказка, що веде вас від Матіеля просто до Клокморта Спаннерспана. Можна поговорити з Клокмортом в Айронфорджі й узяти його доручення в підземеллі одразу, без Матіелевої рекомендації.",al={"чи це завдання обов'язкове","передумова гномереґана","чи можна пропустити необхідне для клокморта"}},{q="Яке завдання йде після «Необхідного для Клокморта»?",a="Розмова з Клокмортом Спаннерспаном завершує це доручення й одразу веде до завдання «Необхідні штучні деталі», що спрямовує шукачів пригод глибоко в підземелля Гномреґана.",al={"наступне завдання","продовження","необхідні штучні деталі далі"}},{q="Чому Матіель хоче допомогти гномові в Айронфорджі?",a="Матіель і Клокморт — давні особисті друзі. Хоча Матіель далеко й не може покинути свого посту, турбота про друга спонукає його знайти надійну людину, яка простягне руку допомоги.",al={"зв'язок матіеля","чому матіель турбується","матіель і клокморт"}}},fp="22,394,24.488.0,22.460.0,43.215.0,38.184.0,43.262.0,43.221.0,42.180.0,58.217.0"}
P.entries["quest:2926"] = {n="Гноґаїн",s="«Гноґаїн» — завдання для Альянсу, яке дає Оззі Тоґлвольт у Хараносі. В ексцентричній спробі створити ліки для прокажених гномів — чи, може, зварити надзвичайно міцний напій — Оззі доручає шукачам пригод вирушити до Гномреґана й зібрати радіоактивні опади зі світних трогів.",h="«Гноґаїн» — завдання для Альянсу, яке дає Оззі Тоґлвольт у Хараносі.",kw={"гноґаїн","оззі тоґлвольт","раззл спрайспрокет","харанос","радіоактивні опади","гномреґан","завдання"},ang={["faction:Alliance"]="Зараза, що витікає з Гномреґана, загрожує всьому Дун Мороґу, тож будь-яка спроба зрозуміти чи знешкодити опади вкрай важлива для безпеки краю.",["profession:Engineering"]="Робота із сирими радіоактивними стоками за допомогою захищених свинцевих колб — наочний приклад звичної для гномів ризикованої польової науки.",["race:Gnome"]="Для гномів-вигнанців відчайдушне бажання знайти хоч якісь ліки для опромінених братів робить вартими спроби навіть ледь не божевільні досліди Оззі."},sec={{t="Ліки чи коктейль",b="Відтоді як упав Гномреґан, біженці на кшталт Ґноарна цілком зосередилися на тому, щоб винищити трогів-загарбників і обернути назад радіоактивну недугу, що змутувала їхніх братів. Натомість Оззі Тоґлвольт і його компаньйон Раззл Спрайспрокет у своїй майстерні в Хараносі обирають дещо менш звичний підхід. Нібито шукаючи ліки для прокажених гномів, Оззі відверто визнає, що їхня експериментальна формула з таким самим успіхом може стати рецептом напрочуд міцного рому."},{t="Збирання сяйва",b="Щоб удосконалити свою суміш, винахідникам потрібні сирі отруйні рештки просто з епіцентру катастрофи. Давши шукачам пригод свинцеву колекційну колбу, Оззі посилає їх до проламаних тунелів Гномреґана. Там мандрівні опромінені загарбники й грабіжники — троги, просякнуті витоками відходів, — світяться тим нудотно-зеленим сяйвом, яким треба наповнити колбу."},{t="Волосся й великі надії",b="Здобувши повну колбу зеленого сяйва, Оззі не гає часу й готує живе випробування. Окрім надії повернути розум і здоров'я полоненому прокаженому гномові, майстер має щодо варива особисті сподівання: він вірить, що суміш опадів може дивом вилікувати і його лисину."}},faq={{q="Хто дає завдання «Гноґаїн»?",a="Завдання дає Оззі Тоґлвольт — гном-майстер, що працює в Хараносі в Дун Мороґу.",al={"хто дає гноґаїн","дає завдання гноґаїн","завдання оззі тоґлвольта"}},{q="Що треба зібрати для цього завдання?",a="Треба застосувати Порожню Свинцеву Колекційну Колбу на трогах, що світяться від опромінення, — опромінених загарбниках чи опромінених грабіжниках — у зовнішніх коридорах, що ведуть до Гномреґана, поки колба не наповниться радіоактивними опадами.",al={"що збирати для гноґаїну","мета гноґаїну","повний свинцевий флакон"}},{q="Де шукати опромінених трогів?",a="Вони в зовнішніх вхідних печерах і звивистих залах, що ведуть до порталу підземелля Гномреґан, тож завдання можна виконати, не ступаючи в саме підземелля.",al={"де опромінені троги","місце опромінених трогів","загарбник опромінений"}},{q="Чи треба виконати «Наступний день», перш ніж узяти це завдання?",a="Ні. «Наступний день» сюжетно пов'язаний зі становищем у Хараносі й підводить до нього, але Оззі запропонує «Гноґаїн» і без нього.",al={"чи наступний день обов'язковий","передумова гноґаїну"}},{q="Чого Оззі хоче досягти радіоактивними опадами?",a="Оззі запевняє, що вони з Раззлом намагаються створити ліки для гномів-прокажених, хоча й визнає, що замість них може вийти міцний ром. Ще він потай сподівається, що вариво поверне йому волосся.",al={"чого хоче оззі","навіщо гноґаїн"}},{q="Яке завдання йде після «Гноґаїну»?",a="Коли ви віддасте повну колбу, одразу відкриється завдання «Єдині ліки — більше зеленого сяйва», для якого доведеться вирушити глибше в сам Гномреґан.",al={"продовження гноґаїну","що після гноґаїну"}}},fp="8,302,20.494.0,19.382.0,19.285.1,30.97.0,41.242.0,39.193.0,63.137.0,64.212.0,28.135.0"}
P.entries["quest:2927"] = {n="Наступний день",s="«Наступний день» — завдання для Альянсу, що пов'язує вцілілих в Айронфорджі з дослідниками в Дун Мороґу. Ґноарн, оплакуючи катастрофічний витік радіації, що коштував йому легендарної чуприни й батьківщини, посилає шукачів пригод допомогти Оззі Тоґлвольту в Хараносі шукати розв'язання.",h="«Наступний день» — завдання для Альянсу, що пов'язує вцілілих в Айронфорджі з дослідниками в Дун Мороґу.",kw={"наступний день","ґноарн","оззі тоґлвольт","харанос","радіація","гномреґан","завдання"},ang={["faction:Alliance"]="Герої Альянсу допомагають гномським мислителям Дун Мороґу стримати химерну біохімічну катастрофу, що загрожує гірському краю.",["profession:Engineering"]="Зусилля Оззі Тоґлвольта показують, як гномські майстри методом спроб і помилок приборкують техногенні катастрофи, що вийшли з-під контролю.",["race:Gnome"]="Для гномів дивний плач Ґноарна передає суміш глибокої трагедії, ексцентричної гордості й гіркої помсти, яку відчуває кожен біженець, вигнаний зі своєї дивовижної столиці."},sec={{t="Трагічна втрата",b="Падіння Гномреґана глибоко зачепило кожного вцілілого, і Ґноарн — не виняток. Біженець у Містечку Майстрів в Айронфорджі, Ґноарн оплакує не лише механічну країну чудес, яку відібрали троги-загарбники, а й своє безцінне гномоафро — пишну чуприну, втрачену вмить, коли в нього вдарив струмінь отруйних опадів. Ведений незгасною люттю на трогів і відчайдушною надією повернути місто, він скеровує співчутливих мандрівників до колег, які, можливо, ще мають досить наукового хисту, щоб урятувати те, що лишилося."},{t="Дорога до Хараноса",b="Замість піддатися відчаю, Ґноарн посилає поборників Альянсу до Хараноса, де винахідливі уми вже взялися за проблему опадів. Найголовніший серед них — Оззі Тоґлвольт, що працює разом зі своїм компаньйоном Раззлом Спрайспрокетом. Оззі яскраво пам'ятає жахливу мить катастрофи: як волосся Ґноарна випадало жмутками, а його охоплювали божевілля й жага помсти. Тепер, у відносній безпеці засніженого містечка, Оззі спрямовує свій інженерний геній на вивчення зараження, сподіваючись знайти протиотруту."}},faq={{q="Хто такий Ґноарн?",a="Ґноарн — гном-біженець з Містечка Майстрів в Айронфорджі. Тяжко озлоблений навалою трогів і радіоактивною катастрофою міста, він особливо переживає раптову втрату свого колись гордого гномського афро.",al={"ґноарн","лисий гном","хто дає наступний день"}},{q="Чому Ґноарн посилає до Оззі Тоґлвольта?",a="Ґноарн вірить, що Гномреґан ще можна врятувати. Оззі Тоґлвольт і його напарник Раззл працюють у Хараносі: досліджують токсичну радіацію, що огорнула місто, і намагаються сконструювати ліки.",al={"чому до оззі тоґлвольта","завдання оззі тоґлвольта","інженер хараноса"}},{q="Що сталося з Гномреґаном, що до цього дійшло?",a="Під час великої підземної навали диких трогів Верховного Механіка Ґелбіна Меккаторка вмовили випустити радіоактивні токсичні відходи в нижні зали, щоб знищити їх. Задум обернувся трагедією: незліченні гноми загинули чи мутували, техномісто стало непридатним для життя, а трогів так і не винищили.",al={"що сталося з гномереґаном","чому гномереґан опромінений","вторгнення трогів"}},{q="Куди веде цей ланцюжок завдань, коли дістанешся Оззі?",a="Доповідь Оззі відкриває завдання «Гноґаїн», де Оззі просить зібрати радіоактивні опади просто з опромінених трогів біля Гномреґана, щоб випробувати експериментальні знешкоджувальні суміші.",al={"продовження наступного дня","що після наступного дня","наступне завдання"}}},fp="13,305,13.521.0,20.545.0,14.221.0,45.229.0,42.313.0,54.198.0"}
P.entries["quest:2928"] = {n="Гіробуроматичні екскаваторатори",s="У глибині Дворфійського Кварталу Стормвінда Шоні Тиха готує флот величезних прохідницьких машин, які мають вирушити до Дун Мороґу. Через брак механічних деталей справа застопорилася, тож вона посилає шукачів пригод в опромінені руїни Гномреґана, щоб добути справні шестерні й нутрощі зі збунтованих автоматонів.",h="У глибині Дворфійського Кварталу Стормвінда Шоні Тиха готує флот величезних прохідницьких машин, які мають...",kw={"гіробуроматичні екскаваторатори","шоні тиха","дворфійський квартал","робомеханічні нутрощі","гномреґан","завдання"},ang={["faction:Alliance"]="Підтримка гномських розкопок зі Стормвінда зміцнює зв'язки між людьми-господарями та вигнанцями, що борються за повернення своєї спадщини.",["profession:Engineering"]="Видобування високоточних годинникових нутрощів зі слуг полеглого Гномреґана — практичний урок передової гномської конструкції й ремонту важких машин.",["race:Gnome"]="Кожна врятована деталь наближає підземний флот Шоні до робочого стану, підтримуючи в Стормвінді мрію про повернення дому й відродження промисловості."},sec={{t="Флоту бракує нутрощів",b="У Дворфійському Кварталі Стормвінда гномські інженери невтомно працюють, щоб підтримати своїх родичів, які втратили дім. Серед них — Шоні Тиха, що керує амбітним підземним проєктом: флотом гіробуроматичних екскаватораторів для Дун Мороґу. Проєкт застряг на вирішальному етапі, бо їй бракує деталей, щоб запустити величезні копальні машини."},{t="Пошуки в полеглому місті",b="Замість кувати нові деталі з нуля, Шоні звертається просто до джерела гномських високих технологій — утраченого міста Гномреґан. Руїни й довколишні тунелі кишать несправними оборонними роботами, механічними вартовими й годинниковими робітниками, що безконтрольно блукають. Мандрівників посилають розбирати ці збунтовані машини й принести до людських земель два десятки в'язок робомеханічних нутрощів."},{t="Велетенська справа",b="Двох десятків механічних нутрощів вистачає, щоб залатати рівно один екскаваторатор. А у флоті Шоні лишається ще майже чотириста машин, тож її мрія про масові підземні перевезення — велетенська, болісно повільна справа. І все ж кожна справна машина — маленький крок до того, щоб повернути втрачене під час катастрофи Гномреґана."}},faq={{q="Що таке гіробуроматичний екскаваторатор?",a="Це важкі гномські прохідницькі установки, або машини-кроти, створені для підземних розкопок і перевезень. Шоні Тиха намагається зібрати їх цілий флот, щоб перевозити людей чи припаси до Дун Мороґу.",al={"що таке екскаваторатор","гіробуроматичні екскаваторатори","гномський бур"}},{q="Хто така Шоні Тиха?",a="Шоні — гномська інженерка з Дворфійського Кварталу Стормвінда. Попри своє прізвисько, вона гучна й вимоглива наглядачка, що завзято лагодить сотні механічних копачів.",al={"шоні тиха","шоні","хто така шоні"}},{q="Чому Шоні потрібні деталі саме з Гномреґана?",a="Гномреґан заполонили сотні збожеволілих автоматів, механічних слуг і захисних мехів. Звичні шляхи постачання обірвалися з падінням міста, тож ці роботи-розбійники — найбагатше доступне джерело сумісних гномських запчастин.",al={"чому деталі з гномереґана","чому нутрощі роботів","порятунок з гномереґана"}},{q="Де шукати Робомеханічні нутрощі?",a="Придатні нутрощі можна зібрати з механічних вартових, заводних конструктів та інших ворогів, що блукають коридорами Гномреґана — і в самому зруйнованому комплексі, і на підступах до його верхніх тунелів.",al={"де робомеханічні нутрощі","де взяти нутрощі","механічні нутрощі гномереґан"}},{q="Чи завершує ремонт однієї машини флот Шоні?",a="Ні. Двох десятків механічних нутрощів вистачає лише на ремонт одного бура. Отримавши їх, Шоні зауважує, що їй лишилося ще 398 екскаватораторів.",al={"скільки екскаваторів","розмір флоту шоні","скільки бурів"}},{q="Навіщо готують флот екскаваторів для Дун Мороґу?",a="Дун Мороґ — споконвічна батьківщина гномів і місце, де стоїть їхня полегла столиця. Важкі прохідницькі установки дають змогу рити, розчищати завали й підтримувати роботу у засніжених гірських краях.",al={"флот до дун мороґу","чому дун мороґ","призначення екскаваторів"}}},fp="30,316,23.370.0,26.395.0,24.379.0,40.216.0,25.189.0,55.262.0,41.218.0,45.156.0,57.211.0"}
P.entries["quest:293"] = {n="Очищення Ока",s="«Очищення Ока» — завдання Альянсу, що посилає шукачів пригод із каламутного Багнокраю на південь, до людської столиці — Стормвінда. Здобувши проклятий камінь провидіння, відомий як Око Палета, мандрівники мають звернутися по допомогу до Архієпископа Бенедиктуса, щоб очистити його від скверни.",h="«Очищення Ока» — завдання Альянсу, що посилає шукачів пригод із каламутного Багнокраю на південь, до людської...",kw={"очищення ока","око палета","архієпископ бенедиктус","ґлорін стілброу","стормвінд","собор світла"},ang={["class:Paladin"]="Паладини вважають повернення святих реліквій із темних боліт урочистим обов'язком, а скверну Ока — образою, яку треба змити в освячених залах Стормвінда.",["class:Priest"]="Для жерців Святого Світла Прокляте Око Палета показує, якими трагічно податливими стають священні вироби під дією розпачу, — і як важливо, що втрутився Архієпископ Бенедиктус, щоб їх очистити.",["faction:Alliance"]="Це завдання показує співпрацю дворфійських застав Багнокраю з духовним проводом Стормвінда, що скріплює королівства спільною вірою."},sec={{t="Сплюндрована реліквія",b="Око Палета, здобуте на болотах, не сяє святою ясністю. Натомість воно просякнуте тривожною тінню й несе залишки скорботи й болю страшної трагедії, що сталася там, де його втратили. Дворф Ґлорін Стілброу визнає силу кулі, але зізнається, що йому бракує божественного вміння, щоб зняти таке тяжке прокляття."},{t="Шлях до Собору",b="Оскільки Очі Палета колись створили жерці-люди Святого Світла, лише найвищі з їхнього ордену знають, як скасувати осквернення. Ґлорін скеровує шукачів пригод до королівства Стормвінд, щоб передати почорнілу кулю Архієпископові Бенедиктусу, провідникові Церкви Святого Світла. Бенедиктус розуміє страшну небезпеку неочищеної реліквії й сам береться повернути їй священне сяйво."}},faq={{q="Що таке Око Палета?",a="Очі Палета — священні сфери, які створили жерці-люди, щоб ті сяяли святим світлом і слугували знаряддям для споглядання чи ясновидіння. Неосквернені, вони сповнені сили Святого Світла, але зіпсовані — їхня енергія стає нестійкою й небезпечною.",al={"лор ока палета","що за сфера","що таке око палета"}},{q="Чому Ґлорін Стілброу не може сам очистити Око?",a="Ґлорін Стілброу — дворф з Багнокраю, якому бракує особливого літургійного вміння, щоб вигнати таку темну недугу. Реліквію створили жерці Святого Світла з людей, тож зняти з неї скверну може лише очільник саме цієї традиції.",al={"чому до стормвінда","очищення ґлоріна","чому бенедиктус"}},{q="Хто такий Архієпископ Бенедиктус?",a="Архієпископ Бенедиктус — шанований очільник Церкви Святого Світла, що перебуває у величному Соборі Світла в Стормвінді. Він став наступником архієпископа Алонсуса Фаола й є опорою духовного проводу для Альянсу.",al={"хто такий бенедиктус","архієпископ бенедиктус","архієпископ стормвінда"}},{q="Чому Око називають заплямованим чи скорботним?",a="За словами Архієпископа Бенедиктуса, сфера стала свідком величезної трагедії в Багнокраї й з часом увібрала той біль. Ця незгасна скорбота обернулася згубним прокляттям, що спотворило природну силу реліквії.",al={"чому око прокляте","трагедія ока палета","прокляте око палета"}},{q="Що буде, коли Бенедиктус отримає сферу?",a="Бенедиктус погоджується провести обряд очищення. Він попереджає, що Очі Палета мають сяяти яскраво, а лишати такий артефакт зіпсованим — тяжка духовна й тілесна небезпека для всіх довкола.",al={"чи бенедиктус очистить","результат ока палета"}},{q="Де розташований Собор Світла?",a="Собор Світла панує над Соборною Площею в північній частині Стормвінда. Архієпископ Бенедиктус стоїть біля головного вівтаря в самому серці святилища.",al={"де собор світла","місце собору світла","знайти бенедиктуса"}}},fp="17,279,15.355.0,24.445.0,26.254.0,51.271.0,29.237.0,48.232.0,46.214.0,40.171.0"}
P.entries["quest:2930"] = {n="Порятунок даних",s="Коли гноми покидали свою опромінену столицю, у ній лишилися величезні архіви важливих технічних знань і записів. Майстер-механік Кастпайп в Айронфорджі наймає відважних агентів, щоб ті проникли в Гномреґан і добули Призматичну Перфокарту з високим рівнем допуску. Долаючи рівень за рівнем комп'ютерного допуску, гінцям доведеться пробивати собі шлях — і перфокарти — крізь дедалі краще захищені термінали в глибинах зруйнованого міста.",h="Коли гноми покидали свою опромінену столицю, у ній лишилися величезні архіви важливих технічних знань і...",kw={"порятунок даних","кастпайп","призматична перфокарта","перфограф","гномреґан","завдання"},ang={["faction:Alliance"]="Підтримка пошуків Кастпайпа допомагає гномському урядові у вигнанні в Айронфорджі, зміцнюючи єдність і технологічні можливості Великого Альянсу.",["profession:Engineering"]="Мережа «Матричний Перфограф» — автоматичне зберігання даних у найкращому вигляді, з хитромудрими алгоритмічними механізмами допуску, розробленими Двором Майстрів.",["race:Gnome"]="Добути дані з Гномреґана — означає повернути викрадену спадщину. Кожна врятована перфокарта гарантує, що винахідливість вашого полеглого міста збережеться, а не загине під трогами й радіацією."},sec={{t="Втрачені архіви підземелля",b="Раптове падіння Гномреґана під натиском трогів і смертоносної радіації змусило гномів покинути століття передових досліджень, креслень і міських журналів. По технологічних коридорах розкидані термінали «Матричний Перфограф» — автоматичні вузли даних, що керують допусками й зберіганням файлів. Для провідників вигнанців, як-от Майстер-механік Кастпайп, повернення цих закодованих на перфокартах архівів із зруйнованих глибин — одна з найнагальніших справ громади біженців у Містечку Майстрів."},{t="Ієрархія перфорацій",b="Гномський протокол даних вимагає суворого допуску, перш ніж відкрити доступ до центральних обчислювальних машин. Щоб скористатися системою, треба почати з простої Білої Перфокарти, яку можна знайти серед уламків біля внутрішньої брами. Вставлена в «Матричний Перфограф 3005-A» у Депо потяга, вона перетворюється на Жовту картку, яку далі треба віднести до терміналу 3005-B у Гуртожитку, щоб отримати Синю, потім удосконалити на моделі 3005-C до Червоної і зрештою спуститися в Інженерні Лабораторії, щоб закодувати жадану Призматичну Перфокарту."},{t="Гномський гумор у двійковому коді",b="Хоча Кастпайп подає це завдання як справу нагальної громадської ваги, самі перфокарти містять потоки двійкових даних, що відкривають ексцентричний, зухвалий світогляд обчислювальних гільдій Гномреґана. Серед справжніх технічних даних візерунки дірок перекладаються в кумедні дотепи, абсурдні скарги на роботу й непристойні жарти про те, що Великий Тінкер Ґелбін Меккаторк носить спідню білизну нічних ельфів. Це доводить, що навіть у серці високотехнологічної інфраструктури гномські інженери не могли втриматися від жарту."}},faq={{q="Що таке Призматична Перфокарта?",a="Призматична Перфокарта — картка доступу найвищого рівня, яку визнають автоматичні головні комп'ютери Гномреґана. Її отримують, обробивши Червону Перфокарту на терміналі Матричний Перфограф 3005-D глибоко в Інженерних Лабораторіях.",al={"призматична картка","що таке перфокарта","перфокарта гномереґана"}},{q="З чого починається послідовність перфокарт?",a="Послідовність починається з простої Білої Перфокарти, яку здобувають з трогів і покинутих механізмів одразу за головним входом до підземелля, біля Депо потяга.",al={"де взяти білу перфокарту","як почати перфокарти","перша перфокарта"}},{q="Де стоять термінали Матричний Перфограф?",a="Модель 3005-A стоїть поза підземеллям, у Депо потяга. Модель 3005-B — у Гуртожитку за Чистою Зоною. Модель 3005-C — на навісних платформах далі, а модель 3005-D — на нижньому рівні Інженерних Лабораторій.",al={"місце терміналів","де перфографи","машини перфокарт"}},{q="Хто такий Майстер-механік Кастпайп?",a="Майстер-механік Кастпайп — старший гном-інженер, що живе серед біженців у Містечку Майстрів в Айронфорджі. Відчайдушно прагнучи врятувати інтелектуальну спадщину Гномреґана, він організовує розвідувальні й рятувальні вилазки в полеглу столицю.",al={"кастпайп","хто дає порятунок даних","лор кастпайпа"}},{q="Які дані насправді на картках?",a="Якщо перекласти сирий двійковий код ASCII, на перфокартах — суміш гномських інженерних балачок, жартів про очільників на кшталт Тралла й Меккаторка та дивакуватих нотаток поряд із найважливішими обчислювальними даними міста.",al={"текст карток","двійковий переклад","що каже двійковий код"}},{q="Чи можуть гравці Орди користуватися цими терміналами?",a="Саме завдання пропонує лише Альянсу Майстер-механік Кастпайп в Айронфорджі, але фізичними терміналами перфографів у підземеллі технічно може скористатися кожен, хто має потрібні картки.",al={"порятунок даних орди","перфокарти орди","чи орда може користуватися терміналами"}}},fp="11,422,32.512.0,27.527.0,24.517.1,33.244.0,45.169.0,51.247.0,32.240.0,35.244.0,41.233.0"}
P.entries["quest:2931"] = {n="Завдання Кастпайпа",s="«Завдання Кастпайпа» — виклик для Альянсу, що скеровує вправних шукачів пригод до Майстра-механіка Кастпайпа в Айронфорджі. Кастпайп організовує небезпечні рятувальні вилазки в опромінені руїни Гномреґана, щоб добути важливі механічні й технічні записи. Цей виклик — офіційний інструктаж, що відправляє найманців на пошукові операції в глибини полеглого міста.",h="«Завдання Кастпайпа» — виклик для Альянсу, що скеровує вправних шукачів пригод до Майстра-механіка Кастпайпа...",kw={"завдання кастпайпа","кастпайп","ґаксим растфіззл","містечко майстрів","гномреґан","завдання"},ang={["faction:Alliance"]="Допомагаючи гномам-вигнанцям зберегти їхні втрачені архіви, ви стабілізуєте Містечко Майстрів і зміцнюєте спільну технологічну міць Альянсу.",["profession:Engineering"]="Ядра даних у Гномреґані зберігають обчислювальні дива й передові креслення, яким немає рівних ніде на Азероті.",["race:Gnome"]="Кожна рятувальна операція — це частинка вашої полеглої батьківщини, вбережена від радіації й руйнування, тож місія Кастпайпа — справа виживання вашої культури."},sec={{t="Заклик до Містечка Майстрів",b="Після трагічного падіння Гномреґана й радіоактивного карантину вцілілі гноми знайшли притулок у Містечку Майстрів в Айронфорджі. Поки їхній величний дім кишить трогами й опроміненими конструктами, важливі робочі записи й механічні креслення лишаються замкненими глибоко в уцілілих обчислювальних масивах міста. Розуміючи, що ці файли можуть стати безцінними, щоб відвоювати місто чи збагнути, що пішло не так, Майстер-механік Кастпайп почав наймати відважних чужинців, готових пройти отруйними залами."},{t="Схвалення Асамблеї",b="Звістку про справу Кастпайпа поширюють такі особи, як Ґаксим Растфіззл із Просвітленої Асамблеї Арканології, Алхімії та Інженерних Наук. Хоча сам Кастпайп і не належить до цього шановного вченого товариства, гноми настільки поважають його технічну кмітливість, що підтримують його починання. За власними розрахунками Растфіззла, ймовірність того, що місія Кастпайпа має справжню стратегічну цінність, становить обнадійливі вісімдесят чотири відсотки, і це спонукає мандрівників вирушати до Містечка Майстрів по накази."}},faq={{q="Хто такий Майстер-механік Кастпайп?",a="Майстер-механік Кастпайп — шанований гномський інженер з Містечка Майстрів в Айронфорджі. Він організовує загони рятувальників і операції з відновлення даних у підземних руїнах Гномреґана.",al={"кастпайп","хто такий кастпайп","майстер-механік кастпайп"}},{q="Навіщо Кастпайпові дані з Гномреґана?",a="Коли Гномреґан отруїли й евакуювали, в пам'яті головного комп'ютера лишилося безліч важливих технічних знань, креслень і системних журналів. Повернути ці відомості вкрай потрібно гномам-вигнанцям, які сподіваються відбудуватися.",al={"дані гномереґана","навіщо повертати дані","записи гномереґана"}},{q="Хто такий Ґаксим Растфіззл?",a="Ґаксим Растфіззл — гном-учений із Просвітленої Асамблеї Арканології, Алхімії та Інженерних Наук. Він — заступник і посередник, що спрямовує вправних шукачів пригод до рятувальної справи Кастпайпа.",al={"ґаксим","растфіззл"}},{q="Де знайти Кастпайпа?",a="Майстер-механік Кастпайп — у Містечку Майстрів, кварталі гномів у східній частині дворфійської столиці Айронфордж.",al={"місце кастпайпа","де кастпайп"}},{q="Що буде, коли з'явитися до Кастпайпа?",a="Доповідь Майстрові-механікові Кастпайпу веде просто до місії в самому полеглому місті — «Порятунок даних»: шукачам пригод доведеться прорватися в отруєні надра Гномреґана, щоб дістати перфокарти й носії даних.",al={"наступне завдання","що далі","після кастпайпа"}},{q="Що таке Просвітлена Асамблея Арканології, Алхімії та Інженерних Наук?",a="Просвітлена Асамблея Арканології, Алхімії та Інженерних Наук — престижне гномське вчене товариство, віддане ретельним науковим, магічним і механічним дослідженням. Її члени, як-от Ґаксим Растфіззл, оцінюють важливі завдання за суворою теорією ймовірностей.",al={"асамблея","просвітлена асамблея"}}},fp="15,376,20.534.0,20.486.0,32.199.0,44.253.0,24.227.0,28.144.0,41.239.0,81.277.0"}
P.entries["quest:294"] = {n="Помста Ормера",s="«Помста Ормера» починає каральний похід Ормера Айронбрейда — дослідника, що застряг високо над Місцем Розкопок Велґара в Багнокраї. Відкопавши прадавні скам'янілі кістки, дворфійська експедиція ненароком приманила зграї ненажерливих плямистих рапторів, які вирізали їхніх товаришів і загнали вцілілих на скелясту кручу.",h="«Помста Ормера» починає каральний похід Ормера Айронбрейда — дослідника, що застряг високо над Місцем...",kw={"помста ормера","ормер айронбрейд","плямисті раптори","місце розкопок велґара","меррін роквівер","багнокрай"},ang={["class:Hunter"]="Агресивні плямисті раптори, що нишпорять схилами довкола розкопу, дають уважним мисливцям нагоду вивчити, як небезпечні плазуни вистежують здобич на болотистій місцевості.",["race:Dwarf"]="Коли дворфів-побратимів убивають під час археологічної праці Ліги Дослідників, очищення кар'єру від рапторів стає справою честі предків і праведної відплати."},sec={{t="Відкопані жахи",b="Місце Розкопок Велґара мало стати тріумфом дворфійської археології — тут відкопували величезні доісторичні рештки, поховані під багнюкою Багнокраю. Натомість велетенські кістки привабили місцевих болотяних рапторів. Зграї плямистих хижаків, яких притягнув шум, налетіли на розкоп, захопили копачів зненацька й пошматували їхні лави."},{t="Гірка оборона",b="Першу різанину пережила лише жменька дворфів. Ормер Айронбрейд, Меррін Роквівер і Шукач Велґар зуміли видертися на кручу над котлованом, але зграї внизу й досі тримають їх в облозі. Гнаний гірким горем і киплячим гнівом, Ормер не збирається просто ховатися. Зобов'язаний охороняти наляканого Шукача й Меррін, він наймає вправних мандрівників, щоб прорідити плямистих рапторів і плямистих верескунів довкола, — це перший залп його помсти."}},faq={{q="Що сталося тут із копачами?",a="Коли дворфійські археологи відкопали в улоговині велетенські кістки, гамір і запах виманили з боліт місцеві зграї ящерів-рапторів. Хижаки захопили табір, вирізали більшість загону, а трьох уцілілих загнали на високу кручу.",al={"чому тут раптори","різанина розкопок вельґара","що вбило дворфів"}},{q="Хто такий Ормер Айронбрейд?",a="Ормер — один з уцілілих дворфів-копачів, що застрягли на Місці Розкопок Велґара. Честь велить йому лишатися й захищати переляканих Шукача Велґара й Мерріна Роквівера, але найбільше він прагне кривавої помсти рапторам, що вирізали його товаришів.",al={"хто такий ормер","передісторія ормера айронбрейда"}},{q="Звідки ці раптори?",a="Плямисті раптори й плямисті верескуни — корінні хижаки Багнокраю, що чатують по всіх багнистих схилах і болотах на захід від кручі з розкопками, а також на стежках, що ведуть до печер розкопок.",al={"де плямисті раптори","місця рапторів багнокраю"}},{q="Чому Ормер не полює на рапторів сам?",a="Хоч Ормер і рветься сам пролити кров рапторів, він мусить стерегти наляканих Шукача Велґара й Мерріна Роквівера, щоб їхній притулок на кручі не захопили.",al={"чому ормер сам не полює","чому ормер застряг"}},{q="Чи вгамовує винищення цих рапторів Ормерову образу?",a="Ні. Пробитися крізь звичайних плямистих рапторів і верескунів — лише перший крок Ормерового задуму помститися за полеглих друзів; далі будуть жорсткіші удари по виводку рапторів.",al={"чи це кінець помсти ормера","що далі з ормером"}},{q="Чому розкопані кістки привабили рапторів?",a="Раптори Багнокраю люто боронять свою землю й завзято шукають падлину. Вибухи й розкопки давніх велетенських решток порушили природну рівновагу улоговини й привели цікавих і голодних хижаків просто в серце табору.",al={"чому кістки привабили рапторів","кістки динозаврів раптори"}}},fp="15,339,17.382.0,14.475.0,37.255.0,23.280.0,33.216.0,43.186.0,46.188.0,49.240.0"}
P.entries["quest:2945"] = {n="Закаляний Брудом Перстень",s="Глибоко в опромінених руїнах Гномреґана шукачі пригод можуть забрати в дворфа-загарбника з клану Темного Заліза прикрасу, густо вкриту отруйним брудом і затверділим намулом. Щоб дізнатися, що це насправді, доведеться скористатися «Іскроматом 5200» — промисловим автоматом для чищення в секторі Гуртожитку. Очищений перстень відкриває особисті позначки, і з них починається подорож, щоб повернути чи переробити цю родинну реліквію.",h="Глибоко в опромінених руїнах Гномреґана шукачі пригод можуть забрати в дворфа-загарбника з клану Темного...",kw={"закаляний брудом перстень","перстень","іскромат 5200","гномреґан","темне залізо","гуртожиток","завдання"},ang={["profession:Engineering"]="«Іскромат 5200» — класичний приклад химерної гномської інженерії, що поєднує промислове шкрябання розчинниками з автоматичним пакуванням подарунків.",["race:Dwarf"]="Те, що перстень знайшовся в лазутчика з Темного Заліза, натякає на здобич, награбовану в мешканців Айронфорджа чи в гномів-жертв серед хаосу падіння Гномреґана.",["race:Gnome"]="Навіть під час катастрофічного падіння свого міста гноми конструювали прибиральні пристрої, які завершують небезпечний промисловий цикл миття веселим дзвіночком і бантиком."},sec={{t="Реліквія під намулом",b="Коридори Гномреґана потопають в отруйному мулі, мастилі й радіоактивних опадах, тож не дивно, що речі, загублені в боях, покриваються непроникним брудом. Убиті дворфи Темного Заліза, що проникають до міста, часто мають при собі дуже забруднені дрібнички, і серед них — цей закаляний брудом перстень. Кірка надто міцна, щоб відмити її руками, і цілком приховує, що під нею — мідь, золото чи просто мотлох."},{t="Іскромат 5200",b="Щоб очистити перстень, треба знайти «Іскромат 5200» у гуртожитку Чистої Зони. Ця машина — гномська інженерія в усій її чарівній безглуздості: вона приймає монети, піддає найбрудніші речі шаленому внутрішньому шкрябанню й випльовує їх свіжовідполірованими та охайно запакованими в подарунковий папір із бантиком. Під знятим опроміненим брудом проступає вигравіювана відзнака, що належить мешканцеві Айронфорджа, — і підібрана дрібничка перетворюється на завдання з повернення власності."}},faq={{q="Де знайти Закаляний Брудом Перстень?",a="Закаляний Брудом Перстень знаходять на тілах дворфів Темного Заліза в обложеному підземеллі Гномреґан.",al={"де падає перстень","звідки закаляний перстень","хто дропає закаляний брудом перстень"}},{q="Як очистити перстень?",a="Віднесіть перстень до Іскромата 5200 у гуртожитку Чистої Зони в Гномреґані. Вкиньте перстень разом із потрібною платою — і почнеться потужне автоматичне чищення, що зніме затвердлий бруд.",al={"як очистити перстень","чистка персня","де помити перстень"}},{q="Що буде, коли перстень очищено?",a="Іскромат видає охайно запаковану коробочку з відновленим перснем, на якому видно особисті гравіювання. Так починається завдання «Повернення персня», що веде до його первісного власника.",al={"наступне завдання закаляного персня","що робити з чистим перснем","результат іскромата"}},{q="Чи можуть гравці Орди виконати це завдання?",a="Так. Шукачі пригод з Орди теж можуть очистити перстень в Іскроматі 5200. Проте далі ланцюжок розходиться, і гравців Орди зрештою спрямовують до інженера в Оргріммарі, а не до Айронфорджа.",al={"закаляний перстень лише для альянсу","закаляний перстень орди","чи орда може очистити перстень"}},{q="Чому після чищення перстень загорнуто в подарункову коробку?",a="Іскромат 5200 створено з типовою гномською примхливістю. Крім того, що апарат завзято шкребе намул і бруд, він запрограмований наприкінці автоматично пакувати оброблені речі й зав'язувати на них ошатний бантик.",al={"подарункова коробка персня","чому подарункова коробка"}},{q="Чи кілька там машин Іскромат?",a="Уздовж стіни в гуртожитку Чистої Зони стоїть кілька Іскроматів, але для персня справно працює лише один — ліворуч, як зайдете сходами, біля привітних гномів.",al={"який іскромат","місця іскромата 5200"}}},fp="20,417,24.429.0,21.453.1,43.130.0,26.223.0,39.192.0,38.221.0,53.235.0,41.186.0"}
P.entries["quest:2947"] = {n="Повернення персня",s="Зчистивши шари підземного мулу в автоматичному чистильному апараті Гномреґана, шукач пригод знаходить бездоганний золотий перстень із печаткою Айронфорджа й ініціалами «ТдК». Ці позначки ведуть у гамірні ремісничі провулки дворфійської столиці, до його ексцентричного творця.",h="Зчистивши шари підземного мулу в автоматичному чистильному апараті Гномреґана, шукач пригод знаходить...",kw={"повернення персня","осяйний золотий перстень","талваш дель кіссель","іскромат 5200","айронфордж","гномреґан","завдання"},ang={["faction:Alliance"]="Знахідка речей із печаткою Айронфорджа в руках лазутчиків Темного Заліза підтверджує, що агенти імператора Тауріссана дедалі сильніше загрожують гірській домівці Альянсу.",["race:Gnome"]="Повернення втраченої роботи з полеглого міста дає рідкісну змогу зазирнути в мирне буденне ремесло, яким гноми жили до катастрофи Термаплаґа."},sec={{t="Скарб у багні",b="Глибоко в опромінених руїнах Гномреґана давні машини й досі гудуть наперекір вторгненню трогів. Якщо вкинути в «Іскромат 5200» брудну, обліплену намулом дрібничку, він зчищає роки опроміненого отруйного бруду, і з-під нього з'являється відполірований Осяйний Золотий Перстень, що пульсує таємною силою. На внутрішньому боці обідка вибито виразну пробірну печатку Айронфорджа, а поруч — три охайно вигравіювані ініціали: «ТдК»."},{t="Майстер Кварталу містиків",b="Ці ініціали належать не кому іншому, як Талвашеві Дель Кісселю — ексцентричному гномові-ювеліру, що працює в Кварталі містиків Айронфорджа, часто гарячково відбиваючись від уявних збирачів боргів. Талваш одразу впізнає в персні одну зі своїх звичайних робіт, які він виготовляв у старій майстерні в Гномреґані ще до падіння. Звістка про те, що прикрасу знайшли в лапах лазутчиків Темного Заліза, глибоко стривожує майстра й натякає на темні інтриги, що вирують під утраченим техномістом."}},faq={{q="Хто зробив перстень, знайдений у Гномреґані?",a="Ініціали «TdK» належать Талвашеві Дель Кісселю — дивакуватому гномові-ювеліру, що нині живе в Кварталі містиків Айронфорджа. До падіння Гномреґана Талваш тримав у місті ювелірну крамницю й викував кілька простих магічних перснів такого зразка.",al={"хто зробив перстень","ініціали персня tdk","хто такий tdk"}},{q="Звідки взявся перстень?",a="Перстень знайшли як заляпану брудом дрібничку глибоко в Гномреґані — його мали при собі ворожі загарбники, як-от дворфи Темного Заліза. Після автоматичного Іскромата 5200 до нього повернулися золотий полиск і клейма майстра.",al={"де знайшли перстень","звідки перстень"}},{q="Звідки в дворфів Темного Заліза Талвашів перстень?",a="Талваш і сам не певен, але зауважує, що знайти його роботу ще з часів до падіння в лазутчиків Темного Заліза — ще один підозрілий штрих до змов довкола загибелі Гномреґана. Найпевніше, перстень потрапив до них з його покинутої майстерні чи з речей когось, хто не встиг утекти від навали.",al={"чому темне залізо має перстень","лор персня темного заліза"}},{q="Чому Талваш Дель Кіссель вважає вас своїм домовласником?",a="Талваш сумно відомий тим, що вічно знервований, дивакуватий і постійно заборгував за оренду в Айронфорджі. Щоразу, як до його крамниці рішуче підходять незнайомці, він думає, що це судові пристави чи домовласники прийшли по його прострочені борги.",al={"чому талваш параноїть","оренда талваша"}},{q="Чи робить Талваш прокляті прикраси?",a="Талваш рішуче запевняє всіх можливих покупців, що не робить проклятих речей, хоча його знервовані поспішні заперечення радше збуджують нові питання, ніж дають відповіді.",al={"чи талваш прокляті прикраси","прокляті прикраси айронфорджа"}},{q="Чи можна просто залишити перстень собі, а не повертати?",a="Дрібничка й сама має магічні властивості, але якщо показати її майстрові, Талваш огляне виріб і запропонує посилити його чари в наступній роботі.",al={"залишити перстень собі","чи повертати перстень"}}},fp="18,314,24.408.0,30.489.1,38.253.0,40.239.0,51.293.0,55.225.0,33.178.0,49.188.0"}
P.entries["quest:2948"] = {n="Гномське вдосконалення",s="Коли шукач пригод приносить Талвашеві Дель Кісселю перстень, який той колись виготовив і який дістали з радіоактивних глибин Гномреґана, Талваш пропонує вдосконалити прикрасу — якщо йому принесуть матеріали. Гном-майстер, якому не щастить у дворфійській столиці Айронфорджі, поєднує срібло, моховий агат і тонку ґратчасту оправу й створює куди кращу дрібничку.",h="Коли шукач пригод приносить Талвашеві Дель Кісселю перстень, який той колись виготовив і який дістали з...",kw={"талваш дель кіссель","перстень","моховий агат","срібло","гномреґан","ювелір"},ang={["faction:Alliance"]="Розгортаючись між Гномреґаном і Айронфорджем, це доручення зміцнює глибокі зв'язки між героями Альянсу та біженцями із загиблої гномської столиці.",["profession:Mining"]="Шахтарі постачають необхідну сировину — виплавлене срібло й моховий агат із підземних покладів, — без якої Талвашеві не обійтися в ювелірній роботі.",["race:Gnome"]="Це завдання показує гордість і стійкість гномських майстрів, які не погоджуються на абияку роботу навіть далеко від дому й без сировини."},sec={{t="Гном-майстер у вигнанні",b="Талваш Дель Кіссель — один із численних гномів-біженців, що втекли з Гномреґана після його катастрофічного падіння під навалою трогів і радіації. Тепер він живе в Кварталі містиків Айронфорджа: удача від нього відвернулася, запаси скінчилися, і він відчайдушно хоче довести, що вигнання не потьмарило його хисту ювеліра й механіка."},{t="Нове життя старого персня",b="Коли шукач пригод показує Талвашеві простенький перстень його власної роботи, ще з часів до падіння, очищений від бруду Блискоматиком 5200, майстер вдячний, але амбіції беруть гору. Він не хоче, щоб клієнт пішов від нього із застарілою, як на його смак, простою прикрасою, тож наполягає на тому, щоб її вдосконалити. Наклавши на обідок тонку ґратку зі срібла й мохового агату, Талваш створює кращу річ, яка свідчить про його зростання в обробці металу й самоцвітів."}},faq={{q="Хто такий Талваш Дель Кіссель?",a="Талваш Дель Кіссель — вправний гном-майстер і ювелір, що нині живе вигнанцем в Айронфорджі. До падіння Гномреґана він тримав там невелику ювелірну крамницю, і один з перснів, які він тоді зробив, можна знайти й принести йому в Квартал містиків.",al={"талваш","талваш дель кіссель","гном-ювелір айронфордж"}},{q="Яка історія персня, що його вдосконалюють?",a="Основа — один з кількох простих перснів, які Талваш зробив у своїй старій крамниці в Гномреґані; згодом його знайшли в дворфа Темного Заліза серед руїн. Коли шукачі пригод забирають перстень з чистильної машини Іскромат 5200 у зруйнованому місті, Талваш пропонує осучаснити й прикрасити простий обідок, перетворивши його на значно витонченішу річ.",al={"звідки перстень","походження закаляного персня"}},{q="Чому Талваш просить гравця принести реагенти?",a="Як і чимало гномів-біженців, вигнаних з Гномреґана, Талваш ледве зводить кінці з кінцями й цілком вичерпав свої запаси сировини в Айронфорджі. Без мецената в нього немає ні срібла, ні мохового агату, щоб виконати тонку ґратчасту роботу самотужки.",al={"навіщо срібло і мохоагат","чому в талваша немає матеріалів"}},{q="Звідки починається цей ланцюжок завдань?",a="Ланцюжок починається в підземеллі Гномреґан: треба здобути з ворогів Закаляний Брудом Перстень, очистити його в машині Іскромат 5200, а тоді за вигравіюваними ініціалами «TdK» знайти Талваша в Айронфорджі.",al={"як почати гномське вдосконалення","початок лінії персня"}},{q="Чи переживає Талваш через своє становище в Айронфорджі?",a="Він нарікає, що застряг у, як він каже, несправедливій фінансовій ямі, але не занепадає духом і зберігає професійну гордість. Він твердо вірить, що, ставши на ноги, прославиться по всьому Азероту як майстер найкращих прикрас.",al={"передісторія талваша","характер талваша"}},{q="Чи доступне це завдання Орді?",a="Ні. Гравці Орди теж можуть очищати Вкриті Брудом речі в Гномреґані, але їхня версія завдання з перснем спрямовує їх до іншого знайомого — Ноґґа в Оргріммарі, а не до Талваша в Айронфорджі.",al={"чи орда може гномське вдосконалення","вдосконалення персня орди"}}},fp="17,365,26.346.0,22.439.0,26.252.0,51.315.0,56.262.0,34.225.0,51.259.0,41.197.0"}
P.entries["quest:2949"] = {n="Повернення персня",s="Зчистивши бруд Гномреґана в «Іскроматі 5200», шукач пригод знаходить перстень із печаткою Оргріммара й вигравіюваними літерами «НОҐ». Слід веде до столиці Орди, просто до гобліна-інженера Ноґґа, який має власні цікаві здогади про падіння міста.",h="Зчистивши бруд Гномреґана в «Іскроматі 5200», шукач пригод знаходить перстень із печаткою Оргріммара й...",kw={"повернення персня","ноґґ","оргріммар","долина честі","іскромат 5200","гномреґан","завдання"},ang={["faction:Horde"]="Знайти символіку Орди в самому серці головної технологічної столиці Східних Королівств — рідкість, і ця знахідка веде шукачів пригод з Орди з Каз Модану назад до Долини Честі.",["profession:Engineering"]="Гоблінські інженери Оргріммара постійно міряються з гномськими винахідниками, тож Ноґґ радо розбере на частини будь-що, принесене із серця їхнього полеглого технологічного дива."},sec={{t="Дивна знахідка",b="Гномреґан — місто Альянсу в глибинах Каз Модану, тож знахідка персня з офіційною печаткою Оргріммара цілком несподівана. Пройшовши крізь гномський чистильний апарат «Іскромат», дрібничка скидає товстий шар підземного мулу, і відкриваються сплеск магічної сили та почасти розбірливі літери «НОҐ». Хай перстень виготовили в Калімдорі чи принесли сюди з якоюсь нещасливою експедицією, він явно походить зі столиці Орди."},{t="Гномське суперництво й змови Темного Заліза",b="Перстень, повернений до Долини Честі в Оргріммарі, приводить просто до Ноґґа — інженера, який одразу пояснює, що це не його особиста прикраса, але її походження викликає цікаві запитання. Гобліни здавна дивляться на гномських винахідників зверхньо, як на ексцентричних суперників. Ноґґові здається, що раз дворфи Темного Заліза тримали перстень у Гномреґані, то гноми, можливо, викрали й переробили конструкції големів Темного Заліза, а ті тепер прагнуть розплати, — і цей слід, на його думку, варто дослідити."}},faq={{q="Чому на персні, знайденому в Гномреґані, печатка Оргріммара?",a="Як саме перстень потрапив до Гномреґана, невідомо, але його занесли глибоко в руїни, і там він опинився в дворфів Темного Заліза. Знак Оргріммара пов'язує його з ковалями й майстрами Орди з Дуротару.",al={"чому печатка оргріммара","перстень орди в гномереґані","як перстень туди потрапив"}},{q="Хто такий Ноґґ?",a="Ноґґ — гоблін-інженер з Долини Честі в Оргріммарі. Він опікується інженерним крамом і машинами, а його ім'я збігається зі стертими літерами, вигравіюваними поряд з печаткою Оргріммара на очищеному персні.",al={"хто такий ноґґ","ноґґ оргріммар","листи ноґґа перстень"}},{q="Що таке Іскромат 5200?",a="Іскромат 5200 — автоматична промислова мийна установка в Чистій Зоні Гномреґана. Вона знімає товсті шари отруйного намулу й радіації з речей, винесених зі зруйнованих коридорів.",al={"що таке іскромат","іскромат 5200","чистомат"}},{q="Чи належить перстень Ноґґові?",a="Ні. Оглянувши очищений обідок, Ноґґ визнає, що він не його. Проте він упізнає майстерність виготовлення й своїми інженерними знаннями вдосконалює перстень для шукача пригод.",al={"чи перстень ноґґа","чи ноґґ загубив перстень","чий перстень"}},{q="Що, на думку Ноґґа, сталося з Гномреґаном?",a="Ноґґ підозрює, що гноми поцупили в клану Темного Заліза креслення новітніх големів. Він міркує, що Темне Залізо захоче за це добряче поквитатися, і вважає, що цей слід варто дослідити.",al={"теорія ноґґа про гномереґан","що сталося з гномереґаном","чому темне залізо"}},{q="Чи можна залишити перстень собі, а не нести Ноґґові?",a="Ви самі вирішуєте: одразу носити перстень чи віднести його до Оргріммара. Але якщо принести його Ноґґові, гоблін-інженер огляне роботу й запропонує її вдосконалити.",al={"залишити золотий перстень","чи повертати перстень","чи віддавати ноґґові"}}},fp="18,307,19.460.0,37.508.1,63.251.0,12.214.0,30.215.0,23.218.1,44.196.0,52.191.0"}
P.entries["quest:295"] = {n="Помста Ормера",s="«Помста Ормера» — завдання Альянсу від Ормера Айронбрейда на зруйнованому Місці Розкопок Велґара в Багнокраї. Коли менших рапторів-розвідників уже знищено, Ормер вимагає винищити важчих плямистих серпокігтів і гостропащ, що вигнали його експедицію з котлованів.",h="«Помста Ормера» — завдання Альянсу від Ормера Айронбрейда на зруйнованому Місці Розкопок Велґара в Багнокраї.",kw={"помста ормера","ормер айронбрейд","серпокігті","гостропащі","раптори","місце розкопок велґара"},ang={["class:Hunter"]="Плямисті раптори Багнокраю — люто ревниві до своєї території зграйні мисливці, і вистежувати їх у тісних багнистих траншеях — смертельно небезпечне випробування.",["faction:Alliance"]="Повернення Місця Розкопок Велґара убезпечує роботу вздовж східної дороги, що з'єднує Багнокрай з Аратійським нагір'ям.",["race:Dwarf"]="Лють Ормера відбиває запеклу гордість Ліги Дослідників, яка не дозволить диким звірам назавжди спинити дворфійські пошуки минулого предків."},sec={{t="Полювання розгортається",b="Ворожнеча Ормера Айронбрейда з рапторами, що лютують на Місці Розкопок Велґара, глибоко особиста. Прорідивши дрібніший молодняк, що заполонив верхній табір, він спрямовує ваші клинки на дорослих хижаків, які нишпорять нижньою частиною розкопу. Плямисті серпокігті й гостропащі — головна загроза для будь-якої надії відновити археологічну працю: вони шматують дворфів-рудошукачів і лишають траншеї всіяними розтрощеними ящиками й покинутими кайлами."},{t="Кров у траншеях",b="Котловани розкопу фактично перетворилися на гніздовище рапторів. Похмуро сидячи на гребені над розкопом, Ормер посилає вправних шукачів пригод у багнюку, щоб ударити просто по дорослих звірах. Шукач Велґар і його загін сподіваються врятувати прадавні реліквії, а Ормер цілком поглинутий помстою: він вимагає чималого рахунку вбитих серпокігтів і гостропащ, перш ніж подумати про те, щоб узятися за найгрізніше страхіття розкопу."}},faq={{q="Чому Ормер так лютує на цих рапторів?",a="Плямисті раптори люто налетіли на Місце Розкопок Велґара й захопили його, вигнавши загін дворфів і вирізавши всіх, хто не встиг утекти. Ормер Айронбрейд лишився без місця й з гіркотою в серці, і він не дасть звірам панувати на розкопках, не заплативши за це кров'ю.",al={"чому ормер лютує","причина помсти ормера","навіщо вбивати рапторів"}},{q="Де водяться плямисті косопазурі й бритвопащі?",a="Обидві породи рапторів никають нижніми траншеями й довколишніми насипами Місця Розкопок Велґара, на схід від Гавані Менетіл і на південний захід від Дун Модра в Багнокраї.",al={"місце плямистих косопазурів","місце плямистих бритвопащів","де шукати рапторів"}},{q="Хто такий Ормер Айронбрейд?",a="Ормер Айронбрейд — дворф із Ліги Дослідників, що працює на Місці Розкопок Велґара. Після того як розкопки катастрофічно захопили, він поставив собі за особисту мету винищити зграю рапторів, що заполонила їхню роботу.",al={"хто такий ормер","ормер айронбрейд лор"}},{q="Що буде, коли проріджено цих рапторів?",a="Коли ви проріджите косопазурів і бритвопащих, Ормер зосереджується на Гарчозубі — великому рапторі, якого вважає ватажком місцевої зграї, і доручає вам знищити головне джерело навали.",al={"що далі після помсти ормера","продовження помсти ормера","наступне завдання після косопазурів"}},{q="Чи пов'язане це завдання з іншими справами на розкопках?",a="Так. Полюючи на рапторів у нижній частині розкопок для Ормера, шукачі пригод часто допомагають Шукачеві Велґару та його загонові в завданні «Розкриваючи минуле», збираючи уламки артефактів землян, розкидані тими самими траншеями.",al={"завдання розкопок вельґара","зв'язок розкриваючи минуле"}},{q="Навіщо дворфи взагалі тут копали?",a="Ліга Дослідників з Айронфорджа заснувала Місце Розкопок Велґара, щоб шукати реліквії титанів і розкрити давню історію дворфійського роду, але роботу довелося зупинити, коли розкопки заполонили агресивні звірі.",al={"чому копали в багнокраї","мета розкопок вельґара"}}},fp="15,272,19.491.0,21.441.0,39.292.0,54.186.0,23.238.0,41.213.1,62.242.0,53.232.0"}
P.entries["quest:2950"] = {n="Ноґґ переробляє перстень",s="Ноґґ переробляє перстень — фінал історії про вкриту брудом прикрасу, яку принесли з руїн Гномреґана до Оргріммара. Навзамін за рідкісні матеріали й цінні відомості про дворфів Темного Заліза гоблінський інженер Ноґґ удосконалює здобутий перстень, прагнучи довести, що гоблінське ремесло вище за гномське.",h="Ноґґ переробляє перстень — фінал історії про вкриту брудом прикрасу, яку принесли з руїн Гномреґана до...",kw={"ноґґ","перстень","гномреґан","темне залізо","моховий агат","срібло"},ang={["faction:Horde"]="Здобуваючи технології із залів, пов'язаних з Альянсом, як-от Гномреґан, і передаючи їх механікам Оргріммара, Орда отримує важливе розуміння можливостей ворога.",["profession:Engineering"]="Завдання показує одвічне ідейне суперництво гоблінської винахідливості й гномських механізмів і гоблінський підхід — завзято переробляти наявну техніку заради найбільшої віддачі.",["profession:Mining"]="Щоб удосконалити здобутий перстень, потрібні цінні дари надр — виплавлений злиток срібла й моховий агат, — тож без умілих шахтарів і різьбярів самоцвітів не обійтися."},sec={{t="Гоблінська вищість",b="Коли шукач пригод приносить до майстерні Ноґґа в Долині Честі очищений золотий перстень, здобутий у глибинах Гномреґана, природна гордість інженера бере гору. Зневажливо назвавши первісну роботу скромним витвором якогось гнома, Ноґґ пропонує угоду. За сировину й невелику плату він обіцяє вдосконалити цю прикрасу Альянсу, сплівши тонку ґратку зі срібла й мохового агату, що має посилити магію, яка струменить обідком."},{t="Дворфійський слід",b="Раптова готовність Ноґґа вдосконалити перстень пояснюється не лише комерційним інтересом. Звістки про дворфів Темного Заліза, що ховаються в обложеному гномському місті, неабияк його зацікавлюють. Для Ноґґа присутність дворфів пояснює, чому гноми раптом зуміли створити такі вишукані механізми — а це гобліни вважають винятково своєю цариною. Ці відомості приносять шукачеві пригод удосконалену прикрасу й неохочу повагу Ноґґа."}},faq={{q="Хто такий Ноґґ?",a="Ноґґ — знаний гоблін-інженер з Долини Честі в Оргріммарі. Він тісно співпрацює з іншими майстрами міста й часто має справу з цікавими механічними артефактами й кресленнями, здобутими в небезпечних експедиціях.",al={"хто такий ноґґ","ноґґ оргріммар","нпц ноґґ"}},{q="Які матеріали потрібні, щоб переробити перстень?",a="Ноґґові потрібні первісний Осяйний Золотий Перстень, один Срібний Злиток, один Моховий Агат і тридцять срібних монет — за роботу й витрати майстерні.",al={"матеріали персня","матеріали ноґґа","що потрібно ноґґові"}},{q="Чому Ноґґа цікавить Гномреґан?",a="Гномреґан має величезну технологічну цінність. Гобліни запекло змагаються з гномами в технічних справах, і Ноґґа особливо зацікавили чутки, що до технологічних аномалій у полеглому техномісті доклали рук дворфи Темного Заліза.",al={"чому ноґґа цікавить гномереґан","інтерес гоблінів до гномереґана"}},{q="Що саме Ноґґ робить із перснем?",a="Ноґґ споруджує просто довкола золотого обідка ґратку зі срібла й мохового агату. Цей тонкий каркас спрямовує й урівноважує приховані чари в прикрасі, і виходить сильніша, могутніша річ, ніж за первісним гномським задумом.",al={"лор вдосконалення персня","що змінюється на персні"}},{q="Де починається цей ланцюжок завдань?",a="Ланцюжок починається глибоко в Гномреґані, коли шукач пригод здобуває з одного з дворфів Темного Заліза Закаляний Брудом Перстень і відмиває його в машині Іскромат 5200.",al={"початок ланцюжка","як почати ноґґа","початок лінії персня"}},{q="Чому Ноґґ підозрює дворфів Темного Заліза?",a="Гобліни-інженери вельми скептично ставляться до гномських винаходів. Для Ноґґа будь-який раптовий проблиск революційної механічної думки в гномів мусив з'явитися під впливом чи з подачі сторонніх пройдисвітів — а саме підступного клану Темного Заліза.",al={"чому темне залізо","зв'язок дворфів темного заліза"}}},fp="16,322,18.448.0,15.467.1,12.264.0,46.147.0,37.245.0,39.253.0,34.182.0,40.227.0"}
P.entries["quest:2951"] = {n="Іскромат 5200!",s="«Іскромат 5200» — автоматичний чистильний пристрій у глибинах руїн Гномреґана, що й далі працює серед хаосу. Вкинувши в нього обліплену брудом річ, знайдену в підземних залах, і сплативши символічну монету, шукачі пригод можуть повернути знайденим дрібничкам, самоцвітам і брухту бездоганний вигляд. Цей пристрій — яскраве свідчення незгасної винахідливості й ексцентричності гномської інженерії.",h="«Іскромат 5200» — автоматичний чистильний пристрій у глибинах руїн Гномреґана, що й далі працює серед хаосу.",kw={"іскромат 5200","чистильна машина","гномреґан","срібні монети","реліквії","завдання"},ang={["faction:Alliance"]="Для рятувальних загонів Альянсу, що ризикують у залах Гномреґана, машина — нагода одразу очистити знайдені реліквії, перш ніж нести їх до Айронфорджа.",["profession:Engineering"]="Інженери оцінять потужний двигун і систему сортування, потрібні, щоб чистити й переробляти невідоме сміття, не заклинюючи й не вибухаючи.",["race:Gnome"]="Машина відображає класичну гномську стійкість: навіть під час катастрофічної евакуації з батьківщини торгівля й іскриста чистота йдуть своїм ходом без перерви."},sec={{t="Маяк серед бруду",b="Серед радіоактивних опадів і трогів, що поглинають Гномреґан, жменька вцілілих гномів утримує захищений периметр біля надзвичайного винаходу — «Іскромата 5200». Створений, щоб зчищати суворий підземний бруд із врятованих цінностей, цей міцний пристрій обіцяє «повернути блискучому — блиск». Навіть коли підземні потвори гатять у перебірки, машина стоїть напоготові до комерційної роботи."},{t="Шалена робота",b="Чистильний механізм аж ніяк не лагідний. Щойно шукач пригод вкидає обліплену брудом реліквію разом із трьома срібними монетами, «Іскромат» вибухає несамовитим вируванням. Увесь залізний апарат стогне, вібрує й хитається з боку на бік, зчищаючи отруйний мул, опромінене мастило й кам'яний пил. За мить він викидає те, що ховалося під брудом, — від коштовних мінералів до механічних деталей."}},faq={{q="Що таке Іскромат 5200?",a="Іскромат 5200 — автоматичний гномський чистильний пристрій у безпечному закутку Гномреґана. Його створено, щоб знімати впертий радіоактивний мазут, намул і бруд з обліплених ним речей, знайдених по всьому полеглому місту.",al={"що таке іскромат","що робить іскромат 5200","чистильна машина гномереґана"}},{q="Що потрібно, щоб машина запрацювала?",a="Щоб запустити Іскромат, потрібен Вкритий Брудом Предмет, знайдений серед чудовиськ і уламків Гномреґана, і плата за обробку — три срібні монети, вкинуті просто в монетоприймач машини.",al={"як користуватися іскроматом","вартість іскромата","що класти в іскромат"}},{q="Звідки робоча машина посеред зони бойових дій?",a="Гномська цивілізація тримається на автоматичних побутових і промислових зручностях. Коли навала трогів і отруйні викиди спустошили місто, уцілілі гноми відступили до укріплених майстерень, де машини на кшталт Іскромата лишилися цілими й під живленням.",al={"чому машина тут","хто поставив іскромат у гномереґані"}},{q="Що виходить після очищення забрудненої речі?",a="Машина повертає вашу знахідку цілком очищеною від бруду, відкриваючи корисні товари, ремісничі камені, самоцвіти чи запасні інженерні деталі, що ховалися під намулом.",al={"що отримуєш від іскромата","здобич іскромата","нагороди закаляних речей"}},{q="Чи можна користуватися Іскроматом 5200 не раз?",a="Так. Після першої демонстрації пристроєм можна користуватися знову й знову через повторювані чищення, якщо приносити нові вкриті брудом предмети й срібні монети.",al={"чи іскромат повторюваний","чи чистити багато речей","більше іскромата"}},{q="Чому машина так несамовито трясеться під час чищення?",a="Бруд у Гномреґані густий, отруйний і затвердлий. Машина покладається на швидкісне струшування й внутрішні шкребки, щоб здерти намул, тож увесь корпус під час роботи хитається й стогне.",al={"чому іскромат трясеться","чи іскромат зламаний"}}},fp="22,425,21.442.0,18.441.0,30.242.0,41.210.0,64.263.0,53.184.0,47.184.0,56.226.0"}
P.entries["quest:2952"] = {n="Іскромат 5200!",s="У глибинах опромінених залів Гномреґана стоїть «Іскромат 5200» — автоматичний чистильний пристрій, створений, щоб зішкрібати отруйний бруд зі знахідок. Машина знімає важкий бруд із забруднених речей і пакує все врятоване в ошатну подарункову коробку.",h="У глибинах опромінених залів Гномреґана стоїть «Іскромат 5200» — автоматичний чистильний пристрій, створений...",kw={"іскромат 5200","скарб","гномреґан","самоцвіти","подарунок","завдання"},ang={["profession:Engineering"]="Вивчення «Іскромата» дає змогу побачити автоматичне очищення від часточок і швидке пакування, розроблені так, щоб витримувати сильне фонове випромінювання.",["race:Gnome"]="«Іскромат» — разюче нагадування про дім до падіння: навіть промисловий чистильний апарат мусив весело дзенькати й видавати готовий виріб, загорнутий, мов подарунок на день народження."},sec={{t="Автоматичне очищення",b="Гномська інженерія часто однаково цінує ефективність і забавку. «Іскромат 5200» створили для роботи з отруйними й зараженими відходами: він зчищає бруд і їдкі рештки автоматичними циклами. Щойно його завантажать і заплатять, пристрій із брязкотом проходить програму чищення, а тоді весело дзенькає й охайно загортає все, що лишилося, у подарунок, перев'язаний бантиком."},{t="Скарб у багні",b="Відтоді як Гномреґан упав під натиском трогів і настала радіаційна катастрофа, незліченні особисті речі й технологічні уламки потонули в промисловій твані. Шукачі пригод, які вкидають у машину обліплені брудом речі, можуть повернути втрачені самоцвіти, сирі руди й давно загублені цінності, які поглинула трясовина, коли місто затопили викидами."}},faq={{q="Що робить Іскромат 5200?",a="Іскромат 5200 — автоматична чистильна машина в Гномреґані. Якщо дати їй вкритий брудом предмет і плату, вона очищає намул, бруд і радіоактивний мул і повертає очищений вміст, запакований у маленьку подарункову коробочку.",al={"що таке іскромат","як працює іскромат","функція іскромата"}},{q="Де стоїть Іскромат 5200?",a="Машина стоїть у внутрішніх коридорах полеглого міста Гномреґан, біля Чистої Зони, де колись діяли уцілілі й автоматичні системи знезараження.",al={"місце іскромата","де чистильна машина","знайти іскромат"}},{q="Чому машина зав'язує речі бантиком?",a="Її запрограмували з типовою гномською примхливістю. Навіть зішкрябавши з предмета небезпечні радіоактивні опади й отруйний бруд, творці задумали останній цикл так, щоб відновлена річ виходила гарненьким, охайно зав'язаним подарунком.",al={"чому подарункова коробка","загорнуто бантиком","в бантику"}},{q="Чи можуть шукачі пригод з Орди користуватися Іскроматом 5200?",a="Так. Іскромат 5200 — цілком автоматичний апарат, якому байдуже до фракцій. Доки відвідувач вкидає монети й забруднені речі, машина виконує свій цикл.",al={"іскромат орди","чи орда може чистити","чи іскромат нейтральний"}},{q="Чи можна користуватися Іскроматом кілька разів?",a="Так. Після першого запуску машина відкриває повторюване завдання, і кожен, хто знайде в підземеллі вкриті брудом речі, може обробляти їх знову й знову.",al={"чи іскромат повторюваний","ще раз іскромат","фарм закаляних речей"}},{q="Що буде після цього завдання?",a="Це перше очищення веде просто до повторюваного циклу чищення — «Іскромат знову в ділі», — де можна очищати будь-які інші вкриті брудом знахідки.",al={"наступне завдання після іскромата","що після іскромата 5200"}}},fp="22,285,19.384.0,22.341.0,35.246.0,39.175.0,41.225.0,48.184.0,42.179.0,30.186.0"}
P.entries["quest:2953"] = {n="Іскромат знову в ділі",s="У глибинах опромінених руїн Гномреґана стоїть «Іскромат 5200» — автоматичний чистильний апарат, покинутий під час евакуації міста. За невелику плату сріблом ця машина завзято вичищає цікаві знахідки з намулу й радіоактивного мулу, що вкриває полеглу столицю.",h="У глибинах опромінених руїн Гномреґана стоїть «Іскромат 5200» — автоматичний чистильний апарат, покинутий під...",kw={"іскромат 5200","чистильний апарат","гномреґан","срібло","знахідки","завдання"},ang={["profession:Engineering"]="Робота з пристроєм дає інженерам змогу на власні очі побачити надійні гномські цикли з розчинниками й автоматику, що вмикається від монети.",["race:Gnome"]="«Іскромат» — свідчення гномської механічної витривалості: він надійно працює серед отруєних руїн вашої батьківщини."},sec={{t="Автоматичне відновлення",b="«Іскромат 5200» — приклад винахідливої автоматичної інфраструктури, яку гноми встановили по всьому Гномреґану ще до вторгнення трогів і радіоактивних опадів. Хоча коридори заповнені отруйними відходами й ворожими автоматонами, цей пристрій досі точно виконує свою програму щоразу, коли отримує три срібні монети й обліплений брудом артефакт."},{t="Дива з намулу",b="Увімкнувшись, «Іскромат» шалено хитається, обливаючи й шкрябаючи вкинуту реліквію потужними гномськими розчинниками. Щойно цикл завершується веселим дзенькотом, машина видає охайно запаковану коробку з усім, що вціліло під їдким слизом трогів і отруйним брудом."}},faq={{q="Що таке Іскромат 5200?",a="Іскромат 5200 — автоматичний гномський чистильний пристрій у Гномреґані. Він знімає їдкий намул, бруд і радіоактивне сміття зі знайдених речей, перетворюючи їх на впізнавану здобич.",al={"іскромат 5200","що робить машина","чистильник гномереґана"}},{q="Чому машина бере гроші?",a="Щоб запустити цикл чищення, Іскроматові потрібні три срібні монети. Навіщо саме він бере плату, не пояснюється.",al={"чому платити срібло","вартість іскромата"}},{q="Які речі можна в неї класти?",a="Машина чистить саме вкриті брудом предмети — реліквії, здобуті з полеглих трогів, зіпсованих вартових і опромінених жахіть, що блукають тунелями Гномреґана.",al={"закаляна річ","які речі чистити"}},{q="Чи захищений Іскромат від радіації?",a="Хоча зовнішні тунелі просякнуті радіоактивними відходами, Іскромат 5200 і далі працює, застосовуючи особливі гномські мийні засоби, щоб зішкрябати небезпечний зовнішній наліт із речей, які в нього потрапляють.",al={"іскромат опромінений","забруднення іскромата"}},{q="Чи можуть обидві фракції користуватися Іскроматом 5200?",a="Так. Іскромат 5200 — цілком механічна автоматична установка, що діє нейтрально: приймає плату й вкриті брудом речі незалежно від того, кому служить відвідувач.",al={"іскромат орди","хто може користуватися"}},{q="Хто сконструював Іскромат?",a="Творця не названо. Іскромат — гномська чистильна машина, що досі працює в Гномреґані.",al={"творець іскромата","хто збудував іскромат"}}},fp="24,297,21.356.0,21.304.0,30.213.0,34.121.0,40.173.0,40.206.0,44.186.0,30.108.0"}
P.entries["quest:296"] = {n="Помста Ормера",s="«Помста Ормера» — завершення походу Ормера Айронбрейда, що мстить за дворфів-розкопувачів, вирізаних на Місці Розкопок Велґара. Переконаний, що лютий напад рапторів очолив хитрий звір на ім'я Сарлтут, Ормер посилає шукача пригод убити ватажка зграї й принести його пазур як доказ.",h="«Помста Ормера» — завершення походу Ормера Айронбрейда, що мстить за дворфів-розкопувачів, вирізаних на Місці...",kw={"помста ормера","сарлтут","ормер айронбрейд","раптори","місце розкопок велґара","багнокрай"},ang={["class:Hunter"]="Сарлтут — один із верховних хижаків Багнокраю, і щоб видертися на гребінь і повалити ватажка зграї, потрібні гострі навички слідопита.",["faction:Alliance"]="Безпека дворфійських експедицій на болотах гарантує, що опорні пункти Альянсу між Айронфорджем і північними землями лишаться цілими.",["race:Dwarf"]="Для дворфів помститися за вирізаний загін Ліги Дослідників на Місці Розкопок Велґара — справа честі полеглих підданих Короля Маґні."},sec={{t="Удар по ватажку зграї",b="Після різанини копачів Ліги Дослідників на Місці Розкопок Велґара Ормер Айронбрейд стежив зі свого гребеня за рапторами, що кишіли внизу, і помітив звіра, куди більшого за решту. Цей особливо великий і лютий раптор, відомий як Сарлтут, сидів над розкопом, спрямовуючи — чи ведучи за собою — зграю, що вигнала дворфів. Для Ормера звір був не просто дикою твариною, а призвідцем нападу на підданих Короля Маґні Бронзбірда."},{t="Справедливість у Багнокраї",b="Ормер вимагає за різанину найвищої кари й велить шукачам пригод піднятися високими стежками на стіни розкопу й покласти край Сарлтутові. Здобувши один із грізних пазурів звіра, ви помститеся за полеглих робітників і пошлете болотами суворе послання: напади на дворфійські експедиції не лишаться без відповіді."}},faq={{q="Хто такий Гарчозуб?",a="Гарчозуб — великий, грізний раптор, що веде зграю, яка захопила Місце Розкопок Велґара в Багнокраї. Ормер Айронбрейд вважає, що саме він спрямовував напад, у якому вирізали дворфів-копачів.",al={"хто такий гарчозуб","бос рапторів","гарчозуб лор"}},{q="Де шукати Гарчозуба?",a="Гарчозуб никає підвищеною стежкою, що здіймається західною стіною в північно-західному куті Місця Розкопок Велґара.",al={"знайти гарчозуба","де гарчозуб","шлях гарчозуба"}},{q="Чому Ормер хоче смерті Гарчозуба, а не просто прогнати його?",a="Ормер вважає напад рапторів прямим злочином проти підданих короля Маґні. Невинні дворфи-робітники загинули, виконуючи свою роботу, тож, на думку Ормера, лише смерть може гідно вшанувати пам'ять полеглих.",al={"причина помсти ормера","чому вбити гарчозуба"}},{q="Який доказ вимагає Ормер?",a="Ормер вимагає один з пазурів Гарчозуба, щоб переконатися, що величезного хижака справді вбито.",al={"доказ гарчозуба","кіготь гарчозуба"}},{q="Хто були жертви на розкопках?",a="Дворфійські археологи й робітники, яких Ліга Дослідників послала відкопувати артефакти титанів, — їх застали зненацька й вирізали, коли розкопки заполонили зграї рапторів.",al={"хто загинув у вельґарі","жертви розкопок"}},{q="Чи робить смерть Гарчозуба розкопки безпечними?",a="Смерть Гарчозуба позбавляє зграю найсмертоноснішого хижака й приносить відплату за полеглих, але раптори й далі никають траншеями, тож місце лишається небезпечним і здебільшого покинутим.",al={"чи вельґар безпечний","чи ормер переміг"}}},fp="15,307,27.456.0,23.340.0,17.196.0,27.123.0,68.210.0,30.97.0,44.165.0,50.187.0"}
P.entries["quest:2962"] = {n="Єдині ліки — більше зеленого сяйва",s="Після попередніх безрезультатних випробувань на трогах із поверхні Оззі Тоґлвольт доручає шукачам пригод добути чисті, високопотужні радіоактивні опади просто з Гномреґана. Його кінцева мета — зрозуміти отруйне випромінювання, що спустошило його народ, і створити ліки для уражених прокажених гномів.",h="Після попередніх безрезультатних випробувань на трогах із поверхні Оззі Тоґлвольт доручає шукачам пригод...",kw={"єдині ліки — більше зеленого сяйва","оззі тоґлвольт","радіоактивні опади","гномреґан","харанос","прокажені гноми","завдання"},ang={["faction:Alliance"]="Щоб убезпечити Дун Мороґ і відвоювати Гномреґан, треба зрозуміти смертельні небезпеки, які досі отруюють землю біля самого порога Айронфорджа.",["profession:Engineering"]="Непередбачуваність радіаційного захисту вимагає міцного свинцевого екранування й точних приладів — і показує, якими катастрофічними бувають наслідки, коли інженерія зазнає краху.",["race:Gnome"]="Кожен гном носить у серці горе за втраченим домом. Допомогти Оззі перевірити, чи можна обернути назад жахливу мутацію, — значить торкнутися найпотаємнішої надії гномів урятувати своїх полеглих родичів."},sec={{t="Чистий зразок",b="Попередні досліди Оззі Тоґлвольта за межами міста зазнали невдачі. Опромінені троги, що блукають Дун Мороґом, мали надто мало й надто нечистих решток, і в його лабораторії в Хараносі з'явилося більше запитань, ніж відповідей. Щоб створити справжні ліки для прокажених гномів, Тоґлвольт доходить висновку, що наукова сумлінність вимагає свіжого концентрованого зразка просто з отруйного черева міста."},{t="Просто з джерела",b="Щоб добути досить потужні опади, доведеться ризикнути й спуститися до самого Гномреґана. Нижні глибини довкола Зали Шестерень і Чистої Зони кишать опроміненими потворами, причаєнцями й слизнями, що з'явилися після катастрофічного викиду радіоактивних відходів. Відбирати цей нестійкий слиз у важку свинцеву колбу — небезпечна справа: опади швидко розпадаються, тож зберігати їх украй ризиковано, і часу обмаль."}},faq={{q="Навіщо Оззі радіоактивні опади?",a="Оззі Тоґлвольт намагається синтезувати ліки для гномів-прокажених, чий розум і тіла зруйнували опади, вивільнені під час падіння Гномреґана. Він вірить, що зрозуміти нерозбавлену отруту — перший крок до того, щоб обернути її жахливу дію.",al={"лік оззі тоґлвольта","навіщо зелене сяйво","лік для прокажених гномів"}},{q="Де гравцеві знайти опади?",a="Опади треба зібрати з живих опромінених жахіть, причаюнів і слизів у глибинах Гномреґана, особливо на нижніх рівнях довкола Зали Шестерень і за Чистою Зоною.",al={"де радіоактивні опади","місце опадів гномереґан"}},{q="Чому зразки з трогів на поверхні відкинули?",a="Троги, що никають біля Гномреґана, мали замало зосередженого зараження. Їхні зразки були надто слабкі й нечисті, щоб правити за надійний матеріал для дослідів Оззі з ліками.",al={"чому не троги","що не так із гноґаїном"}},{q="Чому на опади дано обмежений час?",a="Опади вкрай нестійкі й активні. Навіть у свинцевій колекційній колбі мінлива радіація швидко розпадається, тож дослідники мусять доставити її до лабораторії в Хараносі, поки вона не втратила сили.",al={"чому опади псуються","тривалість опадів"}},{q="Хто такі гноми-прокажені, яким Оззі хоче допомогти?",a="Гноми-прокажені — колишні мешканці Гномреґана, що опинилися в пастці, коли відкрили радіаційні клапани проти трогів. Замість загинути, вони мутували, стали хворими й збожеволілими й ворожими до колишніх родичів.",al={"лор прокажених гномів","хто такі прокажені гноми"}},{q="Хто дає це завдання?",a="Завдання дає Оззі Тоґлвольт — гном-дослідник, що працює в Хараносі в Дун Мороґу й присвятив себе подоланню наслідків катастрофи Гномреґана.",al={"хто дає завдання","місце оззі тоґлвольта"}}},fp="32,311,13.392.0,21.398.0,40.263.0,39.202.0,44.196.0,35.217.0,45.219.0,22.174.0"}
P.entries["quest:298"] = {n="Звіт про хід розкопок",s="«Звіт про хід розкопок» — доручення Альянсу: віднести вісті з розкопок у Лох Модані до міста. Шукач Айронбенд просить шукача пригод доставити його останні донесення з розкопок і повторне замовлення вибухівки Джернові Горнгелму в Телсамар.",h="«Звіт про хід розкопок» — доручення Альянсу: віднести вісті з розкопок у Лох Модані до міста.",kw={"звіт про хід розкопок","шукач айронбенд","джерн горнгелм","телсамар","вибуховий порох","ліга дослідників"},ang={["faction:Alliance"]="Відкрите сполучення між Телсамаром і віддаленими заставами означає, що влада Альянсу в горах Лох Модану лишається міцною.",["profession:Mining"]="Рудокопи надто добре знають, як потрібен надійний вибуховий порох, щоб ламати щільну скелю й прокладати ходи в давніх пластах.",["race:Dwarf"]="Для дворфійських шукачів пригод допомога Айронбендові — це підтримка важливих історичних пошуків Ліги Дослідників і захист родичів від ненажерливої навали трогів."},sec={{t="Донесення до Телсамара",b="Археологічні розкопки Шукача Айронбенда в Лох Модані потребують постійної підтримки сусідніх поселень. Видобувати давні реліквії титанів — тяжка праця, яка вимагає кайл, робочих рук і щедрих запасів вибухового пороху, щоб пробиватися крізь уперту скелю. Айронбенд покладається на гінців, які передають його регулярні звіти й замовлення матеріалів Джернові Горнгелму — місцевому зв'язковому експедиції в Телсамарі."},{t="Зниклі боєприпаси",b="Отримавши донесення Айронбенда, Горнгелм дізнається, що на розкопках не дають спокою агресивні троги. Горнгелм погоджується, що постачати порох — хоч розколювати камінь, хоч підривати трогів — добра справа, але нове замовлення Айронбенда одразу його непокоїть. Кілька тижнів тому Горнгелм уже відправив чималий вантаж вибухового пороху, тож тепер гадає, що ж спіткало зниклі боєприпаси на суворих гірських стежках."}},faq={{q="Хто дає вам цей звіт?",a="Звіт дає вам Шукач Айронбенд на Місці розкопок Айронбенда в південно-східних пагорбах Лох Модану. Він керує археологічними розкопками, що там тривають.",al={"хто дає завдання","хто починає звіт про хід розкопок","місце айронбенда"}},{q="Хто такий Джерн Горнгелм?",a="Джерн Горнгелм — дворф, зв'язковий Ліги Дослідників у Телсамарі. Він опікується місцевим постачанням і припасами для археологічних експедицій по всьому Лох Модану.",al={"де джерн горнгелм","хто одержувач","контакт телсамара"}},{q="Навіщо Шукачеві Айронбенду ще вибуховий порошок?",a="Нібито Айронбендові потрібен вибуховий порошок, щоб розчищати суцільну скелю для розкопок. Проте на розкопках кишать ворожі троги, тож вибухівка не менш важлива й для оборони.",al={"навіщо айронбенду порошок","навіщо вибуховий порошок"}},{q="Що сталося з попередньою партією порошку?",a="Джерн Горнгелм кілька тижнів тому відправив партію вибухового порошку, але до розкопок вона так і не дійшла. Її загадкове зникнення свідчить про негаразди на шляхах постачання між Телсамаром і віддаленими розкопками.",al={"куди подівся порошок","зниклий вибуховий порошок"}},{q="Що далі, коли доставиш звіт про хід розкопок?",a="Обміркувавши скрутне становище Айронбенда й нерозгадане зникнення порошку, Горнгелм просить вас доправити звістку про стан експедиції начальству в Айронфорджі.",al={"наступне завдання","що далі","звіт до айронфорджа"}},{q="Чому троги нападають на розкопки?",a="Дворфійські розкопки часто відкривають підземні зали й тривожать лігва трогів. Ці створіння вважають гірників загарбниками на своїй землі й люто кидаються на кожного, хто риє землю.",al={"причина нападу трогів","чому троги ненавидять айронбенда"}}},fp="26,257,23.440.0,17.437.1,29.181.0,21.188.0,51.179.0,49.205.0,50.177.0,45.192.0"}
P.entries["quest:2985"] = {n="Поклик води",s="«Поклик води» знаменує початок єднання шамана зі стихією води — стихією зцілення й мінливості. Учень, який уже довів свою владу над землею та вогнем, отримує від Серна Фаєрвордера в Оргріммарі настанову розшукати відлюдницю Іслен Вотерсір на східному узбережжі Пусток.",h="«Поклик води» знаменує початок єднання шамана зі стихією води — стихією зцілення й мінливості.",kw={"шаман","вода","поклик води","іслен вотерсір","серн фаєрвордер","пустки","раджет","тотеми"},ang={["class:Shaman"]="Цей поклик знаменує вирішальний перехід від руйнівного вогню й непохитної землі до цілющих сил води: ви відкриваєте духовний канал, без якого неможливо ставити цілющі тотеми.",["faction:Horde"]="Шаманів Орди з усього Калімдору — чи то орків, чи тролів, чи тауренів — скеровують до Іслен Вотерсір на узбережжі Пусток, щоб вони пройшли своє єднання з водою."},sec={{t="Зміна стихій",b="Навчання шамана вимагає рівноваги. Пізнавши непохитну стійкість землі й витримавши дику лють вогню, учні мають звернутися до плинної, мінливої природи води. В Оргріммарі шаман-троль Серн Фаєрвордер стежить за духовним зростанням своїх учнів. Коли учень доводить, що здатен панувати над полум'ям і не згоріти в ньому, Серн визнає: дух учня вже досить загартований, щоб шукати науки води."},{t="Відлюдниця Узбережжя Крамарів",b="Щоб пізнати таємниці духів води, шаман мусить вирушити на південь уздовж Річки Південної Люті до Пусток, а звідти пробитися на схід, до узбережжя, трохи далі за галасливий гоблінський порт Раджет. Там, на березі океану, біля туші величезної акули, живе Іслен Вотерсір. На відміну від наставників, що усамітнилися в Долині Духів, Іслен оселилася там, де солоні хвилі невпинно б'ються об сушу, і саме вона є головною провідницею Орди в єднанні з водою."}},faq={{q="Хто дає це завдання?",a="Серн Фаєрвордер, троль-наставник шаманів у Фортеці Ґроммаш в Оргріммарі, дає це завдання, коли ви доведете свою владу над вогнем і землею.",al={"хто дає завдання","хто починає поклик води","серн фаєрвордер"}},{q="Де знайти Іслен Вотерсір?",a="Іслен Вотерсір живе на східному узбережжі Пусток, трохи на південь від Раджета. Йдіть уздовж Річки Південної Люті на південь з Дуротару, повертайте до берега за Раджетом і шукайте її табір біля великої викинутої на берег акули.",al={"де іслен","місце іслен","як знайти іслен вотерсір"}},{q="Чому шаман мусить опановувати стихії в певному порядку?",a="Шаманська традиція вимагає, щоб посвячений крок за кроком будував духовну рівновагу. Заземлена землею й загартована вогнем, душа стає достатньо стійкою, щоб витримати плинну, мінливу чистоту води й не бути нею віднесеною.",al={"порядок стихій","чому вода після вогню","розвиток шамана"}},{q="Чи доступне це завдання іншим класам?",a="Ні. Завдання «Поклик води» — лише для шаманів, які прагнуть здобути прихильність духів води й закликати свій Тотем Води.",al={"чи не шамани можуть це","чи поклик води лише для шамана"}},{q="За яким орієнтиром шукати Іслен?",a="Серн радить мандрівникам шукати величезну акулу, викинуту на берег на південь від Раджета. Іслен оселилася просто поруч із нею.",al={"орієнтир акули","як помітити табір іслен","узбережжя іслен"}},{q="Що буде, коли дістатися Іслен Вотерсір?",a="Speaking to Islen begins the true trials of water, requiring the shaman to journey across Kalimdor and Lordaeron to gather pure drops of water and confront spirits before earning the totem.",al={"наступний крок","що робить іслен","після поклику води"}}},fp="13,300,23.453.0,33.465.0,21.151.0,33.224.0,57.226.0,41.132.0,57.142.0,44.189.1"}
P.entries["quest:299"] = {n="Розкриваючи минуле",s="Шукач Велґар доручає шукачам пригод вирушити на заполонене звірами Місце Розкопок Велґара в Багнокраї й повернути чотири втрачені частини прадавньої таблички — Каменя Ґоаза, — щоб можна було перекласти її загадкові написи.",h="Шукач Велґар доручає шукачам пригод вирушити на заполонене звірами Місце Розкопок Велґара в Багнокраї й...",kw={"розкриваючи минуле","камінь ґоаза","шукач велґар","титани","древні боги","багнокрай"},ang={["faction:Alliance"]="Підтримуючи розкопки Ліги по всьому Багнокраю, ви зміцнюєте присутність Альянсу й рятуєте цінні знання, поки вони не потрапили до диких чи ворожих рук.",["race:Dwarf"]="Ліга Дослідників вважає кожну знайдену реліквію ключем до розгадки походження дворфів, а написи титанів на Камені Ґоаза прямо пов'язані з цією прадавньою спадщиною."},sec={{t="Розбитий камінь",b="Ще до того, як раптори заполонили розкоп у Багнокраї, Шукач Велґар відкопав важливу реліквію — Камінь Ґоаза. Перші спроби розшифрувати давнє письмо дали лише уривчасті згадки про «божественний задум» і «приречене пророцтво». На жаль, ключові частини відкололися в чотирьох місцях, розкидавши найважливіші уривки землею, всіяною скам'янілостями."},{t="Ризикуючи на розкопі",b="Щоб відновити камінь, доведеться обшукати заполонений рапторами розкоп у пошуках чотирьох утрачених уламків: Адоса, Модра, Голма й Неру. Поховані в пухкій землі серед напіввідкопаних реліквій і стережені лютими гостропащами й серпокігтями, ці уламки дістануться лише тому, хто проб'ється крізь верховних хижаків боліт."},{t="Скуті під Землею",b="Складений докупи, Камінь Ґоаза відкриває тонку й загадкову мову титанів. Перекладаючи відновлені знаки, Велґар знаходить моторошний напис: «Древні Боги... Скуті під Землею». Це далеко не проста історична дивовижа — табличка натякає на титанічні битви на зорі світу й темне зло, поховане під корою Азероту."}},faq={{q="Що таке Камінь Ґоаза?",a="Камінь Ґоаза — давня реліквія титанів, яку Шукач Велґар знайшов на розкопках у Багнокраї. На ньому таємничі написи про космічну історію, божественний задум і давніх істот, закутих глибоко під землею.",al={"лор каменя ґоаза","що таке скрижаль ґоаза","уламки скрижалі багнокрай"}},{q="Хто дає завдання «Розкриваючи минуле»?",a="Завдання пропонує Шукач Велґар зі свого спостережного пункту над Місцем Розкопок Велґара на південних пагорбах Багнокраю, куди його прогнали з розкопок дикі раптори.",al={"хто дає розкриваючи минуле","де взяти розкриваючи минуле"}},{q="Які уламки потрібні, щоб скласти скрижаль?",a="Потрібні чотири певні кам'яні уламки: Адос, Модр, Ґолм і Неру. Вони розкидані по пухких горбах землі й давніх урнах на дні кар'єру, що кишить рапторами.",al={"які уламки","назви уламків скрижалі","адос модр голм неру"}},{q="Чому Шукач Велґар не може сам знайти уламки?",a="Велґар — літній дворф-учений. Коли люті раптори раптово вдерлися в кар'єр і захопили його, він мусив відступити, і йому бракує сил самому пробитися крізь зграї.",al={"чому вельґар сам не знайде","чому вельґар просить вас"}},{q="Що розкривають перекладені гліфи титанів?",a="Коли чотири бракуючі частини стають на місце, Велґар розшифровує письмо титанів і читає фразу: «Древні Боги... Закуті під Землею». Це натяк на давніх космічних істот, замкнених під час творення Азерота.",al={"що каже камінь ґоаза","переклад титанів багнокрай","давні боги під землею"}},{q="Чи пов'язане це завдання з іншими експедиціями поблизу?",a="Так. Воно прямо доповнює ланцюжок Ормера Айронбрейда — «Помсту Ормера», де шукачам пригод доручають проріджувати рапторів у тому самому кар'єрі.",al={"завдання біля розкопок","зв'язок з ормером айронбрейдом","зв'язок з помстою ормера"}}},fp="19,236,16.363.0,20.321.0,24.360.1,23.226.1,40.190.0,49.173.0,59.192.0,43.229.1,54.165.0"}
P.entries["quest:2996"] = {n="У пошуках Страгада",s="«У пошуках Страгада» — важливий обряд посвяти для чорнокнижників Орди, які переросли початкове мистецтво прикликання. За настановою Ґан'рула Бладая з тінистих розколин Оргріммара учні вирушають на південь, до Раджета, щоб навчатися в заклинателя-ренегата з людського роду.",h="«У пошуках Страгада» — важливий обряд посвяти для чорнокнижників Орди, які переросли початкове мистецтво...",kw={"чорнокнижник","страгад фарсан","ґан'рул бладай","раджет","тіньова розколина","демони","мисливець скверни"},ang={["class:Warlock"]="Це завдання знаменує ваш перехід до опанування демонічних сутностей середньої сили й перевіряє, чи готові ви підкорити мисливця Скверни, що пожирає магію.",["faction:Horde"]="Те, що майстри Орди охоче посилають учнів до самітника-людини, показує: ковени чорнокнижників діють незалежно від офіційної дипломатії Вождя."},sec={{t="З тіней Оргріммара",b="У темних закутках Тіньової Розколини орк-наставник чорнокнижників Ґан'рул Бладай веде молодих учнів підступним шляхом підкорення сил Нижнього Світу. Та рано чи пізно учень сягає межі, за якою племінних настанов уже замало. Ґан'рул визнає, що непокірніші сутності потребують особливої науки, і спрямовує учнів за міські мури — до того, хто глибше опанував темні таємниці."},{t="Незвичайний союз",b="Наставник, якого обрав Ґан'рул, — Страгад Фарсан, чаклун із людей, що живе у відлюдній вежі над гоблінським портом Раджет. Попри давню ворожнечу між Ордою та людським родом, чорнокнижники існують у світі, де звична вірність фракції мало що важить. Сила, дисципліна й знання ритуалів важать більше за походження, і Страгада значно більше цікавить прихована в учневі ненависть та його хист до підкорення, ніж колір шкіри."}},faq={{q="Чому орк-чорнокнижник посилає мене до людини?",a="Чорнокнижники поділяють прагматичну філософію, що ставить темні знання вище за расову належність. Ґан'рул Бладай визнає, що Страгад Фарсан має рідкісні й грізні знання поглибленої демонології. Коли йдеться про небезпечні закликання, майстерність наставника важить набагато більше за межі фракцій.",al={"чому вчитися в людини","страгад людина чорнокнижник","чому страгад"}},{q="Де знайти Страгада Фарсана?",a="Страгад Фарсан живе на високих кручах просто над гоблінським портом Раджет у Пустках — стоїть біля своєї вежі над гамірними причалами.",al={"місце страгада","де страгад","вежа страгада ретчет"}},{q="Якої сили навчає Страгад?",a="Страгад веде чорнокнижників крізь складні ритуали, потрібні, щоб підкорити мисливця Скверни — ненажерливого демона з Викривленого Нижнього Світу, що пожирає магію. Його уроки заглиблюються в давні окультні тексти, а тоді перевіряють, чи здатні ви поневолити звіра.",al={"що відкриває страгад","що я отримаю від страгада","нагорода пошуків страгада"}},{q="Хто такий Ґан'рул Бладай?",a="Ґан'рул Бладай — знаний орк, наставник чорнокнижників у Тіньовій Розколині під Оргріммаром. Він навчає молодих чорнокнижників Орди основ магії скверни й закликання нижчих слуг.",al={"ґан'рул","ґан'рул бладай","тренер чорнокнижників оргріммара"}},{q="Чи можна почати це завдання інакше?",a="Так. Чорнокнижники-Відступники отримують паралельний виклик з Магічного Кварталу Андерсіті, який спрямовує їх до того самого наставника-людини над Раджетом.",al={"пошуки страгада андерсіті","відступники пошуки страгада","версія андерсіті"}},{q="Чи небезпечний Раджет для чорнокнижників Орди?",a="Раджет належить картелю Стімвідл і є суворо нейтральним портом. Доки ви дотримуєтеся миру й не нападаєте на інших мандрівників у межах міста, гобліни-вишибали вас не чіпатимуть.",al={"чи ретчет безпечний","вартові ретчета ворожі","нейтральний порт"}}},fp="15,266,32.451.0,22.438.0,44.292.0,32.170.0,30.232.1,24.200.0,41.155.0,47.211.0"}
P.entries["quest:2997"] = {n="Фоліант Божественності",s="Фоліант Божественності — виклик, що скликає юних дворфійських паладинів із польової служби в Дун Мороґу до гірського міста Айронфорджа. Азар Стронгхаммер скеровує посвяченого по настанови до Тізи Баттлфордж, яка чекає нагорі, у Залі Таїнств. Так офіційно починаються глибші випробування паладина на службі Святому Світлу.",h="Фоліант Божественності — виклик, що скликає юних дворфійських паладинів із польової служби в Дун Мороґу до...",kw={"фоліант божественності","паладин","тіза баттлфордж","азар стронгхаммер","зала таїнств","дун мороґ"},ang={["class:Paladin"]="Цей обряд посвяти поєднує практичну військову службу серед снігів із глибокою духовною дисципліною, якої чекають від святих воїнів.",["faction:Alliance"]="Спільне шанування Світла єднає дворфійських захисників Каз Модану з їхніми союзниками-людьми в Лордероні та Стормвінді.",["race:Dwarf"]="Дворфійські паладини поєднують загартовану витривалість свого народу з ученням Святого Світла, а осердя цього вчення — святилище Зали Таїнств в Айронфорджі."},sec={{t="Поклик до Високого Престолу",b="Дворфійські посвячені починають вишкіл, захищаючи засніжені селища й шляхи Дун Мороґа, проте сама лише бойова вправність не робить паладином. Азар Стронгхаммер бачить, коли захисник дозрів до глибшого духовного навчання. Замість звичайної муштри він посилає найздібніших у серце Айронфорджа, де під наглядом шанованих святих старійшин міста почнеться їхнє справжнє посвячення."},{t="Зала Таїнств",b="Виклик веде посвяченого до Кварталу містиків, нагору, у тихі покої Зали Таїнств. Там, серед священних реліквій і зосередженого навчання, стоїть Тіза Баттлфордж. Вона — одна з найшанованіших дворфійських поборниць Світла, і саме вона перевіряє, чи готові новоприбулі паладини прийняти самопожертву, милосердя й тяжкий моральний обов'язок свого святого покликання."}},faq={{q="Яка мета цього завдання?",a="Це вступний виклик, що спрямовує паладина-дворфа з віддалених тренувальних угідь Дун Мороґу до Тізи Баттлфордж в Айронфорджі й починає випробування, потрібні, щоб збагнути Святе Світло й здобути силу воскресіння.",al={"навіщо мені це завдання","для чого фоліант божественності","мета фоліанта божественності"}},{q="Хто така Тіза Баттлфордж?",a="Тіза Баттлфордж — досвідчена паладинка-дворф і шанована наставниця, що перебуває на верхньому поверсі Зали Таїнств в Айронфорджі. Вона опікується духовним навчанням молодих паладинів і веде їх крізь священні випробування Фоліанта Божественності.",al={"хто така тіза","тіза баттлфордж лор","хто такий баттлфордж"}},{q="Де розташована Зала Таїнств?",a="Зала Таїнств — у Кварталі містиків на заході Айронфорджа. Це духовний і чародійський осередок дворфійської столиці, де працюють жерці, паладини й маги.",al={"де зала таїнств","знайти залу таїнств","зала таїнств айронфордж"}},{q="Хто посилає паладина з цим дорученням?",a="Азар Стронгхаммер, наставник паладинів у Дун Мороґу, посилає перспективних посвячених до Айронфорджа, коли ті доведуть свою бойову відданість захистові місцевих дворфійських поселень.",al={"хто починає фоліант божественності","хто дає фоліант божественності","азар стронгхаммер"}},{q="Чому паладини-дворфи мусять навчатися в Айронфорджі?",a="Польові наставники на кшталт Азара навчають основ бою, але офіційне вчення, священні тексти й старійшини Святого Світла перебувають у Залі Таїнств. Вищі обряди й духовні догми треба вивчати безпосередньо в старших наставників, як-от Тізи Баттлфордж.",al={"чому їхати в айронфордж","чому вчитися в айронфорджі"}},{q="Що далі після розмови з Тізою Баттлфордж?",a="Розмова з Тізою починає справжні дворфійські випробування Фоліанта Божественності, що вимагають від паладина довести відданість, співчуття й жертовність на службі Світлу.",al={"що далі","наступне завдання після фоліанта божественності","що дає тіза"}}},fp="16,368,23.420.0,21.381.0,34.239.0,24.243.0,39.178.0,37.197.0,45.263.0,50.174.0"}
P.entries["quest:2998"] = {n="Фоліант Божественності",s="«Фоліант Божественності» — важливий виклик для молодих паладинів-людей, що служать Альянсу. З доручення місцевих наставників, як-от Брата Вільгельма в Ґолдширі, новачки вирушають до Собору Світла в Стормвінді на зустріч із Дуторіаном Раллом. Відгукнувшись на цей поклик, вони починають священне випробування, потрібне, щоб опанувати святий дар воскресіння.",h="«Фоліант Божественності» — важливий виклик для молодих паладинів-людей, що служать Альянсу.",kw={"фоліант божественності","брат вільгельм","дуторіан ралл","собор світла","паладин","воскресіння"},ang={["class:Paladin"]="Це завдання — обряд посвяти для паладинів-людей: мить, коли наставники офіційно визнають ваші звершення й відсилають вас до високих командирів Срібної Длані.",["faction:Alliance"]="Набір і випробування святих воїнів у Стормвінді забезпечують Альянсу відданих цілителів і бійців передової в неспокійні часи.",["race:Human"]="Шлях із сільського Лісу Елвінн до величного Собору Світла прив'язує людських захисників до найглибших духовних і бойових установ королівства."},sec={{t="Виклик до столиці",b="Паладини-новачки, що починають свій шлях у Лісі Елвінн, перші дні допомагають місцевим і випробовують бойову вправність на вовках, розбійниках Дефіас і кобольдах. Щойно новачок виявить і бойову дисципліну, і відданість Святому Світлу, наставники на кшталт Брата Вільгельма передають йому особистий виклик. Впливові провідники паладинів помічають перспективних учнів і велять їм лишити місцеві каплиці та з'явитися просто до духовного серця королівства."},{t="Собор Світла",b="На Соборній Площі Стормвінда височіє Собор Світла — найвища святиня для жрецтва королівства й Лицарів Срібної Длані. Тут перебуває Дуторіан Ралл, що наглядає за зростанням тих, хто присягнув Орденові. Ступивши під високі склепіння, новачок постає перед високими за рангом паладинами, щоб отримати офіційні випробування Фоліанта Божественності — завдання, покликані перевірити незламне співчуття, стійкість і жертовну відданість обов'язку."}},faq={{q="Хто посилає мене до Стормвінда в цьому завданні?",a="Брат Вільгельм, наставник паладинів біля Корчми «Лев'яча Гордість» у Ґолдширі, передає цей виклик, коли ви проявите в полі достатньо хисту й сили.",al={"хто дає завдання","брат вільгельм"}},{q="Де знайти Дуторіана Ралла?",a="Дуторіан Ралл — у Соборі Світла на Соборній Площі на північному заході Стормвінда. Більшість днів він навчає паладинів під величними склепіннями собору.",al={"місце дуторіана ралла","де дуторіан ралл","майстер паладинів"}},{q="Чому цей виклик такий важливий для паладинів?",a="Доповідь Дуторіанові Раллу знаменує перехід від простого бойового вишколу до глибокого святого єднання. Вона починає випробування Фоліанта Божественності, які зрештою дарують священну силу повертати полеглих союзників зі смерті силою Світла.",al={"чому це важливо","важливість завдання","випробування паладинів"}},{q="Чи отримують паладини інших рас саме це завдання?",a="Ця версія виклику походить з Лісу Елвінн від Брата Вільгельма й призначена для паладинів-людей. Паладини-дворфи отримують паралельний поклик у Дун Мороґу від власних наставників — вирушити до Айронфорджа.",al={"дворф-паладин","чи дворфи можуть це","чи завдання лише для людей"}},{q="Що буде, коли з'явитися до Дуторіана Ралла?",a="Дуторіан Ралл вітає вас у Стормвінді й одразу пропонує випробування Фоліанта Божественності, що перевіряють ваше співчуття й відданість захистові слабких.",al={"наступне завдання","що буде далі","наступний крок фоліанта божественності"}},{q="Хто такий Дуторіан Ралл?",a="Дуторіан Ралл — один з найвпливовіших паладинів королівства Стормвінд і Лицарів Срібної Длані; він навчає нові покоління святих воїнів у столиці.",al={"хто такий дуторіан","дуторіан ралл лор"}}},fp="16,320,24.502.0,22.485.0,41.172.0,32.199.0,46.247.0,47.225.0,47.185.0,22.199.0"}
P.entries["quest:2999"] = {n="Фоліант Божественності",s="Фоліант Божественності — завдання-посвята для юних дворфійських паладинів, що служать у Дун Мороґу. Брандур Айронгаммер, наставник паладинів у Залі Таїнств Айронфорджа, посилає посвяченого нагору, до шанованої наставниці Тізи Баттлфордж. Це перехід від простого бойового вишколу до глибших духовних обов'язків і священних обітниць Святого Світла.",h="Фоліант Божественності — завдання-посвята для юних дворфійських паладинів, що служать у Дун Мороґу.",kw={"фоліант божественності","паладин","брандур айронгаммер","тіза баттлфордж","спокута","воскресіння"},ang={["class:Paladin"]="Це завдання позначає мить, коли ви переходите від грубої муштри до глибокого духовного тягаря Святого Світла; воно відкриває шлях до випробувань, що дарують силу Спокути.",["race:Dwarf"]="Дворфійські паладини поєднують відданість Святому Світлу з давніми традиціями обов'язку й братерства Каз Модану й відповідають на поклик у гірських залах Айронфорджа."},sec={{t="Поклик до Високого Престолу",b="Перші дні послушники-паладини боронять Анвілмар і Харанос від трогів і морозних тролів, але згодом служба вимагає глибшої відданості. Переконавшись, що посвячений довів свою бойову дисципліну, Брандур Айронгаммер радить йому відпочити від роботи на засніжених перевалах і піднятися по настанови нагору, у його власну Залу Таїнств в Айронфорджі. Там старші паладини наглядають за духовним зростанням ордену."},{t="Настанови Тізи Баттлфордж",b="Тіза Баттлфордж — одна з найшанованіших паладинок серед дворфів Айронфорджа. Саме вона навчає посвячених справжнього тягаря Світла: не лише фехтування й ударів молотом, а й співчуття, справедливості та самопожертви. Із зустрічі з нею починається офіційне вивчення Фоліанту Божественності — священного шляху, що дає паладинові силу воскрешати полеглих."}},faq={{q="Яка мета цього завдання?",a="Це завдання спрямовує молодих паладинів-дворфів від їхнього наставника, Брандура Айронгаммера, до старшої паладинки Тізи Баттлфордж в Айронфорджі. Це перший крок випробувань, потрібних, щоб вивчити Фоліант Божественності й здобути силу духовного воскресіння.",al={"що робить це завдання","початок фоліанта божественності","навіщо це завдання"}},{q="Хто такий Брандур Айронгаммер?",a="Брандур Айронгаммер — дворф, наставник паладинів у Залі Таїнств у Кварталі містиків Айронфорджа. Він опікується молодими паладинами й посилає перспективних посвячених нагору до Тізи Баттлфордж, коли ті готові до більшої священної відповідальності.",al={"хто дає завдання","роль брандура","брандур айронгаммер лор"}},{q="Хто така Тіза Баттлфордж?",a="Тіза Баттлфордж — шанована досвідчена паладинка на верхньому поверсі Зали Таїнств в Айронфорджі. Вона наставляє молодших паладинів у тому, чого Святе Світло справді вимагає від них понад бойову вправність.",al={"де тіза","роль тізи баттлфордж","хто така тіза"}},{q="Куди веде це завдання далі?",a="Розмова з Тізою Баттлфордж починає випробування Фоліанта Божественності. Вони перевіряють відданість паладина, милосердя й готовність захищати й відновлювати життя на службі Світлу.",al={"наступне завдання","що далі","ланцюжок фоліанта божественності"}},{q="Чому паладини-дворфи мусять шукати Фоліант Божественності?",a="Щоб творити диво повернення полеглого союзника до життя, паладин мусить збагнути справжню безкорисливість і духовний обов'язок. Фоліант Божественності веде посвячених крізь офіційні уроки й випробування віри, без яких не спрямувати такої могутньої святої сили.",al={"чому фоліант божественності","лор викуплення паладинів","дворфи викуплення"}},{q="Чи отримують люди таку саму науку в Айронфорджі?",a="Паладини-люди проходять паралельний шлях через Собор Світла в Стормвінді, а не в Айронфорджі. Цей виклик від Брандура Айронгаммера до Тізи Баттлфордж призначений саме для дворфів, що навчаються в Айронфорджі.",al={"чи люди можуть це","чи лише для дворфів","фоліант божественності людей"}}},fp="16,397,25.447.0,30.413.0,34.260.0,26.258.0,24.201.0,32.200.0,56.245.0,53.222.0"}
P.entries["quest:3000"] = {n="Фоліант Божественності",s="Це доручення кличе дворфійських паладинів, що мандрують світом, додому, до Айронфорджа, щоб вони йшли далі шляхом свого священного покликання. Лорд Ґрейсон Шедовбрейкер у Стормвінді скеровує молодих поборників до Тізи Баттлфордж, однієї з найшанованіших наставниць Зали Таїнств. Повернення додому — початок офіційних випробувань за Фоліантом Божественності.",h="Це доручення кличе дворфійських паладинів, що мандрують світом, додому, до Айронфорджа, щоб вони йшли далі...",kw={"фоліант божественності","паладин","ґрейсон шедовбрейкер","тіза баттлфордж","айронфордж","срібна длань"},ang={["class:Paladin"]="Це важливий обряд посвяти для дворфійських паладинів: він веде їх до вивчення Фоліанту Божественності й опанування дару воскресіння.",["faction:Alliance"]="Спільний вишкіл і взаємна повага між паладинами Стормвінда й наставниками Айронфорджа свідчать про тісний духовний союз дворфів і людей.",["race:Dwarf"]="Це завдання пов'язує ваші пригоди в людських землях з обов'язком перед Каз Моданом: воно кличе вас назад, до родового осідку в Айронфорджі, вчитися у власних старійшин."},sec={{t="Поклик додому",b="Дворфійські паладини часто допомагають королівству Стормвінд і мандрують людськими землями, але їхнє духовне й бойове коріння залишається в Каз Модані. Лорд Ґрейсон Шедовбрейкер бачить, коли польовий вишкіл дворфа зайшов досить далеко, і радить йому повернутися в серце Айронфорджа. Там його власний народ наглядатиме за глибокими духовними обов'язками, яких чекають від повноправного лицаря Срібної Длані."},{t="Зала Таїнств",b="Повернувшись до гірської столиці, паладин вирушає до Кварталу містиків. Глибоко в Залі Таїнств, на її верхньому ярусі, живе Тіза Баттлфордж. Вона — шанована наставниця молодого покоління дворфійських паладинів і готує їх нести тягар Святого Світла через священні випробування, записані у Фоліанті Божественності."}},faq={{q="Чому Лорд Ґрейсон Шедовбрейкер посилає мене назад до Айронфорджа?",a="Лорд Ґрейсон визнає, що ви довели свою загартованість у полі, але молоді паладини-дворфи мають пізнавати глибші засади й випробування Святого Світла безпосередньо від власного народу, під проводом Тізи Баттлфордж.",al={"чому до айронфорджа","чому ґрейсон відсилає","чому до тізи"}},{q="Хто така Тіза Баттлфордж?",a="Тіза Баттлфордж — одна з найшанованіших паладинок-дворфів Айронфорджа. Вона працює на верхньому поверсі Зали Таїнств, наставляє паладинів, що зростають, і проводить випробування, які перевіряють їхню відданість Світлу.",al={"тіза баттлфордж","хто така тіза","тренер паладинів тіза"}},{q="Де знайти Тізу Баттлфордж?",a="Вона в Залі Таїнств, що в Кварталі містиків Айронфорджа. Підніміться нагору в святилищі — там її й знайдете.",al={"де тіза","місце тізи баттлфордж","як знайти тізу"}},{q="Що таке Фоліант Божественності?",a="Фоліант Божественності охоплює святе вчення й суворі випробування, які паладини мусять пройти, щоб опанувати Святе Світло, — зокрема силу воскресіння й безкорисливу відданість полеглим союзникам.",al={"значення фоліанта божественності","що за фоліант","книга паладина"}},{q="Чи можуть паладини-люди виконати цю версію завдання?",a="Ні. Цей виклик спрямовує саме паладинів-дворфів повернутися до наставників рідної землі, а паладини-люди проходять свої випробування безпосередньо в Лорда Ґрейсона Шедовбрейкера й Дуторіана Ралла в Стормвінді.",al={"чи люди-паладини можуть це","чи лише для дворфів"}},{q="Що буде, коли з'явитися до Тізи Баттлфордж?",a="Щойно ви представитеся Тізі, вона дасть вам офіційні дворфійські випробування Фоліанта Божественності, що перевіряють, чи готові ви володіти рятівною силою Світла.",al={"що далі","наступне завдання після фоліанта божественності","після розмови з тізою"}}},fp="16,370,14.432.0,21.365.0,62.228.0,24.213.0,34.136.0,29.198.0,48.226.0,49.177.0"}
P.entries["quest:3001"] = {n="У пошуках Страгада",s="«У пошуках Страгада» — доручення, яке Карендін Галґар в Андерсіті дає чорнокнижникам Орди. Галґар посилає учня за Велике море, на запорошені пагорби над Раджетом, де людський чаклун тримає ключі до глибших і небезпечніших викликів. Це перехід від основ мистецтва тіней до вимогливого мистецтва виклику мисливця Скверни.",h="«У пошуках Страгада» — доручення, яке Карендін Галґар в Андерсіті дає чорнокнижникам Орди.",kw={"у пошуках страгада","карендін галґар","страгад фарсан","андерсіті","мисливець скверни","чорнокнижник"},ang={["class:Warlock"]="Це завдання — вирішальний обряд посвяти приблизно на тридцятому рівні вашої сили: крок від угод із дрібними бісами й блукачами Порожнечі до влади над хижим мисливцем Скверни.",["faction:Horde"]="Знавцям темних мистецтв із Відступників і орків доводиться притлумити звичну ворожість до людей і вирушити аж до нейтрального Раджета, щоб повчитися в живого чаклуна.",["race:Undead"]="Карендін Галґар особисто відсилає учнів-Відступників з Андерсіті, доводячи, що навіть вірні Сильвані охоче вчаться в живих майстрів, щоб поповнити свій арсенал."},sec={{t="Майстер за морем",b="Карендін Галґар, наставник чорнокнижників-Відступників, що наглядає за темними мистецтвами в Магічному Кварталі Андерсіті, бачить, коли новачок переріс основи. Замість того щоб тримати учнів у межах руїн Лордерону, він велить їм розшукати Страгада Фарсана. Галґар застерігає: хоч Страгад — жива людина, він аж ніяк не слабкий, і поводитися з ним як із ворогом не можна. Для чорнокнижників прагнення влади над демонами зазвичай важить більше за кордони рас і фракцій."},{t="Оглядовий майданчик над Раджетом",b="Страгад працює у відносному нейтралітеті високо на кручах над гоблінським портом Раджет у Пустках. Зі свого місця біля кам'яної сторожової вежі він зі стриманою зневагою дивиться на метушливих моряків, найманців і купців унизу й глузує з їхнього блаженного незнання Викривленого Нижнього Світу. Страгада не бентежать недовіра чи тліюча ненависть в очах знавців темних мистецтв з Орди, що приходять до нього; навпаки, він вважає цю неприховану злобу могутнім паливом, яке можна перекувати на темну владу."}},faq={{q="Чому чорнокнижник з Андерсіті посилає мене до людини?",a="Чорнокнижники часто відкладають фракційні чвари, коли йдеться про рідкісні й могутні темні знання. Карендін Галґар визнає, що Страгад Фарсан має особливе вміння у вищих демонічних закликаннях, якого сам Галґар дати не може. У гонитві за демонічною силою знання важать набагато більше за походження наставника.",al={"чому людина-тренер","чому слати до людини","карендін шле до страгада"}},{q="Де саме Страгад Фарсан?",a="Страгад Фарсан живе в Пустках, на високих скелях просто над гоблінським портом Раджет. Він стоїть біля кам'яної вежі над затокою й гамірними причалами внизу.",al={"місце страгада","де страгад","як знайти страгада"}},{q="Якої сили навчає Страгад?",a="Страгад веде досвідчених чорнокнижників крізь складні ритуали підкорення вищих демонів з Викривленого Нижнього Світу, що веде просто до небезпечних випробувань, потрібних, щоб закликати мисливця Скверни й керувати ним.",al={"чому вчить страгад","для чого це завдання","завдання мисливця скверни"}},{q="Чи союзник Страгад Альянсу?",a="Хоч Страгад і людина, він діє з нейтральної гоблінської землі в Раджеті й не пов'язаний з Великим Альянсом. Він незалежний практик, що вільно має справу з чорнокнижниками і Орди, і Альянсу, якщо ті здатні пережити його науку.",al={"чи страгад союзник альянсу","фракція страгада","чи страгад дружній"}},{q="Що буде, коли дістатися Страгада?",a="Коли ви прибудете, Страгад перевірить вашу рішучість і доручить вам зібрати розкидані частини й складники Фоліанта Кабали — так починається довга подорож, що відкриває ритуал закликання мисливця Скверни.",al={"що після страгада","фоліант кабали","наступне завдання"}},{q="Чому Страгад вітає ненависть у своїх учнях?",a="Демонічна магія живиться сильними почуттями, пануванням і силою волі. Страгад вважає ненависть зосередженою, потужною дисципліною, яку можна спрямувати, щоб скорити хаотичних істот Нижнього Світу, які інакше пожерли б недисциплінованого закликача.",al={"чому страгад любить ненависть","ненависть в очах"}}},fp="15,355,23.489.0,23.504.0,50.323.0,40.199.0,38.209.0,36.252.0,36.217.0,48.235.0"}
P.entries["quest:301"] = {n="Доповідь у Айронфордж",s="Це доручення веде шукача пригод з Телсамара в Лох Модані до серця Айронфорджа з важливими новинами з Місця розкопок Айронбенда. Доповідь про хід розкопок, доставлена Шукачеві Стормпайку в Залі Дослідників, запускає розслідування: куди подівся вибуховий порох і чому застопорилися розкопки в передгір'ях.",h="Це доручення веде шукача пригод з Телсамара в Лох Модані до серця Айронфорджа з важливими новинами з Місця...",kw={"шукач стормпайк","шукач айронбенд","ліга дослідників","телсамар","лох модан","вибуховий порох"},ang={["faction:Alliance"]="Це доручення показує, як далеко сягає логістика Альянсу: віддалені дослідницькі табори в гірських долинах пов'язані з військовим і науковим проводом Айронфорджа.",["race:Dwarf"]="Для дворфів продиратися крізь бюрократію Ліги Дослідників і терпіти легендарний норов клану Стормпайк — знайомий обряд посвяти в залах рідної столиці."},sec={{t="Гонець для Ліги",b="Археологічні експедиції по всьому Каз Модану тримаються на грошах, припасах і нагляді Ліги Дослідників. Коли на розкопках Шукача Айронбенда на півдні Лох Модану закінчуються вибухові припаси, його наглядачі не можуть просто роздобути ще на місці. Джерн Горнгелм у корчмі Телсамара доручає шукачеві пригод віднести письмову доповідь Айронбенда через гірські перевали просто Шукачеві Стормпайку до штабу Ліги."},{t="Норов Стормпайків",b="Шукач Стормпайк — утілення тієї суворої, запальної рішучості, якою славиться його клан. Він сидить у величній Бібліотеці й Залі Дослідників в Айронфорджі й чекає від розкопок Ліги швидких і відчутних результатів. Прочитавши донесення, Стормпайк лютує: Айронбенд ані словом не згадує про величезну партію вибухового пороху, відправлену кілька тижнів тому. Отже, постачання в Лох Модані дало небезпечний збій."}},faq={{q="Чому цей звіт треба нести аж до Айронфорджа?",a="Ліга Дослідників суворо контролює розподіл цінних ресурсів на кшталт вибухового порошку. Польові розкопки не можуть замовляти небезпечну вибухівку без офіційного дозволу старших шукачів, що сидять в осередку — Залі Дослідників.",al={"чому нести звіт в айронфордж","чому до стормпайка","причина звіту в айронфордж"}},{q="Хто такий Шукач Стормпайк?",a="Він — високопоставлений урядовець Ліги Дослідників в Айронфорджі. Член гордого клану Стормпайк, він сумно відомий запальною вдачею й нетерпимістю до розкопок, що стоять, і до зниклого майна.",al={"хто такий стормпайк","шукач стормпайк лор"}},{q="Куди подівся перший вибуховий порошок Айронбенда?",a="Партію вибухового порошку відправили ще кілька тижнів тому, але Айронбенд і словом не згадує, що отримав її. Це одразу наводить на думку, що віз на дорогах Лох Модану перехопили троги чи бандити.",al={"що сталося з порошком","зниклий вибуховий порошок","де порошок"}},{q="Де в Айронфорджі знайти Шукача Стормпайка?",a="Шукач Стормпайк — в Асамблеї Дослідників, відомій також як Бібліотека чи Зала Дослідників, у північно-східному крилі Айронфорджа.",al={"місце стормпайка","де стормпайк","місце ліги дослідників"}},{q="Хто дає вам звіт у Телсамарі?",a="Джерн Горнгелм, що мешкає в Корчмі «Міцний Лагер» у Телсамарі, — посередник, який передає звіти й повідомлення між віддаленим табором Айронбенда й міським керівництвом.",al={"хто починає звіт до айронфорджа","роль джерна горнгелма"}},{q="Що буде, коли Стормпайк прочитає звіт?",a="Розлючений через неврахований порох і застій у роботі, Стормпайк наказує гравцеві зібрати нову партію вибухового порошку й доставити її просто Шукачеві Айронбенду.",al={"що далі","наступне завдання після звіту в айронфордж"}}},fp="19,331,24.453.0,20.452.1,57.245.0,28.214.0,45.220.0,52.159.0,38.182.0,46.183.1"}
P.entries["quest:302"] = {n="Порох для Айронбенда",s="Порох для Айронбенда — завдання Альянсу з доставки, що пов'язує штаб Ліги Дослідників в Айронфорджі з Лох Моданом. Отримавши офіційний дозвіл Шукача Стормпайка, шукачі пригод вирушають до Телсамара, щоб простежити за важливою партією вибухового пороху для розкопок Айронбенда.",h="Порох для Айронбенда — завдання Альянсу з доставки, що пов'язує штаб Ліги Дослідників в Айронфорджі з Лох...",kw={"порох","шукач айронбенд","джерн горнгелм","телсамар","лох модан","ліга дослідників"},ang={["faction:Alliance"]="Безпека доріг Лох Модану життєво важлива для єдності Альянсу між Айронфорджем і східним прикордонням.",["profession:Mining"]="Вибуховий порох — незамінне знаряддя дворфійського ремесла: ним однаково користуються і шахтарі, і копачі, що прагнуть розколоти найглибшу скелю.",["race:Dwarf"]="Для дворфів порох для розкопок — не просто постачання: він допомагає святій справі — розкрити таємницю походження їхнього народу."},sec={{t="Бюрократія й вибуховий порох",b="Археологічні розкопки в горах Каз Модану не обходяться без важкої вибухівки. Коли в експедиції Шукача Айронбенда на півдні Лох Модану скінчилися вибухові припаси, звістку надіслали проводу Ліги в Айронфордж. Шукач Стормпайк швидко схвалив запит і звелів гінцеві домовитися з Джерном Горнгелмом у Телсамарі — головному вузлі постачання долини."},{t="Віз, що не дочекався",b="Попередні обози з припасами на шляху через Лох Модан то зникали, то потерпали від нападів місцевих трогів, тож Стормпайк чітко наказав гінцеві особисто охороняти віз із порохом. Та бюрократія й довга дорога грають проти Ліги. Поки гонець дістається до корчми «Міцний Лагер» у Телсамарі, Джерн Горнгелм уже відправляє віз під охороною Гулдара й двох дворфів-носіїв, і гінцеві доводиться щодуху наздоганяти його."}},faq={{q="Навіщо Айронбендові везуть вибуховий порошок?",a="Шукач Айронбенд керує важливими дворфійськими археологічними розкопками на півдні Лох Модану. Щоб відкопувати артефакти титанів і давні кам'яні реліквії, треба підривати щільну скелю, а його загін вичерпав запаси, поки троги дедалі лютішають.",al={"навіщо порошок","вибуховий порошок айронбенда","для чого порошок"}},{q="Хто такий Шукач Стормпайк?",a="Шукач Стормпайк — старший офіцер дворфійської Ліги Дослідників у Залі Дослідників в Айронфорджі. Він розглядає польові запити, затверджує важливе обладнання й опікується постачанням великих розкопок по всьому Каз Модану.",al={"роль стормпайка","хто дав завдання"}},{q="Хто такий Джерн Горнгелм?",a="Джерн Горнгелм — координатор постачання й соратник горян у Телсамарі, у Лох Модані. Він готує припаси й організовує обози, що вирушають на небезпечніші околиці долини.",al={"місце джерна горнгелма","де джерн горнгелм"}},{q="Чому для цієї партії попросили особистий супровід?",a="Попередні вантажі для розкопок так і не дійшли. Лох Модан заполонили троги, що вилазять з пагорбів і розкопок, тож шляхи постачання вздовж головного тракту стають дедалі небезпечнішими.",al={"чому супроводжувати порошок","напади трогів на вози"}},{q="Що буде, коли прибудете до Телсамара?",a="Джерн Горнгелм уже відправив віз у дорогу з Гулдаром і носіями Міраном і Саеном. Вам доведеться йти південним шляхом, щоб наздогнати їх, поки не сталося лиха.",al={"чи я проґавив віз","де вантаж"}},{q="Яке місце це завдання посідає в історії Ліги Дослідників?",a="Це ланка-доставка, що пов'язує перший запит з розкопок через центральну владу в Айронфорджі й назад у поле через Телсамар, аби вберегти роботу експедиції.",al={"ланцюжок айронбенда","лінія розкопок"}}},fp="18,298,31.403.0,18.467.1,46.241.0,28.241.0,21.210.0,52.221.0,42.185.1,61.215.0"}
P.entries["quest:303"] = {n="Війна з Темним Залізом",s="На північному краю Багнокраю Мотлі Ґармасон відчайдушно бореться, щоб відвоювати Дун Модр у клану Темного Заліза. Після того як ворожі диверсанти зруйнували Міст Тандол і захопили містечко, горяни Айронфорджа ледве тримають хиткий рубіж, чекаючи на підкріплення, яке може так і не прийти.",h="На північному краю Багнокраю Мотлі Ґармасон відчайдушно бореться, щоб відвоювати Дун Модр у клану Темного...",kw={"війна з темним залізом","мотлі ґармасон","дун модр","міст тандол","темне залізо","багнокрай"},ang={["faction:Alliance"]="Зруйнування Мосту Тандол і падіння Дун Модра перерізають суходільний шлях між північними союзниками Стормвінда й південними королівствами.",["profession:Engineering"]="Точність, з якою диверсанти Темного Заліза застосували особливу вибухівку, щоб розтрощити прадавню дворфійську кладку, свідчить про моторошну майстерність у руйнуванні споруд.",["race:Dwarf"]="Для дворфів-Бронзбірдів утрата Дун Модра — гірке приниження й пряма загроза суверенітетові Каз Модану, що вимагає помсти давнім ворогам."},sec={{t="Фронт біля північної брами",b="Колись Дун Модр був гордою твердинею Айронфорджа, що стерегла південний кінець Мосту Тандол — велетенського мосту між Каз Моданом і Лордероном. Коли диверсанти й підривники Темного Заліза висадили арку мосту, вони перерізали шлях Альянсу й швидко взяли твердиню. Мотлі Ґармасон і жменька вцілілих захисників зуміли відступити рівно настільки, щоб облаштувати спостережний табір, але без негайних контрударів уся північна брама ризикує назавжди опинитися під владою Темного Заліза."},{t="Виграти час для резервів",b="Оскільки дворфійські полки розкидано по Калімдору й далеких полях битв Альянсу, невеликий загін Мотлі здебільшого покинуто напризволяще. Його розвідники намагаються подати Айронфорджу знак про допомогу, але зв'язок обірвався, а обіцяних резервів не видно. Щоб виграти час і зруйнувати ворожі укріплення, Мотлі наказує завдавати точних ударів просто в руїнах Дун Модра, щоб прорідити інженерів, землекопів і передові загони Темного Заліза, перш ніж вони просунуться далі на південь, у Багнокрай."}},faq={{q="Хто такий Мотлі Ґармасон?",a="Мотлі Ґармасон — офіцер горян Айронфорджа, що командує рештками гарнізону Дун Модра. Він стоїть одразу за захопленим містечком і керує розвідкою й партизанськими ударами по окупантах з Темного Заліза.",al={"мотлі ґармасон","хто такий мотлі","командир дун модру"}},{q="Чому Дун Модр такий важливий для Айронфорджа?",a="Дун Модр стереже південне підніжжя Мосту Тандол. Це єдиний суходільний шлях, що сполучає Каз Модан з Аратійським нагір'ям і північним Лордероном, тож хто тримає Дун Модр, той фактично контролює весь наземний рух і постачання між цими краями.",al={"чому дун модр важливий","важливість дун модру","дун модр лор"}},{q="Чому дворфи Темного Заліза воюють у Багнокраї?",a="Клан Темного Заліза здавна прагне підточити своїх родичів Бронзбірдів і послабити Альянс. Вдершись у Багнокрай і зруйнувавши Міст Тандол, вони перерізали Айронфорджу шляхи постачання на північ і відкрили ворожий другий фронт у тилу Альянсу.",al={"чому темне залізо в багнокраї","темне залізо багнокрай","причина війни темного заліза"}},{q="Що сталося з Мостом Тандол?",a="Підкопники й підривники Темного Заліза заклали потужну вибухівку в опорні арки Мосту Тандол і тяжко пошкодили міст, щоб відрізати підкріплення з Айронфорджа від Лордерону, а тоді захопили Дун Модр.",al={"міст тандол знищено","хто підірвав міст","вибух мосту тандол"}},{q="Де резервні сили Айронфорджа?",a="Військо Айронфорджа розпорошене по кількох походах за кордоном і по обороні рідних земель. Розвідникові Ґармасона, Роґґо, ніяк не вдається налагодити надійний зв'язок з верховним командуванням, тож застава біля Дун Модра тримає рубіж з тими місцевими союзниками, яких вдається знайти.",al={"резерви айронфорджа","де підкріплення","резерв роґґо"}},{q="Що буде, коли відкинути Темне Залізо в Дун Модрі?",a="Знищивши піхоту й саперів, ви виграєте дорогоцінний час, але розвідані Роґґо показують, що напад на Міст Тандол допомагав планувати Кам Діпф'юрі, який сидить у В'язниці Стормвінда, і Мотлі просить вас принести голову Діпф'юрі.",al={"наступне завдання після війни з темним залізом","завдання лють глибока","що після війни з темним залізом"}}},fp="17,310,28.523.0,28.532.0,23.229.0,42.247.0,51.264.0,34.223.0,39.269.0,59.235.1"}
P.entries["quest:304"] = {n="Похмуре завдання",s="Після нищівного нападу Темного Заліза на Дун Модр і Міст Тандол Лонґбрейд Похмурий прагне помститися за полеглих родичів і вояків. Він доручає сміливим мандрівникам вистежити й убити невловимого чорнокнижника Темного Заліза Балґараса Мерзенного й принести його вухо як доказ.",h="Після нищівного нападу Темного Заліза на Дун Модр і Міст Тандол Лонґбрейд Похмурий прагне помститися за...",kw={"похмуре завдання","лонґбрейд похмурий","балґарас мерзенний","дун модр","темне залізо","міст тандол"},ang={["class:Warlock"]="Балґарас Мерзенний орудує зловісною магією скверни, спрямовуючи різанину захисників Дун Модра, — і показує, на які небезпечні цілі Темне Залізо обертає своє ремесло.",["faction:Alliance"]="Міст Тандол — головний суходільний шлях між Каз Моданом і Лордероном, тож усунення диверсантів Темного Заліза — стратегічне першочергове завдання для всього Альянсу.",["race:Dwarf"]="Для дворфів Айронфорджа зрада й насильство клану Темного Заліза в Дун Модрі — особиста образа й свіжа рана в давній міжусобиці кланів."},sec={{t="Руїни Дун Модра",b="Північ Багнокраю стала ареною запеклих боїв між горянами Айронфорджа й лазутчиками з клану Темного Заліза. Під час облоги містечко Дун Модр захопили, а західну частину Мосту Тандол зруйнували. Лонґбрейд Похмурий утратив у тому нападі не лише багатьох вірних вояків, а й рідного брата, тож сповнений рішучості відплатити ворогові тією самою монетою."},{t="Боягузливий командир",b="Розвідка, яку провели такі розвідники, як Роґґо, показала, що загоном Темного Заліза в Дун Модрі командує чорнокнижник, відомий як Балґарас Мерзенний. Замість зустрітися з ворогами віч-на-віч, Балґарас ховається, наказуючи своїм воякам утілювати його темні задуми. Лонґбрейд сподівається, що смерть Балґараса зламає хребет силам Темного Заліза й дасть уцілілим з Айронфорджа змогу вбезпечити важливий прохід на північ."}},faq={{q="Хто такий Балґарас Мерзенний?",a="Балґарас Мерзенний — чорнокнижник з Темного Заліза, що командує силами, які захопили Дун Модр на півночі Багнокраю. Лонґбрейд Похмурий називає його боягузом: він уникає відкритого бою, посилаючи натомість натовпи вояків Темного Заліза тримати край.",al={"балґарас","хто такий балґарас","лідер темного заліза дун модр"}},{q="Хто такий Лонґбрейд Похмурий?",a="Лонґбрейд Похмурий — дворфійський командир, що отаборився біля руїн Дун Модра. Він утратив брата й багатьох солдатів, коли сили Темного Заліза захопили поселення й зруйнували західний перехід Мосту Тандол.",al={"лонґбрейд","лонґбрейд похмурий","хто дає завдання дун модр"}},{q="Навіщо Лонґбрейдові вухо Балґараса?",a="Балґарас — невловна ціль, що раз у раз ховається від відкритого бою, тож Лонґбрейд вимагає речового доказу смерті чорнокнижника, щоб переконатися: загрозу справді усунуто.",al={"навіщо вухо","вухо балґараса"}},{q="Що сталося з Мостом Тандол?",a="Західний проліт Мосту Тандол зруйнували дворфи Темного Заліза під час раптового наступу на Дун Модр, перерізавши важливий шлях між Багнокраєм і Аратійським нагір'ям.",al={"міст тандол зруйновано","чому міст тандол зламаний"}},{q="Де ховається Балґарас?",a="Балґарас засів у захоплених укріпленнях і руїнах довкола Дун Модра, ховаючись за спинами своїх солдатів, а не виходячи на відкриті болота.",al={"де балґарас","знайти балґараса"}},{q="Що буде, коли Балґараса вбито?",a="Коли Балґараса не стане, Лонґбрейд вірить, що з розладнаними рештками вояків Темного Заліза буде значно легше впоратися, поки не прибув інший командир із підкріпленням.",al={"після похмурого завдання","що далі дун модр"}}},fp="11,288,21.409.0,20.441.0,25.240.0,26.217.0,39.180.0,34.200.0,25.155.0,37.171.0"}
P.entries["quest:305"] = {n="У пошуках розкопної команди",s="«У пошуках розкопної команди» починається з Таррела Роквівера в Багнокраї, якого гнітить раптова мовчанка дружини, Меррін. Вона працює на престижному Місці Розкопок Велґара на сході й уже два тижні не надсилає звичних листів, тож Таррел боїться, що експедицію спіткало лихо. Мандрівникам доручають вирушити в болота, знайти розкоп і з'ясувати, чи вона в безпеці.",h="«У пошуках розкопної команди» починається з Таррела Роквівера в Багнокраї, якого гнітить раптова мовчанка...",kw={"у пошуках розкопної команди","таррел роквівер","меррін роквівер","місце розкопок велґара","ліга дослідників","багнокрай"},ang={["faction:Alliance"]="Підтримувати дворфійські опорні пункти й дослідницькі експедиції на болотах конче потрібно, щоб уберегти Багнокрай від диких небезпек, що насуваються.",["race:Dwarf"]="Ліга Дослідників пишається тим, що відкопує давню історію, тож біда родичів на Місці Розкопок Велґара — нагальна справа для кожного мандрівного дворфа."},sec={{t="Чоловіків страх",b="Перебуваючи серед мокрих просторів Багнокраю, Таррел Роквівер звик до постійних листів від дружини, Меррін. Працюючи на дворфійському розкопі, відомому як Місце Розкопок Велґара, Меррін щотижня надсилала звістки про їхню роботу. Коли минуло два повні тижні без жодного слова, Таррел переконався, що табір спіткала біда. Оскільки офіційні дворфійські сили розтягнуто до межі, він покладається на мандрівних розвідників, що наважаться ризикнути серед болотяних небезпек і перевірити, чи копачі ще дихають."},{t="Розкоп Велґара",b="Місце Розкопок Велґара — звичайна дворфійська спроба відкопати прадавні реліквії титанів і створену ними історію, поховані в багнюці Багнокраю. Та, вгризаючись у доісторичні пласти на дикій землі, копачі часто наражаються на неприборканих звірів і ворожі підземні загрози. Щоб дістатися розкопу, треба йти на схід, далеко від відносно безпечних головних доріг, — туди, де досі чигає те, що обірвало листи копачів."}},faq={{q="Хто такий Таррел Роквівер?",a="Таррел Роквівер — стривожений дворф з Багнокраю. Наляканий тим, що раптом перестали приходити листи від його дружини Меррін, яка працює на східних розкопках, він приймає мандрівних шукачів пригод за офіційних розвідників, посланих з'ясувати, чому табір мовчить.",al={"таррел роквівер","хто дає завдання","хто дає пошуки розкопної команди"}},{q="Хто така Меррін Роквівер?",a="Меррін Роквівер — дворфійська археологиня із загону розкопок Велґара на схід від Гавані Менетіл у Багнокраї. Вона регулярно писала чоловікові, аж поки несподівані події раптом не обірвали зв'язок.",al={"меррін роквівер","дружина таррела","хто така меррін"}},{q="Де Місце Розкопок Велґара?",a="Місце Розкопок Велґара лежить на схід від Гавані Менетіл і на південний захід від Дун Модра в Багнокраї, серед скелястих хребтів далеко від головного шляху.",al={"місце розкопок велґара","де знайти меррін","де розкопки вельґара"}},{q="Чому Меррін перестала писати?",a="Раптову тишу з розкопок спричинила нова загроза, що постала там і відрізала дворфів-дослідників від звичних шляхів гінців і буденного табірного життя.",al={"чому меррін перестала писати","чому припинилися листи","що сталося з командою"}},{q="Хто такий «Лонґбрейд», якого згадує Таррел?",a="Лонґбрейд — дворфійський очільник, що пообіцяв послати розвідників перевірити загін розкопок Велґара, якщо обірветься зв'язок, тож Таррел вважає, що кожного вправного шукача пригод, який прийшов допомогти, послав саме Лонґбрейд.",al={"хто такий лонґбрейд","розвідник лонґбрейд"}},{q="Чи безпечно підходити до розкопок?",a="Ні. Розкопки — у небезпечній глушині Багнокраю, і те, що перервало щотижневі донесення загону, становить безпосередню загрозу для кожного, хто прийде на місце.",al={"чи безпечні розкопки","чи вельґар небезпечний"}}},fp="32,409,17.523.0,15.470.0,25.266.0,25.231.0,37.153.0,36.176.0,43.236.0,40.174.0"}
P.entries["quest:306"] = {n="У пошуках розкопної команди",s="Це доручення несе до Гавані Менетіл звістку про страшний напад доісторичних звірів на Місце Розкопок Велґара. Меррін Роквівер поспіхом пише листа, щоб заспокоїти стривоженого чоловіка, Таррела, і розповідає, як експедицію заполонили звірі.",h="Це доручення несе до Гавані Менетіл звістку про страшний напад доісторичних звірів на Місце Розкопок Велґара.",kw={"у пошуках розкопної команди","меррін роквівер","таррел роквівер","гавань менетіл","раптори","лист"},ang={["faction:Alliance"]="Шляхи постачання й прикордонні починання по всьому Багнокраю досі небезпечно вразливі для диких звірів і вимагають від мандрівників Альянсу постійної пильності.",["race:Dwarf"]="Лихо на розкопі болюче вдаряє по дворфійських археологічних амбіціях і показує, які небезпеки чигають на дослідників Короля Маґні далеко від безпечного Айронфорджа."},sec={{t="Послання з руїн",b="Коли рештки розкопної команди знайдено біля гребеня над розкопом, де вони ховалися, Меррін Роквівер поспіхом складає звіт. Відкопування рідкісних артефактів поряд із величезними доісторичними скам'янілостями обернулося смертю, коли зграї місцевих плямистих рапторів налетіли на копачів. Раптова лютість звірів забрала життя більшості команди, а вцілілих відрізала від світу."},{t="Гірке полегшення",b="Повернення до Гавані Менетіл приносить Таррелові Роквіверу похмуру розраду. Знання, що його дружина й щонайменше двоє товаришів уціліли завдяки мужності захисника на ім'я Ормер, заспокоює його, хоча загибель стількох колег тяжко лягає на прикордонний дух містечка."}},faq={{q="Що сталося із загоном розкопок у Багнокраї?",a="Поки дворфійська експедиція відкопувала рідкісні артефакти й велетенські давні кістки, на неї зненацька налетіли плямисті раптори, що боронять свою землю. Більшість копачів загинула, і лише кілька вцілілих опинилися в пастці на кручах над розкопками.",al={"що сталося з розкопками","катастрофа розкопок багнокрай","чому розкопки провалилися"}},{q="Хто врятував Меррін Роквівер?",a="Меррін завдячує відважному захисникові на ім'я Ормер, який відбивався від рапторів і вивів її разом із Шукачем у відносну безпеку на хребет, коли нижня частина табору впала.",al={"хто врятував меррін","ормер роквівер","хто такий ормер"}},{q="Хто такий Таррел Роквівер?",a="Таррел Роквівер — чоловік Меррін, що лишився в Гавані Менетіл. Стривожений тим, що з розкопок немає звісток, він шукав мандрівників, які б з'ясували, що з нею.",al={"хто такий таррел","місце таррела роквівера"}},{q="Де розташовані розкопки?",a="Розкопки лежать у глибині суходолу, на півдні Багнокраю, на схід від Гавані Менетіл, біля підніжжя гірських хребтів Айронфорджа.",al={"де розкопки","місце розкопок вельґара"}},{q="Що шукала експедиція?",a="Під проводом дворфійських шукачів загін відкопував рідкісні підземні артефакти й великі доісторичні скам'янілості, поховані в болотах.",al={"що шукала експедиція","артефакти розкопок"}},{q="Чи є інші вцілілі, крім Меррін?",a="Так, Меррін згадує, що разом із нею від рапторів урятувалися Ормер і головний Шукач, тож відомо про трьох уцілілих.",al={"хто ще вижив","вцілілі розкопок"}}},fp="32,245,24.370.0,15.277.0,53.256.0,28.174.0,25.183.0,30.142.0,36.148.0,40.145.0"}
P.entries["quest:3065"] = {n="Проста Табличка",s="«Проста Табличка» — вступний обряд переходу для воїнів-початківців, що входять у Долину Випробувань. Вручена вам після того, як ви довели свою вправність проти тутешніх звірів, вона спрямовує вас до Франґа — місцевого ветерана, якому доручено обертати сиру силу на бойову дисципліну.",h="«Проста Табличка» — вступний обряд переходу для воїнів-початківців, що входять у Долину Випробувань.",kw={"проста табличка","воїн","франґ","ґорнек","долина випробувань","плямисті вепри"},ang={["class:Warrior"]="Цей виклик — ваш найперший крок на шлях воїна в Дуроторі; він веде вас просто до Франґа вчитися основних стійок і ударів.",["faction:Horde"]="Орда покладається на постійний потік загартованих бійців передової, щоб убезпечити хиткі кордони Дуротару від кентаврів, шипогривів і людських зайд.",["race:Troll"]="Тролі Темного Списа, що навчаються в долині, можуть почути грубуваті зауваги Франґа щодо їхньої любові до списів замість орчих сокир, хоч він поважає все, що вбиває."},sec={{t="Поклик до зброї",b="Коли ви доведете, що здатні дати раду Плямистим Вепрам долини, Ґорнек вручає вам пергамент, позначений саме для вас. У суворому середовищі Дуротару Орда не лишає своїх бійців надовго без настанов. Табличка — запрошення розшукати Франґа, наставника воїнів, що стоїть біля Лігва."},{t="У затінку Лігва",b="Франґ ховається в затінку одразу біля Лігва, спостерігаючи, як новобранці стікаються з червоних чагарників. Він оцінює новачків досвідченим оком, готовий передати основи — чи то махати важкою сокирою, чи то орудувати списом, — щоб кожен новий солдат міг боронити крихкі поселення молодої Орди."}},faq={{q="Що таке Проста Табличка?",a="Це вступне розпорядження, яке вручають молодим воїнам у Долині Випробувань. Ґорнек передає його, щоб спрямувати новобранців до Франґа — місцевого наставника воїнів.",al={"проста табличка","що за табличка","записка воїна"}},{q="Хто надсилає табличку?",a="Послання походить від Франґа — досвідченого наставника воїнів, що відпочиває біля Лігва й пильно видивляється нових бійців.",al={"хто написав табличку","хто надіслав просту табличку"}},{q="Де знайти Франґа?",a="Франґ стоїть біля Лігва в Долині Випробувань, ховаючись від пустельного сонця під скельними навісами.",al={"місце франґа","де франґ","знайти тренера воїнів"}},{q="Чому Франґ згадує списи й сокири?",a="Франґ зауважує, що новобранці Орди б'ються по-різному. Орки полюбляють важкі рубаки на кшталт дворучних сокир, а тролі й інші бійці часто воліють списи й легшу древкову зброю — і те, і те добре служить у бою.",al={"цитата франґа про списи","чому списи"}},{q="Чи отримують це завдання інші класи?",a="Ні. Просту Табличку дають саме воїнам. Інші класи отримують власний пергамент, руну чи сувій, що спрямовує їх до відповідних наставників.",al={"чи проста табличка лише для воїнів","класові завдання долини випробувань"}},{q="Навіщо потрібне Лігво?",a="Лігво — захищений комплекс печер у Долині Випробувань, де подалі від пекучої спеки й блукаючих звірів збираються наставники, припаси й новобранці, що відпочивають.",al={"що таке лігво","лігво дуротар"}}},fp="13,277,17.338.0,26.318.0,26.170.0,21.131.0,23.121.0,39.213.0,32.159.0,31.164.0"}
P.entries["quest:307"] = {n="Брудні лапи",s="«Брудні лапи» — доручення Горянина Стормпайка врятувати цінне спорядження із заполоненої Шахти Срібного Потоку. Руда в шахті вичерпалася, і Ліга Шахтарів обернула її на склад, але потім тунелі заполонили кобольди. Дворфійська влада хоче повернути свої міцні інструменти, перш ніж горяни підуть на нищівний штурм.",h="«Брудні лапи» — доручення Горянина Стормпайка врятувати цінне спорядження із заполоненої Шахти Срібного...",kw={"брудні лапи","горянин стормпайк","шахта срібного потоку","ліга шахтарів","кобольди","лох модан"},ang={["faction:Alliance"]="Дворфійських оборонців ледве вистачає на весь Каз Модан, тож очищені склади постачання — запорука того, що важливі споруди лишаться відкритими для Альянсу.",["profession:Mining"]="Рудокопи оцінять вартість добірного дворфійського спорядження — і трагедію справних інструментів, що іржавіють у лапах печерної напасті.",["race:Dwarf"]="Для дворфів бачити, як грубі кобольди паплюжать вироби Ліги Шахтарів, — образа, що вимагає швидкої відплати й гострої сталі."},sec={{t="Вичерпаний склад",b="Шахта Срібного Потоку, захована в пагорбах північного Лох Модану на схід від Станції Алґаз, давно віддала останні срібні жили. Дворфійська Ліга Шахтарів не покинула підземний комплекс, а перетворила сухі штольні на надійний склад запасного гірничого спорядження, кайл і припасів. Міцні підземні тунелі в Каз Модані — природні комори, якщо тільки їх стережуть і замикають від дикої місцини."},{t="Лапи на складі",b="Дворфійська пильність у Лох Модані ослабла, і кобольди скористалися нагодою пролізти в штольні. Їх приваблюють темні тунелі й блискучі залізні інструменти, тож ця напасть швидко облаштувала тут собі нору. Горянин Стормпайк рветься повести загін воїнів у тунелі й винищити кобольдів, але важкі чоботи й розмашисті удари потрощили б ящики. Шукачеві пригод доведеться прокрастися чи пробитися всередину й винести припаси ліги, перш ніж почнеться штурм."}},faq={{q="Чому в копальні лишили спорядження, якщо вона вже вичерпалася?",a="Коли руда скінчилася, Ліга Шахтарів перетворила Шахту Срібного Потоку на центральний склад. Дворфійські підземні тунелі — надійні, сухі сховища, де можна тримати громіздке знаряддя й припаси, доки вони не знадобляться деінде.",al={"чому спорядження в шахті срібного потоку","чому знаряддя в шахті","склад ліги гірників"}},{q="Чому Горянин Стормпайк сам не зачистить копальню?",a="Стормпайк має наказ чекати. До того ж Ліга Шахтарів хоче спершу забрати своє спорядження: вартові, що вдеруться у вузькі темні штреки, в запалі бою, найпевніше, потрощать делікатне знаряддя в ящиках.",al={"чому стормпайк не піде сам","чому горяни чекають","причина завдання стормпайка"}},{q="Де розташована Шахта Срібного Потоку?",a="Шахта — на півночі Лох Модану, на схід від Станції Алґаз і на південний захід від Каменетесної Греблі.",al={"місце шахти срібного потоку","де шахта срібного потоку","де брудні лапи"}},{q="Чому кобольдів так цікавить дворфійське знаряддя?",a="Кобольди — нав'язливі підземні збирачі. Вони жадають металевих кайл, лопат, свічок і готових залізних виробів, що полегшують їм вічне риття, тож склад дворфійського знаряддя для них — непереборна принада.",al={"чому кобольдам знаряддя","крадіжка інструментів кобольдами","кобольди шахта срібного потоку"}},{q="Чи небезпечно досліджувати Шахту Срібного Потоку самому?",a="Вузькі проходи й густі зграї кобольдів роблять копальню небезпечною. Горянин Стормпайк прямо попереджає, що шукачам пригод-одинакам краще взяти із собою товаришів.",al={"чи брудні лапи складні","складність шахти срібного потоку","чи можна соло брудні лапи"}},{q="Кому належать припаси в копальні?",a="Припаси належать Лізі Шахтарів Айронфорджа — ремісничій гільдії, що відповідає за видобуток каменю й руди та за підземні ресурси по всьому дворфійському королівству.",al={"чиє спорядження","скрині ліги гірників","хто керує лігою гірників"}}},fp="11,367,16.453.0,17.509.0,56.227.0,57.229.0,40.104.0,50.217.0,53.179.0,41.167.0"}
P.entries["quest:308"] = {n="Відвернути увагу Джарвена",s="У льоху Ґуральні Тандербрю вартовий Джарвен Тандербрю опиняється серед барил, яких йому заборонено торкатися. Жадаючи скуштувати родинного ремесла, він просить подорожнього шукача пригод принести кухоль Громового Елю, щоб загострити розум на чергуванні.",h="У льоху Ґуральні Тандербрю вартовий Джарвен Тандербрю опиняється серед барил, яких йому заборонено торкатися.",kw={"відвернути увагу джарвена","джарвен тандербрю","вартовий","громовий ель","льох","ґуральня тандербрю","харанос"},ang={["class:Rogue"]="Відволікти вартового міцним трунком — давній трюк ремесла, навіть якщо Джарвен сам радо просить його відволікти.",["race:Dwarf"]="Кожен дворф розуміє муку стояти на варті біля діжок легендарного елю, не маючи права на жоден ковток."},sec={{t="Спраглий вартовий на чергуванні",b="Джарвену Тандербрю доручено стерегти глибокі запаси Ґуральні Тандербрю в Хараносі. Хоч він і оточений найкращим стаутом у Дун Мороґу, він працює під суворим родинним наказом не прикладатися до запасів на варті. Спокуса виявляється надто сильною, і він залучає подорожніх, щоб ті принесли йому пінту міцного Громового Елю з кранів нагорі."},{t="Сумнівний гострильний камінь",b="Джарвен наполягає, що добрий трунок лише загострить його чуття й зміцнить його варту. Чи мудро потурати вартовому на чергуванні — питання відкрите, та серед витривалих дворфів Дун Мороґу мало хто дорікне комусь із Тандербрю за бажання скуштувати всесвітньо відоме вариво власної рідні."}},faq={{q="Хто такий Джарвен Тандербрю?",a="Джарвен — член славетної родини Тандербрю, що стоїть унизу, у льоху Ґуральні Тандербрю в Хараносі, і стереже бочки із запасами.",al={"джарвен","хто такий джарвен","вартовий у підвалі"}},{q="Чому Джарвенові треба, щоб хтось приніс йому елю?",a="Родина суворо заборонила Джарвенові пити з льоху, поки він на варті. Щоб обійти правила й не відкорковувати запечатаних бочок, він просить чужинця принести йому свіжий кухоль згори.",al={"чому джарвену потрібен ель","завдання елю джарвена","чому принести випивку"}},{q="Де взяти Громовий Ель?",a="Громовий Ель подають просто нагорі, у головній залі Ґуральні Тандербрю в Хараносі, — його продають корчмар і шинкарі.",al={"де взяти громовий ель","де громовий ель","купити громовий ель"}},{q="Де розташована Ґуральня Тандербрю?",a="Ґуральня — гамірна головна корчма Хараноса, що тулиться в засніженому серці Дун Мороґу, трохи нижче в горах від Айронфорджа.",al={"винокурня хараноса","місце льоху тандербрю","де джарвен"}},{q="Чому ель Тандербрю такий славетний?",a="Стаут і елі клану Тандербрю легендарні по всьому Каз Модану й за його межами: виняткова міцність, смак і справжній дворфійський удар.",al={"репутація тандербрю","що таке громовий ель"}},{q="Чи наробить біди, якщо Джарвен сп'яніє?",a="Джарвен запевняє, що ель гострить йому розум, а не притуплює, — хоча він безперечно відвертає його увагу від тих, хто нишпорить у нижньому сховищі.",al={"наслідки п'яного джарвена","що буде після відволікання джарвена"}}},fp="18,257,23.385.0,19.276.0,26.163.0,46.215.0,27.133.0,44.142.0,33.151.0,44.149.0"}
P.entries["quest:3082"] = {n="Гравірована Табличка",s="«Гравірована Табличка» — вступне завдання мисливця, яке дають у Долині Випробувань після перших випробувань. Воно спрямовує майбутніх тролів-мисливців з'явитися до наставниці мисливців Джен'шан, щоб почати офіційний вишкіл у нетрях.",h="«Гравірована Табличка» — вступне завдання мисливця, яке дають у Долині Випробувань після перших випробувань.",kw={"гравірована табличка","мисливець","джен'шан","ґорнек","долина випробувань","темний спис"},ang={["class:Hunter"]="Це завдання знаменує ваш офіційний вступ до лав мисливців Орди і встановлює ваш зв'язок із дикою природою та місцевою наставницею.",["faction:Horde"]="Обмін між Джен'шан і молодими новобранцями показує, як Орда поєднує відмінні культурні сили орків і тролів задля спільного виживання.",["race:Orc"]="Для молодих орків отримати табличку означає вчитися витонченого скрадання й вистежування в нетрях у союзників із Темного Списа, доповнюючи традиційну воїнську міць.",["race:Troll"]="Джен'шан пишається тим, як мисливські знання Темного Списа допомогли Орді вкоренитися на Калімдорі, і підтверджує життєво важливу роль тролячих традицій у виживанні їхніх союзників."},sec={{t="Поклик на полювання",b="Коли мисливці-новачки доведуть свою першу вправність проти тутешніх вепрів Лігва, їх перестріває Ґорнек із вирізьбленим посланням. Кам'яна табличка несе знак Джен'шан — умілої тролиці-мисливиці, що стоїть неподалік. Ґорнек передає її як знак, що молодий мисливець виявив достатньо завзяття, аби привернути увагу досвідчених майстрів виживання, і це позначає перехід від простого грубого виживання до дисциплінованого вишколу в нетрях."},{t="Поділитися виживанням",b="Коли ви з'являєтеся до Джен'шан, тролиця-наставниця розповідає про глибоку історію між орками й тролями в Орді. Орки мали славетні традиції воїнів і шаманів, а тролі Темного Списа принесли давні вміння скрадання, вистежування й виживання, що допомогли оркам вистояти на Азероті. Джен'шан бачить у вишколі нових мисливців тривалий обмін знаннями про виживання, що зближує союзні народи через спільну повагу до полювання."}},faq={{q="Хто надсилає Гравіровану Табличку?",a="Вирізьблений камінь надсилає наставниця мисливців Джен'шан, а вручає його вам Ґорнек, коли ви проявите себе в Долині Випробувань.",al={"хто надіслав гравіровану табличку","відправник таблички","хто дав табличку"}},{q="Де знайти Джен'шан?",a="Джен'шан — у північній частині Долини Випробувань у Дуротарі, серед інших класових наставників біля Лігва.",al={"місце джен'шан","де джен'шан","знайти джен'шан"}},{q="Чому тут орків-мисливців навчають тролі?",a="Джен'шан каже, що Орда звернулася до тролів по мисливську науку, коли виборювала виживання в Азероті. Орки й так знали шлях воїна й шамана, і обидва народи й далі обмінюються вміннями.",al={"чому тролі вчать мисливців-орків","троль тренер мисливців","мисливці темних списів"}},{q="Що буде, коли віддати цю табличку?",a="Джен'шан бере вас в учні й обіцяє навчати основних прийомів, пострілів і способів виживання, потрібних мисливцям Орди, у міру того як ви набиратиметеся досвіду.",al={"що далі після таблички","нагорода гравірованої таблички","продовження джен'шан"}},{q="Що треба виконати, перш ніж отримати цю табличку?",a="Спершу треба виконати для Ґорнека перше завдання — «Ріжуться зуби», — убивши плямистих вепрів, щоб довести свою базову витривалість.",al={"передумова таблички","як відкрити гравіровану табличку","вимоги до гравірованої таблички"}},{q="Чи може це завдання виконати будь-який клас?",a="Ні, це завдання саме для мисливців-новачків, що починають свій шлях у Долині Випробувань. Інші класи отримують від Ґорнека власні виклики до наставників.",al={"хто може отримати гравіровану табличку","клас гравірованої таблички","чи лише для мисливців"}}},fp="13,237,21.438.0,23.469.0,28.147.0,28.135.0,45.195.0,42.172.0,62.121.0,34.168.0"}
P.entries["quest:3083"] = {n="Зашифрована Табличка",s="Зашифрована Табличка — виклик, який Ґорнек вручає майбутнім розбійникам, що навчаються в Долині Випробувань. Написане шифром послання спрямовує злодюжок-новачків до Рваґа — таємного агента в Лігві, який керує вишколом розбійників і зв'язками з Розтрощеною Рукою.",h="Зашифрована Табличка — виклик, який Ґорнек вручає майбутнім розбійникам, що навчаються в Долині Випробувань.",kw={"зашифрована табличка","розбійник","рваґ","ґорнек","розтрощена рука","лігво","долина випробувань"},ang={["class:Rogue"]="Ця табличка — ваше офіційне посвячення в таємні операції Дуротару: вона зводить вас із першим наставником, Рваґом, і знайомить із непомітним впливом Розтрощеної Руки.",["race:Orc"]="Хоч традиційна орча культура шанує відкритий бій на полі битви, орчі розбійники відіграють незамінну роль розвідників і лазутчиків у сучасній Орді.",["race:Troll"]="Розбійники Темного Списа поєднують чуття слідопитів джунглів із мистецтвом клинка, якого навчають наставники в Лігві, і так утверджують свою тиху користь серед союзників-орків."},sec={{t="Шифрований виклик",b="Щойно посвячуваний доведе свою вправність проти тутешньої звірини, Ґорнек вручає йому Зашифровану Табличку, доставлену саме для нього. Замість простої мови послання замкнене в шифрі — випробування й пересторога, що личать тим, хто практикує мистецтво скрадання, отрут і хитрощів. Воно запрошує новобранця спуститися в Лігво й зустріти Рваґа — наставника, відповідального за вишкіл розбійників, крадіїв і злодюжок для Орди."},{t="Тінь Руки",b="Розгадавши вказівки й увійшовши в Лігво, посвячувані знаходять Рваґа — агента, пов'язаного з Розтрощеною Рукою. Хоч він запевняє новоприйнятих розбійників, що гільдія не диктуватиме їм кожен подих, він застерігає: Рука спитає з нього, якщо учень не впорається. У молодій нації, оточеній ворогами, Орда значною мірою покладається на мовчазних розвідників і спритних злодюжок, щоб збирати відомості й усувати загрози з тіні."}},faq={{q="Навіщо потрібна Зашифрована Табличка?",a="Це вступний виклик для розбійників-новачків у Долині Випробувань, що спрямовує їх до класового наставника, Рваґа, у Лігві.",al={"що робить табличка","призначення зашифрованої таблички","навіщо шифр"}},{q="Хто вручає табличку гравцеві?",a="Ґорнек, наглядач випробувань у долині, дає вам табличку, коли ви пройдете перше бойове випробування — убивство плямистих вепрів.",al={"хто дає зашифровану табличку","хто дає завдання таблички","табличка горнека"}},{q="Де знайти Рваґа?",a="Рваґ — глибоко в Лігві, темному комплексі печер біля північного урвища Долини Випробувань.",al={"місце рваґа","де рваґ","знайти рваґа"}},{q="Що за «Рука», яку згадує Рваґ?",a="Рваґ має на увазі Розтрощену Руку — таємну мережу й гільдію вбивць, шпигунів і розбійників на службі Орди Вождя Тралла.",al={"що за рука","розтрощена рука рваґ","хто така рука"}},{q="Чому табличку написано шифром?",a="Шифр гарантує, що делікатні справи розбійників і особи їхніх кураторів лишаються прихованими від цікавих очей, а заразом перевіряє, чи вміє новачок поводитися з таємними посланнями.",al={"чому шифр","чому табличка зашифрована","код розбійників"}},{q="Чи може будь-який клас узятися за це завдання?",a="Ні. Зашифровану Табличку призначено саме для тролів-розбійників, які починають свій шлях у Долині Випробувань.",al={"чи лише для розбійників","чи воїни можуть зашифровану табличку","обмеження класу таблички"}}},fp="16,270,15.438.0,22.457.0,44.149.0,38.142.0,24.122.0,37.134.0,49.177.0,35.115.0"}
P.entries["quest:3084"] = {n="Табличка з Рунними Письменами",s="Табличка з Рунними Письменами — послання-виклик, яке отримують майбутні шамани, що навчаються в Долині Випробувань. Надіслана Шікріком, вона запрошує здібних посвячуваних почати офіційне навчання єднання з духами й володіння стихійними силами землі, вогню, води й повітря.",h="Табличка з Рунними Письменами — послання-виклик, яке отримують майбутні шамани, що навчаються в Долині...",kw={"табличка з рунами","шаман","шікрік","ґорнек","стихії","долина випробувань","тралл"},ang={["class:Shaman"]="Ця табличка — ваше офіційне посвячення на шаманський шлях; вона доручає вам урівноважувати сили стихій і бути маяком провідництва предків.",["faction:Horde"]="Шаманізм — моральний і духовний хребет нової Орди, компас честі й рівноваги на суворому прикордонні.",["race:Orc"]="Табличка відображає сучасне повернення орків до шаманізму предків, яке обстоює Тралл, і відхід від темної чорнокнижницької спадщини демонічного минулого.",["race:Troll"]="Тролі Темного Списа, що практикують шаманізм, знаходять спільну мову з орками-наставниками на кшталт Шікріка, поєднуючи єднання з предками зі спільними стихійними традиціями Орди."},sec={{t="Поклик до духів",b="Коли шамани-початківці доведуть свою першу дисципліну на запорошених тренувальних землях Долини Випробувань, Ґорнек вручає їм вирізьблену кам'яну табличку. Руни на ній — запрошення від Шікріка, тутешнього наставника шаманів, знак, що посвячуваний готовий дивитися далі за простий фізичний бій і дослухатися до глибших течій природного світу."},{t="Духовне провідництво в новій Орді",b="Шаманізм посідає священне місце у відродженій Орді. Як учить Шікрік, шамани черпають свою міць із чотирьох стихійних сил, а силу — від духів предків. За прикладом Вождя Тралла від шаманів чекають, що вони будуть духовними провідниками й опорою мудрості для своїх громад і даруватимуть захист поселенням, які вкорінюються по всьому Дуротару."}},faq={{q="Що таке Табличка з Рунними Письменами?",a="Це кам'яна табличка з написом, яку Ґорнек передає шаманам-новачкам у Долині Випробувань. На ній — виклик від наставниці шаманів Шікрік, що закликає молодого шукача пригод почати справжнє навчання духовних і стихійних мистецтв.",al={"табличка з рунними письменами","предмет таблички","табличка шамана"}},{q="Хто така Шікрік?",a="Шікрік — наставниця шаманів біля входу до Лігва в Долині Випробувань. Вона навчає нових шаманів-орків і тролів опановувати стихії й розуміти свій обов'язок духовних провідників в Орді.",al={"шікрік","хто така шікрік","тренер шаманів долини випробувань"}},{q="Чому Шікрік, говорячи з новими шаманами, згадує Тралла?",a="Вождь Тралл очолив відродження шаманства предків після демонічного розбещення Старої Орди. Шікрік ставить Тралла за взірець обов'язку шамана: зберігати гармонію стихій і водночас вести й захищати свій народ.",al={"чому шікрік згадує тралла","шікрік про тралла"}},{q="Де знайти Шікрік?",a="Шікрік стоїть одразу біля входу до Лігва, у східній частині Долини Випробувань, готова навчати шаманів-новачків перших прийомів.",al={"де шікрік","знайти шікрік"}},{q="Хто видає табличку?",a="Табличку вручає Ґорнек, що наглядає за першими випробуваннями новоприбулих у Долині Випробувань, коли посвячений доведе свою базову загартованість.",al={"хто дає табличку","табличка горнека"}},{q="Якої головної філософії навчає Шікрік?",a="Шікрік наголошує, що силу шаман черпає з вогню, землі, води й повітря, а витривалість і рішучість — від духів предків. Від шаманів чекають, що вони даватимуть мудрість і захист кожному містечку чи загону, до якого пристануть.",al={"філософія шікрік","вчення шаманів"}}},fp="21,286,21.360.0,37.362.0,34.234.0,15.221.0,60.244.0,25.150.0,25.154.0,40.242.0"}
P.entries["quest:3085"] = {n="Освячена Табличка",s="Простий виклик, який отримують жерці-початківці в Долині Випробувань після першої перевірки сили. Табличка з написом посилає молодих служителів духів до Кен'джая — тутешнього наставника жерців-тролів, який відкриває їм глибше єднання з духами.",h="Простий виклик, який отримують жерці-початківці в Долині Випробувань після першої перевірки сили.",kw={"жрець","кен'джай","долина випробувань","табличка","духи","тролі"},ang={["class:Priest"]="Це завдання знаменує перехід від буденних випробувань долини до справжнього духовного навчання під проводом Кен'джая біля Лігва.",["faction:Horde"]="Поки Орда облаштовується в Дуротарі, містики дбають, щоб духовні обряди й воля духів лишалися осердям зростання молодої держави.",["race:Troll"]="Табличка підкреслює духовні традиції Темного Списа: звернення до духів предків і лоа замість догматичних учень чужоземних жрецтв."},sec={{t="Послання від Кен'джая",b="Довівши свою стійкість у сутичках із місцевими вепрами під наглядом Ґорнека, молоді жерці, що навчаються в Долині Випробувань, отримують різьблений камінь, відомий як Освячена Табличка. Послання, передане через Ґорнека, несе знак Кен'джая — містика з племені Темного Списа, що стоїть біля входу до Лігва й наглядає за новачками, покликаними на шлях віри та духовної магії."},{t="Єднання з духами",b="На відміну від Святого Світла, якому служать люди й дворфи за морем, жрецтво серед тролів Темного Списа в Орді зосереджене на єднанні з духами та лоа. Кен'джай вітає новоприбулих послушників у Дуротарі нагадуванням, що їхня сила народжується з духовної дисципліни, і обіцяє навчити їх вищих обрядів лише тоді, коли їхній зв'язок із духами зміцніє."}},faq={{q="Що таке Освячена Табличка?",a="Це послання з написом від троля, наставника жерців Кен'джая, для молодих жерців, що навчаються в Долині Випробувань. Ґорнек тримає її в себе, доки посвячений не доведе в долині свої базові здібності.",al={"що таке освячена табличка","предмет освяченої таблички","лор таблички"}},{q="Хто такий Кен'джай?",a="Кен'джай — троль з Темного Спису, наставник жерців, що стоїть біля Лігва в Долині Випробувань. Він навчає молодих посвячених єднання з духами й веде їх, поки ті вчаться володіти і цілющими, і тіньовими духовними мистецтвами.",al={"кен'джай","хто такий кен'джай","тренер кен'джай"}},{q="Чому жрець починає з боїв із плямистими вепрами?",a="Кожен посвячений у Долині Випробувань, хай яким буде його покликання, мусить довести базову самостійність і вміння вижити, перш ніж наставники-фахівці витрачатимуть на нього час.",al={"чому вбивати вепрів","зв'язок з гострими зубами"}},{q="Чим жрецтво Кен'джая відрізняється від Святого Світла?",a="Жерці Темного Спису звертаються до духів і лоа, а не моляться Святому Світлу людських і дворфійських церков. Кен'джай наголошує, як важливо зберігати прихильність і гармонію з цими невидимими силами.",al={"лор троля-жерця","жерці орди","духи проти світла"}},{q="Де Лігво?",a="Лігво — печерне поселення в Долині Випробувань на півдні Дуротару, осередок наставників і наглядачів випробувань, які опікуються новобранцями Орди.",al={"лігво дуротар","де лігво","місце кен'джая"}},{q="Чи можуть орки стати жерцями через це завдання?",a="Ні. У Долині Випробувань лише тролі Темного Спису мають духовні традиції, потрібні, щоб навчатися на жерців у Кен'джая. Орча культура натомість спирається на шаманство й магію чорнокнижників.",al={"жерці-орки","чи орки можуть бути жерцями","орк освячена табличка"}}},fp="15,268,22.369.0,26.376.0,28.205.0,15.231.0,51.194.0,57.198.0,17.169.0,43.190.0"}
P.entries["quest:3086"] = {n="Гліфічна Табличка",s="Гліфічна Табличка — вступне класове завдання в Долині Випробувань для магів-новачків Орди. Її передає Ґорнек після того, як новобранець доведе свою силу, і вона скеровує юних чарівників до Май'ї, наставниці магів-тролів біля входу до Лігва.",h="Гліфічна Табличка — вступне класове завдання в Долині Випробувань для магів-новачків Орди.",kw={"маг","май'а","гліфічна табличка","долина випробувань","таємна магія"},ang={["class:Mage"]="Це завдання — ваше офіційне вітання в лавах магів Орди: воно знайомить вас із наставницею долини й наголошує на дисципліні розуму, потрібній, щоб тримати в шорах сиру магію.",["race:Orc"]="У традиційній культурі орків магів немає зовсім, тож це навчання — радше нагода для інших рас Орди, як-от тролів Темного Списа, відточити своє ремесло на тренувальних землях Дуротару.",["race:Troll"]="Для тролів Темного Списа, що стають на шлях таємної магії, навчання в Май'ї відображає те, як плем'я дедалі більше опановує впорядковане чаклунство поряд зі своїми традиційними духовними обрядами."},sec={{t="Послання в різьбленому камені",b="Довівши свою стійкість у сутичках із тутешньою звіриною в Долині Випробувань, маги-початківці отримують різьблену табличку, яку передає Ґорнек. Послання походить від Май'ї, наставниці магів у долині: вона кличе учня знайти її біля входу до Лігва, щойно той буде готовий узятися за справжнє вивчення таємної магії."},{t="Небезпеки незримого",b="Зустрівши учня, Май'а не гає часу на церемонії й одразу переходить до суворої правди про таємну силу. Визнаючи, що маги здатні змінювати світ, вона попереджає: найбільша загроза для них — не ворожі воїни й не чужі раси, а незрима, розбещувальна спокуса самої магії. Вона радить смирення й терпіння, застерігаючи, що неприборкане чаклунство легко обманює чародія, змушуючи переоцінювати власну майстерність."}},faq={{q="Хто вручає гравцеві Гліфічну Табличку?",a="Ґорнек, перший, хто дає завдання в долині, передає вам табличку, коли ви виконаєте попереднє доручення — проріджуєте плямистих вепрів у Долині Випробувань.",al={"хто дає гліфічну табличку","де взяти гліфічну табличку","початок гліфічної таблички"}},{q="Хто така Май'а?",a="Май'а — тролиця з Темного Спису, наставниця магів, що стоїть одразу біля входу до Лігва в Долині Випробувань. Вона навчає магів-початківців Орди перших заклять і суворо попереджає про небезпеку чародійської скверни.",al={"хто така май'а","май'а лор","тренер магів-тролів"}},{q="Де знайти Май'а?",a="Май'а стоїть одразу біля входу до Лігва, праворуч від тунелю, у північній частині Долини Випробувань.",al={"де май'а","місце май'а","знайти май'а"}},{q="Про що Май'а попереджає щодо магії?",a="Май'а попереджає, що магія має природний розбещувальний вплив, який нелегко спинити. Вона наголошує, що маги мають остерігатися невидимих спокус і хибних уявлень про владу, які несе чародійство, а не тілесних ворогів на кшталт орків, ельфів чи дворфів.",al={"попередження май'а","лор скверни магії","що каже май'а"}},{q="Чи отримують Гліфічну Табличку інші класи?",a="Ні. Гліфічна Табличка призначена суто для магів-новачків. Інші класи отримують окремі вступні виклики — руни, сувої чи знаки — до своїх наставників.",al={"чи інші класи гліфічна табличка","чи лише для магів"}},{q="Що треба виконати, щоб отримати цю табличку?",a="Спершу треба виконати для Ґорнека перше завдання — «Ріжуться зуби», — вбиваючи плямистих вепрів на рудих рівнинах Долини Випробувань.",al={"вимоги гліфічної таблички","передумова гліфічної таблички"}}},fp="14,242,28.358.0,25.438.0,46.162.0,14.230.0,24.134.0,42.256.0,44.192.0,53.144.0"}
P.entries["quest:3087"] = {n="Гравірований Пергамент",s="Гравірований Пергамент — вступне завдання, що скеровує молодих мисливців-орків у Долині Випробувань до їхньої наставниці Джен'шан. Записку передає Ґорнек після першого бойового хрещення новачка, і вона відкриває двері до особливого вишколу в дикій природі та мистецтва виживання в Дуротарі.",h="Гравірований Пергамент — вступне завдання, що скеровує молодих мисливців-орків у Долині Випробувань до їхньої...",kw={"мисливець","джен'шан","гравірований пергамент","долина випробувань","дуротар"},ang={["class:Hunter"]="Ця записка — перше офіційне визнання вас мисливцем Орди: вона скеровує вас до Джен'шан, щоб відточити влучність і зрозуміти дику природу.",["faction:Horde"]="Мисливці розвідують кордони й годують табори; рання наука ремесла дбає про те, щоб молода держава Дуротар була нагодована й захищена.",["race:Orc"]="Мисливці-орки покладаються на таких наставників, як Джен'шан, щоб пристосувати традиційні кланові способи полювання до посушливих скель і смертоносних звірів Дуротару.",["race:Troll"]="Для новобранців Темного Списа навчання в Джен'шан зберігає живими давні традиції вистежування здобичі в джунглях, принесені з Островів Відлуння."},sec={{t="Поклик дикої землі",b="Довівши свою стійкість у сутичках із тутешніми плямистими вепрами, мисливці, що починають шлях у Долині Випробувань, отримують гравірований пергамент із рук Ґорнека. Послання походить від Джен'шан, досвідченої мисливиці Темного Списа, яка спостерігає за новоприбулими з околиць табору. Записка — це офіційне запрошення розпочати справжнє навчання: визнання того, що новачок має чуття, потрібне, аби впокорити неприборканих звірів і суворі землі Дуротару."},{t="Шлях мисливця",b="Явившись до Джен'шан, новобранець перестає бути простим рекрутом і стає справжнім слідопитом. Джен'шан одразу розвіює хибну думку, ніби ремесло мисливця простіше за таємні мистецтва чи шаманізм предків. Опанувати хижаків Дуротару, доглядати зброю для стрільби й виживати на безжальній землі — усе це вимагає невпинної дисципліни. Вона скеровує своїх учнів допомагати іншим мешканцям долини, щоб випробувати свої вміння, а тоді повернутися до неї по складніші навички виживання."}},faq={{q="Що таке Гравірований Пергамент?",a="Це письмовий виклик, який Ґорнек передає від імені наставниці мисливців Джен'шан. Він кличе перспективних новобранців з'явитися до неї по особливу бойову й польову науку в Долині Випробувань.",al={"що за пергамент","записка з гравірованого пергаменту","пергамент мисливця"}},{q="Хто вручає цей виклик гравцеві?",a="Ґорнек віддає пергамент, коли ви пройдете перше випробування — убивство плямистих вепрів у Долині Випробувань.",al={"хто дає гравірований пергамент","де взяти завдання"}},{q="Хто така Джен'шан?",a="Джен'шан — тролиця-мисливиця з Темного Спису, що стоїть у Долині Випробувань. Вона оцінює нових мисливців-орків і тролів і навчає їх основ дальнього бою, вистежування й поводження зі звірами.",al={"лор джен'шан","хто така джен'шан"}},{q="Чому Джен'шан порівнює мисливців з магами й шаманами?",a="Джен'шан попереджає, що багато хто вважає мисливство легким шляхом порівняно з владою над духами предків чи чародійською магією. Вона наголошує, що опанувати смертоносну влучність і диких звірів — не менш відповідальна й небезпечна справа.",al={"чому мисливці не легкі","діалог джен'шан"}},{q="Що буде, коли з'явитися до Джен'шан?",a="Джен'шан знайомить вас із глибшими мисливськими прийомами й радить допомагати іншим мешканцям Долини Випробувань, щоб відточити щойно здобуті вміння на практиці.",al={"що далі після пергаменту","продовження завдання мисливця"}},{q="Хто може отримати це завдання?",a="Це завдання пропонують лише новоствореним мисливцям-оркам, що навчаються в Долині Випробувань.",al={"хто може отримати гравірований пергамент","чи лише для мисливців"}}},fp="16,283,23.472.0,16.490.0,29.206.0,40.119.0,16.195.0,55.216.0,41.182.0,27.96.0"}
P.entries["quest:3088"] = {n="Зашифрований Пергамент",s="Зашифрований Пергамент — виклик, який отримують розбійники-орки, що довели в Долині Випробувань свої основні навички виживання. Написаний шифром, він скеровує перспективних новобранців у затінені глибини Лігва на зустріч із Рваґом — агентом, що служить інтересам Розтрощеної Руки.",h="Зашифрований Пергамент — виклик, який отримують розбійники-орки, що довели в Долині Випробувань свої основні...",kw={"розбійник","рваґ","зашифрований пергамент","розбита рука","лігво","долина випробувань"},ang={["class:Rogue"]="Цей пергамент — ваше офіційне посвячення в таємну службу Орди: він знайомить вас із Рваґом і відкриває ваш перший фаховий вишкіл.",["faction:Horde"]="Навіть такий шляхетний вождь, як Тралл, визнає, що шпигуни й розвідники потрібні, аби захистити молоді землі Дуротару від прихованих загроз.",["race:Orc"]="На відміну від типових воїнів-орків, які шукають відкритої кривавої слави, розбійники-орки поєднують дисципліну предків із тихою хитрістю, якої вимагає Розтрощена Рука."},sec={{t="Шифрований виклик",b="Довівши свою стійкість у сутичках із тутешньою звіриною, новачки-орки отримують зашифрований пергамент, який передає Ґорнек. Поки інші наставники відкрито набирають учнів на галявині, учитель розбійників Рваґ воліє надійну непомітність шифру й каменю. Пергамент веде новобранця повз залитий сонцем табір углиб печери, відомої як Лігво."},{t="Очі в тінях",b="Розгадавши записку й зайшовши всередину, новачок знаходить Рваґа, що причаївся серед скель. Насторожений чорнокнижниками, які ховаються ще глибше в печері, Рваґ не гаючись пояснює свою справжню відданість: він наглядає за новобранцями від імені Розтрощеної Руки. Поки орківське суспільство славить відкриту честь і славу на полі бою, Розтрощена Рука діє як мовчазна мережа шпигунів, горлорізів і збирачів відомостей Орди."}},faq={{q="Хто надсилає Зашифрований Пергамент?",a="Пергамент написав Рваґ, наставник розбійників у Долині Випробувань. Він доручає Ґорнекові передати шифроване послання перспективним молодим оркам, коли ті пройдуть перші випробування.",al={"хто написав пергамент","хто дав зашифрований пергамент","хто надіслав записку"}},{q="Яка мета цього завдання?",a="Це вступне класове завдання для розбійників-орків: воно вчить їх знайти Рваґа в Лігві, щоб почати справжнє навчання скрадання, відмикання замків і бойових хитрощів.",al={"навіщо зашифрований пергамент","що робить це завдання"}},{q="Де знайти Рваґа?",a="Рваґ ховається в Лігві — темній печері на північному боці Долини Випробувань. Він скрадається в тінях біля входу, обережно тримаючись подалі від чорнокнижників у глибині.",al={"де рваґ","знайти рваґа","місце рваґа"}},{q="Чому пергамент зашифровано?",a="Розбійники покладаються на таємність і стриманість. Шифр гарантує, що мандрівні громили чи цікаві чужинці не прочитають виклику, а заразом перевіряє, чи вміє новачок розшифровувати таємні повідомлення.",al={"чому шифр","чому записка закодована"}},{q="Хто такі Розтрощена Рука?",a="Колись сумнозвісний орчий клан, відомий самокалічінням, Розтрощена Рука в Орді Тралла стала організацією розвідників, убивць і таємних агентів, що з тіні захищають інтереси Орди.",al={"розтрощена рука орда","що таке розтрощена рука"}},{q="Чому Рваґ не довіряє Нартокові?",a="Нарток — наставник чорнокнижників, що стоїть глибше в Лігві. Розбійники діють потай, але навіть Рваґові вкрай моторошно, що темні чаклуни відкрито проводять обряди скверни в найглибших закутках печери.",al={"рваґ нартока","чому рваґ ненавидить чорнокнижників"}}},fp="19,293,15.355.0,19.441.0,34.182.0,34.192.0,22.198.0,31.214.0,27.225.0,30.209.0"}
P.entries["quest:3089"] = {n="Пергамент з Рунними Письменами",s="Пергамент з Рунними Письменами — послання, яке отримують шамани-початківці Орди, що розпочинають свій шлях у Долині Випробувань. Його написала наставниця Шікрік, і він кличе перспективних новачків до справжнього навчання єднанню з духами та стихіями.",h="Пергамент з Рунними Письменами — послання, яке отримують шамани-початківці Орди, що розпочинають свій шлях у...",kw={"шаман","шікрік","пергамент","рунні письмена","духи","стихії","долина випробувань"},ang={["class:Shaman"]="Цей пергамент — ваш перший крок на духовному шляху, що скріплює священний союз із духами та первісними стихіями Дуротару.",["race:Orc"]="Для орків повернення до шаманізму вшановує традиції предків із Дренору, які ледь не згасли під час демонічного розбещення Старої Орди.",["race:Troll"]="Тролі Темного Списа, що відгукуються на цей поклик, вплітають своє вроджене єднання з духами й шану до предків у спільні шаманські традиції нової Орди."},sec={{t="Поклик духів",b="Довівши свої основні навички виживання в сутичках із тутешньою звіриною, нові шамани-орки отримують пергамент із рунними письменами від Ґорнека, наглядача Долини Випробувань. На пергаменті — містичні знаки Шікрік, наставниці шаманів у долині, яка просить новоприбулого новачка з'явитися до неї."},{t="Шлях шамана",b="Прихід до Шікрік — це початок священного обов'язку шамана перед Ордою. Шікрік нагадує молодому новачкові, що його покликання — не лише воєнне: він обраний бути провідником духів предків і володарем гніву стихій. Через Шікрік нові шамани вчаться спрямовувати духовні сили, зцілювати рани й кликати на поміч природні сили Калімдору."}},faq={{q="Що таке Пергамент з Рунними Письменами?",a="Це письмовий виклик, який Ґорнек у Долині Випробувань вручає новим шаманам, закликаючи їх розшукати свою наставницю, Шікрік, і почати справжнє навчання стихій.",al={"що за завдання","завдання з пергаментом","записка шамана на початку"}},{q="Хто надсилає пергамент?",a="Послання написала Шікрік — наставниця шаманів біля лігв у Долині Випробувань, що чекає на обранців, покликаних духовно вести свій народ.",al={"хто написав пергамент","записка шікрік","хто така шікрік"}},{q="Куди нести пергамент?",a="Нести недалеко — у межах Долини Випробувань, де під рудими скелями на вас чекає Шікрік, готова навчати шаманів-орків і тролів.",al={"куди йти","де шікрік","місце здавання"}},{q="Чому саме мій герой отримав його?",a="За словами Шікрік, ті, кого вабить шлях шамана, обрані бути провідниками предків і говорити безпосередньо зі стихійними силами світу.",al={"чому шаман","чому обраний","лор поклику шамана"}},{q="Що буде, коли показати пергамент?",a="Шікрік бере вас в учні й знайомить зі шляхом стихійної магії, єднання з предками та основами зцілення й бою.",al={"наступний крок","що робить шікрік","після пергаменту"}},{q="Чи може будь-який клас виконати це завдання?",a="Ні. Пергамент з Рунними Письменами адресовано саме шаманам-новачкам. Інші класи отримують власні виклики до своїх наставників.",al={"чи лише для шаманів","хто отримує пергамент","пергамент для воїнів"}}},fp="24,270,26.317.0,22.385.0,37.168.0,24.165.0,30.142.0,42.161.0,44.145.0,34.159.0"}
P.entries["quest:309"] = {n="Захист вантажу",s="«Захист вантажу» — завдання із супроводом у південному Лох Модані: шукачі пригод оберігають гінця Мірана на шляху до Місця розкопок Айронбенда. Міран везе скриню нестійкого вибухового пороху, якої нагально потребує Шукач Айронбенд. Дорогою відкривається, що підривна діяльність Темного Заліза й досі загрожує дворфійській глибинці.",h="«Захист вантажу» — завдання із супроводом у південному Лох Модані: шукачі пригод оберігають гінця Мірана на...",kw={"захист вантажу","міран","супровід","шукач айронбенд","вибуховий порох","темне залізо","лох модан"},ang={["faction:Alliance"]="Альянс покладається на налагоджене постачання в Лох Модані: вберігаючи гінців від підземних нападників, ви зберігаєте зв'язок між Айронфорджем і східним порубіжжям.",["profession:Mining"]="Рудокопи надто добре знають ціну — і небезпеку — вибухового пороху, коли треба пробиватися в уперту скелю Каз Модану.",["race:Dwarf"]="Для дворфів Айронфорджа захистити припаси Айронбенда — значить захистити свою спадщину, вберегти знахідки предків від диверсій запеклих родичів із Темного Заліза."},sec={{t="Небезпечний рейс із порохом",b="Археологічним розкопкам Шукача Айронбенда в пагорбах південного Лох Модану потрібне постійне постачання вибухового пороху, щоб пробиватися крізь уперту скелю. Коли шляхи постачання розладналися й возам гінців стали загрожувати, Міран застряг на дорозі з важким вантажем пороху. Безпечно провівши Мірана нерівними шляхами до розкопок, ви не дасте роботі Айронбенда стати зовсім."},{t="Прихильники Темного Заліза",b="На дорозі до розкопок чатують не лише дикі звірі — лазутчики Темного Заліза навмисно підстерігають вибуховий вантаж. Їхня зухвала засідка біля розкопок відкриває Айронбендові похмуру правду: сили Темного Заліза роздобувають заборонені матеріали й сіють розбрат у самому серці Лох Модану. Доставка дає розкопкам змогу тривати, але й б'є на сполох: ворожі диверсії сягають углиб земель Альянсу."}},faq={{q="Хто такий Міран?",a="Міран — гонець Альянсу, якому доручено возити важливі припаси, зокрема вибуховий порошок, небезпечними манівцями Лох Модану до Місця розкопок Айронбенда.",al={"хто такий міран","міран лох модан","кур'єр міран"}},{q="Навіщо Шукачеві Айронбенду порошок?",a="Шукач Айронбенд керує важливими археологічними розкопками на півдні Лох Модану. Його загін покладається на потужний вибуховий порошок, щоб розчищати скелю, відкопувати давні артефакти титанів і підтримувати роботу.",al={"навіщо айронбенду порошок","призначення порошку","вибуховий порошок айронбенда"}},{q="Хто нападає під час супроводу?",a="Біля самих розкопок на гінця влаштовують засідку диверсанти з дворфів Темного Заліза, щоб захопити вибухівку й зірвати роботу Айронфорджа в краю.",al={"хто нападає","хто влаштовує засідку на міран","напасники під час супроводу"}},{q="Куди веде супровід?",a="Супровід починається на південному шляху Лох Модану й завершується на Місці розкопок Айронбенда, на пагорбах на південний схід від озера.",al={"куди супровід","куди йде міран","де айронбенд"}},{q="Що дворфи Темного Заліза роблять у Лох Модані?",a="Клан Темного Заліза має таємні осередки й шпигунів по всьому Каз Модану. Вони нападають на шляхи постачання, шкодять розкопкам Ліги Дослідників і прагнуть розхитати оборонний периметр Айронфорджа.",al={"темне залізо лох модан","чому дворфи темного заліза тут","присутність темного заліза"}},{q="Що буде, коли вантаж прибуде?",a="Шукач Айронбенд з полегшенням приймає порошок, дякуючи Світлу, що припаси дійшли, попри тривожне відкриття: поблизу діють пособники Темного Заліза.",al={"продовження завдання","що після захисту вантажу","наступне завдання"}}},fp="23,331,21.413.0,22.441.1,13.173.0,45.215.0,30.160.0,27.144.0,33.200.0,40.180.0"}
P.entries["quest:3092"] = {n="Гравірована Записка",s="Гравірована Записка — офіційний виклик, адресований перспективним молодим мисливцям-тауренам, яких зібрав Табір Нарачі. Передане від імені наставника Ланки Фаршота послання кличе новачка почати опановувати практичні й духовні мистецтва дикої природи.",h="Гравірована Записка — офіційний виклик, адресований перспективним молодим мисливцям-тауренам, яких зібрав...",kw={"гравірована записка","мисливець","ланка фаршот","ґрулл гоквінд","табір нарачі","шу'гало"},ang={["class:Hunter"]="Цей виклик знаменує ваше офіційне посвячення в традицію мисливців і готує вас опанувати мистецтво влучної стрільби, виживання в дикій природі й дружби зі звірами.",["race:Tauren"]="Для шу'гало полювання — священний обов'язок, що шанує Матір-Землю через повагу до звірів, які годують плем'я на рівнинах Малгору."},sec={{t="Поклик до полювання",b="Молодим тауренам, що навчаються серед круч Плато Червоної Хмари й виявляють хист до влучної стрільби та слідопитства, передають гравіроване послання. Записка, що переходить із рук Ґрулла Гоквінда, несе звістку: Ланка Фаршот помітив родовід і природну здібність юнака й закликає його взятися за науку під його пильним оком."},{t="Традиція рівнин",b="Для шу'гало мисливець — значно більше, ніж простий розвідник чи воїн. Мисливці годують племена своєю здобиччю, захищають кочові стійбища й живуть у тісній рівновазі зі звірами Калімдору. Кличучи новачка на навчання, Ланка закладає підвалини для опанування зброї, розуміння створінь Малгору і, зрештою, стародавнього мистецтва приборкувати диких супутників."}},faq={{q="Навіщо потрібна Гравірована Записка?",a="Гравірована Записка — офіційне знайомство, що пов'язує таурена-мисливця з Ланкою Фаршотом, місцевим класовим наставником у Таборі Нарачі.",al={"що робить гравірована записка","призначення гравірованої записки","чому я отримав записку"}},{q="Хто вручає записку?",a="Записку передає Ґрулл Гоквінд, пояснюючи, що гонець від наставника мисливців щойно шукав молодого мисливця.",al={"хто дає записку","хто дає гравіровану записку","записка роґаку"}},{q="Де знайти Ланку Фаршота?",a="Ланка Фаршот — у Таборі Нарачі на Плато Червоної Хмари, біля тренувального майданчика мисливців, готовий навчати новобранців.",al={"де ланка фаршот","знайти ланку фаршот","місце ланки"}},{q="Чому мисливців так шанують серед тауренів?",a="Мисливці відіграють важливу роль у суспільстві тауренів: вони добувають їжу, розуміються на дикій природі й підтримують гармонію з духами рівнин.",al={"лор мисливців таурен","чому мисливці таурен важливі"}},{q="Яких умінь знайомить це навчання?",a="Ланка готує новачка до основ мисливства: користуватися зброєю дальнього бою, розуміти диких звірів, а згодом — і до обрядів, потрібних, щоб приручати звірів-супутників.",al={"чого вчить ланка","основи мисливця таурен"}},{q="Що далі, коли прочитаєш записку?",a="Доповідь Ланці Фаршоту завершує виклик, і він стає вашим наставником — навчатиме стріляти з рушниці, приручати улюбленця й багато чого іншого, у міру того як ви зростатимете.",al={"наступне завдання після записки","продовження гравірованої записки"}}},fp="11,247,21.346.0,23.398.0,39.152.0,22.132.0,31.134.0,44.152.0,41.189.0,45.148.0"}
P.entries["quest:3094"] = {n="Зелена Записка",s="Зелена Записка — офіційний виклик, який вручають перспективним молодим тауренам на Плато Червоної Хмари. Довірене Ґруллу Гоквінду послання велить майбутнім захисникам дикої природи розшукати наставника друїдів Ґарта Містраннера там, де стоїть Табір Нарачі.",h="Зелена Записка — офіційний виклик, який вручають перспективним молодим тауренам на Плато Червоної Хмари.",kw={"зелена записка","друїд","ґарт містраннер","ґрулл гоквінд","табір нарачі","мати-земля","плато червоної хмари"},ang={["class:Druid"]="Цей виклик — найперше посвячення друїда в спрямування диких енергій і неспокійних духів Азерота.",["faction:Horde"]="Друїди-таурени — головний міст між сучасною Ордою й природними таємницями Калімдору, що дає духовну рівновагу первісній бойовій силі фракції.",["race:Tauren"]="Для тауренів друїдизм — не просто школа магії, а священний заповіт, успадкований від їхньої міфічної відданості Матері-Землі."},sec={{t="Поклик на шлях",b="Молодих тауренів, що беруться за свої обов'язки на Плато Червоної Хмари, швидко вирізняють за природними дарами. Ґрулл Гоквінд передає це послання від імені гінця, якого надіслав Ґарт Містраннер. Записка — запрошення в стародавнє коло друїдизму тауренів: вона кличе посвяченого від простих сільських доручень до того, щоб дослухатися до шепітливої рівноваги рівнин."},{t="Голоси Матері-Землі",b="Коли посвячений відгукується на виклик, Ґарт Містраннер застерігає друїда-початківця: духи предків і природи стали неспокійними по всьому Малгору. Друїди-таурени мають бути живими втіленнями природи й зберігати злагоду з волею Матері-Землі, хоч би які далекі суперечки точилися. Нічні ельфи теж практикують друїдичні мистецтва, та Ґарт застерігає: їхня гордість засліплює їх і не дає побачити власний глибокий зв'язок тауренів зі світом природи."}},faq={{q="Що таке Зелена Записка?",a="Це вступний виклик для молодих друїдів-тауренів у Таборі Нарачі. Він велить розшукати місцевого наставника, Ґарта Містраннера, щоб почати впорядковане навчання друїдських мистецтв.",al={"що таке зелена записка","лист друїда","записка друїда малґора"}},{q="Хто вручає записку гравцеві?",a="Ґрулл Гоквінд передає записку молодому друїдові, згадуючи, що гонець від Ґарта Містраннера нещодавно його шукав.",al={"хто дає зелену записку","початок зеленої записки"}},{q="Де знайти Ґарта Містраннера?",a="Ґарт Містраннер — у Таборі Нарачі, під захистом природних круч табору, де він опікується навчанням друїдів-тауренів.",al={"місце ґарта містраннера","де ґарт"}},{q="Чому Ґарт Містраннер застерігає щодо нічних ельфів?",a="Обидві раси шанують природу й практикують друїдство в межах Кола Кенарія, але Ґарт помічає, що пиха нічних ельфів часто забарвлює їхнє ставлення до інших культур. Він радить учневі не зважати на таке й зосередитися лише на мудрості Земної Матері.",al={"таурени й нічні ельфи друїди","гордість нічних ельфів друїди"}},{q="Чому духи в Малгорі неспокійні?",a="Ґарт Містраннер відчуває збурення, що тривожать духів предків і природи по всіх рівнинах Малгору, — це рання ознака того, що берегти рівновагу дикої природи буде обов'язком молодого друїда все життя.",al={"чому духи малґора неспокійні","чому духи природи сердиті"}},{q="Якого вміння навчає Ґарт після цього завдання?",a="Коли ви з'явитеся до Ґарта Містраннера, він стає наставником посвяченого й обіцяє навчати дарів Земної Матері, у міру того як той мудрішатиме.",al={"що після зеленої записки","продовження завдання друїда"}}},fp="12,237,21.383.0,25.433.0,25.201.0,36.134.0,35.150.0,54.278.0,40.202.0,62.137.0"}
P.entries["quest:3096"] = {n="Зашифрований Сувій",s="Зашифрований Сувій — непримітний виклик, який отримують щойно пробуджені розбійники Відступників у Похоронному Подзвоні. Передана через Жерця Тіні Сарвіса, шифровка скеровує новобранця до Девіда Тріаса — наставника розбійників, що тихо працює з місцевого заїзду.",h="Зашифрований Сувій — непримітний виклик, який отримують щойно пробуджені розбійники Відступників у...",kw={"зашифрований сувій","девід тріас","сарвіс","похоронний подзвін","розбійник","тінеслідці"},ang={["class:Rogue"]="Це послання — ваше офіційне посвячення в таємну мережу Відступників, місток між щойно піднятим трупом і майбутнім таємним агентом.",["race:Undead"]="Поки новостворені Відступники обороняють Галявини Тірісфалю від Погибелі та недобитків живих, розвідники й таємні агенти життєво важливі для стратегії виживання Темної Леді."},sec={{t="Тихий виклик",b="Поки щойно піднята нежить б'ється з безтямними зомбі на цвинтарі, очільники поселення придивляються до тих, хто має хист до скрадання й хитрощів. Жрець Тіні Сарвіс вручає цей запечатаний пергамент перспективним розвідникам, щойно ті доведуть свою первинну готовність. Позначений непримітною печаткою Девіда Тріаса, він слугує першим знайомством із тіньовою мережею, що діє в глибині ієрархії Відступників."},{t="Очі в тінях",b="Девід Тріас спостерігає за перехрестям і заїздом Похоронного Подзвону, вишукуючи кандидатів для майбутніх таємних операцій. Відступникам потрібні не прості злодії чи безрозсудні кишенькові крадії, а дисципліновані таємні агенти на службі молодого королівства. Тріас натякає, що здібні розбійники з часом можуть привернути увагу Тіньових Переслідувачів — відданого загону Відступників, де цінують хитрість, точність і беззастережну вірність Темній Леді."}},faq={{q="Навіщо потрібен Зашифрований Сувій?",a="Сувій — приватне запрошення для щойно пробуджених розбійників-Відступників. Жрець Тіні Сарвіс вручає його, коли ви доведете свою вправність, і спрямовує вас до Девіда Тріаса по особливий вишкіл.",al={"що таке зашифрований сувій","що робить сувій","навіщо зашифрований сувій"}},{q="Хто такий Девід Тріас?",a="Девід Тріас — наставник розбійників у корчмі Похоронного Подзвону. Він оцінює новобранців і вишукує можливих агентів для більших розвідувальних операцій Відступників.",al={"девід тріас","хто такий тріас","тренер розбійників похоронного подзвону"}},{q="Хто такі Тінескрадачі, яких згадує Тріас?",a="Тінескрадачі — організація агентів-скрадачів і вбивць з Відступників. Тріас попереджає нових розбійників, що Тінескрадачі беруть лише обдарованих, дисциплінованих агентів, а не незграбних кишенькових злодіїв.",al={"хто такі тінескрадачі","тінескрадачі відступники","тінескрадачі"}},{q="Чому послання зашифровано?",a="Розбійники-Відступники понад усе цінують таємність і безпеку операцій. Зашифровані донесення гарантують, що делікатні повідомлення не потраплять на очі сторонніх у такому вразливому поселенні, як Похоронний Подзвін.",al={"чому шифр","чому послання зашифроване"}},{q="Де знайти Жерця Тіні Сарвіса?",a="Жрець Тіні Сарвіс приймає нових Відступників у центральному комплексі склепу й каплиці Похоронного Подзвону в Галявинах Тірісфалю.",al={"де сарвіс","місце сарвіса","знайти жерця тіні сарвіса"}},{q="Де знайти Девіда Тріаса?",a="Девід Тріас стоїть у пошкодженій будівлі корчми трохи нижче стежкою від центральної каплиці Похоронного Подзвону.",al={"де тріас","місце девіда тріаса","тренер у корчмі похоронного подзвону"}}},fp="16,243,15.433.0,19.443.0,44.200.0,19.169.0,46.205.0,29.217.0,39.142.0,29.108.0"}
P.entries["quest:3097"] = {n="Освячений Сувій",s="Освячений Сувій — вступний виклик для щойно пробуджених жерців Відступників у Похоронному Подзвоні. Передане Жерцем Тіні Сарвісом, послання кличе новака до Темного Клірика Дюстена в зруйновану сільську каплицю — дізнатися, як нежить тримається віри після смерті.",h="Освячений Сувій — вступний виклик для щойно пробуджених жерців Відступників у Похоронному Подзвоні.",kw={"освячений сувій","дюстен","сарвіс","жрець","похоронний подзвін","тінь","віра"},ang={["class:Priest"]="Це завдання — ваше філософське хрещення в жрецтві Відступників: відмова від традиційного благочестя заради опори на себе, страждання і магії Тіні.",["race:Undead"]="Сувій утілює світогляд Відступників: відірвані від колишньої людської віри, вони виживають лише залізною волею і взаємною необхідністю."},sec={{t="Виклик у Похоронному Подзвоні",b="Коли щойно пробуджена нежить вибирається з могил Похоронного Подзвону, її розум часто ще хитається від пережитого: чуми, смерті й раптового звільнення з лещат Короля-Ліча. Для тих, хто за життя був ревним послідовником Святого Світла, сум'яття особливо глибоке. Поки молода нежить б'ється з безтямною Погибеллю на околицях поселення, Жрець Тіні Сарвіс перехоплює вхідні послання. Освячений сувій, позначений знаком Темного Клірика Дюстена, велить новопіднятим жерцям облишити блукання і з'явитися до оскверненої міської каплиці."},{t="Віра, переосмислена наново",b="Доставивши сувій, новак стикається з суворим богослов'ям жрецтва Відступників. Темний Клірик Дюстен не добирає м'яких слів: Святе Світло покинуло їх у смерті, духи предків — порожні казки, а демони з інших світів байдужі до їхньої біди. Натомість духівництво Відступників навчає: єдине справжнє джерело порятунку — чиста сила волі та безоглядна опора на себе. Під наставництвом Дюстена новопідняті жерці вчаться спрямовувати і божественну дисципліну, і Тінь, черпаючи силу не з відданості далеким богам, а з непохитної переконаності у власному виживанні."}},faq={{q="Що таке Освячений Сувій?",a="Це запечатаний документ, який Жрець Тіні Сарвіс дає щойно воскреслим жерцям-Відступникам у Похоронному Подзвоні. Він велить розшукати Темного Кліріка Дюстена в місцевій каплиці, щоб почати справжнє жрецьке навчання.",al={"освячений сувій","предмет сувій","сувій жерця"}},{q="Хто надсилає сувій гравцеві?",a="На сувої — особиста печатка Темного Кліріка Дюстена, наставника жерців-Відступників, що мешкає в каплиці Похоронного Подзвону, хоча вручає його вам Жрець Тіні Сарвіс.",al={"хто надіслав сувій","сувій дюстена","лист сарвіса"}},{q="Чи можуть Відступники й далі володіти Святим Світлом?",a="Темний Клірик Дюстен каже новим жерцям, що Святе Світло їх більше не стосується. За його словами, від звичного шанування Світла відмовляються на користь віри в себе й панування над Тінню.",al={"чи нежить може користуватися світлом","відступники святе світло","чи нежить може творити світло"}},{q="Де знайти Темного Кліріка Дюстена?",a="Він у зруйнованій церкві посеред Похоронного Подзвону на заході Галявин Тірісфалю, поруч з іншими наставниками-Відступниками.",al={"знайти дюстена","місце дюстена","де клірик дюстен"}},{q="Чому Дюстен відкидає і предків, і демонів?",a="Дюстен хоче розвіяти всі ілюзії, які мають щойно воскреслі мерці. Культура Відступників відкидає зовнішніх божественних рятівників, допомогу предків і демонічні угоди й навчає, що їхнє виживання залежить лише від їхньої спільної сили волі.",al={"промова дюстена","казки","навіть нижній світ не хоче вас"}},{q="Що буде, коли прочитати сувій?",a="Ви читаєте пергамент і з'являєтеся до Темного Кліріка Дюстена в каплиці Похоронного Подзвону — це відкриває ваші перші жрецькі вміння, і він стає вашим наставником, поки ви в початковому краї.",al={"мета освяченого сувою","здати сувій"}}},fp="15,277,23.577.0,15.584.0,28.210.0,35.179.0,40.201.0,37.133.0,46.244.0,38.197.0"}
P.entries["quest:3098"] = {n="Гліфічний Сувій",s="Гліфічний Сувій — офіційний виклик, який отримують щойно пробуджені маги Відступників у Похоронному Подзвоні. Пергамент із печаткою наставниці магів Ізабелли скеровує перспективних адептів таємної магії до неї, в осквернену сільську церкву, — приборкати свою нестримну силу.",h="Гліфічний Сувій — офіційний виклик, який отримують щойно пробуджені маги Відступників у Похоронному Подзвоні.",kw={"гліфічний сувій","ізабелла","маг","похоронний подзвін","таємна магія","даларан"},ang={["class:Mage"]="Цей сувій — ваше офіційне посвячення в лави магів Відступників; він напряму пов'язує ваше ремесло з виживанням і відродженням вашого щойно звільненого народу.",["race:Undead"]="Маги Відступників володіють таємною магією з темною метою: для них це не вчена гра Даларана, а незамінна зброя, щоб повернути вкрадену батьківщину."},sec={{t="Виклик до таємної магії",b="Коли щойно піднятий Відступник, винищуючи безтямну Погибель довкола Похоронного Подзвону, виявляє хист до таємної магії, старші одразу беруть його на замітку. Гліфічний Сувій, переданий із рук у руки, позначено магічною печаттю Ізабелли, місцевої наставниці магів. Він велить новопіднятому адепту з'явитися до її посту в зруйнованій церкві, адже неконтрольований магічний хист небезпечний для Відступників не менше, ніж для їхніх ворогів."},{t="Магія в нежитті",b="У зруйнованій каплиці Похоронного Подзвону Ізабелла втовкмачує новачкам: смерть не звільнила їх від небезпек таємної магії. Нехай смертність забрала тілесну слабкість, та нестримний потяг магії та її згубна природа нікуди не поділися. Для Відступників опанування таємної магії — не просто інтелектуальна вправа, а знаряддя виживання і помсти: спосіб повернути собі долю і стерти кожного, хто зазіхне на їхнє крихке відвоювання Лордерону."}},faq={{q="Що таке Гліфічний Сувій?",a="Гліфічний Сувій — настановче письмо з особистою печаткою Ізабелли, наставниці магів-Відступників у Похоронному Подзвоні. Він велить щойно пробудженим магам з'явитися до зруйнованої церкви, щоб продовжити вивчати чародійство.",al={"що таке гліфічний сувій","завдання гліфічного сувою","сувій похоронного подзвону"}},{q="Хто надсилає вам Гліфічний Сувій?",a="Сувій надсилає Ізабелла, місцева наставниця магів у Похоронному Подзвоні, і його вручають вам, коли ви доведете свою корисність, упоравшись з довколишньою безвольною Погибеллю.",al={"хто надіслав сувій","хто написав гліфічний сувій","відправник сувою"}},{q="Де знайти Ізабеллу?",a="Ізабелла — у зруйнованій сільській церкві посеред Похоронного Подзвону, поруч з іншими класовими наставниками, що допомагають щойно воскреслим Відступникам.",al={"де ізабелла","знайти ізабеллу","місце тренера магів похоронного подзвону"}},{q="Чому Ізабелла попереджає про магічну скверну?",a="Ізабелла попереджає: хоча Відступники — нежить, нестійка природа чародійської сили не змінилася. Магія й далі несе постійний ризик розбещення й залежності, тож щоб опанувати її й не згоріти, потрібні дисципліна й воля.",al={"скверна магії нежить","лор скверни аркани","чому магія небезпечна для нежиті"}},{q="Чому чародійська магія важлива для Відступників у Похоронному Подзвоні?",a="Маги-Відступники вважають чародійську силу необхідним знаряддям, щоб повернути Лордерон і відстояти свою незалежність від безвольної Погибелі, ворожих живих смертних і Багряного Хрестового Походу.",al={"чому відступники користуються магією","лор магів-нежиті"}},{q="Чи може будь-який клас Відступників отримати цей сувій?",a="Ні. Гліфічний Сувій дають лише магам-Відступникам як вступний виклик до їхнього головного класового наставника в Похоронному Подзвоні.",al={"чи лише для магів","чи чорнокнижники можуть гліфічний сувій","хто отримує гліфічний сувій"}}},fp="14,286,23.482.0,25.502.0,27.226.0,36.169.0,26.165.0,52.239.0,60.174.0,43.134.0"}
P.entries["quest:31"] = {n="Водяна форма",s="Це завдання — останній крок на шляху юного друїда Орди до влади над водами. Довівши свою гідність і налаштувавшись на аспект морського лева в Місячному Гаю, друїд повертається додому, до Тандер Блафа, щоб отримати офіційне визнання й опанувати водяну форму.",h="Це завдання — останній крок на шляху юного друїда Орди до влади над водами.",kw={"водяна форма","друїд","амулет морського лева","турак рунтотем","місячний гай","тандер блаф","морський лев"},ang={["class:Druid"]="Здобута водяна форма долає прірву між суходолом і морем: ви легко перетинаєте водойми й утікаєте від хижаків у глибинах.",["faction:Horde"]="Друїди-таурени — духовна ланка між Ордою й Колом Кенарія: вони ходять між прадавніми нейтральними святилищами й племінними столицями свого народу.",["race:Tauren"]="Турак Рунтотем нагадує вам, що опанування морських звірів ушановує ваших предків і зміцнює священне відродження друїдських звичаїв серед тауренів."},sec={{t="Повернення морського лева",b="Подолавши випробування у священному прихистку Місячного Гаю, молодий друїд-таурен за настановою Дендрита Старблейза повертається до Малгору. Маючи при собі Амулет Морського Лева, учень несе відчутний доказ своєї рівноваги й відданості, здобутий у водах Калімдору. Амулет засвідчує, що він ушанував прадавні традиції, без яких не прийняти водяного аспекту."},{t="Єднання з водами",b="Піднявшись на висоти Тандер Блафа, мандрівник показує амулет своєму наставникові, Тураку Рунтотему. Утішений тим, що учень ушанував предків і природну рівновагу, Турак відкриває йому таємницю водяної форми. Відтепер друїд уміє пірнати в ріки й океани, вільно дихати під водою й долати глибини, мов морська істота."}},faq={{q="Яка мета цього завдання?",a="Це завдання завершує обряд посвяти для молодих друїдів Орди: вони віддають у Тандер Блафі тяжко здобутий Амулет Морського Лева й нарешті відкривають Водяну подобу.",al={"мета завдання","навіщо водяна форма","що дає це завдання"}},{q="Кому нести Амулет Морського Лева?",a="Амулет треба віднести Туракові Рунтотему — наставникові друїдів на верхніх узвишшях Тандер Блафа в Малгорі.",al={"хто приймає амулет","куди здати водяну форму","місце турака рунетотема"}},{q="Хто посилає вас назад до Тандер Блафа?",a="Дендрит Старблейз, друїд-охоронець з нічних ельфів у нейтральному притулку Місячного Гаю, посилає вас назад, коли ви завершите водні випробування.",al={"хто дає водяну форму","завдання дендрита старблейза"}},{q="Чи можуть це завдання виконати не друїди?",a="Ні. Цей ланцюжок завдань — лише для друїдів, як частина їхнього духовного й магічного зростання, що відкриває звірині подоби.",al={"чи лише для друїдів","чи інші класи водяна форма"}},{q="Чому нічний ельф у Місячному Гаю допомагає друїдові Орди?",a="Місячний Гай — нейтральний притулок під опікою Кола Кенарія. Навчаючи давніх мистецтв шляху Кенарія, наставники з нічних ельфів ведуть друїдів-тауренів без політичної ворожнечі, дбаючи лише про рівновагу природи.",al={"чому дендрит допомагає орді","місячний гай орда альянс","нейтральність друїдів"}},{q="Яке вміння дає це завдання?",a="Коли ви здасте завдання Туракові Рунтотему, він навчить вас Водяної подоби: у ній ви швидше плаваєте й дихаєте під водою.",al={"яку форму я отримаю","закляття водяної форми","форма води"}}},fp="12,268,22.381.0,25.390.0,34.200.0,46.120.0,36.147.0,35.127.0,53.231.0,46.153.0"}
P.entries["quest:310"] = {n="Запеклі суперники",s="Запеклі суперники — раннє завдання Альянсу в Дун Мороґу, народжене з лютого змагання між двома гордими дворфійськими броварськими родинами. Марлет Барліб'ю посилає шукача пригод проникнути до Ґуральні Тандербрю в Хараносі й попорпатися в запасах суперників.",h="Запеклі суперники — раннє завдання Альянсу в Дун Мороґу, народжене з лютого змагання між двома гордими...",kw={"запеклі суперники","марлет барліб'ю","тандербрю","барліброю","громовий ель","окріп барліброю","льох","харанос"},ang={["class:Rogue"]="Проникнути до охоронюваного льоху, відволікти вартового й непомітно підмінити контрабанду — звична робота для будь-якого розбійника, навіть якщо нагорода — пиво, а не золото.",["faction:Alliance"]="Харанос — культурний і логістичний осередок Дун Мороґу для мандрівників Альянсу, тож місцеві корчемні суперечки — часта розвага для новобранців, що проходять повз.",["race:Dwarf"]="Для дворфів броварство — серйозна справа, що за престижем не поступається ковальству. Устрягнути в льохову ворожнечу через суперницькі елі — цілком звична річ серед снігів Дун Мороґу."},sec={{t="Смак змагання",b="Мало що в Каз Модані розпалює пристрасті так швидко, як пінта елю. Барліброю давно нидіють у тіні уславленої Ґуральні Тандербрю в Хараносі. Хоч Марлет Барліб'ю неохоче визнає, що ремесло Тандербрю гідне поваги, вона не може стерпіти думки, що це єдиний уславлений трунок у Дун Мороґу. Щоб струснути місцевий смак, вона задумує підмінити діжку Громового Елю своїм вогняним варивом — Окропом Барліброю."},{t="Підступ у льоху",b="Щоб здійснити задум, треба прослизнути просто під носом у відвідувачів Хараноса. Під кухнею ґуральні лежить підвальна комора, де витримані діжки чекають, щоб їх відкоркували. Оскільки Тандербрю тримають вартового біля свого найціннішого запасу, майбутній диверсант мусить знайти спосіб відманити сторожа, перш ніж потай підмінити барила."}},faq={{q="Хто дає завдання «Запеклі суперники»?",a="Завдання дає Марлет Барліб'ю. Він сповнений рішучості довести, що ремесло його родини може змагатися зі славетними напоями, які наливають у Ґуральні Тандербрю.",al={"хто дає запеклих суперників","початок завдання марлет"}},{q="Де льох Тандербрю?",a="Льох — під Ґуральнею Тандербрю в містечку Харанос. Сходи вниз сховані за столом на кухні.",al={"де льох тандербрю","як дістатися погреба винокурні"}},{q="Що таке Окріп Барліброу?",a="Окріп Барліброу — міцний фірмовий ель Марлета Барліб'ю. Він вірить, що коли відвідувачі в Хараносі скуштують його під виглядом Громового Елю, то нарешті визнають його пивоварську перевагу.",al={"окріп барліброу","який напій підмінити"}},{q="Як оминути вартового, що стереже бочки?",a="Вартовий Тандербрю внизу, у підвалі, сам натякне, що могло б відволікти його увагу, — і поки він відволічеться, у вас буде якраз досить часу, щоб підмінити бочки.",al={"відволікання вартового льоху","безпечна бочка громового елю","вартовий бочки"}},{q="Чому Барліб'ю й Тандербрю ворогують?",a="Це питання дворфійської професійної гордості. Тандербрю панують серед корчем Хараноса, а Барліб'ю хочуть довести, що їхні рецепти не гірші, а то й кращі.",al={"ворожнеча пивоварів","чому барліб'ю ненавидить тандербрю"}},{q="Яке завдання йде після «Запеклих суперників»?",a="Щойно барильце Окропу Барліброу стоїть на місці, завдання веде просто до «Повернення до Марлет», щоб доповісти про успіх.",al={"наступне завдання після запеклих суперників","що після запеклих суперників"}}},fp="13,260,22.464.0,17.369.0,34.153.0,40.144.0,27.194.0,49.179.0,49.197.0,33.120.0"}
P.entries["quest:3103"] = {n="Освячений Лист",s="Освячений Лист — офіційний виклик, який Маршал Макбрайд вручає перспективним молодим жерцям від імені наставниці Абатства Нортшира, Жриці Анетти. Він знаменує початок формального навчання жерця-початківця засадам Святого Світла посеред неспокійного й уразливого світу.",h="Освячений Лист — офіційний виклик, який Маршал Макбрайд вручає перспективним молодим жерцям від імені...",kw={"освячений лист","жрець","жриця анетта","святе світло","нортшир","маршал макбрайд"},ang={["class:Priest"]="Це завдання означає ваше офіційне посвячення в учні Святого Світла під проводом Жриці Анетти й подає вашу божественну магію як життєво важливий обов'язок зцілювати розколотий світ.",["race:Human"]="Абатство Нортшира здавна було прихистком віри й одужання для Королівства Стормвінд і зберігає свої традиції, попри лихо, що підступає до Елвінну."},sec={{t="Поклик до сану",b="Довівши свою доблесть у боротьбі зі шкідниками, що лізуть на виноградники Нортширу, жерці-новачки отримують послання зі священною печаткою Жриці Анетти. Лист, переданий через Маршала Макбрайда, слугує запрошенням розпочати серйозне вивчення Святого Світла в тихих залах абатства."},{t="Світ, що потребує допомоги",b="Отримавши лист, Жриця Анетта доносить до нового учня, у якому похмурому стані перебуває світ. Загроза Палаючого Легіону й досі кидає довгі тіні на Азерот, а континенти потерпають від свіжих ран і заворушень. У її очах узяти на себе служіння жерця — не просто вчена відданість, а нагальний моральний обов'язок нести зцілення й розраду стражденному світу."}},faq={{q="Що таке Освячений Лист?",a="Це запечатаний лист із гербом Жриці Анетти, який Маршал Макбрайд у Долині Нортширу вручає щойно прибулим жерцям-людям. Він велить новачкові почати справжнє навчання в Абатстві Нортшира.",al={"освячений лист","завдання жерця нортшир","лист анетти"}},{q="Хто надсилає Освячений Лист?",a="Жриця Анетта, наставниця жерців в Абатстві Нортшира, пише й запечатує послання й просить Маршала Макбрайда передати його, коли посвячений повернеться з розвідки навали кобольдів.",al={"хто написав освячений лист","хто надіслав лист"}},{q="Чому Жриця Анетта кличе нових жерців?",a="Анетта бачить, що новачок покликаний до Святого Світла, і хоче вести його навчання. У світі досі чатують небезпеки на кшталт решток Палаючого Легіону, тож, наголошує вона, дисципліновані цілителі й провідники потрібні негайно.",al={"чому анетта хоче мене","мета листа"}},{q="Де знайти Жрицю Анетту?",a="Вона в головній залі Абатства Нортшира, готова навчати жерців-людей, поки ті опановують перші молитви й обряди.",al={"де анетта","місце жриці анетти"}},{q="Що буде, коли показати лист Жриці Анетті?",a="Прочитавши лист і привітавшись, Анетта бере гравця в учні, ділиться першою мудрістю й запрошує повертатися по нову науку, у міру того як він набиратиметься досвіду.",al={"наступне завдання після освяченого листа","що після освяченого листа"}},{q="Чому в Нортширі згадують Палаючий Легіон?",a="Третя війна скінчилася, але демонічні рештки Легіону досі нишпорять Азеротом. Жриця Анетта згадує цю загрозу для всього світу, щоб наголосити на ширших небезпеках, які чекають на кожного шукача пригод за межами долини.",al={"палаючий легіон нортшир","чому анетта говорить про демонів"}}},fp="15,292,22.311.0,15.409.0,28.217.0,30.202.0,45.233.0,36.130.0,61.180.0,50.205.0"}
P.entries["quest:3104"] = {n="Гліфічний Лист",s="Гліфічний Лист — офіційний виклик, який Маршал Макбрайд вручає магам-початківцям із людей у Долині Нортширу. Записка, скріплена чародійською печаткою Келдена Бремена, кличе перспективних заклиначів до Абатства Нортшира, щоб розпочати формальне навчання таємних мистецтв.",h="Гліфічний Лист — офіційний виклик, який Маршал Макбрайд вручає магам-початківцям із людей у Долині Нортширу.",kw={"гліфічний лист","маг","келден бремен","чародійство","нортшир","маршал макбрайд"},ang={["class:Mage"]="Це завдання знаменує ваш офіційний перехід від сирого, невишколеного таланту до визнаного підмайстра чародійських мистецтв Стормвінда під проводом Келдена Бремена.",["race:Human"]="Люди-маги Нортширу успадковують традицію, що сягає перших людських чародіїв Даларану й Кірін-Тору, і несуть чародійську міць у Королівство Стормвінд."},sec={{t="Поклик до чародійства",b="Коли майбутній підмайстер доводить свої здібності, допомагаючи Маршалу Макбрайду проти місцевих шкідників, командир гарнізону вручає йому послання, позначене чародійськими рунами. Лист надіслав сам Келден Бремен, наставник магів Нортширу, який придивляється до новобранців, що прибувають до абатства, шукаючи ознак магічної дисципліни й таланту."},{t="Тягар чародійства",b="Абатство Нортшира історично було прихистком Святого Світла, однак небезпеки, що нависли над Стормвіндом, вимагають практиків усіх дисциплін. Відгукнувшись на лист, новачок піднімається сходами до Келдена Бремена. Замість легкої похвали наставник дає суворе попередження: щоб опанувати чародійську силу, треба кидати виклик природним межам, а це викликає у простолюду і глибоку повагу, і глибинний страх."}},faq={{q="Хто вручає Гліфічний Лист?",a="Маршал Макбрайд вручає лист щойно прибулим магам біля Абатства Нортшира, коли ті допоможуть вичистити довколишніх кобольдів.",al={"хто дає гліфічний лист","початок гліфічного листа"}},{q="Хто написав Гліфічний Лист?",a="Лист написав і запечатав Келден Бремен — місцевий наставник магів у верхніх покоях Абатства Нортшира.",al={"автор гліфічного листа","хто надіслав гліфічний лист"}},{q="Де знайти Келдена Бремена?",a="Увійдіть до Абатства Нортшира за Маршалом Макбрайдом, поверніть у лівий коридор, підніміться сходами й пошукайте в дальніх покоях — там Келден чекає, щоб навчати.",al={"місце келдена бремена","де келден"}},{q="Чому наставник магів в абатстві?",a="Абатство Нортшира передусім святе місце, але Стормвінд використовує долину як перший навчальний осередок для захисників усіх ремесел, тож чародійські наставники працюють тут поруч зі священниками й маршалами.",al={"чому маги в абатстві","тренер магів у святому абатстві"}},{q="Що буде, коли віддати лист?",a="Келден Бремен бере вас в учні, схвалює вашу рішучість володіти чародійством попри його небезпеки й відкриває доступ до першого навчання закляттям.",al={"що після гліфічного листа","наступне завдання після гліфічного листа"}},{q="Чому Келден попереджає, що магів боятимуться?",a="Чародійська магія — нестійка сила, що викривлює дійсність. Келден нагадує учням, що прагнення найвищого знання означає переступати межі, від яких звичайним людям глибоко моторошно.",al={"чому магів бояться","діалог келдена бремена"}}},fp="14,275,23.348.0,22.425.0,32.137.0,29.135.0,31.157.0,44.207.0,41.155.0,48.178.0"}
P.entries["quest:3105"] = {n="Опоганений Лист",s="Опоганений Лист — таємний виклик для чорнокнижників-початківців із людей, що навчаються в Долині Нортширу. Послання, яке потайна наставниця Друзілла Ла Салль довірила Маршалу Макбрайду, кличе посвячених подалі від допитливих очей варти абатства — розпочати формальне навчання мистецтва скверни.",h="Опоганений Лист — таємний виклик для чорнокнижників-початківців із людей, що навчаються в Долині Нортширу.",kw={"опоганений лист","чорнокнижник","друзілла ла салль","скверна","нортшир","маршал макбрайд"},ang={["class:Warlock"]="Це завдання — формальний набір людей-чорнокнижників у Нортширі, що встановлює тонку рівновагу між переховуванням від осудливої варти й опануванням небезпечної магії Нижнього Світу.",["race:Human"]="Людська культура здебільшого шанує Святе Світло та дисципліноване чародійство Кірін-Тору, тож людям-чорнокнижникам доводиться вправлятися в прикликанні на тихих околицях таких поселень, як Нортшир."},sec={{t="Таємний виклик",b="Поки жерці та паладини відкрито навчаються в освячених залах Абатства Нортшира, адепти темнішої магії мусять ступати обережно. Довівши свою вправність у боротьбі з місцевими кобольдами, чорнокнижники-новачки отримують листа, переданого через Маршала Макбрайда. Послання з печаткою Друзілли Ла Салль наказує заклиначу-початківцю негайно з'явитися на її відлюдний пост за головними мурами абатства, перш ніж братися за будь-які інші справи."},{t="Спокуса й честолюбство",b="Зустріч із Друзіллою відкриває, яким хистким є шлях чорнокнижника під пильним оком стормвіндської варти, яку вона зневажливо зве «жалюгідними простаками». Друзілла відверто застерігає учня: черпати силу з Викривленого Нижнього Світу й спілкуватися з демонами означає жити під постійною загрозою розбещення. Вона радить терпіння, обачність і непохитне самовладання, щоб не стати жертвою темних енергій, якими вони орудують, — але дає зрозуміти, що така обережність ніколи не має гасити палке честолюбство."}},faq={{q="Хто надсилає Опоганений Лист?",a="Лист написала й запечатала Друзілла Ла Салль — місцева наставниця чорнокнижників, що мешкає одразу біля Абатства Нортшира. Вона просить Маршала Макбрайда передати його вам, щойно ви повернетеся з довколишніх таборів кобольдів.",al={"хто написав опоганений лист","автор опоганеного листа","хто дає опоганений лист"}},{q="Чому Маршал Макбрайд доставляє лист чорнокнижниці?",a="Маршал Макбрайд у долині — просто гонець, що передає послання перспективним новобранцям. Він знає, що на листі печатка Друзілли, і наполягає, що справа першочергова, але його турбує передусім оборона й порядок у Нортширі, а не те, якою саме магією орудують його захисники.",al={"чому макбрайд має лист","чи макбрайд знає що в листі","лист чорнокнижниці макбрайда"}},{q="Де знайти Друзіллу Ла Салль?",a="Друзілла Ла Салль стоїть біля головного входу до Абатства Нортшира, коло зовнішніх мурів і наметів, подалі від священників усередині.",al={"місце друзілли","де друзілла ла салль","знайти друзіллу"}},{q="Чому чорнокнижників пускають до Абатства Нортшира?",a="На землях Альянсу чорнокнижники перебувають під пильною підозрою й не впадають в око. У Нортширі Друзілла тримає своє навчання поза самим святилищем: вона стоїть надворі, де може навчати новобранців, уникаючи прямої сутички зі священниками й паладинами Святого Ордену Нортширу.",al={"чорнокнижники в нортширі","чи магія скверни законна в нортширі","чому дозволяють чорнокнижників"}},{q="Якого уроку навчає Друзілла, отримавши лист?",a="Друзілла попереджає, що черпати силу з Викривленого Нижнього Світу — значить накликати скверну на кожного практика, якому бракує дисципліни. Вона радить суворий самоконтроль і обачність, але наголошує, що страх скверни ніколи не має душити особистих амбіцій чорнокнижника.",al={"порада друзілли","що каже друзілла","урок опоганеного листа"}},{q="Що далі, коли доставиш Опоганений Лист?",a="Розмова з Друзіллою завершує виклик, і вона стає вашою наставницею: запрошує повертатися, коли зміцнієте, щоб пізнати більше шляхів чорнокнижника.",al={"наступне завдання після опоганеного листа","продовження опоганеного листа"}}},fp="14,304,18.465.0,23.538.0,29.223.0,50.315.0,35.143.0,45.296.0,58.248.0,47.161.0"}
P.entries["quest:3106"] = {n="Проста Руна",s="Проста Руна — вступне завдання для дворфів-воїнів-новачків у Долині Холодного Хребта. Передана Стеном Стаутармом від імені наставника воїнів Трана Кормана, вона скеровує свіжих новобранців до Анвілмара, щоб розпочати бойовий вишкіл.",h="Проста Руна — вступне завдання для дворфів-воїнів-новачків у Долині Холодного Хребта.",kw={"проста руна","воїн","тран корман","стен стаутарм","анвілмар","долина холодного хребта","вишкіл"},ang={["class:Warrior"]="Ця руна знаменує офіційний вступ воїна до бойової дисципліни, скеровуючи нові клинки й довбні просто до Трана Кормана в Анвілмарі.",["faction:Alliance"]="Долина Холодного Хребта — початковий навчальний майданчик для гірських сил, що боронять південні підступи Альянсу до Каз Модану.",["race:Dwarf"]="Тран Корман надзвичайно пишається тим, що вчить дворфійських новобранців битися з традиційною твердістю, закорінюючи їхню культуру в сталі й залізі посеред світу, що стрімко змінюється.",["race:Gnome"]="Утративши Гномреґан через трогів і радіацію, гномські бійці, що починають шлях у Долині Холодного Хребта, мусять учитися війни на передовій пліч-о-пліч із дворфійськими наставниками, щоб вижити у вигнанні."},sec={{t="Виклик до ковадла",b="Поки молоді новобранці винищують шкідників і доводять свою твердість довкола Долини Холодного Хребта, досвідчені розвідники пильно виглядають перспективних бійців. Стен Стаутарм передає камінь із написом — просту руну, — яку йому вручив Тран Корман. Цей виклик кличе бойових хлопців і дівчат із засніжених стежок долини до теплої ковальської зали Анвілмара, щоб офіційно присягнути воїнському ремеслу."},{t="Дун Мороґ, що змінюється",b="З'явившись до Трана, одразу бачиш суворі реалії сучасного Дун Мороґу. Досвідчений наставник говорить відверто про мінливий краєвид королівства: переселені гноми, що шукають прихистку після катастрофічних вибухів, які знищили Гномреґан, дворфи, що опановують чужоземні таємні мистецтва чи переймають людську відданість Святому Світлу, і повсякчасна загроза підземних трогів, що дряпаються в гірські кордони. В очах Трана тверда бойова дисципліна лишається підмурівком, потрібним, щоб усе це витримати."}},faq={{q="Що таке Проста Руна?",a="Проста Руна — невелика кам'яна плитка з написом, яку Стен Стаутарм передає від імені Трана Кормана. Це офіційне запрошення й настанова для нових воїнів — зайти досередини по справжній вишкіл.",al={"предмет проста руна","що робить руна","лор простої руни"}},{q="Хто такий Тран Корман?",a="Тран Корман — місцевий наставник воїнів в Анвілмарі в Долині Холодного Хребта. Він навчає воїнів-новачків з дворфів і гномів основ ближнього бою, дисципліни й дворфійської завзятості.",al={"хто такий тран","тран корман лор","тренер воїнів холодного хребта"}},{q="Чому гноми живуть у Дун Мороґу й Айронфорджі?",a="Гномів нещодавно вигнали з їхнього підземного технодива, Гномреґана, після того як вони, відчайдушно намагаючись відбити навалу трогів з глибин, спричинили катастрофічні радіоактивні вибухи. Уцілілі втекли вгору схилами гори й знайшли притулок у союзників-дворфів в Айронфорджі.",al={"чому гноми тут","гноми в айронфорджі","біженці гномереґана"}},{q="Чому Тран згадує трогів?",a="Троги — первісні, люті створіння, що нещодавно прорвалися в печери на поверхні в Долині Холодного Хребта й Дун Мороґу, розтривожені глибоко під землею. Вони безпосередньо загрожують місцевим поселенням і торговельним шляхам, тож захисники Анвілмара мусять пильнувати зі зброєю в руках.",al={"загроза трогів","чому навколо троги","троги холодного хребта"}},{q="Що Тран має на увазі, кажучи, що дворфи шанують Святе Світло?",a="Здавна прив'язані до гірських традицій предків і шанування титанів, дворфи за століття тісного союзу з людськими королівствами на кшталт Лордерону й Стормвінда дедалі більше переймали віру в Святе Світло й тепер готують власних паладинів і жерців.",al={"дворфи і святе світло","лор дворфів-паладинів","жерці дворфів"}},{q="Куди нести Просту Руну?",a="Руну треба віднести просто Транові Корману, який стоїть біля тренувального майданчика у великій залі-сховищі Анвілмара, трохи вище стежкою в Долині Холодного Хребта.",al={"куди здати просту руну","де тран корман","знайти трана"}}},fp="11,242,22.389.0,21.522.0,24.215.0,21.231.0,50.294.0,30.278.0,62.277.0,32.159.0"}
P.entries["quest:3107"] = {n="Освячена Руна",s="Освячена Руна — вступний виклик, який вручають дворфійським паладинам-початківцям у Долині Холодного Хребта. Передана Стеном Стаутармом від імені Бромоса Ґруммнера, вона знаменує офіційне прийняття послушника до Лицарів Срібної Длані.",h="Освячена Руна — вступний виклик, який вручають дворфійським паладинам-початківцям у Долині Холодного Хребта.",kw={"освячена руна","паладин","бромос ґруммнер","стен стаутарм","срібна длань","святе світло","анвілмар"},ang={["class:Paladin"]="Ця руна — ваш перший офіційний крок до Лицарів Срібної Длані, що встановлює ваш обов'язок спрямовувати Світло на захист Айронфорджа.",["race:Dwarf"]="Дворфійські паладини поєднують традиційну дворфійську стійкість із богослов'ям, якого навчили люди, вносячи непохитну рішучість у вчення Святого Світла."},sec={{t="Виклик до Анвілмара",b="Поки шукачі пригод-новачки винищують трогів і вовків довкола Долини Холодного Хребта, місцеві очільники пильно стежать за тими, хто виявляє хист до божественної бойової вправності. Стен Стаутарм вручає цю руну з написом молодим паладинам, наказуючи знайти Бромоса Ґруммнера в теплі Анвілмара. Це водночас і запрошення, і офіційне повідомлення, що сирий потенціал тепер треба загартувати дисципліною."},{t="Дворфи й Святе Світло",b="Хоч Лицарі Срібної Длані постали серед людей Лордерону, дворфи Айронфорджа прийняли філософію Святого Світла з палкою відданістю. Бромос Ґруммнер вітає послушників у братстві, нагадуючи, що дворфійські паладини тепер поділяють урочистий обов'язок захищати Азерот. Закорінений у жертовності, традиції й бойовій чесноті, орден вимагає, щоб новобранці взяли молот і віру рівною мірою."}},faq={{q="Що таке Освячена Руна?",a="Це знак з написом, який вручають паладинам-новачкам з дворфів у Долині Холодного Хребта: він велить з'явитися до Бромоса Ґруммнера в Анвілмарі по справжнє навчання.",al={"предмет освячена руна","що робить руна","руна паладина холодного хребта"}},{q="Хто такий Бромос Ґруммнер?",a="Бромос Ґруммнер — місцевий наставник паладинів в Анвілмарі. Він навчає нових дворфів — членів Лицарів Срібної Длані — і готує їх до небезпек, що загрожують Дун Мороґу.",al={"хто такий бромос","тренер паладинів анвілмар","бромос ґруммнер лор"}},{q="Чому дворфи входять до Лицарів Срібної Длані?",a="Під час Другої війни й після неї жерці й паладини з людей познайомили дворфів Айронфорджа із засадами Святого Світла. Дворфи глибоко шанують бойову дисципліну ордену й готовність жертвувати собою заради захисту Азерота.",al={"лор паладинів-дворфів","чому в дворфів паладини","дворфи срібної длані"}},{q="Хто дає вам Освячену Руну?",a="Стен Стаутарм передає вам руну біля Анвілмара, коли ви допоможете йому з місцевими справами, зауваживши, що Бромос Ґруммнер просив її доставити.",al={"де взяти руну","хто дає руну"}},{q="Де знайти Бромоса Ґруммнера?",a="Бромос Ґруммнер — у великій залі Анвілмара в Долині Холодного Хребта, поруч з іншими класовими наставниками.",al={"місце бромоса","де бромос","знайти бромоса ґруммнера"}},{q="Що буде, коли показати руну Бромосу?",a="Бромос визнає ваше прийняття до Срібної Длані й дає перше справжнє бойове й святе навчання, а тоді відпускає вас назад у Дун Мороґ.",al={"що далі","після освяченої руни"}}},fp="16,245,21.418.0,26.433.0,29.165.0,23.194.0,55.247.0,35.150.0,33.123.0,49.155.0"}
P.entries["quest:3108"] = {n="Гравірована Руна",s="Гравірована Руна — письмовий виклик, який вручають дворфійським мисливцям-новачкам, що допомагають варті в Долині Холодного Хребта. Переданий Стеном Стаутармом, камінь із написом скеровує слідопитів-початківців до Торґаса Ґрімсона в Анвілмарі, щоб офіційно розпочати бойовий і лісовий вишкіл.",h="Гравірована Руна — письмовий виклик, який вручають дворфійським мисливцям-новачкам, що допомагають варті в...",kw={"гравірована руна","мисливець","торґас ґрімсон","стен стаутарм","анвілмар","долина холодного хребта","вистежування"},ang={["class:Hunter"]="Ця руна розпочинає вашу подорож мисливця в Дун Мороґу, знайомлячи вас із Торґасом Ґрімсоном і засадничими дворфійськими традиціями вистежування, догляду за зброєю й виживання в дикій природі.",["race:Dwarf"]="Вирізьблювати послання в суцільному камені — вияв давньої дворфійської шани до тривкого ремесла, навіть для буденних викликів і польових вказівок."},sec={{t="Виклик у камені",b="Допомагаючи Стену Стаутарму з довколишніми загрозами в Долині Холодного Хребта, перспективні дворфійські мисливці отримують кам'яну табличку з написом, відому як Гравірована Руна. Замість передавати усні накази чи простий пергамент, дворфійські наставники воліють різьблені руни для офіційних послань. Руна велить одержувачу підбити підсумок своєї ранньої праці й з'явитися до Анвілмара по глибші настанови в мистецтві полювання."},{t="Традиції мисливця Дун Мороґу",b="Показати руну Торґасу Ґрімсону — означає для мисливця вступити до офіційної дисципліни. Торґас наголошує, що гірське ремесло й виживання в Каз Модані вимагають глибокої поваги до суворого довкілля: читати сліди в лютих заметах, доглядати зброю й набої, розуміти диких звірів, що никають скелями. Гравірований камінь — перший крок мисливця від самотнього блукальця з рушницею до учня досвідчених слідопитів Анвілмара."}},faq={{q="Що таке Гравірована Руна?",a="Це кам'яна табличка з написом, яку передають мисливцям-новачкам у Долині Холодного Хребта: письмове запрошення до справжнього навчання в Торґаса Ґрімсона в Анвілмарі.",al={"що таке гравірована руна","предмет гравірованої руни","значення руни"}},{q="Хто надсилає Гравіровану Руну?",a="Її надсилає наставник мисливців Торґас Ґрімсон, а вручає вам горянин Стен Стаутарм, коли ви доведете свою базову вправність біля Анвілмара.",al={"хто дав гравіровану руну","відправник гравірованої руни"}},{q="Куди нести Гравіровану Руну?",a="Несіть її Торґасові Ґрімсону — він у великій залі Анвілмара в Долині Холодного Хребта.",al={"куди йти","кому здати","місце торґаса"}},{q="Чому дворфи вживають руни, а не листи?",a="Дворфійська культура високо цінує роботу з каменем, традицію й довговічне ремесло. Послання й священні настанови, вирізьблені на кам'яних рунах, значно краще за крихкий пергамент витримують пронизливі вітри й суворі негоди Дун Мороґу.",al={"чому гравірована руна","лор рун дворфів"}},{q="Що буде, коли показати руну Торґасові Ґрімсону?",a="Торґас вітає вас серед дворфійських слідопитів, пояснює головні засади виживання серед мерзлих скель, догляду за спорядженням і пошани до диких звірів, а тоді пропонує навчити основних мисливських прийомів.",al={"чого вчить торґас","здати гравіровану руну"}},{q="Чи може будь-який клас отримати Гравіровану Руну?",a="Ні. Гравіровану Руну дають саме мисливцям-дворфам, які починають шлях у Долині Холодного Хребта. Інші класи отримують власні знаки, що спрямовують їх до відповідних наставників в Анвілмарі.",al={"чи лише для мисливців","чи воїни можуть гравіровану руну"}}},fp="11,289,18.443.0,35.466.0,24.175.0,26.172.0,32.104.0,44.243.0,58.235.0,38.218.0"}
P.entries["quest:3109"] = {n="Зашифрована Руна",s="Зашифрована Руна — закодоване послання, яке вручають майбутнім розбійникам, що роблять перші кроки в Долині Холодного Хребта. Передане Стеном Стаутармом, вигравіруване послання скеровує перспективні тіні до Анвілмара, щоб з'явитися до наставника розбійників Солма Гарґріна.",h="Зашифрована Руна — закодоване послання, яке вручають майбутнім розбійникам, що роблять перші кроки в Долині...",kw={"зашифрована руна","розбійник","солм гарґрін","стен стаутарм","анвілмар","шифр","долина холодного хребта"},ang={["class:Rogue"]="Ця руна — ваш перший офіційний контакт із мережею розбійників Дун Мороґу, що веде вас до Солма Гарґріна, щоб почати відточувати скрадання, бойові хитрощі й ремесло виживання.",["race:Dwarf"]="Солм вітає дворфів клану Айронфорджа в тінях, зауважуючи, що ніщо так не тримає оперативника живим у Дун Мороґу, як холодний клинок і темрява.",["race:Gnome"]="Солм закликає учнів виявляти побратимство до гномів, що знайшли прихисток у Долині Холодного Хребта після трагічної втрати їхнього дому в Гномреґані."},sec={{t="Послання в коді",b="Допомагаючи Стену Стаутарму на засніжених перевалах Долини Холодного Хребта, гострозорі розбійники отримують дивний гравірований камінь. Стен зізнається, що річ йому підкинули, щоб він її передав, і підозрює, що вона просто від Солма Гарґріна. Замість гукати через подвір'я, шукаючи потенційних розвідників і пройдисвітів, Солм використовує зашифровану руну, щоб перевірити обачність новачка й покликати його під дах."},{t="Під кроквами Анвілмара",b="В Анвілмарі Солм Гарґрін вітає новоприбулих оперативників у ремеслі. Він пропонує навчити маневрів, ударів і тонких мистецтв, що тримають оперативника живим і наповнюють його кишені монетою. Окрім гостріння кинджалів, Солм нагадує дворфійським розбійникам дбати про своїх переселених гномських союзників, які досі оговтуються після катастрофічного падіння Гномреґану."}},faq={{q="Хто надсилає Зашифровану Руну?",a="Автор руни — Солм Гарґрін, наставник розбійників у великій залі Анвілмара. Він доручає Стенові Стаутарму непомітно передавати її перспективним новобранцям надворі, на снігу.",al={"хто написав руну","відправник зашифрованої руни","хто дав стену руну"}},{q="Де знайти Солма Гарґріна?",a="Солм Гарґрін — у головній залі Анвілмара, кам'яної твердині посеред Долини Холодного Хребта в Дун Мороґу.",al={"де солм","місце солма гарґріна","знайти солма"}},{q="Навіщо потрібна ця руна?",a="Це вступний виклик для розбійників-новачків: він заохочує розшифрувати послання, з'явитися до класового наставника й почати опановувати складніші бойові прийоми й способи виживання.",al={"що робить руна","призначення зашифрованої руни","навіщо зашифрована руна"}},{q="Чому Солм згадує гномів?",a="Відколи Гномреґан спіткало лихо, гноми-біженці ділять Долину Холодного Хребта й Анвілмар із дворфами. Солм нагадує учням, що гномам довелося несолодко й їм треба допомогти облаштуватися на тимчасовій оселі.",al={"чому допомагати гномам","коментар солма про гномереґан"}},{q="Хто вручає руну гравцеві?",a="Стен Стаутарм передає камінь розбійникам у Долині Холодного Хребта, коли ті допоможуть йому з першими справами в долині.",al={"хто починає зашифровану руну","хто дає завдання зашифрованої руни"}},{q="Чи можуть цю руну отримати інші класи?",a="Ні. Зашифрована Руна призначена лише для розбійників-новачків, які починають свій шлях у Долині Холодного Хребта.",al={"чи лише для розбійників","чи воїни можуть зашифровану руну"}}},fp="14,248,17.392.0,24.381.0,29.185.0,29.124.0,33.196.0,33.232.0,33.146.0,36.106.0"}
P.entries["quest:311"] = {n="Повернення до Марлет",s="Повернення до Марлет — пустотливе завершення запеклої броварської ворожнечі в Дун Мороґу. Проникнувши до льоху Хараноса й підмінивши діжку вогняним Окропом Марлет, шукач пригод повертається до Села Брюнолл із трофейним барилом Громового Елю як незаперечним доказом.",h="Повернення до Марлет — пустотливе завершення запеклої броварської ворожнечі в Дун Мороґу.",kw={"повернення до марлет","марлет барліб'ю","село брюнолл","громовий ель","окріп барліброю","барило","харанос"},ang={["class:Rogue"]="Проникнути до охоронюваного льоху, щоб підмінити заборонені діжки, — кумедна перевірка скрадання й спритності рук серед засніжених пагорбів.",["race:Dwarf"]="Дворфійська культура має броварство за мистецтво й змагання честі, тож дрібне льохове шпигунство — справа великої місцевої гордості."},sec={{t="Здобич диверсії",b="Дворфійські суперництва рідко вирішуються дипломатією, коли на кону ель. Марлет Барліб'ю із Села Брюнолл плекає люту змагальну образу на ґуральників Хараноса, творців уславленого Громового Елю. Коли її міцний «Окріп» непомітно підкинуто до льоху Тандербрю, Марлет вимагає доказу подвигу. Винести справжнє барило Громового Елю з-під їхнього носа — і трофей, і козир."},{t="Гірке вариво залагоджено",b="Притягти важку діжку назад через засніжені хребти до Села Брюнолл — завершити витівку. Марлет у захваті від того, що задум удався, і зловтішно смакує тим, як перехитрила варту й льохових майстрів Хараноса. Хоч на поверхні витівка й нешкідлива, вона скріплює люту, безкомпромісну гордість, яку різні дворфійські родини вкладають у свої фірмові рецепти по всьому Дун Мороґу."}},faq={{q="Яка мета цього завдання?",a="Треба віднести вкрадену бочку Громового Елю Марлетові Барліб'ю в Село Брюнолл, щоб довести, що ви успішно підкинули його Окріп у льох у Хараносі.",al={"що робити","мета повернення до марлет","здати бочку"}},{q="Хто такий Марлет Барліб'ю?",a="Марлет — дворф-пивовар із Села Брюнолл. Він страшенно пишається родинними рецептами стаута й дріб'язково суперничає з пивоварами Тандербрю з Хараноса.",al={"хто така марлет","марлет лор","барліб'ю"}},{q="Звідки бочка?",a="Бочку забирають просто з льоху Ґуральні Тандербрю в Хараносі, підмінивши її в їхніх запасах Марлетовим Окропом.",al={"звідки бочка","льох хараноса","місце громового елю"}},{q="Де Село Брюнолл?",a="Село Брюнолл — на замерзлих берегах Озера Крижаного Потоку на заході Дун Мороґу, на північний захід від Хараноса.",al={"місце брюноллу","де брюнолл","як знайти марлет"}},{q="Чому Марлет ворогує з Хараносом?",a="Дворфійські пивовари запекло змагаються рецептами. Марлет хотів довести, що його власне вариво, Окріп, здатне перевершити чи осоромити славетний Громовий Ель від Тандербрю.",al={"чому суперники","марлет проти тандербрю","ворожнеча пивоварів"}},{q="Що Марлет робить із бочкою?",a="Бочка — передусім доказ, що підміну провернули під носом у вартових Хараноса, хоча Марлет, безперечно, радий залишити собі запаси суперника.",al={"навіщо красти громовий ель","що буде з елем"}}},fp="17,278,22.453.0,21.378.0,34.166.0,26.181.0,33.153.0,26.110.0,36.198.0,37.174.0"}
P.entries["quest:3110"] = {n="Освячена Руна",s="Освячена Руна — вступне завдання для дворфійських жерців-початківців у Долині Холодного Хребта. Стен Стаутарм передає руну з написом від наставника жерців Бранстока Калдера, яка кличе новачка до Анвілмара, щоб поглибити зв'язок зі Святим Світлом.",h="Освячена Руна — вступне завдання для дворфійських жерців-початківців у Долині Холодного Хребта.",kw={"освячена руна","жрець","брансток калдер","стен стаутарм","святе світло","анвілмар","долина холодного хребта"},ang={["class:Priest"]="Цей пергамент знаменує ваше офіційне визнання як служителя Святого Світла в Дун Мороґу й скеровує вас до Бранстока Калдера по найперші закляття.",["race:Dwarf"]="Дворфійські жерці поєднують глибоку відданість Світлу зі звичною гірською твердістю, і без них не втримати Долину Холодного Хребта проти трогів-загарбників."},sec={{t="Поклик до ряси",b="Поки новоприбулий жрець допомагає Стену Стаутарму розчищати найближчі загрози біля Анвілмара, він потрапляє на око духовному провідникові поселення. Брансток Калдер довіряє Стену освячену руну з молитвами й настановами, яка скеровує молодого шукача пригод до міцних зал Анвілмара, щоб офіційно розпочати священні студії."},{t="Захисники Холодного Хребта",b="Хоч дворфійська культура часто наголошує на бойовій стійкості й важкій броні, Святе Світло лишається наріжним каменем суспільства Айронфорджа. У Долині Холодного Хребта святі заклиначі відіграють життєво важливу роль поруч із воїнами й мисливцями, захищаючи анклав від зухвалих набігів трогів і небезпечної звірини, що підкрадається заметами."}},faq={{q="Що таке Освячена Руна?",a="Це жрецька руна з написом, яку Стен Стаутарм передає від імені Бранстока Калдера. Прочитавши її, молоді жерці знайомляться з першими молитвами, і вона заохочує їх шукати справжньої науки.",al={"що таке освячена руна","призначення руни"}},{q="Хто такий Брансток Калдер?",a="Брансток Калдер — дворф, наставник жерців в Анвілмарі. Відомий сухим гумором і непохитною вірою, він навчає молодих послушників і вчить їх основних святих заклять, щоб допомагати обороні Долини Холодного Хребта.",al={"брансток калдер","тренер жерців холодного хребта"}},{q="Де знайти Бранстока Калдера?",a="Він у головній кам'яній оселі Анвілмара, на центральній галявині Долини Холодного Хребта в Дун Мороґу.",al={"місце бранстока","де брансток"}},{q="Навіщо дворфам жерці в Долині Холодного Хребта?",a="Троги заполонили частину долини, і місцева варта покладається на цілющу силу й святі удари тих, хто володіє Світлом, щоб утримувати рубежі й лікувати поранених.",al={"навіщо дворфам жерці","жерці анвілмара"}},{q="Чи може будь-який клас узяти це завдання?",a="Ні. Освячену Руну дають лише молодим жерцям-дворфам, які починають свій шлях у Долині Холодного Хребта.",al={"хто отримує освячену руну","чи лише для жерців"}},{q="Хто вручає руну гравцеві?",a="Стен Стаутарм, горянин з Анвілмара, що наглядає за випробуваннями біля оселі, віддає руну, коли ви допоможете йому з першою обороною долини.",al={"хто починає освячену руну","роль стена стаутарма"}}},fp="13,258,22.364.0,22.331.0,26.202.0,25.229.0,34.123.0,48.168.0,30.116.0,36.148.0"}
P.entries["quest:3112"] = {n="Проста Службова Записка",s="Проста Службова Записка — послання, яке вручають майбутнім гномам-воїнам, що починають шлях у Долині Холодного Хребта. Передана Стеном Стаутармом надворі, вона скеровує новонавчених бійців до Анвілмара на зустріч із Траном Корманом, який пообіцяв підготувати їх до повернення Гномреґану.",h="Проста Службова Записка — послання, яке вручають майбутнім гномам-воїнам, що починають шлях у Долині...",kw={"проста службова записка","воїн","гном","тран корман","стен стаутарм","анвілмар","гномреґан"},ang={["class:Warrior"]="Це послання офіційно розпочинає бойову освіту гнома-воїна, установлюючи зв'язок із досвідченими майстрами зброї Айронфорджа.",["race:Dwarf"]="Дворфійські наставники на кшталт Трана Кормана ставлять біду гномів нарівні з власними давніми чварами, виявляючи глибоку солідарність із переселеними союзниками.",["race:Gnome"]="Записка підкреслює вигнання гномів із Гномреґану та їхню тиху рішучість вишколити воїнів, здатних повернути їхнє радіоактивне місто."},sec={{t="Виклик до Анвілмара",b="Поки молодий гном-воїн винищує трогів і вепрів, що дошкуляють Долині Холодного Хребта, для горянина Стена Стаутарма, він отримує коротке послання, підкинуте дворфові до рук. Розгледівши потенціал у новобранці-біженці, досвідчений наставник Тран Корман за допомогою записки кличе новачка до центральної зали Анвілмара, щоб розпочати справжній бойовий вишкіл."},{t="Обітниця солідарності",b="Хоч дворфійські наставники часом і підсміюються з гномів-воїнів через їхній крихітний зріст, Тран Корман ставиться до їхньої боротьби серйозно. Співчуваючи втраті Гномреґану, Тран порівнює біду гномів із тим, що відчули б дворфи, якби Айронфордж упав перед Темним Залізом. Дотримуючи слова, він присягається навчати бійців-вигнанців мистецтва війни, доки ті не будуть готові відвоювати свій дім."}},faq={{q="Що таке Проста Службова Записка?",a="Це вступна записка, яку Стен Стаутарм у Долині Холодного Хребта вручає воїнам-новачкам з гномів. Вона велить розшукати Трана Кормана — наставника воїнів у великій залі Анвілмара.",al={"проста службова записка","що за записка","завдання службової записки"}},{q="Хто надсилає записку?",a="Вона від Трана Кормана, місцевого дворфа-наставника воїнів в Анвілмарі. Він доручає Стенові Стаутарму передавати її перспективним бійцям, що допомагають горянам.",al={"хто написав службову записку","хто надіслав просту службову записку"}},{q="Чому Тран Корман навчає гномів-воїнів?",a="Тран дав слово допомагати гномам-вигнанцям. Він шанує їхню рішучість і щиро співчуває їхній трагедії, порівнюючи падіння Гномреґана з тим, як було б, якби Айронфордж захопив клан Темного Заліза.",al={"чому тран навчає гномів-воїнів","лор гномів-воїнів"}},{q="Де знайти Трана Кормана?",a="Тран Корман стоїть у головній залі Анвілмара — головного поселення Долини Холодного Хребта в Дун Мороґу.",al={"де тран корман","місце трана кормана"}},{q="Хто такий Стен Стаутарм?",a="Стен Стаутарм — дворф-горянин, що стоїть одразу біля Анвілмара в Долині Холодного Хребта й керує місцевою обороною від агресивних вепрів і трогів-загарбників.",al={"стен стаутарм","хто такий стен"}},{q="Чому гноми починають у Долині Холодного Хребта?",a="Після трагічного падіння й опромінення Гномреґана вцілілі гноми втекли біженцями на дворфійські землі. Анвілмар і Айронфордж відчинили двері, щоб прихистити їх, поки вони відновлюють сили.",al={"чому гноми в холодному хребті","гноми холодний хребет"}}},fp="17,274,21.363.0,22.406.0,30.211.0,25.181.0,44.231.0,30.124.0,21.166.0,44.208.0"}
P.entries["quest:3113"] = {n="Зашифрована Записка",s="Зашифрована Записка — вступний виклик для гномів-розбійників-початківців, що прибувають до Долини Холодного Хребта. Передана через Стена Стаутарма, замаскована записка тихо скеровує нових оперативників до Солма Гарґріна в Анвілмарі.",h="Зашифрована Записка — вступний виклик для гномів-розбійників-початківців, що прибувають до Долини Холодного...",kw={"зашифрована записка","розбійник","гном","солм гарґрін","стен стаутарм","анвілмар","гномреґан"},ang={["class:Rogue"]="Це завдання — перший поклик для гномів-розбійників, що знайомить їх із Солмом Гарґріном і філософією взаємного захисту, потрібною, щоб провадити таємне ремесло на дворфійських землях.",["race:Dwarf"]="Дворфійські горяни на кшталт Стена Стаутарма сприяють цьому зв'язку, показуючи практичну співпрацю між Айронфорджем і переселеними гномами в Долині Холодного Хребта.",["race:Gnome"]="Записка підкреслює біду гномських біженців після катастрофи в Гномреґані, показуючи, як уцілілі гуртуються, живучи гостями серед дворфів."},sec={{t="Непомітне знайомство",b="Поки новоприбулі гноми допомагають горянам Долини Холодного Хребта з місцевими загрозами від трогів, Стен Стаутарм передає згорнутий аркуш пергаменту, довірений йому потай. Зовні записка вдає офіційну службову записку, та насправді це запрошення зустрітися з Солмом Гарґріном, наставником розбійників, що служить в Анвілмарі."},{t="Спільні злигодні в снігу",b="Послання відображає неспокійну реальність, що постала перед гномами після раптового падіння Гномреґану. Витіснені з підземного дому, уцілілі гноми мусять тіснитися зі своїми дворфійськими господарями в Дун Мороґу. Солм Гарґрін розуміє, що розбійники привертають підозру, коли речі зникають, і обстоює мовчазну солідарність серед майстрів ремесла задля їхнього спільного виживання."}},faq={{q="Хто написав Зашифровану Записку?",a="Записку написав Солм Гарґрін, наставник розбійників в Анвілмарі. Він видав її за офіційне розпорядження згори, щоб Стен Стаутарм передав її, нічого не запідозривши.",al={"хто надіслав службову записку","хто написав записку","записка солма"}},{q="Навіщо записку замасковано?",a="Розбійники воліють стриманість, особливо в гамірній дворфійській твердині на кшталт Анвілмара. Солм Гарґрін не впадає в око, щоб уникнути чуток і звинувачень щоразу, як щось зникає, і звертається саме до своїх братів-шибеників шифрованими привітаннями.",al={"чому замасковано","чому зашифровано"}},{q="Що ця записка розкриває про становище в Дун Мороґу?",a="Розмова показує і тертя, і солідарність між гномами й дворфами після втрати Гномреґана. Тіснява, коли обидва народи скупчилися в Айронфорджі й Дун Мороґу, виснажує запаси, але Солм наголошує, що люди їхнього тіньового ремесла мусять пильнувати одне одного.",al={"стосунки гномів і дворфів","біженці гномереґана дун мороґ"}},{q="Хто вручає записку гравцеві?",a="Стен Стаутарм віддає документ, коли ви допоможете йому в Долині Холодного Хребта, вважаючи, що Солм Гарґрін надіслав його для вашого навчання.",al={"доставка стена стаутарма","хто вручає записку"}},{q="Яку роль виконує Солм Гарґрін?",a="Солм Гарґрін — наставник розбійників у гірській залі Анвілмара; він навчає нових розбійників бойових прийомів і тіньових умінь.",al={"роль солма гарґріна","що робить солм"}},{q="Чи пов'язане це завдання з падінням Гномреґана?",a="Так. Солм прямо згадує захоплений Гномреґан і наголошує, що, хоч гноми-розбійники й утратили свою механічну батьківщину, вони можуть вистояти, спираючись на спільне братерство.",al={"лор падіння гномереґана","статус біженців гномів"}}},fp="20,238,23.321.0,28.393.0,35.194.0,32.242.0,61.274.0,42.133.0,34.160.0,44.188.0"}
P.entries["quest:3114"] = {n="Гліфічний Меморандум",s="Гліфічний Меморандум — вступне завдання, що скеровує магів-новачків у Долині Холодного Хребта до їхнього місцевого наставника в Анвілмарі. Довірене горянину Стену Стаутарму, послання кличе початківців таємних мистецтв знайти ексцентричного гнома Марріка Нуррібіта, щоб розпочати офіційні студії заклять.",h="Гліфічний Меморандум — вступне завдання, що скеровує магів-новачків у Долині Холодного Хребта до їхнього...",kw={"гліфічний меморандум","маг","маррік нуррібіт","стен стаутарм","анвілмар","долина холодного хребта","навчання"},ang={["class:Mage"]="Це послання — ваше офіційне знайомство з навчанням таємних мистецтв у Дун Мороґу, що зводить вас напряму з вашим першим наставником.",["faction:Alliance"]="Злагоджена співпраця Стена Стаутарма й Марріка Нуррібіта ілюструє тісне партнерство дворфів і гномів, що ділять Долину Холодного Хребта.",["race:Gnome"]="Маррік Нуррібіт — один із кількох гномських фахівців, які після падіння Гномреґану знайшли прихисток на дворфійських землях, щоб навчати свого традиційного ремесла."},sec={{t="Послання для магів-новачків",b="Допомагаючи горянину Стену Стаутарму з ранніми обов'язками по Долині Холодного Хребта, новоприбулі маги отримують виклик від місцевого авторитету в таємних мистецтвах. Стен одержує письмовий меморандум, адресований заклиначеві-початківцю, і передає його, радячи знайти хвилинку, прочитати зміст і зайти в тепло Анвілмара, щоб зустрітися з автором."},{t="Навчання в Марріка Нуррібіта",b="Автор меморандуму — Маррік Нуррібіт, гном, наставник магів, що служить в Анвілмарі. Замість топити учня в густих теоретичних лекціях, Маррік дає прості, приземлені поради: не встрягайте в серйозні халепи, відкладайте монети на навчання й корчемні напої і суворо уникайте радіоактивної катастрофи, якою став полеглий Гномреґан. Коли основні очікування окреслено, Маррік готовий навчати новачків таємних мистецтв."}},faq={{q="Хто вручає цей меморандум?",a="Стен Стаутарм, горянин Альянсу з Долини Холодного Хребта, вручає вам меморандум, коли ви допоможете йому з першими справами.",al={"хто дає гліфічний меморандум","завдання стена стаутарма"}},{q="Хто такий Маррік Нуррібіт?",a="Маррік Нуррібіт — гном, наставник магів в Анвілмарі в Долині Холодного Хребта. Він навчає магів-новачків перших заклять і загальних правил чародійської безпеки.",al={"маррік","тренер магів анвілмара"}},{q="Де знайти Марріка Нуррібіта?",a="Маррік — у головній залі Анвілмара, центральної дворфійської застави на верхньому краю Долини Холодного Хребта в Дун Мороґу.",al={"місце марріка нуррібіта","де тренер магів у холодному хребті"}},{q="Чому Маррік застерігає від походів до Гномреґана?",a="Гномреґан нещодавно заполонили троги, а катастрофічний викид радіоактивного газу отруїв його, тож він смертельно небезпечний для кожного новачка, що блукає Дун Мороґом.",al={"попередження марріка про гномереґан","чому триматися подалі від гномереґана"}},{q="Які класи отримують це завдання?",a="Це завдання дають лише магам-новачкам, що починають шлях у Долині Холодного Хребта, щоб познайомити їх із класовим наставником.",al={"хто отримує гліфічний меморандум","чи лише для магів"}},{q="Чого Маррік чекає від учнів?",a="Вимоги Марріка прості: не вплутуватися в халепи, відкладати досить срібла, щоб платити за закляття й пригостити його елем, і триматися якомога далі від Гномреґана.",al={"очікування марріка","чого хоче тренер"}}},fp="18,304,26.362.0,29.436.0,29.139.0,23.157.0,33.134.0,49.171.0,31.138.0,42.176.0"}
P.entries["quest:3115"] = {n="Осквернений меморандум",s="Осквернений Меморандум — вступне завдання для гномів-чорнокнижників-початківців, що роблять перші кроки в Долині Холодного Хребта. Тихо передане через Стена Стаутарма, послання кличе неофіта в тіні Анвілмара на зустріч з Аламаром Гріммом, який проповідує самодостатність через темну силу, а не довіру до дворфів-господарів.",h="Осквернений Меморандум — вступне завдання для гномів-чорнокнижників-початківців, що роблять перші кроки в...",kw={"осквернений меморандум","чорнокнижник","гном","аламар грімм","стен стаутарм","анвілмар","гномреґан"},ang={["class:Warlock"]="Це послання знаменує ваш офіційний вступ до ремесла чорнокнижника, подаючи демонічні угоди не як божевілля, а як прагматизм, народжений виживанням.",["race:Dwarf"]="Дворфи-господарі терплять цих темних практиків під своїм дахом із відвертою відразою й гострою настороженістю.",["race:Gnome"]="Меморандум відображає глибоке приховане обурення, яке дехто з гномів-вигнанців відчуває через своє переселене становище й залежність від Айронфорджа."},sec={{t="Непомітний виклик",b="Навіть у замерзлій заставі Долини Холодного Хребта практику темних мистецтв зустрічають із глибокою підозрою. Допомагаючи Стену Стаутарму з місцевими загрозами, молоді гноми-чорнокнижники отримують підкинуту записку. Стен передає її неохоче, озвучуючи хистке перемир'я, яке дозволяє чорнокнижникам бути на землях Альянсу: «пильнуй себе… твоєму брату тут не надто довіряють»."},{t="Гномська гіркота у вигнанні",b="Відгукнувшись на записку, чорнокнижник зустрічає Аламара Грімма, що зачаївся в залах Анвілмара. Грімм не добирає слів щодо біди гномів. У його очах звичайне винахідництво й буденна магія геть підвели Гномреґан, довівши їхній народ майже до вимирання й лишивши його біженцями другого сорту, залежними від дворфійської доброї волі. Замість молитися Святому Світлу чи покладатися на дворфійську політику, Грімм закликає учня прикликати й підкорити бісів, що пропонують беззастережну покору."}},faq={{q="Що таке Осквернений Меморандум?",a="Це письмове послання, яке Стен Стаутарм у Долині Холодного Хребта вручає чорнокнижникам-новачкам з гномів. Воно велить розшукати Аламара Грімма — місцевого наставника чорнокнижників в Анвілмарі.",al={"осквернений меморандум","записка чорнокнижника дун мороґ","що за меморандум"}},{q="Чому в Долині Холодного Хребта не довіряють чорнокнижникам?",a="Дворфи та їхні союзники з Альянсу високо шанують традиційні чесноти на кшталт бойової честі й Святого Світла, а демонологію й магію тіні вважають за самою природою зіпсованими й небезпечними. Гноми-чорнокнижники живуть під хмарою глибокої суспільної підозри.",al={"чому дворфи не люблять чорнокнижників","упередження до чорнокнижників анвілмар"}},{q="Хто такий Аламар Грімм?",a="Аламар Грімм — гном, наставник чорнокнижників в Анвілмарі. Озлоблений падінням Гномреґана й приниженням від залежності від дворфійської милості, він навчає молодих гномів підкоряти демонічних слуг, щоб здобути власну силу.",al={"лор аламара грімма","хто такий аламар"}},{q="Чому Грімм критикує звичайну магію й техніку?",a="Грімм вважає, що звична інженерія й визнані школи магії підвели гномів під час катастрофи в Гномреґані й зробили їх залежними від покровителів-дворфів, які дбають про зв'язки з людьми більше, ніж про повернення гномської батьківщини.",al={"погляд грімма на гномереґан","чому темна магія замість інженерії"}},{q="Чи можуть чорнокнижники-дворфи отримати це завдання?",a="Ні. У Дун Мороґу шляхом чорнокнижника можуть іти лише гноми, тож цей виклик — лише для щойно прибулих гномів-практиків.",al={"дворф-чорнокнижник осквернений меморандум","чи дворфи можуть бути чорнокнижниками"}},{q="Де відбувається це завдання?",a="Завдання починається біля Стена Стаутарма в Долині Холодного Хребта й завершується в Анвілмарі — центральній твердині над долиною на південному заході Дун Мороґу.",al={"де аламар грімм","здати осквернений меморандум"}}},fp="18,326,18.373.0,27.513.0,31.174.0,48.248.0,20.232.0,53.235.0,38.131.0,33.156.0"}
P.entries["quest:3116"] = {n="Простий Сигіл",s="«Простий Сигіл» — вступний виклик для юних воїнів нічних ельфів у Тінедолі. Його передає Консерватор Ілталайн від імені наставниці Алііссії, і він офіційно знаменує перехід новобранця до бойового вишколу, щоб захищати молоде гілля Тельдрассила.",h="«Простий Сигіл» — вступний виклик для юних воїнів нічних ельфів у Тінедолі.",kw={"простий сигіл","воїн","алііссія","консерватор ілталайн","тінедол","алдрассил","тельдрассил"},ang={["class:Warrior"]="Це завдання знаменує ваш офіційний початок як воїна калдорей і знайомить вас із Алііссією — вашою першою наставницею в ратній справі.",["faction:Alliance"]="Порада Алііссії відображає перші спроби нічних ельфів прийняти на своєму гіллі інші раси Альянсу попри століття відособленості.",["race:NightElf"]="Сигіл говорить просто про стрімкі зміни довкола калдорей — від висадження Тельдрассила до відкриття усамітненої домівки для чужоземних союзників."},sec={{t="Заклик до зброї в Тінедолі",b="Довівши свої перші навички виживання в сутичках із неспокійною живністю Тінедола, юні воїни нічних ельфів одержують через Консерватора Ілталайна сигіл із написом. Цей знак — офіційне запрошення від Алііссії, місцевої наставниці воїнів, що стоїть на варті в Алдрассилі: вона кличе новачка виступити вперед і присвятити свою ратну силу захистові свого народу."},{t="Буремна нова доба",b="Коли ви приходите до Алііссії, вона вписує вишкіл воїна в тло стрімких і тривожних змін. Усього за кілька років нічні ельфи виростили Світове Дерево Тельдрассил, побачили, як підступна скверна ширилася серед лісових звірів і поблизу, і далеко, та знову з'єдналися з давніми землями предків, які вважали втраченими, — такими як Фералас. Перед лицем цих небезпек здібні захисники потрібні невідкладно."},{t="Відкрите гілля",b="Окрім ратної дисципліни, Алііссія готує юних калдорей до світу за межами їхньої затишної галявини. Вона радить новобранцям не судити упереджено чужинців інших рас, що прибувають на Тельдрассил. Застерігаючи, що не кожен мандрівник діє з чистих спонук, вона наголошує: союзники життєво важливі для захисту калдорей, — і закликає учнів виявляти розумну довіру, беручи на себе роль захисників."}},faq={{q="Що таке Простий Сигіл?",a="Це знак з написом від Алііссії, наставниці воїнів у Тінедолі; його вручають воїнам-новачкам з нічних ельфів, щоб покликати їх на справжній бойовий вишкіл.",al={"предмет простий сигіл","що за сигіл","сигіл воїна"}},{q="Хто посилає шукати Алііссію?",a="Консерватор Ілталайн вручає сигіл і спрямовує вас до Алііссії, коли ви виконаєте перші завдання з підтримання рівноваги в Тінедолі.",al={"хто дає простий сигіл","початок простого сигіла"}},{q="Де знайти Алііссію?",a="Алііссія — у безпечному притулку Тінедолу, біля величезного стовбура Алдрассила, де вона навчає молодих воїнів з нічних ельфів.",al={"місце алііссії","де алііссія","тренер воїнів тіньового яру"}},{q="Чому Алііссія каже, що воїни потрібні саме тепер?",a="Останні роки принесли важкі випробування: заснування Тельдрассила, скверну, що вражає місцевих звірів, і повторне відкриття давно втрачених земель на кшталт Фераласу. Потрібні вправні бійці, щоб захистити калдореїв від загроз, які насуваються.",al={"чому нічним ельфам потрібні воїни","лор воїнів тіньового яру"}},{q="Що Алііссія каже про інші раси, які відвідують Тельдрассил?",a="Вона застерігає від упереджень, пояснюючи, що невдовзі гілля Тельдрассила відвідають чужинці інших рас. Визнаючи, що не всі прибульці безкорисливі, вона радить виявляти до них певну довіру, щоб вони допомогли боронити дерево.",al={"алііссія про інші раси","нічні ельфи й чужинці","альянс на тельдрассилі"}},{q="Чому важливо, що згадано Фералас?",a="Фералас — давні землі нічних ельфів, від яких вони довго були відрізані чи вважали втраченими після Великого Розколу. Його повторне відкриття показує, як швидко калдореї відновлюють зв'язки з ширшим світом після тисячоліть ізоляції.",al={"чому фералас","зв'язок з фераласом"}}},fp="12,280,28.370.0,20.422.0,18.430.0,25.162.0,31.146.0,28.145.0,52.261.0,61.259.0,47.233.0"}
P.entries["quest:3117"] = {n="Гравірований Сигіл",s="«Гравірований Сигіл» — письмовий виклик, що його через Консерватора Ілталайна одержують юні мисливці нічних ельфів у Тінедолі. Він кличе їх угору, на могутнє гілля Алдрассила, до наставниці Аянни Еверстрайд, щоб офіційно ступити на шлях лучництва й звірознавства.",h="«Гравірований Сигіл» — письмовий виклик, що його через Консерватора Ілталайна одержують юні мисливці нічних...",kw={"гравірований сигіл","мисливець","аянна еверстрайд","консерватор ілталайн","тінедол","алдрассил"},ang={["class:Hunter"]="Це завдання знаменує ваше офіційне знайомство з мисливським наставництвом на Тельдрассилі й відчиняє двері до науки лука, вистежування та володарювання над звірами.",["race:NightElf"]="Для калдорей полювання — священна дисципліна, сплетена з гармонією природи й шануванням Елуни, а не проста розвага."},sec={{t="Виклик на гілля",b="Довівши свою ранню пильність у захисті Тінедола, юні мисливці калдорей одержують від Консерватора Ілталайна знак із написом. Гравірований сигіл, що його спершу приніс посланець від наставниці мисливців Аянни Еверстрайд, велить новачкові піднятися високо, до верхніх ярусів Алдрассила, звідки наставники пильнують крони."},{t="Шлях мисливця",b="Зустріч з Аянною — офіційний початок мисливського вишколу на Тельдрассилі. Вона навчає новачків двоєдиного мистецтва: влучної стрільби й розуміння диких створінь Калімдору. Аянна наголошує, що справжній мисливець має ставитися до своїх звірів-супутників із повагою, зберігаючи пильність і смирення у світі, повному незримих небезпек."}},faq={{q="Що таке Гравірований Сигіл?",a="Це послання з написом від наставниці мисливців Аянни Еверстрайд, що спрямовує перспективних новачків з нічних ельфів до її посту на Алдрассилі.",al={"гравірований сигіл","що за сигіл","предмет сигіл"}},{q="Де знайти Аянну Еверстрайд?",a="Її можна знайти на верхніх терасах Алдрассила — великого дерева-оселі посеред Тінедолу.",al={"де аянна","знайти аянну еверстрайд","місце аянни еверстрайд"}},{q="Хто видає Гравірований Сигіл?",a="Консерватор Ілталайн вручає його мисливцям з нічних ельфів, коли ті починають проявляти себе, захищаючи місцевий ліс.",al={"хто дає завдання","хто дає гравірований сигіл","де взяти гравірований сигіл"}},{q="Чого навчає Аянна Еверстрайд?",a="Вона навчає мисливців традицій влучної стрільби, поводження зі звірами й виживання в дикій природі, застерігаючи ніколи не недооцінювати небезпек на чужині.",al={"навчання мисливця","чого вчить аянна","чому говорити з аянною"}},{q="Чому Аянна застерігає мисливців щодо їхніх улюбленців?",a="Вона нагадує учням, що дика природа ховає загрози набагато грізніші, ніж уявляють новачки, тож мисливець мусить поважати своїх звірів-супутників, а не легковажно ставитися до їхніх здібностей.",al={"небезпека звірів","чому поважати звірів","застереження про улюбленців"}},{q="Чи доступне це завдання іншим класам?",a="Ні, Гравірований Сигіл — вступний класовий виклик лише для мисливців з нічних ельфів.",al={"чи друїди можуть це","чи лише для мисливців","інші класи"}}},fp="12,266,23.350.0,22.334.0,25.137.0,35.109.0,31.120.0,34.157.0,49.207.0,41.102.0"}
P.entries["quest:3118"] = {n="Зашифрований Сигіл",s="«Зашифрований Сигіл» — вступний виклик для новоявлених розбійників нічних ельфів, що прибувають до Тінедола. Його передає Консерватор Ілталайн від імені Фрагуна Шейдвіспера: він скеровує таємних оперативників розпочати вишкіл і пам'ятати, яким крихким є мир у Калімдорі.",h="«Зашифрований Сигіл» — вступний виклик для новоявлених розбійників нічних ельфів, що прибувають до Тінедола.",kw={"зашифрований сигіл","розбійник","фрагун шейдвіспер","консерватор ілталайн","тінедол","алдрассил","калімдор"},ang={["class:Rogue"]="Це завдання знаменує ваш вступ до мережі калдорей — розвідників, убивць і збирачів відомостей, яким доручено берегти Тельдрассил від незримих ворогів.",["faction:Alliance"]="Наставники Тінедола нагадують новобранцям, що угоди між фракціями крихкі, а розвідка — запорука того, щоб не допустити вторгнень Орди.",["race:NightElf"]="Навіть у затишному прихистку Алдрассила калдореї пильно стежать за мінливими кордонами Калімдору, щоб захистити своє щойно висаджене гілля."},sec={{t="Послання з тіні",b="Поки молодші нічні ельфи вивчають рівновагу природи під наглядом Консерватора Ілталайна, ті, хто схильний до скритності й хитрощів, одержують тихіший виклик. Зашифрований Сигіл приносить гонець від Фрагуна Шейдвіспера, наставника розбійників у Тінедолі. Списаний шифрами, зрозумілими лише посвяченим у ремесло, він велить власникові розгадати зміст і розшукати Фрагуна біля коріння Алдрассила, щоб офіційно розпочати навчання."},{t="Пильнуючи обрій",b="Послання Фрагуна — не просто запрошення на вишкіл; це тверезе застереження про розстановку сил у Калімдорі. Третя війна скінчилася, та мир між Альянсом і новопосталою Ордою тонкий, як папір. У Тінедолі розвідників і донощиків-розбійників закликають змалку розвивати очі й вуха, стежачи за можливими загрозами й таємними провокаціями, що здатні знову розпалити війну на кордонах."}},faq={{q="Що таке Зашифрований Сигіл?",a="Це шифрований знак від наставника розбійників Фрагуна Шейдвіспера для нових розбійників у Тінедолі: він велить з'явитися до нього під Алдрассил по справжній вишкіл.",al={"що за сигіл","завдання зашифрованого сигіла","предмет сигіл"}},{q="Хто вручає сигіл молодим нічним ельфам?",a="Консерватор Ілталайн вручає сигіл від імені Фрагуна, коли посвячений доведе базову вправність, упоравшись із місцевими звірами довкола гілля Тінедолу.",al={"хто дає завдання","хто дає зашифрований сигіл","консерватор ілталайн"}},{q="Де знайти Фрагуна Шейдвіспера?",a="Фрагун Шейдвіспер — під прихистком Великого Дерева Алдрассил у Тінедолі, готовий навчати щойно прибулих розбійників з нічних ельфів.",al={"де фрагун","знайти фрагуна шейдвіспера","місце фрагуна"}},{q="Навіщо розбійники в мирному Тельдрассилі?",a="Як зауважує Фрагун, перемир'я із зовнішніми силами хитке. Потайні розвідники й збирачі відомостей украй потрібні, щоб викривати підступи, — особливо щодо пересувань Орди та внутрішніх загроз гіллю.",al={"навіщо нічним ельфам розбійники","розбійники в тіньовому яру","мета розбійників"}},{q="Що буде, коли показати сигіл Фрагунові?",a="Фрагун приймає шифр, визнає вашу готовність і запрошує повертатися, коли наберетеся досвіду, щоб навчити вас бойових прийомів, володіння зброєю й мистецтва скрадання.",al={"що далі","після зашифрованого сигіла","нагорода сигіла"}},{q="Чи загрожує Орда безпосередньо Тінедолу?",a="Віддалене гілля Тельдрассила здебільшого недосяжне для відкритого нападу Орди, але чутки про агентів Орди, що сіють недовіру по всьому Калімдору, тримають вартових і агентів калдореїв насторожі.",al={"чи орда на тельдрассилі","загроза орди тінедолу","орда зерна недовіри"}}},fp="15,280,24.439.0,20.437.0,28.164.0,41.169.0,39.144.0,45.228.0,50.181.0,53.192.0"}
P.entries["quest:3119"] = {n="Освячений Сигіл",s="«Освячений Сигіл» — вступний виклик для юних жерців нічних ельфів, що починають вишкіл у Тінедолі. Консерватор Ілталайн передає послання від наставниці жерців Шанди, яка скеровує новачків шукати настанов в Алдрассилі, де вони вчаться володіти благодаттю Елуни.",h="«Освячений Сигіл» — вступний виклик для юних жерців нічних ельфів, що починають вишкіл у Тінедолі.",kw={"освячений сигіл","жрець","шанда","елуна","консерватор ілталайн","тінедол","алдрассил"},ang={["class:Priest"]="Цей обряд переходу зводить молодого жерця калдорей із Шандою й започатковує його офіційне навчання світлу та мудрості Елуни.",["faction:Alliance"]="Слова Шанди підкреслюють, як щойно укладені союзи в Альянсі приводять незнайомі раси й мандрівників просто на гілля Тельдрассила.",["race:NightElf"]="Жрецтво — осердя культури калдорей, керованої давніми традиціями місячної відданості, що вели цей народ тисячоліттями."},sec={{t="Покликання до служіння",b="Жерці в культурі нічних ельфів посідають священне місце як служниці й слуги богині місяця Елуни. Коли юний калдорей у Тінедолі виявляє хист до божественного світла й відданості, Консерватор Ілталайн довіряє йому освячений сигіл. Надісланий гінцем від наставниці жерців Шанди, цей знак — офіційне запрошення з'явитися до дерева Алдрассил і розпочати духовне навчання."},{t="Мінливий світ",b="Зустрівши Шанду, молодий послушник дізнається, що затишне святилище Тельдрассила переживає незвичні потрясіння. Шанда зауважує, що гілля Світового Дерева повниться мандрівниками, зокрема й представниками ширшого Альянсу, яким дозволено зустрітися з калдореями. Хоч великий світ і кличе, Шанда радить новачкам спершу дати раду бідам, що безпосередньо спіткали Тінедол, перш ніж вирушати до ширших конфліктів за його межами."}},faq={{q="Що таке Освячений Сигіл?",a="Це знак з написом, який наставниця жерців Шанда надіслала гінцем Консерваторові Ілталайну, щоб покликати жерця-новачка на навчання в Алдрассилі.",al={"предмет освячений сигіл","що за сигіл","сигіл шанди"}},{q="Хто така Шанда?",a="Шанда — наставниця жерців на Алдрассилі в Тінедолі. Вона навчає молодих жерців з нічних ельфів основних обрядів, дисциплін і молитов Сестринства Елуни.",al={"тренер жерців альдрассилу","хто така шанда"}},{q="Де знайти Шанду?",a="Шанда — у дуплистій основі Алдрассила, величезного центрального дерева в самому серці Тінедолу на Тельдрассилі.",al={"знайти шанду","куди здати освячений сигіл","місце шанди"}},{q="Чому члени Альянсу відвідують Тельдрассил?",a="Після Третьої війни нічні ельфи налагодили зв'язки з Альянсом. Чужинці інших рас починають прибувати на гілля Тельдрассила, щоб узгоджувати дії й радитися з калдореями, поки обидві сторони готуються до випробувань, що чекають на Азерот.",al={"альянс на тельдрассилі","чому чужинці на світовому дереві"}},{q="Що робити жерцеві після цього завдання?",a="Шанда радить жерцям допомагати місцевим захисникам і доглядачам по всьому Тінедолу й повертатися до неї щоразу, як треба буде вивчити нові молитви й прийоми.",al={"що далі після сигіла","після освяченого сигіла"}},{q="Чому це завдання дає Ілталайн?",a="Консерватор Ілталайн наглядає за першими випробуваннями новачків у Тінедолі. Коли гонець від Шанди приніс сигіл, Ілталайн притримав його, доки жрець-початківець не довів, що готовий до наступних кроків.",al={"консерватор ілталайн жрець","чому говорити з ілталайн"}}},fp="14,305,20.428.0,16.449.0,27.161.0,14.184.0,24.118.0,45.236.0,51.159.0,36.218.0"}
P.entries["quest:312"] = {n="Вкрадені припаси Тундри МакҐранна",s="Тундра МакГранн, поранений дворфійський мисливець, що живе серед холодних скель Дун Мороґу, втратив зимові припаси через сумнозвісного місцевого звіра. Велетенський єті, відомий як Старий Айсбірд, затягнув посилену торієм м'ясну скриню МакГранна до свого лігва. Не в змозі наздогнати звіра на хворій нозі, мисливець покладається на подорожніх шукачів пригод, які прослизнуть усередину й повернуть його харчі.",h="Тундра МакГранн, поранений дворфійський мисливець, що живе серед холодних скель Дун Мороґу, втратив зимові...",kw={"вкрадені припаси","тундра макгранн","старий айсбірд","єті","м'ясна скриня","торій","дун мороґ"},ang={["class:Hunter"]="Побратими-слідопити поспівчувають біді МакГранна: місяці старанного оброблення й зберігання дичини зведені нанівець звіром-опортуністом, поки він вистежував оленів.",["class:Rogue"]="МакГранн навмисне шукає скрадливих мандрівників, тож ця крадіжка — хрестоматійна робота для розвідників, здатних прослизнути за спиною Старого Айсбірда, так і не оголивши клинка.",["race:Dwarf"]="Кожен дворф у Дун Мороґу знає безжальну жорстокість гірської зими: без збереженого м'яса чи прихистку навіть загартований горянин не витримає морозу."},sec={{t="Зимові запаси й украдені скрині",b="Пережити суворі зими Дун Мороґу можна лише з підготовкою, особливо горянам, що живуть поза теплом Хараноса й Айронфорджа. Тундра МакГранн старанно засолив цілий місячний запас в'яленого м'яса, щоб перебути хуртовини холодної пори. Остерігаючись голодних диких ведмедів, він запечатав харчі в посиленій торієвій м'ясній скрині. На жаль, він не врахував суцільної сили гірських єті, які понесли всю скриню замість ламати її на місці."},{t="Лігво Старого Айсбірда",b="Винуватець крадіжки — Старий Айсбірд, грізний і лютий єті, що зачаївся серед зубчастих пагорбів. Поки МакГранн полював на оленів, Айсбірд ухопив скриню й затягнув її до своєї гірської печери. Хоч МакГранн і певен, що навіть єті не розтрощить суцільне торієве обшиття, через поранену ногу похід по неї для нього був би самогубством. Кожен сміливець, що зважиться зайти до печери, мусить або зітнутися зі звіром напряму, або ретельно вибрати мить, поки чудовисько никає заметами."}},faq={{q="Хто такий Тундра МакГранн?",a="Тундра МакГранн — дворф-трапер і мисливець, що живе на засніжених просторах Дун Мороґу. Він береже хвору ногу й покладається на свої заготовлені запаси, щоб пережити сувору зиму.",al={"тундра макґранн","макґранн","хто такий макґранн"}},{q="Хто вкрав скриню з м'ясом МакГранна?",a="Скриню поцупив грізний місцевий єті, знаний як Старий Айсбірд, поки МакГранн полював на оленів, і затягнув важку торієву скриню у своє гірське лігво.",al={"хто вкрав скриню","хто забрав м'ясо","злодій запасів"}},{q="Чому МакГранн не може сам повернути своє м'ясо?",a="У МакГранна поранена нога, що дуже сковує його рухи. Він знає, що не зможе досить швидко й тихо пробратися в печеру Старого Айсбірда й вибратися звідти, не потрапивши йому в лапи.",al={"чому макґранн сам не може","нога макґранна","хвора нога"}},{q="Чи з'їв єті харчі?",a="Ні. В'ялене м'ясо замкнене в міцній скрині із суцільного торію. Єті вдалося потягти важку скриню, але пробити метал він не може.",al={"чи єті з'їв харчі","чи старий айсбірд відкриє скриню"}},{q="Чи доведеться битися зі Старим Айсбірдом, щоб забрати скриню?",a="Ні, битися не обов'язково. Старий Айсбірд частенько виходить зі свого лігва, і спритні шукачі пригод можуть непомітно прокрастися в печеру й забрати скриню.",al={"чи можна пройти повз айсбірда","чи треба вбивати айсбірда"}},{q="Де лежить украдений запас?",a="Украдена скриня з м'ясом — глибоко в гірській печері Старого Айсбірда, серед пагорбів біля табору МакГранна в Дун Мороґу.",al={"де печера","місце печери айсбірда"}}},fp="30,373,32.541.0,18.519.0,23.186.0,33.155.0,46.194.0,26.184.0,57.189.0,34.127.0"}
P.entries["quest:3120"] = {n="Зелений Сигіл",s="«Зелений Сигіл» — письмовий виклик для щойно пробуджених друїдів нічних ельфів у Тінедолі. Консерватор Ілталайн передає його, щоб скерувати новоявлених майстрів перевтілення до Марданта Стронґоука в гіллі Алдрассила. Він знаменує офіційний початок навчання друїда таємницям природи й Смарагдового Сну.",h="«Зелений Сигіл» — письмовий виклик для щойно пробуджених друїдів нічних ельфів у Тінедолі.",kw={"зелений сигіл","друїд","мардант стронґоук","консерватор ілталайн","тінедол","алдрассил","смарагдовий сон"},ang={["class:Druid"]="Це завдання — ваше офіційне посвячення у вчення Кола Кенарія під проводом Марданта Стронґоука, що виводить вас на довгий шлях пізнання Смарагдового Сну.",["race:NightElf"]="Друїдизм глибоко вплетений у культуру нічних ельфів; показати цей сигіл в Алдрассилі — перший крок посвяченого в давню традицію."},sec={{t="Поклик гілля",b="Щойно юний нічний ельф виявляє хист до підтримання рівноваги в Тінедолі, його належить офіційно представити ордену. Консерватор Ілталайн одержує Зелений Сигіл від гінця й довіряє його посвяченому. Цей маленький знак означає, що коло в Алдрассилі звернуло на нього увагу й запрошує молодого друїда офіційно розпочати навчання."},{t="Єднання і Сон",b="Коли посвячений показує сигіл Мардантові Стронґоуку всередині Алдрассила, його приймають до кола. Глибше єднання зі Смарагдовим Сном і опанування звіриних подоб ще попереду, та Мардант стає його першим провідником, якому доручено навчити тлумачити духів природи й спрямовувати первісну силу лісу."}},faq={{q="Що таке Зелений Сигіл?",a="Це виклик з написом, який Консерватор Ілталайн передає від імені Марданта Стронґоука: він кличе друїда-новачка почати справжнє навчання в Алдрассилі.",al={"предмет зелений сигіл","що за сигіл","сигіл друїда"}},{q="Куди нести Зелений Сигіл?",a="Несіть його Мардантові Стронґоуку — наставникові друїдів у великому дереві-оселі Алдрассил у серці Тінедолу.",al={"де мардант","здати зелений сигіл","куди йти"}},{q="Чому Мардант згадує Смарагдовий Сон?",a="Друїди черпають чимало сили й мудрості зі Смарагдового Сну під час тривалих сонних трансів. Новачок ще не готовий вільно блукати Сном, але Мардант знайомить його з ним як з основною таємницею, яку той зрештою вивчатиме.",al={"чому смарагдовий сон","діалог марданта про сон","друїдський транс"}},{q="Хто надсилає сигіл Ілталайнові?",a="Гонець, якого послав Мардант Стронґоук, приніс сигіл Консерваторові Ілталайну, щоб той вручив його просто в руки перспективному молодому друїдові.",al={"хто надіслав сигіл","гонець сигіла"}},{q="Що буде, коли показати сигіл?",a="Мардант Стронґоук стає вашим головним наставником у Тінедолі: у нього ви вивчатимете перші друїдські закляття й магічні прийоми, у міру того як зростатиме ваша сила.",al={"чого навчуся далі","після зеленого сигіла"}},{q="Чи можуть це завдання отримати не друїди?",a="Ні. Зелений Сигіл призначений лише для друїдів з нічних ельфів, що починають свій шлях у Тінедолі. Інші класи отримують власні виклики до своїх наставників.",al={"чи лише для друїдів","хто отримує зелений сигіл"}}},fp="13,326,20.364.0,23.330.0,26.170.0,34.128.0,43.235.0,34.157.0,40.156.0,34.178.0"}
P.entries["quest:313"] = {n="Сиве Лігво",s="Пілот Стоунґір із Хараноса шукає когось зі справжньою дворфійською твердістю, щоб облаштувати свою улюблену облогову машину Троллплоу. Щоб перевірити витримку майбутнього шукача пригод, він посилає його на захід, у небезпечну печеру, відому як Сиве Лігво, полювати на диких вендиґо заради їхніх густих шкур.",h="Пілот Стоунґір із Хараноса шукає когось зі справжньою дворфійською твердістю, щоб облаштувати свою улюблену...",kw={"сиве лігво","пілот стоунґір","вендиґо","троллплоу","шкури","склад стілґрила","харанос"},ang={["profession:Engineering"]="Кожен, хто цінує ремесло дворфійських облогових машин, знає: утримувати важку техніку на морозі вимагає творчих рішень для тепла в кабіні.",["race:Dwarf"]="Для молодих горян і шукачів пригод Айронфорджа вийти проти вендиґо Сивого Лігва — квінтесенція місцевого обряду посвяти.",["race:Gnome"]="Жити пліч-о-пліч із дворфами довкола Хараноса — означає долучатися до спорядження важких броньованих машин Айронфорджа."},sec={{t="Перевірка твердості",b="Керувати велетенським дворфійським облоговим танком — потрібні залізні нерви й міцна будова тіла, щоб витримувати механізми, від яких цокотять зуби, на крижаному гірському повітрі. Пілот Стоунґір, що служить на Складі Стілґрила біля Хараноса, заявляє, що має і те, й те з лишком. Замість роздавати роботу чи повагу за так, він кидає новачкам виклик: довести, що в них така сама непохитна вдача, вирушивши в замерзлі пагорби назустріч тутешнім звірам."},{t="Затишок у Троллплоу",b="Облогова машина Стоунґіра носить горде й анітрохи не скромне ім'я Троллплоу, але її тісна, обшита залізом кабіна люто холодна в суворому кліматі Дун Мороґу. Стоунґір знаходить практичне, хоч і дике розв'язання: шкура вендиґо. Густі гриви, зняті з лютих вендиґо, що никають Сивим Лігвом, дають матеріал для міцного теплого килима на палубу Троллплоу, а заразом тримають поголів'я місцевих звірів у межах."}},faq={{q="Хто такий Пілот Стоунґір?",a="Пілот Стоунґір — дворф, водій облогової машини, що стоїть біля Хараноса в Дун Мороґу. Він керує броньованою бойовою машиною, яку лагідно охрестив Тролеорачем, і неабияк пишається своїми залізними нервами й механічним ремеслом.",al={"пілот стоунґір","хто дає завдання","хто такий стоунґір"}},{q="Де розташоване Сиве Лігво?",a="Сиве Лігво — засніжена мережа печер у горах просто на захід від Хараноса. Це сумнозвісне лігво лютих вендиго Дун Мороґу.",al={"місце сивого лігва","де печера вендиго","як знайти сиве лігво"}},{q="Навіщо Стоунґірові гриви вендиго?",a="Стоунґір хоче з густого теплого хутра вендиго зробити затишний килимок для кабіни своєї облогової машини, Тролеорача, а заразом перевірити відвагу шукача пригод.",al={"навіщо гриви вендиго","призначення грив","для чого гриви"}},{q="Що таке Тролеорач?",a="Тролеорач — особиста облогова машина Пілота Стоунґіра. Її войовнича назва відбиває давню боротьбу дворфів Айронфорджа з ворожими тролями-Морозогривами, що населяють довколишні скелі.",al={"тролеорач","танк стоунґіра","що таке тролеорач"}},{q="Які створіння живуть у Сивому Лігві?",a="У печері живуть люті вендиго — дикі, мавпоподібні звірі, корінні мешканці засніжених висот Дун Мороґу, що люто боронять свою землю від усіх, хто туди вдереться.",al={"монстри сивого лігва","хто живе в сивому лігві"}},{q="Чи небезпечні вендиго для Хараноса?",a="Вендиго рідко влаштовують злагоджені напади, як тролі-Морозогриви, але через свою люту вдачу й близькість до головних шляхів вони — постійна небезпека і для мандрівників, і для місцевих ремісників.",al={"чи вендиго загрожують харанос","небезпека вендиго"}}},fp="16,281,14.425.0,30.426.0,23.224.0,34.163.0,38.185.0,18.206.0,48.167.0,39.204.0"}
P.entries["quest:314"] = {n="Захист отари",s="Захист отари — завдання, яке дає Рудра Амберстілл на Ранчо Амберстілл у Дун Мороґу. Лютий хижий звір на ім'я Ваґаш ночами нападає на цінних гірських баранів ранчо, а оскільки військовий гарнізон Айронфорджа розтягнутий по всьому королівству, місцеві заводчики мусять покладатися на захист подорожніх шукачів пригод.",h="Захист отари — завдання, яке дає Рудра Амберстілл на Ранчо Амберстілл у Дун Мороґу.",kw={"захист отари","рудра амберстілл","ранчо амберстілл","ваґаш","барани","хижак","дун мороґ"},ang={["class:Hunter"]="Вистежити такого сумнозвісного верховного хижака, як Ваґаш, у його гірському лігві — класичний полігон для будь-якого слідопита, що відточує навички в заметах Дун Мороґу.",["faction:Alliance"]="Поки полки Високого Престолу відтягнуто на підтримку зобов'язань Альянсу по всіх Східних Королівствах, допомога скрутним сільським обійстям стабілізує домашній фронт.",["race:Dwarf"]="Для дворфійських мандрівників захистити Ранчо Амберстілл — означає захистити тих самих гірських баранів, що несуть ваших родичів у бій по всьому Каз Модану."},sec={{t="Загроза для ранчо",b="Ранчо Амберстілл постачає гірських баранів, що слугують знаковими їздовими й робочими тваринами дворфів Бронзбірдів. Утримувати ці отари життєво важливо для сільського господарства Дун Мороґу. Коли впала ніч і над загонами розляглися відчайдушні крики, родина Амберстілл виявила, що двоє їхніх цінних баранів зникли. Винуватець — Ваґаш, сумнозвісний і дикий звір, що зачаївся в сусідніх скелях над ранчо й відомий тим, що люто полює на місцеву худобу."},{t="Виснажена оборона",b="Зазвичай місцевими загрозами такого масштабу займалися б дворфійські горяни чи королівські сили Короля Маґні Бронзбірда. Проте регулярне військо Айронфорджа нині розтягнуте по далеких кордонах на підтримку ширшого Альянсу. Лишившись без офіційного військового загону, щоб патрулювати хребти, Рудра Амберстілл змушений просити незалежних бійців вистежити Ваґаша й принести одне з його смертоносних ікол як доказ."}},faq={{q="Хто такий Ваґаш?",a="Ваґаш — небезпечне хиже чудовисько, що никає засніженими хребтами просто над Ранчо Амберстілл. Його бояться через неймовірну силу й ненажерливість, і він смертельно загрожує і свійським отарам баранів, і необачним мандрівникам на сході Дун Мороґу.",al={"що таке ваґаш","чудовисько ваґаш","ваґаш лор"}},{q="Де знайти Ваґаша?",a="Ваґаш влаштував лігво в засніженій печері високо серед скель над Ранчо Амберстілл. Підніміться засніженим пагорбом одразу за соснами позаду садиби — і опинитеся просто біля входу до його лігва.",al={"місце ваґаша","де ваґаш","знайти ваґаша"}},{q="Чому цим не займається варта Айронфорджа?",a="Сили короля Маґні Бронзбірда нині розпорошені: вони боронять стратегічні гарнізони й підтримують далекі походи Альянсу. Тож сільські садиби на кшталт Ранчо Амберстілл мусять самі себе захищати або наймати вправних шукачів пригод.",al={"чому немає вартових","де армія айронфорджа","чому допомагати амберстілу"}},{q="Хто такий Верон, якого згадує Рудра?",a="Верон Амберстілл — майстер-баранівник на ранчо, що навчає й доглядає славетних верхових баранів Бронзбірдів. Рудра каже, що Верон неймовірно полегшено зітхне, коли хижака, який полює на їхніх цінних тварин, буде знищено.",al={"хто такий верон","верон амберстіл","верон"}},{q="Навіщо потрібен доказ убивства?",a="Рудра просить ікло Ваґаша, щоб без жодного сумніву переконатися: убито саме те чудовисько, що тероризувало їхні отари, а не якогось звичайного хижака з гірських схилів.",al={"чому ікло ваґаша","ікло ваґаша","який доказ"}},{q="Яке значення мають барани для Дун Мороґу?",a="Гірські барани — витривалі, впевнені на ногах тварини, напрочуд пристосовані до мерзлих скелястих країв Каз Модану. Для дворфійського королівства вони — незамінні тяглові тварини, джерело вовни й верхові скакуни кінноти.",al={"чому барани важливі","призначення баранів амберстіла","лор дворфійських баранів"}}},fp="19,335,21.456.0,17.452.0,14.250.0,26.210.0,47.246.0,32.240.0,34.185.0,47.216.0"}
P.entries["quest:315"] = {n="Ідеальне темне пиво",s="Реджолд Барліброю із Села Брюнолл твердо вирішив зварити довершений дворфійський стаут, поєднавши родинну броварську традицію з екзотичними місцевими інгредієнтами. Щоб довершити експериментальний рецепт, він шукає мерехтраву — різку рослину, яку вирощують лише ворожі тролі Морозогриви на Мерехтливому Хребті. Відважних мандрівників посилають до тролячого табору, щоб поцупити зілля просто з племінних кошиків.",h="Реджолд Барліброю із Села Брюнолл твердо вирішив зварити довершений дворфійський стаут, поєднавши родинну...",kw={"ідеальне темне пиво","реджолд барліброю","мерехтрава","стаут","село брюнолл","мерехтливий хребет","морозогриви"},ang={["profession:Herbalism"]="Хоч мерехтрава й не стандартне ремісниче зілля, унікальні ботанічні риси цієї морозостійкої рослини роблять її цікавою дивовижею серед замерзлих скель Дун Мороґу.",["race:Dwarf"]="Броварство для клану Бронзбірдів майже священне, і знайти екзотичне дике зілля, щоб перевершити суперницькі корчми, вважається шляхетною справою."},sec={{t="Амбіції бровара",b="У Селі Брюнолл броварство — більше ніж ремесло, це спосіб життя, особливо для родини Барліброю. Реджолд Барліброю вірить, що броварська велич у нього в крові, та щоб досягти легендарного «ідеального стауту», потрібне нестандартне новаторство. Замість покладатися лише на звичайний хміль, солод і гірську джерельну воду, Реджолд звертає погляд на дику флору Дун Мороґу, щоб надати своєму елю неповторної гостроти."},{t="Троляче зілля Мерехтливого Хребта",b="Таємний інгредієнт, якого жадає Реджолд, — мерехтрава, морозостійка рослина, яку тролі Морозогриви вирощують на Мерехтливому Хребті на північному заході. Поки Морозогриви збирають її для своїх племінних і містичних ритуалів, дворфи не мали з неї практичної користі, хіба що зауважили її різкий, прикметний смак. Поцуплене просто зі сховкових кошиків у тролячому селищі, зілля стає осердям найновішого й найсміливішого бродильного експерименту Реджолда."}},faq={{q="Що таке мерехтлива трава?",a="Мерехтлива трава — особлива рослина, яку вирощують і збирають тролі-Морозогриви на Мерехтливому Хребті. Тролі вживають її передусім у племінних обрядах і ритуалах, а Реджолд Барліброю хоче випробувати її гострий, незвичний смак як нетипову приправу в дворфійському пивоварінні.",al={"лор мерехтливої трави","що робить мерехтлива трава","рослина морозогривів"}},{q="Де розташований Мерехтливий Хребет?",a="Мерехтливий Хребет — на засніжених висотах на північний захід від Села Брюнолл у Дун Мороґу. Це укріплений табір корінних тролів-Морозогривів, тож кожна вилазка по траву туди — небезпечний похід на ворожу землю.",al={"місце мерехтливого хребта","де мерехтливий хребет","як знайти мерехтливий хребет"}},{q="Чому Реджолд хоче красти в тролів-Морозогривів?",a="Тролі-Морозогриви — єдині, хто вирощує мерехтливу траву в Дун Мороґу, а напруга між дворфами й тролями унеможливлює мирну торгівлю. Рослини вже зібрані й складені в племінні кошики в їхньому таборі, тож прокрастися чи пробитися туди й забрати їх — єдиний вихід для Реджолда.",al={"чому красти в тролів","чому кошики тролів","план реджолда щодо тролів"}},{q="Хто такий Реджолд Барліброю?",a="Реджолд Барліброю — честолюбний дворф-пивовар із Села Брюнолл. Вірний своєму родовому імені, він присвятив ремесло пошукові рецепта ідеального темного пива й постійно експериментує з новими смаками й міцними дикими складниками.",al={"хто такий реджолд","реджолд барліброю","родина барліброю"}},{q="Чи вважається мерехтлива трава алхімічною травою?",a="Ні. Мерехтлива трава — не алхімічний реагент, який збирають у дикій природі. Це предмет для завдання, що зберігається в плетених кошиках і схованках по всіх поселеннях Морозогривів на Мерехтливому Хребті.",al={"чи травники можуть зібрати мерехтливу траву","чи мерехтлива трава зілля","збір мерехтливої трави"}},{q="Що стається з мерехтливою травою, коли її віддати?",a="Реджолд кидає свіжозібрану мерехтливу траву просто в чан, де бродить пиво в Селі Брюнолл, сподіваючись, що її особливий смак нарешті відкриє бездоганний рецепт, який він так довго шукав.",al={"чи вдасться стаут","результат варива реджолда","пиво з мерехтливої трави"}}},fp="17,402,19.424.0,31.459.0,20.281.0,31.242.0,56.313.0,25.248.0,42.182.0,47.191.0"}
P.entries["quest:317"] = {n="Запаси для Джетстіма",s="Запаси для Джетстіма — завдання Альянсу, яке пропонує Пілот Беловфіз на Складі Стілґрила в Дун Мороґу. Готуючи свою облогову машину до тривалого розгортання з Обложною Бригадою Айронфорджа, пілот залучає місцевих мисливців, щоб ті зібрали м'ясо вепрів і ведмежі шкури на харчі для екіпажу.",h="Запаси для Джетстіма — завдання Альянсу, яке пропонує Пілот Беловфіз на Складі Стілґрила в Дун Мороґу.",kw={"запаси для джетстіма","пілот беловфіз","джетстім","облогова бригада","вепряче м'ясо","ведмежі шкури","склад стілґрила"},ang={["faction:Alliance"]="Співпраця дворфійських ремонтних дворів і броньованих екіпажів Облогової Бригади тримає передову облогову техніку Альянсу в робочому стані.",["profession:Cooking"]="Збір товстих шматків вепрячого м'яса в заметах Дун Мороґу підкреслює головну дичину, що годує місцеві гірські гарнізони.",["race:Dwarf"]="Дичина зі скель Дун Мороґу тримає дворфійські екіпажі Облогової Бригади ситими й відпочилими, поки вони працюють у машинних дворах Каз Модану.",["race:Gnome"]="Допомога Беловфізу тримає дворфійську Облогову Бригаду — механізованого союзника Айронфорджа для гномів-вигнанців — повністю спорядженою для довгих походів попереду."},sec={{t="Спорядження машини",b="Пілот Беловфіз, що служить просто біля Хараноса на Складі Стілґрила, наглядає за підготовкою до майбутньої далекої операції Облогової Бригади. Його облоговий танк на ім'я Джетстім потребує і механічного налаштування від майстра-інженера Белдіна Стілґрілла, і місячного запасу польових харчів, щоб екіпаж лишався дієздатним у суворих морозах Дун Мороґу."},{t="Полювання на снігових полях",b="Оскільки Белдін Стілґрілл порпається під капотом Джетстіма, Беловфіз не може покинути машину, щоб зібрати харчі й утеплення. Він скеровує мандрівників полювати на засніжених рівнинах на південь від Сивого Лігва, де тутешні вепри дають поживне м'ясо на їжу, а місцеві ведмеді — густі шкури, що годяться на теплу постіль у танку."}},faq={{q="Що таке Джетстім?",a="Джетстім — облоговий танк, яким керує дворф Пілот Беловфіз. Він стоїть на Складі Стілґрила, де його налаштовують і споряджають для тривалого бойового походу від імені Облогової Бригади Айронфорджа.",al={"що таке джетстім","хто такий джетстім","що таке реактивний струмінь","танк беловфіза"}},{q="Хто такий Пілот Беловфіз?",a="Пілот Беловфіз на прізвисько Фіззер — дворф, пілот облогової машини з Облогової Бригади Айронфорджа. Поки його машину механічно налаштовують на Складі Стілґрила, він збирає польові припаси для майбутнього завдання.",al={"пілот беловфіз","беловфіз","хто такий пілот беловфіз"}},{q="Де зібрати потрібні припаси?",a="Пілот Беловфіз радить мисливцям засніжені рівнини на південь від Сивого Лігва — там водяться вепри й ведмеді, чиє м'ясо й шкури дадуть достатньо харчів і постелі.",al={"де кабани","де ведмеді","місце полювання","м'ясо кабана дун мороґ"}},{q="Що таке Облогова Бригада?",a="Облогова Бригада — корпус пілотів облогових машин Айронфорджа, що керують важкоброньованими бойовими машинами на кшталт Джетстіма й Тролеорача, підтримуючи оборону дворфів і походи Альянсу.",al={"облогова бригада"}},{q="Куди веде це доручення далі?",a="Поповнивши запаси Джетстіма м'ясом і хутром, Пілот Беловфіз посилає мандрівників на захід до Села Брюнолл у завданні «Евершайн» — по міцний напій, яким він і зігрівається, і користується як аварійним паливом для топки танка.",al={"наступне завдання","що після запасів для джетстіма","продовження запасів для джетстіма"}},{q="Навіщо облоговій машині звірині шкури?",a="Усередині дворфійського чи гномського парового танка холодно й гуляють протяги під час довгих походів серед гірських снігів. Товсті ведмежі шкури дають екіпажу тепло й утеплення для постелі, коли доводиться довго бути далеко від табору.",al={"навіщо хутро","призначення густого ведмежого хутра","підстилка"}}},fp="17,280,23.382.0,23.325.0,17.210.0,23.228.0,44.185.0,26.183.0,34.220.1,44.223.0"}
P.entries["quest:318"] = {n="Евершайн",s="Евершайн — завдання Альянсу на доставку, що починається з Пілота Беловфіза біля Хараноса. Дворфійський пілот облогової машини посилає мандрівників на захід до Села Брюнолл по міцне дворфійське вариво, яке приготував Реджолд Барліброю. Трунок слугує і зігрівальним напоєм, і аварійним високооктановим пальним для облогової машини Беловфіза.",h="Евершайн — завдання Альянсу на доставку, що починається з Пілота Беловфіза біля Хараноса.",kw={"евершайн","пілот беловфіз","реджолд барліброю","село брюнолл","пальне","джетстім","вариво"},ang={["profession:Engineering"]="Використання леткого дистильованого спирту як допоміжного підсилювача пального показує, як пілоти на кшталт Беловфіза тримають облогові машини на ходу в суворих умовах.",["race:Dwarf"]="Міцний трунок Реджолда Барліброю втілює вогняні крайнощі дворфійської броварської традиції на холодних вершинах Дун Мороґу.",["race:Gnome"]="Звичка Пілота Беловфіза перетворювати буденні речі — навіть дворфійську горілку — на імпровізоване пальне вразила б будь-якого гномського майстра."},sec={{t="Міцне вариво",b="Дворфійське броварство уславлене на весь Каз Модан, але рецепти Реджолда Барліброю в Селі Брюнолл розсувають межі звичайного бродіння. Його експериментальний напій, Евершайн, сумнозвісний тим, що валить з ніг усіх, крім найміцніших дворфів. Попри люту міцність, його цінують у лютому холоді Дун Мороґу за суцільну зігрівальну силу."},{t="Пальне для Пілота Беловфіза",b="Пілоти облогових машин часто знаходять нетрадиційне застосування буденним речам, і Пілот Беловфіз не виняток. Працюючи зі Складу Стілґрила біля Хараноса, Беловфіз покладається на Евершайн не лише як на ковток проти крижаних вітрів, а й як на додаткове пальне. Залитий просто в топку його облогової машини Джетстім, леткий спирт дає вибуховий сплеск аварійної потужності, який не раз витягав його з халепи."}},faq={{q="Що таке Евершайн?",a="Евершайн — надзвичайно міцний експериментальний трунок, який вигадав дворф, майстер-пивовар Реджолд Барліброю в Селі Брюнолл. Він славиться вогняним ударом і здатністю звалити з ніг навіть загартованих дворфів-питущих.",al={"що таке евершайн","варево евершайн","який це напій"}},{q="Навіщо Пілотові Беловфізу Евершайн?",a="Пілот Беловфіз користується Евершайном і щоб зігріватися в холоднечі Дун Мороґу, і як аварійним пальним. Якщо влити цей летючий трунок у топку його облогової машини, Джетстіма, вона миттєво отримує ривок.",al={"навіщо беловфізу евершайн","пілот беловфіз евершайн","навіщо йому це"}},{q="Де Село Брюнолл?",a="Село Брюнолл — на заході Дун Мороґу, просто при шляху на захід від Хараноса. Воно тулиться біля засніжених пагорбів, і там живуть місцеві пивовари на кшталт Реджолда Барліброю.",al={"де брюнолл","місце села брюнолл","знайти брюнолл"}},{q="Хто такий Реджолд Барліброю?",a="Реджолд Барліброю — дворф-пивовар-експериментатор із Села Брюнолл. Він варить найрізноманітніші напої — від приємних елів до таких лютих сумішей, що ними можна розпалювати топки машин.",al={"хто такий реджолд","реджолд барліброю інфо","пивовар барліброю"}},{q="Що далі, коли дістанешся Реджолда Барліброю?",a="Реджолд не віддає свого цінного трунку просто так. Прибуття до Села Брюнолл веде до завдання «Послуга для Евершайна», де треба допомогти пивоварові, перш ніж він віддасть барильце для Пілота Беловфіза.",al={"наступне завдання після евершайна","що після евершайна","продовження реджолда"}},{q="Чи справді Евершайн безпечно пити?",a="За словами Пілота Беловфіза, Евершайн звалить з ніг майже будь-якого дворфа, що його скуштує. Формально його можуть пити горяни з найзалізнішими шлунками, але через надзвичайну горючість він не менше годиться, щоб палити топку двигуна.",al={"чи можна пити евершайн","чи евершайн отрута","чи евершайн небезпечний"}}},fp="9,327,19.362.0,24.448.0,18.221.0,40.231.0,26.182.0,25.209.0,49.222.1,33.236.0"}
P.entries["quest:319"] = {n="Послуга для Евершайна",s="Щоб здобути діжку Евершайну для Пілота Беловфіза на Складі Стілґрила, шукач пригод мусить спершу допомогти Селу Брюнолл. Бровар Реджолд Барліброю відмовляється розлучатися зі своїм трунком, доки небезпечних хижаків, що никають довколишніми заметами, не прорідять.",h="Щоб здобути діжку Евершайну для Пілота Беловфіза на Складі Стілґрила, шукач пригод мусить спершу допомогти...",kw={"послуга для евершайна","реджолд барліброю","село брюнолл","хижаки","ведмеді","вепри","снігові леопарди","евершайн"},ang={["class:Hunter"]="Проріджування зухвалих хижаків західного Дун Мороґу — перевірка влучності проти найвитриваліших зимових звірів скель.",["race:Dwarf"]="Кожен дворф розуміє, як важливо тримати диких хижаків подалі від чесного перегінного куба, щоб легендарні діжки Брюнолла лишалися неторканими.",["race:Gnome"]="Пілоти облогових машин і майстри на Складі Стілґрила нетерпляче чекають на цю діжку й покладаються на шукачів пригод, які задобрять упертого бровара, щоб підготовка Джетстіма тривала."},sec={{t="Угода бровара",b="У Реджолда Барліброю є діжка Евершайну, потрібна Пілотові Беловфізу, та він не квапиться віддавати своє дорогоцінне вариво задарма. Замість просити монет, Реджолд просить захисту. Дикі звірі західного Дун Мороґу — ненажерливі Крижанокігті Ведмеді, товстошкірі Старі Скельні Вепри й Снігові Леопарди, що никають довкола, — підходять небезпечно близько до Села Брюнолл, постійно відволікаючи місцевих і наражаючи їх на небезпеку."},{t="Спокій для ремісників",b="Хоч Реджолд одразу наполягає, що жоден поважний дворф не тремтить перед дикими тваринами, боротьба з хижаками цілодобово з'їдає цінні години. Винищення місцевої звірини дає селянам спокій, потрібний, щоб зосередитися на дистиляції й ковальстві, не тримаючи одне око повсякчас на узліссі."}},faq={{q="Чому Реджолд хоче, щоб цих звірів убили?",a="Біля Села Брюнолл никають ведмеді, вепри й снігові барси. Дворфи їх не бояться, але проганяти їх — марнувати дорогоцінні робочі години, які можна було б віддати пивоварінню й ремеслу.",al={"чому вбивати цих звірів","навіщо проріджувати тварин брюнолла","причина завдання реджолда"}},{q="Що таке Евершайн?",a="Евершайн — міцний славетний трунок, який варить лише Реджолд Барліброю в Селі Брюнолл. Пілоти облогових машин, як-от Пілот Беловфіз, вважають його напрочуд корисним — і як напій, і як летючу домішку до пального.",al={"що таке евершайн","варево евершайн","горілка реджолда"}},{q="Хто спершу попросив Евершайн?",a="Пілот Беловфіз зі Складу Стілґрила послав вас по нього, щоб зігріватися в дорозі й кидати в топку своєї облогової машини, Джетстіма, для ривка потужності.",al={"хто просив евершайн","хто хоче евершайн","початок ланцюжка"}},{q="Де шукати звірів?",a="Вони никають замерзлими полями й скелями одразу довкола Села Брюнолл і Озера Крижаного Потоку на заході Дун Мороґу.",al={"де ведмеді крижаного кігтя","місце снігових леопардів","місце старих кабанів"}},{q="Що буде, коли виконаєш послугу?",a="Коли звірів проріджено, Реджолд віддає барильце Евершайну, і ви можете віднести його просто Пілотові Беловфізу на Склад Стілґрила.",al={"наступне завдання","що після послуги для евершайна"}},{q="Чи справді хижаки загрожують селянам?",a="Реджолд запевняє, що жоден поважний дворф не боїться звіра на снігу, але небезпечні хижаки, що гарчать під самими дверима, — постійна перешкода й загроза щоденній роботі.",al={"чи хижаки справді загрожують","чи брюнолл у небезпеці"}}},fp="21,264,18.420.0,23.313.0,42.205.0,18.221.0,39.181.0,31.120.0,40.145.0,54.184.0"}
P.entries["quest:321"] = {n="Загартоване Світлом залізо",s="«Загартоване Світлом залізо» — завдання Альянсу з пошуку вантажу від Ґлоріна Стілброу в Гавані Менетіл. Шукачі пригод мають обнишпорити уламки «Летючої Скопи» — ельфійського бойового корабля, що віз рідкісний священний метал і загинув разом із Третім флотом Кул Тіраса під час Другої війни.",h="«Загартоване Світлом залізо» — завдання Альянсу з пошуку вантажу від Ґлоріна Стілброу в Гавані Менетіл.",kw={"загартоване світлом залізо","ґлорін стілброу","летюча скопа","третій флот","мурлоки","гавань менетіл"},ang={["class:Paladin"]="Зброя із загартованого Світлом заліза глибоко співзвучна зі Святим Світлом, тож повернути навіть один утрачений злиток — справа духовної ваги.",["faction:Alliance"]="Затонулі кораблі біля Гавані Менетіл — скорботні пам'ятники Другої війни, де відважні моряки з Кул Тіраса й Лордерона загинули від драконячого полум'я.",["profession:Blacksmithing"]="Ковалі всіх шкіл шанують загартоване Світлом залізо як найвищу мрію серед матеріалів: воно тримає потужні благословення й має неперевершену міцність."},sec={{t="Священний вантаж",b="Більшість затонулих корпусів біля узбережжя Багнокраю належали славетному Третьому флоту Кул Тіраса, але один корабель вирізнявся: ельфійський бойовий корабель на ім'я «Летюча Скопа». Вирушивши з Лордерона, він шукав безпеки, тримаючись разом із флотом, і віз дорогоцінний вантаж загартованого Світлом заліза. На жаль, похід разом із бойовими галерами не врятував його, коли поневолені кланом Драконячої Пащі червоні дракони впали з неба, підпалили флот і пустили на дно і вояків, і освячений метал."},{t="Пограбований хвилями",b="Коли дістаєшся розтрощених решток «Летючої Скопи» на південь від Гавані Менетіл, стає зрозуміло, що працювали тут не лише час і море. Просякнуту водою скриню з вантажем розбито й перерито пазурами. Прибережні мурлоки, завжди охочі обнишпорити уламки, розграбували трюм і розтягли злитки, лишивши ледь помітний слід дорогоцінної руди, яку шукає Ґлорін Стілброу."}},faq={{q="Що таке «Летюча Скопа»?",a="«Летюча Скопа» — ельфійський есмінець, що вийшов з Лордерону під час Другої війни. Він віз рідкісний вантаж загартованого Світлом заліза й ішов разом із Третім флотом Кул Тірасу заради захисту, але згорів і затонув разом з рештою флоту від червоних драконів, поневолених орками.",al={"лор летючої скопи","ельфійський знищувач багнокрай","який корабель віз залізо"}},{q="Хто такий Ґлорін Стілброу?",a="Ґлорін Стілброу — дворф з Гавані Менетіл у Багнокраї. Його цікавить підйом історичних решток і цінних матеріалів із затонулих біля узбережжя кораблів, особливо легендарних металів на кшталт загартованого Світлом заліза.",al={"ґлорін стілброу","дворф у менетілі","хто дає загартоване світлом залізо"}},{q="Що таке загартоване Світлом залізо?",a="Загартоване Світлом залізо — надзвичайно рідкісний освячений метал, з якого кують освячену зброю й обладунки. Ковалі й поборники Святого Світла цінують його за чистоту й стійкі духовні властивості.",al={"метал світлокування","що таке загартоване світлом залізо","зливки світлокування"}},{q="Чому кораблі затонули в Багнокраї?",a="Під час Другої війни ордійський клан Драконячої Пащі поневолив червоний драконячий рід за допомогою Душі Демона. Вершники на драконах напали на Третій флот Кул Тірасу біля узбережжя Багнокраю, спалили кораблі й пустили їх на морське дно.",al={"хто потопив третій флот","чому кораблі розбиті в багнокраї","червоні дракони багнокрай флот"}},{q="Чому скриня майже порожня?",a="На розмоклій скрині з «Летючої Скопи» — свіжі сліди пазурів прибережних мурлоків. Ці створіння розкрили її й пограбували вантаж, потягли більшість зливків і порозкидали їх болотистим берегом.",al={"де зливки","чому подряпини на скрині","хто вкрав залізо"}},{q="Де уламки «Летючої Скопи»?",a="Уламки лежать серед прибережних мілин трохи на південь від Гавані Менетіл, на західному березі Багнокраю, розкидані мілководдям біля місцевих поселень мурлоків.",al={"місце летючої скопи","де скриня","місце уламків у багнокраї"}}},fp="15,276,14.542.0,22.407.1,26.291.0,24.241.0,24.206.0,40.234.0,30.223.0,51.170.0"}
P.entries["quest:322"] = {n="Благословенна зброя",s="Врятувавши світлоковані злитки з уламків «Летючої Скопи» в Багнокраї, шукач пригод має доправити дорогоцінний метал до Стормвінда. Там на нього чекає майстер-коваль, дворф Ґріманд Елмор, щоб перетворити сирий метал на знаряддя, здатне протистояти некромантові Морбенту Фелу.",h="Врятувавши світлоковані злитки з уламків «Летючої Скопи» в Багнокраї, шукач пригод має доправити дорогоцінний...",kw={"благословенна зброя","ґріманд елмор","загартоване Світлом залізо","ґлорін стілброу","морбент фел","дворфійський квартал"},ang={["class:Paladin"]="Нести освячене залізо, щоб викувати зброю проти некроманта із Сутінколісся, — це відлуння головного покликання Срібної Длані: очищати землю від темного чаклунства святою пильністю.",["faction:Alliance"]="Ця доставка показує тісну співпрацю між королівствами: дворфійський жрець із Гавані Менетіл і кузні Дворфійського Кварталу Стормвінда разом допомагають знедоленим людям Сутінколісся.",["profession:Blacksmithing"]="Загартоване Світлом залізо — рідкісний і примхливий метал; спостерігаючи, як досвідчений дворфійський коваль Ґріманд Елмор береться за нього, ви бачите, якої виняткової майстерності вимагає кування святої зброї."},sec={{t="Рідкісний метал повертається",b="Загартоване Світлом залізо — не буденний товар, який знайдеш на звичайних ятках. Воно славиться тим, що відгукується проти мерзенних і нечестивих створінь, і вимагає коваля, який знає його гарт і примхи. Коли вантаж підняли з уламків «Летючої Скопи» біля узбережжя Багнокраю, Ґлорін Стілброу спакував повернені злитки в міцну скриню — він знав лише одного майстра в південних королівствах, здатного впоратися з таким незвичайним матеріалом: зброяра Ґріманда Елмора."},{t="Кузня Дворфійського Кварталу",b="Серед кіптяви й гуркоту Дворфійського Кварталу Стормвінда Ґріманд Елмор тримає одне з найкращих ковадел міста. Побачивши повернений вантаж, Елмор зауважує, що минули роки відтоді, як він востаннє кував загартоване Світлом залізо. Зацікавлений героїчним дорученням і охочий завдати удару некромантові Морбенту Фелу, бувалий майстер охоче береться допомогти своїм молотом."}},faq={{q="Яка мета цієї доставки?",a="У ящику — загартоване Світлом залізо, підняте з уламків «Летючої Скопи» в Багнокраї. Ґлорін Стілброу посилає його Ґрімандові Елмору, щоб вправний коваль викував з освяченого металу зброю, здатну здолати некроманта Морбента Фела.",al={"чому нести зливки до стормвінда","мета благословенної зброї","навіщо ящик зливків"}},{q="Хто такий Ґріманд Елмор?",a="Ґріманд Елмор — шанований дворф-зброяр, що працює в Дворфійському Кварталі Стормвінда. Він — один з небагатьох майстрів, що мають вишкіл і вміння кувати особливі метали на кшталт загартованого Світлом заліза.",al={"лор ґріманда елмора","хто коваль у дворфійському кварталі"}},{q="Чому загартоване Світлом залізо таке важливе проти Морбента Фела?",a="Морбент Фел — невловний і могутній некромант під захистом темної магії. Звичайна зброя ледве пробиває його нечестивий захист, тож потрібна зброя з освяченого загартованого Світлом заліза, щоб зірвати з нього цей захист і зробити його вразливим.",al={"чому загартоване світлом залізо","як залізо шкодить морбенту фелу"}},{q="Куди посилає вас Ґлорін Стілброу?",a="Ґлорін Стілброу посилає вас з Гавані Менетіл у Багнокраї до Дворфійського Кварталу Стормвінда, де тримає кузню Ґріманд Елмор.",al={"куди йти за благословенною зброєю","де ґріманд елмор"}},{q="Чи працював Ґріманд Елмор раніше із загартованим Світлом залізом?",a="Так. Оглянувши метал, Ґріманд зауважує, що вже багато років не працював із загартованим Світлом залізом, і радіє нагоді знову попрацювати з таким славетним матеріалом.",al={"чи ґріманд кував раніше","досвід ґріманда елмора"}},{q="Що має статися, перш ніж зброя буде готова?",a="Ґріманд погоджується викувати з піднятого загартованого Світлом заліза Погибель Морбента. Коли він закінчить, зброю треба віднести Свенові Йорґену в Сутінколісся.",al={"що після благословенної зброї","чи зброю викують одразу"}}},fp="11,302,20.489.0,28.410.0,37.257.0,22.219.0,56.244.0,37.144.0,54.194.0,51.149.0"}
P.entries["quest:3221"] = {n="Поговори з Ренферрелом",s="«Поговори з Ренферрелом» — коротке доручення в Гробниці в Срібноліссі. Верховний Екзекутор Гадрек посилає вас назад до місцевого дослідника Королівського Аптекарського Товариства, щоб обговорити знахідки щодо отруєних вовчих сердець.",h="«Поговори з Ренферрелом» — коротке доручення в Гробниці в Срібноліссі.",kw={"поговори з ренферрелом","аптекар ренферрел","верховний екзекутор гадрек","гробниця","вовчі серця","срібнолісся"},ang={["faction:Horde"]="Поки Орда закріплюється по всьому Лордерону, розуміння зіпсуття, що вражає місцевих звірів, вкрай важливе, щоб приборкати дику місцину.",["race:Undead"]="Королівське Аптекарське Товариство тісно співпрацює з військовим командуванням у Гробниці, щоб кожну біологічну аномалію Срібнолісся вивчили на користь задумів Темної Леді."},sec={{t="Виклик від Товариства",b="Після того як ви допомогли скрадачам смерті по всьому Срібноліссю, Верховний Екзекутор Гадрек передає вам нагальне повідомлення від Аптекаря Ренферрела. Ренферрел дослідив знебарвлені вовчі серця, зібрані з місцевої звірини, і вимагає, щоб ви негайно з'явилися."},{t="Алхімічні дивовижі",b="Аптекар Ренферрел служить Королівському Аптекарському Товариству зі своєї лабораторії в склепі Гробниці. Його дослідження вивчають, як темна магія й хвороби змінюють звірів Срібнолісся, поєднуючи військову розвідку на передовій із хімічною наукою."}},faq={{q="Де знайти Аптекаря Ренферрела?",a="Аптекар Ренферрел — у склепі Гробниці в центрі Срібнолісся, біля свого алхімічного обладнання, за кілька кроків від Верховного Екзекутора Гадрека.",al={"місце ренферрела","де ренферрел","знайти ренферрела"}},{q="Чому Аптекар Ренферрел хоче зі мною поговорити?",a="Ренферрел досліджував знебарвлені вовчі серця, зібрані з місцевих вовків Срібнолісся, і виявив у їхній зіпсованості дивні особливості, що потребують подальшого вивчення й зв'язку з Андерсіті.",al={"чому ренферрел хоче мене","ренферрел вовчі серця"}},{q="Хто посилає до Ренферрела?",a="Верховний Екзекутор Гадрек, військовий командир Відступників у Гробниці, передає вам виклик Ренферрела, коли ви повернетеся, допомігши його Скрадачам смерті.",al={"хто дає поговори з ренферрелом","хто дає завдання"}},{q="Що далі після цієї розмови?",a="Розмова з Ренферрелом веде просто до завдань, що пов'язують місцеві алхімічні дослідження Гробниці зі старшими постатями на кшталт Аптекаря Зінґе в Андерсіті.",al={"наступне завдання після ренферрела","продовження ренферрела"}}},fp="20,221,24.273.0,22.261.0,38.169.0,52.211.0,27.159.0,31.172.0"}
P.entries["quest:323"] = {n="Довести свою вартість",s="«Довести свою вартість» — важливий крок у помсті Свена Йорґена на заході Сутінколісся. Перш ніж дозволити шукачеві пригод зійтися з некромантом Морбентом Фелом, скорботний самітник вимагає доказу, що той здатен здолати легіони нежиті, які заполонили Цвинтар Воронячого Пагорба.",h="«Довести свою вартість» — важливий крок у помсті Свена Йорґена на заході Сутінколісся.",kw={"довести свою вартість","свен йорґен","морбент фел","цвинтар воронячого пагорба","кістяки","мор'ладім"},ang={["class:Paladin"]="Очистити Цвинтар Воронячого Пагорба від неспокійних мерців Морбента Фела — свята справа: так на плач непохованих померлих Сутінколісся відповідає правосуддя Світла.",["class:Priest"]="Осквернені темними обрядами гробниці Воронячого Пагорба волають про духовне очищення — і про кінець вартових і цілителів, що спотворюють життя й смерть.",["faction:Alliance"]="Без регулярних патрулів Стормвінда західне Сутінколісся поринуло в анархію, і спустошені прикордонники на кшталт Свена мусять цілком покладатися на мандрівних звитяжців, щоб відкинути навалу нежиті."},sec={{t="Випробування гіркого самітника",b="Свен Йорґен ховається у відлюдному таборі на північ від виючих лісів, поглинутий горем і люттю через різанину своєї родини. Він з'ясував, що таємничі Темні Вершники, які спалили його хутір, були в союзі зі зловісним некромантом на ім'я Морбент Фел. Хоч Свен і прагне відплати, він не настільки безрозсудний, щоб кинути неперевіреного новачка просто в лапи Фела. Він вимагає показати справжню бойову майстерність у сутичці з кістяним військом, що засіло на Цвинтарі Воронячого Пагорба."},{t="Склепи Воронячого Пагорба",b="Щоб догодити Свенові, шукачі пригод мусять заглибитися в некрополь Воронячого Пагорба на південь від Покинутого Ряду. Мавзолей і довколишні ділянки кишать неспокійними мерцями, скутими мерзенною магією Фела: між надгробками патрулюють кістяки-нападники з мечами, а в темніших підземних залах порядкують кістяки-вартові й кістяки-цілителі. Розчистити цей передовий загін — кривава робота, тим паче що цвинтарними стежками блукають жахіття на кшталт мстивого привида Мор'Ладіма."},{t="Дорога до некроманта",b="Пройшовши крізь устелені кістками катакомби, шукач пригод переконує Свена, що має не лише порожню відвагу. Та перемога над дрібними посіпаками Фела — лише пролог. Морбента Фела оберігають темні захисні чари, через які звичайна зброя його майже не бере, тож Свенові доводиться шукати глибшої мудрості й давніх реліквій, перш ніж почнеться остаточна сутичка."}},faq={{q="Чому Свен змушує мене битися зі скелетами, перш ніж іти на Морбента Фела?",a="Свен знає, що Морбент Фел — смертоносний некромант у союзі з таємничими Темними Вершниками. Він не хоче посилати союзника на марну смерть, доки той не доведе, що має витривалість і тактичну вправність, аби прорубатися крізь цілий авангард слуг-нежиті.",al={"чому довести свою вартість","чому свен змушує вбивати скелетів","випробування свена"}},{q="Де шукати скелетів-вартових і скелетів-цілителів?",a="Скелети-грабіжники блукають відкритим цвинтарем на південь від Покинутого Ряду, а скелети-цілителі й вартові зосереджені переважно всередині й довкола великого мавзолею та тунелів склепів на захід від центру цвинтаря.",al={"де скелети-вартові","де скелети-цілителі","знайти скелетів-вартових"}},{q="Хто такий Мор'Ладім і чому тут його варто остерігатися?",a="Мор'Ладім — могутній, трагічний лицар-нежить, що блукає стежками Цвинтаря Воронячого Пагорба. Він значно сильніший за звичайних скелетів біля склепів і швидко розправиться з необачними шукачами пригод.",al={"небезпека мор'ладіма","хто такий мор'ладім","мандрівна еліта воронячого пагорба"}},{q="Як Морбент Фел пов'язаний з Темними Вершниками?",a="Свен дізнався, що Морбент Фел уклав союз із Темними Вершниками в плащах, які вирізали його дружину й дітей. Вершники знову зникли в тінях, а Фел лишився в Сутінколіссі й далі чинить своє мерзенне некромантство.",al={"морбент фел і темні вершники","чому темні вершники і фел","убивці родини свена"}},{q="Що буде після цього завдання?",a="Коли ви доведете свою бойову вправність, Свен визнає вашу силу, але пояснює, що Морбента Фела не вбити самою грубою силою. Він радить звернутися по пораду до Єпископа Фартінґа в Соборі Світла в Стормвінді, щоб знайти спосіб позбавити некроманта його нечестивого захисту.",al={"наступне завдання після довести свою вартість","що після скелетів"}},{q="Де табір Свена Йорґена?",a="Свен тримає прихований табір серед пагорбів на далекому північно-західному краю Сутінколісся, у безпечному закутку на північ від Воронячого Пагорба й на захід від шляху до Вестфолу.",al={"де свен","місце табору свена"}}},fp="18,282,22.482.0,21.463.0,27.362.1,64.250.0,49.239.0,57.200.0,48.220.0,41.288.1,36.171.0"}
P.entries["quest:324"] = {n="Загублені злитки",s="«Загублені злитки» — завдання Альянсу в Багнокраї: повернути освячений метал із корабельних уламків. Знайшовши в затонулій скрині лише один злиток, мандрівники мають вистежити місцевих мурлоків-Блакитнозябрих, що розграбували решту вантажу.",h="«Загублені злитки» — завдання Альянсу в Багнокраї: повернути освячений метал із корабельних уламків.",kw={"загублені злитки","загартоване світлом залізо","мурлоки-синьозябрі","ґлорін стілброу","летюча скопа","багнокрай"},ang={["class:Paladin"]="Відвоювавши загартоване Світлом залізо в первісних мурлоків, ви бережете святі матеріали, з яких викують освячену зброю, гідну захисників Світла.",["profession:Blacksmithing"]="Кожен металург знає, як гірко бачити такий добірний матеріал, як загартоване Світлом залізо, дрібничкою в мурлочому гнізді на узбережжі, а не на ковадлі.",["race:Dwarf"]="Повернути втрачену добірну руду й передати її в руки дворфа-жерця, як-от Ґлоріна Стілброу, — значить ушанувати давню традицію дворфійських майстрів і тих, хто повертає втрачене."},sec={{t="Пограбовані уламки",b="Біля туманних берегів Багнокраю лежать розтрощені уламки «Летючої Скопи». Ті, кого послали по дорогоцінне загартоване Світлом залізо для дворфа-жерця Ґлоріна Стілброу, виявили, що просякнута водою скриня в трюмі майже порожня. Ненажерливі місцеві мурлоки-Блакитнозябрі вже обнишпорили корабель і забрали блискучі злитки собі."},{t="Повернення священного металу",b="Загартоване Світлом залізо — не звичайна руда: це рідкісний особливий метал, придатний для священного ковальства. Лишити його гнити в мурлочих таборах — неприпустимо для дворфа Світла. Вистежуючи нападників-Блакитнозябрих, що кишать на мілині біля розбитого корпусу, шукачі пригод відвойовують розкидані злитки, щоб Ґлорін Стілброу міг побачити, як із заліза викують зброю."}},faq={{q="Який корабель віз загартоване Світлом залізо?",a="Вантаж прибув на «Летючій Скопі» — злощасному кораблі, що загинув біля узбережжя Багнокраю. Його поламані балки досі частково стирчать з мілководдя.",al={"який корабель","летюча скопа","назва уламків"}},{q="Чому в скрині не було зливків?",a="У розмоклій скрині лишився замкненим лише один зливок. Прибережні мурлоки Блакитнозябрі вже розкрили затонулі уламки й розтягли решту вантажу між своїми прибережними нападниками.",al={"де зливки","чому мурлоки тримають залізо","порожня скриня"}},{q="Хто такий Ґлорін Стілброу?",a="Ґлорін Стілброу — дворф, жрець Церкви Святого Світла, якого можна знайти в Таверні «Глибока Вода» в Гавані Менетіл. Колега Єпископа Фартінґа, він шукає загартоване Світлом залізо, щоб викувати зброю проти некроманта Морбента Фела.",al={"ґлорін","хто такий ґлорін стілброу","хто дає завдання"}},{q="Чим особливе загартоване Світлом залізо?",a="Загартоване Світлом залізо — рідкісний освячений метал, напрочуд сприйнятливий до святих чарів і кування. Його цінують майстри, що кують зброю, споріднену зі Святим Світлом.",al={"лор загартованого світлом заліза","що таке загартоване світлом залізо","чому залізо важливе"}},{q="Які мурлоки забрали залізо?",a="Зниклі зливки захопило плем'я Блакитнозябрих — а саме мурлоки-нападники, що никають мілинами й пляжами довкола уламків «Летючої Скопи».",al={"хто вкрав зливки","яке плем'я","рейдери блюгілів"}},{q="Що далі, коли повернути зливки?",a="Отримавши всі зливки, Ґлорін Стілброу пакує освячений метал у ящик і посилає вас до зброяра Ґріманда Елмора в Стормвінд, щоб той його викував, — далі йде «Благословенна зброя».",al={"наступне завдання","що робить ґлорін","завдання благословенної зброї"}}},fp="15,236,21.371.0,27.370.0,38.180.0,37.216.0,24.239.0,38.170.0,28.154.0,43.204.1"}
P.entries["quest:325"] = {n="Озброєний і готовий",s="«Озброєний і готовий» — завершення кування зброї, створеної спеціально для того, щоб зірвати нечестивий захист некроманта Морбента Фела. Здобувши майстерність Ґріманда Елмора й святе благословення, шукач пригод несе Погибель Морбента назад за річку — до спраглого помсти Свена Йорґена в Сутінколіссі.",h="«Озброєний і готовий» — завершення кування зброї, створеної спеціально для того, щоб зірвати нечестивий...",kw={"озброєний і готовий","погибель морбента","морбент фел","свен йорґен","воронячий пагорб","ґріманд елмор"},ang={["class:Paladin"]="Поєднання доброї дворфійської сталі й святого освячення перегукується з традицією паладинів наповнювати бойову зброю божественним світлом, щоб трощити захисні чари нежиті.",["faction:Alliance"]="Злагоджена робота між майстрами Стормвінда й уцілілими на передовій у Сутінколіссі показує, як Альянс мусить спиратися на знання своєї столиці, щоб викорінювати скверну, що повзе його землями.",["profession:Blacksmithing"]="Робота Ґріманда Елмора показує, як вишукане ковальство можна поєднати зі святими обрядами, щоб створити особливу зброю проти надприродних загроз."},sec={{t="Зброю викувано",b="Morbent Fel's grasp on the Raven Hill cemetery seemed unbreakable. Conventional steel shattered or deflected harmlessly off the dark wards shrouding the necromancer. Overcoming such vile magic required a specialized artifact: Morbent's Bane. With the metal shaped by Grimand Elmore in the Dwarven District of Stormwind and properly consecrated with sacred power, the ward-breaking relic is finally complete and ready to sever Fel's connection to unlife."},{t="Повернення до самітника",b="Погибель Морбента, яку несуть назад у Сутінколісся, дарує надію Свенові Йорґену, що бачив, як його родина й ферма стали жертвами темряви, яка насувається. У своєму самотньому таборі біля західного краю лісу Свен одразу помічає вогонь в очах мандрівника й божественну роботу зброї. Тепер, коли реліквію, що ламає захисні чари, доставлено, усе готово до прямого удару по господареві Воронячого Пагорба."}},faq={{q="Що таке Погибель Морбента?",a="Погибель Морбента — особливо викувана й освячена зброя, створена, щоб пробити непроникний магічний захист некроманта Морбента Фела на Воронячому Пагорбі.",al={"погибель морбента","що за зброя","меч погибель морбента"}},{q="Хто викував зброю?",a="Grimand Elmore, a skilled blacksmith residing in the Dwarven District of Stormwind City, fashioned the ward-breaking relic before it received a sacred blessing.",al={"хто викував погибель морбента","роль ґріманда елмора"}},{q="Кому віддати Погибель Морбента?",a="Зброю треба доставити Свенові Йорґену, що ховається в таборі на заході Сутінколісся, неподалік кордону з Вестфолом.",al={"де свен","місце свена йорґена","куди здати"}},{q="Чому Свен Йорґен не може сам битися з Морбентом Фелом?",a="Свена Йорґена вигнали з дому, і він утратив родину й товаришів через темні сили, що заполонили ліс. Самотній і переслідуваний, він покладається на вправних поборників Альянсу, щоб помститися за полеглих.",al={"чому свен не б'ється","передісторія свена йорґена"}},{q="Що буде після завдання «Озброєний і готовий»?",a="Отримавши благословенну зброю, Свен Йорґен доручає вам вирушити просто на Цвинтар Воронячого Пагорба, зійтися з Морбентом Фелом і вбити його.",al={"що далі","наступне завдання після озброєний і готовий"}},{q="Як найшвидше повернутися до табору Свена?",a="Шлях на схід від Сентінел Гілл у Вестфолі через річку часто виходить значно коротшим і безпечнішим, ніж пробиратися на захід крізь жахи довкола Даркшира.",al={"найшвидше до свена","як швидко дістатися свена"}}},fp="15,305,15.453.0,20.429.1,23.163.0,23.160.0,34.134.0,48.201.0,46.146.1,47.182.0"}
P.entries["quest:3261"] = {n="Джорн Скайсір",s="«Джорн Скайсір» — завдання-подорож Орди, що веде досвідчених мисливців із Перехрестя на південь через Пустки до Табору Тауражо. Довівши Серґрі Даркторн свою вправність у вистежуванні місцевих рапторів, мисливці вирушають по глибшу духовну й тілесну науку до старого тауренського слідопита Джорна Скайсіра.",h="«Джорн Скайсір» — завдання-подорож Орди, що веде досвідчених мисливців із Перехрестя на південь через Пустки...",kw={"джорн скайсір","серґра даркторн","табір тауражо","золотий шлях","мисливець","раптори"},ang={["class:Hunter"]="Це завдання знайомить вас із Джорном Скайсіром, який перевірить, чи здатні ви перехитрувати й здолати легендарних верховних хижаків центральних і південних рівнин.",["faction:Horde"]="Поєднуючи Перехрестя з Табором Тауражо, цей шлях веде сили Орди глибше на спірні південні землі Пусток.",["race:Tauren"]="Для тауренів, що повертаються на південь до Табору Тауражо, ця подорож знову поєднує племінне мисливське мистецтво з духовним опікуванням дикої природи Пусток."},sec={{t="Передача естафети",b="Вполювавши хитрих сонцелуских рапторів і косокігтів, що скрадаються північною саваною, шукач пригод здобуває повагу Серґри Даркторн на Перехресті. Знаючи, що сирий бойовий хист рано чи пізно треба доповнити глибшим розумінням великих звірів цього краю, Серґра оголошує, що її наставництво завершене, і посилає мисливця на південь."},{t="Дорога до Тауражо",b="Довгий Золотий Шлях веде на південь дедалі суворішими рівнинами до Табору Тауражо — важливого тауренського поселення неподалік південних диких земель. Там чекає Джорн Скайсір, вправний старий слідопит, готовий навчити мисливців переслідувати невловиму, легендарну здобич по всіх Пустках."}},faq={{q="Хто посилає мене до Джорна Скайсіра?",a="Серґра Даркторн, мисливиця на рапторів з Перехрестя, посилає вас до нього, коли ви доведете свою вправність у вистежуванні й полюванні на місцевих косопазурів.",al={"хто дає джорна скайсіра","хто починає джорна скайсіра","завдання серґри даркторн"}},{q="Де знайти Джорна Скайсіра?",a="Джорн Скайсір — у Таборі Тауражо, далеко на півдні при головному шляху через Пустки.",al={"де джорн скайсір","місце джорна скайсіра","знайти джорна скайсіра"}},{q="Що буде, коли дістатися Джорна Скайсіра?",a="Коли ви з'явитеся до нього, Джорн вітає вас на шляху мисливця й починає посилати вистежувати й полювати на невловних звірів південних Пусток — почати доведеться з легендарного раптора Ішамугале.",al={"чого вчить джорн","продовження джорна скайсіра","наступне завдання після джорна скайсіра"}},{q="Чи треба бути мисливцем, щоб виконати це завдання?",a="Ні. Сюжет обертається довкола того, як опанувати мистецтво слідопита рівнин і стати на шлях мисливця, але взятися за нього може будь-який шукач пригод з Орди, що виконав завдання Серґри Даркторн з рапторами.",al={"чи треба бути мисливцем","вимога до класу джорн скайсір"}},{q="Чому Серґра далі вас не навчає?",a="Серґра Даркторн працює довкола північних гнізд рапторів біля Перехрестя. Щойно шукач пригод опанує ці полювання, вона спрямовує його на південь до Джорна Скайсіра, який керує глибшими вилазками по південну дичину.",al={"чому серґра відсилає","серґра закінчила навчання"}},{q="Що таке Табір Тауражо?",a="Табір Тауражо — поселення тауренів у південних Пустках. Це мисливська застава, торговий осередок і культурна зупинка для мандрівників між північними рівнинами й Малгором чи Тисячею Голок.",al={"про табір тауражо","що таке тауражо"}}},fp="12,319,18.340.0,19.288.0,29.162.0,30.116.0,41.201.0,48.193.0,42.218.0,21.212.0"}
P.entries["quest:3281"] = {n="Викрадене Срібло",s="«Викрадене Срібло» — доручення Орди від Ґазроґа на Перехресті: повернути скарбничку з платнею, яку поцупили раптори. Ідучи за чутками про їхню моторошну хитрість, мандрівники вистежують зниклі гроші глибоко в Угіддях Рапторів на південь від Раджета. Повернута скринька гарантує, що гарнізон Перехрестя таки отримає платню.",h="«Викрадене Срібло» — доручення Орди від Ґазроґа на Перехресті: повернути скарбничку з платнею, яку поцупили...",kw={"викрадене срібло","ґазроґ","раптори","угіддя рапторів","перехрестя","платня"},ang={["class:Hunter"]="Поведінка рапторів у Пустках не вкладається у звичні уявлення про звірів: вони мають складне гніздове суспільне життя й незвичний потяг до штучного, блискучого вантажу.",["faction:Horde"]="Перехрестя — хребет постачання Орди в Калімдорі; щоб утримувати рубіж, його вартові мають бути ситі й отримувати платню."},sec={{t="Звірине пограбування",b="Перехрестя — життєво важливий вузол Пусток, що поєднує Оргріммар, Малгор і Раджет. Щоб тримати лад на цій неосяжній савані, потрібні пильні вартові, а вартовим потрібна стала платня. Коли раптори напали на вантаж із платнею, Ґазроґ спершу прагнув помститися звірам. Та вбивство зграї не зведе рахунків поселення, тож Орді доводиться з'ясовувати, як і навіщо звичайні тварини потягли важкі ящики з монетами."},{t="Угіддя Рапторів",b="Розвідники виявили густе гніздовище рапторів між двома скелястими вершинами на південь від Раджета й на північний захід від Твердині Північної Варти. Звірі затягли цілу скриньку просто на свою гніздову територію й боронили її разом із яйцями та свіжою здобиччю. Ґазроґ мусить визнати, що оповіді про розум рапторів і їхню звичку робити запаси напрочуд правдиві, адже звичайні звірі навряд чи ховали б металеві цінності."}},faq={{q="Навіщо раптори взагалі вкрали срібло?",a="Раптори Пусток відомі дивовижною хитрістю й цікавими звичками збирачів. Чи то їх приваблював блискучий метал, чи запах вичиненої шкіри на скрині, чи просто агресивний інстинкт накопичення, — вони затягли цілу скриню до своїх спільних гнізд в Угіддях Рапторів.",al={"чому раптори вкрали срібло","навіщо рапторам срібло","мотив рапторів"}},{q="Хто такий Ґазроґ?",a="Ґазроґ — орк-офіцер у головному бункері Перехрестя. Він відповідає за безпеку й постачання застави й має справу з загрозами від місцевих звірів, набігами кентаврів і зривами виплат.",al={"ґазроґ","хто дає викрадене срібло","завдання ґазроґа на перехресті"}},{q="Де розташовані Угіддя Рапторів?",a="Угіддя Рапторів лежать на сході Пусток, на південь від гоблінського порту Раджет і на північний захід від фортеці Альянсу — Твердині Північної Варти. Гнізда заповнюють суворий прохід, затиснутий між двома горами.",al={"місце угідь рапторів","де викрадене срібло","місце скрині викраденого срібла"}},{q="Що буде, якщо срібла не повернути?",a="Украдене срібло — місячна платня вартових Перехрестя. Без неї захисникам застави доведеться служити задарма, а це підриває бойовий дух у фортеці, на яку раз у раз нападають шипогриви, кентаври й загони Альянсу.",al={"чому викрадене срібло важливе","плата вартовим перехрестя"}},{q="Чи це частина довшого ланцюжка завдань?",a="Так. Перш ніж шукати схованку, шукачі пригод мусять виконати для Ґазроґа завдання «Раптори-злодії» — проріджувати рапторів Пусток, що напали на перший обоз, а тоді вистежити, де сама схованка.",al={"передумови викраденого срібла","продовження про рапторів-злодіїв"}},{q="Чи причетний до крадіжки Альянс?",a="Ні. Твердиня Північної Варти стоїть на південний схід від Угідь Рапторів, але крадіжку цілком скоїли місцеві раптори, чим здивували навіть досвідчених командирів Орди своїм злодійством і пристрастю до накопичення.",al={"чи нортвотч вкрав срібло","альянс і раптори в пустках"}}},fp="13,323,15.453.0,18.433.0,48.282.0,14.210.0,37.199.0,44.228.0,37.214.0,38.202.0"}
P.entries["quest:33"] = {n="Вовки перетинають кордон",s="«Вовки перетинають кордон» — одне з перших завдань, яке дає Іґан Пелтскіннер біля Абатства Нортшира. Він наймає нових шукачів пригод полювати на вовків, що никають долиною, і збирати їхнє м'ясо для власної кухні.",h="«Вовки перетинають кордон» — одне з перших завдань, яке дає Іґан Пелтскіннер біля Абатства Нортшира.",kw={"вовки","іґан пелтскіннер","вовче м'ясо","нортшир","полювання","кулінарія"},ang={["profession:Cooking"]="Апетит Іґана до вовчого стейка знайомить нових шукачів пригод із суворою правдою прикордоння Азерота: що вполював, те часто можна зготувати й з'їсти.",["race:Human"]="Для людей-новобранців, що починають шлях у Нортширі, це одне з перших практичних завдань на захист найближчих кордонів Стормвінда."},sec={{t="Практичне прохання",b="Поки Маршал Макбрайд і варта Стормвінда зосереджують свої нечисленні сили на захисті Абатства Нортшира від бандитів Дефіас, звичайні ремісники мають щоденні потреби. Іґан Пелтскіннер стоїть під мурами абатства й плекає глибоку неприязнь до місцевих лісових вовків. Замість просто нарікати на звірів, що блукають прикордонними лісами, він наймає новобранців, що проходять повз, проріджувати їхні зграї й приносити жорстке вовче м'ясо йому на сковорідку."},{t="Дика природа Нортширу",b="Долина Нортширу колись була мирним прихистком, захищеним пологими пагорбами й густими лісами. Та відколи Королівство Стормвінд потерпає від безвладдя й нестачі війська, дикі хижаки — молоді вовки й лісові вовки — посміливішали й підходять дедалі ближче до стежок і садів абатства. Зачистка від них не лише наповнює комору Іґана, а й робить ближні стежки безпечнішими для послушників, робітників і щойно прибулих захисників."}},faq={{q="Хто такий Іґан Пелтскіннер?",a="Іґан Пелтскіннер — місцевий мисливець і торговець біля входу до Абатства Нортшира. Він недолюблює диких лісових вовків краю, але дуже охоче їх готує й їсть.",al={"хто такий іґан","пелтскіннер","іґан пелтскіннер"}},{q="Навіщо Іґанові вовче м'ясо?",a="Іґан щиро полюбляє вовчі стейки. Він дає корисне початкове спорядження й гроші новобранцям, готовим піти й добути йому свіжого м'яса.",al={"навіщо вовче м'ясо","іґан голодний","що іґан робить із м'ясом"}},{q="Де водяться вовки?",a="Лісові вовки й вовченята никають полями, пагорбами й берегами річки по всій Долині Нортширу, особливо на південь і схід від абатства.",al={"де вовки","місця вовків","знайти вовків"}},{q="Чому вовки — це біда для Нортширу?",a="Через поріділі патрулі й загрози на кшталт бандитів Дефіас, що насідають на долину, звірі підступили до доріг і ферм, і подорожувати без супроводу стало небезпечно для священників і робітників.",al={"чому вовки нападають","проблема вовків нортширу"}},{q="Чи треба з кимось поговорити, перш ніж узяти це завдання?",a="Ні. Помічник Віллем може спрямувати новачків до Іґана Пелтскіннера вступним дорученням, але Іґан запропонує це полювання будь-кому, хто підійде до нього біля абатства.",al={"передумови","вимоги","хто дає це завдання"}},{q="Чи йде жорстке вовче м'ясо на кулінарні рецепти?",a="Іґан збирається приготувати м'ясо сам, але кухарі-початківці часто дізнаються, що вовче м'ясо з Лісу Елвінн — проста основа для куховарства в поході.",al={"чи жорстке вовче м'ясо для кулінарії","чи можна приготувати вовче м'ясо"}}},fp="24,218,19.440.0,19.442.0,25.206.0,30.143.0,29.152.0,39.185.0,53.185.0,44.157.0"}
P.entries["quest:3301"] = {n="Мура Рунтотем",s="Це завдання доручає мандрівникові зразок зміненого панцира щелепаня з Пусток, який треба доставити Мурі Рунтотем у Срібнолісся. Воно поєднує цілительські зусилля тауренів на різних континентах — дивну життєву силу рівнин Калімдору зі сплюндрованими землями Відступників.",h="Це завдання доручає мандрівникові зразок зміненого панцира щелепаня з Пусток, який треба доставити Мурі...",kw={"мура рунтотем","тонга рунтотем","зразок панцира щелепаня","срібнолісся","гробниця","друїди"},ang={["class:Druid"]="Вивчення незвичних відроджень природи — навіть тих, що народилися з дивних мутацій, — серцевина друїдських зусиль повернути рівновагу зламаним землям.",["faction:Horde"]="Це доручення показує, як міцніє співпраця в молодій Орді: оборонці Калімдору напряму долучаються до боротьби Відступників у Лордероні.",["race:Tauren"]="Це доручення показує глибоку відданість клану Рунтотем турботі про природу: свою цілющу руку вони простягають навіть за море, у похмурі, зів'ялі гаї Срібнолісся.",["race:Undead"]="Багато хто вважає землі Відступників безповоротно втраченими для гнилі й помори, але тауренські друїди на кшталт Мури Рунтотем щиро прагнуть відродити ліс довкола Гробниці."},sec={{t="Міст через моря",b="Досліджуючи дивну, змінену магією звірину довкола пишних оаз Пусток, Тонга Рунтотем помічає щось особливе у змінених щелепанях. Попри скверну, їхні панцири пульсують яскравою, стійкою енергією. Вірячи, що ця дивна життєва сила може прислужитися більшій меті, Тонга просить шукача пригод віднести панцир за Велике море своїй родичці з клану, Мурі Рунтотем, що перебуває у Східних Королівствах."},{t="Допомога Відступникам",b="Мура Рунтотем живе в Гробниці — заставі Відступників серед моторошних, гниючих лісів Срібнолісся. Бачачи, що Срібнолісся — недужий, сплюндрований ліс, Мура вирушила в нелегку подорож, щоб допомогти найновішим союзникам Орди очистити й відродити їхній дім. Вона сподівається, що внутрішнє сяйво панцира й уперта, незгасна іскра життя в ньому відкриють таємниці, які повернуть силу північному континенту."}},faq={{q="Хто така Мура Рунтотем?",a="Мура Рунтотем — тауренка-друїдка, родичка Тонги Рунтотема з одного клану. Вона перепливла море до Срібнолісся й оселилася в Гробниці, щоб допомогти Відступникам, шукаючи способу вилікувати їхній вмирущий ліс.",al={"мура","хто така мура","рунтотем срібнолісся"}},{q="Де знайти Муру Рунтотем?",a="Мура Рунтотем — у Гробниці, містечку Відступників при шляху в центрі Срібнолісся, на континенті Східних Королівств.",al={"місце мури","де мура","знайти муру рунтотем"}},{q="Навіщо Тонга посилає панцир клацнощелепа до Срібнолісся?",a="Панцирі клацнощелепів, зібрані біля оаз Пусток, мають неприродну життєву силу й внутрішнє сяйво. Тонга вірить, що, вивчивши цю стійку життєву силу, Мура зрозуміє, як зцілити спаплюжену, вмирущу природу Срібнолісся.",al={"навіщо панцир до срібнолісся","призначення панцира клацнощелепа","навіщо мурі панцир"}},{q="Чому таурени намагаються зцілити землі Відступників?",a="Таурени мають священний обов'язок плекати й лікувати природний світ. Бачачи, що Срібнолісся гниє й спаплюжене, Мура сподівається поширити цілющі традиції землі, щоб допомогти новим союзникам по Орді й відновити рівновагу ґрунту.",al={"таурени лікують землі нежиті","чому зцілювати срібнолісся","друїди в срібноліссі"}},{q="Як це завдання пов'язує Пустки зі Срібноліссям?",a="Воно — сюжетна й географічна ниточка між ранніми землями Орди, що веде шукачів пригод з випалених сонцем рівнин Калімдору до темних лісів Східних Королівств із дослідницьким матеріалом.",al={"завдання від пусток до срібнолісся","завдання між континентами"}},{q="Що буде, коли віддати панцир Мурі?",a="Муру захоплює незгасне внутрішнє сяйво панцира, і вона вирішує ретельно його вивчити, продовжуючи свої довгі пошуки ліків для спаплюжених лісів Срібнолісся.",al={"продовження мури","що далі"}}},fp="14,293,20.444.0,19.410.0,22.218.0,32.155.0,55.236.0,49.249.0,54.211.0,41.180.0"}
P.entries["quest:332"] = {n="Реклама винної крамниці",s="«Реклама винної крамниці» — коротке рекламне доручення, яке дає Ренато Галліна в Торговому Кварталі Стормвінда. Він заманює перехожих талоном на безкоштовну пляшку витриманого вина з родинної крамниці біля каналів. Це буденний погляд на місцеву торгівлю й дрібні справи, що процвітають у відбудованій столиці.",h="«Реклама винної крамниці» — коротке рекламне доручення, яке дає Ренато Галліна в Торговому Кварталі...",kw={"реклама винної крамниці","ренато галліна","сюзетта галліна","виноробня галліна","вино","торговий квартал"},ang={["faction:Alliance"]="Навіть у буремні часи війни й зниклих королів жвавий Торговий Квартал Стормвінда зберігає діяльний ринок місцевих розкошів і привізних смаків.",["profession:Cooking"]="Добірні вина на кшталт піно нуар від родини Галліна — бажані супутники ситних страв, які готують у шинках по всіх Східних Королівствах.",["race:Human"]="Для людей, що відбудовують своє життя в Стормвінді, родинні виноробні на берегах каналів — утішний знак відродження міста."},sec={{t="Смак Каналів",b="Поки шукачі пригод заклопотані бойовими загрозами й політичними інтригами, щоденне життя Стормвінда крутиться довкола жвавої торгівлі. Ренато Галліна ходить бруківкою Торгового Кварталу й розхвалює виноробню Галліна — невелику крамницю, яку тримає разом зі своєю сестрою Сюзеттою. Щоб привабити і спраглих мандрівників, і місцевих, він роздає рекламні листівки, що дають власникові право на безкоштовну дегустацію."},{t="Витримане піно нуар",b="Нагорода від родини Галліна — пляшка їхнього славетного піно нуар. Пройшовши за квитком до входу виноробні біля водних шляхів каналів, відвідувачі застають Сюзетту Галліну, готову вручити пляшку, — вона певна, що один ковток їхнього фірмового вина зробить будь-якого новачка вірним постійним гостем."}},faq={{q="Де розташована Винарня Галліна?",a="Винарня Галліна — у Торговому Кварталі Стормвінда, на самому краю мальовничих каналів, неподалік від маршруту, яким Ренато Галліна роздає рекламу.",al={"де винарня галліна","місце сюзетти галліна","куди здати рекламу винної крамниці"}},{q="Хто такі Ренато й Сюзетта Галліна?",a="Ренато й Сюзетта Галліна — брат і сестра, що тримають незалежну винну крамницю в Стормвінді. Ренато ходить вулицями й рекламує їхню справу листівками, а Сюзетта стоїть за прилавком і наливає вино.",al={"хто такі галліна","ренато галліна","сюзетта галліна лор"}},{q="Яке вино дають за квиток?",a="Пляшку славетного піно нуар від Галліна — фірмового червоного вина крамниці, яке, сподівається Ренато, перетворить новачків на вірних завсідників.",al={"піно нуар","яке вино отримаєш","піно нуар стормвінд"}},{q="Чому Ренато роздає безкоштовні квитки на вино?",a="Це класична вулична реклама. Ренато пригощає зразками свого найкращого товару, щоб заманити перехожих до крамниці біля каналу й зібрати серед мешканців Стормвінда постійних покупців.",al={"чому безкоштовне вино","мета квитка на вино"}},{q="Чи є в цьому дорученні небезпека чи бій?",a="Ні. Треба лише взяти в Ренато рекламний квиток і пройтися безпечними вулицями Торгового Кварталу недалеко до крамниці, де чекає Сюзетта.",al={"чи небезпечна реклама винної крамниці","бої в завданні з вином"}},{q="Чи продає Винарня Галліна інший товар?",a="Сюзетта тримає добірку звичайних вин і спиртних напоїв для спраглих мандрівників, вартових на перерві й місцевих постачальників корчем, яким треба поповнити запаси.",al={"що ще продає сюзетта","напої винарні галліна"}}},fp="16,361,21.410.0,22.302.0,36.157.0,35.208.0,31.128.0,43.196.0,46.178.0,41.156.0"}
P.entries["quest:333"] = {n="Гарлану потрібен новий товар",s="Гарлан Беґлі, торговець у Стормвінді, бачить, як його полиці спорожніли через небачений попит на міцний одяг і обладунки. Не знаючи про конфлікти, що назрівають за міськими мурами, він відсилає гінця з терміновим замовленням на тканину до Реми Шнайдер у «Кравецьку майстерню на Каналах».",h="Гарлан Беґлі, торговець у Стормвінді, бачить, як його полиці спорожніли через небачений попит на міцний одяг...",kw={"гарлан беґлі","рема шнайдер","кравецтво","канали","стормвінд","тканина"},ang={["faction:Alliance"]="Тиха паніка серед покупців Стормвінда натякає на дедалі більший неспокій, що охоплює серце Альянсу за відсутності короля Варіана Рінна.",["profession:Tailoring"]="Це доручення дає зазирнути в буденну логістику кравецького ремесла Стормвінда, де невеликі майстерні на каналах постачають більші торгові крамниці.",["race:Human"]="Ремісники-трудівники Стормвінда й далі насторожено ставляться до правителів, підозрюючи знать у тому, що вона тримає простих містян у невіданні щодо небезпек, які насуваються."},sec={{t="Нашестя на міцний одяг",b="У гамірних торгових кварталах Стормвінда крамарі на кшталт Гарлана Беґлі бачать, як їхні запаси тануть із тривожною швидкістю. І звичайні містяни, і мандрівні шукачі пригод розхоплюють укріплені туніки, дорожній одяг і бойові обладунки. Гарланові здається, що люди королівства готуються до суворої пори чи близької зими, але від такого обсягу продажів його крамниця спорожніла й відчайдушно потребує готової тканини."},{t="Питання на Каналах",b="Щоб поповнити полиці, Беґлі відсилає посланця через міські водні шляхи до Реми Шнайдер — швачки, що тримає «Кравецьку майстерню на Каналах». Рема вдячна за постійні замовлення, але раптовий наплив покупців на захисне вбрання її непокоїть. Королівством ширяться тривожні чутки, і швачка мимоволі думає, чи не приховує правлячий Дім Вельмож від простого люду звісток про відкриту війну."}},faq={{q="Хто такий Гарлан Беґлі?",a="Гарлан Беґлі — торговець одягом і крамар у Стормвінді. Його справа залежить від місцевих кравців, які постачають йому в'язані речі й одяг, придатний для мандрів.",al={"гарлан беґлі","хто такий гарлан","беґлі стормвінд"}},{q="Хто така Рема Шнайдер?",a="Рема Шнайдер — кравчиня й швачка з Кравецької майстерні «Канал» у Стормвінді. Разом із чоловіком Корбеттом вона постачає торговцям по всьому місту свіжопошиті тканини й одяг.",al={"рема шнайдер","кравчиня рема","кравчиня каналу"}},{q="Чому в Гарлана закінчується одяг?",a="Містяни й мандрівники незвично масово скуповують обладунки й міцний одяг. Гарлан жартує, що люди поводяться так, ніби насувається люта зима, хоча справжня причина — дедалі більші заворушення й небезпеки на кордонах королівства.",al={"чому в гарлана немає одягу","чому купує обладунок","гарлан бізнес росте"}},{q="Чому Рема Шнайдер підозрює вельмож?",a="Рема вважає неприродним, що прості люди раптом спорядилися до бою, хоча війни офіційно ніхто не оголошував. Відколи король Варіан Рінн відсутній, королівськими справами керує Дім Вельмож, тож вона боїться, що аристократія приховує від людей прийдешню війну.",al={"чому рема підозрює вельмож","вельможі стормвінду приховують війну","чому підозрюють вельмож"}},{q="Де розташована Кравецька майстерня «Канал»?",a="Кравецька майстерня «Канал» стоїть при каналах, що в'ються Стормвіндом, — зручно між головними кварталами міста, щоб легко доставляти товар торговцям.",al={"місце майстерні канал","де рема шнайдер","де кравецька майстерня"}},{q="Що буде, коли доставити запит на тканину?",a="Отримавши замовлення, Рема готує заявку на припаси, і її чоловік Корбетт Шнайдер вирушає міськими вулицями — повз місцеві крамниці на кшталт Зброярні «Левове Серце» й «Сирів Тріаса» — у торгових справах.",al={"корбетт шнайдер","що робить корбетт","чоловік реми"}}},fp="23,289,23.469.0,23.448.0,21.184.0,22.221.0,38.241.0,43.291.0,47.170.0,50.234.0"}
P.entries["quest:334"] = {n="Посилка для Турмана",s="«Посилка для Турмана» — коротке доручення на вулицях Стормвінда. Стривожена мати, Рема Шнайдер, просить мандрівників віднести забуте кравецьке приладдя її синові — ледачому учневі в крамниці «Одяг Ларсонів» у Кварталі магів.",h="«Посилка для Турмана» — коротке доручення на вулицях Стормвінда.",kw={"посилка для турмана","турман","рема шнайдер","одяг ларсонів","квартал магів","кравецтво"},ang={["faction:Alliance"]="Під високою політикою Фортеці Стормвінда звичайні містяни й ремісники дбають, щоб столиця була вдягнена, нагодована й жила — доручення за дорученням.",["profession:Tailoring"]="Кожен великий кравець починав із низів: прокладав шви, тримав шпильки й намагався втекти від учнівської роботи в «Одязі Ларсонів»."},sec={{t="Материне доручення",b="У щоденній метушні Стормвінда не кожне доручення — це бій із гнолами чи викриття змов Дефіас. Рема Шнайдер, яка турбується про заробіток свого сина Турмана, помічає, що він поспіхом пішов із дому без ножиць і голок. Боячись, що син відстане в роботі, вона благає шукача пригод віднести приладдя через канали до його майстерні."},{t="Неохочий учень",b="Крамниця «Одяг Ларсонів» сховалася глибоко в Кварталі магів, неподалік від високих шпилів Вежі магів. Отримавши свої інструменти, Турман зізнається, що залишив ножиці зовсім не випадково: він хотів відкараскатися від щоденних обов'язків і розважитися. Та після маминого втручання його вільний день розвіюється, мов дим, і він мусить повернутися до шиття."}},faq={{q="Хто дає завдання «Посилка для Турмана»?",a="Завдання дає Рема Шнайдер. Вона шукає, хто б доставив набір для шиття її синові, який працює на іншому кінці міста, у Кварталі магів.",al={"хто дає завдання","завдання реми шнайдер","хто дає посилку для турмана"}},{q="Де знайти Турмана Шнайдера?",a="Турман Шнайдер — у крамниці одягу «Ларсон» у Кварталі магів Стормвінда. Крамниця — в глибині кварталу, біля стежки, що веде до Вежі магів.",al={"місце турмана","де турман","знайти турмана"}},{q="Чи справді Турман забув знаряддя випадково?",a="Rema believes Thurman hurried out without his kit and asks you to bring it to him.",al={"чи турман забув","чому турман залишив знаряддя","турман ледарює"}},{q="У якій крамниці Турман учнем?",a="Турман — учень кравця в крамниці одягу «Ларсон», що в Кварталі магів Стормвінда; її тримає родина Ларсонів.",al={"де працює турман","ларсон одяг","на кого працює турман"}},{q="Чому Рема Шнайдер просить допомоги в шукача пригод?",a="Рема вірить, що без набору синове учнівство під загрозою. Сама вона не може покинути своїх справ, тож звертається до мандрівних шукачів пригод, які, може, якраз ідуть до Кварталу магів.",al={"чому просять допомоги гравця","допомога реми"}},{q="Що буде, коли доставити набір для шиття?",a="Bring the sewing kit to Thurman at Larson Clothiers in Stormwind.",al={"нагорода за завдання","після посилки для турмана","реакція турмана"}}},fp="19,243,17.361.0,22.393.1,41.138.0,37.182.0,50.82.1,38.128.0,51.187.0,46.65.1"}
P.entries["quest:335"] = {n="Шляхетне пиво",s="Глибоко в темних закутках шинку «Зарізане Ягня» в Стормвінді Зардет із Чорного Кігтя плете інтриги проти знаті міста. Допитливий вельможа, Лорд Вішок, загрожує викрити осередок чорнокнижників під шинком, — тож починається тихе збирання рідкісних і сильнодійних реагентів, щоб усунути загрозу.",h="Глибоко в темних закутках шинку «Зарізане Ягня» в Стормвінді Зардет із Чорного Кігтя плете інтриги проти...",kw={"шляхетне пиво","зардет із чорного кігтя","лорд вішок","сльоза тіллоа","мускусний корінь","зарізане ягня"},ang={["class:Warlock"]="Склепи під «Зарізаним Ягням» — ваш безпечний прихисток у Стормвінді. Допомагаючи Зардетові, ви захищаєте своїх братів і сестер у темних мистецтвах від допитливих очей праведної знаті королівства.",["faction:Alliance"]="Поки король Варіан Рінн зник безвісти, політичні ігри в Домі Вельмож сягнули небувалого розмаху, тож внутрішні скандали особливо небезпечні для стабільності міста.",["profession:Herbalism"]="Сльоза Тіллоа й Мускусний Корінь — рідкісні, особливі рослини, що ростуть лише в краях із похмурою історією або в потоках чистої води."},sec={{t="Загроза від знаті",b="Під вулицями Кварталу магів ковен чорнокнижників, що діє з «Зарізаного Ягняти», тішиться хиткою таємністю. Цій таємності загрожує Лорд Вішок — член Дому Вельмож, що прочув про темну магію, яка вирує під містом. Вішок почав домагатися від інших вельмож повного розслідування, а це звалило б на ковен і міську варту, і пильне око корони."},{t="Зілля в тіні",b="Не бажаючи ризикувати відкритим протистоянням із правлячою верхівкою Стормвінда, Зардет із Чорного Кігтя вигадує тихий засіб, щоб Лорд Вішок раз і назавжди мав інші турботи. Для зілля потрібні маловідомі рослинні складники з далеких куточків Східних Королівств: бліда квітка, відома як Сльоза Тіллоа, із Сутінколісся та підводний Мускусний Корінь, вирваний з-під Каменетесної Греблі."}},faq={{q="Хто такий лорд Вішок?",a="Лорд Вішок — шляхтич із Дому Вельмож Стормвінда. Натрапивши на сліди діяльності чорнокнижників під Кварталом магів, він почав домагатися від ради офіційного розслідування.",al={"вішок","лорд вішок","хто такий вішок"}},{q="Хто такий Зардет із Чорного Кігтя?",a="Зардет — старший чорнокнижник, що діє з крипт під корчмою «Зарізане Ягня» в Стормвінді. Він дбає, щоб кабалу чорнокнижників міста не викрила й не винищила влада.",al={"зардет","зардет чорний кіготь","хто такий зардет"}},{q="Звідки береться Сльоза Тіллоа?",a="Сльоза Тіллоа — ніжна біла квітка, що росте в зарослому Саду Сталвана на околиці Даркшира в Сутінколіссі.",al={"місце сльози тіллоа","сльоза тіллоа","де сльоза тіллоа"}},{q="Де росте Мускусний Корінь?",a="Мускусний Корінь росте лише на мокрих землях біля самого підніжжя величезних водоспадів під Каменетесною Греблею в Багнокраї.",al={"місце мускусного кореня","мускусний корінь","де взяти мускусний корінь"}},{q="Чому влада Стормвінда досі не знає про чорнокнижників?",a="Магія скверни суворо заборонена й зневажувана в Альянсі. Чорнокнижники під «Зарізаним Ягням» мусять практикувати своє ремесло цілковито в підпіллі, щоб паладини й міська варта не кинули їх до в'язниці чи не стратили.",al={"чорнокнижники стормвінда таємниця","чому чорнокнижники ховаються","чи чорнокнижники поза законом"}},{q="Що Зардет збирається зварити з цих реагентів?",a="Зардет запевняє, що вариво «займе» лорда Вішока, тож розслідування застопориться. Що саме він задумав для шляхтича, стає ясно лише тоді, коли вариво готове.",al={"що за варево","призначення шляхетного пива","навіщо варити"}}},fp="12,312,24.402.0,27.413.1,20.201.0,33.196.0,40.137.0,33.142.0,67.219.0,53.177.1"}
P.entries["quest:336"] = {n="Шляхетне пиво",s="«Шляхетне пиво» — вершина таємного задуму, виплеканого в темному підвалі під шинком «Зарізане Ягня» в Стормвінді. На вимогу Зардета із Чорного Кігтя гінець — чи то необізнаний, чи то байдужий — доставляє сильнодійне зілля, відоме як Темне Пиво Чорного Пазура, Лордові Баурлесу К. Вішоку в королівській Фортеці.",h="«Шляхетне пиво» — вершина таємного задуму, виплеканого в темному підвалі під шинком «Зарізане Ягня» в...",kw={"шляхетне пиво","темне пиво чорного пазура","баурлес вішок","зардет із чорного кігтя","палата прохача","зарізане ягня"},sec={{t="Шляхетний лицемір",b="Лорд Баурлес К. Вішок — вельможа, що часто буває в Палаті Прохача у Фортеці Стормвінда й пишномовно розводиться про власну значущість і майбутнє королівства. Та під аристократичною позою ховається таємниця, відома всім завсідникам «Зарізаного Ягняти»: ночами Вішок навідується до горішніх кімнат шинку, п'є без міри й набирає величезні борги, яких ніколи не сплачує. А що найгірше в очах закладу — вдень він домагається, щоб шинок закрили зовсім."},{t="Смертельний тост",b="Зардет із Чорного Кігтя, чорнокнижник, що чатує в темних закутках під шинком, вирішує розквитатися з боргом Вішока раз і назавжди. Він варить особливий трунок — Темне Пиво Чорного Пазура — й обіцяє, що воно «добряче б'є в голову». Коли пихатому вельможі в Палаті Прохача подають пінистий кухоль, той бере гінця за звичайного слугу, жбурляє йому мідяк, щоб спекатися, і жадібно п'є — а за мить падає мертвий просто в залах фортеці."}},faq={{q="Хто такий Зардет із Чорного Кігтя?",a="Зардет із Чорного Кігтя — чорнокнижник, пов'язаний з тіньовою кабалою, що діє в прихованих катакомбах під «Зарізаним Ягням» у Кварталі магів Стормвінда. Він проводить небезпечні таємні операції подалі від очей міської варти.",al={"хто такий зардет","зардет чорного кігтя","хто дає завдання"}},{q="Чому Зардет обрав за ціль лорда Вішока?",a="Вішок — п'яниця й лицемір: ночами він гуляє на верхніх поверхах «Зарізаного Ягняти», не сплачуючи рахунків, а вдень у Залі Прохачів вимагає від влади закрити корчму.",al={"чому вбивати вішока","мотив вішока","чому отруїти"}},{q="Де знайти лорда Вішока?",a="Лорд Баурлес К. Вішок тиняється в Залі Прохачів — передпокої у Фортеці Стормвінда, де шляхта й містяни збираються, щоб обробляти регентство королівства.",al={"місце лорда вішока","де вішок","зала прохачів вішок"}},{q="Як лорд Вішок приймає вариво?",a="Вішок приймає гінця за слугу, бере стаут як освіжний напій і відпускає його, давши одну мідну монету.",al={"чи вішок помре","смерть вішока","що робить стаут"}},{q="Чи привертає доставка стауту увагу вартових?",a="Доставку сприймають як звичайного слугу, що приніс напій, і гонець може продовжити свою справу без сутички з вартовими.",al={"чи вартові нападуть","чи мене розшукують у стормвінді","наслідки отруєння"}},{q="Яке завдання йде після цієї доставки?",a="Доручення продовжується завданням «Ви добре нам прислужилися» — треба повернутися до Зардета під «Зарізане Ягня».",al={"що далі","після шляхетного пива","наступне завдання"}}},fp="12,320,17.484.0,14.482.1,33.238.0,37.231.1,28.159.0,39.130.1,56.147.1,33.103.1"}
P.entries["quest:3361"] = {n="Біда біженця",s="Після катастрофічного падіння Гномреґану під натиском трогів і радіації переселені гноми втекли в засніжені пустища Дун Мороґу. Біля Анвілмара інженер на ім'я Фелікс Віндлболт під час панічної евакуації втратив своє життєво важливе майно й інструменти через мародерів із тролів Морозогривів.",h="Після катастрофічного падіння Гномреґану під натиском трогів і радіації переселені гноми втекли в засніжені...",kw={"біда біженця","фелікс віндлболт","гномреґан","біженці","морозогриви","тролі","анвілмар","інструменти"},ang={["profession:Engineering"]="Жоден поважний ремісник не стоятиме осторонь, поки мародери тягнуть точні болти, штангенциркулі й ящики з інструментами, які збирали все життя.",["race:Dwarf"]="Гори Холодного Хребта століттями давали прихисток вашим родичам; допомогти гномським біженцям закріпитися в Анвілмарі — ушанувати давній союз між Айронфорджем і Гномреґаном.",["race:Gnome"]="Це завдання втілює гірку трагедію вашого народу: утративши чудесний дім через отруту й зраду, звичайні майстри тепер мусять благати чужинців вирвати базові інструменти в грубих тролів."},sec={{t="Утеча з Гномреґану",b="Коли підземні троги захопили високотехнологічне місто Гномреґан, Великий Тінкер Ґелбін Меккаторк і його радники дозволили випустити радіоактивний газ у відчайдушній спробі винищити загарбників. Ризикований крок обернувся катастрофою: він убив тисячі невинних, перетворив уцілілих на безтямних прокажених гномів і змусив решту населення до панічного виходу через Дун Мороґ."},{t="Мародери в снігу",b="Інженери й майстри-втікачі несли, які могли, цінні інструменти й креслення. Однак крижаними гірськими перевалами між Гномреґаном і Долиною Холодного Хребта никають тутешні тролі Морозогриви. Поки Фелікс Віндлболт пробивався до прихистку Анвілмара, нальотчики Морозогривів вихопили його скриню з інструментами, скриньку й відро болтів і відвезли їх до своїх таборів на південний захід від містечка."}},faq={{q="Хто такий Фелікс Віндлболт?",a="Фелікс Віндлболт — гном-інженер, що ледве врятувався від радіоактивної загибелі Гномреґана. Не маючи бойової вправності, щоб давати раду небезпекам Дун Мороґу, він ховається біля Анвілмара й намагається повернути вкрадене спорядження.",al={"фелікс віндлболт","хто такий фелікс","фелікс анвілмар"}},{q="Чому Гномреґан опромінений?",a="Під час несподіваної навали трогів гномська влада випустила нестійкий радіоактивний газ, щоб знищити чудовиськ. Натомість газ отруїв вентиляцію міста, убив чи спотворив більшість мешканців і зробив столицю непридатною для життя.",al={"що сталося з гномереґаном","радіація гномереґана","падіння гномереґана"}},{q="Хто вкрав речі Фелікса?",a="Його скриню, коробку й відро болтів забрали тролі-Морозогриви. Ці корінні тролі влаштовують засідки на мандрівників на гірських стежках Дун Мороґу й тягнуть украдений брухт і спорядження до своїх грубих таборів на південний захід від Анвілмара.",al={"хто вкрав болти","у кого речі фелікса","тролі морозогриви"}},{q="Де шукали притулку гноми-вигнанці?",a="Багато гномів утекли через Дун Мороґ до дворфійського королівства Айронфордж, а інші знайшли тимчасовий притулок у менших поселеннях Дун Мороґу, як-от Анвілмар і Харанос.",al={"де живуть гноми","біженці гноми","поселення гномів"}},{q="Чому відро болтів так багато важить?",a="Для гнома-майстра у вигнанні знаряддя, особливі гвинти й точені болти — це весь його хліб. Без належного спорядження інженери-біженці не можуть займатися ремеслом, будувати захист чи відбудовувати життя на чужині.",al={"навіщо болти","відро болтів фелікса"}},{q="Яку загрозу тролі-Морозогриви становлять для Долини Холодного Хребта?",a="Плем'я Морозогривів здавна живе на суворих вершинах Дун Мороґу. Після недавніх проривів трогів і хаосу евакуації Гномреґана тролі осміліли: нападають на шляхи постачання й влаштовують засідки на мандрівників.",al={"тролі дун мороґ","загроза морозогривів","табір морозогривів"}}},fp="20,283,26.396.0,22.399.0,25.243.0,29.266.0,29.221.0,43.182.0,42.237.0,61.221.0"}
P.entries["quest:3364"] = {n="Доставка Пекучого Ранкового Варива",s="Доставка Пекучого Ранкового Варива — поспішне доручення через Долину Холодного Хребта: доправити свіжий гарячий напій, перш ніж він вистигне на гірському морозі. Норі Прайддріфт довіряє доставку шукачеві пригод, щоб Дурнан Фуркаттер отримав свій ранковий узвар обпікаюче гарячим.",h="Доставка Пекучого Ранкового Варива — поспішне доручення через Долину Холодного Хребта: доправити свіжий...",kw={"доставка пекучого ранкового варива","ранковий узвар","норі прайддріфт","дурнан фуркаттер","анвілмар","долина холодного хребта","гарячий напій"},ang={["profession:Cooking"]="Подавати напої належної температури — ознака справжньої кулінарної поваги, особливо в безжальних морозах Дун Мороґу.",["race:Dwarf"]="Кожен дворф розуміє трагедію холодного напою на крижаному гірському повітрі, тож цей забіг через долину — справа чистого принципу."},sec={{t="Наввипередки з морозом",b="Пронизливий холод Дун Мороґу зіпсував не одну гарячу страву, і ранковий узвар не виняток. Доставивши порцію Ґреліну Вайтбірду, Норі Прайддріфт розуміє, що не встигне принести ще один свіжий кухоль до Анвілмара, перш ніж той замерзне в неїстівну кашу. Замість підвести клієнта, він залучає будь-якого прудкого мандрівника, готового кинути виклик снігу."},{t="Ціна теплого кухля",b="Дурнан Фуркаттер, що перебуває в теплі гірської зали Анвілмара, відомий своєю вибагливістю щодо напоїв. Прохолодний ранковий узвар просто не годиться. Доправлений гарячим напій дарує втомленому дворфові таку потрібну перерву від обов'язків, хоч Норі все одно чекає, що його улюблений кухоль повернуть цілим."}},faq={{q="Хто такий Дурнан Фуркаттер?",a="Дурнан Фуркаттер — дворф, що живе в підземній залі Анвілмара в Долині Холодного Хребта. Гаряче ранкове вариво йому доставляє Норі Прайддріфт.",al={"дурнан фуркаттер","хто такий дурнан","фуркаттер"}},{q="Чому доставка має бути такою швидкою?",a="У морозну гірську погоду Долини Холодного Хребта гарячі напої швидко холонуть. Дурнан замовив саме пекуче ранкове вариво, а холодний ель чи чай, за дворфійськими мірками, — зіпсований.",al={"чому на час","таймер ранкового варива","навіщо поспішати"}},{q="Хто такий Норі Прайддріфт?",a="Норі Прайддріфт — дворф, що стоїть на засніжених стежках Долини Холодного Хребта. Він опікується доставками між місцевими таборами, зокрема носить напої Ґреліну Вайтбірду й робітникам в Анвілмарі.",al={"норі прайддріфт","норі","хто такий норі"}},{q="Що таке ранкове вариво?",a="Ранкове вариво — тепле, бадьорливе дворфійське ранкове питво, створене, щоб проганяти пекучий холод вершин Дун Мороґу й підтримувати сили витривалих гірських трударів.",al={"що таке ранкове вариво","лор ранкового варива"}},{q="Де розташований Анвілмар?",a="Анвілмар — просто на північний схід від посту Норі; його видовбано в гірській скелі Долини Холодного Хребта, щоб ховати молодих горян і ремісників від хуртовин.",al={"де анвілмар","місце анвілмара","знайти анвілмар"}},{q="Чи хоче Норі повернути кухоль?",a="Так. Коли Дурнан допиває своє гаряче вариво, він повертає порожню посудину, щоб її віднесли назад Норі в Долину Холодного Хребта.",al={"кухоль повернути","принести назад кухоль","кухоль норі"}}},fp="26,254,24.351.0,23.318.0,24.171.0,41.190.0,23.202.0,17.156.0,26.169.0,28.133.0"}
P.entries["quest:3365"] = {n="Поверни кухоль",s="Після доставки обпікаюче гарячого ранкового узвару через замети Дун Мороґу лишається останнє доручення: повернути порожній кухоль. Дурнан Фуркаттер відсилає гінця назад через Долину Холодного Хребта, щоб повернути дорогоцінний кухоль Норі Прайддріфта. Проста люб'язність, але продавець напою глибоко її цінує.",h="Після доставки обпікаюче гарячого ранкового узвару через замети Дун Мороґу лишається останнє доручення...",kw={"поверни кухоль","кухоль","норі прайддріфт","дурнан фуркаттер","ранковий узвар","долина холодного хребта","етикет"},ang={["profession:Cooking"]="Кожен порядний кухар чи бровар знає: якісне обслуговування не закінчується, доки посуд не пораховано й не повернуто на кухню.",["race:Dwarf"]="Кожен дворф знає, що привласнити кухоль шинкаря — швидкий шлях до бійки; повернути кухоль Норі — елементарна дворфійська ввічливість."},sec={{t="Справа корчемного етикету",b="Подавати обпікаюче гарячий ранковий узвар на лютому морозі Дун Мороґу — делікатна справа. Коли Дурнан Фуркаттер відігріє кістки гарячим варивом, порожній кухоль не можна просто кинути в сніг. Дворфійська гостинність тримається на взаємній повазі, і загубити добрий посуд — певний спосіб лишитися без наступних порцій."},{t="Кухлі на деревах не ростуть",b="Повернення до Долини Холодного Хребта завершує доставку для Норі Прайддріфта. Як Норі любить нагадувати забудькуватим кур'єрам, міцний посуд на деревах не росте — особливо в крижаних скелях дворфійської батьківщини. Повернути порожній кухоль цілим — закріпити репутацію шукача пригод як надійної людини в місцевій громаді."}},faq={{q="Хто дає це доручення?",a="Дурнан Фуркаттер дає вам це завдання одразу після того, як ви доставите йому свіжозварене ранкове вариво в Дун Мороґу.",al={"хто дає завдання","хто дає поверни кухоль","завдання дурнана фуркаттера"}},{q="Кому повернути кухоль?",a="Порожній кухоль треба повернути Норі Прайддріфту, який ходить Долиною Холодного Хребта в Дун Мороґу й продає своє ранкове вариво.",al={"куди нести кухоль","хто отримує кухоль","місце норі"}},{q="Чи є обмеження часу, щоб повернути кухоль?",a="Ні. Першу доставку Пекучого Ранкового Варива треба було встигнути, поки напій гарячий, а порожній кухоль можна повернути без поспіху.",al={"чи на час","таймер кухля","чи треба поспішати"}},{q="Чому Норі так переймається порожнім кухлем?",a="Добрі кухлі й келихи — цінний посуд у Дун Мороґу. Як зауважує Норі, кухлі на деревах не ростуть, і корчми не можуть собі дозволити втрачати посуд через кожного мандрівного гінця.",al={"чому норі хоче кухоль","важливість кухля"}},{q="Яке завдання веде безпосередньо до цього?",a="Це доручення — пряме продовження «Доставки Пекучого Ранкового Варива»; воно починається, щойно Дурнан вип'є принесений вами напій.",al={"передумова","що перед поверни кухоль"}},{q="Де знайти Дурнана Фуркаттера?",a="Дурнан Фуркаттер — торговець тканинними й шкіряними обладунками в Анвілмарі, поселенні, видовбаному в горі в Долині Холодного Хребта.",al={"місце дурнана","де дурнан"}}},fp="18,313,28.361.0,24.354.0,23.120.0,27.109.0,40.158.0,46.176.0,40.133.0,36.135.0"}
P.entries["quest:3369"] = {n="У кошмарах",s="«У кошмарах» — завдання Орди, у якому шукач пригод має доставити тривожну реліквію, Скалку Жаху, Верховному Друїдові Гамуулу Рунтотему на Узвишшя Старійшин у Тандер Блафі. Уламок, знайдений як сяйливий кристал у Печерах Стогонів, відкриває глибоко тривожну скверну, що просочується в Смарагдовий Сон.",h="«У кошмарах» — завдання Орди, у якому шукач пригод має доставити тривожну реліквію, Скалку Жаху, Верховному...",kw={"у кошмарах","скалка жаху","гамуул рунотем","смарагдовий сон","фалла сейджвінд","печери стогонів","узвишшя старійшин","друїд"},ang={["class:Druid"]="Для друїдів ця скалка — глибоко тривожний доказ того, що незаймана святість Смарагдового Сну порушена, а шепіт про скверну, що повзе колами Кенарія, — правда.",["faction:Horde"]="Доставка скалки оберігає духовний добробут центрального Калімдору й показує, що Орда відіграє важливу роль у стримуванні грибкової скверни, народженої Сном, що розповзається з Пусток.",["race:Tauren"]="Повернення до Верховного Друїда Гамуула Рунтотема підкреслює дедалі вагоміше місце друїдів-тауренів у Колі Кенарія: вони протистоять прадавнім загрозам світобудови пліч-о-пліч зі своїми вчителями — нічними ельфами."},sec={{t="Тривожна знахідка",b="Оглянувши дивний кристал, здобутий у глибинах Печер Стогонів, Фалла Сейджвінд розуміє, що він утворений із чистої сутності Смарагдового Сну. Проте видіння всередині темне й хаотичне — на ньому печать не мирного сну, а жахіття наяву. Не бажаючи відкрито говорити про такі тривожні знамення, вона довіряє скалку вам і велить розшукати найшанованішого старшого друїда Тандер Блафа — Верховного Друїда Гамуула Рунтотема."},{t="Таємниця Сну",b="Коли Гамуулові Рунтотему на Узвишші Старійшин показують Скалку Жаху, його звичний спокій похитується, щойно він зазирає всередину. Маючи перед собою відчутний доказ того, що Смарагдовий Сон розпадається на жахіття, верховний друїд добирає слова дуже обережно. Він рішуче радить мовчати, застерігаючи, що такі делікатні справи далеко поза розумінням звичайних мандрівників, і потай вирішує розслідувати невидиму недугу, що загрожує царству сну."}},faq={{q="Що таке Скалка Жаху?",a="Скалка Жаху — очищена форма сяйливої скалки, здобутої з мутованих звірів у Печерах Стогонів. Хоча вона постала з чистої духовної сутності Смарагдового Сну, у ній — мерзенне, спотворене видіння, що свідчить: зі Сном щось страшенно негаразд.",al={"що таке скалка жаху","сяюча скалка кошмару","що знайшла фалла"}},{q="Хто така Фалла Сейджвінд?",a="Фалла Сейджвінд — обізнана тауренка-друїдка на схилі гори над Печерами Стогонів у Пустках. Вона вивчає незвичайні явища, що виходять з печер зіпсованої оази, і посилає гінців Орди до Гамуула Рунтотема, коли знаходять небезпечні реліквії.",al={"фалла сейджвінд","хто дав завдання","хто дає завдання"}},{q="Де знайти Верховного Друїда Гамуула Рунтотема?",a="Верховний Друїд Гамуул Рунтотем живе на Узвишші Старійшин, одній з високих столових гір Тандер Блафа. Він стоїть у друїдському колі разом з іншими практиками Кола Кенарія.",al={"де гамуул","місце гамуула рунтотема","гамуул"}},{q="Чому Гамуул хоче тримати скалку в таємниці?",a="Смарагдовий Сон — священний притулок природи й сплячих друїдів. Відчутний доказ того, що його спотворюють на жах, міг би посіяти повсюдну паніку серед Кола Кенарія й підірвати хиткі зусилля з духовного відновлення по всьому Калімдору, тож Гамуул закликає мовчати.",al={"чому гамуул мовчить","таємниця гамуула","чому гамуул ховає скалку"}},{q="Чи має Альянс свою версію цього завдання?",a="Так. Поборники Орди несуть Скалку Жаху Верховному Друїдові Гамуулу Рунтотему в Тандер Блаф, а гравців Альянсу, які досліджують Печери Стогонів, спрямовують за море до Дарнасуса — показати скалку друїдові Матренґілу Берволкеру з Кола Кенарія.",al={"версія альянсу","у кошмарах альянс","чи альянс може це"}},{q="Як це пов'язано з Печерами Стогонів?",a="Скалка походить з Печер Стогонів, де друїд Наралекс поринув у глибокий транс, щоб спрямувати підземні джерела в Пустки. Замість зцілити землю, сон Наралекса обернувся кошмаром наяву, що спотворив звірів печер і просочився в кристалічні скалки на кшталт цієї.",al={"печери стогонів","зв'язок наралекса","як це пов'язано з наралексом"}}},fp="13,325,22.482.0,21.463.1,28.285.0,22.283.0,45.197.0,48.296.0,47.288.0,44.297.0"}
P.entries["quest:337"] = {n="Стара Книга з Історії",s="Цей пошарпаний фоліант, знайдений серед зараженої землі й чудовиськових лігв Сутінколісся, має офіційну печатку Королівської Бібліотеки Стормвінда. Він має назву «Історія Стормвінда» й зник ще до того, як королівство відбудували після Першої війни. Повернувши його головному бібліотекареві Мілтонові Шіфу, ви віддаєте втрачену хроніку на місце й започатковуєте зусилля зі збереження історії людей Півдня.",h="Цей пошарпаний фоліант, знайдений серед зараженої землі й чудовиськових лігв Сутінколісся, має офіційну...",kw={"стара книга з історії","мілтон шіф","королівська бібліотека","історія стормвінда","сутінколісся","перша війна"},ang={["class:Mage"]="Знавці тайної магії розуміють: знання давніх бібліотек, покинуті в дикій глушині, вразливі до тління й занедбаності.",["faction:Alliance"]="Повертаючи довоєнні тексти, ви відновлюєте уламки втраченої спадщини Стормвінда, що пережили спустошення Першої війни.",["race:Human"]="Для людей Півдня повернути писані записи з дикої глушини — важливий крок до відродження культури, яку розтрощила Стара Орда."},sec={{t="Реліквія Першої війни",b="Знайдений серед ворожої нежиті й брутальних огрів, що блукають Сутінколіссям, цей обліплений багнюкою том — рідкісний уцілілий артефакт доби до знищення Стормвінда. На першій сторінці стоїть офіційна печатка королівської бібліотеки; книгу взяли десятиліття тому — ще до того, як Орда зрівняла столицю з землею, — і вважали назавжди втраченою під час падіння Півдня."},{t="Відновлення забутих літописів",b="Коли книгу приносять Мілтонові Шіфу до Королівської Бібліотеки у Фортеці Стормвінда, він визнає її безцінним скарбом, гідним архіву рідкісних видань. Роки в примарній глушині тяжко пошкодили сторінки, і знахідка спонукає Шіфа шукати й інші втрачені знання — його погляд звертається на північ, до Саутшора, найближчого містечка до зруйнованого королівства Альтерак і його покинутих бібліотек."}},faq={{q="Де знайти цю книгу?",a="Книга випадає з різних ворожих створінь Сутінколісся — найчастіше з нежиті, що блукає цвинтарями й полями, чи з огрів, які засіли на південних пагорбах.",al={"де знайти книгу","місце старої книги з історії","книга з історії сутінколісся"}},{q="Кому нести книгу?",a="Том треба повернути Мілтонові Шіфу — головному бібліотекареві Королівської Бібліотеки у Фортеці Стормвінда.",al={"куди здати","кому нести книгу","місце мілтона шіфа"}},{q="Чому книга в такому поганому стані?",a="Книгу взяли з бібліотеки ще до Першої війни й розграбування Стормвінда. Вона пролежала десятиліття в глушині Сутінколісся, потерпаючи від бруду, гнилі й рук мандрівних збирачів і чудовиськ.",al={"чому брудна","чому пошкоджена"}},{q="Чи веде повернення цієї книги до інших доручень?",a="Так. Мілтон Шіф пошле вас на північ до Саутшора в Передгір'ї Гілсбреда — до Знавця Переказів Діббса, який підкаже, де шукати книги, що досі лежать у Руїнах Альтераку.",al={"що далі","наступне завдання","ланцюжок книги"}},{q="Чому Мілтона Шіфа так цікавить саме цей том?",a="Давнє королівство зрівняли з землею під час Першої війни, і мало що з первісних історичних записів уціліло, коли місто горіло. Справжні довоєнні тексти допомагають ученим відтворити минуле королівства.",al={"чому книга важлива","важливість історії стормвінда"}},{q="Чи можуть гравці Орди виконати це завдання?",a="Ні. Книга належить Королівській Бібліотеці Стормвінда, і здати її можна лише бібліотекарям Альянсу у Фортеці Стормвінда.",al={"версія орди","чи лише для альянсу"}}},fp="19,380,24.358.0,26.404.0,25.166.0,27.110.0,39.201.0,45.175.0,60.208.0,38.126.0"}
P.entries["quest:3370"] = {n="У кошмарах",s="Знайшовши дивну сяйливу скалку, Фалла Сейджвінд розпізнає, що в цьому артефакті — чиста сутність Смарагдового Сну, затьмарена темними видіннями. Вона посилає шукача пригод до Дарнасуса, щоб той передав тривожну реліквію просто старшим друїдам Кола Кенарія.",h="Знайшовши дивну сяйливу скалку, Фалла Сейджвінд розпізнає, що в цьому артефакті — чиста сутність Смарагдового...",kw={"у кошмарах","скалка жаху","смарагдовий сон","фалла сейджвінд","матренґіл берволкер","печери стогонів","коло кенарія"},ang={["class:Druid"]="Для друїдів це завдання відкриває, що священний Смарагдовий Сон — не той незайманий прихисток, з яким їх учили єднатися, і натякає на глибоку внутрішню небезпеку.",["faction:Alliance"]="Шукачі пригод Альянсу, що приносять цю реліквію в серце Дарнасуса, дають проводу нічних ельфів змогу першим побачити скверну, яка шириться під поверхнею світу.",["race:NightElf"]="Нічні ельфи шанують сонне царство, де перебуває Малфуріон Стормрейдж; кошмар наяву в самій його сутності б'є в серце їхньої духовної спадщини."},sec={{t="Тривожне відкриття",b="Сяйлива скалка, здобута в глибинах Печер Стогонів, виявляється куди небезпечнішою за звичайний кристал. Оглянувши її, Фалла Сейджвінд упізнає в ній утілення найчистішої сутності Смарагдового Сну. Та замість відбивати зелену досконалість первісного задуму Азероту, камінь звивається моторошними, страхітливими видіннями. Приголомшена побаченим, Фалла не наважується зазирати глибше сама й наполягає, щоб скалку безпечно передали старшим провідникам Кола Кенарія."},{t="Шепіт у Ценаріонському Анклаві",b="У Дарнасусі реліквію показують Матренґілу Берволкеру — досвідченому друїдові Ценаріонського Анклаву. Спершу він зустрічає її зі спокійною цікавістю, але щойно зазирає в серцевину скалки, помітно бентежиться. Збагнувши, що скверна, яка вразила Пустки, напряму пов'язана з негараздами в глибинах самого Смарагдового Сну, він швидко обриває розмову. Старший друїд застерігає, що такі жахливі аномалії — не для чужих вух, і тихо забирає Скалку Жаху, щоб дослідити тінь, яка насувається."}},faq={{q="Що таке Скалка Жаху?",a="Скалка Жаху — кристалізований шматочок сутності Смарагдового Сну, спершу знайдений як загадкова сяйлива скалка. Замість відбивати природну гармонію, вона випромінює темні видіння й згубну силу, показуючи, що до Сну почала вдиратися зловісна присутність.",al={"що таке скалка жаху","лор сяючої скалки","скалка смарагдового сну"}},{q="Хто така Фалла Сейджвінд?",a="Фалла Сейджвінд — тауренка-друїдка, знавчиня природи, що оглядає дивні реліквії, знайдені в дикій глушині. Збагнувши справжнє, моторошне походження сяйливої скалки, вона спрямовує мандрівників до вищих друїдських авторитетів у Дарнасусі.",al={"фалла сейджвінд","хто така фалла"}},{q="Хто такий Матренґіл Берволкер?",a="Матренґіл Берволкер — старший наставник друїдів з Кола Кенарія в Ценаріонському Анклаві в Дарнасусі. Він — досвідчений наставник, що розслідує серйозні духовні загрози природі й Смарагдовому Сну.",al={"матренґіл берволкер","ведмедеход дарнас","хто такий матренґіл"}},{q="Чому Матренґіл так приховує скалку?",a="Смарагдовий Сон шанують як незаймане, недоторканне царство природи під опікою Зеленого драконячого роду й сплячих друїдів. Докази того, що це царство потерпає від кошмарної скверни, — глибока духовна криза, яку Коло Кенарія не поспішає оприлюднювати.",al={"чому ховає","що ховає матренґіл","чому матренґіл мовчить"}},{q="Звідки починається цей ланцюжок завдань?",a="Історія починається з «Сяйливої Скалки» — предмета, який знаходять на Мутанусі Пожирачеві наприкінці Печер Стогонів. Скалку приносять ученим, які зрештою простежують її лиховісне походження до Дарнасуса чи Тандер Блафа.",al={"передумова у кошмарах","звідки почалося","як отримати у кошмарах"}},{q="Чи мають гравці Орди схоже завдання?",a="Так. Герої Альянсу доповідають Матренґілові Берволкеру в Дарнасусі, а поборники Орди несуть свої знахідки Гамуулу Рунтотему на Узвишшя Старійшин у Тандер Блафі й дізнаються ту саму тривожну новину про Смарагдовий Сон.",al={"версія орди","чи є у кошмарах для орди","у кошмарах орда"}}},fp="13,294,22.507.0,32.552.1,28.278.1,22.231.0,29.234.0,47.298.1,34.237.0,42.229.0"}
P.entries["quest:3376"] = {n="Зломи Шарптаска!",s="«Зломи Шарптаска!» — вирішальний обряд посвяти, який дає Сміливець Віндфезер на Плато Червоної Хмари. Щоб убезпечити батьківщину тауренів від безперервних наскоків, молодих звитяжців посилають на схід, у Яр Тернистого Клинка, вбити Вождя Шарптаска Торнмантла. Загибель ватажка Щетиноспинів завдає тяжкого удару шипогривам, що зазіхають на Малгор.",h="«Зломи Шарптаска!» — вирішальний обряд посвяти, який дає Сміливець Віндфезер на Плато Червоної Хмари.",kw={"шарптаск","торнмантл","шипогриви","щетиноспини","малгор","яр тернистого клинка","віндфезер"},ang={["class:Hunter"]="Для мисливців це завдання — головне раннє випробування: вистежити здобич, яка має власну хитрість, зброю та намір уполювати вас у відповідь.",["faction:Horde"]="Стративши Вождя Шарптаска, союзники Орди засвідчують свою відданість справі замирення Малгору та здобуття мирних земель для нових братів-тауренів.",["race:Tauren"]="Убивство Шарптаска Торнмантла — одне з останніх випробувань, які молодий таурен проходить перед тим, як покинути Табір Нарачі, доводячи, що має рішучість захищати племена від ворожих сусідів."},sec={{t="Дім, здобутий кров'ю",b="Трав'янисті висоти Плато Червоної Хмари віддавна були мирним прихистком, де молоді таурени осягають традиції полювання та єднання із Земною Матір'ю. Та цей спокій раз у раз під загрозою. На сході лежить Яр Тернистого Клинка — зарослий колючками виярок, який присвоїло собі вороже плем'я шипогривів-Щетиноспинів. Шипогриви мають тауренів за загарбників, що крадуть священну землю, і без упину нападають на племена, які намагаються налагодити осіле життя в Малгорі."},{t="Загроза Торнмантла",b="Постійні напади на плато — не сліпа лють: ними керує жорстокий Вождь Шарптаск Торнмантл. Засівши в укріпленому саморобному селищі в глибині яру, Шарптаск спрямовує своїх воїнів і геомантів проти шу'хало. Розуміючи, що Щетиноспини не припинять наскоків, доки їхній вождь дихає, Сміливець Віндфезер наказує майбутньому герою прорватися в яр, здолати Торнмантла й повернутися з його відтятою головою як доказом."},{t="Уроки полювання",b="Для молодих тауренів та їхніх союзників полювання на Шарптаска — більше ніж проста страта: це посвята в сувору правду виживання. Як навчає Сміливець Віндфезер, лови на звіра вчать терпіння, а полювання на ворога, досить хитрого, щоб полювати у відповідь, випробовує мужність, пильність і бойову дисципліну. Загибель Шарптаска — це справедливість за полеглих родичів і знак, що мисливець готовий вийти на широкі рівнини Малгору."}},faq={{q="Хто такий Вождь Шарптаск Торнмантл?",a="Вождь Шарптаск Торнмантл — безжальний ватажок шипогривів-Щетиноспинів, що живуть у Яру Тернистого Клинка. Під його проводом плем'я раз у раз нападає й затіває сутички з поселенням тауренів на Плато Червоної Хмари.",al={"хто такий шарптаск","шарптаск торнмантл лор","вождь шипогривів"}},{q="Де знайти Вождя Шарптаска Торнмантла?",a="Шарптаск живе глибоко в Яру Тернистого Клинка, на східному краю Плато Червоної Хмари. Він править плем'ям зі свого нашвидкуруч зведеного селища в порослому тернем каньйоні.",al={"місце шарптаска","де шарптаск","як знайти шарптаска"}},{q="Хто дає завдання «Зломи Шарптаска!»?",a="Завдання пропонує Сміливець Віндфезер — бувалий таурен-воїн, що стереже Табір Нарачі на Плато Червоної Хмари. Він доручає перспективним новачкам довести свою загартованість, усунувши загрозу від Щетиноспинів.",al={"хто дає зломи шарптаска","хто починає зломи шарптаска","місце сміливця віндфезера"}},{q="Чому шипогриви-Щетиноспини ненавидять тауренів?",a="Шипогриви вірять, що вся земля, прикрашена кровавиком і священним терням, належить їм за божественним правом їхнього творця-напівбога Аґамаґґана. Тауренів, які засновують поселення в Малгорі, вони вважають загарбниками споконвічних мисливських угідь.",al={"чому шипогриви нападають","конфлікт тауренів і шипогривів","чому шипогриви ворожі"}},{q="Якого доказу вимагає Сміливець Віндфезер?",a="Сміливець Віндфезер вимагає відрубану голову Вождя Шарптаска Торнмантла. Голова незаперечно доводить, що ватажок загинув, і стає суворим попередженням для решти Щетиноспинів.",al={"що принести віндфезеру","доказ шарптаска","мета зломи шарптаска"}},{q="Яке культурне значення має це полювання для молодих тауренів?",a="У культурі тауренів справжня зрілість приходить з розумінням рівноваги між мисливцем і здобиччю. Віндфезер наголошує, що вистежування мислячого, хитрого супротивника на кшталт Шарптаска вчить молодих воїнів ваги смертельного бою й відповідальності за захист племені.",al={"чому вбивати шарптаска","обряд дорослішання тауренів","значення полювання"}}},fp="16,345,19.488.0,25.507.0,23.453.0,35.229.0,47.190.0,37.204.0,48.259.0,41.200.0,64.277.0"}
P.entries["quest:343"] = {n="До слова про стійкість",s="«До слова про стійкість» — доручення Альянсу в Стормвінді, яке починає Брат Крістофф на Соборній Площі. Готуючи проповідь під назвою «Стійкість духу», Крістофф просить шукача пригод навідатися до Королівської Бібліотеки у Фортеці Стормвінда й попросити в головного бібліотекаря Мілтона Шіфа одну особливу технічну працю.",h="«До слова про стійкість» — доручення Альянсу в Стормвінді, яке починає Брат Крістофф на Соборній Площі.",kw={"до слова про стійкість","брат крістофф","мілтон шіф","королівська бібліотека","напруження заліза","собор світла"},ang={["class:Priest"]="Проповідь Брата Крістоффа присвячена духовній стійкості й показує, як духовенство Стормвінда складає проповіді, поєднуючи буденні ремісничі уроки з відданістю Світлу.",["faction:Alliance"]="Це доручення пов'язує жрецтво Соборної Площі просто з Королівською Бібліотекою у Фортеці Стормвінда й показує, яку громадську й наукову інфраструктуру підтримує столиця.",["profession:Blacksmithing"]="Проповідь спирається на «Напруження заліза» — і це показує, що навіть учені богослови звертаються до суворої правди кузні, щоб пояснити, як витримувати тиск."},sec={{t="Метафора в металі",b="Брат Крістофф, один із жерців Собору Світла в Стормвінді, хоче виголосити проповідь про стійкість духу. Він не обмежується священними текстами — щоб показати гарт і витривалість віри, Крістофф звертається до ремесла металістів. Зокрема, йому потрібен трактат «Напруження заліза», щоб цитувати його під час проповіді: він сподівається, що уроки про те, як витримувати тиск, знайдуть відгук у серцях парафіян."},{t="Королівські полиці",b="У Фортеці Стормвінда міститься Королівська Бібліотека — головне сховище знань, історії й громадянських трактатів королівства Стормвінд. Зібрання охоплює незліченні полиці й праці багатьох століть, тож Крістофф скеровує посланців до Мілтона Шіфа, головного бібліотекаря. Шіф пишається тим, що знає архів напам'ять, — тож лише він може допомогти розшукати маловідомі ремісничі рукописи серед розлогих сховищ фортеці."}},faq={{q="Хто такий Брат Крістофф?",a="Брат Крістофф — священник Церкви Святого Світла на Соборній Площі в Стормвінді. Він часто просить відвідувачів допомогти роздобути матеріали й джерела для його повчань і проповідей.",al={"крістофф","хто дає до слова про стійкість","брат крістофф"}},{q="Яку книгу шукає Брат Крістофф?",a="Він шукає технічний текст під назвою «Напруження заліза» — посібник з металургії, який хоче цитувати як метафору духовної стійкості.",al={"яка книга","напруження заліза","книга крістоффа"}},{q="Хто такий Мілтон Шіф?",a="Мілтон Шіф — головний бібліотекар Королівської Бібліотеки у Фортеці Стормвінда. Він опікується величезним зібранням книжок, сувоїв і міських записів королівства й знає його досконало.",al={"мілтон шіф","бібліотекар стормвінда","головний бібліотекар"}},{q="Де розташована Королівська Бібліотека?",a="Королівська Бібліотека — у північно-східному крилі Фортеці Стормвінда, вхід до неї — просто з головної зали королівського палацу.",al={"місце бібліотеки стормвінда","де королівська бібліотека","бібліотека замку стормвінда"}},{q="Навіщо священникові книга з металургії?",a="Брат Крістофф пише проповідь під назвою «Стійкість духу». Він хоче використати фізичні навантаження, яких зазнає залізо під час кування, як алегорію того, як людський дух міцніє у випробуваннях.",al={"чому металургія","чому книга про залізо","проповідь про стійкість"}},{q="Чи одразу Мілтон Шіф має книгу напоготові?",a="Мілтон Шіф підтверджує, що в бібліотеці є праці з металургії, але, коли до нього звертаються, мусить перевірити точну назву й організувати пошуки — так починається розшук Крістоффового тексту.",al={"чи шіф має книгу","здати до слова про стійкість"}}},fp="21,314,19.460.0,16.440.0,24.215.0,42.166.0,20.196.0,35.133.0,41.212.0,49.195.0"}
P.entries["quest:344"] = {n="Брат Пакстон",s="«Брат Пакстон» — доручення, що відсилає шукачів пригод із королівських архівів Стормвінда до Абатства Нортшира. Бібліотекар Мілтон Шіф скеровує їх туди, щоб розшукати позичений дворфійський трактат про гірництво, який так і не повернувся на міські полиці.",h="«Брат Пакстон» — доручення, що відсилає шукачів пригод із королівських архівів Стормвінда до Абатства...",kw={"брат пакстон","мілтон шіф","абатство нортшира","напруження заліза","марґульф блеґґон","переписування"},ang={["class:Priest"]="Візит до Брата Пакстона дає зазирнути в наукові обов'язки клириків Нортшира, які сумлінно переписують книги від руки, щоб зберегти знання для ордену.",["faction:Alliance"]="Це завдання підкреслює культурний обмін, що єднає Стормвінд і Айронфордж: людські бібліотеки дбайливо зберігають і вивчають засадничі дворфійські тексти.",["profession:Mining"]="Предмет ваших пошуків — «Напруження заліза» Марґульфа Блеґґона — це десятиліття тяжко здобутих дворфійських гірницьких знань, видобутих просто з гір Каз Модану.",["race:Dwarf"]="Книга, яку шукають, — дворфійська майстерність у найкращому вигляді: її написав гірник Марґульф Блеґґон, і вона настільки шанована, що писарі Стормвінда прагнуть мати власні списки."},sec={{t="Позичений том",b="Коли дослідники приходять до Стормвінда по рідкісні технічні знання, головний бібліотекар Мілтон Шіф нерідко виявляє, що його зібрання розпорошене. Помітного трактату про металургійні прийоми — «Напруження заліза» дворфа-рудошукача Марґульфа Блеґґона — немає на столичних полицях. Його не загубили в столиці: кілька місяців тому книгу позичили клирикам Абатства Нортшира для переписування."},{t="Писар Нортшира",b="Переписувати й берегти книжки доручено Братові Пакстону, доглядачеві бібліотеки абатства. Святий Орден Клириків Нортшира цінує знання, проте переписувати від руки довгі технічні рукописи — праця кропітка й повільна. Спійманий на гарячому з простроченою книгою, Пакстон визнає, що ще не закінчив копіювати працю Блеґґона, — тож повернення оригіналу затримується."}},faq={{q="Чому Мілтон Шіф посилає вас до Абатства Нортшира?",a="Кілька місяців тому Мілтон Шіф позичив бібліотечний примірник «Напруження заліза» Братові Пакстону, щоб абатство зробило власну копію. Ні звісток, ні рукопису так і не надійшло, тож Шіф посилає вас дізнатися, як просувається справа в Пакстона.",al={"чому брат пакстон","де книга","доручення мілтона шіфа"}},{q="Хто такий Брат Пакстон?",a="Брат Пакстон — священник і доглядач бібліотеки Абатства Нортшира. Днями він впорядковує каталог і вручну переписує цінні книжки, поповнюючи місцеве зібрання абатства.",al={"хто такий пакстон","лор брата пакстона","пакстон нортшир"}},{q="Що таке «Напруження заліза»?",a="Це шанований технічний посібник, написаний десятиліття тому дворфом-гірником Марґульфом Блеґґоном, де він ділиться спостереженнями про видобуток руди й навантаження на метал глибоко в горах Каз Модану.",al={"що таке напруження заліза","книга напруження заліза","книга марґульфа бляґґона"}},{q="Чому Пакстон досі не повернув книгу?",a="Брат Пакстон досі вручну переписує рукопис для полиць своєї бібліотеки. Переписати вручну об'ємну технічну працю — справа довга й витратна, тож він не хоче віддавати оригінал, поки не закінчить.",al={"чому прострочено","чому пакстон довго","затримка пакстона"}},{q="Де знайти Брата Пакстона?",a="Брат Пакстон — в Абатстві Нортшира, осідку Святого Ордену Священників Нортширу, у Долині Нортширу на півночі Лісу Елвінн.",al={"місце пакстона","де брат пакстон"}},{q="Що буде, коли заговорити з Братом Пакстоном?",a="Пакстон визнає, що книга в нього, і пояснює, що не може закінчити копію, не поповнивши запасів для письма, тож посилає вас по складники для чорнила.",al={"наступне завдання після пакстона","що потрібно пакстону"}}},fp="14,254,17.422.0,19.406.0,51.228.0,22.188.0,31.198.0,40.233.0,34.156.0,47.167.1"}
P.entries["quest:345"] = {n="Запаси чорнила",s="«Запаси чорнила» — доручення Альянсу від імені Брата Пакстона, ченця-писаря з Абатства Нортшира. Йому потрібна особлива мінеральна складова для швидкосохнучого чорнила, тож Пакстон відсилає шукача пригод на схід, до обложеного містечка Лейкшир, щоб дістати Ретбанську Руду в Бригадира Ослоу.",h="«Запаси чорнила» — доручення Альянсу від імені Брата Пакстона, ченця-писаря з Абатства Нортшира.",kw={"запаси чорнила","брат пакстон","бригадир ослоу","ретбанська руда","лейкшир","печери ретбану"},ang={["class:Priest"]="Ланцюжок завдань Брата Пакстона — частина ранніх випробувань, пов'язаних із чеснотою стійкості: він веде послушників Святого Світла допомагати духовенству в його наукових обов'язках.",["faction:Alliance"]="Мандрівка показує разючий контраст між тихою відлюдністю Абатства Нортшира й жорстокою прикордонною кризою, що поглинає Лейкшир.",["profession:Mining"]="Це завдання знайомить із Ретбанською Рудою — місцевим родовищем, що ховається високо серед скель Редріджу."},sec={{t="Рецепт писаря",b="Брат Пакстон неабияк пишається своїм письменницьким ремеслом і не хоче користатися звичайним чорнилом для важливих списків на кшталт «Напруження заліза». Натомість він варить чорнило за власним рецептом, яке не розмазується й швидко висихає. Головна вада цього рецепта — воно висихає навіть у каламарі, якщо залишити його надовго. Щоб поповнити запас, потрібна сира Ретбанська Руда — особливий мінерал, який видобувають у скелястих закутках Гір Редріджу."},{t="Містечко в облозі",b="Мандрівники, що прибувають до Лейкширу зі скромною заявкою Пакстона, бачать: поселенню зовсім не до забаганок далекого ченця. Бригадир Ослоу наглядає за виснаженими робітниками містечка, які цілком поглинуті зміцненням барикад, відбудовою зруйнованих будівель і підготовкою до нових набігів орків Блекрок. Ослоу не має ні людей, ні терпіння копати руду для писарів Стормвінда, тож чужинцям доводиться самим спускатися до небезпечних Печер Ретбану."}},faq={{q="Навіщо Братові Пакстону для чорнила залізна руда?",a="Брат Пакстон користується власним рецептом, що дає стійке, нерозмазне письмо, яке висихає майже миттєво. Мелена Ретбанська Руда дає мінеральний пігмент і закріплювальні властивості, без яких не буде його особливого чорнила.",al={"навіщо залізо для чорнила","руда пакстона чорнило","рецепт чорнила пакстона"}},{q="Хто такий Бригадир Ослоу?",a="Бригадир Ослоу — головний наглядач за будівництвом і ремонтом у Лейкширі. Містечко постійно тиснуть орки Блекрок, тож він керує укріпленням і відбудовою вздовж озера.",al={"бригадир ослоу","ослоу лейкшир","хто такий ослоу"}},{q="Куди посилає вас Брат Пакстон?",a="Пакстон посилає вас на схід від Лісу Елвінн до Лейкшира, головного містечка Гір Редріджу, розшукати Бригадира Ослоу.",al={"куди йти за чорнилом","де ослоу","куди за запасами чорнила"}},{q="Чому Бригадир Ослоу не віддасть вам руду просто так?",a="На Лейкшир невпинно нападають орки клану Блекрок. Бригада Ослоу цілком зайнята лагодженням пошкоджених будівель і укріпленням околиць містечка, тож на гірничі доручення не лишається жодних рук.",al={"чому ослоу не дасть руди","ослоу відмовляє","чому ослоу сердитий"}},{q="Яку книгу намагається переписати Брат Пакстон?",a="Він саме переписує том під назвою «Напруження заліза», але справа зупинилася, коли попередня партія його швидкосохнучого чорнила застигла просто в посудині.",al={"книга пакстона","що переписує пакстон","напруження заліза"}},{q="Що буде після розмови з Бригадиром Ослоу?",a="Ослоу каже, що коли вам потрібна Ретбанська Руда, доведеться добувати її самому в небезпечних Печерах Ретбану на північ від Озера Незрушне.",al={"наступне завдання після запасів чорнила","що після ослоу","продовження запасів чорнила"}}},fp="12,295,18.462.0,18.481.0,46.240.0,21.219.0,35.131.0,46.215.0,47.171.0,47.147.0"}
P.entries["quest:346"] = {n="Повернення до Крістоффа",s="«Повернення до Крістоффа» завершує пошуки Братом Крістоффом невловимого фоліанта «Напруження заліза». Пройшовши Редріджем по руду для особливого чорнила й дочекавшись писарів Нортшира, шукач пригод нарешті приносить позичений том назад до Собору Світла в Стормвінді.",h="«Повернення до Крістоффа» завершує пошуки Братом Крістоффом невловимого фоліанта «Напруження заліза».",kw={"повернення до крістоффа","брат крістофф","брат пакстон","напруження заліза","собор світла","абатство нортшира"},ang={["class:Priest"]="Просте доручення для духовенства показує, як Церква Святого Світла береже, зберігає й поширює важливі знання по всьому королівству.",["faction:Alliance"]="Навіть найбуденніший науковий обмін залежить від безпечних доріг між Фортецею Стормвінда, Нортширом і охопленими боями Горами Редріджу."},sec={{t="Довгоочікуване повернення",b="Братові Крістоффу, що служить на Соборній Площі Стормвінда, потрібна була особлива праця з металургії — «Напруження заліза». Пошуки книги погнали гінців людськими землями: спершу до Королівської Бібліотеки у Фортеці Стормвінда, а потім і вглиб Абатства Нортшира. Там Брат Пакстон старанно переписував текст від руки, але затримався через брак Ретбанської Руди, потрібної для писарського чорнила. Тепер, коли руду здобуто, а список готовий, Пакстон нарешті віддає оригінал, щоб його повернули до міста."},{t="Праця писарів",b="У королівстві, на яке постійно тиснуть загрози ззовні, тиха праця переписувачів Нортшира лишається вкрай важливою для збереження громадських і духовних знань. Прохання Брата Пакстона перепросити від його імені Бібліотекаря Мілтона Шіфа показує, наскільки виснажені ресурси абатства. Цінні книги треба ретельно переписувати рисочка за рисочкою чорнилом, багатим на мінерали, перш ніж повернути їх на зберігання Стормвінду, — і просте прохання про книгу перетворюється на виснажливу справу логістики."}},faq={{q="Про що книга «Напруження заліза»?",a="«Напруження заліза» — трактат з металургії й обробки металу. Брат Крістофф шукав його для навчання на Соборній Площі, а писарям Абатства Нортшира потрібна була точна копія, щоб зберегти ці знання.",al={"що таке напруження заліза","книга напруження заліза","яку книгу шукає крістофф"}},{q="Чому книга опинилася в Абатстві Нортшира?",a="Королівська Бібліотека позичила книгу Братові Пакстону, щоб він зробив для архіву Абатства Нортшира ілюміновану копію. Тамтешні писарі зберігають важливі тексти, переписуючи їх вручну, але справа Пакстона застопорилася, коли йому забракло Ретбанської Руди для особливого чорнила.",al={"чому пакстон тримав книгу","чому в нортширі"}},{q="Хто такий Брат Крістофф?",a="Брат Крістофф — член духовенства Святого Світла на Соборній Площі біля Собору Світла в Стормвінді. Він попросив книгу й на знак вдячності дає духовне благословення.",al={"хто такий крістофф","крістофф стормвінд"}},{q="Хто такий Мілтон?",a="Мілтон Шіф — головний бібліотекар Королівської Бібліотеки у Фортеці Стормвінда. Саме він дозволив позичити «Напруження заліза» й дедалі більше нетерпеливився через довгу затримку з поверненням.",al={"бібліотекар мілтон","мілтон шіф"}},{q="Звідки починається цей ланцюжок завдань?",a="Ланцюжок починається на Соборній Площі Стормвінда з Братом Крістоффом у завданні «До слова про стійкість», далі веде до бібліотекаря Мілтона Шіфа, потім до Абатства Нортшира й у Гори Редріджу, а завершується знову в Крістоффа.",al={"як почати до слова про стійкість","початок ланцюжка"}},{q="Чи має це завдання продовження?",a="«Повернення до Крістоффа» завершує ланцюжок «До слова про стійкість». Коли ви доставите «Напруження заліза», Брат Крістофф дякує й дає благословення Світла — і справу закрито.",al={"що після повернення до крістоффа","чи є наступне завдання"}}},fp="18,293,21.544.0,20.471.0,44.216.0,37.254.0,24.202.0,14.192.0,34.234.0,36.197.0"}
P.entries["quest:347"] = {n="Ретбанська Руда",s="Бригадир Ослоу відсилає шукачів пригод до Печер Ретбану в Редріджі по дивний темний мінерал. Він надто м'який, щоб кувати з нього надійну броню чи зброю, але завдяки своєму особливому пігменту незамінний для писарів Абатства Нортшира, що виготовляють із нього особливе чорнило.",h="Бригадир Ослоу відсилає шукачів пригод до Печер Ретбану в Редріджі по дивний темний мінерал.",kw={"ретбанська руда","печери ретбану","бригадир ослоу","брат пакстон","редрідж","гноли"},ang={["faction:Alliance"]="Це доручення показує, наскільки розтягнуті шляхи постачання королівства Стормвінд: монастирським писарям доводиться покладатися на мандрівних шукачів пригод, щоб добути звичайне письмове приладдя із зони бойових дій.",["profession:Mining"]="Гірники можуть добувати Ретбанську Руду просто з печерних жил кайлом, не збираючи сирих шматків у гнолів-чорноробів.",["race:Human"]="Зберігати історичні рукописи в Абатстві Нортшира — священний обов'язок для вчених Стормвінда, які прагнуть відновити знання, втрачені в Першій і Другій війнах."},sec={{t="Дивний мінерал",b="Ретбанська Руда названа на честь того, хто її відкрив, — Барта Ретбана. На відміну від звичайного заліза чи міді, ця руда мало чого варта біля ковадла бронника: виплавлений із неї метал не має міцності, потрібної для надійної зброї чи лат. Справжня її цінність — у сирому темному матовому кольорі, який ченці й писарі цінують як основу для насичених фарб для рукописів."},{t="Спірні печери",b="Головні поклади мінералу лежать у Печерах Ретбану, що сховалися в північних горах Редріджу. На лихо для каменярів Лейкширу, місцеві гірники покинули печеру. Тунелі захопила люта зграя гнолів Редріджу, і тепер гноли-чорнороби відколюють кам'яні жили для власних примітивних потреб."},{t="Збереження слова",b="Брат Пакстон, чернець, що живе в тихих стінах Абатства Нортшира, залежить від цього пігменту, щоб відтворювати історичні тексти. Його нинішня праця — список трактату «Напруження заліза» — раптово зупинилася без потрібної фарби, і тепер гінці та шукачі пригод вирушають глибоко в землі, які кишать гнолами, щоб добути сирий камінь."}},faq={{q="Для чого використовують Ретбанську Руду?",a="Після виплавки вона надто слабка, щоб кувати міцну зброю чи обладунки, але її темний, матовий колір робить її чудовою основою для чорнил і фарб. Писарі на кшталт Брата Пакстона з Абатства Нортшира покладаються на неї, ілюмінуючи й переписуючи давні рукописи.",al={"навіщо ретбанська руда","призначення ретбанської руди","для чого ретбанська руда"}},{q="Ким був Барт Ретбан?",a="Барт Ретбан — дослідник і шукач, що першим відкрив жили темної руди в північних горах Редріджу; від нього й назва мінералу, і Печер Ретбану.",al={"хто відкрив ретбанську руду","барт ретбан лор"}},{q="Чому Лейкшир останнім часом не добуває руду?",a="Бригадир Ослоу й робітники містечка цілком поглинуті обороною Лейкшира від набігів орків Блекрок. На довершення в Печерах Ретбану оселилися гноли Редріджу й витіснили мирних гірників.",al={"чому ослоу не добуває","чому шахти покинуті"}},{q="Яку книгу переписує Брат Пакстон?",a="Брат Пакстон старанно переписує пізнавальну працю під назвою «Напруження заліза». Йому потрібна темна фарба з Ретбанської Руди, щоб завершити копію для бібліотеки абатства.",al={"яку книгу пише пакстон","рукопис пакстона"}},{q="Навіщо гнолам руда?",a="Гноли Редріджу змушують своїх трударів рити по всіх печерах. Гноли рідко ведуть розлогі записи, але жадають рудних покладів — для грубого знаряддя, торгівлі чи просто щоб укріпити свої гірські нори від непроханих гостей.",al={"чому гноли видобувають","гноли-чорнороби ретбан"}},{q="Куди веде цей ланцюжок завдань далі?",a="Коли Брат Пакстон отримає руду й приготує чорнило, він посилає вас назад до Стормвінда доповісти про успіх Крістоффові — так завершується доручення для писарів Нортширу.",al={"яке завдання після ретбанської руди","повернення до крістоффа далі"}}},fp="11,270,17.371.0,17.358.0,19.362.0,29.256.0,21.188.0,44.217.0,36.197.0,27.246.0,38.186.1"}
P.entries["quest:35"] = {n="Подальші тривоги",s="«Подальші тривоги» — кур'єрське завдання Альянсу від Маршала Дуґана з Ґолдшира: перевірити чутки про загрозу з води. Маршал посилає вас на схід через Ліс Елвінн порадитися з Вартовим Томасом біля річкової переправи. Так ваша увага зміщується від буденної служби в центральному гарнізоні до дедалі гострішої кризи безпеки на східному прикордонні.",h="«Подальші тривоги» — кур'єрське завдання Альянсу від Маршала Дуґана з Ґолдшира: перевірити чутки про загрозу...",kw={"мурлоки","вартовий томас","маршал дуґан","міст","ліс елвінн","редрідж","тривоги"},ang={["faction:Alliance"]="Завдання підкреслює дедалі більші тріщини в Королівстві Стормвінд і показує, якою тонкою стала людська оборона навіть за кілька кроків від столиці.",["race:Human"]="Для людей Елвінну поширення агресивних мурлоків загрожує житниці краю — фермам і торговим артеріям, що з'єднують Ґолдшир із Лейкширом."},sec={{t="Очі на східній переправі",b="Поки центральний Ліс Елвінн знемагає під тягарем розбою й шкідників, почали ширитися тривожні чутки про водяних істот, що повзуть уздовж берегів річки. Маршал Дуґан, командир гарнізону в Ґолдширі, не бажає відмахнутися від паніки. Замість знімати вартових із міста він посилає мандрівників на схід — порадитися з Вартовим Томасом, який несе варту на мосту через східну річку, що веде до Редріджу."},{t="Розтягнуте прикордоння",b="Вартовий Томас тримає заставу біля мосту вже понад тиждень і на власні очі бачить те, про що в Ґолдширі могли лише здогадуватися. Напіврозумні ворожі мурлоки влаштували табори вздовж усіх водних шляхів східного Елвінну. Армія Стормвінда відсутня, місцеві гарнізони прикуті до захисту міських мурів і ліній постачання, тож такі сільські застави, як пост Томаса, лишаються у критичній ізоляції перед цією навалою."}},faq={{q="Чому Маршал Дуґан посилає мене до Вартового Томаса?",a="До Маршала Дуґана дійшли звіти й чутки, що мурлоки підбираються до східних проток. Вартовий Томас уже тиждень стоїть на східному мосту Елвінну, тож Дуґан покладається на нього, щоб підтвердити, чи загроза справжня.",al={"чому вартовий томас","мета дуґана","поговори з томасом"}},{q="Де стоїть Вартовий Томас?",a="Вартовий Томас стоїть на дерев'яному мосту через річку на далекому сході Лісу Елвінн і стереже шлях, що веде до Гір Редріджу.",al={"місце вартового томаса","де томас","вартовий східного мосту"}},{q="Яку загрозу підтверджує Вартовий Томас?",a="Вартовий Томас підтверджує, що ворожі, напіврозумні мурлоки справді оселилися вздовж струмків і проток східного Елвінну й безпосередньо загрожують мандрівникам і сусіднім хуторам.",al={"мурлокська загроза","що знайшов томас","загроза східної річки"}},{q="Як дістатися Вартового Томаса?",a="Ідіть шляхом на схід від Ґолдширу через Ліс Елвінн до мосту через східну річку, де вартує Томас.",al={"швидко до томаса","кінь від дуґана","до мосту верхи"}},{q="Чому Стормвінд не посилає війська на допомогу східному Елвінну?",a="Постійне військо Стормвінда дуже обмежене: король Варіан Рінн зник, а ресурси відведено від сільських країв. Віддалені вартові на кшталт Томаса здебільшого можуть покладатися лише на мандрівних шукачів пригод.",al={"де вартові стормвінда","чому елвінн без захисту","військова допомога стормвінда"}},{q="Що буде, коли доповісти Вартовому Томасу?",a="Щойно Вартовий Томас підтвердить присутність мурлоків, він попросить вас з'ясувати долю інших вартових, які патрулювали берег річки й не повернулися.",al={"наступне завдання після подальших тривог","продовження томаса","завдання зниклих стражників"}}},fp="16,348,28.437.0,25.425.0,48.234.0,32.152.0,38.193.0,30.126.0,58.226.0,45.167.0"}
P.entries["quest:350"] = {n="Звернися до давнього друга",s="Майстер Матіас Шоу відсилає слідчого розшукати незвичного зв'язкового в Торговому Кварталі Стормвінда. Оскільки продажність знаті захищає впливових зрадників від звичайного законного правосуддя, майстер шпигунства неохоче покладається на мережу інформаторів найкращого сироторговця міста.",h="Майстер Матіас Шоу відсилає слідчого розшукати незвичного зв'язкового в Торговому Кварталі Стормвінда.",kw={"звернися до давнього друга","матіас шоу","еллінг тріас","ґреґор лесковар","si:7","сири тріаса"},ang={["class:Rogue"]="Тиха суперечка між Матіасом Шоу й Еллінгом Тріасом показує роздробленість таємних агентів Стормвінда, де вуличні інформатори часто мають кращі важелі, ніж офіційна розвідка корони.",["faction:Alliance"]="Це завдання показує, як продажність Дому Вельмож паралізує внутрішню безпеку Стормвінда, поки король Варіан Рінн зник безвісти."},sec={{t="Над законом",b="Після відкриття, що Лорд Ґреґор Лесковар і вбивця Марзон Тихий Клинок мають прямі зв'язки з Братством Дефіас, Майстер Матіас Шоу заходить у розвідувальний глухий кут. Едвін Венкліф загинув у Мертвих Копальнях, Базіла Тредда усунуто у В'язниці, тож живих ватажків розбійників, які могли б свідчити, не лишилося. До того ж аристократичний статус Лесковара й розгалужені політичні зв'язки ставлять його фактично поза межі досяжності звичайного правосуддя Королівської варти й офіційних ордерів SI:7."},{t="Вухо сироторговця",b="Щоб пробити оборону вельможі Стормвінда, Шоу відсилає свого агента до Еллінга Тріаса, власника крамниці «Сири Тріаса» в Торговому Кварталі. Зовні він — норовливий крамар, відомий на все місто привізними сирами в головках і скибках, але насправді Тріас тримає власну мережу очей і вух, що змагається з самою SI:7. Шоу терпіти не може звертатися до колишнього колеги, та викриття зради у Фортеці Стормвінда вимагає методів поза офіційними королівськими каналами."}},faq={{q="Чому Матіас Шоу посилає мене до торговця сиром?",a="Еллінг Тріас — далеко не простий торговець сиром. Він тримає крамницю «Сири Тріаса» біля входу до Торгового Кварталу, але водночас керує власною розгалуженою підпільною мережею розвідників. Шоу ненавидить просити його про допомогу, та щоб виступити проти вельможі, до якого не дотягнеться звичайна варта, SI:7 доводиться вдаватися до незвичних засобів.",al={"чому еллінг тріас","чому говорити з тріасом","чому крамниця сиру"}},{q="Чому Матіас Шоу не може просто заарештувати лорда Лесковара?",a="Лорд Лесковар — впливовий вельможа Стормвінда з глибокими зв'язками в Домі Вельмож. Шоу бракує свідчень, щоб докази проти аристократа мали юридичну силу.",al={"чому не заарештувати лесковара","чому шоу не може заарештувати лесковара","чому лесковар недоторканний"}},{q="Хто такий Марзон Тихий Клинок?",a="Марзон Тихий Клинок — смертоносний агент, який тісно співпрацює зі змовниками Дефіас і таємно листується з лордом Лесковаром при дворі Стормвінда.",al={"хто такий марзон","роль марзона тихого клинка"}},{q="Чому Тріас згадує Детвінга, коли з ним говориш?",a="Почувши про змову за участю Братства Дефіас, Тріас відповідає з гірким сарказмом: мовляв, далі ви ще скажете, що давно зниклий Аспект чорних драконів Детвінг живий і нападає на королівство.",al={"чому тріас каже детвінг","репліка тріаса про детвінга","детвінг нападає на стормвінд"}},{q="Що відбувається після зустрічі з Еллінгом Тріасом?",a="Вислухавши всю історію змови, Тріас починає готувати тихе проникнення до Фортеці Стормвінда, щоб загнати лорда Лесковара в кут, не сполохавши решту знатного двору.",al={"наступне завдання після тріаса","куди після звернися до давнього друга"}},{q="Де знайти Еллінга Тріаса?",a="Еллінг Тріас — у власній крамниці «Сири Тріаса» в Торговому Кварталі Стормвінда, неподалік головної дороги від міської брами.",al={"місце тріаса","де тріас сир"}}},fp="21,288,13.491.1,22.450.1,52.343.0,51.185.0,31.171.0,55.235.0,45.185.1,30.148.0"}
P.entries["quest:3513"] = {n="Рунічний сувій",s="Рунований сувій — дивний документ, перев'язаний сріблястою стрічкою, знайдений у дикій глушині Калімдору. Його урочистий вигляд свідчить, що це військове чи урядове повідомлення нічних ельфів з-за кордону. Знахідка веде розвідників Орди просто до Валу Мор'шан, щоб попередити вартових про рух на півночі.",h="Рунований сувій — дивний документ, перев'язаний сріблястою стрічкою, знайдений у дикій глушині Калімдору.",kw={"рунічний сувій","рунований сувій","кадрак","вал мор'шан","нічні ельфи","ашенваль"},ang={["faction:Horde"]="Кожне перехоплене розвіддання Альянсу захищає лісорубів і прикордонних вартових, що боронять ворота в Ашенваль.",["race:Orc"]="Просування клану Бойової Пісні в Ашенваль багато в чому залежить від оборони кордону на Валу Мор'шан, тож послання нічних ельфів — вкрай важливі новини."},sec={{t="Срібляста стрічка",b="Туго обв'язаний вишуканою сріблястою стрічкою, сувій одразу видає свою чужинність серед грубої шкіри й пергаменту, звичних для Пусток. Тонка робота й письмо вказують на нічних ельфів, що живуть під густим лісовим наметом Ашенвалю трохи на північ. На землі, де за кожен кряж і кожну дорогу точиться боротьба, перехоплене послання має неабияку стратегічну цінність для передової Орди."},{t="Очі на північному кордоні",b="Замість того щоб нести сувій через рівнини до Вождя в Оргріммар, кожен шукач пригод із бойовим чуттям розуміє, що тут важливе місцеве командування. На Валу Мор'шан, саме там, де червона земля Пусток поступається пишним лісам Ашенвалю, оркський воїн Кадрак пильнує, щоб на кордон ніхто не вдерся. Доставлений сувій дасть заставі на Валу важливі відомості про пересування військ нічних ельфів."}},faq={{q="Що таке Рунований Сувій?",a="Це офіційний, вишукано оформлений документ, перев'язаний сріблястою стрічкою, — ознака того, що його склали нічні ельфи. У ньому розвідані відомості про їхні пересування чи плани вздовж кордону з Пустками.",al={"що за сувій","лор рунованого сувою","сувій срібної стрічки"}},{q="Куди віднести сувій?",a="Сувій треба доставити до північної прикордонної сторожової вежі на Валу Мор'шан, де Кадрак стежить за всім, що діється між Пустками й Ашенвалем.",al={"куди віднести рунований сувій","здати сувій","кому потрібен сувій"}},{q="Хто такий Кадрак?",a="Кадрак — розвідник і вартовий Орди. Він стоїть на одній з оборонних веж Валу Мор'шан і пильнує загрози, що сходять на кордон з Ашенвалю.",al={"кадрак","орк біля вежі"}},{q="Звідки в Пустках сувій нічних ельфів?",a="Вартові й розвідники нічних ельфів постійно патрулюють кордони й околиці Ашенвалю, а часом просуваються на південь, щоб промацати оборону Орди чи влаштувати засідку на обози, що йдуть на північ.",al={"чому сувій у пустках","нічні ельфи в пустках"}},{q="Що буде, коли віддати сувій Кадракові?",a="Переглянувши сувій, Кадрак упізнає його авторку — дріаду Рінтаріель Ключник із Лігва Кігтя — і посилає вас на Пік Кам'яного Кігтя, щоб убити її й поставити в лігві прапор Орди.",al={"завдання присутність орди","що далі"}},{q="Чому сувій важливий для Орди?",a="Між Ордою та нічними ельфами постійно назріває напруга через вирубку лісів і кордони. Кожне перехоплене повідомлення дає змогу заздалегідь дізнатися про засідки Альянсу на Валу Мор'шан.",al={"важливість рунованого сувою","інтерес орди до сувою"}}},fp="16,330,16.421.0,27.453.0,25.194.0,31.152.0,14.170.0,55.178.0,47.189.0,40.201.0"}
